locales_quest['ruRU'] = {
  [1] = {
    'Задание Канретада',
    {'C возвращением из мира смерти, герой. Было время, когда ты с гордостью $Gстоял:стояла; среди своих собратьев, и меч твой был остер. Ныне же ты – лишь тень прошлого. Но встань передо мной, и я воскрешу легендарного рыцаря, которым ты некогда $Gбыл:была;.|n|nЯ восполню твои силы, восстановлю оружие и подготовлю тебя к новым подвигам.', },
    {'Поговорите с Канретадом, чтобы восстановить ваши таланты, оружие и средство передвижения.', },
  },
  [2] = {
    'Коготь гиппогрифа Острокогтя',
    {'Могучий гиппогриф Острокоготь был убит, и коготь этой свирепой твари – свидетельство вашей победы. Сенани Громосерд на заставе Расщепленного Дерева несомненно пожелает увидеть этот трофей – доказательство ваших деяний.', },
    {'Принесите коготь гиппогрифа Острокогтя Сенани Громосерд на заставу Расщепленного Дерева в Ясеневом лесу.', },
  },
  [5] = {
    'Урчащий живот Трясунчика',
    {'Я прячусь в этом призрачном городе несколько недель и не ел ничего, кроме трав и кореньев! Страшно хочется нормальной еды, и я за нее хорошо заплачу.|n|nУстрой мне пир, и не пожалеешь.|n|nГоворят, что шеф-повар Груаль в таверне "Алый ворон" делает превосходные темные пирожки с крабами...', },
    {'Поговорите с шеф-поваром Груалем.', },
  },
  [6] = {
    'Награда за голову Гаррика Тихокрада',
    {'Гаррик Тихокрад – головорез, который уже много недель не дает покоя нашим крестьянам и торговцам. Недавно его видели у лачуги возле виноградников, что к востоку от аббатства, за мостом. Принесешь мне голову этого негодяя – получишь награду!|n|nНо будь $Gосторожен:осторожна;, $N. Гаррик собрал разбойничью шайку. До него непросто будет добраться.', },
    {'Убейте Гаррика Тихокрада и принесите его голову заместителю судьи Виллему в Аббатство Североземья.', },
  },
  [7] = {
    '10 января 2012 г.',
    {'Первое твое задание, $N, – это зачистка. Северные леса наводнили кобольды. Ступай туда и уничтожь столько кобольдов-вредителей, сколько сможешь. Сократи их число, чтобы в один прекрасный день мы смогли вытеснить их из Североземья.', },
    {'Уничтожьте 6 кобольдов-вредителей. Вернитесь к маршалу Макбрайду.', },
  },
  [8] = {
    'Выгодная сделка',
    {'Эй, $Gприятель:подруга;! Сделай одолжение для парня, который более чем достаточно бился с безмозглыми зомби и пауками! |n|nУ меня тут есть письмецо, которое нужно доставить в Брилл... хозяйке таверны Ренни-как-ее-там. Неважно, какая у нее там фамилия! |n|nДа и в любом случае, Брилл – это славное уютное местечко, полное жертв чумы, пытающихся как-то выжить в этом мире. Ты и $Gсам:сама; сможешь там отдохнуть, если захочешь. По крайней мере, ты $Gдолжен:должна; туда заглянуть... ну а за доставку письма я тебе хорошенько заплачу.', },
    {'Доставьте ненадписанное письмо Ренни – хозяйке таверны в Тирисфальских лесах.', },
  },
  [9] = {
    'Поля смерти',
    {'Взгляните, во что превратилось это место! Когда-то эти земли населяли честные крестьяне. Но проклятые воры выжили отсюда всех. Только не меня! Однако угодья захватили големы – дозорные полей.|n|nЕсли вы готовы поработать, я попросил бы вас пойти и убить 20 таких големов. Возвращайтесь за оплатой, когда все будет сделано. Когда расправитесь с теми, что обитают на моем поле, зачистите поля и моих соседей тоже.', },
    {'Убейте 20 дозорных полей по просьбе фермера Сальдена.', },
  },
  [10] = {
    'Спасение Холстомера',
    {'Ох, это ужасно! Я послал моего лучшего помощника, младшего геодезиста Холстомера в пустыню, на юго-восток отсюда. Именно там располагается Зияющая бездна. Вот, а теперь он пропал, и в последнем докладе шла речь о странных насекомых. Неужели они наводнили уже два основных района пустыни?|n|nПрошу тебя, доберись до Зияющей бездны и поищи там Холстомера! Его... или хотя бы оборудование. Боюсь, больше от бедняги ничего и не осталось.', },
    {'Узнайте, что стало с младшим геодезистом Холстомером и приведите его или верните его оборудование старшему геодезисту Рудознатцу в Прибамбасск.', },
  },
  [11] = {
    'Награда за гноллов из стаи Речной Лапы',
    {'На границах Элвиннского леса появились гноллы – звероподобные твари, которым попросту нечего делать в этих краях. К югу от сторожевой башни была замечена большая группа этих существ: их слишком много, чтобы мы сумели с ними справиться. Хуже того: на востоке, у Озера Каменных Столбов, тоже обнаружили гноллов.|n|nАрмия Штормграда будет благодарна любому, кто поможет справиться с этой угрозой. В доказательство своей победы принеси мне раскрашенные нарукавные повязки гноллов.', },
    {'Принесите 8 раскрашенных поручей гноллов в казармы заместителю судьи Рейнеру.', },
  },
  [12] = {
    'Народное ополчение',
    {'У народного ополчения есть лишь одна цель: защитить земли Западного Края и вернуть в них мир. К сожалению, приходится это делать путем кровопролития.|n|nОдин из моих разведчиков сообщил о группе звероловов из Братства Справедливости, наводящих на местных жителей ужас и панику. У меня есть сообщения, что звероловов Братства замечали около Рудника Янго к северо-западу отсюда, а также неподалеку от фермы Мольсена и тыквенной фермы Хмуроброва. Если ты хочешь присоединиться к ополчению, убей 15 звероловов и 15 контрабандистов из Братства Справедливости, а затем возвращайся ко мне.', },
    {'Убейте 15 звероловов и 15 контрабандистов из Братства Справедливости и вернитесь к Гриану Камнегриву.', },
  },
  [13] = {
    'Народное ополчение',
    {'Шайка злобных погромщиков из Братства Справедливости разбойничает близ Прииска на Золотом Берегу, Луноречья и усадьбы Алекстона. Народное ополчение не потерпит этого. Разберись с этим немедленно, $N, и пусть весь Западный Край узнает о силе Света.|n|nЗолотой карьер находится неподалеку от побережья, к западу от башни. В качестве следующего этапа твоего обучения я хочу, чтобы ты $Gубил:убила; 15 погромщиков и 15 мошенников из Братства Справедливости.', },
    {'Убейте 15 погромщиков и 15 мошенников из Братства Справедливости и вернитесь к Гриану Камнегриву на Сторожевой холм.', },
  },
  [14] = {
    'Народное ополчение',
    {'Некоторые члены Братства Справедливости от нас ускользнули. Один из моих разведчиков, которому я очень доверяю, сообщает, что члены этого братства грабят и разоряют деревни вплоть до Южного Западного Края. Мы считаем, что они скрываются в Холмах Разбойничьих Кинжалов, замышляя новые бесчинства. Убей этих негодяев от имени народного ополчения.', },
    {'Убейте 15 разбойников, 5 налетчиков и 5 кастетчиков из Братства Справедливости. Вернитесь к Гриану Камнегриву на Сторожевой холм.', },
  },
  [15] = {
    'Разведка в руднике Горного эха',
    {'$N, мои разведчики доносят, что в эти края проникло гораздо больше кобольдов, чем мы рассчитывали. Группа кобольдов-рабочих разбила лагерь близ Рудника Горного Эха к северу отсюда.|n|nОтправляйся к шахте и уничтожь их. Насколько нам известно, кобольдов там много... Убей-ка десяток, посмотри, сколько еще осталось, и доложи мне.', },
    {'Уничтожьте 8 кобольдов-рабочих и вернитесь к маршалу Макбрайду.', },
