  },
  [3090] = {
    'Гниющий пергамент',
    {'А, $N! Тебе тут пергамент прислали, пока тебя не было.|n|nЯ лично стараюсь не иметь дела с чернокнижниками, однако ты его все-таки прочитай, когда время будет. Это, кажется, от твоего нового наставника, Нартока. Он хочет с тобой поговорить.', },
    {'Прочтите гниющий пергамент и поговорите с Нартоком в Логове в Долине Испытаний.', },
  },
  [3091] = {
    'Простая записка',
    {'Привет, $N! Слушай, минуту назад ко мне подошел посыльный и передал вот эту записку для тебя. Думаю, она от наставника воинов Харутта. На твоем месте я бы прочитал ее поскорее.', },
    {'Прочтите простую записку и поговорите с Харуттом Громовым Рогом в Лагере Нараче.', },
  },
  [3092] = {
    'Нацарапанная записка',
    {'Привет, $N! Слушай, минуту назад ко мне подошел посыльный и передал вот эту записку для тебя. Думаю, она от наставника охотников Ланко. На твоем месте я бы прочитал ее поскорее.', },
    {'Прочтите нацарапанную записку и поговорите с Ланко Дальнострелом на Плато Красного Облака.', },
  },
  [3093] = {
    'Руническая записка',
    {'Привет, $N! Слушай, минуту назад ко мне подошел посыльный и передал вот эту записку для тебя. Думаю, она от наставницы шаманов Милы. На твоем месте я бы прочитал ее поскорее.', },
    {'Прочтите руническую записку и поговорите с Милой Рассветной Странницей в Лагере Нараче.', },
  },
  [3094] = {
    'Зеленая записка',
    {'Привет, $N! Слушай, минуту назад ко мне подошел посыльный и передал вот эту записку для тебя. Думаю, она от наставника друидов Гарта. На твоем месте я бы прочитал ее поскорее.', },
    {'Прочтите зеленую записку и поговорите с Гартом Вестником Туманов в Лагере Нараче.', },
  },
  [3095] = {
    'Простой свиток',
    {'А, вот и ты! Пока ты $Gразбирался:разбиралась; с безмозглыми тварями, тебе тут свиток прислали. Я думаю, в нем что-то важное, поскольку на нем, похоже, стоит печать наставника воинов Даннала. Я бы на твоем месте потратил время на его изучение, прежде чем пускаться в дальнейший путь.', },
    {'Прочитайте простой свиток и поговорите с Данналом Штерном в Могильнике.', },
  },
  [3096] = {
    'Зашифрованный свиток',
    {'А, вот и ты! Пока ты $Gразбирался:разбиралась; с безмозглыми тварями, тебе тут свиток прислали. Я думаю, в нем что-то важное, поскольку на нем, похоже, стоит печать наставника разбойников Давида Триаса. Я бы на твоем месте потратил время на его изучение, прежде чем пускаться в дальнейший путь.', },
    {'Прочитайте зашифрованный свиток и поговорите с Давидом Триасом в Могильнике.', },
  },
  [3097] = {
    'Священный свиток',
    {'А, вот и ты! Пока ты $Gразбирался:разбиралась; с безмозглыми тварями, тебе тут свиток прислали. Я думаю, в нем что-то важное, поскольку на нем, похоже, стоит печать наставника жрецов Дьюстена. Я бы на твоем месте потратил время на его изучение, прежде чем пускаться в дальнейший путь.', },
    {'Прочитайте священный свиток и поговорите с темным священником Дьюстеном в церкви Могильника.', },
  },
  [3098] = {
    'Свиток, покрытый письменами',
    {'А, вот и ты! Пока ты $Gразбирался:разбиралась; с безмозглыми тварями Плети, тебе тут свиток прислали. Я думаю, в нем что-то важное, поскольку на нем, похоже, стоит печать наставницы магов Изабеллы. Я бы на твоем месте потратил время на его изучение, прежде чем пускаться в дальнейший путь.', },
    {'Прочитайте свиток, покрытый письменами, и поговорите с Изабеллой в церкви Могильника.', },
  },
  [3099] = {
    'Грязный свиток',
    {'А, вот и ты! Пока ты $Gразбирался:разбиралась; с безмозглыми тварями, тебе тут свиток прислали. Я думаю, в нем что-то важное, поскольку на нем, похоже, стоит печать наставника чернокнижников Максимиллиона. Я бы на твоем месте потратил время на его изучение, прежде чем пускаться в дальнейший путь.', },
    {'Прочитайте нечистый свиток и поговорите с Максимиллионом в Могильнике.', },
  },
  [3100] = {
    'Простое письмо',
    {'Меня попросили передать тебе это письмо, как только ты вернешься из лагеря кобольдов. Похоже, что на нем стоит печать Ллана, местного наставника воинов. На твоем месте я немедленно прочел бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь в аббатстве.', },
    {'Прочитайте обычное письмо и поговорите с Лланом Бишером в Аббатстве Североземья.', },
  },
  [3101] = {
    'Освященное письмо',
    {'Меня попросили передать тебе это письмо, как только ты вернешься из лагеря кобольдов. Похоже, что на нем стоит печать брата Самуэля, местного наставника паладинов. На твоем месте я немедленно прочел бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь в аббатстве.', },
    {'Прочитайте благословенное письмо и поговорите с братом Самуэлем в Аббатстве Североземья.', },
  },
  [3102] = {
    'Зашифрованное письмо',
    {'Меня попросили передать тебе это письмо, как только ты вернешься из лагеря кобольдов. Похоже, что на нем стоит печать Джорика, одного из наших местных наставников. На твоем месте я немедленно прочел бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь в аббатстве.', },
    {'Прочитайте зашифрованное письмо и поговорите с Джориком Керриданом в стойлах за Аббатством Североземья.', },
  },
  [3103] = {
    'Благословенное письмо',
    {'Меня попросили передать тебе это письмо, как только ты вернешься из лагеря кобольдов. Похоже, что на нем стоит печать Анетты, местной наставницы жрецов. На твоем месте я немедленно прочел бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь в аббатстве.', },
    {'Прочитайте святое письмо и поговорите с жрицей Анеттой в Аббатстве Североземья.', },
  },
  [3104] = {
    'Письмо мага',
    {'Меня попросили передать тебе это письмо, как только ты вернешься из лагеря кобольдов. Похоже, что на нем стоит печать Келдена, местного наставника магов. На твоем месте я немедленно прочел бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь в аббатстве.', },
    {'Прочитайте символьное письмо и поговорите с Кельденом Бременом в Аббатстве Североземья.', },
  },
  [3105] = {
    'Грязное письмо',
    {'Меня просили передать тебе это письмо, как только ты вернешься из лагеря кобольдов. Похоже, что на нем печать Друзиллы, одной из наших местных наставниц. На твоем месте я немедленно прочел бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь, в аббатстве.', },
    {'Прочитайте тайное письмо и поговорите с Друзиллой ла Салле возле Аббатства Североземья.', },
  },
  [3106] = {
    'Простая руна',
    {'Меня тут попросили передать тебе благодарность за помощь и вот эту руну. Изучи ее, когда будет время. Думаю, руну прислал Тран, наставник воинов. Если представится случай, отыщи его в Старой Наковальне.', },
    {'Изучите простую руну. Найдите в Холодной долине Трана Кормана и поговорите с ним.', },
  },
  [3107] = {
    'Священная руна',
    {'Меня тут попросили передать тебе благодарность за помощь и вот эту руну. Изучи ее, когда будет время. Думаю, руну прислал Бромос, наставник паладинов. Если представится случай, отыщи его в Старой Наковальне.', },
    {'Изучите священную руну. Найдите в Холодной долине Бромоса Груммнера и поговорите с ним.', },
  },
  [3108] = {
    'Гравированная руна',
    {'Меня тут попросили передать тебе благодарность за помощь и вот эту руну. Изучи ее, когда будет время. Думаю, руну прислал Торгас, наставник охотников. Если представится случай, отыщи его в Старой Наковальне.', },
    {'Изучите гравированную руну. Найдите в Холодной долине Торгаса Мрачнона и поговорите с ним.', },
  },
  [3109] = {
    'Зашифрованная руна',
    {'Меня тут попросили передать тебе благодарность за помощь и вот эту руну. Изучи ее, когда будет время. Думаю, руну прислал Сольм, наставник разбойников. Если представится случай, отыщи его в Старой Наковальне.', },
    {'Изучите зашифрованную руну. Найдите в Холодной долине Сольма Харгрина и поговорите с ним.', },
  },
  [3110] = {
    'Благословенная руна',
    {'Меня тут попросили передать тебе благодарность за помощь и вот эту руну. Изучи ее, когда будет время. Думаю, руну прислал Брансток, наставник жрецов. Если представится случай, отыщи его в Старой Наковальне.', },
    {'Изучите благословенную руну. Найдите в Старой Наковальне Бранстока Халдера и поговорите с ним.', },
  },
  [3112] = {
    'Записка',
    {'Меня тут попросили передать тебе благодарность за помощь и вот эту записку. Прочти ее, когда будет время. Думаю, записку прислал Тран, наставник воинов. Если представится случай, отыщи его в Старой Наковальне.', },
    {'Прочитайте записку и поговорите с Траном Корманом в Холодной долине.', },
  },
  [3113] = {
    'Зашифрованная записка',
    {'Меня тут попросили передать тебе благодарность за помощь и вот эту записку. Прочти ее, когда будет время. Думаю, записку прислал Сольм, наставник разбойников. Если представится случай, отыщи его в Старой Наковальне.', },
    {'Прочтите зашифрованную записку. Найдите Сольма Харгрина в Холодной долине и поговорите с ним.', },
  },
  [3114] = {
    'Таинственная записка',
    {'Меня тут попросили передать тебе благодарность за помощь и вот эту записку. Прочти ее, когда будет время. Думаю, записку прислал Маррайк, наставник магов. Если представится случай, отыщи его в Старой Наковальне.', },
    {'Прочитайте таинственную записку. Найдите в Холодной долине Маррайка Нуррибита и поговорите с ним.', },
  },
  [3115] = {
    'Оскверненная руна',
    {'Пока ты мне $Gпомогал:помогала;, тут вот передали для тебя руну. Найди время, чтоб ее прочитать. Думаю, она от чародейки по имени Сарипал. Когда представится возможность, навести ее в Старой Наковальне.|n|nИ будь поосторожней, $N, – таким, как ты, в этих краях не очень-то доверяют.', },
    {'Прочитайте оскверненную руну и поговорите с Сарипал Дымоварь в Старой Наковальне над Холодной долиной.', },
  },
  [3116] = {
    'Простой знак',
    {'Этот знак был передан мне посланником нашей наставницы воинов, Алайссии. Похоже, она хотела бы поговорить с тобой, когда у тебя будет время. Изучи знак и отправляйся к Алайссии.', },
    {'Изучите простой знак и поговорите с Алайссией в Тенистой долине.', },
  },
  [3117] = {
    'Выгравированный знак',
    {'Этот знак был передан мне посланником нашей наставницы охотников, Аянны. Похоже, она хотела бы поговорить с тобой, когда у тебя будет время. Изучи знак и отправляйся к Аянне.', },
    {'Изучите выгравированный знак и поговорите с Аянной Вечнобродкой на верхушке Альдрассила в Тенистой долине.', },
  },
  [3118] = {
    'Зашифрованный знак',
    {'Этот знак был передан мне посланником нашего наставника разбойников, Фрагуна. Похоже, он хотел бы поговорить с тобой, когда у тебя будет время. Изучи знак и отправляйся к Фрагуну.', },
    {'Прочтите зашифрованный знак и поговорите с Фрагуном Шепотом Тени в Тенистой долине.', },
  },
  [3119] = {
    'Благословенный знак',
    {'Этот знак был передан мне посланником нашей наставницы жрецов, Шанды. Похоже, она хотела бы поговорить с тобой, когда у тебя будет время. Изучи знак и отправляйся к Шанде.', },
    {'Прочтите благословенный знак и поговорите с Шандой в Альдрассиле.', },
  },
  [3120] = {
    'Зеленый знак',
    {'Этот знак был передан мне посланником нашего наставника друидов, Марданта. Похоже, он хотел бы поговорить с тобой, когда у тебя будет время. Изучи знак и отправляйся к Марданту.', },
    {'Прочтите зеленый знак и поговорите с Мардантом Крепким Дубом на древе Альдрассил в Тенистой долине.', },
  },
  [3121] = {
    'Странная просьба',
    {'Для начала мне понадобится помощь Ксераша Огненного Клинка из павильона Лорисс, что рядом с лагерем Мохаче! Он изготовил состав, который нужен мне для... ну, потом увидишь.|n|nВ общем, отправляйся к Огненному Клинку. Да, и захвати с собой вот это. Это мумифицированная голова, которую я обещал Ксерашу в обмен на его травки. Какой-то злосчастный дворф, с которым я повстречался в лесу... Думаю, Ксераш останется доволен.', },
    {'Отнесите сушеную голову Ксерашу Огненному Клинку в павильон Лорисс в Фераласе.', },
  },
  [3122] = {
    'Возвращение к знахарю Узер\'и',
    {'Вот травы, $N. Отнеси их знахарю Узер\'и.|n|nИ, пожалуйста, передай ему, что сушеная голова – то, что надо.', },
    {'Отнесите знахарю Узер\'и в Фералас мешочек для трав Ксераша.', },
  },
  [3123] = {
    'Испытание сосуда',
    {'Это будет испытание – испытание придуманного мною ритуала и твоих способностей. Возьми этот сосуд, $N. С его помощью ты сможешь уменьшать и помещать внутрь него разных существ.|n|nОтправляйся в дикие земли и отыщи диких существ. Медведи-сталемехи и длиннозубы-охотники станут твоей первой добычей, $N. Убивай этих существ и с помощью сосуда уменьшения возьми их души в плен, пока они не успели ускользнуть.', },
    {'Убейте 10 медведей-сталемехов или длиннозубов-охотников, и используйте сосуд уменьшения, чтобы уменьшить и пленить их.|n|nОтнесите 10 уменьшенных зверей знахарю Узер\'и в Фералас.', },
  },
  [3124] = {
    'Уменьшенный гиппогриф',
    {'Ты уже $Gдоказал:доказала;, что на тебя можно положиться, и ты умеешь обращаться с сосудами уменьшения. Теперь я попрошу тебя пленить другое создание.|n|nГиппогрифы в течение многих лет были верными спутниками ночных эльфов, и души их тверды и преданны.|n|nТвоя задача – убить 10 блеклоперых гиппогрифов, быстро уменьшить их и загнать в сосуды, чтобы сохранить таким образом их души. Гиппогрифов можно найти в Высокогорных дебрях, к югу отсюда.', },
    {'Убейте 10 блеклоперых гиппогрифов любого вида, затем используйте сосуд уменьшения, чтобы уменьшить и пленить их.', },
  },
  [3125] = {
    'Уменьшенный лесной дракончик',
    {'$N, теперь я попрошу тебя отловить существо, которое на вид кажется довольно хилым, но дух его могуч, а это – именно то, что нам надо. Лесные дракончики, о которых я говорю, были союзниками ночных эльфов. Нам надо поймать такого дракончика, чтобы Орда тоже могла воспользоваться силой его духа.|n|nУбей 8 летучих хамелеонов или радужных дракончиков, и плени их души. Эти существа водятся к западу отсюда.', },
    {'Убейте 8 летучих хамелеонов или радужных дракончиков. Используйте сосуд уменьшения, чтобы пленить павших лесных дракончиков.', },
  },
  [3126] = {
    'Уменьшенный древень',
    {'Следующей нашей добычей, $N, станут бродячие лесные великаны, живые деревья. Ночные эльфы считают древней своими союзниками в борьбе против Орды. Движения древней медлительны, но в качестве защитников они незаменимы!|n|nИ вскоре мы сможем использовать их мощь в своих целях.|n|nОтыщи 3 бродячих лесных древней, убей их и используй этот сосуд уменьшения, чтобы пленить их души!', },
    {'Убейте 3 бродячих лесных древней. Используйте сосуд уменьшения, чтобы уменьшить и пленить павших древней.', },
  },
  [3127] = {
    'Уменьшенный горный великан',
    {'Последнее, что от тебя потребуется – это отправиться на северо-запад и отыскать основного противника.|n|nКогда Пылающий Легион явился в мир, горные великаны спустились с гор, чтобы помогать ночным эльфам. Ты без труда обнаружишь их: они огромного роста, и когда они поблизости, земля начинает дрожать под ногами.|n|nЯ жажду подчинить себе подобную мощь! Убей 7 горных великанов и используй сосуд уменьшения, чтобы пленить их могучие души!', },
    {'Убейте 7 сухопутных бродяг или скальных великанов. Используйте сосуд уменьшения, чтобы уменьшить и пленить павших скальных великанов.', },
  },
  [3128] = {
    'Природные материалы',
    {'Для выполнения моего замысла мне нужны некоторые материалы... Будешь выполнять другие мои поручения – поищи заодно и то, что я тебя попрошу.|n|nВо-первых, расколотый ствол фераласского древня. Во-вторых, покрытые коркой минералы – эти можно добыть у горных великанов и волшебных драконов на западе. Кроме этого, добудь мне упругих сухожилий совухов из Внутренних земель либо гиппогрифов из Фераласа. И, наконец, мне потребуется большое количество металлических фрагментов, какие найдутся у любого из перечисленных созданий.', },
    {'Принесите 2 расколотых бревна, 6 минералов, покрытых коркой, 20 кусков упругих сухожилий и 40 металлических фрагментов знахарю Узер\'и в Лагерь Мохаче.', },
  },
  [3129] = {
    'Оружие духа',
    {'Вселить дух животного в оружие – процесс непростой! Теперь, когда у меня есть все необходимые материалы и души пойманных тобой созданий, я могу приступить к делу. Погоди немного, я скоро вернусь.', },
    {'Подождите, пока знахарь Узер\'и готовит оружие.', },
  },
  [3130] = {
    'Борьба с Гребнем Ненависти',
    {'В данный момент я собираюсь направить тебя к своему заместителю, Латроникусу. Он следит за боевыми приготовлениями наг. Сама же я буду продолжать осуществлять общее наблюдение. Как бы мне ни хотелось нанести им удар всеми имеющимися у нас силами, оставить крепость беззащитной перед атаками Орды – а может быть, и кого-то похуже, – не представляется разумным.|n|nКак бы то ни было, Латроникус тебя ждет. Пока что ты $Gпоказал:показала; себя молодцом, $N. Продолжай в том же духе!|n|nМожешь идти.', },
    {'Явитесь к Латроникусу Лунному Копью в Крепость Оперенной Луны.', },
  },
  [3141] = {
    'Лорамус',
    {'Так ты хочешь вступить в сражение с демонами? Тебе лучше для начала услышать то, что я скажу.', },
    {'Послушайте, как Лорамус Многоног рассказывает свою историю.', },
  },
  [3161] = {
    'Газ\'рилльское украшение',
    {'Я ученый, но в душе – кладоискатель!|n|nДавным-давно, когда в этих землях жили тролли, они обожествляли Газ\'риллу, огромную гидру, и создали множество украшений в форме ее тела. Их вырезали из особого материала, я называю его "газ\'риллий" в честь богини-гидры.|n|nЯ и сам ухитрился найти несколько образцов, но для исследований этого не хватает – может, ты мне еще принесешь?|n|nЯ даже создал детектор, позволяющий мигом обнаружить газ\'риллий! Надень его и приступай к поискам!', },
    {'Марвон Клепальщик из Танариса поручил собрать 30 газ\'рилловых украшений.', },
  },
  [3181] = {
    'Рог чудовища',
    {'Гигантский рог испещрен многочисленными сколами и царапинами, кроме того, из него торчит непонятный металлический предмет. |n|nОсмотрев рог более внимательно, вы понимаете, что металлический предмет есть ничто иное как обух секиры, сорванный с рукояти. На нем виднеется гравировка:|n|n"Принадлежит горному пехотинцу Щебеночке".|n|nКогда вы пытаетесь вытащить обух секиры из рога, он рассыпается на кусочки. |n|nОпаньки...', },
    {'Отнести гигантский рог Маргульи горному пехотинцу Щебеночке.', },
  },
  [3182] = {
    'Доказательство содеянного',
    {'Ты думаешь, я поверю этим россказням? Если бы это был настоящий рог, из него до сих пор торчал бы обух моей секиры.|n|nВот что, неси-ка свою подделку смотрителю Ториусу в Стальгорн. Если он признает, что твои слова – правда, он даст тебе доказательство. Принеси его мне, и я дам тебе ключ к Тлеющему ущелью.|n|nИди, иди!', },
    {'Отнесите гигантский рог Маргульи смотрителю Ториусу в Стальгорн.', },
  },
  [3201] = {
    'Наконец-то!',
    {'Не может быть, чтобы Щебеночка усомнилась в подлинности рога. Между нами говоря, думаю, она просто ревнует. Я знаю, она хотела убить чудовище сама.|n|nТак вам, значит, нужно доказательство. Разумеется, вы принесли музею столь ценный дар, что я почту за честь написать для вас свидетельство. |n|n*Смотритель Ториус начинает заполнять огромный документ* |n|nНу вот, можете показать его Щебеночке.', },
    {'Отнесите доказательство содеянного горному пехотинцу Щебеночке.', },
  },
  [3221] = {
    'Беседа с Ренферрелом',
    {'Пока вы отсутствовали, помогая нашим стражам смерти, за вами приходил аптекарь Ренферрел. Он не рассказывал мне подробностей, но хотел поговорить с вами о волчьих сердцах, что вы ему передали.', },
    {'Поговорите с аптекарем Ренферрелом в Гробнице.', },
  },
  [3241] = {
    '<NYI> <TXT><redux> Вершина Багрового Тумана',
    {'Соберите тотемы Вершины Багрового Тумана, потому что там теперь гадко, и хорошеньким чистым тотемам там не место.', },
    {'Принесите тотемы Тонге Руническому Тотему.', },
  },
  [3261] = {
    '[DEPRECATED in 4.x] Джорн Заклинатель Небес',
    {'Вот и закончились наши уроки, $N. Не останавливайся на достигнутом, ступай в Лагерь Таурахо на юге и поговори с Джорном Заклинателем Небес. Он станет твоим новым учителем.', },
    {'Поговорите с Джорном Заклинателем Небес в Лагере Таурахо.', },
  },
  [3281] = {
    '[DEPRECATED] Похищенное серебро',
    {'Ящеров-то ты $Gубил:убила;, но похищенное серебро необходимо вернуть! Говорят, что ящеры гнездятся на юге от Кабестана, в Землях ящеров. Скорее всего они утащили похищенное серебро именно туда.|n|nОтправляйся в логово мерзких тварей и поищи наше серебро. Как найдешь – сразу возвращайся ко мне.', },
    {'Принесите украденное серебро Газрогу в Перекресток.', },
  },
  [3301] = {
    'Муура Рунический Тотем',
    {'Одна из моих соплеменниц, Муура Рунический Тотем, отправилась в Серебряный бор на помощь нашим союзникам-нежити. Серебряный бор – больной, вымирающий лес, и Муура надеялась вдохнуть в него новую жизнь. Может быть, необычные обитатели Степей подскажут ей, как лучше выполнить задачу.|n|nВозьми образец добытых тобой панцирей и отнеси его Мууре в Серебряный бор. Она остановилась в Гробнице. При удаче, осмотрев панцирь, она придумает, как исцелить это погибающее место.', },
    {'Поговорите с Муурой Руническим Тотемом в Гробнице, что в Серебряном бору.', },
  },
  [3321] = {
    'Не ее ли ищете?',
    {'Ты много $Gсделал:сделала; для Ордена, $N. Обычный искатель приключений не выдержал бы такой нагрузки. Ни я, ни Гальван не сомневаемся, что ты $Gстал одним:стала одной; из нас.|n|nПоэтому мне кажется, что ты заслуживаешь награды. Сущий пустяк, побрякушку. Может быть, ты знаешь о ее свойствах. Должно быть, именно из-за них ты и $Gпришел:пришла; к нам.', },
    {'Дождитесь, пока Трентон закончит работу.', },
  },
  [3341] = {
    'Да сгинет Хладовей',
    {'В Степях есть уголок, заросший кошмарными колючками. Он называется Курганы Иглошкурых. Хотя с первого взгляда это место не показалось нам опасным, по последним сведениям все куда серьезнее…|n|nЖивущие в холмах свинобразы поддались злому влиянию Плети. Теперь их действиями руководит лич по имени Амненнар Хладовей.|n|nУ Амненнара прямая телепатическая связь с Нер\'зулом; мы должны прервать ее, $N. Да сгинет Хладовей!', },
    {'Эндрю Браунелл поручил вам убить Амненнара Хладовея и принести его череп.', },
  },
  [3361] = {
    'Беда беженца',
    {'Мы изгнали троггов из Гномрегана и уж было собрались праздновать победу, но тут все пошло наперекосяк! Только представь: радиация кругом, а гномы – те, кто еще жив – разбрелись по Дун Морогу...|n|nЯ так торопился, что все свои вещи бросил, да и все инструменты в придачу. Вот тролли – те не растерялись: им что радиация, что грибной дождик... Прибрали все к рукам: и сундук, и ларец, и даже ведро с винтиками не постеснялись прихватить! Все, все уволокли к себе в лагерь, куда-то к юго-западу от Старой Наковальни...|n|nПутешественник из меня никудышный, так я вот тут подумал: может, ты у них заберешь мои вещи и вернешь их мне?', },
    {'Принести в Старую Наковальню ларец Феликса, сундук Феликса и ведро с винтиками и вручить все это Феликсу.', },
  },
  [3362] = {
    'Долина Кактусов',
    {'Ты когда-нибудь $Gбыл:была; в Долине Кактусов? Это опасное место, $N.|n|nТам такие жуткие твари, я к ним и близко не подойду! Бугристые шипокожи и терновые корнеплеты, кажется так они зовутся…|n|nТак или иначе, я хочу попасть в эту долину, но пока там столько шипокожей, ноги моей там не будет. Вот зачем ты мне $Gнужен:нужна; – если перебить часть этих тварей, я могу и решиться на поход. Что скажешь, $N? Поможешь мне?', },
    {'Тран\'рек из Прибамбасска велит убить 8 бугристых шипокожей и 8 терновых корнеплетов.', },
  },
  [3363] = {
    'Оскверненный песнецвет',
    nil,
    nil,
  },
  [3364] = {
    'Жгучая бражка',
    {'Я уже давно должен был доставить эту отличнейшую жгучую бражку в Старую Наковальню Дарнану Мехорезу, да только сначала мне нужно было завезти немного Грелину. Боюсь, к тому времени, как я доберусь до Старой Наковальни, остынет бражка-то!|n|nТы на ногу полегче моего будешь, как я погляжу; вот я и подумал... эта кружка останется горячей еще несколько минут, а Дарнан вовсе не охлажденную бражку заказывал, – не пиво, чай! – так что отправляйся-ка ты в путь. Старая Наковальня – это такое поселение в скалах к северо-востоку отсюда.|n|nБлагодарю заранее... и вот еще что, $N: не забудь вернуть мою кружку!', },
    {'Отнесите жгучую бражку в Старую Наковальню и передайте ее Дарнану Мехорезу, пока она не остыла!', },
  },
  [3365] = {
    'Возвращение кружки',
    {'Ох, хорошо-то как! Все эти прохладительные напитки – полная ерунда: в морозный денек нет ничего лучше глотка горячей бражки! Даже на душе теплее становится!|n|nВот, держи, $N; сделай доброе дело, отнеси эту кружку Нори, ладно?', },
    {'Отнесите кружку хозяину – Нори по прозвищу Гордый Штрек. Он обитает в Холодной долине.', },
  },
  [3366] = {
    'Светящийся осколок',
    {'Блестящий осколок ярко-зеленый, без примесей, но под поверхностью можно видеть что-то похожее на клубы дыма. Оторвать взгляд от этих узоров в глубине невозможно, но в то же время вы осознаете какое-то беспокойство.|n|nПожалуй, стоит поискать в Кабестане кого-нибудь, кто может знать больше об этом странном осколке.', },
    {'Отправляйтесь в Кабестан и выясните, какие секреты скрывает кристалл кошмаров.', },
  },
  [3367] = {
    'Камни Сунтары',
    {'<Из груди Дориуса вырывается стон> |n|nЯ тяжело ранен, |3-6($R). Ужасно кружится голова... Думаю, у меня внутреннее кровотечение... |n|nМне нужно добраться обратно в Стальгорн. Помоги мне, $N.', },
    {'Помогите Дориусу вернуться в Стальгорн.', },
  },
  [3368] = {
    'Камни Сунтары',
    {'Брат! |n|nЕсли ты читаешь эти строки, меня уже нет в живых. Не знаю, кто доставил тебе письмо, но непременно поблагодари и вознагради его. |n|nТеперь о камнях: они существуют и сейчас находятся у клана Черного Железа. С помощью этих камней их главарь, Латорик Черный, удерживает моих соратников по экспедиции в плену. Лишенные рассудка, они день и ночь трудятся над созданием монстра, именуемого Обсидионом. |n|nСпаси их, брат. Это моя последняя воля. |n|nДориус.', },
    {'Доставьте опаленное письмо Ториусу в Стальгорн. Его можно найти в Зале Исследователей.', },
  },
  [3369] = {
    'Кошмары',
    {'В этом осколке заключены великие тайны. Это чистейшая сущность Изумрудного Сна, однако видения, которые она таит, скорее напоминают кошмары.|n|nТревогу бить рано, но, сдается мне, $N, тебе лучше отнести осколок какому-нибудь мудрому друиду, да побыстрее.|n|nРекомендую тебе найти Хамуула Рунического Тотема на Вершине Старейшин. Отправляйся в Громовой Утес. Больше мне сказать нечего.', },
    {'Принесите осколок кошмара Хамуулу Руническому Тотему на Вершине Старейшин.', },
  },
  [3370] = {
    'Кошмары',
    {'Этот осколок сам по себе большая загадка; Это чистая эссенция Изумрудного Сна. Но это осколок не сна, а скорее кошмара.|n|nНе хочу тревожить тебя, $N, но лучше будет, отдать его кому-то из старших друидов, как только сможешь.|n|nМатренгил Медвежья Лапа из Круга Кенария, вот кого тебе надо найти. Отправляйся в Дарнас, точнее сказать не могу.', },
    {'Принесите осколок кошмара Матренгилу Медвежьей Лапе в Дарнас.', },
  },
  [3371] = {
    'Правосудие дворфов',
    {'Теперь в груди моей зияет черная дыра – там, где было когда-то сердце... Я никогда не смогу смириться с гибелью Дориуса, $N. Я сделаю все, чтобы его последняя воля была исполнена – тех, на ком его кровь, должна настигнуть суровая кара. |n|nВозвращайся в Тлеющее ущелье и исполни волю Дориуса – освободи его соратников. Дворфы Черного Железа заставляют своих рабов трудиться в раскаленной шахте, именуемой Шлаковой Ямой.', },
    {'Вернитесь в Тлеющее ущелье и найдите археологов Дориуса.', },
  },
  [3372] = {
    'Отпусти их',
    {'Отпусти их, |3-6($R). Даже когда их тела совсем обессилят, власть Сунтары заставляет их достичь цели любой ценой. |n|nВсе дело в алтаре Сунтары. Отправляйся на северо-запад, там, в холмах над пещерой... Сумеречный Молот хранит реликвию. Добудь ее и возложи на алтарь Сунтары.|n|n*С этими словами умирающий археолог испускает дух*.', },
    {'Найдите таинственный артефакт, охраняемый идолослужителями Сумеречного Молота в северо-западной области Тлеющего ущелья и возложите его на алтарь Сунтары в Шлаковой Яме.', },
  },
  [3373] = {
    'Сущность Эраникуса',
    {'Вы касаетесь камня и слышите голос, звучащий в вашем сознании.|n|n"Услышь мою мольбу, о $Gсмертный:смертная;. Имя мне Эраникус из народа зеленых драконов. Мои попытки положить конец богохульным деяниям троллей закончились неудачей. Я вдохнул частицу своей души в этот кристалл. Однако я чувствую, что моя связь с Изумрудным Сном теряется, и меня поглощает хаос. Пожалуйста, помести этот кристалл в купель сущности в моем логове – пусть магия очистит мое сознание от скверны и спасет меня!"', },
    {'Поместите сущность Эраникуса в купель сущности в его логове в затонувшем храме.', },
  },
  [3374] = {
    'Сущность Эраникуса',
    {'Вы приводите в действие Камень клятвы и с его помощью Итар мысленно заговаривает с вами.|n|n"Приняв силу, заключенную в камне Клятвы, ты соглашаешься помочь мне и драконьему выводку Изеры освободить истерзанную душу Эраникуса. Первая из многих жертв, на которую придется пойти и тебе, и мне – это передать мне камень, в котором заключено то, что осталось от свободной воли Эраникуса.|n|nСделай это, $N, и дальше мы будем действовать вместе, чтобы освободить достойную многих жертв душу."', },
    {'Принесите камень Клятвы драконьего выводка Изеры и скованную сущность Эраникуса на Болото Печали. Там вам придется сделать выбор: помогать Драконам Изеры или нет.', },
  },
  [3375] = {
    'Запасной фиал',
    {'Хм... тебе нужен еще один фиал виденья? Шутишь? А куда ты $Gдел:дела; прежний?! У нас и так забот полон рот, |3-6($R). Эти фиалы на деревьях не растут! Хорошо бы, чтобы росли, я тогда пошел бы да сорвал, потому как другого-то у меня нет!|n|nА чтобы сделать тебе новый, мне нужно следующее: зелье маны, кусок угля и немного сладкого нектара. И не спрашивай зачем, просто принеси, я и тебе сделаю новый.', },
    {'Принесите зелье маны, уголь и сладкий нектар Талвашу дель Кисселю в Стальгорн, чтобы получить запасной фиал виденья Талваша.', },
  },
  [3376] = {
    'Сразить Остроклыка!',
    {'$N – я слыхала о тебе, $N. Возможно, именно тебе удастся то, что не удалось другим. |n|nМы, таурены, сделали это место своим домом, но это далось нам дорогой ценой. Дыбогривые свинобразы из клана Вздыбленной Щетины под предводительством вождя Остроклыка Терновой Мантии не дают нам покоя своими набегами. Я хочу, чтобы ты $Gпринес:принесла; мне голову их вождя! |n|nТы найдешь его в одной из кустарных хижин в Ежевичной лощине к востоку отсюда.', },
    {'Принесите голову вождя Остроклыка Терновой Мантии Храбрецу Перу Ветра на плато Красного Облака.', },
  },
  [3377] = {
    'Молитва к Элуне',
    {'Мне нужна твоя помощь, $Gсмертный:смертная;. Выслушай меня!', },
    {'Выслушайте Зимаэля.', },
  },
  [3378] = {
    'Молитва к Элуне',
    {'Ты поможешь мне, $Gсмертный:смертная;? Ты отыщешь молитву Элуне?|n|nКак я говорил, молитва выгравирована на золотой табличке, которая теперь, видимо, у одного из этих мерзких идолопоклонников. |n|nЕсли ты сможешь отыскать ее, отнеси табличку Астарии Ловцу Звезд в Дарнас. Пусть я пришел к вере после того, как совершил много зла этому миру и его обитателям, моя молитва должна быть услышана. А на прощение своих грехов я не надеюсь...', },
    {'Найдите молитву Элуне и принесите ее Астарии Ловцу Звезд в Дарнас.', },
  },
  [3379] = {
    'Мастер Тени',
    {'Пауки, которые водятся в Тлеющем ущелье, производят бесценный тенешелк. Как ты знаешь, тенешелк необходим для нашего ремесла. |n|nНе так давно в этих землях появилась шайка браконьеров, бессовестно убивающих пауков в погоне за сиюминутной прибылью. Твоя задача проста: найти их и прикончить. |n|nНачни поиски с северных пределов. |n|nЕсли потребуется помощь, обращайся к Пожару.', },
    {'Убейте банду похитителей тенешелка, хозяйничающую в Тлеющем ущелье. Нилит полагает, что их пятеро. Вернитесь к Нилит по выполнению задания.', },
  },
  [3380] = {
    'Затонувший храм',
    {'Этот мир полон беспокойных духов, $N. Среди них есть такие, которые оказались скованы в местах, в которых таится древнее зло, и были поражены скверной.|n|nСлыхала я о храме, сокрытом в глубинах болот – он был погружен туда силами, величие которых недоступно сознанию простого смертного.|n|nЕсли хочешь узнать больше о затонувшем храме, отыщи гоблина по имени Марвон Клепальщик. Он облазил многие развалины и останки древних поселений. А недавно он отправился изучать развалины строений троллей в Танарисе.', },
    {'Найдите Марвона Клепальщика в Танарисе.', },
  },
  [3381] = {
    'Встреча с господином',
    {'О, $Gюный:юная:r; |3-6($R) $Gпочтил:почтила; визитом Саната. О, это прекрасный день! Я так польщен! Благодарю тебя... |n|nНадеюсь, ты не столь $Gсамонадеян:самонадеяна;, чтобы принять мой сарказм за чистую монету? Скажу прямо: ты мне не нравишься. Но речь сейчас не о том, хочу ли видеть тебя я, но о том, желает ли видеть тебя мой господин. |n|nПринеси мне пару перьев гиппогрифа для моих стрел, и я пропущу тебя к господину. Он принимает только тех, кто доказал, что на что-то годен.', },
    {'Принесите 2 неповрежденных пера гиппогрифа Санату Лим-Йо в в Азшару, если хотите говорить с его господином.', },
  },
  [3382] = {
    'На абордаж!',
    {'Мы плыли вдоль берега, в поисках места, где бросить якорь. Солнце зашло не более часа назад, и тут они на нас напали. Проклятые наги! |n|nНе знаю, что им было нужно, но они явно этого не нашли. Почему я в этом уверена? Потому что они вернулись! Я оставила пару своих людей охранять долину, чтобы они предупредили нас в случае атаки. |n|nМне жаль, что ты $Gоказался втянутым:оказалась втянутой; в эту заварушку, но увы, ничего уже нельзя сделать. |n|nТы $Gготов:готова; биться не на жизнь, а на смерть?', },
    {'Защитите капитана Ванессу Белтис, ее команду и пассажиров "Покорителя Горизонтов" от нападения наг. Капитан Ванесса Белтис должна выжить.', },
  },
  [3385] = {
    'Черный рынок',
    {'Они называют себя Черным рынком – шайка головорезов, которые готовы купить, продать и украсть что угодно, если цена будет подходящей.|n|nИ что еще хуже, $N, они устроили себе логово в Тлеющем ущелье. Искусный торговец Ковиц – их главарь. У него есть связи с местными дворфами клана Черного Железа.|n|nМы должны нанести по ним мощный удар и недвусмысленно дать понять, что здесь им не рады. Убей торговца Ковица и его прихвостня Лязгуна. Принеси мне сумку торговца.|n|nОтправляйся в Котлован немедля!', },
    {'Убейте торговца Ковица и его прихвостня Лязгуна. Снимите с тела сумку и вернитесь к Нилит.', },
  },
  [3402] = {
    'Черный рынок',
    {'Мне нужно, чтобы ты лично $Gдонес:донесла; весть о кончине Ковиса Визглику в Прибамбасск. Он будет так рад, что непременно щедро наградит тебя.', },
    {'Поговорите с Визгликом в Прибамбасске.', },
  },
  [3421] = {
    'Возвращение',
    nil,
    nil,
  },
  [3441] = {
    'Божественное воздаяние',
    {'Выслушай меня, $Gcтранник:странница;.', },
    {'Выслушайте Каларана Ветрореза.', },
  },
  [3442] = {
    'Неугасимое пламя',
    {'Ты $Gпринял:приняла; правильное решение, $N. |n|nНадо нанести удар по самому уязвимому месту – четырем сторожевым башням. |n|nТебе потребуется особый факел, чтобы поджечь их. Над его изготовлением придется потрудиться, кроме того, нужно добыть необходимые ингредиенты. |n|nПринеси мне четыре сердца пламени и четыре меры масла големов, и тогда я сделаю для тебя факел, чье пламя будет неугасимым. |n|nЧтобы достать эти ингредиенты, ищи големов и элементалей.', },
    {'Принести 4 сердца пламени и 4 меры масла големов Каларану Ветрорезу.', },
  },
  [3443] = {
    'Древко факела',
    {'Чтобы удержать неугасимое пламя факела, нам необходимо создать особое древко и наложить защитные чары. Начнем с древка.|n|nВ Котловане надсмотрщики и работорговцы из клана Черного Железа используют оружие из зачарованного тория – особенно прочного сплава. Если ты принесешь мне восемь окованных торием кинжалов, я смогу выплавить торий и использовать его для укрепления древка.', },
    {'Принесите 8 окованных торием кинжалов Каларану Ветрорезу.', },
  },
  [3444] = {
    'Круглый камень',
    {'Мне приходилось бывать в преддвериях затонувшего храма. Зло, таящееся в этом жутком месте, окутывает всякого, кто входит туда. Я едва смог выбраться обратно, увязая в липкой грязи, покрывающей пол. Помню, есть там огромный круглый зал со множеством высеченных из камня змей.|n|nНе так давно мне попал в руки круглый камень, на котором была высечена подобная змея. Я велел послать его в мою мастерскую в Кабестане. Забери его оттуда, и возможно, я смогу ответить на твои вопросы.', },
    {'Заберите круглый камень из мастерской Марвона Клепальщика в Кабестане.', },
  },
  [3445] = {
    'Затонувший храм',
    {'Слыхала я о храме, сокрытом в глубинах болот – он был погружен туда силами, величие которых недоступно сознанию простого смертного.|n|nЕсли хочешь узнать больше о затонувшем храме, отыщи гоблина по имени Марвон Клепальщик. Также как и мы с Троясом, он облазал многие развалины и останки древних поселений. Говорят, что он отправился изучать развалины строений троллей в Танарисе.|n|nУдачи в поисках, о нем давненько ничего не слышали!', },
    {'Найдите Марвона Клепальщика в Танарисе.', },
  },
  [3446] = {
    'Во глубине болот',
    {'В храме я видел круглый зал с шестью галереями, каждую из которых украшала змея, высеченная из камня. Я всего лишь дотронулся до одной из них и угодил в ловушку! Произошел сильнейший взрыв – мне несказанно повезло, что я остался цел. Лежа там, на краю галереи, я заметил еще одну статую в самом низу зала – что-то вроде алтаря. Алтарь Хаккара, полагаю.|n|nПоложи этот знак на алтарь в Затонувшем храме – думаю, это поможет открыть его секреты.', },
    {'Найдите алтарь Хаккара в затонувшем храме на Болоте Печали.', },
  },
  [3447] = {
    'Тайна камня',
    {'Все, что я видел в Затонувшем храме, сохранилось в моей памяти лишь урывками, но я постараюсь рассказать тебе все как можно подробней. Круг статуй, сокрытый в храме – весьма опасное место, но я уверен, что там спрятан ключ к великим сокровищам.|n|nКогда я подошел к главному алтарю, в зале зажглись огни. Если тебе удастся разгадать, что они значат, возможно, сумеешь понять и тайны, которые скрывает эта комната.|n|nОднако я должен предупредить тебя, $N. В храме заключено великое зло. Какие бы сокровища там не скрывались, древние силы будут яростно защищать их от посягательств.', },
    {'Отправляйтесь в затонувший храм и узнайте, что скрывается в круге статуй.', },
  },
  [3448] = {
    'Передача поручения',
    {'Недавно мне доверили задачу исследования Азшары – некогда прекрасного края, который эльфы называли домом. Это было в те времена, когда они занимались магией. Теперь же это место скорее опасно, чем прекрасно, но это не остановит нас. Мы перевернем его по камушку, чтобы разгадать загадки нашего прошлого.|n|nМой товарищ Тимор предложил мне помощь в исследованиях, поскольку это и его самого особенно интересует.|n|nУ него здесь в городе есть небольшой дом рядом с Залом Тайн.', },
    {'Поговорите с Тимором в Стальгорне.', },
  },
  [3449] = {
    'Чародейские руны',
    {'Некоторые эльфы в старину почитали магию не меньше самой Элуны. Их самые могущественные маги создали руны и таблички, в которых были перечислены законы чародейства и разгадки их открытий. Они, как правило, выставляли их на всеобщее обозрение, чтобы все могли над ними поразмышлять.|n|nЯ был бы очень рад получить прорисовки этих рун из руин Эльдарата. Чтобы сделать прорисовки, я дам вам готовальню, но найти их должны вы сами. Будьте осторожны, не только лига Исследователей имеет свои интересы в Эльдарате.', },
    {'При помощи готовальни сделайте прорисовки руны Бет\'Амары, руны Джин\'йаэль, руны Маркри и руны Саэл\'Хаи. Отправляйтесь на маленький островок близ южного полуострова Азшары и дайте сигнал пилоту Зиггсу Зажигателю забрать их.', },
  },
  [3450] = {
    'Легкая доставка',
    {'Я хочу, чтобы эти прорисовки были доставлены мне в башню, но вам незачем лично проделывать весь этот путь. Пусть их просто доставят из Азшары по воздуху.|n|nУ Зиггса Зажигателя есть перед мной должок, к тому же он скоро окажется в тех местах – он назначен патрулировать побережье. Поговорите с ним перед отъездом. Он даст вам сигнальное ружье, чтобы вы могли подать ему сигнал. Когда добудете прорисовки, отправляйтесь в условленное место и отдайте их ему, чтобы он доставил их в мою башню в целости и сохранности. Он должен быть в ангаре в Палатах Войны.', },
    {'Поговорите с Зиггсом Зажигателем в Стальгорне.', },
  },
  [3451] = {
    'Сигнал "Взять на борт!"',
    {'А, так вас послал Тимор? Да, есть у меня перед ним должок. Это что? Ах, поганец! Ладно, я ему помогу. Значит, вам нужны сигнальное ружье и условленная точка... да легко.|n|nБлиз южного мыса Азшары есть небольшой островок, где мы соорудили посадочную площадку. Берете ружье и даете оттуда сигнал. Я вижу сигнал и прилетаю забрать это... ну, что ему надо.', },
    {'Поговорите с Зиггсом Зажигателем в Стальгорне и получите от него сигнальное ружье.', },
  },
  [3452] = {
    'Защита пламени',
    {'Работа над факелом близится к завершению. Не хватет лишь одного компонента. |n|nВ горах к северо-западу отсюда есть большой лагерь Сумеречного Молота. Говорят, они носят при себе некие символы и идолов в дань уважения своему богу. Полагаю, в этих символах и идолах заключены чары достаточной силы для создания магической брони. Принеси мне знак Рагнароса, и я попытаюсь извлечь из него его магическую силу, чтобы создать защитные чары для факела.', },
    {'Найдите знак Рагнароса и принесите его Каларану Ветрорезу.', },
  },
  [3453] = {
    'Факел воздаяния',
    {'Мне нужно несколько минут, чтобы сложить вместе все части и наложить чары.', },
    {'Подождите, пока Каларан Ветрорез закончит факел Воздаяния.', },
  },
  [3454] = {
    'Факел воздаяния',
    {'Факел готов и отныне связан со своим владельцем. Возьми его, $N.', },
    {'Возьмите факел воздаяния.', },
  },
  [3461] = {
    'Возвращение к Тимору',
    {'Тимор не оставил мне ничего, чтобы вам заплатить, потому предлагаю вам обсудить награду лично с ним, когда вернетесь в Стальгорн. Я уверен, что он до сих пор у себя в Палатах Магии. Постучитесь и потребуйте щедрой платы, потому как местечко-то не для пикника... это уж точно.|n|nВсе же благодарю вас, что вы ему помогли, и желаю удачи.|n|nОй, готовальня мне ни к чему. Почему бы вам просто не отдать ее лично Тимору, когда вы с ним встретитесь?', },
    {'Принесите Тимору его готовальню назад в Стальгорн.', },
  },
  [3462] = {
    'Оруженосец Малтрейк',
    {'Поговори с моим посыльным, оруженосцем Малтрейком. Он объяснит тебе, как использовать факел.', },
    {'Поговорите с оруженосцем Малтрейком.', },
  },
  [3463] = {
    'Задай им жару!',
    {'Слушай меня внимательно, $N. Четыре башни нельзя разрушить, но если поджечь их с помощью факела воздаяния, пламя не угаснет очень долго – и это пламя нельзя будет унять никакими силами. |n|nПока башни горят, ни один страж или караульный не сможет подняться на них – а значит, первая линия обороны противника фактически будет прорвана. |n|nТы $Gдолжен:должна; пробраться в башни и поджечь их с помощью факела воздаяния. И берегись патрульных Черного Железа!', },
    {'Подожгите северную, южную, восточную и западную сторожевые башни с помощью факела воздаяния.', },
  },
  [3481] = {
    'Безделушки...',
    {'Похоже, сундук заперт.', },
    {'Откройте сундук.', },
  },
  [3482] = {
    '<NYI> <TXT> Щербатая черная коробка',
    {'Это задание "Черный ящик" в версии для Орды', },
    {'Отнесите этот ящик Крейвелу.', },
  },
  [3483] = {
    'Сигнал "Взять на борт!"',
    nil,
    nil,
  },
  [3501] = {
    'Счет идет на большие числа',
    {'Быть может, ты никогда не найдешь безупречную сферу из дренетиста, однако во время скитаний по этим землям тебе, несомненно, удастся обнаружить различные несовершенные фрагменты дренетиста.|n|nХотя сомнительно, что Кум\'иша сможет использовать эти несовершенные фрагменты для возвращения домой, эти осколки могут сослужить иную, весьма полезную службу для дренеев.|n|nПринеси любой несовершенный фрагмент дренетиста, который найдешь, и я вознагражу тебя.', },
    {'Принесите Кум\'ише несовершенные фрагменты дренетиста и получите награду за каждый из них.', },
  },
  [3502] = {
    'Дренейский хлам...',
    {'Ну-с, узрев проявление этой ненасытной жадности, я не могу сдержать отвращение.|n|nИ тем не менее я не намерен долго задерживаться на твоем пристрастии к материальным благам.|n|nЗа каждый несовершенный фрагмент дренетиста, который ты принесешь, я вознагражу тебя каким-нибудь хламом. Моя груда хлама будет уменьшаться, а твоя – расти. На Дреноре такая ситуация называлась "все в выигрыше".', },
    {'Принесите Кум\'ише несовершенные фрагменты дренетиста. У любого вида монстров в Выжженных землях могут быть эти фрагменты.', },
  },
  [3503] = {
    'Встреча с господином',
    nil,
    nil,
  },
  [3504] = {
    'Предательница',
    {'Предательница и воровка! Других слов для нее у меня нет!|n|nНаверное, я сделал большую ошибку, $N. Я доверился эльфу крови. Хуже того – я доверился бабе!|n|nОна уверяла, будто в Азшаре хранятся несметные сокровища... могущественные артефакты... Все, что нужно, – это отправить с ней нескольких воинов для охраны, и она меня щедро вознаградит. Ну, и кто остался в дураках? Она их всех перебила!|n|nЯ жажду мести, $N. Но посылать туда других воинов я уже не могу. Найди Аг\'тора в Храбростане, к северу от лагеря Халдарр. Он тебе скажет, что делать дальше.', },
    {'Отнесите запечатанное письмо Аг\'тору Кровопалу в Азшару.', },
  },
  [3505] = {
    '[DEPRECATED 4.x] Предательница',
    {'Так я и думал.|n|nМы начнем наступать на ее приспешников от южных утесов северного полуострова Азшары. Убивайте их, не зная пощады – пусть знают, кого предали!|n|nНасчет ее самой пока не тревожьтесь – она проводит большую часть времени, рыская по Азшаре вместе со своими телохранителями. После того как перебьете ее работников, стоит отыскать ее личный лагерь. Нужно сначала разведать, откуда можно на нее напасть. Может быть, стоит как-нибудь выманить ее из лагеря...', },
    {'Убейте 10 эльфов крови-землемеров и 10 эльфов крови-геодезистов, потом разыщите лагерь волхва Римтори. В лагере найдите что-нибудь важное для мага, из-за чего она могла бы ринуться в бой.', },
  },
  [3506] = {
    'Предательница',
    {'Вы поразмыслили еще немного, и вам на ум пришло сразу несколько идей, одна из которых заставила улыбнуться: возможно, если вы уничтожите кристаллы, подлая эльфийка, погубившая стольких орков, достаточно разозлится?|n|nВы продолжаете разбирать текст и рисунки и понимаете, что один из кристаллов связан с создателем круга – прочие же связаны с куда более жуткими тварями.|n|nВы закрываете книгу и начинаете прикидывать, какой из кристаллов следует уничтожить.', },
    {'Уничтожьте кристалл средоточия чар, связанный с волхвом Римтори, затем убейте ее. Отнесите голову Римтори Аг\'тору Кроволапу в Азшаре.', },
  },
  [3507] = {
    '[DEPRECATED 4.x] Предательница',
    {'Вернись в Оргриммар к Белгрому. Он захочет увидеть ее голову своими глазами! Мы там тоже скоро будем.|n|nУдачный у нас денек! Спасибо за помощь, $N.', },
    {'Поговорите с Белгромом Каменной Булавой в Оргриммаре.', },
  },
  [3508] = {
    'Минуя охрану',
    {'Тебе свойственна безрассудная храбрость, $N. Это ценное качество твоего рода – слепо кидаться в битву, почти не имея шансов на успех. Я помогу тебе, хотя бы только ради того, чтобы увидеть смерть приспешников Разелиха. |n|nОднако для того, чтобы пробиться через охранные чары, окружающие их, требуется время, равно как и использование редких артефактов.|n|nНе нарушай тишину, я должен исполнить ритуал просветления. Сведения, которые я получу, помогут мне отковать оружие великой мощи.', },
    {'Подождите, пока Лорамус завершит заклинание просветления.', },
  },
  [3509] = {
    'Имя Зверя',
    {'Существует лишь один способ причинить вред повелителю демонов и его приспешникам. Следует выковать оружие силы, несущее его истинное имя.|n|nКогда такое оружие будет выковано, демон и все, кем он повелевает, станут уязвимы. |n|nВ Азшаре обитает меньшее божество: лорд Арккорос. Тебе следует найти его. Однако осторожнее: его слуги не остановятся ни перед чем, чтобы убить тебя, если обнаружат.|n|nНесомненно, за такие сведения придется заплатить.', },
    {'Поговорите в Азшаре с лордом Арккоросом. Начните поиски у кромки воды, чтобы найти Храм Арккоран.', },
  },
  [3510] = {
    'Имя Зверя',
    {'Она убивает моих детей. Она называет себя повелительницей океанов. Фальшивая богиня, и ничего более. Сокруши ее и принеси мне все ее головы.|n|nЗа это ты получишь то имя, которое тебе нужно, и кое-что еще, не менее важное.|n|nОна бродит вокруг гнезда... Она зовется Хетайра.|n|n*Лорд Арккорос указывает на юго-запад.*|n|nИди!', },
    {'Убейте Хетайру и принесите окровавленную голову Хетайры, разбитую голову Хетайры и покрытую синяками голову Хетайры лорду Арккоросу.', },
  },
  [3511] = {
    'Имя Зверя',
    {'Как и обещал, я открою тебе имя Повелителя демонов Разелиха Осквернителя. Однако сначала я должен приготовить кое-что необычайно важное для твоего путешествия.|n|nДля создания оружия, которое ты ищешь, необходим состав для закалки. Подожди немного, я выжму кровь из этих голов.|n|n*Лорд Арккорос сжимает головы между своими гигантскими ладонями, выдавливая из них кровь.*|n|nДоставь этот состав для закалки Лорамусу вместе с именем зверя: Рах\'лих.', },
    {'Отнесите состав для закалки Лорамусу Многоногу.', },
  },
  [3512] = {
    'Судя по словам Эраникуса...',
    {'$N, нашим первым шагом будет разработка способа связаться с Эраникусом через этот камень. Он сейчас находится на зыбкой грани между сном и смертью, в сетях кошмаров. Хотя принесенная тобою сущность сильно поражена порчей, все еще есть шанс, что мы дотянемся до Эраникуса.|n|nТебе придется отправиться далеко на север и к востоку от Зимних ключей разыскать нашего смертного союзника, Умбранса Ищущего Духов. Он умеет говорить с мертвыми. Хотя Эраникус и не вполне мертв, этот человек все же сможет нам помочь.', },
    {'Отправляйтесь в восточную часть Зимних Ключей и поговорите с Умбрансом Ищущим Духов.', },
  },
  [3513] = {
    'Свиток с рунами',
    {'Свиток официального вида перевязан серебристой лентой. Несомненно, кому-то он был бы весьма интересен, но кому?|n|nНа севере, рядом с границей Ясеневого леса, есть застава, и если в свитке идет речь о ночных эльфах, именно туда его и надо отнести.', },
    {'Отнесите свиток с рунами в северную сторожевую башню Степей.', },
  },
  [3514] = {
    'Мощь Орды',
    {'Это послание от коварной дриады Ринтариэль, Хранительницы Ключей Логова Когтя на Пике Каменного Когтя.|n|nОна уже не встретится с гонцом, у которого ты нашел этот свиток, хе-хе, но так просто им это не пройдет. Орда не потерпит такого нахальства.|n|nСтупай в Логово Когтя, $N. Убей Ринтариэль и покажи это всем. Возьми с собой флаг Орды и установи его в Логове Когтя у всех на виду. В другой раз они трижды подумают, прежде чем снова соваться в наши земли.', },
    {'Убейте предводительницу Логова Когтя, Ринтариэль Хранительницу Ключей.', },
  },
  [3517] = {
    'Тайненькое знаньице',
    {'Ты знаешь, $N, я, в общем, неплохо устроилась в Азшаре. У наказания Белгрома, обрушившегося на мою голову, есть свои положительные стороны. |n|nЯ тут полазала по окрестностям и обнаружила просто уйму ценностей, валяющихся без дела. |n|nЕсли интересно, могу рассказать подробнее и даже поделюсь прибылью, если поможешь мне добыть кое-что. |n|nВ руинах Эльдарата к востоку отсюда сокрыты четыре таблички. Каждая из них носит имя мага высокорожденных. Принеси мне их, и мы поговорим о дальнейшем сотрудничестве.', },
    {'Найдите таблички Бет\'Амары, Джин\'яэль, Маркри и Саэль\'Хай и принесите их Джедиге в Азшару.', },
  },
  [3518] = {
    'Доставка Магате',
    {'Первую табличку нужно отнести таурену по имени Магата. Ты найдешь ее среди старейшин Громового Утеса. Она самая ярая сторонница заключения союза тауренов с Отрекшимися, ибо считает, что именно таурены и их обычаи могут помочь Отрекшимся вновь найти путь к обретению человеческой природы. |n|nОтнеси ей табличку Бет\'Амары. Тауренка считает, что может найти в табличке способ, как помочь Отрекшимся... ну да, по крайней мере она в это верит.', },
    {'Отнесите табличку Бет\'Амары Магате в Громовой Утес.', },
  },
  [3519] = {
    'Друг в беде',
    {'Ох... меня сильно покусала паучиха по имени Гитьис Зловещая, когда я обследовал паучиную пещеру. Похоже, я серьезно отравлен. Помоги мне!|n|nПожалуйста, дай знать Дирании Серебряному Сиянию. Она сможет помочь мне.|n|nСпеши... Как голова кружится…', },
    {'Поговорите с Диранией Серебряным Сиянием в Тенистой долине.', },
  },
  [3520] = {
    'Духи крикунов',
    {'Мне нужны духи дольных крикунов из Фераласа. Они родственники старого-престарого бога и напрямую связаны с ним.|n|nВозьми ежевичный посох и ступай в Фералас. Отыщи в южной и центральной части дольных крикунов и одержи над ними верх. Потом помаши моим посохом над их телами. Таким образом ты выманишь их души. Коснись каждой из душ и собери их сущности.|n|nПринеси мне посох и собранные сущности, и я расскажу тебе о том старом боге.', },
    {'Поймайте души трех крикунов из Фераласа и возвращайтесь к Йе\'кинье в Порт Картеля.', },
  },
  [3521] = {
    'Противоядие Иверрона',
    {'Мы могли бы помочь Иверрону: я знаю противоядие, которое нейтрализует действие яда. Но для него мне нужны некоторые ингредиенты.|n|nМне понадобятся гиацинтовые грибы. Их можно найти под деревьями или добыть у греллей к югу отсюда – похоже, они им по вкусу. Еще мне нужны лунные лилии, что растут только вокруг прудов.|n|nПоследний ингредиент добыть сложнее всего. Это лимфа тех самых чащобных тенетников, что отравили Иверрона.', },
    {'Соберите 7 гиацинтовых грибов, 4 лунные лилии и 1 порцию лимфы чащобного тенетника и принесите Дирании Серебряное Сияние в Тенистую долину.', },
  },
  [3522] = {
    'Противоядие Иверрона',
    {'Противоядие готово, $N. Пожалуйста, проследи, чтобы Иверрон его выпил.|n|nИ запомни – это важно: противоядие будет обладать своими целебными свойствами в течение пяти минут. Необходимо доставить его до истечения этого времени.|n|nПоторопись, во имя Элуны!', },
    {'Отнесите противоядие Иверрону, прежде чем оно потеряет свои целебные свойства. Иверрона можно найти около пещеры, что к северу отсюда.', },
  },
  [3523] = {
    'Плеть в холмах',
    {'Благодарю, что $Gспас:спасла; меня! Имя мне Белнистраз. Не хотелось бы закончить жизнь столь бесславно – быть сожранным одной из омерзительных тварей Плети. Да-да, ты не $Gослышался:ослышалась;, Плеть вступила в союз с местными свинобразами.|n|nПослушай... вместо того, чтобы бежать, спасая собственную жизнь, я бы предпочел вступить с врагом в бой, чтобы защитить невинных. Не желаешь ли ты мне помочь? Это опасно, но ты явно не из тех, кто пасует перед трудностями.', },
    {'Если вы хотите помочь Белнистразу, поговорите с ним еще раз и верните ему Камень клятвы, который он дал вам.', },
  },
  [3524] = {
    'Останки на берегу',
    {'Громадные морские твари выбрасываются на пески Темных берегов и лежат там, пока не умирают. В последнее время останки этих тварей выносит на берег все чаще и чаще. Меня послали сюда из Храма Луны для расследования ситуации, но наличие мурлоков у береговой линии затрудняет мою задачу.|n|nОдни такие останки лежат на юге от Аубердина, совсем рядом, но вокруг очень много злобных мурлоков из племени Серой Мглы. Можешь сходить туда и принести мне для изучения кости этой твари?', },
    {'Соберите кости морской твари, выброшенной на берег к югу от Аубердина, и принесите их Гвеннид Блай\'Леггонд в Аубердин.', },
  },
  [3525] = {
    'Уничтожить идола',
    {'Рядом с входом ты увидишь идола – свинобразы используют его как жертвенный очаг. Эти твари на самом деле пожирают своих пленников из Степей. Я должен разбить идола, чтобы они более никогда не могли его использовать, но мне потребуется твоя помощь. Сопроводи меня к идолу. Там я проведу ритуал, но при этом я даже не смогу говорить с тобой, не говоря уж о том, чтобы самому защитить себя. Тебе придется держать оборону, пока я буду проводить ритуал. Если меня убьют раньше, чем я закончу, это будет означать крах всех наших планов.|n|nТы $Gготов:готова;?', },
    {'Сопроводите Белнистраза к идолу свинобразов в Курганах Иглошкурых. |n|nЗащищайте Белнистраза, пока он будет проводить ритуал, чтобы разрушить идола.', },
  },
  [3526] = {
    'Гоблинское инженерное дело',
    {'Инженерам-умельцам приходится выбирать между двумя школами инженерного дела: гномской и гоблинской. Очевидно, что наиболее талантливые инженеры предпочитают гоблинскую. Покори же мир с помощью отборной взрывчатки и фантастических механизмов!|n|nПрочитай этот учебник, $N. Если ты хочешь поучиться гоблинскому инженерному делу, поговори с Никсом Шепружином в Прибамбасске. Помни: сделав выбор единожды, ты не сможешь передумать. Поэтому хорошо подумай, прежде чем браться за задание Никса.', },
    {'Если вы хотите начать обучение гоблинскому инженерному делу, отнесите cправочник по инженерным дисциплинам Никсу Шепружину в Прибамбасск.', },
  },
  [3527] = {
    'Пророчество Мошару',
    {'Древнее пророчество Мошару повествует о том, как взять в плен сущность бога Хаккара. Пророчество записали на двух табличках и отнесли в тролльский город Зул\'Фаррак, что к западу от Прибамбасска.|n|nПринеси мне таблички Мошару!|n|nПервая табличка находится у давно умершего тролля Теки Мученика. Говорят, что его истязатели превратились в скарабеев и до сих пор ползают по его святилищу.|n|nВторая табличка – у гидроманта Велраты, рядом со священным озером Газ\'риллы.|n|nДобудешь таблички – сразу приходи.', },
    {'Принесите первую и вторую таблички Мошару Йе\'кинье в Танарис.', },
  },
  [3528] = {
    'Бог Хаккар',
    {'Пришло время брать в плен сущность аватары Хаккара.|n|nОтнеси яйцо Хаккара в святилище Падшего Бога в Затонувшем храме Азерота. Призови силу яйца и разбуди мертвого бога.|n|nОн пошлет против тебя своих прислужников. Одолей их и нацеди из них крови Хаккари. Угаси при помощи этой крови вечный огонь, в котором заключен дух Хаккара. Когда пламя погаснет, в мир войдет аватара Хаккара.|n|nПобеди его и помести его сущность в яйцо Хаккара.', },
    {'Отнесите заполненное яйцо Хаккара Йе\'кинье в Танарис.', },
  },
  [3541] = {
    'Доставка Джес\'римону',
    {'В Оргриммаре есть у меня скупщик краденого. У него притон в Волоке. Этого скользкого типа нелегко найти, если не знать точно где искать. Запомни: искать следует в одном из самых высоких зданий. |n|nТолько сделай мне одолжение, не ори на весь Калимдор, где он и чем занимается – это было бы... весьма неприятно для нас обоих. |n|nОн готов заплатить очень хорошую цену за табличку Джин\'яэль. Не знаю, зачем уж она ему сдалась, но $Gвидел:видела; бы ты, как у него загорелись глаза, когда я упомянула, что знаю, где ее найти!', },
    {'Отнесите табличку Джин\'яэль Джес\'римону в Оргриммар.', },
  },
  [3542] = {
    'Доставка Андрону Ганту',
    {'Теперь ты отправишься к Андрону Ганту. Он обретается в Подгороде, недалеко от Района Фармацевтов. |n|nЭтот был более многословен, когда я спросила, зачем ему нужна табличка. Маги Подгорода хотят изучить некоторые тайные заклинания высокорожденных. Они считают, что табличка им в этом поможет. Маркри был очень талантлив в чарах призыва различных существ, особенно элементалей. |n|nОтнеси ему табличку Маркри и возвращайся за своей долей.', },
    {'Отнесите табличку Маркри Андрону Ганту в Подгород.', },
  },
  [3561] = {
    'Доставка верховному магу Ксилему',
    {'Последнюю табличку надлежит доставить весьма опасному человеку, $N. Можешь не сомневаться, я доверяю ему куда меньше,чем кому-либо из тех, к кому я тебя отправляла. |n|nВерховный маг Ксилем живет в башне в холмах, возвышающихся над Азшарой. Он человек, однако он не похож на людей, которых мне приходилось встречать... или убивать. Он необычайно властен. Я не смею спросить его, что он собирается делать с табличкой. |n|nОн сказал мне, что страж его, Санат, поможет мне попасть в его башню, когда я буду готова предстать перед ним. Ищи Саната на севере.', },
    {'Отнесите табличку Саэль\'Хай верховному магу Ксилему в Азшару.', },
  },
  [3562] = {
    '[DEPRECATED] Плата Магаты Джедиге',
    {'Отнеси это послание Джедиге. Скажи ей, что я заплачу ей лично, когда она придет ко мне.|n|nСтупай скорее, $N. Скажи своей госпоже, что награда ожидает ее.', },
    {'Отнесите записку Магаты Джедиге в Азшару.', },
  },
  [3563] = {
    'Плата Джес\'римона Джедиге',
    {'Отнеси это послание Джедиге. Скажи ей, что я доволен ее работой.|n|nСкажи, чтобы скорее возвращалась в Оргриммар – Джес\'римон достойно наградит ее. |n|nПередай ей это, и, возможно, впредь я буду давать тебе поручения, $N.', },
    {'Доставьте записку Джес\'римона Джедиге в Азшару.', },
  },
  [3564] = {
    'Плата Андрона Джедиге',
    {'Вот *ик!* держи *ик!* Это для Джедиги. И ты это, *ик* заходи, если что!', },
    {'Доставьте записку Андрона Джедиге в Азшару.', },
  },
  [3565] = {
    'Плата Ксилема Джедиге',
    {'Что еще? Ах да, оплата. Конечно. |n|nВот, возьми и выметайся. Уверен, Джедига ждет не дождется твоего возвращения.', },
    {'Доставь записку Ксилема Джедиге в Азшару.', },
  },
  [3566] = {
    'Восстань, Обсидион!',
    {'Это... была... ловушка... |n|nПрости... меня... |n|nТы $Gдолжен:должна; убить предателя... Отомсти ему за нас... За Ториуса...', },
    {'Убейте Латорика Черного и Обсидиона и принесите голову Латорика и сердце Обсидиона Ториусу в Стальгорн.', },
  },
  [3567] = {
    'Умный в гору не пойдет...',
    nil,
    nil,
  },
  [3568] = {
    'Разносчик заразы',
    {'Видишь этого несчастного таурена? Она недавно побывала в Азшаре. Среди руин Эльдарата она была ранена в бою с нагами.|n|nОтбившись от них, она решила отдохнуть на берегу и попила водички из приливной заводи. Теперь ее тошнит... помимо всего прочего.|n|nМне нужно выяснить, что она пила. Возьми этот ящик, в нем несколько помеченных фиалов. Наполни их из разных заводей и возвращайся.', },
    {'Наполните все 4 пустых фиала из приливных заводей в руинах Эльдарата и возвращайтесь к химику Карабосу.', },
  },
  [3569] = {
    'Разносчик заразы',
    {'Отнеси эликсир Терсе – вдруг он ей поможет? Пока она не выпьет его, точно не скажешь.', },
    {'Дайте эликсир Карабоса Терсе Песне Ветра в Подгороде.', },
  },
  [3570] = {
    'Разносчик заразы',
    nil,
    nil,
  },
  [3601] = {
    'Оскорбленный Ким\'джаель',
    {'Ким\'джаель оскорблен до глубины души! Знаешь, что на самом деле Ким\'джаель значит для эльфов крови, $N? Я для них всего лишь букашка! Маленькое безвредное создание, на которое можно и наступить – не жалко! |n|nОни наняли меня, чтобы я обшарил для них место, где, как они сказали, спрятано сокровище. Ну ты понимаешь, при слове "сокровище" я утратил бдительность и купился на их посулы! Конечно же, они предали меня и даже пытались прикончить! |n|nНикогда нельзя верить мерзким эльфам крови! |n|nМне удалось уйти живым, но у негодяев осталось все мое снаряжение! Пожалуйста, забери его у них!', },
    {'Обыщите Талассийское поселение и найдите компас, прицел, плюшевого цыпленка и центробежный растягиватель Ким\'джаеля. Верните все это Ким\'джаелю в Азшару.', },
  },
  [3602] = {
    'Азшарит',
    {'Древние скальные великаны из южных регионов Азшары для поддержания существования поглощают камни и каменные образования. Продуктом переработки такой "пищи" являются чрезвычайно податливые, но при этом необычайно прочные кристаллы, известные как азшарит. |n|nНа южной гряде находятся целые залежи азшарита, однако его почти никому не удавалось добыть из-за чрезвычайной жестокости великанов.|n|nТебе следует отправиться на юг и раздобыть азшарита столько, чтобы его хватило для создания оружия. Мои гончие скверны помогут в розыске кристаллов.', },
    {'Найдите в южной Азшаре двадцать кристаллов азшарита. Вы можете использовать Гончих Скверны, которые помогут вам "вынюхивать" местонахождение хорошо сокрытых залежей. |n|nКогда задача будет завершена, возвращайтесь к Лорамусу Многоногу.', },
  },
  [3621] = {
    'Создание отравы Скверны',
    {'Оружие готово к отковке. Тебе следует отнести закаленный азшарит к тому, кто может обуздать энергию скверны.|n|nВ Тернистой долине живет такой кузнец. Гальван Древний, глава Ордена Мифрила, создаст оружие по твоему заказу. Ты можешь найти его становище между Зул\'Гурубом и холмом Мош\'Огг.|n|nПусть решительность и вера помогут тебе пройти это испытание. А если ты погибнешь, знай, что твой Бог тебе улыбается.', },
    {'Отнести груз Гальвану Древнему в Тернистую долину.', },
  },
  [3625] = {
    'Зачарованное азшаритовое оружие, отравленное Скверной',
    {'$N, для создания оружия необходимо время.|n|nВдобавок, ты можешь использовать силу оружия Проклятия Скверны лишь раз в три минуты. Длительность действия, ослабляющего Разелиха Осквернителя и его приспешников, может быть различной. Именно поэтому следует высвобождать силу Проклятия Скверны лишь в нужный момент!|n|nТеперь дай мне время на создания оружия для тебя, $N.', },
    {'Подождите, пока Гальван закончит отковывать оружие.', },
  },
  [3626] = {
    'Возвращение в Выжженные земли',
    {'Час возмездия близок, $N. Тебе следует вернуться в Выжженные земли вместе с твоим новообретенным оружием и поговорить с Павшим героем Орды о том, как достичь твоей главной цели.', },
    {'Вернитесь к Павшему герою Орды на Развилку Расщепленного Копья, что на Болоте Печали.', },
  },
  [3627] = {
    'Воссоединить расколотый амулет',
    {'Чтобы добраться до Осквернителя, тебе следует сначала уничтожить троицу силы и собрать осколки амулета. Когда у тебя в руках будут все три осколка, возвращайся ко мне, и я скажу, что делать дальше.|n|nИди, $N! В Выжженные земли! Севина, Аллистарий и Грол должны погибнуть!', },
    {'Убейте Грола Разрушителя, леди Севину и верховного мага Аллистария. С их трупов заберите Амулет Грола, Амулет Севины и Амулет Аллистария.|n|nПомните о том, что нужно использовать зачарованное азшаритовое оружие, отравленное Скверной, чтобы ослабить троицу! Их нельзя убить иначе – но используйте оружие разумно...', },
  },
  [3628] = {
    'Ты – Рах\'лих, демон!',
    {'Логово Разелиха находится на вершине самой высокой горы Выжженных земель. Единственный способ достигнуть логова – это использовать телепортирующие руны поблизости от горы. Пока у тебя есть этот амулет, ты свободно можешь переместиться в логово. А достигнув логова, призови зверя. Ключ к этому – твой амулет, $N. Используй его на Алтаре Осквернителя.|n|nЕсли одолеешь Осквернителя, принеси его рог. Он станет символом надежды для всех, кто увидит его – доказательством того, что в этом раздираемом войнами мире еще есть герои!', },
    {'Уничтожьте Разелиха Осквернителя и вернитесь к Павшему герою Орды с Отрубленным Рогом Осквернителя. Вам также понадобится вернуть Оберег Осквернителя, чтобы Павший герой мог уничтожить его, дабы оберег не попал к тому, кто использует его во зло.', },
  },
  [3629] = {
    'Гоблинское инженерное дело',
    {'В инженерном деле есть две дисциплины: гномская и гоблинская. Я – честный учитель, и только поэтому упомянул гоблинское инженерное дело. Видишь ли, гоблины обожают делать всякие взрывоопасные штучки и редко заботятся о том, что окажется на пути такой штучки – даже если это будет сам инженер.|n|n$N, почитай этот справочник. Если хочешь узнать, как эффектно покончить с собой, отнеси его к Никсу Шепружину в Прибамбасск. Помни – выбор твой не подлежит пересмотру, сменить дисциплину ты не сможешь; так что прежде, чем выполнить задание, что даст тебе Никс, убедись, что ты хочешь именно этого.', },
    {'Если вы хотите начать обучение гоблинскому инженерному делу, отнесите cправочник по инженерным дисциплинам Никсу Шепружину в Прибамбасск.', },
  },
  [3630] = {
    'Гномское инженерное дело',
    {'В инженерном деле есть две дисциплины: гномская и гоблинская. Гномское инженерное дело пока что зарекомендовала себя лучшей из двух. В ней речь идет о конструировании чудесных штучек и приспособлений, которые украшают жизнь!|n|n$N, почитай этот справочник. Если ты захочешь больше узнать о гномском инженерном деле, то отнеси его мехмастеру Замыкальцу в Стальгорн. Помни – выбор твой не подлежит пересмотру, и изучить другую дисциплину ты не сможешь, так что удостоверься в своем выборе, прежде чем выполнять его задание!', },
    {'Если вы хотите узнать больше о гномском инженерном деле, отнесите справочник по инженерным дисциплинам мехмастеру Замыкальцу в Стальгорн.', },
  },
  [3631] = {
    'Призывание коня Скверны',
    {'Хммм. Я сказал бы, что ты еще $Gне готов:не готова;, но тут не мне решать. Страад думает иначе, а решает он... пока.|n|nОн хочет с тобой говорить, причем срочно. Он пока все еще в Степях над Кабестаном, в своей маленькой башне со своими учениками.|n|nДолго не тяни.', },
    {'Поговорите в Кабестане со Страхадом Фарсаном.', },
  },
  [3632] = {
    'Гномское инженерное дело',
    {'На высоких уровнях инженерное дело расходится на два направления: на гномское и гоблинское. Гномская намного сильнее! Она занимается конструированием чудесных штучек и устройств, которые делают лучше нашу жизнь!|n|n$N, прочтите эту инструкцию. Если вы желаете узнать побольше о гномском инженерном деле, отнесите этот справочник мехмастеру Замыкальцу – он здесь, в Стальгорне. Помните: если выберете гномское инженерное дело, то это с концами, другим направлением вы заниматься не сможете, так что подумайте хорошенько, прежде чем выполнить его поручение!', },
    {'Если вы хотите узнать больше о гномском инженерном деле, отнесите справочник по инженерным дисциплинам мехмастеру Замыкальцу в Стальгорн.', },
  },
  [3633] = {
    'Гоблинское инженерное дело',
    {'Инженерам-умельцам приходится выбирать между двумя школами инженерного дела: гномской и гоблинской. Очевидно, что наиболее талантливые инженеры предпочитают гоблинскую. Покори же мир с помощью отборной взрывчатки и фантастических механизмов!|n|nПрочитай этот учебник, $N. Если ты хочешь поучиться гоблинскому инженерному делу, поговори с Никсом Шепружином в Прибамбасске. Помни: сделав выбор единожды, ты не сможешь передумать. Поэтому хорошо подумай, прежде чем браться за задание Никса.', },
    {'Если вы хотите начать обучение гоблинскому инженерному делу, отнесите cправочник по инженерным дисциплинам Никсу Шепружину в Прибамбасск.', },
  },
  [3634] = {
    'Гномское инженерное дело',
    {'На высоких уровнях инженерное дело расходится на два направления: на гномское и гоблинское. Хотя, на мой взгляд, это пустая трата времени, я должен рассказать тебе о гномском инженерном деле. Она занимается конструированием разных штучек и устройств, которые должны изменить мир, но редко работают.|n|n$N, прочти эту инструкцию. Если ты желаешь узнать побольше о гномском инженерном деле, отнеси этот справочник мехмастеру Замыкальцу в Стальгорн. Помни: выбрав гномское инженерное дело, ты не сможешь заниматься другим направлением, так что подумай хорошенько, прежде чем выполнить поручение Замыкальца!', },
    {'Если вы хотите узнать больше о гномском инженерном деле, отнесите справочник по инженерным дисциплинам мехмастеру Замыкальцу в Стальгорн.', },
  },
  [3635] = {
    'Гномское инженерное дело',
    {'На высоких уровнях инженерное дело расходится на два направления: гномскую и гоблинскую. Хотя, на мой взгляд, это пустая трата времени, я должен рассказать тебе о гномском инженерном деле. Гномы занимаются конструированием разных штучек и устройств, которые должны изменить мир, но редко работают.|n|n$N, прочти этот учебник. Если ты хочешь научиться делать металлические пресс-папье, отнеси его Карлсу Пропеллерзу в Пиратскую Бухту. Помни: выбрав гномское инженерное дело, ты не сможешь заниматься инженерным делом другой школы, так что подумай хорошенько, прежде чем выполнить поручение Карлса!', },
    {'Если вы хотите узнать побольше о гномском инженерном деле, возьмите справочник по инженерным дисциплинам и отнесите его Карлсу Пропеллерзу в Пиратскую Бухту.', },
  },
  [3636] = {
    'Нести свет',
    {'Плеть постоянно досаждает силам Альянса. Думаю, $N, ты знаешь об этом не хуже меня. В последнее время нам удалось сделать пару интересных находок.|n|nВ Степях есть жуткие заросли терновника, называемые Курганы Иглошкурых. Сначала казалось, что там обитают только иглогривы, но теперь выясняется, что в этих зарослях гнездятся самые разнообразные чудовища. Управляет ими лич по имени Амненнар Хладовей.|n|nВо имя Света, $N! Изгони зло с холмов Иглошкурых!', },
    {'Убейте Амненнара Хладовея в Курганах Иглошкурых.', },
  },
  [3637] = {
    'Гномское инженерное дело',
    {'На высоких уровнях инженерное дело расходится на два направления: гномскую и гоблинскую. Хотя, на мой взгляд, это пустая трата времени, я должен рассказать тебе о гномском инженерном деле. Гномы занимаются конструированием разных штучек и устройств, которые должны изменить мир, но редко работают.|n|n$N, прочти этот учебник. Если ты хочешь научиться делать металлические пресс-папье, отнеси его Карлсу Пропеллерзу в Пиратскую Бухту. Помни: выбрав гномское инженерное дело, ты не сможешь заниматься инженерным делом другой школы, так что подумай хорошенько, прежде чем выполнить поручение Карлса!', },
    {'Если вы хотите узнать побольше о гномском инженерном деле, возьмите справочник по инженерным дисциплинам и отнесите его Карлсу Пропеллерзу в Пиратскую Бухту.', },
  },
  [3638] = {
    'Договор о неразглашении',
    {'Гоблинское инженерное дело нацелено на получение высоких прибылей и огромной взрывной силы! Наши чертежи позволяют нам создавать мощные бомбы и прочее оружие, и в справочнике, что у тебя в руках, об этом написано.|n|nНо этот справочник также содержит древнюю клятву хранить наши чертежи в тайне. Как только ты займешься гоблинским инженерным делом, то все. Доступа к гномскому инженерному делу не будет.|n|nЕсли ты по-прежнему хочешь заняться гоблинским инженерным делом, подпиши этот документ о пожизненном неразглашении тайн и снова обращайся ко мне. Но сначала подумай хорошенько.', },
    {'Если вы согласны заниматься гоблинским инженерным делом, щелкните правой кнопкой мыши по Договору о неразглашении и еще раз обратитесь к Никсу Шепружину в Прибамбасске.', },
  },
  [3639] = {
    'Покажи свою работу',
    {'Блеск в твоих глазах выдает тебя с головой – ты любишь взрывать! Ты опытный инженер, тут вопросов нет, $N. Но я надеюсь проанализировать твои работы, чтобы найти способ отточить гоблинскоориентированную технику для будущих трудов. Мне нужны следующие образцы: двадцать больших железных бомб, двадцать шашек твердого динамита и пять взрывоопасных овец – и смотри $Gсам:сама; не подорвись!|n|nСдай мне эти предметы, и я признаю тебя истинным гоблином-инженером!', },
    {'Принесите 20 больших железных бомб, 20 шашек твердого динамита и 5 взрывоопасных овец Никсу Шепружину в Прибамбасск.', },
  },
  [3640] = {
    'Договор о неразглашении',
    {'Гномское инженерное дело стоит на пороге открытия теории, которая послужит нашим нуждам! Наши чертежи позволяют нам сооружать устройства, контролирующие мир вокруг нас, и в справочнике, что у вас в руках, об этом написано.|n|nНо этот справочник также содержит древнюю клятву хранить наши чертежи в тайне. Как только вы займетесь гномским инженерным делом, то все. Доступа к гоблинскому инженерному делу не будет.|n|nЕсли вы по-прежнему хотите заняться гномским инженерным делом, подпишите этот документ о пожизненном неразглашении тайн и снова обратитесь ко мне. Хорошенько подумайте, $N.', },
    {'Щелкните правой кнопкой мыши по Договору о неразглашении и еще раз обратитесь к мехмастеру Замыкальцу в Стальгорне.', },
  },
  [3641] = {
    'Покажи свою работу',
    {'Если ты $Gготов:готова; приступить к изготовлению потрясающих изделий – то ты $Gобратился:обратилась; по адресу! Ты опытный инженер, тут вопросов нет, $N. Но я надеюсь проанализировать твои работы, чтобы найти способ отточить гномскоориентированную технику ваших будущих трудов. Мне нужны следующие образцы: шесть мифриловых трубок, точный прицел и два усовершенствованных манекена-мишени.|n|nСдай мне эти предметы, и я признаю тебя истинным гномов-инженером.', },
    {'Принесите 6 мифриловых трубок, точный прицел и 2 усовершенствованных манекена-мишени мехмастеру Замыкальцу в Стальгорн.', },
  },
  [3642] = {
    'Договор о неразглашении',
    {'Гномское инженерное дело стоит на пороге открытия теории, которая послужит нашим нуждам! Наши чертежи позволяют нам сооружать устройства, контролирующие мир вокруг нас, и в справочнике, что у вас в руках, об этом написано.|n|nНо этот справочник также содержит древнюю клятву хранить наши чертежи в тайне. Как только вы займетесь гномским инженерным делом, то все. Доступа к гоблинскому инженерному делу не будет.|n|nЕсли вы по-прежнему хотите заняться гномским инженерным делом, подпишите этот документ о пожизненном неразглашении тайн и снова обратитесь ко мне. Хорошенько подумайте, $N.', },
    {'Если вы согласны заниматься гномским инженерным делом, щелкните правой кнопкой мыши по Договору о неразглашении и еще раз обратитесь к Карлсу Пропеллерзу в Пиратской Бухте.', },
  },
  [3643] = {
    'Покажи свою работу',
    {'Если ты $Gготов:готова; приступить к изготовлению потрясающих изделий – то ты $Gобратился:обратилась; по адресу! Ты опытный инженер, тут вопросов нет, $N. Но я надеюсь проанализировать твои работы, чтобы найти способ отточить гномскоориентированную технику ваших будущих трудов. Мне нужны следующие образцы: шесть мифриловых трубок, точный прицел и два усовершенствованных манекена-мишени.|n|nСдай мне эти предметы, и я признаю тебя истинным гномов-инженером.', },
    {'Принесите 6 мифриловых трубок, точный прицел и 2 усовершенствованных манекена-мишени Карлсу Пропеллерзу в Пиратскую Бухту.', },
