  [7666] = {
    'Возвращение в Главный склеп',
    nil,
    nil,
  },
  [7667] = {
    'Существенная помощь',
    {'$N, у меня есть срочное дело, и надеюсь, ты сумеешь мне помочь. Разреши, я объясню.|n|nВ глубине Некроситета в Лордероне есть здание, которое называется Главный склеп. Мне нужно изготовить устройство, которое позволит развеять зловещие тени этого жуткого места. Но чтобы его завершить, мне нужны два алмаза, азеротский и безупречный черный. Найти их не так-то просто, я знаю, но самому мне их раздобыть не под силу.|n|nНе согласишься ли ты добыть для меня эти камни?', },
    {'Принесите Сагорну Гребнестраннику в Аллею Мудрости в Оргриммаре азеротский алмаз и безупречный черный алмаз.', },
  },
  [7668] = {
    'Угроза Темного Губителя',
    {'Рыцарь смерти Темный Терзатель, владычествует над Главным cклепом в Некроситете. Он собирается подчинить себе весь мир духов! Его необходимо остановить! Тут-то тебе и понадобится кристальный предсказатель.|n|nПриведи его в действие в Главном склепе, чтобы вызвать духов-приспешников Темного Терзателя. Когда ты одолеешь этих духов, явится сам рыцарь смерти. Принеси мне его голову, $N! Только его гибель способна исправить урон, нанесенный миру духов!', },
    {'Используйте кристальный предсказатель в Главном склепе в Некроситете. Сразитесь с духами. Когда появится Темный Терзатель, убейте его.|n|nПринесите голову Темного Терзателя Сагорну Гривастому Страннику в Аллею Мудрости Оргриммара.', },
  },
  [7669] = {
    'Возвращение в Главный склеп',
    nil,
    nil,
  },
  [7670] = {
    'Лорд Грейсон Тенелом',
    {'$N, пришла пора узнать, что потребуется от тебя, дабы получить предмет твоих давних мечтаний, а именно... боевого скакуна.|n|nПоговори с лордом Грейсоном Тенеломом в Храмовом квартале Штормграда. Он не только наставит тебя в обращении с самым верным товарищем паладина, но и даст тебе задачу, прежде чем ты получишь своего скакуна.|n|nЖелаю тебе успешно пройти это испытание. Во имя Света, $Gблагородный брат:благородная сестра;!', },
    {'Поговорите с лордом Грейсоном Тенеломом в Храмовом квартале Штормграда.', },
  },
