  [7905] = {
    'Ярмарка Новолуния',
    {'Скоро начнется Ярмарка Новолуния – время чудес и веселья!|n|nЕсли ты поторопишься, то сможешь обменять этот сертификат на бесплатные призовые купоны! Передай сертификат Гелвасу Углешлюзу в ярмарочном лагере.|n|nСейчас ярмарка стоит рядом со Златоземьем, в Элвиннском лесу. Не упусти свой шанс! Отправляйся прямо сегодня!', },
    {'Передайте сертификат на призовой купон Гельвасу Угольному Шлюзу на ярмарке Новолуния.', },
  },
  [7906] = {
    'Карты Новолуния – Звери',
    nil,
    nil,
  },
  [7907] = {
    'Колода карт Новолуния: Звери',
    {'Как только вы собираете вместе восемь карт из колоды Зверей, девятая карта с такой же "рубашкой" появляется в колоде. На карте написано: "Принеси колоду на ярмарку Новолуния, и получишь награду". Ярмарка приезжает в Мулгор и Златоземье раз в несколько месяцев. Придется подождать до следующего раза...', },
    {'Принесите колоду Зверей на ярмарку Новолуния.', },
  },
  [7908] = {
    'Повелитель арены',
    {'Должно быть, стать повелителем арены не так просто! Быть может, пират-распорядитель на Арене Гурубаши, знает, в чем тут штука!', },
    {'Поговорите с Коротышкой Джоном Мифрилом на арене Тернистой долины.', },
  },
  [7926] = {
    'Ярмарка Новолуния',
    {'Скоро начнется Ярмарка Новолуния – время чудес и веселья!|n|nЕсли ты поторопишься, то сможешь обменять этот сертификат на бесплатные призовые купоны! Передай свой сертификат Гелвасу Углешлюзу в ярмарочном лагере.|n|nСейчас ярмарка стоит рядом с Громовым Утесом, в Мулгоре. Не упусти свой шанс! Отправляйся прямо сегодня!', },
    {'Передайте сертификат на призовой купон Гельвасу Угольному Шлюзу на ярмарке Новолуния.', },
  },
  [7927] = {
    'Колода карт Новолуния: Порталы',
    {'Как только вы собираете вместе восемь карт из колоды Порталов, девятая карта с такой же "рубашкой" появляется в колоде. На карте написано: "Принеси колоду на ярмарку Новолуния, и получишь награду". Ярмарка приезжает в Мулгор и Златоземье раз в несколько месяцев. Придется подождать до следующего раза...', },
    {'Принесите карты Порталов на ярмарку Новолуния.', },
  },
  [7928] = {
    'Колода карт Новолуния: Полководцы',
    {'Как только вы собираете вместе восемь карт из колоды воинов, девятая карта с такой же "рубашкой" появляется в колоде. На карте написано: "Принеси колоду на ярмарку Новолуния, и получишь награду". Ярмарка приезжает в Мулгор и Златоземье раз в несколько месяцев. Придется подождать до следующего раза...', },
    {'Принесите колоду Полководцев на ярмарку Новолуния.', },
  },
  [7929] = {
    'Колода карт Новолуния: Элементали',
    {'Как только вы собираете вместе восемь карт из колоды Элементалей, девятая карта с такой же "рубашкой" появляется в колоде. На карте написано: "Принеси колоду на ярмарку Новолуния, и получишь награду". Ярмарка приезжает в Мулгор и Златоземье раз в несколько месяцев. Придется подождать до следующего раза...', },
    {'Принесите колоду Элементалей на ярмарку Новолуния.', },
  },
