  [8194] = {
    'Начинающий рыболов',
    nil,
    nil,
  },
  [8195] = {
    'Монеты племен: Зулиан, Раззаши и Хаккари',
    nil,
    nil,
  },
  [8196] = {
    'Экстракт манго',
    nil,
    nil,
  },
  [8201] = {
    'Коллекция голов',
    {'Это правда. Хаккар теперь обитает в Зул\'Гурубе, питаясь силой наших богов. Порабощеные им жрецы направляют энергию самых священных божеств Свежевателю Душ, и скоро сильнее его в Азероте не будет существа. Его надо остановить!|n|nВозьми этот священный шнур. Нанижи на него головы верховных жрецов, по вине которых сила наших богов утекает к Хаккару.|n|nСделав это, возвращайся ко мне.', },
    {'Соберите ожерелье из голов пятерых жрецов и вернитесь с ним к Экзалу на остров Йоджамба.', },
  },
  [8221] = {
    'Редкая рыба – рыба-ангел Кифэра',
    nil,
    nil,
  },
  [8222] = {
    'Светящаяся кровь скорпида',
    nil,
    nil,
  },
  [8223] = {
    'Обмен: светящаяся кровь скорпида',
    nil,
    nil,
  },
  [8224] = {
    'Редкая рыба – дезийская ставрида',
    nil,
    nil,
  },
  [8225] = {
    'Редкая рыба – синий полосатик Браунелла',
    nil,
    nil,
  },
  [8226] = {
    'Редкая рыба – бледная упырыба',
    nil,
    nil,
  },
  [8227] = {
    'Измерительная лента Ната',
    {'Среди разбросанных рыболовных инструментов лежит свернутая шелковая измерительная лента. К ней прицеплена бирка с надписью:|n|n"Нат Пэгл, Пылевые топи".', },
    {'Верните измерительную ленту Нату Пэглу. Найти Пэгла можно в Пылевых топях.', },
  },
  [8228] = {
    'Приглашение на рыбалку',
    nil,
    nil,
  },
  [8229] = {
    'Приглашение на рыбалку',
    nil,
    nil,
  },
  [8230] = {
    'Пробный квест Коллина',
    nil,
    nil,
  },
  [8231] = {
    'Охота на волношлепа',
    {'Волношлеп – земноводное, встречающееся только в Азшаре. Эти твари сильны и очень живучи. |n|nВ их твердой блестящей чешуе, как в зеркале, отражается мастерство охотника. |n|nВыследи и убей нескольких на побережье Азшары и принеси мне их чешую.', },
    {'Принесите 6 чешуй волношлепа Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата.', },
  },
  [8232] = {
    'Зеленый дракон',
    {'Ты отправляешься на опасную охоту, |3-6($R). Убей зеленого дракона Морфаза и принеси мне его зуб. Морфаз обитает в Храме Атал\'Хаккара. Вход в него ты найдешь на Болоте Печали. |n|nНо помни, $Gодному:одной; тебе его не осилить. У дракона много врагов – найди соратников и уничтожь его! |n|nМногие, очень многие не прочь добыть зуб этой твари. Принеси его мне, и я достойно награжу тебя.', },
    {'Принесите зуб Морфаза Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата.', },
  },
  [8233] = {
    'Приглашение',
    {'Лорд Джорах Черный Ворон настоятельно приглашает вас к себе. Приглашение тайное, поэтому никаких подробностей.|n|nПоместье Черный Ворон находится в предгорьях Хилсбрада – горная тропа начинается на северо-западе от крепости Дарнхольд.', },
    {'Поговорите с лордом Джорахом Черным Вороном в его поместье.', },
  },
  [8234] = {
    'Запечатанная лазурная сумка',
    {'Начнем сначала. Я потерял небольшую сумку голубого цвета. В ней были мои личные вещи. |n|nНет нужды искать воров – они уже мертвы. Мне известно лишь, что эти дураки не сумели открыть сумку и продали ее какому-то шаману из племени Древобрюхов в Азшаре, выдав ее за священную реликвию. Очень умно. |n|nЯ хочу, чтобы ты $Gотправился:отправилась; в Азшару и $Gзаполучил:заполучила; у шамана мою сумку – хитростью или силой. Полагаю, что лучше все же хитростью. Сумку отнеси верховному магу Ксилему.', },
    {'Добудьте запечатанную лазурную сумку у шамана из племени Древобрюхов в Азшаре. Затем отнесите сумку верховному магу Ксилему в Азшаре.', },
  },
  [8235] = {
    'Зашифрованные фрагменты',
    {'Лорд Черный Ворон просил нас с тобой об услуге. Он желает снять заклятие с этой сумки. |n|nК сожалению, мои книги по снятию чар были захвачены и уничтожены дикарями. Каждый клочок, оставшийся от них, невероятно ценен для меня. |n|nЕсли ты сможешь принести мне зашифрованные фрагменты, я попробую восстановить хотя бы часть моих книг. Чтобы найти фрагменты, поохоться на обитающих в Азшаре зверей – они обычно подбирают все, что плохо лежит.', },
    {'Принесите 10 зашифрованных фрагментов верховному магу Ксилему в Азшару.', },
  },
  [8236] = {
    'Лазурный ключ',
    {'Мне потребуется время, чтобы расшифровать фрагменты и снять заклятие. Когда я закончу, то самолично доставлю сумку лорду Черному Ворону. |n|nОднако нам все еще нужен ключ. Говорят, что ключ присвоил зеленый дракон по имени Морфаз. Его логово находится в глубинах Храма Атал\'Хаккара – вход в него ты найдешь на Болоте Печали. |n|nСобери своих сподвижников и отправляйся к логову дракона. Лорд Черный Ворон ждет, когда ты принесешь ему ключ.', },
    {'Принесите лазурный ключ лорду Черному Ворону.', },
  },
  [8238] = {
    'Монеты племен: Гурубаши, Порочная Ветвь и Сухокожие',
    nil,
    nil,
  },
  [8239] = {
    'Монеты племен: Песчаная Буря, Дробители Черепов и Кровавый Скальп',
    nil,
    nil,
  },
  [8240] = {
    'Драгоценности для Занзы',
    {'Драгоценности Хаккари необходимо уничтожить. Это наше внутреннее дело, но оно настолько важное, что мы просим о помощи и чужеземцев.|n|nОтыщи в Зул\'Гурубе все драгоценности, которые сможешь, принеси на Алтарь Занзы и уничтожь их. Если ты справишься с этим заданием, я дам тебе почетный знак нашего племени. Знай, что у нас этими знаками не разбрасываются!|n|nСтупай, и да пребудет с тобой благословение Занзы!', },
    {'Найдите в Зул\'Гурубе драгоценности Хаккари и уничтожьте их на Алтаре Занзы на острове Йоджамба. Поговорите с Винчаксой.', },
  },
  [8241] = {
    'Пополнение запасов огненного плавня - железо',
    nil,
    nil,
  },
  [8242] = {
    'Пополнение запасов огненного плавня - толстая кожа',
    nil,
    nil,
  },
  [8243] = {
    'Напиток могущества Занзы',
    nil,
    nil,
  },
  [8246] = {
    'Перстни Зандалара',
    nil,
    nil,
  },
  [8249] = {
    'Принести лари',
    nil,
    nil,
  },
  [8250] = {
    'Магическое искусство',
    {'Верховный маг Ксилем ищет кого-то... Не менее опытного, чем ты.|n|nЕсли хочешь, поговори с ним. Он живет в Азшаре, в башне на вершине утеса. Добраться туда можно лишь при помощи заклинания, которое известно его заносчивому слуге, Санату Лим-Йо.|n|nСанат живет в лагере ниже башни своего хозяина. Найти его можно так: там, где главная дорога Азшары разветвляется у входа в руины Эльдарата, поворачивай строго на север и иди, пока не упрешься в скалы.', },
    {'Найдите Саната Лим-Йо и добейтесь, чтобы он доставил вас к верховному магу Ксилему.', },
  },
  [8251] = {
    'Волшебная пыль',
    {'Эльфы крови в Азшаре изобрели свой способ распылять магические предметы. Получаемая в результате сияющая пыль отличается от элементов, получаемых в результате обычного распыления.|n|nЯ отправил ученика купить этой пыли, но эльфы безжалостно убили его. Они должны заплатить за это! |n|nВремя мирных переговоров прошло, $N. Найди эльфов крови в скалах Азшары и примени к ним более... убедительные методы. Мне нужна эта пыль.', },
    {'Принесите 10 горстей сияющей пыли верховному магу Ксилему.', },
  },
  [8252] = {
    'Кораллы сирен',
    {'Оглянись вокруг. Развалины и все побережье кишат тварями Бича Злобы. Проклятые создания научились искать редкие вещества и предметы, встречающиеся в Азшаре. |n|nНапример, эти твари почему-то очень интересуются заколдованными кораллами – по совершенно не ясным мне причинам. Теперь этих кораллов в бухте почти не осталось, а они так нужны мне для исследований! Прошу тебя, отбери несколько кораллов у сирен из клана Бича Злобы и принеси их мне.', },
    {'Соберите 6 заколдованных кораллов и принесите их верховному магу Ксилему.', },
  },
  [8253] = {
    'Уничтожить Морфаза',
    {'В глубинах Храма Атал\'Хаккара скрывается зеленой дракон по имени Морфаз. |n|nМного лет назад он напал на меня из засады и проглотил целиком сопровождавшего меня ученика. Мне не впервой терять учеников, однако имено этот, проглоченный, нес кристалл тайной магии небывалой мощи. |n|nВыбери достаточно сильных соратников и отправляйся в Затонувший храм. Уничтожь Морфаза и принеси мне мой кристалл.', },
    {'Добудьте кристалл тайной магии из брюха Морфаза и принесите его верховному магу Ксилему.', },
  },
  [8254] = {
    'Помощь Кенарию',
    {'Служителям богов пристало помогать попавшим в беду. Как именно – неважно, главное – во имя чего.|n|nКругу Кенария необходима помощь. Если ты хочешь протянуть им руку помощи, поговори с Огтинком. Он живет на вершинах скал на северо-востоке от руин Эльдарата в Азшаре.', },
    {'Отыщи Огтинка в Азшаре.', },
  },
  [8255] = {
    'Охота на беговых оленей',
    {'Мохноногие олени, обитающие в Азшаре, – самые великолепные создания, когда-либо населявшие Оскверненный лес. Они наделены естественной невосприимчивостью ко всем болезням и ядам, поэтому порча не коснулась их. Мудрые животные предпочли покинуть зараженные земли. |n|nК прискорбию своему я должен просить тебя поохотиться на этих прекрасных созданий, поскольку их железы необходимы для изготовления целительного снадобья. Снадобья, которое вернет Оскверненному лесу его прежний облик.', },
    {'Добудьте 4 железы здорового мохоногого оленя и принесите их Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата.', },
  },
  [8256] = {
    'Лимфа нежити',
    {'Чтобы получить целительное снадобье, воспользуемся простым рецептом: смешаем одну часть яда с двумя благотворными субстанциями. Один целительный компонент у нас уже есть, теперь надо добыть яд. |n|nСамые могущественные твари нежити, такие как неупокоенные высокорожденные, скитающиеся по руинам Эльдарата, часто настолько сильно поражены порчей, что она принимает вполне осязаемую форму зеленой слизи. Среди живых эта субстанция известна как лимфа нежити. |n|nЭто очень мощный яд, поэтому потребуется лишь одна мера.', },
    {'Принесите лимфу нежити Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата.', },
  },
  [8257] = {
    'Кровь Морфаза',
    {'Теперь нам нужен последний целительный компонент. |n|nИзвестно, что зеленый дракон Морфаз наделен невосприимчивостью ко всем болезням и ядам. Это знание досталось дорогой ценой – не один друид погиб, пытаясь справиться с драконом. Уверен, его кровь послужит отличным компонентом для нашего снадобья.|n|nПосланник Круга Кенария заберет уже собранные тобой компоненты, пока ты будешь добывать последний. Собери соратников и отправляйся в логово зеленого дракона в затонувший Храм Атал\'Хаккара. Принеси его кровь Грете Замшелому Копыту в Оскверненный лес.', },
    {'Убейте Морфаза в затонувшем Храме Атал\'Хаккара и принесите его кровь Грете Замшелому Копыту в Оскверненный лес. Вход в храм сокрыт на Болоте Печали.', },
  },
  [8258] = {
    'Угроза Темного Губителя',
    {'Темный Терзатель, рыцарь смерти, владычествует над Главным cклепом в Некроситете. Он собирается подчинить себе весь мир духов! Его необходимо остановить! Тут-то тебе и понадобится кристальный предсказатель.|n|nПриведи его в действие в Главном склепе, чтобы вызвать духов-приспешников Темного Терзателя. Когда ты одолеешь этих духов, явится сам рыцарь смерти. Принеси мне его голову, $N! Только его гибель способна исправить урон, нанесенный миру духов!', },
    {'Используйте кристальный предсказатель в Главном склепе в Некроситете. Сразитесь с духами. Когда появится Темный Терзатель, убейте его.|n|nПринесите голову Темного Терзателя Сагорну Гривастому Страннику в Аллею Мудрости Оргриммара.', },
  },
  [8259] = {
    'Более достойная награда',
    nil,
    nil,
  },
  [8260] = {
    'Амуниция Аратора',
    nil,
