  [8704] = {
    'Перстень Незримого пути',
    {'Я слышала, что кольца, которые носят киражские лейтенанты, дают им невероятные способности. Однако считается, что если заменить пораженные скверной драгоценные камни, вставленные в оправу, на более чистые, мощь колец возрастет еще больше.|n|nКамни, украшающие киражских идолов, вполне подойдут – они отменного качества.|n|nПринеси мне этих идолов и кольцо одного из лейтенантов, и я создам для тебя могущественный талисман, |3-6($C).', },
    {'Принесите киражское церемониальное кольцо, 2 янтарных идола, 5 золотых и 5 глиняных скарабеев Зовущей Йессендре в Силитус. Кроме того, необходимо заслужить как минимум уважительное отношение Круга Кенария.', },
  },
  [8705] = {
    'Чекан Беспредельной мудрости',
    {'Киражи и их прислужники владеют вещами, которые созданы из редчайших и благороднейших материалов – костей гигантских древних созданий, драгоценностей из самых глубин земли, чистейших и прочных металлов...|n|nПри одном взгляде на киражские артефакты мне хочется разбить их, чтобы переплавить обломки и испробовать на них свое собственное искусство. Докажи Кругу Кенариуса свою преданность, $N, и я создам для тебя могучее оружие из лучших киражских материалов.', },
    {'Принесите киражскую изысканную рукоять, 2 лучистых идола, 5 бронзовых скарабеев и 5 скарабеев из слоновой кости Надзирателю Харо в Силитус. Кроме того, вас должны превозносить в Круге Кенария.', },
  },
  [8706] = {
    'Молот Надвигающейся бури',
    {'Киражи и их прислужники владеют вещами, которые созданы из редчайших и благороднейших материалов – костей гигантских древних созданий, драгоценностей из самых глубин земли, чистейших и прочных металлов...|n|nПри одном взгляде на киражские артефакты мне хочется разбить их, чтобы переплавить обломки и испробовать на них свое собственное искусство. Докажи Кругу Кенариуса свою преданность, $N, и я создам для тебя могучее оружие из лучших киражских материалов.', },
    {'Принесите киражскую шипастую рукоять, 2 янтарных идола, 5 скарабеев из слоновой кости и 5 бронзовых скарабеев Надзирателю Харо в Силитус. Кроме того, вас должны превозносить в Круге Кенария.', },
  },
  [8707] = {
    'Клинок Погребенных Тайн',
    {'Киражи и их прислужники владеют вещами, которые созданы из редчайших и благороднейших материалов – костей гигантских древних созданий, драгоценностей из самых глубин земли, чистейших и прочных металлов...|n|nПри одном взгляде на киражские артефакты мне хочется разбить их, чтобы переплавить обломки и испробовать на них свое собственное искусство. Докажи Кругу Кенариуса свою преданность, $N, и я создам для тебя могучее оружие из лучших киражских материалов.', },
    {'Принесите киражскую изысканную рукоять, 2 обсидиановых идола, 5 серебряных и 5 костяных скарабеев Надзирателю Харо в Силитус. Кроме того, вас должны превозносить в Круге Кенария.', },
  },
  [8708] = {
