  [8769] = {
    'Тикающий подарок',
    nil,
    nil,
  },
  [8770] = {
    'Цель: защитники из Улья Аши',
    {'По мере нарастания конфликта, силитиды представляют все большую опасность для наших операций. Тебя избрали для участия в нападении на Улей Аши. Твоей основной целью будут защитники из этого улья.|n|nВыполнив задание, отчитайся командиру Мар\'алиту.', },
    {'Убейте 30 защитников из Улья Аши и доложите о выполнении задания командиру Мар\'алиту в Крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу I.', },
  },
  [8771] = {
    'Цель: пескоходы из Улья Аши',
    {'По мере нарастания конфликта, силитиды представляют все большую опасность для наших операций. Тебя избрали для участия в нападении на Улей Аши. Твоей основной целью будут пескоходы из этого улья.|n|nВыполнив задание, отчитайся командиру Мар\'алиту.', },
    {'Убейте 30 пескоходов из Улья Аши и доложите о выполнении задания командиру Мар\'алиту в Крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу II.', },
  },
  [8772] = {
    'Цель: стражи дорог из Улья Зора',
    {'Мы вызвали подкрепление для сражения у Улья Зора. Твоя задача – убить как можно больше стражей дорог. Выполнив задание, отчитайся командиру Мар\'алиту.', },
    {'Убейте 30 стражей дорог из Улья Зора и доложите о выполнении задания командиру Мар\'алиту из Крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу VI.', },
  },
  [8773] = {
    'Цель: разрушители из Улья Зора',
    {'Мы вызвали подкрепление для сражения у Улья Зора. Твоя задача – убить как можно больше разрушителей. Выполнив задание, отчитайся командиру Мар\'алиту.', },
    {'Убейте 30 разрушителей из Улья Зора и доложите о выполнении задания командиру Мар\'алиту в Крепости Кенария в Силитусе. Для завершения задания принесите изложение боевой задачи IV.', },
  },
  [8774] = {
    'Цель: стерегущие из Улья Регал',
    {'По мере нарастания конфликта, силитиды представляют все большую опасность для наших операций. Тебя избрали для участия в нападении на Улей Регал. Твоей основной целью будут стерегущие этот улей душители.|n|nВыполнив задание, отчитайся командиру Мар\'алиту.', },
    {'Убейте 30 стерегущих из Улья Регал и доложите об этом командиру Мар\'алиту в Крепости Кенария в Силитусе. Для завершения задания принесите изложение боевой задачи VIII.', },
  },
  [8775] = {
    'Цель: злюки из Улья Регал',
    {'По мере нарастания конфликта, силитиды представляют все большую опасность для наших операций. Тебя избрали для участия в нападении на Улей Регал. Твоей основной целью будут огнеполохи из этого улья.|n|nВыполнив задание, отчитайся командиру Мар\'алиту.', },
    {'Убейте 30 злюк из Улья Регал и доложите о выполнении задания командиру Мар\'алиту в Крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу IX.', },
  },
  [8776] = {
    'Цель: поработители из Улья Регал',
    {'По мере нарастания конфликта, силитиды представляют все большую опасность для наших операций. Тебя избрали для участия в нападении на Улей Регал. Твоей основной целью будут поработители из этого улья.|n|nВыполнив задание, отчитайся командиру Мар\'алиту.', },
    {'Убейте 30 поработителей из Улья Регал и доложите о выполнении задания командиру Мар\'алиту в Крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу X.', },
  },
  [8777] = {
    'Цель: землерои из Улья Регал',
    {'По мере нарастания конфликта, силитиды представляют все большую опасность для наших операций. Тебя избрали для участия в нападении на Улей Регал. Твоей основной целью будут землерои из этого улья.|n|nВыполнив задание, отчитайся командиру Мар\'алиту.', },
    {'Убейте 30 землероев из Улья Регал и доложите о выполнении задания командиру Мар\'алиту в Крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу XI.', },
  },
  [8778] = {
    'Взрывчатка для дружины Стальгорна',
    {'Дружина Стальгорна прислала необычный запрос – на весьма... э-э-э... неустойчивые вещества. Собери их и принеси господину Пружине Форсунки из дружины Стальгорна.', },
    {'Принесите 6 бутылок воспламеняющей смеси, 5 бочонков гоблинского ракетного топлива и 10 порций концентрированного взрывчатого вещества чародею Пружине Форсунки возле Улья Зора в Силитусе. Кроме того, принесите тыловое задание IV.', },
  },
  [8779] = {
    'Материалы для гадания',
    {'Исследования геолога Злая Шутка имели огромное значение для нашей деятельности в Силитусе. Недавно она запросила материалы для гадания.|n|nПожалуйста, собери все необходимое и отнеси ей. Пусть она продолжает исследования.', },
    {'Принесите 1 большой сверкающий осколок, 1 большой светозарный осколок и 1 огромный изумруд геологу Злой Шутке в Крепости Кенария в Силитусе. Также принесите тыловое задание V.', },
  },
  [8780] = {
    'Комплекты брони',
    {'У дружины Стальгорна на исходе запасы накладок на доспехи. Добудь партию таких комплектов и отнеси их Джанеле Твердомолот на заставу дружины Стальгорна, что рядом с Ульем Зора.', },
    {'Принесите 8 комплектов накладок из грубой кожи и 8 комплектов накладок из толстой кожи Джанеле Твердомолот на заставу дружины Стальгорна возле Улья Зора в Силитусе. Кроме того, сдайте тыловую задачу VII.', },
  },
  [8781] = {
    'Нехватка оружия',
    {'Дружина Стальгорна оказалась чрезвычайно полезным союзником в наших битвах в Силитусе. К сожалению, по пути они растеряли много припасов и оборудования. Добудь партию оружия и доставь ее Джанеле Твердомолот к Улью Зора.', },
    {'Принесите 2 палаша лунной стали Джанеле Твердомолот на заставу дружины Стальгорна возле Улья Зора в Силитусе. Кроме того, сдайте тыловую задачу VI.', },
  },
  [8782] = {
    'Поставки формы',
    {'У нас такой приток добровольцев, что не хватает формы. Принеси материалы для пошива формы и отдай их Зовущей из клана Гордый Рог.', },
    {'Принесите 1 кусок луноткани, 2 рулона рунической ткани и 1 железношелковую паутину Зовущей из клана Гордый Рог в Крепости Кенария в Силитусе. Кроме того сдайте тыловую задачу VIII.', },
  },
  [8783] = {
    'Необычные материалы',
    {'Варгус, кузнец Крепости Кенария, запросил партию зачарованных материалов для создания мощного оружия для наших солдат. Добудь все необходимое и отнеси их Варгусу в Крепость Кенария, чтобы он снабдил войска всем необходимым.', },
    {'Принесите Варгусу из Крепости Кенария в Силитусе 2 зачарованных ториевых слитка и 2 куска зачарованной кожи. Кроме того, принесите тыловое задание IX.', },
  },
  [8784] = {
    'Секреты Кираи',
    {'Вам удалось обнаружить древний киражский артефакт! Возможно, один из драконов, стоящих в храме недалеко от входа, сможет найти применение этой реликвии.', },
    {'Принесите древний киражский артефакт драконам, которые укрылись в храме, недалеко от входа.', },
  },
  [8785] = {
    'Амулеты для легиона Оргриммара',
    {'Легион Оргриммара послал запрос на несколько необычные вещества. Учитывая, как хорошо они проявили себя в Силитусе, мы бы хотели как можно скорее выполнить их просьбу. Собери материалы и отнеси их троллихе по имени Шаи.', },
    {'Принесите 6 мощных амулетов, 6 бутылей большого колдунства и 8 бутылок воспламеняющей смеси темной жрице Шаи к Улью Регал в Силитус. Кроме того, принесите тыловое задание IV.', },
  },
  [8786] = {
    'Нехватка оружия',
    {'Легион Оргриммара послал запрос на поставку оружия, а его нет на складе! Добудь необходимое снаряжение и отнеси его Мероку Долгому Шагу к Улью Регал.', },
    {'Принесите 3 массивных железных топора Мероку Долгому Шагу в лагерь легиона Оргриммара рядом с Ульем Регал. Кроме того, сдайте тыловую задачу VI.', },
  },
  [8787] = {
    'Комплекты брони',
    {'В Силитус, к нам на подмогу, прибыли отважные добровольцы из легиона Оргриммара. По пути они растеряли свои запасы накладок на доспехи. Добудь партию таких комплектов и отнеси их Мероку Долгому Шагу, в лагерь легиона Оргриммара.', },
    {'Принесите 8 комплектов накладок из грубой кожи и 8 комплектов накладок из толстой кожи Мероку Долгому Шагу к Улью Регал. Кроме того, сдайте тыловую задачу VII.', },
  },
  [8788] = {
    'Слегка помятый подарок',
    nil,
    nil,
  },
  [8789] = {
    'Киражское императорское оружие',
    {'Мы не то чтобы просто сидели здесь на протяжении тысячелетий, $N.|n|nМы наблюдали за торжеством этих тварей, пока они пировали и истощали свои ресурсы. Мы слушали, как они строят схемы и планы по уничтожению нашего мира. Мы узнали о предателях в их рядах.|n|nУ них есть слабости, и теперь мы знаем, как их использовать.|n|nНайди и принеси мне их церемониальное оружие. В сочетании с предметами, созданными непостоянством их собственного бога, оно станет силой, с которой придется считаться любому.', },
    {'Аригос в Храме Ан\'Киража создаст для вас усиленное элементием оружие, если вы принесете ему киражское имперское оружие и 3 куска элементиевой руды.', },
  },
  [8790] = {
    'Киражские монаршие регалии',
    {'Аригос предполагает, что элемент, рожденный в результате столкновения между Древними Богами и их прислужниками, в надлежащих условиях станет для них смертельным. Я имею в виду элементий, $Gсмертный:смертная;.|n|nПринеси мне киражские императорские регалии и это вещество-яд, я и смогу создать оружие, обладающее великой силой.', },
    {'Меритра из Сна в Храме Ан\'Киража может создать для вас усиленное элементием оружие, если вы принесете ей киражские имперские регалии и 3 куска элементиевой руды.', },
  },
  [8791] = {
    'Повергнутый Оссириан',
    {'Смертельная угроза больше не нависает над нами. Безжалостный Оссириан повержен!|n|nОб этой победе должны узнать все жители Калимдора. Отнесите голову Оссириана командиру Мар\'алиту в Крепость Кенария.', },
    {'Принесите голову Оссириана Неуязвимого командиру Мар\'алиту в Крепость Кенария.', },
  },
  [8792] = {
    'Орде нужна твоя помощь!',
    {'Приветствую! Хорошо, что ты $Gрешил:решила; поговорить со мной. Если мы хотим достойно подготовиться к ан\'киражской войне, то Орде должны помогать все, кто может. Вот и тебе не след оставаться в стороне. Пока мы тут с тобой болтаем, наши интенданты запасают всяческие ресурсы, но без твоей помощи им не справиться, $N!|n|nПоговори с тем, кто отвечает за заготовки, – с вождем Горчуком. Ну как, что скажешь, |3-6($C)? Примешь участие в этом жизненно важном деле?', },
    {'Поговорите с вождем Горчуком в Аллее Духов Оргриммара.', },
  },
  [8793] = {
    'Орде нужна твоя помощь!',
    {'Приветствую! Хорошо, что ты $Gрешил:решила; поговорить со мной. Если мы хотим достойно подготовиться к ан\'киражской войне, то Орде должны помогать все, кто может. Вот и тебе не след оставаться в стороне. Пока мы тут с тобой болтаем, наши интенданты запасают всяческие ресурсы, но без твоей помощи им не справиться, $N!|n|nПоговори с тем, кто отвечает за заготовки, – с вождем Горчуком. Ну как, что скажешь, |3-6($C)? Примешь участие в этом жизненно важном деле?', },
    {'Поговорите с вождем Горчуком в Аллее Духов Оргриммара.', },
  },
  [8794] = {
    'Орде нужна твоя помощь!',
    {'Приветствую! Хорошо, что ты $Gрешил:решила; поговорить со мной. Если мы хотим достойно подготовиться к ан\'киражской войне, то Орде должны помогать все, кто может. Вот и тебе не след оставаться в стороне. Пока мы тут с тобой болтаем, наши интенданты запасают всяческие ресурсы, но без твоей помощи им не справиться, $N!|n|nПоговори с тем, кто отвечает за заготовки, – с вождем Горчуком. Ну как, что скажешь, |3-6($C)? Примешь участие в этом жизненно важном деле?', },
    {'Поговорите с вождем Горчуком в Аллее Духов Оргриммара.', },
  },
  [8795] = {
    'Альянсу нужна твоя помощь!',
    {'Приветствую. Хорошо, что ты $Gрешил:решила; поговорить со мной. В подготовке к войне в Ан\'Кираже Альянс должен использовать все доступные ресурсы, а значит, посильный вклад может внести каждый! Уже назначены ответственные за сбор разнообразных материалов, но без помощи обычных граждан им не справиться, $N!|n|nЕсли хочешь поддержать Альянс, обратись к фельдмаршалу Снегопаду, который отвечает за заготовки. Ну как, что скажешь, |3-6($C)? Примешь ли ты участие ли ты в нашем жизненно важном деле?', },
    {'Поговорите с фельдмаршалом Снегопадом, который находится в Палатах Войны Стальгорна.', },
  },
  [8796] = {
    'Альянсу нужна твоя помощь!',
    {'Приветствую. Хорошо, что ты $Gрешил:решила; поговорить со мной. В подготовке к войне в Ан\'Кираже Альянс должен использовать все доступные ресурсы, а значит, посильный вклад может внести каждый! Уже назначены ответственные за сбор разнообразных материалов, но без помощи обычных граждан им не справиться, $N!|n|nЕсли хочешь поддержать Альянс, обратись к фельдмаршалу Снегопаду, который отвечает за заготовки. Ну как, что скажешь, |3-6($C)? Примешь ли ты участие ли ты в нашем жизненно важном деле?', },
    {'Поговорите с фельдмаршалом Снегопадом, который находится в Палатах Войны Стальгорна.', },
  },
  [8797] = {
    'Альянсу нужна твоя помощь!',
    {'Приветствую. Хорошо, что ты $Gрешил:решила; поговорить со мной. В подготовке к войне в Ан\'Кираже Альянс должен использовать все доступные ресурсы, а значит, посильный вклад может внести каждый! Уже назначены ответственные за сбор разнообразных материалов, но без помощи обычных граждан им не справиться, $N!|n|nЕсли хочешь поддержать Альянс, обратись к фельдмаршалу Снегопаду, который отвечает за заготовки. Ну как, что скажешь, |3-6($C)? Примешь ли ты участие ли ты в нашем жизненно важном деле?', },
    {'Поговорите с фельдмаршалом Снегопадом, который находится в Палатах Войны Стальгорна.', },
  },
  [8798] = {
    'Твой собственный Йети',
    nil,
    nil,
  },
  [8799] = {
    'Герой дня',
    {'Слушай... Я вообще-то не должен тебе этого говорить, но раз уж ты у нас сегодня герой; и все такое...|n|nВ эту пору везде полно остролиста, но он быстро вянет. Мы получили машину для заготовки остролиста – и он не портится! Мы его используем, чтобы придать вкус празднику... и ради прибыли – летом!|n|nЯ позволю тебе попользоваться этой машинкой, но только если ты мастер-кулинар. От тебя потребуется некоторое количество глубокоскальной соли и два-три, ну, скажем, пять золотых. И получишь славную партию остролиста, которую можно хранить сколько угодно.', },
    {'Принесите 1 порцию глубокоскальной соли и 5 золотых монет к сушилке для остролиста, чтобы получить 5 сушеных остролистов.', },
  },
  [8800] = {
    'Броня Кенария',
    {'Выполнив все задания, обратись к Варгусу, кузнецу. Покажи ему все заработанные знаки, и получишь награду, в зависимости от твоей преданности нашему делу.', },
    {'Поговорите с Варгусом в Крепости Кенария в Силитусе.', },
  },
  [8801] = {
    'Наследие К\'Туна',
    {'Стены Ан\'Киража содрогаются. Сила зла, более древняя, чем сам этот мир, уничтожена.|n|nПри одном взгляде на лежащие перед вами мерзкие останки стынет сердце. Даже после смерти К\'Тун распространяет вокруг себя ауру зла.|n|nВам удалось совершить невозможное.|n|nВы извлекаете глаз и осторожно укладываете его в сумку.|n|nНужно доставить глаз К\'Туна в соседнюю залу и отдать драконам.', },
    {'Принесите Глаз К\'Туна Келестрасу в Храм Ан\'Кирая.', },
  },
  [8802] = {
    'Спаситель Калимдора',
    {'Пришла пора вернуться в Пещеры Времени, $Gгосподин:госпожа; $N. Анахронос ожидает тебя. Отдай ему глаз К\'Туна – не сомневаюсь, он непременно захочет поместить его в коллекцию своего хозяина.', },
    {'Принесите глаз К\'Туна Анахроносу в Пещеры Времени.', },
  },
  [8803] = {
    'Подарок в разноцветной упаковке',
    nil,
    nil,
  },
  [8804] = {
    'Неприкосновенный запас',
    {'В Крепость Кенария прибыли новые добровольцы, и мы должны позаботиться, чтобы они выжили в пустыне. Новичкам грозит обезвоживание и множество ядовитых тварей. Собери как можно больше составляющих неприкосновенных наборов для отправляющихся в пустыню и отнеси их Каландрате в Крепость Кенария.', },
    {'Принесите 4 сферы воды, 4 мощных противоядия и 4 копченые пустынные клецки Каландрате в таверну в Крепости Кенария в Силитусе. Кроме того, сдайте тыловую задачу I.', },
  },
  [8805] = {
    'Сапоги для стражей',
    {'Верховому подразделению Крепости Кенария не хватает изысканных мифриловых сапог. Принеси нам очередную партию и передай их капитану Вишу Коцусу из Крепости Кенария.', },
    {'Принесите 3 пары изысканных мифриловых сапог Вишу Коцусу, капитану стражи в Крепости Кенария в Силитусе. Кроме того сдайте тыловую задачу II.', },
  },
  [8806] = {
    'Шлифовальные камни',
    {'У стражи Крепости Кенария на исходе шлифовальные камни. Добудь их и отнеси капитану Вишу Коцусу в Крепость Кенария.', },
    {'Принесите 10 увесистых точильных каменей, 10 твердых шлифовальных камней и 10 тяжелых точильных каменей Вишу Коцусу, капитану стражи в Крепости Кенария в Силитусе. Кроме того сдайте тыловую задачу III.', },
  },
  [8807] = {
    'Материалы для гадания',
    {'Исследования геолога Злая Шутка имели огромное значение для нашей деятельности в Силитусе. Недавно она запросила материалы для гадания.|n|nПожалуйста, собери все необходимое и отнеси ей. Пусть она продолжает исследования.', },
    {'Принесите 1 большой сверкающий осколок, 1 большой светозарный осколок и 1 огромный изумруд геологу Злой Шутке в Крепости Кенария в Силитусе. Также принесите тыловое задание V.', },
  },
  [8808] = {
    'Поставки формы',
    {'У нас такой приток добровольцев, что не хватает формы. Принеси материалы для пошива формы и отдай их Зовущей из клана Гордый Рог.', },
    {'Принесите 1 кусок луноткани, 2 рулона рунической ткани и 1 железношелковую паутину Зовущей из клана Гордый Рог в Крепости Кенария в Силитусе. Кроме того сдайте тыловую задачу VIII.', },
  },
  [8809] = {
    'Необычные материалы',
    {'Варгус, кузнец Крепости Кенария, запросил партию зачарованных материалов для создания мощного оружия для наших солдат. Добудь все необходимое и отнеси их Варгусу в Крепость Кенария, чтобы он снабдил войска всем необходимым.', },
    {'Принесите Варгусу из Крепости Кенария в Силитусе 2 зачарованных ториевых слитка и 2 куска зачарованной кожи. Кроме того, принесите тыловое задание IX.', },
  },
  [8810] = {
    'Запас бинтов',
    {'В последнее время мы понесли серьезные потери, и запас бинтов стремительно иссякает. Добудь нам первоклассные перевязочные материалы и отнеси их призывательнице ветров Гордому Рогу в Крепость Кенария.', },
    {'Принесите 30 плотных бинтов из рунической ткани, 30 плотных шелковых бинтов и 30 бинтов из магической ткани призывательнице ветров Гордому Рогу в Крепости Кенария в Силитусе. Кроме того, сдайте тыловую задачу X.', },
  },
