  [8856] = {
    'Неприкосновенный запас',
    {'В Крепость Кенария прибыли новые добровольцы, и мы должны позаботиться, чтобы они выжили в пустыне. Новичкам грозит обезвоживание и множество ядовитых тварей. Собери как можно больше составляющих неприкосновенных наборов для отправляющихся в пустыню и отнеси их Каландрате в Крепость Кенария.', },
    {'Принесите 4 сферы воды, 4 мощных противоядия и 4 печеных лосося Каландрате в таверну в Крепости Кенария в Силитусе.', },
  },
  [8857] = {
    'Тайны колосса – Аши',
    {'Мне нужны закаленные в бою искатели приключений, которые согласятся принести свежие образцы панциря павшего колосса Аши Карлсу в Пиратскую Бухту. Нет-нет, я не прошу подходить к телу этой твари. Возьми один из образцов у меня и поспеши. Тухлятина ему не годится!', },
    {'Отнесите фрагмент панциря колосса Аши Карлсу Пропеллерзу в Пиратскую Бухту.', },
  },
  [8858] = {
    'Тайны колосса – Регал',
    {'Я бы с радостью сунул этот панцирь прямо в наглую рожу Скользкорука... Только вот мне не выбраться, я собираю образцы этого тараканища. И судя по его размерам, провожусь еще лет сто.|n|nОтнеси этот образец Скользкоруку, и побыстрее. Он платит МНОГО!|n|nА вот его адресок: Лагерь Братства Тория – он в Тлеющем ущелье.', },
    {'Отнесите фрагмент панциря колосса Регала надзирателю Скользоруку в Тлеющем ущелье.', },
  },
  [8859] = {
    'Тайны колосса – Зора',
    {'Моих слуг едва не убили при попытке добыть эти образцы. Не медли ни минуты! Лорд Максвелл Тиросс с нетерпением ждет свежих образцов панцирей. Он надеется, что тайны Колосса помогут нам в войне с Плетью!|n|nТы еще тут?! Вперед, в часовню Последней Надежды! Да, ты получишь неплохую награду за труды...', },
    {'Отнесите фрагмент панциря колосса Зоры лорду Максвеллу Тироссу в Часовню Последней Надежды в Восточных Чумных землях.', },
  },
  [8860] = {
    'Отмечаем Новый Год!',
    {'Штормград устраивает празднество в честь нового года! Целый день там можно пить задарма, а ночью будет фейерверк!|n|nЭто должно быть прекрасно... но в Пиратской Бухте сегодня тоже праздник, и держу пари, там будет еще лучше!|n|nНу, как бы то ни было, хозяйке таверны Аллисон в Штормграде требуются припасы Пастбищ Дымного Леса, чтобы помочь накормить всех гуляк. Окажи мне услугу, доставь эту партию!|n|nСпасибо, $N! Аллисон держит таверну "Позолоченная роза" в Торговом квартале Штормграда.', },
    {'Отнесите припасы Пастбищ Дымного Леса хозяйке таверны Аллисон в Штормград.', },
  },
  [8861] = {
    'Отмечаем Новый Год!',
    {'Громовой Утес устраивает празднество в честь нового года! Целый день там можно пить задарма, а ночью будет фейерверк!|n|nЭто должно быть прекрасно... но в Пиратской Бухте сегодня тоже праздник, и держу пари, там будет еще лучше!|n|nНу, как бы то ни было, хозяйке таверны Пале в Громовом Утесе требуются припасы Пастбищ Дымного Леса, чтобы помочь накормить всех гуляк. Окажи мне услугу, доставь эту партию!|n|nСпасибо, $N! Пала держит таверну возле моста, ведущего на вершину Охотников.', },
    {'Отнесите припасы Пастбищ Дымного Леса хозяйке таверны Пале в Громовой Утес.', },
  },
  [8862] = {
    'Свеча Элуны',
    nil,
    nil,
  },
  [8863] = {
    'Праздничные клецки',
    nil,
    nil,
  },
  [8864] = {
    'Платья Лунного фестиваля',
    nil,
    nil,
  },
  [8865] = {
    'Костюмы Лунного фестиваля',
    nil,
    nil,
  },
  [8866] = {
    'Предок Бронзобород',
    nil,
    nil,
  },
  [8867] = {
    'Лунный фейерверк',
    {'Каждый год друиды Лунной поляны празднуют торжество своего города над древним злом.|n|nМы вспоминаем о мудрости старейшин, наслаждаемся пирами и, разумеется, пускаем фейерверки!|n|nЗа небольшое пожертвование ты можешь приобрести разноцветные ракеты у наших торговцев и запустить их с помощью пусковых установок.', },
    {'Запустите 8 ракет и 2 фейерверка. Вернитесь к предвестнице Лунного фестиваля в любую столицу.', },
  },
  [8868] = {
    'Благословение Элуны',
    {'Этот проклятый демон, Омен, был некогда героем нашего мира. Волк великой силы, баловень удачи, Омен сражался плечом к плечу с героями Войны Древних, пока не попал под власть демонический магии. Обратившись против своих союзников, он в ярости рыскал по Азероту, сея вокруг себя смерть и ужас.|n|nНаконец, побежденный здесь, в Лунной поляне, Омен ныне спит под илом озера Элуне\'ара. Но каждый год во время праздника он пробуждается... |n|nСобирай соратников, $N, вызови на бой и порази исчадие тьмы, Омена. Заслужи благословение Элуны!', },
    {'Призовите Омена, победите его и получите благословение Элуны. Вернитесь к Валадару Звездной Песне в Ночную Гавань.', },
  },
  [8869] = {
    'Секрет безмятежности',
    {'Отправляйтесь в Стратхольм и убейте Молотобойца из Багрового легиона. Возьмите его фартук и возвращайтесь к Лилит.', },
    {'Отправляйтесь в Стратхольм и убейте Молотобойца из Багрового легиона. Возьмите его фартук и возвращайтесь к Лилит.', },
  },
  [8870] = {
    'Лунный фестиваль',
    {'Время веселиться, $N! Круг Кенария приглашает всех обитателей Азерота принять участие в нашем Лунном фестивале. В городе ты найдешь предвестницу Лунного фестиваля – ее расположение отмечено кругом благословенного лунного света. Она расскажет тебе больше об этом празднике.', },
    {'Поговорите с предвестницей Лунного фестиваля в Палатах Магии Стальгорна. Вы можете также поговорить с предвестницами Лунного фестиваля в других столичных городах.', },
  },
  [8871] = {
    'Лунный фестиваль',
    {'Время веселиться, $N! Круг Кенария приглашает всех обитателей Азерота принять участие в нашем Лунном фестивале. В городе ты найдешь предвестницу Лунного фестиваля – ее расположение отмечено кругом благословенного лунного света. Она расскажет тебе больше об этом празднике.', },
    {'Поговорите с предвестницей Лунного фестиваля в парке Штормграда. Вы можете также поговорить с предвестницами Лунного фестиваля в других столичных городах.', },
  },
  [8872] = {
    'Лунный фестиваль',
    {'Время веселиться, $N! Круг Кенария приглашает всех обитателей Азерота принять участие в нашем Лунном фестивале. В городе ты найдешь предвестницу Лунного фестиваля – ее расположение отмечено кругом благословенного лунного света. Она расскажет тебе больше об этом празднике.', },
    {'Поговорите с предвестницей Лунного фестиваля в дарнасском Анклаве Кенария. Вы можете также поговорить с предвестницами Лунного фестиваля в других столичных городах.', },
  },
  [8873] = {
    'Лунный фестиваль',
    {'Время веселиться, $N! Круг Кенария приглашает всех обитателей Азерота принять участие в нашем Лунном фестивале. В городе ты найдешь предвестницу Лунного фестиваля – ее расположение отмечено кругом благословенного лунного света. Она расскажет тебе больше об этом празднике.', },
    {'Поговорите с предвестницей Лунного фестиваля в Аллее Мудрости в Оргриммаре. Вы можете также поговорить с предвестницами Лунного фестиваля в других столичных городах.', },
  },
  [8874] = {
    'Лунный фестиваль',
    {'Время веселиться, $N! Круг Кенария приглашает всех обитателей Азерота принять участие в нашем Лунном фестивале. В городе ты найдешь предвестницу Лунного фестиваля – ее расположение отмечено кругом благословенного лунного света. Она расскажет тебе больше об этом празднике.', },
    {'Поговорите с предвестницей Лунного фестиваля у входа в Подгород. Вы можете также поговорить с предвестницами Лунного фестиваля в других столичных городах.', },
  },
  [8875] = {
    'Лунный фестиваль',
    {'Время веселиться, $N! Круг Кенария приглашает всех обитателей Азерота принять участие в нашем Лунном фестивале. В городе ты найдешь предвестницу Лунного фестиваля – ее расположение отмечено кругом благословенного лунного света. Она расскажет тебе больше об этом празднике.', },
    {'Поговорите с предвестницей Лунного фестиваля на вершине Старейшин Громового Утеса. Вы можете также поговорить с предвестницами Лунного фестиваля в других столичных городах.', },
  },
  [8876] = {
