  [9050] = {
    'Накулачники искупления',
    {'Убивая лордов Наксрамаса, ты найдешь остатки доспехов наших павших героев. Принеси их мне. Заодно захвати обломки лат, поврежденных в бою, и материалы, способные вдохнуть новую жизнь в оскверненные доспехи. Тогда я сделаю тебе очень неплохую броню.', },
    {'Командир Элигор Вестник Рассвета из Часовни Последней Надежды, что в Восточных Чумных землях, готов сделать накулачники Искупления, если вы принесете ему следующее: 1 испоганенные накулачники, 6 обломков доспехов, 1 слиток арканита и 2 обработанных грубых шкуры.', },
  },
  [9051] = {
    'Испытание яда',
    {'Яд, который ты $Gпомог:помогла; мне создать, нужен мне для особых целей. Огромные дьявозавры, обитающие в кратере, мешают мне охотиться и даже угрожают моей жизни. Даже если бы у меня хватило сил, чтобы убить дьявозавра, это было бы бесполезно – на место убитого немедленно придет другой. |n|nВозьми эту отравленную колючку и загони ее глубоко в шкуру дьявозавра. Яд усмирит зверя, хоть я и не знаю, насколько быстро...', },
    {'Уколите дьявозавра колючкой дьявозавра. По выполнении задания вернитесь к Землепроходцу Торве.', },
  },
  [9052] = {
    'Яд кровоцвета',
    {'Мне нужна твоя помощь в создании яда, с помощью которого я собираюсь усмирять огромных чудовищ, обитающих в кратере. Не бойся, яд не смертелен. Кроме того, острые глаза |3-1($C) будут большим подспорьем при сборе ингредиентов. |n|nГрибы-кровошляпочники растут под побегами кровоцвета – их в кратере полным полно. Жала Гориши можно собрать с насекомых, которые водятся в районе Скользкого оврага в южной части кратера.', },
    {'Соберите 8 кровошляпочников и 8 жал Гориши и вернитесь к Землепроходцу Торве в Кратер Ун\'Горо.', },
  },
  [9053] = {
    'Лучший ингредиент',
    {'Как я и опасался – яд слишком слаб для такого большого зверя. |n|nЧтобы создать более мощный яд, мне потребуются лучшие ингредиенты. Отправляйся на дно Храма Атал\'Хаккара, раскрой секреты алтаря и заполучи от тамошнего стража гнилую лозу. Храм опасен, поэтому не ходи $Gодин:одна;. |n|nВозвращайся ко мне, когда закончишь задание.', },
    {'Возьмите гнилую лозу у стража на дне затонувшего храма и вернитесь к Землепроходцу Торве.', },
  },
