  [9061] = {
    'Накулачники расхитителя гробниц',
    {'Я придумал, как лучше использовать панцири некрорахнидов. Если укрепить с их помощью испоганенные магические доспехи, которых хватает в Наксрамасе, выйдет броня невиданной прочности.|n|nПринеси мне все необходимое, и я создам для тебя лучшие на свете доспехи!', },
    {'Охотник Леопольд из Часовни Последней Надежды в Восточных Чумных землях готов создать накулачники Расхитителя гробниц, если вы принесете ему следующее: 1 испоганенные накулачники, 6 обрывков кольчуги, 1 слиток арканита и 2 обработанных грубых шкуры.', },
  },
  [9062] = {
    'Промокшие страницы',
    {'Да уж, завидев кого-то, кому с ними не справиться, эти проклятые Презренные разбегаются быстрее зайцев! Ладно, сейчас не о том речь. Нужно отыскать гримуар стихий моего наставника!|n|nЯ точно видел, как один из этих трусов швырнул его в реку, но вот где он теперь? Может, ты поможешь его отыскать? Я в долгу не останусь!', },
    {'Отыщите в реке под мостом гримуар стихий Антеола по просьбе ученика Меледора в Лесах Вечной Песни.', },
  },
  [9063] = {
    'Землепроходец Торва',
    {'Охотнику по имени Землепроходец Торва понадобилась помощь друида. Он сказал, что лишь у нас есть нужные навыки и должное уважение к природе.|n|nОт Кратера Ун\'Горо к пустыне Танарис ведет дорога. Торва стоит у самого входа в кратер.', },
    {'Поговорите с Землепроходцем Торвой в Кратере Ун\'Горо.', },
  },
  [9064] = {
    'Взять вину на себя',
    {'Ох, то-то Антеол разъярится, что его книжка испорчена! Слушай, есть предложение. Не бойся, ты внакладе не останешься.|n|nОтнеси ему эту книжку. О том, что произошло, ни гу-гу. А если спросит, как это вышло, просто скажи, что ты $Gуронил:уронила; книжку в лужу. Тебе он не наставник, так что тебе за это ничего не будет.|n|nАнтеол читает свои лекции у пруда Тихого Шелеста, к юго-востоку от Луносвета. Ты ведь это сделаешь, ладно? Мы в долгу не останемся!', },
    {'Принесите гримуар стихий Антеола Инструктору Антеолу у пруда Тихого Шелеста в Лесах Вечной Песни.', },
  },
  [9065] = {
    'Задание Чоу (123)аа',
    {'Эй, ты! Убей пару кобольдов-вредителей.', },
    {'Убедитесь, что вы уничтожили эту башню!', },
  },
  [9066] = {
    'Суровый урок',
    {'Надеюсь, что сегодня ты, $N, получишь ценный урок. Никогда не поручай кому-то другому лгать вместо тебя.|n|nА теперь возвращайся к моим бестолковым студентам и вразуми их с помощью этого жезла. Моя магия подсказывает мне, что ты найдешь их на дороге к западу отсюда, по ту сторону Тропы Мертвых.|n|nКогда выполнишь это, возвращайся ко мне. Я дам тебе небольшую награду за труды.', },
    {'Накажите карающим жезлом Антеола двух его студентов, ученика Ралена и ученика Меледора. Верните жезл Антеолу у пруда Тихого Шелеста в Лесах Вечной Песни.', },
  },
  [9067] = {
    'Бесконечный праздник',
    {'Люблю устраивать праздники! Кель\'Талас будто нарочно для этого создан.|n|nНо сейчас мне совершенно недосуг. Мне нужна твоя помощь. Собери побольше припасов к праздничному столу.|n|nПринеси мне от винодела Благословение Солнца из таверны Луносвета бутылку вина "Особые запасы Благословения Солнца". У Залены Юной Зари в Обители Странников возьмешь еще немного этой прелестной закуски из прыголапа. Еще, кстати, забери заказанные мною фейерверки у Халиса Рассветного Странника в деревне Легкий Ветерок!|n|nДа побыстрее!', },
    {'Возьмите бутылку "Особых запасов Прикосновения Солнца", закуску из прыголапа и связку фейерверков и принесите все это лорду Салтерилу на виллу Салтерила, что в Лесах Вечной Песни.', },
  },
  [9068] = {
    'Мундир Землекрушителя',
    {'Прошу тебя, окажи мне честь и верни броню тех, кто пал, защищая эти земли.|n|nЗлые силы несомненно испоганили эти доспехи и используют их для собственных гнусных целей, однако их можно укрепить при помощи обрывков кольчуг и вновь пойти в них на войну.|n|nПринеси мне остатки брони павших и материалы для их очищения, и получишь взамен доспехи Землекрушителя.|n|nСтупай, поищи в Наксрамасе.', },
    {'Римблат Землекрушитель из Часовни Последней Надежды в Восточных Чумных землях готов создать мундир Землекрушителя, если вы принесете ему следующее: 1 испоганенный мундир, 25 обрывков кольчуги, 4 слитка арканита и 3 обработанных грубых шкуры.', },
