  [9187] = {
    'Задание мастера: рунические кожание штаны',
    {'Податель сего имеет право на получение награды в форме значков отличия по своему выбору в случае выполнения задания, указанного в контракте.|n|nЗаказ-наряд LW-8485:|n|n4 пары рунических кожаных штанов.|n|nВыполненные заказы доставлять караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли.|n|nКонтракт признается недействительным в случае, если бумага была подделана или тем или иным образом испорчена.|n|nПодпись: Командир Метц, Серебряный Рассвет', },
    {'Доставьте 4 пары рунических кожаных штанов и соответствующее задание мастера караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли.', },
  },
  [9188] = {
    'Задание мастера: штаны из яркой ткани',
    {'Податель сего имеет право на получение награды в форме значков отличия по своему выбору в случае выполнения задания, указанного в контракте.|n|nЗаказ-наряд TR-95:|n|n6 пар штаны из яркой ткани.|n|nВыполненные заказы доставлять караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли.|n|nКонтракт признается недействительным в случае, если бумага была подделана или тем или иным образом испорчена.|n|nПодпись: Командир Метц, Серебряный Рассвет', },
    {'Доставьте 6 пар штаны из яркой ткани и соответствующее задание мастера караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли.', },
  },
  [9189] = {
    'Посылка в Гробницу',
    {'Тебе удалось тронуть женское сердце, хоть оно и не бьется.|n|nОднако мне нужно доставить кое-какие бумаги в Гробницу, расположенную в Серебряном бору. Наш представитель там – советник Соррелон.|n|nЕсли ты не собираешься лететь на летучей мыши, кратчайший путь – это выйти из Подгорода и двинуться по дороге на юг. Смотри на указатели, отыскать нужное место будет несложно. Соберись с духом. Гробница представляет собой полуразрушенный склеп.|n|nСтранные существа эти Отрекшиеся.', },
    {'Отнесите запечатанные приказы син\'дорай советнику Соррелону в Гробницу в Серебряном бору.', },
  },
  [9190] = {
    'Задание мастера: сапоги из рунической ткани',
    {'Податель сего имеет право на получение награды в форме значков отличия по своему выбору в случае выполнения задания, указанного в контракте.|n|nЗаказ-наряд TR-635:|n|n8 пар сапог из рунической ткани.|n|nВыполненные заказы доставлять караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли.|n|nКонтракт признается недействительным в случае, если бумага была подделана или тем или иным образом испорчена.|n|nПодпись: Командир Метц, Серебряный Рассвет', },
    {'Доставьте 8 пар сапог из рунической ткани и соответствующее задание мастера караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли.', },
  },
  [9191] = {
    'Задание мастера: мешок из рунической ткани',
    {'Податель сего имеет право на получение награды в форме значков отличия по своему выбору в случае выполнения задания, указанного в контракте.|n|nЗаказ-наряд TR-9999:|n|n8 сумок из рунической ткани.|n|nВыполненные заказы доставлять караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли.|n|nКонтракт признается недействительным в случае, если бумага была подделана или тем или иным образом испорчена.|n|nПодпись: Командир Метц, Серебряный Рассвет', },
    {'Доставьте 8 сумок из рунической ткани и соответствующее задание мастера караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли.', },
  },
  [9192] = {
    'Беда в Беспросветных рудниках',
    {'Беспросветные рудники к юго-западу отсюда захвачены гноллами, зовущими себя кланом Черной Лапы. Мне не надо напоминать тебе, сколь стратегически важны эти рудники для нашей кампании в Призрачных землях!|n|nСтупай по южной дороге из города и на развилке возьми вправо. Прямо за зиккуратом справа будет короткая грунтовая тропа на запад. Иди по ней.|n|nКак увидишь кучи руды, знай – ты $Gпришел:пришла;.', },
    {'Убейте 8 гноллов-чернолапов, 6 падальщиков-чернолапов и 4 шаманов-чернолапов и возвращайтесь к стражу смерти Малтендису в Транквиллион в Призрачных землях.', },
  },
  [9193] = {
    'Обследуйте катакомбы Амани.',
    {'$C, наши разведчики доносят, что тролли, погребенные в катакомбах Амани под пиком Солнечного пастбища, восстали из мертвых. Госпожа Златилен хочет, чтобы ты $Gобследовал:обследовала; эти катакомбы и $Gсжег:сожгла; все останки, что пока еще не ожили. Ни одна из этих тварей не должна восстать их мертвых!|n|nБыстрее всего туда можно добраться по северной дороге из города, а затем на первой развилке свернуть направо. Так ты доберешься до северного склона пика, стало быть, вход ищи на юге.', },
    {'Обследуйте катакомбы Амани и сожгите 10 иссохших останков троллей, затем возвращайтесь к советнице Вальвин в Транквиллион в Призрачных землях.', },
  },
  [9194] = {
    'Задание мастера: одеяние из рунической ткани',
