  [11864] = {
    'Вступление',
    nil,
    nil,
  },
  [11865] = {
    'Им рано умирать',
    {'Используйте охапку искусственных шкур, чтобы поймать в ловушки 8 звероловов Эрнестуэя по просьбе Зазы из лагеря Д.Э.Г.О.Ж. в Борейской тундре.', },
    {'Используйте охапку искусственных шкур, чтобы поймать в ловушки 8 звероловов Эрнестуэя по просьбе Зазы из лагеря Д.Э.Г.О.Ж. в Борейской тундре.', },
  },
  [11866] = {
    'Уши мертвых врагов',
    {'Будь то искатели сокровищ или кровожадные охотники с пустошей, любые существа, поддерживающие Эрнестуэя и осмеливающиеся губить нашу драгоценную природу, объявляются врагами Д.Э.Г.О.Ж. Если вам случится убить кого-то из этих грязных прихвостней Эрнестуэя, принесите мне доказательства их смерти, и получите в награду благословение друидов Д.Э.Г.О.Ж.!', },
    {'Принесите верховному друиду Латориусу из лагеря Д.Э.Г.О.Ж. в Борейской тундре 15 ушей прихвостней Эрнестуэя и получите награду.', },
  },
  [11867] = {
    'Коллекция ушей',
    {'Будь то искатели сокровищ или кровожадные охотники с пустошей, любые существа, поддерживающие Эрнестуэя и осмеливающиеся губить нашу драгоценную природу, объявляются врагами Д.Э.Г.О.Ж. Если вам случится убить кого-то из этих грязных прихвостней Эрнестуэя, принесите мне доказательства их смерти и получите в награду благословение друидов Д.Э.Г.О.Ж.!', },
    {'Принесите верховному друиду Латориусу из лагеря Д.Э.Г.О.Ж. в Борейской тундре 15 ушей прихвостней Эрнестуэя и получите награду.', },
  },
  [11868] = {
    'Сортировщица грядет!',
    {'У южного края утеса – вот где ты найдешь коварного лидера охотников на карибу. Она – дикарка, каких поискать, издевается над телами убитых животных: пьет их кровь и воет потом на луну!|n|nНайдите эту убийцу – ее зовут Карина – и положи конец ее никчемному существованию.|n|nПодготовься как следует, $N. Карина Сортировщица купается в богатстве, которое Эрнестуэй щедро излил на нее! Она будет хорошо вооружена и с охраной из своих прихвостней.', },
    {'По заданию Заза из лагеря Д.Э.Г.О.Ж. в Борейской тундре убейте Карину Сортировщицу.', },
  },
  [11869] = {
    'Судьба моллюсков',
    {'К западу от нас находится озеро Кум\'уа. Это, насколько нам известно, единственный пресный водоем в мире, где обитают гигантские моллюски.|n|nКонечно, прихвостни Эрнестуэя занялись там культивированием жемчуга. Их нужно остановить! Тем, кто покушается на жизнь целого вида, нужно преподать урок.|n|nОтправляйся к озеру Кум\'уа и найди этих загребущих ловцов жемчуга. Убивай их, пока воды озера не покраснеют от крови! Возвращайся, когда покажешь им, где раки зимуют!', },
    {'По заданию иерофанта Сениуса из лагеря Д.Э.Г.О.Ж. в Борейской тундре убейте 10 загребущих ныряльщиков.', },
  },
  [11870] = {
    'Покинутый предел',
    {'Мы только что получили сообщение от Лиандры, что наемники, работающие на Эрнестуэя, переносят добро с берега на главный корабль Эрнестуэя. Несомненно, они рассчитывают разбогатеть на своем убийственном ремесле!|n|nЛиандра просит, чтобы мы отправили помощь в Покинутый предел, к югу отсюда, на побережье Борейской тундры.|n|nТоропись, Лиандра ждет тебя!', },
    {'Найдите иерофанта Лиандру в Покинутом пределе.', },
  },
  [11871] = {
    'Пока мы на страже',
    {'На берегу, среди обломков кораблекрушения, валяются ящики и мешки с частями тел животных. Похоже, Эрнестуэй в сговоре с флибустьерами Северных морей. Эти грязные пираты перевозят добычу, которую кровожадные прихвостни Эрнестуэя добывают на побережье. Несомненно, все это добро завершает свой путь на плечах не слишком щепетильных богатеев по всему Азероту!|n|nТак вот, не бывать этому! Во всяком случае, пока мы на страже! Принеси мне весь груз, какой найдешь на берегу. Они его не получат!', },
    {'Добудьте 12 партий частей тел животных по просьбе иерофанта Лиандры из Покинутого предела в Борейской тундре.', },
  },
  [11872] = {
    'Гнусный специалист по моллюскам',
    {'Убейте специалиста по моллюскам К и возвращайтесь к иерофанту Сениус в лагерь Д.Э.Г.О.Ж.', },
    {'Убейте специалиста по моллюскам К и возвращайтесь к иерофанту Сениус в лагерь Д.Э.Г.О.Ж.', },
  },
  [11873] = {
    'Новости для Выкрутеня',
    {'Не будешь ли ты так $Gлюбезен:любезна; отправиться на взлетную полосу и сообщить Выкрутеню, что я скоро появлюсь и доложу обо всем, как положено? Мой ветролет потерпел крушение, я прибуду, как только разберусь с этим.|n|nНе сомневайся, я позабочусь о том, чтобы Выкрутень знал, что я обязан тебе жизнью и спасением.|n|nХотел бы я знать, что сделал бы старик, если бы сам летел с нами, как в старые добрые времена. Мне его изрядно не достает...', },
    {'Вернитесь на взлетную полосу Выкрутеня и поговорите с Выкрутенем Разгоняйло.', },
  },
  [11874] = {
    'Upper Deck Promo – Верховая ракета',
    nil,
    nil,
  },
  [11875] = {
    'Обретение преимущества',
    nil,
    {'Принесите 8 горстей пыли Пустоты эмиссару Мордину в Шаттрат.', },
  },
  [11876] = {
    'Помоги тем, кто не может помочь себе сам',
    {'Какие величественные звери, правда?|n|n<Латориус указывает на мамонтов северной тундры.>|n|nДень ото дня их число уменьшается. Демоны, называющие себя охотниками, убивают их ради забавы и богатства.|n|n<Лицо Латориуса перекашивается от гнева.>|n|nА этот плач просто сводит меня с ума, $N. Эти звуки приносит ветер: к нам взывают малыши-мамонтенки, попавшие в жестокие ловушки охотников.|n|nВозьми этот молот и сокруши ловушки. Освободи детенышей!', },
    {'По заданию верховного друида Латориуса в лагере Д.Э.Г.О.Ж. в Борейской тундре освободите 8 мамонтят с помощью уничтожителя ловушек Д.Э.Г.О.Ж.', },
  },
  [11877] = {
    'Военные планы Ярости Солнца',
    {'Развивая наступление на Кель\'Данасе, мы обнаружили, что прихвостни Кель\'таса планируют контратаку. Отдав приказ эльфам крови Ярости Солнца, что базируются в Пустоверти, напасть на нашу операционную группировку в Запределье, он надеется, что мы отвлечемся от Солнечного Колодца и оттянем войска.|n|nМы не должны этого допустить, $N. На передовой каждый клинок драгоценен.|n|nОтправляйся в Пустоверть и захвати их военные планы. Они могут оказаться у любого эльфа крови Ярости Солнца. Удачи, $N.', },
    {'Лорд Торвос из Шаттрата хочет, чтобы вы захватили военные планы Ярости Солнца.', },
  },
  [11878] = {
    'Ку\'нок обо всем позаботится!',
    {'Ты $Gпомог:помогла; освободить детенышей, попавших в ловушку, но многие из них все равно погибнут. Понимаешь, оставшись без матери, эти детеныши вынуждены будут заботиться о себе сами.|n|nНо выход есть! У них остается надежда на спасение!|n|nК северу отсюда, на равнинах у берегов Жгучих прудов, пасется Ку\'нок Чудовище, древний и мудрый мамонт. Возьми этого осиротевшего детеныша и отведи его к Ку\'ноку. Он обо всем позаботится!', },
    {'Отведите мамонтенока-сиротку к Ку\'ноку Чудовищу в Борейской тундре.', },
  },
  [11879] = {
    'Кау Гроза Мамонтов',
    {'В одиночку тебе не удастся убить существо, виновное в гибели моих сородичей. Но мамонты из тундры помогут тебе!|n|nСтупай на равнины и найди там могучего самца мамонта. Он позволит тебе сесть на него верхом и управлять им.Он привезет тебя на север, в Гнездо Кау, где обитает Кау. Вместе вы сумеете покончить с этим чудовищем!|n|nИстреби воинство Кау и отбери у него его драгоценную боевую алебарду.|n|nЕсли одержишь победу – возвращайся к Латориусу в лагерь Д.Э.Г.О.Ж.', },
    {'Убейте Кау Грозу Мамонтов и добудьте боевую алебарду Кау. Доставьте ее верховному друиду Латориусу в лагерь Д.Э.Г.О.Ж. в Борейской тундре.', },
  },
  [11880] = {
    'Мультифазовый подход',
    {'Я уверен, что этот "гном-изобретатель" – чокнутый. Он все болтал о каких-то темных искажениях, что стали проявляться на Полях Духов вокруг Ошу\'гуна в Награнде.|n|nПо его словам эти, кхм, мультифазовые... кхм, спектрографические очки позволяют носителю видеть эти искажения и снимать с них данные. Он настаивал, что запись этих данных имеет фундаментальное значение для нашей кампании у Солнечного Колодца. Я думаю, он сумасшедший, но мне приказано исследовать все, что может помочь. Не хочешь ли провести считывание кое-каких данных?', },
    {'Предвестник Харонем из Шаттрата просит вас при помощи мультифазовых спектрографических очков 6 раз провести считывание мультифазовых данных.', },
  },
  [11881] = {
    'Ценный груз',
    {'Доводилось ли тебе видеть в небе ветролеты? Любопытнейшая гномская новинка!|n|nДавненько мне хотелось наложить лапу на эти машинки, и вот, наконец, представился удобный случай это сделать! Один из их разведывательных отрядов потерпел катастрофу у Жгучих прудов, в юго-западной части Поля гейзеров.|n|nСвистни в этот свисток у одной из разбившихся машин, и к тебе прибежит моя верная ослица Дженни. Она послушно пойдет за тобой следом и понесет на себе обломки, но тебе следует ее защищать. Если на нее нападут, она начнет ронять груз.', },
    {'Помогите ослице Дженни добраться с места крушения к Феззиксу Штукельверту в деревню Таунка\'ле, не растеряв груз.', },
  },
  [11882] = {
    'Игра с огнем',
    {'Хочешь научиться кое-чему новому?|n|nНе знаю, сумеешь ли ты когда-нибудь сравниться со мной в исскустве, но если будешь слушать внимательно, то пару-другую фокусов переймешь. Поговори с мастером-огнеглотателем в любой столице Альянса. Они тебя научат.', },
    {'Поговорите с мастером-огнеглотателем в любой из столиц Альянса.', },
  },
  [11883] = {
    'Танцы с огнем?',
    {'Хочешь научиться танцевать с огнем?|n|nЧто же, хорошо. Поговори с мастером огненного танца в любой из столиц Орды. Они тебе помогут.', },
    {'Поговорите с мастером огненного танца в любой из столиц Орды.', },
  },
  [11884] = {
    'Нед, "Повелитель люторогов"',
    {'К западу отсюда, на высоких утесах над озером Кум\'уа, обитает презренное создание, известное под именем Недар. Самозваный "Повелитель люторогов" охотится в пустошах на раненых и молодых животных – люторогов, неспособных защититься от трусливых атак Неда. Чтобы добавить оскорбительности к истреблению, Нед взрастил своего собственного люторога, который служит ему и как ездовое животное, и как телохранитель.|n|nБольшая редкость – чтобы от Д.Э.Г.О.Ж. исходил призыв к смерти животного, но с порченым люторогом просто необходимо разобраться... Убей обоих и возвращайся ко мне.', },
    {'По заданию Киллинджера Смотрителя Логова из лагеря Д.Э.Г.О.Ж. в Борейской тундре убейте Недара, "Повелителя люторогов", и его спутника, люторога по кличке "Закуска".', },
  },
  [11885] = {
    'Кровные враги',
    {'Потомки, которых держат в плену жрецы когтя из Скеттиса, упомянуты в этой книге: Охотница Геззарак, хрустальный гигант Каррог, еретик по имени Темный Крикун Аккарай и Ваккиз Ветрояр. Для того чтобы Терокк вернулся в этот мир, нужно будет убить их всех.|n|nДля этого тебе потребуются свитки затерянных во времени араккоа – с помощью свитков ты сможешь призвать потомков в кругах призыва в Скеттисе. Принеси мне какую-нибудь вещь от каждого из них, но помни, что все они очень сильны, и лучше бы тебе позвать с собой друзей.', },
    {'Найдите груды черепов в середине кругов призыва Скеттиса. С помощью 10 свитков затерянных во времени призовите каждого потомка Скеттиса, уничтожьте их и отнесите трофеи Хаззику в лагерь Черного Ветра.', },
  },
  [11886] = {
    'Необычная активность',
    {'Как говорится, потехе свой час, |3-6($C), но и делу время.|n|nКогда начался праздник, мы получили донесение с Зорамского взморья по поводу резкого усиления активности культа Сумеречного Молота. История праздника восходит к тем самым силам, которым эти безумцы поклоняются, так что это не совпадение. Отправляйся ко входу в Непроглядную Пучину – прямо к югу от него лежат руины. Посмотри, не сможешь ли ты получить какую информацию от этих фанатиков. Если понадобится – выбей ее силой. Когда понадобится помощь проводника, воспользуйся этим маячком.', },
    {'Отправляйтесь в новый лагерь культа Сумеречного Молота к югу от входа в Непроглядную Пучину на Зорамском взморье, что в Ясеневом лесу, и добудьте сумеречную корреспонденцию, затем при помощи тотема-маяка свяжитесь с проводником из Служителей Земли.', },
  },
  [11887] = {
    'Неприкосновенный запас',
    {'Роясь в вещах убитого гнома, вы находите небольшой мешок с припасами, инструментами и удобным рулончиком гномской клейкой ленты. Возможно, этот мешок пригодится Феззиксу Штукельверту, когда придется собирать из обломков гномские ветролеты.|n|nЕсли принести Феззиксу несколько таких мешков, можно получить приличную награду!', },
    {'Соберите 7 гномских ремонтных наборов с тел погибших пилотов-разведчиков со станции Выкрутеня и принесите их Феззиксу Штукельверту в деревню Таунка\'ле.', },
  },
  [11888] = {
    'Поездка в деревню Таунка\'ле',
    {'$R, вождь заставляет меня ждать... Время – это то, чего у Таунка\'ле нет!|n|nО твоем мастерстве ходят слухи. Чем ждать, пока Гаррош пошлет подкрепление, лучше я попрошу тебя пойти и помочь моим соплеменникам.|n|nДеревня Таунка\'ле находится далеко на северо-восток отсюда. Езжай по дороге на восток от крепости, поверни на север на перепутье. Немного погодя ты наткнешься на еще одно перепутье. Следуй по пути на восток, пройдя к югу, а затем к востоку от больших прудов вдоль Затопленных равнин.|n|nКогда прибудешь в деревню, поговори с ведуном земли и неба.', },
    {'Поговорите с ведуном земли и неба в деревне Таунка\'ле.', },
  },
  [11889] = {
    'Смерть с небес',
    {'Мы неплохо держимся на передовых линиях против этих жуков. Правда, кое-кто из этих нахальных тварей может перелетать те самые передовые линии, и они сильно терзают наши внутренние оборонительные порядки.|n|nЯ реквизировал укрепленные рыболовецкие сети с наших гражданских кораблей. Если руки у тебя приспособлены для метания, с помощью этих сетей можно сдернуть врагов с неба. Нужно уменьшить их количество, чтобы наши силы сумели удержать крепость.', },
    {'По поручению сержанта Молотогора убейте вне стен крепости Отваги 6 порабощенных Плетью изрыгателей огня с помощью укрепленной сети.', },
  },
  [11890] = {
    'Что там с ними?',
    {'У гномов на прудах к западу отсюда возникли какие-то проблемы. Поделом им, конечно, ведь они всю землю уже изгадили своими так называемыми изобретениями.|n|nЯ хочу, чтобы ты $Gотправился:отправилась; к их насосной станции и $Gразузнал:разузнала;, что ж там с ними приключилось. А потом возвращайся, расскажешь.', },
    {'Исследуйте область вокруг насосной станции Выкрутеня, а затем возвращайтесь к ведуну земли и неба в деревню Таунка\'ле.', },
  },
  [11891] = {
    'Невинный маскарад',
    {'Судя по всему, похоже, что к северо-западу от большого скопления служителей культа на Зорамском взморье есть еще один их лагерь, и они разговаривают... с гостями?|n|nЕсли подслушать эти разговоры. то многое можно узнать, |3-6($R). Возьми эту сферу. Она поможет тебе принять вид одного из крабов, которых полно на побережье. Подслушай разговоры служителей культа с этими "гостями" в северо-западном лагере и, если все пройдет удачно, вернись ко мне и расскажи, что удалось узнать.', },
    {'При помощи сферы Краба проникните в новый Сумеречный лагерь к западу от входа в Непроглядную Пучину на Зорамском взморье в Ясеневом лесу, затем вызовите проводника из Служителей Земли при помощи тотема-маяка.', },
  },
  [11892] = {
    'Убить Гарольда Лейна!',
    {'Ты много $Gсделал:сделала; для животных Борейской тундры, $N. Тебе удалось как следует отделать прихвостней Эрнестуэя и преподать им урок, который они нескоро забудут.|n|nГарольд Лейн, в наибольшей степени ответственный за массовую бойню в Награнде, оказался тем же человеком, что отвечает за операции Эрнестуэя в тундре. Он расположился у озера Кум\'уа, к западу отсюда.|n|n<Латориус передает вам покрытый причудливой резьбой дубовый рог.>|n|nНайди Лейна и убей его. Если понадобится наша помощь – труби в рог.', },
    {'По поручению верховного друида Латориуса из лагеря Д.Э.Г.О.Ж. в Борейской тундре убейте Гарольда Лейна.', },
  },
  [11893] = {
    'Сила стихий',
    {'Я все пытаюсь объяснить этому глупому гоблину, что его машины ненадежны.|n|nВот сила стихий – дело другое! И когда мое ученичество окончится, я овладею всей их мощью. Однако и того, что я уже знаю, будет достаточно, чтобы помочь нашему другу Феззиксу.|n|nВозьми этот тотем духа ветра и установи его вблизи одного из паровых яростней к западу от деревни. Тотем вберет в себя энергию убитых элементалей. Вернись ко мне с заряженным тотемом, остальное я беру на себя.', },
    {'Дорейн Морозное Копыто из деревни Таунка\'ле просит вас использовать тотем духа ветра, чтобы собрать энергию 10 паровых яростней.', },
  },
  [11894] = {
    'Заплатки',
    {'Помнишь ту клейкую ленту, что ты мне $Gпритащил:притащила;?|n|nНу вот, я нашел ей применение. Корпус этого ветролета пробит в стольких местах, что мне нужно обязательно укрепить его, если я хочу хоть когда-нибудь на нем полететь.|n|nДорейн – вон он, там стоит, – сказал мне, что таунка используют для изготовления водонепроницаемых контейнеров пропаренную кожу карибу. Болотные карибу тут в округе, возле деревни, повсюду живут, да и на Затопленных равнинах их хватает. Найди наилучшие шкуры и выделай их над паром на Полях гейзеров.', },
    {'Принесите 5 пропаренных шкур Феззиксу Штукельверту в деревню Таунка\'ле.', },
  },
  [11895] = {
    'Одолеть бурю',
    {'Из твоего описания следует, что с этими металлическими созданиями несложно будет справиться. Но сначала тебе нужно справиться с бурей.|n|nПозади меня на гряде есть тотем. Когда будешь $Gготов:готова;, сосредоточь на нем свою волю – и грянет шторм. Ты $Gдолжен:должна; одолеть шторм и таким образом вобрать в себя его сущность.|n|nЕсли там есть еще кто-нибудь, можете сражаться сообща, этого достаточно. А потом, |3-6($C), возвращайся ко мне.', },
    {'Одолейте порыв шторма, затем возвращайтесь к ведуну земли и неба в деревне Таунка\'ле.', },
  },
  [11896] = {
    'Уязвимы для молний',
    {'Ты теперь носишь в себе ярость шторма! Я научу тебя концентрировать эту силу, чтобы выводить из строя роботов в прудах.|n|nВот, возьми этот молниевый жезл. Используй его против роботов механогномов, которых найдешь среди прудов на западе. Против самих механогномов использовать его не трудись – у Великой матери Тайги другие планы на их счет.|n|nА когда сила бури ослабит роботов, разбери их полностью!', },
    {'Уничтожьте 15 любых роботов, кроме механогномов, ослабленных воздействием ярости шторма, в области прудов вокруг насосной станции Выкрутеня.|n|nПосле этого вернитесь к ведуну земли и неба в деревне Таунка\'ле.', },
  },
  [11897] = {
    'Заткнуть воронки!',
    {'Силы Плети и не собираются отступать, $N. Эти проклятые воронки: они соединены с туннелями на всем пути к леднику Ледяной Короны, насколько нам известно.|n|nЕсли годы занятий горным делами меня чему и научили, так это тому, что без опорных балок туннели легко обвалятся после взрыва.|n|nВозьми эту взрывчатку и установи заряды у входов в воронки на хребте над побережьем, к западу отсюда. Возвращайся, когда обвалишь туннели.', },
    {'По поручению сержанта Молотогора используйте зажигательную взрывчатку, чтобы взорвать и обвалить воронки к юго-западу и северо-западу от крепости Отваги.', },
  },
  [11898] = {
    'Прорыв',
    {'В нижнем ярусе Храмового города находится серый алтарь, окутанный светом. Ступи на него, и ты войдешь в некрополь Наксанар.|n|nНо будь осторожнее, $N! Принца Валанара наверняка обороняют его личные вассалы, которые готовы отдать жизнь ради того, чтобы не дать тебе взойти на вершину некрополя.|n|nТебе нужно пробраться через некрополь к трону принца. Если ты не сумеешь одолеть его, $N, боюсь, моему народу никогда не удастся укрыться в надежных стенах Ледяной Пыли...', },
    {'Одолейте принца Валанара с его подручными, Вантрином Безжалостным и Лютионом Злобным, потом явитесь к вождю Зимней Стуже в деревне Таунка\'ле.', },
  },
  [11899] = {
    'Души распроклятых',
    {'Мехагномы, живущие в прудах к западу отсюда, представляют для нас крупную загадку. Они появились там вскоре после того, как с насосной станции и из ее окрестностей исчезли гномы.|n|nОни неестественны и опасны, с ними необходимо разобраться.|n|nВозьми этот Ловец Душ и используй его на останках мехагномов, чтобы взять их души в плен. Когда ты вернешься, мы выпустим их на волю и посмотрим, что будет.', },
    {'Используйте ловца душ Великой Матери, чтобы захватить души 10 мехагномов со станции Выкрутеня. Затем вернитесь к Великой Матери Тайге в деревне Таунка\'ле.', },
  },
  [11900] = {
    'Что показывают приборы?',
    {'Я надеялся, что влияние Нексуса ограничивается этой местностью. Но недавно пошли сообщения со всего Азерота, что геологическая нестабильность растет лавинообразно!|n|nМне нужно постоянно наблюдать за Нексусом, поскольку я работаю над решением. |n|nЯ разместил в Хладарре чувствительные инструменты, замаскировав их под гадальные шары Малигоса. Один лежит во рве рядом с Нексусом, а еще три спрятаны в разных структурах по периметру долины. Посети все четыре места и принеси мне данные их измерений.', },
    {'По просьбе верховного мага Беринанда из лагеря под Маскировочным щитом соберите показания его приборов в Хладарре.', },
  },
  [11901] = {
    'Военные? Какие военные?',
    {'Плеть повсюду, |3-6($C). Мы организовали ополчение из фермеров и шахтеров, но ему не справиться.|n|nЕдинственное воинское подразделение, присланное из Крепости Отваги, защищает шахту. Мы о них уже несколько дней никаких вестей не получали!|n|nЕсли ты, правда, хочешь нам помочь, не сходишь ли на шахту – посмотреть, что там творится? Может быть, они смогут прислать нам хотя бы небольшое подкрепление.', },
    {'По просьбе Джеральда Грина из Далечья отправляйтесь на север, в шахту, и выясните, что случилось с направленным туда воинским подразделением.', },
  },
  [11902] = {
    'Ужасное свидетельство',
    {'Мешки с зерном издают жуткое зловоние, которое наводит вас на мысли о Чуме. Вероятно, это объясняет, что случилось с пехотинцами, защищавшими рудник.|n|nЛучше бы сообщить об этом Джеральду Грину.', },
    {'Вернитесь к Джеральду Грину в Далечье.', },
  },
  [11903] = {
    'Время действовать!',
    {'Итак, $N. Теперь, когда наши последние бойцы в Далечье или погибли, или их постигла еще худшая участь, нам остается только одно: самим сразиться с Плетью.|n|nМы развернули ополчение в том, что осталось от Далечья. Без твоей помощи у них практически нет надежды на победу. Иди и протяни им руку помощи. А я с ребятами останусь наблюдать за тропой. Мы не можем позволить Плети прорваться!', },
    {'По просьбе Джеральда Грина из Далечья убейте 14 чумных падальщиков.', },
  },
  [11904] = {
    'Плоды трудов наших',
    {'Силы плети все прибывают... но мы не можем сдаться! Послушай, $N. В этой шахте осталась одна повозка с последней порцией руды, которую Альянс теперь долго не увидит на этой стороне континента.|n|nПроблема в том, что пусковой механизм повозки заблокирован. Когда сюда пришли военные, капитан Якобс реквизировал все важное оборудование, включая и ключ от повозки.|n|nЧума, поразившая всех солдат в шахте, должно быть, сразила и Якобса. Добудь у него ключ и спаси груз руды.', },
    {'Отправляйтесь на шахту Далечья, добудьте ключ от повозки у капитана Якобса и используйте его для того, чтобы пустить повозку с рудой. По завершении задания вернитесь к Джеральду Грину в Далечье.', },
  },
  [11905] = {
    'Оттянуть неотвратимое',
    {'Я определил причину нестабильности!|n|nСиловые линии Азерота перенаправлены на Нексус. Потрясающе! Если бы я мог провести остаток своих дней, исследуя эту аномалию…|n|nУвы, придется заняться текущими проблемами. Поток магической энергии расширяет разлом между измерениями.|n|nВ глубине Нексуса творится то, из-за чего ткань нашей вселенной истончается. Остановить это я не могу, однако нашел способ замедлить это.|n|nОтнеси это в Нексус и активируй поблизости от формирующегося разлома.', },
    {'Используйте восстановитель измерений вблизи разлома в Нексусе по просьбе верховного мага Беринарда из лагеря под Маскировочным щитом.', },
  },
  [11906] = {
    'Очищение прудов',
    {'<По лицу Стальных Глаз скатывается слеза.>|n|nЯ знаю, ты направляешься обратно к прудам, что на западе. Раз уж ты все равно там будешь, у меня есть для тебя поручение.|n|nГномы, которых не волнует судьба земли, загрязнили ее своей техникой. Я прошу тебя собрать валяющиеся на земле запчасти.|n|nПринеси их мне сюда. Я позабочусь о том, чтобы они были утилизованы должным образом прежде, чем мы уйдем отсюда навсегда.', },
    {'Соберите 15 запасных деталей Выкрутеня и доставьте их Стальным Глазам в деревню Таунка\'ле.', },
  },
  [11907] = {
    'Подручные Механозода',
    {'Известно, что у механизатора Механозода имеется четверо подручных, которые управляют роботами в прудах.|n|nИх необходимо уничтожить!|n|nНаши выносливые гонцы и снежные следопыты говорят, что, если открыть клапаны на Западной, Северной, Центральной и Южной станциях, то эти подручные тут же явятся, чтобы устранить помеху в работе.|n|nСтанции расположены вокруг вращающихся маячков в прудах вокруг насосной станции.|n|nТоропись, $N!', },
    {'Уничтожьте Шатунишку, ЕД-210, Макса Шмякса и Шлифовальщика, затем вернитесь к Ведуну земли и неба в деревню Таунка\'ле.', },
  },
  [11908] = {
    'Справочные материалы',
    {'Я ведал уборочными големами – это была ответственная работа, пока Плеть не разорила большинство наших пахотных земель. У меня, впрочем, есть идея, как снова сделать големов полезными.|n|nЯ думаю, что могу переделать схему сборщиков урожая так, чтобы они помогли нам в войне с Плетью.|n|nЯ еще не большой специалист в этом, так что мне потребуется сверяться с руководством. Проблема в том, что я оставил его в мастерской... а моя мастерская, к несчастью, – вон то горящее здание рядом с шахтой. Как думаешь, удастся тебе вытащить оттуда руководство?', },
    {'По просьбе Иеремии Хоунинга вынесите книгу "Поля, заводы и мастерские" из горящего здания рядом с рудником Далечья.', },
  },
  [11909] = {
    'Убить механизатора!',
    {'Ясно, что этот механизатор Механозод не в своем уме. Если его идея исцеления и бессмертия состоит в том, чтобы все мы стали роботоподобными рабами, то его нужно остановить!|n|nВетра, что ведут меня, шепчут, что он находится на вершине насосной станции в центре прудов к западу отсюда.|n|nСкорее всего, его можно будет найти в лачуге на самом верху постройки. Войди туда и исследуй его труды.|n|n$N, тебе нужно сразиться с Мехазодом, если все мы хотим жить!', },
    {'Изучите Руководство механизатора и принесите голову Механозода Великой матери Тайге в деревню Таунка\'ле.', },
  },
  [11910] = {
    'Тайны Древних',
    {'Постепенно становится ясно, что нестабильность в этой местности оказывает воздействие и на обитающих тут существ.|n|nЯ особо заинтересовался ледовыми древами и их недавними изменениями. Подозреваю, что их трансформация в зачарованные древа поможет нам разобраться в наших затруднениях.|n|nДля моих исследований мне нужны образцы и с тех, и с других. Поторопись...', },
    {'По просьбе верховного мага Беринарда из-под Маскировочного щита принесите 3 ледяных осколка и 3 щепки зачарованного древа, собранных с древ в Хладарре.', },
  },
  [11911] = {
    'Преображение',
    {'Хотя мы, может быть, стоим на пороге прекращения нашего существования, я не перестаю изумляться. За короткое время, проведенное здесь, я узнал больше, чем за десятилетия исследований.|n|nЭти древа постоянно находятся под воздействием магической энергии. Она буквально на глазах превращает их в нечто... иное.|n|nЯ уверен, что это еще одна ступень их трансформации. Я хочу, чтобы ты $Gотправился:отправилась; прямо в Нексус и $Gнашел:нашла; какие-нибудь свидетельства об их конечном состоянии.|n|nПожалуйста, будь осторожнее...', },
    {'По заданию верховного мага Беринанда из лагеря под Маскировочным щитом отправьтесь в Нексус и соберите 5 магических обломков кристаллических заступников.', },
  },
  [11912] = {
    'На подножном корму',
    {'О! Как приятно в кои-то веки увидеть новое лицо! А то уже такое ощущение, будто мы тут вообще отрезаны от мира.|n|nВо всяком случае от снабжения мы уже несколько дней как отрезаны, так что перспективы у нас, скажем так, мрачноватые. По правде говоря, мы с самого начала шли на верную смерть, если хочешь знать.|n|nА может, это просто не по мне, все это насилие, убийства – не говоря уже о здешних холодах! Эх, сидеть бы сейчас в Даларане, изучать древние тексты...|n|nНо ближе к делу. Наши припасы на исходе. Пожалуйста, постарайся раздобыть какой-нибудь пищи и принеси ее мне!', },
    {'Соберите 10 ягод снежевики с кустов снежевики в Хладарре по просьбе библиотекаря Серры из лагеря под Маскировочным щитом.', },
  },
  [11913] = {
    'Надо действовать наверняка',
    {'Я слышала, что ты $Gсказал:сказала; Джеральду, и мне это совсем не нравится. Если сектантам удалось отравить зерно в шахте этой своей чумой, они с легкостью могли отравить зерно и снаружи.|n|nУ нас нет времени перебирать зерно, отделяя хорошее от зараженного. Нужно действовать быстро, и придется сжечь все.|n|nВозьми этот факел и сожги все мешки с зерном, какие найдешь. Будет настоящей трагедией, если мы переживем эту атаку только для того, чтобы стать жертвами чумы...', },
    {'По просьбе Венди Даррен сожгите 8 мешков с зерном Далечья, воспользовавшись факелом Венди.', },
  },
  [11914] = {
    'Сохранение секретности',
    {'Само наше существование здесь зависит от нашей скрытности. Если щит падет, даже на мгновение, приспешники Малигоса будут тут как тут.|n|nОдной из моих обязанностей является возобновление и восполнение маны у военных магов, чтобы не ослабела их сосредоточенность. Поскольку мы отрезаны от поставок, мне приходится импровизировать.|n|nТы можешь помочь мне, $N.|n|nСовсем рядом с Нексусом среди потоков магической энергии плавают волшебные змеи. Сраженный змей выделяет субстанцию маны, которая может мне пригодиться.', },
    {'По просьбе библиотекаря Серры убейте волшебных змеев и принесите за Маскировочный щит 5 субстанций маны Нексуса.', },
  },
  [11915] = {
    'Игра с огнем',
    {'Хочешь научиться кое-чему новому?|n|nНе знаю, сумеешь ли ты когда-нибудь сравниться со мной в исскустве, но если будешь слушать внимательно, то пару-другую фокусов переймешь. Поговори с мастером-пламеглотателем в любой столице Орды. Они тебя научат.', },
    {'Поговорите с мастером-пламеглотателем в любой из столиц Орды.', },
  },
  [11916] = {
    'Воин Адского Крика',
    {'Ты встречаешь опасности лицом к лицу и сокрушаешь их железной рукой. Именно благодаря тебе, $N, Орда теперь надежно закрепилась в Нордсколе.|n|nНо наши труды здесь только начинаются. Наш путь лежит к Ледяной Короне! Мы должны сокрушить ее стены!|n|nСейчас же тебе следует отправиться на восток, в деревню Таунка\'ле. У наших союзников (таунка) большие неприятности, им нужна помощь. Добудь себе средство передвижения у Дуркота Брата Волка, смотрителя стойл. В Таунка\'ле отыщи вождя Зимнюю Стужу.', },
    {'Отыщите вождя Зимнюю Стужу в деревне Таунка\'ле.', },
  },
  [11917] = {
    'Ответный удар',
    {'Мы должны действовать! Мы должны сохранить равновесие. Время против нас.|n|nВозвращайся в лагерь на Зорамское взморье с большими Камнями Льда. Они пользуются ими для связи с элементалями, как в Силитусе. Хотя мне ужасно не хочется этого делать, но духи поймут – тебе придется вызвать одного из помощников Ахуна и уничтожить его. Возможно, этого упреждающего удара будет достаточно...', },
    {'Убейте лейтенанта Хладоволна, помощника Ахуна, вызвав его при помощи Камня Льда на Зорамском взморье в Ясеневом лесу, затем вернитесь к старейшине Служителей Земли в столицу.', },
  },
  [11918] = {
    'Первое знакомство',
    {'Это война, $Gсмертный:смертная;, и мы – в гуще схватки!|n|nВаши мелкие свары из-за земель или денег бледнеют перед этим конфликтом. Нас ждет встреча с Аспектом Малигосом и его синими драконами. Тебе достаточно знать, что, если Малигос одержит победу, этого мира больше не будет.|n|nНас тут мало, и мы сражаемся против многих. Можно считать, что мы обречены, и, если нам удастся хотя бы задержать врага, это уже будет успех.|n|nСтупай же. Найди себе какое-нибудь дело, пока я решу, что делать с тобой.', },
    {'Убейте 10 чароплетов Хладарры по просьбе Релораза из лагеря под Маскировочным щитом.', },
  },
  [11919] = {
    'Охота на драконов',
    {'Синие начали наносить на своих драконов таинственные руны. Я должен выяснить их значение.|n|n<Релораз протыкает руку копьем и смазывает кровью наконечник.>|n|nВозьми это копье и воздействуй им на одного из них. Подожди, пока он не подчинится, а затем принеси мне, пока не кончится действие крови.|n|nИх детеныши кормятся на северо-западном крае долины.', },
    {'По просьбе Релораза используйте копье с окровавленным наконечником, чтобы подчинить детеныша дракона Нексуса, а затем принесите Релоразу копье назад за Маскировочный щит.', },
  },
  [11920] = {
    'Сектанты среди нас',
    {'На этом алтаре полным-полно знаков Культа Проклятых. Похоже, фанатики с материка добрались уже и до Нордскола. Благоразумие требует сообщить об этом капитану корабля.|n|nВероятно, его можно найти на палубе.', },
    {'Поговорите с капитаном "Левшой" Люггером на "Рассекателе туч" в Крепости Отваги.', },
  },
  [11921] = {
    'Опять бросаем факелы',
    {'Привет, $Gфакельный жонглер:факельная циркачка;! Нравится устраивать огненную неразбериху? Приятно слышать! Думаешь, ты так уж и $Gкрут:крута;?Давай проверим...|n|nПравила ты знаешь: бросаешь факел в отмеченные жаровни. Но на сей раз у тебя больше времени и НАМНОГО больше жаровен.|n|n$GГотов:Готова;?', },
    {'Выиграйте игру в бросание факелов, затем поговорите с мастером-огнеглотателем.', },
  },
  [11922] = {
    'Жонглирование факелами',
    {'Значит, ты хочешь научиться жонглировать горящими факелами? А у тебя есть необходимые для этого качества? Ловкость? Быстрота? Отвага? Если ты думаешь, что да, то давай попрактикуемся немного!|n|nБери эти факелы и беги к костру. Над ним увидишь жаровни, с горящими метками. Бросай факелы в отмеченные жаровни. И делать это надо быстро! До того, как метка погаснет, если хочешь получить очко за попадание!|n|nПопади в достаточное количество отмеченных жаровен прежде, чем выйдет время, затем возвращайся назад... для следующего урока.', },
    {'Выиграйте игру в бросание факелов, затем поговорите с мастером-пламеглотателем.', },
  },
  [11923] = {
    'Поймай факел!',
    {'Ну, факел ты теперь бросать умеешь, так посмотри, сможешь ли ты его еще и поймать!|n|nБери эту связку незажженных факелов. Ступай к костру и подбрось факел высоко в воздух. Поймай его прежде, чем он коснется земли... затем снова подбрось его в воздух! Поймай четыре факела подряд, затем возвращайся ко мне.|n|nОсторожнее! Они опасны при ударе о землю! И не пропусти ни одного! Если пропустишь, придется вернуться к костру и начать все с начала. Удачи!', },
    {'Поймайте подряд 4 факела, затем поговорите с мастером-пламеглотателем.', },
  },
  [11924] = {
    'Опять жонглирование факелами',
    {'Небось, жонглируя факелами приходится держаться начеку? Как думаешь, долго продержишься?|n|nПосмотрим-ка...', },
    {'Поймайте 10 факелов подряд, затем поговорите с мастером-огнеглотателем.', },
  },
  [11925] = {
    'Опять жонглирование факелами',
    {'Небось, жонглируя факелами приходится держаться начеку? Как думаешь, долго продержишься?|n|nПосмотрим-ка...', },
    {'Поймайте 10 факелов подряд, затем поговорите с мастером-пламеглотателем.', },
  },
  [11926] = {
    'Опять бросаем факелы',
    nil,
    {'Выиграйте игру в бросание факелов, затем поговорите с мастером-пламеглотателем.', },
  },
  [11927] = {
    'Встреча в трактире',
    {'Эй, $N! Тут одна девушка в таверне о тебе спрашивала. Ее зовут Лерисса.|n|nНет, не думаю, что она знакома с тобой, но сказала, что ей нужна твоя помощь. Судя по всему, она просто в отчаянии.', },
    {'Найдите Лериссу в таверне в крепости Отваги.', },
  },
  [11928] = {
    'Далечье',
    {'Мои ребята сумеют продолжить с этого места, $N. Крепость Отваги построена так, чтобы выдержать неприятности и покруче этой. Я беспокоюсь только о наших пахотных землях и шахте в Далечье.|n|nМы послали целый отряд для защиты наших горняков прямо перед вторжением – должно быть, они сумеют защитить гражданское население.|n|nТамошними селянами руководит Джеральд Грин. Проход через северную стену крепости Отваги выведет тебя прямо к нему. Узнай, чем ты можешь ему помочь.', },
    {'Отправляйтесь в Далечье в Борейской Тундре и поговорите с Джеральдом Грином.', },
  },
  [11929] = {
    'Гибель деревни Таунка\'ле',
    {'Для нас все потеряно, $N. Это место было нашим домом долгие поколения, но теперь здесь слишком опасно. Здесь царит смерть... Смерть и память о том, что когда-то было.|n|nЯ призвал к бегству из Таунка\'ле. Все оставшиеся в живых таунка должны покинуть деревню вместе и направиться в нашу столицу, Ледяную Пыль, расположенную на Драконьем Погосте.|n|n<Зимняя Стужа указывает на восток.>|n|nТы $Gдолжен:должна; помочь моим соплеменникам добраться в безопасное место, $N. Мать Тауранук ждет тебя у ворот деревни. Скорее! Силы Плети приближаются со всех сторон!', },
    {'Поговорите с матерью Тауранук у ворот деревни Таунка\'ле.', },
  },
  [11930] = {
    'Через Трансборею',
    {'Проводите эвакуированных жителей Таунка\'ле через Трансборею на границу Драконьего Погоста, где их ждет Вартук Дитя Льда.', },
    {'Проводите эвакуированных жителей Таунка\'ле через Трансборею на границу Драконьего Погоста, где их ждет Вартук Дитя Льда.', },
  },
  [11931] = {
    'Взломать шифр',
    {'Я чувствую определенную странность в здешних драконах, но значение рун, нанесенных на их тела, по-прежнему ускользает от меня.|n|nБез кодекса их интерпретация займет слишком много времени.|n|nНедалеко отсюда обитает один предатель ордена Кирин-Тор, Калерас, у которого, вероятно, есть экземпляр той книги, что мне нужна. У его приспешников есть руны, которые мне понадобятся для расшифровки.|n|nПоторопись, $Gсмертный:смертная;. С каждым мгновением сила Малигоса прибывает.', },
    {'Добудьте Лазурный кодекс у инквизитора Калераса и 3 мерцающих руны у его чародеев Хладарры и отнесите Релоразу за Маскировочный щит.', },
  },
  [11932] = {
    'Дураки и трусы',
    {'Послушай меня, $N. Не хочу никого обидеть, но операция, во главе которой поставили Тассариана, была чистым самоубийством!|n|nГорстке наших бойцов было поручено атаковать самое крупное объединение Плети в этом регионе!|n|nМожет, я и идиот, но, на мой взгляд, штурмовать зиккурат Плети рядом с зачумленным нерубским городом с отрядом в десяток бойцов – это даже не смешно.|n|nЕсли ты все еще хочешь отыскать Тассариана, можешь отправиться на восток к клыкарру по имени Атаика. Он живет в Каскале, на северо-востоке. Ну, удачи тебе в твоем безумном предприятии!', },
    {'Поговорить с Атаикой в Каскале, к северо-востоку от крепости Отваги.', },
  },
  [11933] = {
    'Похищение пламени Экзодара',
    {'Этот пламень, похищенный самого сердца Экзодара, омывает вас теплом. Эта неукротимая сила незнакома вам, но Праздничный сказитель должен знать больше...', },
    {'Верните Пламя Экзодара Праздничному сказителю.', },
  },
  [11935] = {
    'Похищение пламени Луносвета',
    {'Этот пламень, похищенный из Луносвета, омывает вас теплом. Эта неукротимая сила незнакома вам, но хранитель мудрости Празднества должен знать больше...', },
    {'Верните пламя Луносвета хранителю мудрости Праздника.', },
  },
  [11936] = {
    'Наклевывается план!',
    {'Наши цели в здешних краях просты. Надо скрываться от Малигоса, наблюдать за его отпрысками и мешать ему, чем только сумеем.|n|nВот это-то я и хочу поручить тебе.|n|nСиние драконы откладывают яйца у подножия Нексуса. Под влиянием столь мощной магической энергии яйца проклюнутся быстрее, и неизвестно, как это скажется на детенышах драконов.|n|nЧестно говоря, я и не стремлюсь это проверять. Перебей местных драконидов и используй их застывшие топоры, чтобы разбить яйца.', },
    {'Убейте драконидов из Хладарры и используйте их застывшие топоры, чтобы разбить 5 яиц синих драконов по просьбе Релораза из лагеря под Маскировочным щитом.', },
  },
  [11937] = {
    'УКАЗАТЕЛЬ – все факелы возвращены, задание выполнено',
    nil,
    nil,
  },
  [11938] = {
    'Отвлечь противника',
    {'Теперь, когда у нас есть этот талисман, мне не составит труда раздобыть необходимые сведения. Однако Плеть в Храмовом городе скоро обнаружит, что что-то не так.|n|nОтразить полномасштабную атаку я не сумею. А может, и сумею… но проверять не хочется!|n|nПопробуй пробраться туда и организовать несколько несчастных случаев. Есть надежда, что это их отвлечет, и эти двое успеют расколоться... нет, естественно, в переносном смысле! Возьми с собой Лурида, он тебе пригодится.', },
    {'Подстройте 20 несчастных случаев, в которых пострадает Плеть в Храмовом городе Эн\'кила, по просьбе Тассариана из Стонущего зиккурата в Борейской тундре. Используйте кости Лурида, если вам понадобится помощь.', },
  },
  [11939] = {
    nil,
    {'[PH]Задание, завершающее эту серию заданий – вызвать и убить взрослого дракона (элитного?) – бой с драконом в подземелье?', },
    nil,
  },
  [11940] = {
    'Охота на драконов',
    {'Мне нужно больше детенышей драконов, чтобы продолжить исследовать руны, покрывающие их тела.|n|nИх можно найти у северо-западного края долины…|n|n<Релораз прокалывает копьем руку и смазывает наконечник своей кровью.>|n|nВот, возьми копье и воздействуй им на одного из детенышей, пока не подчинишь его. А потом принеси его мне, пока кровь еще действует.', },
    {'По просьбе Релораза используйте копье с окровавленным наконечником, чтобы подчинить детеныша дракона Нексуса, а затем принесите ему копье за Маскировочный щит.', },
  },
  [11941] = {
    'Загадочный обломок',
    {'В этом металлическом обломке есть что-то, что не позволяет вам выбросить его.|n|nБыть может, Релораз сможет пролить свет на его назначение.', },
    {'Принесите искрометный обломок Релоразу за Маскировочный щит.', },
  },
  [11942] = {
    'Слова могущества',
    {'Так сказал лич, $N. Тайну входа в Наксанар хранят верховные жрецы из Эн\'кила.|n|nОтправляйся к Шпилю Крови, Шпилю Боли и Шпилю Порчи и убей жрецов.|n|nВозвращайся, когда в твоих руках окажутся три свитка.', },
    {'По поручению Тассариана, который находится у Стонущего зиккурата, отправляйтесь в храмовый город Эн\'кила и раздобудьте свиток верховного жреца Талет-Ха в Шпиле Боли, свиток верховного жреца Наферсета – в Шпиле Порчи и свиток верховного жреца Андората – в Шпиле Крови.', },
  },
  [11943] = {
    'Магическая клетка',
    {'Ты $Gобнаружил:обнаружила; фрагмент особой тюрьмы, $N.|n|nПодобные клетки подручные Малигоса используют для содержания пленных магов и иных магических существ, но эта тюрьма предназначалась для… для кого-то более могущественного.|n|nЕсть надежда, что враг нашего врага окажется другом. Отыщи оставшиеся фрагменты клетки.|n|nСкорее всего, они находятся в руках самых доверенных приверженцев Малигоса.', },
    {'Добудьте тюремную обшивку у генерала Церулеана и энергетическое ядро у завоевателя Кровозмея по просьбе Релораза из лагеря под Маскировочным щитом.', },
  },
  [11944] = {
    'В окружении!',
    {'Наша ситуация почти безнадежна. Нам дали приказ занять Стонущий зиккурат с горсткой воинов.|n|nНам очень повезет, если нам удастся удержать эту позицию и не сдать ее Плети. Нас превосходят числом, многие из нас ранены, а бежать в случае чего здесь некуда.|n|nЕсли ты сможешь немного помочь нам, мы, наверное, смогли бы укрепить нашу позицию. Если ты убьешь некоторое количество нежити вокруг постройки, мы сдержим их продвижение.', },
    {'По заданию капрала Венна убейте 7 защитников зиккурата.', },
  },
  [11945] = {
    'Подготовка к самому худшему',
    {'Темные времена для нас настали. Дух Каркута ходит по земле, собирая духи мертвых клыкарров.|n|nСыновья тумана забрали многих наших братьев. Скоро наша любимая Каскала превратится в пепелище.|n|nНо есть еще надежда. Быть может, не для нас – но ведь мы отослали наши семьи в Уну\'пе. Мы сражаемся здесь за то, чтобы у тех, кто там, было будущее.|n|nИм понадобятся съестные припасы, или они умрут с голода. В Уну\'пе еды маловато. Собери что-нибудь, пока для наших родных еще не слишком поздно.', },
    {'По просьбе Утайка соберите в Каскале 8 ящиков припасов Каскала.', },
  },
  [11946] = {
    'Керистраза',
    {'Я... свободна?|n|nМне было суждено вечно скитаться в пустынной бездне, и теперь – я спасена и свободна? Неизмерима глубина моей благодарности, $Gсмертный:смертная;.|n|nКогда я отказалась подчиниться воле Малигоса, он приковал меня к этой тюрьме, а затем расколол ее и разбросал осколки. Проживи я еще сотни твоих жизней, я и тогда не забуду этой услуги.|n|nБыть может, в свое время я найду способ отплатить тебе за нее. А сейчас мы должны сосредоточить наше внимание на Малигосе. Я ослабела, а сделать нужно так много.|n|nМне нужна твоя помощь, $N.', },
    {'Поговорите с Керистразой, когда будете готовы к встрече с Малигосом.|n|nЕсли потеряете свою магическую клетку, поговорите с Релоразом у Маскировочного щита.', },
  },
  [11947] = {
    'Ответный удар',
    {'Мы должны действовать! Мы должны сохранить равновесие. Время против нас.|n|nЕсть один лагерь в тени Этель-Ретор в северо-западных Пустошах. Там, при помощи Камней Льда, они держат связь с элементалями, как в Силитусе. Хотя мне ужасно не хочется этого делать, но духи поймут – тебе придется вызвать одного из помощников Ахуна и уничтожить его. Возможно, этого упреждающего удара будет достаточно...', },
    {'Убейте лейтенанта Градня, помощника Ахуна, вызвав его при помощи Камня Льда к Этель-Ретор в Пустошах, затем вернитесь к старейшине Служителей Земли в столицу.', },
  },
  [11948] = {
    'Ответный удар',
    {'Мы должны действовать! Мы должны сохранить равновесие. Время против нас.|n|nУ Нептулона издавна была операционная база на островке к западу от Тернистой долины. Там сумеречный культ при помощи Камней Льда держит связь с царством Охотника Прилива, как в Силитусе. Хотя мне ужасно не хочется этого делать, но духи поймут – тебе придется вызвать одного из помощников Ахуна и уничтожить его. Возможно, этого упреждающего удара будет достаточно...', },
    {'Убейте лейтенанта Промозглый Ветер, помощника Ахуна, вызвав его при помощи Камня Льда на островке элементалей воды к западу от Тернистой долины, затем вернитесь к старейшине Служителей Земли в столицу.', },
  },
  [11949] = {
    'Не сдаваться без боя!',
    {'Каскала для нас священное место, |3-6($R). Наших предков привел сюда дух самой Таютки.|n|nА теперь эти гнусные твари появляются из тумана и нападают на нас без всякого повода!|n|nНо мы им покажем, что копья у нас не только для того, чтобы бить китов! Сражайся и ты с нами, друг! Быть может, в будущем мой народ вознаградит тебя по заслугам.', },
    {'По просьбе Атаики убейте 12 налетчиков из племени Квалдир в Каскале.', },
  },
  [11950] = {
    'Мудрость Муахита',
    {'Послушай, $N. Воинам вроде меня несложно найти замену. Если я паду, мои братья и родичи подхватят мое копье и продолжат сражаться.|n|nА вот без мудрых старейшин мой народ не проживет. Упрямый Муахит, наш самый почтенный шаман, отказывается покинуть алтарь Таютки на центральном острове. Мы понесем серьезную утрату, если его убьют эти чудовища.|n|nТы здесь $Gчужестранец:чужестранка; – быть может, тебя он послушает? Объясни ему причины... уговори его уйти в безопасность Уну\'пе, пока еще не поздно.', },
    {'Найдите в Каскале старейшину Муахита.', },
  },
  [11951] = {
    'Приманка',
    {'Находясь в плену, я сумела многое узнать о Малигосе. Теперь судьба распорядилась так, что я могу использовать это против него.|n|nВ небе над Нексусом кружит большой синий дракон, Сарагоса. Она одновременно страж аспекта и его супруга. Если возникает серьезная опасность, она предупреждает своего господина.|n|nВ плену я испытала немало страданий от руки Сарагосы, и вот настал ее черед умереть. Однако для начала нужно подготовить ловушку...', },
    {'Соберите в Хладарре 10 осколков кристаллизованной маны по просьбе Керистразы.|n|nЕсли потеряете свою магическую клетку, поговорите с Релоразом у Маскировочного щита.', },
  },
  [11952] = {
    'Ответный удар',
    {'Мы должны действовать! Мы должны сохранить равновесие. Время работает против нас.|n|nГряда Огненной стражи в Тлеющем ущелье – известная позиция культа Сумеречного Молота. Недавно культ стал использовать Камни Льда для связи с царством Охотника Прилива, как в Силитусе. Хотя мне ужасно не хочется этого делать, но духи поймут – тебе придется вызвать одного из помощников Ахуна и уничтожить его. Возможно, этого упреждающего удара будет достаточно...', },
    {'Убейте лейтенанта Лютостужу, помощника Ахуна, вызвав его при помощи Камня Льда в пещере под горами Огненной стражи на северо-западе от Тлеющего ущелья, затем вернитесь к старейшине Служителей Земли в столицу.', },
  },
  [11953] = {
    'Ответный удар',
    {'Мы должны действовать! Мы должны сохранить равновесие. Время работает против нас.|n|nСилитус – азеротская база культа Сумеречного Молота. Там на севере, они используют Камни Льда, чтобы связываться с царством Охотника Прилива. Хотя мне ужасно не хочется этого делать, но духи поймут – тебе придется вызвать одного из помощников Ахуна и уничтожить его. Возможно, этого упреждающего удара будет достаточно...', },
    {'Убейте лейтенанта Хладноглыба, помощника Ахуна, вызвав его при помощи Камня Льда в Сумеречной пещере в северном Силитусе, затем вернитесь к старейшине Служителей Земли в столицу.', },
  },
  [11954] = {
    'Ответный удар',
    {'Мы должны действовать! Мы должны сохранить равновесие. Время против нас.|n|nБлиз Темного портала в Дреноре возник мрачный культ, который хочет помочь Ахуну войти в наш мир. Они используют Камни Льда, чтобы обеспечить явление Повелителя Холода. Хотя мне ужасно не хочется этого делать, но духи поймут – тебе придется вызвать одного из помощников Ахуна и уничтожить его. Возможно, этого упреждающего удара будет достаточно...', },
    {'Убейте Ледяного Храмовника, помощника Ахуна, вызвав его при помощи Камня Льда к Темному порталу на Полуострове Адского Пламени, затем вернитесь к старейшине Служителей Земли в столицу.', },
  },
  [11955] = {
    'Ахун, Повелитель Холода',
    {'Надеюсь, тебе хватит сил на выполнение последнего задания.|n|nМы не можем позволить, чтобы заговор фанатиков культа Сумеречного Молота и наг-отступников Нептулона осуществился. Во имя Азерота и всей жизни на нем мы должны действовать. Наша дорога ясна. Отправляйся в Узилище в недрах Резервуара Кривого Клыка и встреться там с нашей шаманкой. Спеши!', },
    {'Отправляйтесь в Узилище в Резервуар Кривого Клыка, что в Зангартопи и поговорите с Нумой Сестрой Облаков.', },
  },
  [11956] = {
    'Поиски талисмана',
    {'Для болтовни нет времени, $N. Меня послали сюда с самоубийственным заданием – занять зиккурат. Свой солдатский долг я выполнил, а теперь настала пора получить ответы на некоторые вопросы.|n|nЭтот лич обладает знанием, которого я ищу, но в то же время я не могу причинить боль его физическому телу, чтобы это знание заполучить.|n|nЛич поместил свою душу в талисман, и, пока он сокрыт, я не смогу вырвать из лича информацию.|n|nВозвращайся в лагерь и возьми моего коня, Сумрака. Он привезет тебя к талисману. Принеси мне его.', },
    {'Отправляйтесь на Стоянку Смерти и скачите на Сумраке к месту, где находится талисман Танатала. Добудьте его и принесите Тассариану в Стонущий зиккурат.', },
  },
  [11957] = {
    'Смерть Сарагосе!',
    {'Используя предоставленные тобой кристаллы маны, я изготовила это средоточие магии.|n|nСарагоса же обжора! Она не сможет устоять перед такой приманкой. А внутри приманки – магия, которая очень и очень ее ослабит. Будем надеяться, она не заметит мою хитрость...|n|nСоберись с духом, $N, и скажи мне, когда будешь $Gготов:готова; встретиться лицом к лицу с Сарагосой.', },
    {'По просьбе Керистразы используйте средоточие магии для привлечения внимания Сарагосы, а затем сразитесь с ней.', },
  },
  [11958] = {
    'Чтоб ничего не пропало!',
    {'Волчеры всегда были нашими естественными врагами. Но после того, как в Большой Драконий Погост вторгся ваш народ, они оказались заперты на тесном пятачке на севере.|n|nА после сегодняшнего колебания земли они совсем озверели. Они уже несколько раз совершали набеги на наши припасы... припасы, без которых нам не обойтись, если мы хотим пережить это путешествие!|n|nЕсли ты нам друг, отбери наше добро у волчеров Поляны Снегопада!', },
    {'Отберите у волчеров 6 украденных припасов Моа\'ки. Верните их старейшине Ко\'нани в Гавани Моа\'ки.', },
  },
  [11959] = {
    'Убить Логуна!',
    {'Дела идут все хуже и хуже. Остался один-единственный выход... к сожалению, это смерть Логуна!|n|nЭто вожак племени Поляны Снегопада, злобный волчер. Его смерть позволит нам хоть ненадолго прервать постоянные нападения волчеров и их грабительские набеги.|n|n"Сокрушителя плоти" ты найдешь перед его лачугой, на северном откосе поляны. Он крупнее остальных – не ошибешься. Убей его и измажься его кровью, чтобы продемонстрировать свое превосходство над волчерами и уважение к клыкаррам.', },
    {'Намажьтесь кровью Логуна и возвращайтесь к старейшине Ко\'нани в гавань Моа\'ки.', },
  },
  [11960] = {
    'Планы на будущее',
    {'Если мы хотим выжить, нам следует бороться с волчерами. Я только боюсь, как бы мы в своем рвении не истребили слишком многих.|n|nВолчеры Поляны Снегопада имеют такое же право на жизнь, как и мы сами. И мы с тобой позаботимся о том, чтобы они получили свой шанс.|n|nЕсли старейшина Ко\'нани не просил тебя с ними разобраться, значит, еще попросит. Когда будешь на севере, на их поляне, собери, пожалуйста, щенков и принеси их мне.', },
    {'Соберите 12 щенков Поляны Снегопада. Принесите их зверолову Мау\'и в гавани Моа\'ки.', },
  },
  [11961] = {
    'Духи присматривают за нами',
    {'Могущественные духи присматривают за моим кланом – Каскала не будет утрачена.|n|nИссилрук дарует нам смелость, Таютка обеспечит выживших едой и кровом, а Каркут присмотрит за павшими, чтобы они не потеряли свой путь.|n|nРуководство Иссилрука – то, что нам больше всего нужно прямо сейчас. Я просил своего племянника, Ирука, принести мне тотем Иссилрука, но квалдирские копья сразили его, и его тело скатилось в воды к северу отсюда. Принеси мне этот тотем, $N. Пусть смерть моего племянника не будет напрасной.', },
    {'Найдите тело Ирука в воде, заберите тотем Иссилрука и принесите старейшине Муахиту в бухту Дыхания Ньорда.', },
  },
  [11962] = {
    'Последняя партия',
    {'Значит, так. С последней партией руды, которую тебе удалось спасти, у нас выходит достаточно, чтобы отправить груз в крепость Отваги.|n|nЕсли Далечье окажется стерто с лица Азерота, по крайней мере, нас запомнят как тех, кто первым встал на защиту родной земли и кто сдался последним.|n|nДоставь эту руду Хильде Каменной Кузне – это мой хороший друг. Скажи ей, пусть изготовит из нее доброе оружие. Оно нам еще очень и очень понадобится!', },
    {'Доставьте ящик руды из Далечья Хильде Каменной Кузне в крепость Отваги.', },
  },
  [11963] = {
    'Оружие для Далечья',
    {'Далечье вот-вот будет захвачено, а Джеральд не может придумать ничего умнее, кроме как отправить мне очередную партию руды? Этот человек так же бессердечен, как и все солдаты!|n|nМы не можем допустить, чтобы мирные жители теряли свои земли, иначе они не захотят сражаться, когда придет нужда! Правда, мы не можем отправить подкрепление, зато у нас есть для них оружие!|n|nПравда, оно предназначалось для новобранцев, но я успею сделать новое из привезенной тобой руды. Передай Джеральду, что оружие вот-вот будет!', },
    {'Вернитесь к Джеральду Грину в Далечье.', },
  },
  [11964] = {
    'Благовония для летних пламеней',
    {'Известно ли тебе, что наши праздничные костры горят во всех краях, где есть поселения Альянса? Их поддерживают стражи Пламени в лагерях близ каждого городка, чтобы огонь горел ярко до конца праздника.|n|nПри каждом страже Пламени есть летний сполох – посланец духов стихии Огня.|n|nНе хочешь ли выказать почтение сполоху, $N? Возьми эти благовония и преподнеси любому летнему сполоху. Ублажи маленького духа огня, и он, возможно, отблагодарит тебя.', },
    {'Хранитель мудрости Праздника хочет, чтобы вы отнесли благовония Лета летнему пламеню к любому поселению Альянса.', },
  },
  [11965] = {
    'К оружию!',
    {'У Далечья появился шанс побороться, $N. Это все, о чем мы просили, и благодаря тебе это стало возможным.|n|nВсе, что нам еще нужно теперь – это сборный пункт. Я скажу своим людям отнести оружие в ратушу. И ты иди туда же и звони в колокол, чтобы собрать всех выживших.|n|nНастало время показать Плети, из какого теста мы сделаны.', },
    {'Войдите в здание ратуши в Далечье и позвоните в колокол, находящийся в этом здании.', },
  },
  [11966] = {
    'Благовония для праздничных сполохов',
    {'Известно ли тебе, что наши праздничные костры горят во всех краях, где есть поселения Орды? Их поддерживают хранители огня в лагерях близ каждого городка, чтобы огонь горел ярко до конца праздника.|n|nПри каждом хранителе огня есть праздничный сполох – посланец духов стихии Огня.|n|nНе хочешь ли выказать почтение Сполоху, $N? Возьми эти благовония и преподнеси любому праздничному сполоху. Ублажи маленького духа огня, и он, возможно, отблагодарит тебя.', },
    {'Праздничный сказитель хочет, чтобы вы отнесли благовония Лета праздничному сполоху к любому поселению Орды.', },
  },
  [11967] = {
    'Сбор красных драконов',
    {'Малигос явно заметил, что что-то не так.|n|nЯ его знаю. Он не умеет думать о нескольких вещах за раз. Я наверняка сумею выманить его из безопасного логова, когда он узнает, что стало с его ненаглядной Сарагосой.|n|nОтведи меня к Релоразу, $N, и немедленно! Пусть поднимает своих драконов на бой с Малигосом!', },
    {'Отведите Керистразу к Релоразу к Маскировочному щиту.', },
  },
  [11968] = {
    'Поворот колеса Фортуны',
    {'Духи услышали наш крик о помощи, $N. Это знак, что Каскалу еще можно спасти.|n|nВоспользуйся неразберихой, которую внесли капризы погоды, и убей квалдирского вожака. Твои действия склонят чашу весов на нашу пользу, я уверен.', },
    {'По просьбе старейшины Муахита убейте Хейгарра Душегуба в бухте Дыхания Ньорда.', },
  },
  [11969] = {
    'Сработавший капкан',
    {'Мы добились этого во многом благодаря твоим усилиям, $N.|n|nБудет справедливо, если именно ты возглавишь атаку на Малигоса!|n|nВозьми этот сигнальный огонь и запали его у северо-западного входа в Нексус. К тебе присоединится Керистраза.', },
    {'Используйте сигнальный огонь Релораза у северо-западного входа в Нексус по просьбе Релораза.', },
  },
  [11970] = {
    'Хранитель мудрости праздника Середины Лета',
    {'Нынешний праздник – время смеха и забав. Но важно не забывать о его происхождении. Найди же того, кто поделится с тобой этим знанием, и насладись древними преданиями.|n|nВ этом тебе поможет Хранитель мудрости Праздника в любой из столиц Альянса. Ступай же.', },
    {'Поговорите с Хранителем мудрости Празднества в любой из столиц Альянса.', },
  },
  [11971] = {
    'Сказитель Летнего праздника',
    {'Нынешний праздник – время смеха и забав. Но важно не забывать о его происхождении. Найди же того, кто поделится с тобой этим знанием, и насладись древними преданиями.|n|nВ этом тебе поможет Праздничный сказитель в любой из столиц Орды. Ступай же.', },
    {'Поговорите с праздничным сказителем в любой из столиц Орды.', },
  },
  [11972] = {
    'Осколки Ахуна',
    {'Эти осколки пульсируют, испуская какую-то недобрую энергию. Не сохранилось ли в них остатков сущности Повелителя Холода?', },
    {'Принесите ледяные осколки Луме Матери Небес.', },
  },
  [11973] = {
    'Пленница',
    {'Малигос забрал Керистразу и заставляет ее стать его супругой?! Немыслимо!|n|nОна никогда не согласится на это, но Малигос – могучий аспект. Рано или поздно он сломит ее волю.|n|n$N, нельзя этого допустить. Я не позволю ей страдать, испытывая такое унижение.|n|nТы $Gдолжен:должна; войти в Нексус и сделать все, чтобы избавить ее от этой ужасной судьбы.', },
    {'По просьбе Релораза из лагеря под Маскировочным щитом отправьтесь в Нексус и освободите Керистразу.', },
  },
  [11974] = {
    '[ph] Когда я вырасту...',
    {'Когда ты $Gбыл:была; в моем возрасте, ты $Gзнал:знала;, что будешь |3-6($C), когда вырастешь?|n|nА я не знаю, кем хочу быть. Сначала я хотела быть рыцарем крови, а теперь не хочу. Теперь я хочу быть рок-звездой! Как тот эльф крови из группы L70 ETC!|n|nКогда они не ездят с гастролями, они находятся в Луносвете! Ты отвезешь меня туда? Они обычно на Пути Старейшин, на балконе... Наверное, чтобы фанаты не добрались. Но ведь мы можем попытаться, верно?|n|nНу, пожалуйста, отвези меня туда, ну, пожалуйста!', },
    {'Отведите вашу сиротку, Саландрию, посмотреть на выступление группы L70ETC в Луносвет, на Путь Старейшин. Обязательно позовите Саландрию, если по прибытии ее не окажется рядом.', },
  },
  [11975] = {
    'Когда я вырасту...',
    {'Может, я уже спрашивала, но когда ты $Gбыл:была; в моем возрасте, ты $Gзнал:знала;, что будешь |3-6($C), когда вырастешь?|n|nА я не знаю, кем хочу быть. Может, магом или чернокнижницей, или рыцарем крови, как я уже говорила. Или... рок-звездой! Как Сиг Шивес, эльф крови из группы "Вожди тауренов"!|n|nЯ слышала, что когда они не ездят с гастролями, они находятся в Луносвете! Они сидят на балконе на Пути Старейшин и ждут, когда возле них остановятся. |n|nОчень прошу, отвези меня туда, ну, пожалуйста!', },
    {'Отведите вашу сиротку, Саландрию, посмотреть на группу "Вожди тауренов" в Луносвет, на Путь Старейшин. Не забудьте позвать ее, если ее не окажется, когда прибудете.', },
  },
  [11976] = {
    'Осколки льда',
    {'Эти осколки пульсируют, испуская какую-то недобрую энергию. Не сохранилось ли в них остатков сущности Повелителя Холода?', },
    {'Принесите ледяные осколки Луме Матери Небес.', },
  },
  [11977] = {
    'Таурен среди таунка',
    {'Поищите эмиссара Светлое Копыто в лагере беженцев Западного Ветра.', },
    {'Поищите эмиссара Светлое Копыто в лагере беженцев Западного Ветра.', },
  },
  [11978] = {
    'Добро пожаловать в Орду',
    {'Прежде чем мы сможем официально принять этих таунка в лоно Орды, мы должны отбить наше вооружение у нерубов-воинов Ануб\'ара, которые заполонили окрестные леса. Это вооружение было утеряно, когда на караван из Молота Агмара напали прошлой ночью силы Плети.|n|nОтправляйся в лес к востоку от лагеря беженцев Западного Ветра и верни вооружение, |3-6($R).', },
    {'По просьбе эмиссара Светлое Копыто из лагеря беженцев Западного Ветра на Драконьем Погосте добудьте 10 ящиков с ордынским оружием.', },
  },
  [11979] = {
    'Таунка и таурены',
    {'Плеть захватила столицу таунка, деревню Ледяной Пыли! Всех выживших таунка держат пока в лагере беженцев Западного Ветра на западной границе Драконьего Погоста.|n|nЛорд Адский Крик считает, что, чтобы выжить, таунка необходимо примкнуть к Орде. Поэтому он отправил в лагерь Западного Ветра посланника-таурена, чтобы укрепить нашу дружбу с северными тауренами. Отправляйся в лагерь беженцев Западного Ветра и отыщи эмиссара Светлое Копыто. Ей понадобится твоя помощь.', },
    {'Поищите эмиссара Светлое Копыто в лагере беженцев Западного Ветра.', },
  },
  [11980] = {
    'Гордость Орды',
    {'Убейте 15 ануб\'арских душителей по просьбе кровавого стража Рох\'килла из лагеря беженцев Западного Ветра в Драконьем Погосте.', },
    {'Убейте 15 ануб\'арских душителей по просьбе кровавого стража Рох\'килла из лагеря беженцев Западного Ветра в Драконьем Погосте.', },
  },
  [11981] = {
    'Найди Куруна!',
    {'Каменная поверхность земельника-воина покрыта трещинами и впадинами. Хотя он не может истекать кровью, вы чувствуете, что великан находится при смерти.|n|nТихий, едва различимый голос срывается с губ умирающего.|n|n"Найди... Куруна... ты $Gдолжен:должна; найти... Куруна."|n|nВ ответ на ваши попытки выяснить, кто такой Курун, он беспомощно смотрит на вас из-под полуопущенных век.|n|n"Наш... предводитель... он стоит на... холме, с которого виден весь Тор Модан... командует нашей армией. Прошу... скажи ему... мы не сможем взять... город... "', },
    {'Поговорите с Куруном, который стоит на вершине холма рядом с Тор Моданом.', },
  },
  [11982] = {
    'Каменный дождь',
    {'Прямо под нами находится древняя крепость железных дворфов, Тор Модан. Тысячи лет назад каменные великаны вызвали землетрясение, обрушившее большую часть города в огромную пропасть и стеревшее с лица земли то, что от него осталось.|n|nНо железные дворфы никогда не прекращали попыток отвоевать древнюю столицу. Мы не можем этого допустить! Мои гиганты засыпят пропасть щебнем и камнями вместе с работающими железными дворфами. Возможно, тогда нам удастся избавиться от них навсегда. Тебя же я попрошу помочь нам в этом деле, скинув в пропасть на северо-востоке как можно больше булыжников.', },
    {'Курун, стоящий на холме, рядом с Тор Моданом, просит вас помешать железным дворфам, сбросив в котлован Тор Модана несколько булыжников.', },
  },
  [11983] = {
    'Клятва крови Орды',
    {'Они готовы, $N. Эти таунка добровольно вольются в Орду и отдадут все, что у них есть, чтобы выдворить армию Плети из этого мира.|n|n<Светлое Копыто передает вам свиток, на котором – знак Орды.>|n|nНа этом свитке запечатлена клятва крови Орде. Традиция предписывает нашим новым братьям и сестрам из народа таунка произнести вместе священные слова клятвы.|n|nВозьми этот свиток и прими клятву таунка Орде, командор. Верни мне свиток, когда выполнишь эту почетную обязанность.', },
    {'Поговорите с таунка в лагере беженцев Западного Ветра и примите у пятерых из них клятву верности Орде.|n|nВерните клятву крови Орды эмиссару Светлое Копыто, когда выполните задание.', },
  },
  [11984] = {
    'Захлопнуть клетку',
    {'Эх, старина Бадд уже отжил свой век.|n|nС тех пор, как мы перебрались сюда из Призрачных земель, он просто висит у нас камнем на шее. А мы тут, между прочим, пытаемся как-то наладить жизнь! В смысле, продаем пленных троллей тому, кто больше заплатит.|n|nК счастью, для Бадда тоже нашлась работенка. В его состоянии легко втереться в доверие к троллям, так что мы обучили его кое-каким прибыльным трюкам.|n|nДа лучше $Gсамому:самой; увидеть, чем сто раз услышать. Поговори с Баддом и отведи его на юго-запад к Руинам Драк\'Зина. После этого тебе останется только захлопнуть дверцу клетки за пойманным троллем!', },
    {'Самир из Гранитных ключей просит вас запереть в клетку охотника оглушенного Баддом ледяного тролля.', },
  },
  [11985] = {
    'Битва в Проломе',
    {'Если мы не сможем подорвать оборону Тор Модана, то наша осада ни к чему не приведет. Дети земли отважно сражаются с големами, созданными сынами железа, но им не под силу проникнуть в город.|n|nВедущие туда тоннели слишком узки, и мои братья-великаны не могут ими воспользоваться. Но тебе под силу пробраться в самое сердце укреплений железных дворфов и убить их предводителя!', },
    {'Курун, стоящий на холме, возвышающемся над Тор Моданом, просит вас убить железного тана Аргрума.', },
  },
  [11986] = {
    'Порванный журнал',
    {'Этот потрепанный, запятнанный дневник знавал лучшие времена. Листая его, вы находите множество карт, диаграмм и других заметок.|n|nПочерк кажется смутно знакомым, но только обнаружив в конце одной из записей подпись Бранна Бронзоборода, вы понимаете, кому он принадлежит.|n|nВторая половина книги, содержащая самые последние записи, была грубо вырвана. Поле битвы усеяно разделенными страницами – чтобы узнать, что выяснил Бранн, придется собрать их в исходном порядке.', },
    {'Разыщите 8 недостающих страниц, вклейте их в дневник и принесите его Тортену Глубокопу в Лагерь дружины Западного Края.', },
  },
  [11987] = {
    'zzOLDГадательная карта: Серебро',
    nil,
    nil,
  },
  [11988] = {
    'Рунический краеугольный камень',
    {'В своем дневнике Бранн упомянул некий рунический краеугольный камень, с помощью которого можно перевести самые важные руны на найденной им табличке. Без этого камня мы не сможем понять ни единой надписи.|n|nВ самом конце дневника сказано, что камень был похищен железными дворфами-защитниками, которые поделили его части между собой. Мы должны собрать эти фрагменты, чтобы расшифровать табличку! Увы, Бранн не смог описать похитителей. А это значит, что куски камня могут оказаться у любого дворфа в Тор Модане.', },
    {'Принесите 5 фрагментов рунического краеугольного камня Тортену Глубокопу в Лагерь дружины Западного Края.', },
  },
  [11989] = {
    'Перемирие?',
    {'Осторожнее, $Gдружище:подруга;.|n|nТы не представляешь, сколько таких хорошеньких голов полегло под топором Дракуру – я до стольки даже считать не умею. Повезло тебе, что я сижу в клетке – а то в моем списке стало бы на одну жертву больше.|n|nНо, возможно, на этот раз мы сможем что-нибудь придумать!|n|nДракуру знает много всего на свете, и кое-что из этого могло бы тебе помочь. |n|n<Дракуру царапает ладонь об один из своих клыков и протягивает вам руку меж прутьев клетки.>|n|nЧто скажешь? Заключим перемирие?', },
    {'Дракуру из Гранитных ключей просит вас скрепить перемирие кровью, поцарапав свою руку тупым резаком, лежащим возле его клетки.', },
  },
  [11990] = {
    'Пузырек видений',
    {'Не будем торопиться, дружок. Сначала нам надо подготовиться. |n|nКто знает, как долго я смогу здесь оставаться. Поэтому, чтобы мы с тобой смогли общаться и дальше, тебе придется добыть очень мощный эликсир.|n|nК счастью, я знаю, что может нам помочь! И все его компоненты буквально лежат под рукой. |n|nМне нужна склянка одного из этих маленьких, миленьких троллей, которые тут стоят, немного водорослей из северного пруда и немного туманнолистника.|n|nТолько поторопись, пока они меня не утащили.', },
    {'Дракуру из Гранитных ключей просит вас принести ему укрепленную колбу, сплетение водорослей и три листа туманнолистника.', },
  },
  [11991] = {
    'Требуется расшифровка',
    {'Говорят, что когда-то для укрепления Крепости Драк\'Тарон были созданы могущественные артефакты, но они были утеряны много веков назад.|n|nМногие считают, что это просто легенда, но Дракуру знает правду!|n|nЯ был близок к тому, чтобы обнаружить первый артефакт, но меня захватили в тот самый момент, когда я расшифровывал важные иероглифы, могущие привести нас к истине. Отправляйся на юго-запад, к жаровне в руинах Драк\'Зина и воспользуйся моим эликсиром, чтобы я смог закончить работу. |n|nУвы и ах, чтобы призвать меня туда, тебе придется смешать эликсир с застывшим настоем, который есть только у моих братьев. Мне больно думать о том, что ради этого тебе придется убивать моих родственничков, но наша цель оправдывает средства.', },
    {'Дракуру просит вас добыть 5 застывших настоев у Драккари, обитающих среди Руин Драк\'Зина, и затем выпить эликсир возле жаровни Дракуру.', },
  },
  [11992] = {
    'Навигационные карты (DEPRECATED)',
    {'Вы обнаружили первую часть навигационной карты, начертанной на обрывке драконьей шкуры. Если бы вам удалось собрать полную карту, вы смогли бы найти квалдирские планы будущей атаки.|n|nДолжно быть, остальные части карты находятся у других моряков на берегу Терзающего Бича. Наверняка, Карука заинтересовала бы информация, содержащаяся в карте.', },
    {'Раздобудьте недостающие части скадирской навигационной карты и принесите Каруку на берег Терзающего Бича.', },
  },
  [11993] = {
    'Рунические пророчества',
    {'Нельзя терять ни минуты! Теперь, когда рунический краеугольный камень практически собран, мы можем перевести те самые рунические таблички, над которыми работал Бранн до побега.|n|nК сожалению, нам неизвестно, какую часть информации ему удалось получить, так что будем предполагать, что он узнал достаточно для того, чтобы определить свой следующий шаг.|n|nПодойди к каждой табличке и воспользуйся руническим краеугольным камнем. Помни – Бранн может надеяться только на нас!', },
    {'Тортен Глубокоп из Лагеря дружины Западного Края просит вас расшифровать три рунических диска.', },
  },
  [11995] = {
    'Безотлагательное путешествие в Покой Звезд',
    {'$C, я знаю, эти клыкарры будут просить тебя о том и о сем, но тебе нужно поспешить в Покой Звезд.|n|nПертурбации, произошедшие этим утром, бесспорно, будут иметь куда больший резонанс, чем просто неудобство для местных жителей.|n|nПокой Звезд находится к западу отсюда, за перекрестком с дорогой, ведущей к северу из гавани. Верховный маг Модера будет ждать тебя там.', },
    {'Поговорите с проекцией верховного мага Модеры в Покое Звезд.', },
  },
  [11996] = {
    'Безотлагательное путешествие в Молот Агмара',
    {'$C, я знаю, эти клыкарры будут просить тебя о том и о сем, но тебе нужно поспешить в Молот Агмара.|n|nПертурбации, произошедшие этим утром, бесспорно, будут иметь куда больший резонанс, чем просто неудобство для местных жителей.|n|nМолот Агмара находится к западу отсюда, за перекрестком с дорогой, ведущей к северу из гавани. Там тебя будет ждать сам верховный маг Этас Похититель Солнца!', },
    {'Поговорите с проекцией верховного мага Этаса Похитителя Солнца в Молоте Агмара.', },
  },
  [11997] = {
    nil,
    {'Мы отправили дружинников Западного Края на северо-восток Седых холмов, чтобы они обеспечили безопасный проход для наших отрядов. Они разбили лагерь на северо-востоке от Седой Пасти, к юго-западу от Тор Модана.|n|nНадеюсь, ты помнишь капитана Гриана Камнегрива, почетного ветерана Лордеронской войны с Плетью? Он больше известен обитателям Западного Края за свое решение покинуть поле битвы и вернуться домой, чтобы выступить против Братства Справедливости.', },
    {'Поговорите с капитаном Грианом Камнегривом в Лагере дружины Западного Края.', },
  },
  [11998] = {
    'Подсластить пилюлю',
    {'Я обнаружил самый быстрый способ перебросить наши войска на Ледник Ледяной Короны – через сеть туннелей, пролегающей под древним городом железных дворфов, Тор Моданом.|n|nБругар Гравировщик и его ребята из Лиги Исследователей, конечно, не обрадуются такому решению, но приказа не ослушаются.|n|nВпрочем, мы могли бы подсластить им пилюлю, прислав бочку самогона Полнолуния. Его продает Хью Гласс в Торговой лавке Красного леса. Этот магазин находится на юго-востоке отсюда, если идти вдоль просеки.|n|nОн, правда, слегка чокнутый – но зато у него самый ядреный самогон во всей долине!', },
    {'Принесите Бругару Гравировщику из Лагеря дружины Западного Края бочку старого доброго самогона.', },
  },
  [11999] = {
    'Обшарить трупы',
    {'Сады Лунного Покоя на юго-западе были местом последнего упокоения нескольких высокорожденных эльфов. Там находился и узел силовых линий.|n|nСиние драконы применили магическое устройство, которое они называют волноловами, чтобы уничтожить этот узел и высвободить энергию, перенаправив ее по своему усмотрению.|n|nМне нужны дополнительные сведения, и ты их мне добудешь!|n|nПосле того как эти земли были разорены, призраки высокорожденных восстали и уничтожили половину здешних охотников на магов. Обыщи их тела, чтобы добыть сведения.', },
    {'Найдите планы в Садах Лунного Покоя и вернитесь с ними к проекции верховного мага Этаса Похитителя Солнца в Молоте Агмара.', },
  },
  [12000] = {
    'Обшарить трупы',
    {'Сады Лунного Покоя на юго-западе были местом последнего упокоения нескольких высокорожденных эльфов. Там находился и узел силовых линий.|n|nСиние драконы применили магическое устройство, которое они называют волноловами, чтобы уничтожить этот узел и высвободить энергию, перенаправив ее по своему усмотрению.|n|nМне нужны дополнительные сведения, и ты их мне добудешь!|n|nПосле того как эти земли были разорены, призраки высокорожденных восстали и уничтожили половину здешних охотников на магов. Обыщи их тела, чтобы добыть сведения.', },
    {'Найдите планы в Садах Лунного Покоя и вернитесь с ними к проекции верховного мага Модеры в Покое Звезд.', },
  },
  [12001] = {
    'zzOLDКарты охотника: меньшие звери',
    {'Вглядевшись в карту, вы внезапно видите себя, $Gзакутавшегося:закутавшуюся; в волчьи и медвежьи шкуры. Вы полагаете, что, исполнив это пророчество, можно пробудить истинную силу карты.', },
    {'Соберите 12 рваных шкур и призовите охотника с помощью карты. Рваные шкуры можно добыть, убивая зверей 5 уровня или выше.', },
  },
  [12002] = {
    'Братья по оружию',
    {'Надеюсь, Гриан понимает, почему я отозвал своих людей из Тор Модана после начала сражения. Невозможно работать, когда над головой взрываются снаряды!|n|nСлушай, ты с виду не робкого десятка, да и Камнегрив тебе доверяет.|n|nОтправляйся в Тор Модан, что на северо-востоке отсюда, и помоги нашим братьям одолеть этих проклятых железных дворфов. А я тем временем составлю план поисков.', },
    {'Убейте 10 рунических боевых големов и вернитесь к Бругару Гравировщику в Лагерь дружины Западного Края.', },
  },
  [12003] = {
    'В поисках туннелей',
    {'На месте железных дворфов я бы спрятал вход в подземные туннели в одном из зданий, окружающих Тор Модан. Именно с них мы и начнем наши поиски.|n|nПравда, надо быть осторожным, осматривая эти постройки – я заметил, что именно там укрылись выжившие железные дворфы-защитники.|n|nСкорее всего, вход в туннели будет с обратной стороны здания. Не знаю уж, что там надеется найти Камнегрив, но железные дворфы вряд ли станут помогать нам в поисках.', },
    {'Бругар Гравировщик из Лагеря дружины Западного Края просит вас осмотреть северное, восточное и южное строения в Тор Модане.', },
  },
  [12004] = {
    'Предотвратить союз',
    {'$C, сейчас нам нужно убить одним выстрелом сразу двух зайцев. И этим выстрелом будешь ты!|n|nА зайцами будут Му\'фа Торговец Ветром и Горамош. Они должны быть где-то здесь, в западной части садов Лунного Покоя. Скорее всего, они в большом двухэтажном здании, которое стоит над обрывом.|n|nИ, будь так $Gлюбезен:любезна;, принеси мне доказательства их смерти!', },
    {'Принесите проекции верховного мага Модеры в Покой Звезд останки торговца Ветром Му\'фа и чешую Горамоша.', },
  },
  [12005] = {
    'Предотвратить союз',
    {'$C, сейчас нам нужно убить одним выстрелом сразу двух зайцев. И этим выстрелом будешь ты!|n|nА зайцами будут Му\'фа Торговец Ветром и Горамош. Они должны быть где-то здесь, в западной части садов Лунного Покоя. Скорее всего, они в большом двухэтажном здании, которое стоит над обрывом.|n|nИ, будь так $Gлюбезен:любезна;, принеси мне доказательства их смерти!', },
    {'Доставьте останки Му\'фы Торговца Ветром и чешую Горамоша к проекции верховного мага Этаса Похитителя Солнца в Молоте Агмара.', },
  },
  [12006] = {
    'Месть за бесчинства!',
    {'Эти так называемые охотники на магов явились сюда и уничтожили наше место отдыха.|n|nОтомсти за нас, или я позабочусь о том, чтобы вашу операционную базу заполонили духи умерших!', },
    {'Убейте охотников на магов с Драконьего Погоста, ловчих из Садов Лунного Покоя, колдунов Волноловов и волшебников средоточия, общим числом 15, после чего возвращайтесь к Этениалу Тени Луны в Сады Лунного Покоя.', },
  },
  [12007] = {
    'Необходимые жертвы',
    {'Я все понял, $Gдружище:подруга;!|n|nНа севере, на зиккурате в Зеб\'Халак стоит каменная голова с рубиновыми глазами. Один из этих рубинов – Око пророка! Отнеси его к моей жаровне и выпей эликсир.|n|nИ снова для этого тебе понадобится настой – на этот раз вождя Зим\'бо. Он прячется в одной из хижин Зеб\'Халака.|n|nЖаль будет убивать Зим\'бо, но он поклялся защищать Драк\'Тарон до последней капли крови – и не сдержал обещание. Теперь он сможет послужить нам, отдав свой настой во имя благого дела.', },
    {'Дракуру просит принести ему Око пророка к жаровне в Зеб\'Халаке.|n|nЧтобы эликсир Дракуру сработал на пьедестале, вам придется добыть настой Зим\'бо.', },
  },
  [12008] = {
    'Молот Агмара',
    {'К востоку от нашего лагеря, совсем рядом, находится Молот Агмара – главное укрепление Орды на Драконьем Погосте.|n|nНесомненно, наши братья и сестры уже могли воочию убедиться в том, что ты всеми силами помогаешь таунка стать частью Орды. Однако я хочу, чтобы ты лично $Gдоставил:доставила; известие о своем успехе командиру Агмару.|n|nИди же, $N! Лети на крыльях ветра! На восток, в Молот Агмара!', },
    {'Отправляйтесь в Молот Агмара на Драконьем Погосте и поговорите с командиром Агмаром.', },
  },
  [12009] = {
    'Крабовые ловушки Туа\'кеа',
    {'Из-за всех этих проблем я потерял своих помощников. Я тут подумывал, вдруг ты захочешь мне помочь?|n|nПод водой в гавани я расставил множество ловушек на крабов. Не принесешь ли их мне? Я уже слишком стар для таких вещей, да и в воде небезопасно.|n|nПрошу тебя, возьми эту воздушную камеру, она поможет тебе дышать, когда будешь там, внизу.', },
    {'Соберите 8 ловушек Туа\'кеа для крабов и принесите их ему в гавань Моа\'ки.', },
  },
  [12010] = {
    'Что случилось с Орлондом?',
    {'Когда мы начали раскопки города, я послал геодезиста Орлонда проверить устойчивость туннелей в Тор Модане. Признаться, я не видел его в числе эвакуировавшихся после начала сражения, и я опасаюсь, что он может все еще оставаться в городе.|n|nА его исследования жизненно необходимы нам для того, чтобы обеспечить безопасную транспортировку армии через Тор Модан! Камнегрив с меня живьем шкуру снимет, если под обвалом окажется одна из его дружин!', },
    {'Найдите геодезиста Орлонда в Тор Модане.', },
  },
  [12011] = {
    'Признаки большой проблемы',
    {'Эта ловушка для крабов, похоже, была уничтожена чем-то более крупным, чем шныряющие поблизости акулы.|n|nМожет быть, стоит рассказать об этом Туа\'кеа – рыбаку из гавани Моа\'ки?', },
    {'Сообщите рыбаку Туа\'кеа о разрушенной ловушке на крабов.', },
  },
  [12012] = {
    'Сообщи старейшим',
    {'Эти сведения должны быть переданы всем членам Служителей Земли. Не знаю, что делать дальше, но это может знать тот, кто тебя послал сюда. Пожалуйста, вернись к нему и узнай, что делать дальше – нельзя сидеть сложа руки!', },
    nil,
  },
  [12013] = {
    'Покончить с Арканимусом!',
    {'Осталась еще одна вещь, которую ты $Gдолжен:должна; сделать, $N- |3-6($R). Я хочу, чтобы ты $Gуничтожил:уничтожила; Арканимуса!|n|nКолдуны к западу отсюда использовали то гигантское устройство в небе для того, чтобы высверлить огромный провал там, где мы отдыхаем. Когда они это сделали, то выпустили монстра!|n|nЯ бы так не беспокоился, если бы это было просто угрозой для смертных, но Арканимус питается духами умерших.|n|nТы $Gдолжен:должна; немедленно положить этому конец!', },
    {'Уничтожьте Арканимуса и вернитесь к Этениалу Тени Луны в сады Лунного Покоя.', },
  },
  [12014] = {
    'Крепкий как камень?',
    {'Судя по записям, Орлонд привез с собой некий "переносной сейсмограф", но поблизости нет ничего похожего на этот прибор. |n|nВ исследовательском дневнике указано, что Орлонд закончил измерения в туннеле Тор Модана, за исключением одного места, помеченного как "восточный тупик открытого прохода". |n|nВ последней записи сказано, что Орлонд пытался укрыться в воде, но на него напали подземные крепкобузы. Возможно, именно они забрали его оборудование. Вам надо вернуть сейсмограф, чтобы закончить исследования.', },
    {'Верните портативный сейсмограф и сделайте последний замер колебаний в Тор Модане, после чего вернитесь к Бругару Гравировщику в Лагерь дружины Западного Края.', },
  },
  [12015] = {
    'Тестовое задание для Крейга',
    {'олджолджод', },
    {'Принесите 5 незнамо чего Крейгу Амай незнамо куда.', },
  },
  [12016] = {
    'Наживка',
    {'Я уверен в этом... Вернулся наш древний заклятый водный враг, Ту\'у\'гвар – "Тот, кто играет с добычей". Мы должны приготовить для него ловушку – ты и я. Есть один вид мяса, мимо которого он уж точно не сможет проплыть равнодушно. |n|nЭто матриарх всех крабов, Кили\'уа "Огромные Клешни". Она нежится на своем острове, в водах к юго-западу отсюда. Нанеси-ка ей визит... и возвращайся с ее мясом.', },
    {'Добудьте мясо матриарха по прозвищу "Огромные Клешни" и принесите его Туа\'кеа в гавань Моа\'ки.', },
  },
  [12017] = {
    'Наживка на крючке',
    {'Настала пора, мой друг: с Ту\'у\'гваром должно быть покончено!|n|nЯ подготовил мясо таким образом, что эта тварь обязательно придет, когда насадишь наживку на крючок, который я установил под водой. Просто следуй за этой рыболовной леской.|n|nЧто бы ты ни $Gделал:делала;, не дай Ту\'у\'гвару проглотить тебя целиком, $N!', },
    {'Убейте Ту\'у\'гвара, а затем вернитесь к Туа\'кеа в гавань Моа\'ки.', },
  },
  [12018] = {
    'Месть сладка',
    {'Эй, ты... С виду ты вроде $Gне дурак:не дура; подраться. Я жажду отомстить Плети, чьи воины убили мою семью. Пойди добудь мне с горгулий пару здоровенных кусков камня, чтобы я мог бросить их на землю и яростно топтать их до тех пор, пока они не рассыплются в гравий, в пыль!|n|nДа. Иди. Убей их.', },
    {'Добудьте 2 отколотых куска горгульи, убивая горгулий-падальщиков с восточных Полей Падальщиков. Выполнив задачу, вернитесь к лорду Бевису.', },
  },
  [12019] = {
    'Последние ритуалы',
    {'Я служил Артасу в смерти, потому что у меня не было выбора. Он управлял моей волей и моим телом. А приверженцы Культа Проклятых служат Артасу живыми… добровольно…|n|nТеперь, когда мы знаем слова могущества, необходимые для того, чтобы войти в Наксанар, мы можем положить конец этой язве! Ступай в Эн\'кила и отыщи под парящей цитаделью сферу телепортации!|n|nПроберись наверх, встретимся на вершине. Тебе понадобится все твое мужество – возможно, живыми мы оттуда не выберемся...', },
    {'Отправьтесь в Храмовый город Эн\'кила и отыщите сферу телепортации под парящей цитаделью Наксанар. Используйте сферу, чтобы попасть на вершину цитадели и помочь Тассариану.', },
  },
  [12020] = {
    'Однажды, напившись в...',
    {'Дворфы Черного Железа потерпели поражение! Убегая в "Угрюмого обжору", они потеряли почти весь свой транспорт. Но главное – наш лагерь цел и невредим. |n|nБеги к Бокси и расскажи ему о нашей славной победе над кланом Черного Железа.', },
    {'Поговорите с Бокси Болтокрутом в лагере Хмельного фестиваля.', },
  },
  [12021] = {
    'Письмо домой',
    {'Это письмо, похоже, адресовано одному из жителей Штормграда одним из последних селян с Полей Падальщиков. Может быть, кто-то из выживших в восточном лагере возьмется переправить письмо по адресу.', },
    {'Доставьте письмо домой к леди Алистре на восточные Поля Падальщиков.', },
  },
  [12022] = {
    'Пей до дна!',
    {'Эй! Похоже, с выпивкой ты обращаться умеешь. А вот с пивной кружкой? |n|nЭти дворфы из клана Черного Железа опять вернулись! Мстить хотят и праздник нам порушить! Легче всего их отогнать, если запустить в них пивной кружкой, но сначала посмотрим-ка, попадешь ли ты в чучелко – С.С.М.?|n|nЭто просто – хлебни бесплатного пивка, только встань сначала лицом к С.С.М. Попади в цель пять раз, тогда поговорим.', },
    {'Попадите кружкой с бесплатным пивом в С.С.М. 5 раз, затем поговорите с Бокси Болтокрутом.', },
  },
  [12023] = {
    'Сладость мести',
    {'Хрустит вполне прилично. Теперь слушай, ты... |3-6($R) или кто ты там... На склоне холма к югу отсюда бродит поганище. Иди и убей его. Убей как следует!', },
    {'Убейте поганище, бродящее по склону в восточных Полях Падальщиков. Затем возвращайтесь к лорду Бевису.', },
  },
  [12024] = {
    'Перепись павших',
    {'Спасибо, что $Gпришел:пришла; на помощь, $N. Мы давно не получаем вестей из крепости Стражей Зимы. Наверняка они сражаются с Плетью, но я не могу поверить, что они бросили нас одних на погибель.|n|nНужно собрать имена всех павших, чтобы известить их семьи. Когда нас сюда прислали, все мы заполняли ведомости, которые нам велели носить при себе.|n|nСтупай, обыщи трупы и принеси мне любые документы, какие найдешь, чтобы можно было составить список.', },
    {'Обыщите скелеты на Полях Падальщиков и заберите у них расчетные ведомости Альянса.', },
  },
  [12025] = {
    'Алый орден среди нас',
    {'Рада видеть, что вы не пострадали от Плети. Быть может, ты согласишься помочь?|n|nК северу отсюда обосновался Алый орден. Они явно намерены сражаться с Плетью. Что меня тревожит, так это то, что они взялись за строительство прежде, чем на нас напали. Должно быть, им что-то известно!|n|nЯ подозреваю, что тут замешан кто-то из наших. Попытайся разузнать о тех из нас, кто вернулся обратно в обличье вурдалаков. Если что-то узнаешь, сообщи это мне.', },
    {'Отыщите свидетельства связи с Алым орденом на недавно появившихся вурдалаках-падальщиках с восточных Полей Падальщиков. Когда что-нибудь найдете, вернитесь к леди Алустре.', },
  },
  [12026] = {
    'Порванный журнал',
    {'Этот потрепанный, запятнанный дневник знавал лучшие времена. Листая страницы, вы находите множество карт, диаграмм и заметок, написанных на дворфийском языке.|n|nВам удается разобрать только имя Бранна Бронзоборода, написанное в конце одной из заметок.|n|nВторая половина книги, содержащая самые последние записи, была грубо вырвана. Похоже, кто-то счел этот дневник достаточно важным, и попытался уничтожить. Вы надеетесь, что недостающие страницы все еще можно отыскать на поле боя.', },
    {'Разыщите 8 недостающих страниц, вклейте их в дневник и верните его Ведунье Палуне в Лагерь Уанква.', },
  },
  [12027] = {
    'Удивительное приключение мистера Ушастика',
    {'Простите, $Gгосподин:госпожа;, вы не могли бы подсказать нам дорогу в военный лагерь?|n|nМы с мистером Ушастиком решили погулять в лесу вместе с моим братиком Волтером, но в последний момент его куда-то позвали.|n|nТак что мы с мистером Ушастиком пошли гулять одни, но сразу же заблудились, а потом за нами погнались голодные волки, но мы нашли эту башню и спрятались внутри. |n|nВолки убежали, но мы теперь не знаем, куда идти.|n|nМожет быть, вы нам поможете? Пожа-алуйста!', },
    {'Помогите Эмили и мистеру Ушастику вернуться в Лагерь дружины Западного Края, после чего поговорите с оруженосцем Волтером.', },
  },
  [12028] = {
    'Духовное озарение',
    {'$R, мы не слышали о наших соплеменниках в деревне Инду\'ле с того самого момента, как земля затряслась и стала раскалываться!|n|nТебе когда-нибудь доводилось выполнять обряд поиска видений? Ты ведь $Gпревзошел:превзошла; Логуна, так что у тебя должно получиться.|n|nЯ дам тебе особое благовоние, которое нужно будет всыпать в мою жаровню. Глубоко вдохни его дым, и твой дух воспарит, чтобы увидеть, что произошло в Инду\'ле.|n|nА пока дух твой будет в полете, я смогу смотреть твоими глазами.', },
    {'Поговорите с Тоалу\'у Мистиком после того, как пройдете обряд поиска видений.', },
  },
  [12029] = {
    'Пылающая Плеть',
    {'<Ик>... сжечь надо эти трупы, пока они снова не начали ходить.|n|nЗнаешь, что говорил мне мой папочка? Нет ничего хуже тролля, которого приходится убивать дважды.|n|nВот..<ик>... как нам оттеснить этих троллей на север, если их так много?|n|nДавай-ка ты избавишь этих мерзавцев от печальной участи жизни после смерти?', },
    {'Мак с Гранитных ключей просит вас поджечь 20 голодающих троллей Плети с помощью его грога.', },
  },
  [12030] = {
    'Старейшина Мана\'лоа',
    {'Мой народ…|n|n<Мистик едва не теряет самообладание.>|n|nПока дух твой летал по территории деревни, я почувствовал, что тебя заметил старейшина Мана\'лоа. $N, он хочет поговорить с тобой. Каменных старейшин мы почитаем как источники древней мудрости.|n|nНаверное, старейшине нужна помощь. Найди его в северо-западном углу деревни.', },
    {'Поговорите со статуей старейшины Мана\'лоа в деревне Инду\'ле.', },
  },
  [12031] = {
    'Свобода перемещения',
    {'Священная земля эльфов на западе была расколота. Теперь их магия течет по земле, сея разрушение на своем пути.|n|nДуши калу\'аков в опасности, поскольку силы синих драконов пытаются взять эту магию под контроль.|n|nЭнергия поднялась из озера, в мгновение ока убив большинство жителей деревни. Те, кто выжили, сошли с ума.|n|n$N, тебе нужно освободить их души, чтобы они могли свободно двигаться. А свихнувшихся живых оставь в покое – может быть, они со временем придут в себя.', },
    {'Успокойте рыбаков, мистиков и воинов из деревни Инду\'ле (общим числом 15 противников), а затем вернитесь к старейшине Мана\'лоа в деревню Инду\'ле.', },
  },
  [12032] = {
    'Разговор с бездной',
    {'Нужно посоветоваться с богиней воды, Оача\'ноа, только она может знать, какая судьба ожидает калу\'аков. И лишь Жемчужина Бездны может вызвать ее из темных глубин.|n|nНа юго-западе, неподалеку от берега, возвышается Соленая вершина. На ней стоит алтарь, на алтаре – жемчужина.|n|nОбратись к алтарю, и Оача\'ноа услышит твой зов. Смотри, делай все, как она велит, не то навлечешь на себя ее гнев и погубишь всех клыкарров!|n|nЕсли выживешь, возвращайся к мистику.', },
    {'Обратитесь к Жемчужине Бездны и выполните распоряжения морской богини Оача\'ноа.|n|nЕсли вы переживете все испытания, вернитесь к Тоалу\'у Мистику в гавани Моа\'ки.', },
  },
  [12033] = {
    'Послание с запада',
    {'<Торвус пожимает вам руку, и одновременно сует в нее письмо.>|n|n<Говорит, не разжимая губ.>|n|nПодыграй мне, $N!|n|nРад видеть тебя здесь, солдат! Лорд Адский Крик, несомненно, отправил к лорду Агмару самых сильных своих бойцов!|n|n<Говорит, не разжимая губ.>|n|nПрочитай его, и тут же сожги в жаровне рядом со мной.', },
    {'Прочитайте письмо от Саурфанга и уничтожьте его.|n|nВыполнив это, поговорите с посланником Торвусом.', },
  },
  [12034] = {
    'Победа близка…',
    {'Теперь у нас на пути остаются лишь две основных угрозы. Одна – жуткая цитадель Наксрамас далеко на востоке, парящая над альянсовской крепостью Стражей Зимы, а вторая – Провал Наржуна, откуда появляются армии нежити Ажол-Неруба. Именно из Провала Наржуна появились нерубы – воины Ануб\'ара, которые атаковали и стерли с лица земли Ледяную Пыль, деревню таунка.|n|nМы уничтожим воинов Ануб\'ара и закроем Провал Наржуна!|n|nЯвись к главному сержанту Юктоку, он отдаст тебе соответствующие распоряжения.', },
    {'Поговорите с главным сержантом Юктоком в Молоте Агмара.', },
  },
  [12035] = {
    'Переналадка технологии',
    {'Да, теперь я понял! Перемонтаж – штука непростая, но $Gтакой умный:такая умная:r; |3-6($R), как ты, разберется.|n|nВозьми мои инструменты и обесточь несколько сборщиков урожая. Когда они придут в нерабочее состояние, используй инструменты, чтобы воткнуть все красные провода в синие розетки. Это должно перевести сборщиков в режим самообороны. Поспеши, $N. А то еще немного – и будет нечего спасать.', },
    {'По поручению Иеремии Хоунинга обезвредьте 5 сборщиков урожая, а затем воспользуйтесь инструментами Иеремии, чтобы перемонтировать их.', },
  },
  [12036] = {
    'Глубины Азжол-Неруба',
    {'Нерубы, напавшие на деревню Ледяной Пыли, явились из гигантской воронки, известной как Провал Наржуна. Если их оставить в покое, эти кошмарные твари, несомненно, обойдут с флангов наши силы у Врат Гнева и станут серьезной преградой на нашем пути к победе.|n|nМне нужны глаза на земле, $N. Ты направишься на запад и обследуешь Провал Наржуна. Нам нужно вычислить их основную точку выхода и запечатать ее. Найди же эту точку.', },
    {'Исследуйте Провал Наржуна и возвращайтесь с данными к главному сержанту Юктоку, ожидающему у Молота Агмара.', },
  },
  [12037] = {
    'Спасательная операция',
    {'Орчихи – самые упрямые бабы на свете... ик. Ты со мной $Gсогласен:согласна;, |3-6($R)?|n|nВот, например, Курцель – столько лет уже работает с нами. Даже макака успела бы усвоить, как надо проворачивать дела. Нашел дурака делать за тебя самую опасную работу, а награду положил себе в карман. Неужели так сложно это понять?|n|nТак ведь нет... эта нетерпеливая зеленошкурая баба срывается с места и берет все в свои руки. Наверное, она уже мертва... но мне все равно как-то не по себе из-за того, что мы бросили ее одну. Жаль, что я не в том состоянии, чтобы прийти ей на помощь... ик!|n|n$GДружище:Подруга;, может быть, ты попробуешь ее отыскать?', },
    {'Мак из Гранитных ключей просит вас отправиться в Драк\'Тарон и узнать, все ли в порядке с Курцель.', },
  },
  [12038] = {
    'Пылающая Плеть',
    {'Чего ждем, |3-6($C)? Думаешь, эти тролли сами по cебе скопытятся?|n|nДавай-ка, за работу. Идешь на север, в Драк\'Тарон. Черпаешь грог и плещешь на этих мерзавцев...<ик>. А потом отбегаешь в сторонку и смотришь, как они будут гореть!', },
    {'Мак из Гранитных ключей просит вас поджечь 30 голодающих троллей Плети с помощью его грога.', },
  },
  [12039] = {
    'Черная кровь Йогг-Сарона',
    {'Ангратар, Врата Гнева… Я был свидетелем тому, как металл, удерживающий створки ворот, пульсировал и бился, будто живой! За 50 лет я никогда не видел, чтобы металл "дышал"…|n|nОб этом могут знать только клыкарры. Они называли это "черной кровью Йогг-Сарона" и предупреждали меня, чтобы я не приближался.|n|nЗа пределами деревни Ледяной Пыли, на запад от нее, есть воронка, называемая "Провалом Наржуна". Я слышал, что подобные воронки богаты этой странной рудой. Если путь твой лежит в ту сторону, можешь попробовать найти руду и принести мне несколько образцов?', },
    {'Принесите Борусу Железные Клещи из Молота Агмара на Драконьем Погосте 10 образцов черной крови Йогг-Сарона.', },
  },
  [12040] = {
    'Общий враг в лице Артаса',
    {'У нас гражданская война в разгаре. В самом сердце этого мира существа моего вида пытаются защититься от тотального уничтожения. Король-лич жаждет править царством Азжол-Неруба любой ценой. Несогласные объявляются врагами Плети и приговариваются к смерти.|n|nАртас – наш общий враг...|n|nПрисоединяйся к нашей кампании и очисти это место от скверны воинов Ануб\'ара! Пусть сам Ануб\'арак услышит их мучительные предсмертные крики!', },
    {'По заданию Киликса Разрушителя у Провала Наржуна на Драконьем Погосте убейте 6 ануб\'арских владык подземелий.', },
  },
  [12041] = {
    'Потерянная империя',
    {'Ты $Gдоказал, что готов:доказала, что готова; помочь империи Ажол в ее трудные времена – и, в таком случае, ажольская империя поможет Орде.|n|nОтнеси этот свиток своему вождю. Там перечислены сильные и слабые стороны нерубов, напавших на деревню Ледяной Пыли. Считай это жестом доброй воли – добровольным желанием помочь твоему народу. Воспользуйся знанием, зафиксированным на этих страницах, для того, чтобы сразить воинов Ануб\'ара – и ты сослужишь хорошую службу всем нам.|n|nПрощай, |3-6($R).', },
    {'Доставьте боевые планы Киликса командиру Агмару в Молот Агмара на востоке.', },
  },
  [12042] = {
    'Сердце древних',
    {'Тайны древности, откройтесь мне!|n|n<Дракуру смотрит через Глаз пророков.>|n|nО-о, меня ждет великая судьба, $N. Повезло тебе оказаться рядом со мной.|n|nАга! Вижу! Вижу Сердце древних! Ну, до него будет легко добраться...|n|nОно лежит рядом с трупом гоблина, в какой-то постройке, что рядом с рекой к востоку отсюда.', },
    {'Дракуру просит вас отправиться в самую верхнюю комнату Лесозаготовок Синего Неба и найти Сердце древних.', },
  },
  [12043] = {
    'Защита Лагеря Соплозабилось',
    {'Слышь, ты, |3-6($C)! Эта нежить к югу от нас просто до жути мешает нам работать. Сходи-ка зачисть там, а?', },
    {'Убейте 12 землекопов пустошей и одного надсмотрщика пустошей на раскопках, окружающих Покой Галакронда. Вернитесь к Нарфу в Лагерь Соплозабилось, когда задание будет выполнено.', },
  },
  [12044] = {
    'Припасти руды',
    {'Привет-привет! Силы Плети к югу отсюда выкапывают из земли какого-то древнего дракона. Мне абсолютно по барабану, какого лешего им это надо, но в процессе выкапывания они достают кучи композитной руды.|n|nПойди принеси мне немного такой руды. Эта руда будет подороже всего оружия, что в Орде изготавливают.', },
    {'Соберите 8 пригоршней композитной руды на раскопках, окружающих Покой Галакронда и принесите их Зинку в Лагерь Соплозабилось.', },
  },
  [12045] = {
    'Битый лед',
    {'Никогда тебя раньше не видела. Ты что, новичок в Погани? Очень приятно. Лишние рабочие руки никогда не помешают.|n|nДобудь мне материалы, я доделаю свою машину, загоним ее этим воякам и уедем домой богатыми!|n|nВообще-то все основные компоненты у меня уже есть, но мне недостает кое-каких материалов для снаряда. Нарф говорил, что из зазубренных осколков льда, полученных от северных элементалей, выйдет замечательная шрапнель. Добудь мне таких осколков, а?', },
    {'Соберите 4 горсти осколков льда от ледяных элементалей на севере и принесите их Живликс в Лагерь Соплозабилось.', },
  },
  [12046] = {
    'Мягкая оболочка',
    {'Мне нужна какая-то новая оболочка для этих разрывных бомб. Все, что у меня есть, слишком прочное, осколки не разлетаются при взрыве.|n|nЧто нам нужно, так это тонкая звериная шкура. Например, сгодятся туннельные йормунгары… или кондоры, которые роются в драконьих костях... Короче, принеси что найдешь.', },
    {'Соберите 12 тонких шкур животных, убив нужное количество туннельных йормунгаров или глодателей драконьих костей близ Лагеря Соплозабилось. Добыв шкуры, вернитесь с ними к Живликс.', },
  },
  [12047] = {
    'Нечто тугоплавкое',
    {'Нет-нет-нет! Эти ледяные осколки совершенно не годятся! Они растают, не успев никому причинить вреда! Чтоб я еще поверила Нарфу, когда речь идет о материалах! Значит, для изготовления шрапнели нужно что-то совершенно другое…|n|nЗнаю! Я гений! Осколки костей.|n|nТут повсюду валяются кости, йормунгары их постоянно точат. Попробуй найти для меня осколки, которые сгодятся в дело.', },
    {'Найдите среди драконьих костей к востоку от лагеря Соплозабилось 12 расколотых костей.', },
  },
  [12048] = {
    'Доспехи воинов Плети',
    {'Я из этой проклятущей руды ничего сделать не могу. Ничего держаться не будет! Несмотря на все мои усилия, металл Плети не гнется и не тянется!|n|nМожет быть, если бы у меня были образцы доспехов воинов Плети, я мог бы разобраться в процессе их изготовления.|n|nДеревня Ледяной Пыли кишит бронированными воинами Неруба. Иди принеси мне элементы доспехов воинов Плети! С твоей помощью я, должно быть, преуспею в изготовлении хоть чего-нибудь из этой руды.|n|nДеревня Ледяной Пыли находится к западу отсюда.', },
    {'Принесите 8 элементов доспехов воинов Плети Борусу Железные Клещи из Молота Агмара.', },
  },
  [12049] = {
    'Мясо с пылу с жару',
    {'Эти войска бесспорно нужно хорошенько накормить.|n|nЯ открою тебе один ма-а-аленький секрет, который $Gтакой брезгливый:такая брезгливая:r; |3-6($R), как ты, никогда не $Gузнал:узнала; бы самостоятельно... Эти йормунгарские черви по вкусу – что твои цыплята.|n|nИди, разозли одного из этих огромных неповоротливых йормунгаров, к востоку отсюда. Вряд ли тебе удастся убить такого, так что просто запихни вот это ему в глотку, когда он рот откроет. Принеси мне столько мяса, сколько дотащишь.', },
    {'К востоку от Лагеря Соплозабилось сразитесь с огромным йормунгаром – до тех пор, пока тот не откроет рот. Затем бросьте ему в глотку мощную взрывчатку. После взрыва соберите 6 кусков обугленного мяса йормунгара с земли и принесите их Зинку.', },
  },
  [12050] = {
    'Лесорубы',
    {'Теперь надо раздобыть древесины – Альянсу нужно много дерева для строительства башен! На юге растут кое-какие деревца, но для строительства куда больше подходят деревья на севере, на которых гнездятся гарпии.|n|nВозьми это. Когда придешь к месту гнездовий гарпий, нажми на кнопку, и к тебе явится один из моих крошшеров. Добудь как можно больше древесины! Конечно, гарпии будут против – но с ними ты, думаю, разберешься.|n|nВперед, за дело!', },
    {'Используйте пульт управления Крошшером Зинка, чтобы вызвать Крошшер, когда доберетесь до гнездовья гарпий на севере. Соберите 50 связок бревен и возвращайтесь к Зинку в Лагерь Соплозабилось.|n|nЕсли потеряете пульт управления Крошшером Зинка, поговорите с Зинком в Лагере Соплозабилось, чтобы получить новый.', },
  },
  [12051] = {
    'Выдирание перьев',
    {'Эти гарпии слишком долго замедляли получение нами прибылей! Убей их всех!', },
    {'По просьбе Нарфа из лагеря Соплозабилось убейте 20 гарпий к северо-западу от Лагеря Соплозабилось.', },
  },
  [12052] = {
    'Смерть гарпиям!',
    {'$C, ты это $Gвидел:видела;? Проклятая гарпия напала на наш груз, приготовленный к отправке к вратам! Кажется, я уже встречался с ней на Морозных высях.|n|nМы и так уже понесли значительные убытки из-за этих гарпий! Убей их всех!', },
    {'Убейте госпожу Морозной выси и 15 гарпий Морозной выси в горах к северо-западу от лагеря Соплозабилось. Когда задание будет выполнено, возвращайтесь к Нарфу.|n|nЕсли вам понадобится пульт управления крошшером Зинка, обратитесь к Зинку в Лагерь Соплозабилось.', },
  },
  [12053] = {
    'Мощь Орды',
    {'Таунка теперь – наши братья по оружию. Мы должны доказать им нашу солидарность и отвоевать деревню Ледяной Пыли.|n|nОна находится к западу от Молота Агмара, устроившись у подножья гор. Отправляйся туда и начни бой с нерубскими воинами Ануб\'ара! Установи наше ненаглядное знамя Орды в деревне Ледяной Пыли и уничтожь любого, кто попытается сорвать его!|n|nПусть ануб\'ары почувствуют мощь Орды! Пусть наше боевое знамя станет последней вещью, которую они увидят в жизни!', },
    {'Установите боевой штандарт клана Песни Войны в деревне Ледяной Пыли и защитите его от нападающих.|n|nЗатем верните боевой штандарт клана Песни Войны главному сержанту Юктоку в Молот Агмара на Драконьем Погосте.', },
  },
  [12054] = {
    'Расшифровать записи',
    {'Вор\'такх прав – мы не можем упустить такую возможность.|n|nК счастью, я знаю способ, как перевести дневник этого Бранна.|n|nШаманы племени Красного Клыка, обитающие в Святилище Кровавого Сердца к югу от лагеря, выращивают траву, известную как дыхание духа. Опытные мистики используют ее в качестве благовония, позволяющего входить в транс и советоваться с духами предков. |n|nНайди шамана Грумбальда Одноглазого. У него должен быть с собой запас травы для проведения обрядов в Урсоке.', },
    {'Принесите пучок дыхания духа ведунье Палуне в Лагерь Уанква.', },
  },
  [12055] = {
    'Странное приспособление',
    {'Взяв в руки это странное приспособление, вы сразу обретаете уверенность, что оно – магической природы. К сожалению, по его внешнему виду никак не определить, как и для чего это устройство используется.|n|nМожет быть, верховный маг в Покое Звезд на восток от Садов Лунного Покоя сможет сказать, для чего оно нужно?', },
    {'Отнесите странное устройство Горамоша проекции верховного мага Модеры в Покой Звезд.', },
  },
  [12056] = {
    'Приговорен к смерти: верховный сектант Зангус',
    {'Предательство произошло на моих глазах! Этот изменник повел воинов Ануб\'ара в атаку на крепость и погубил некоторых из моих лучших бойцов.|n|n<Горт горько качает головой.>|n|nОн все это время работал на Плеть, а мы и знать не знали! Сколько здесь еще таких, подобных Зангусу? Мы найдем их всех, а когда найдем...|n|n<Горт делает выразительный жест поперек шеи.>|n|nОднако Зангус возглавляет список. Наши разведчики докладывают, что он скрывается в Провале Наржуна, к западу отсюда. Найди его, убей и принеси мне его голову.', },
    {'Убейте верховного сектанта Зангуса и отнесите его голову капитану Горту в Молот Агмара на Драконьем Погосте.', },
  },
  [12057] = {
    'Сшитый плотью фолиант',
    {'Фолиант обтянут плотью и, кажется, из него сочится кровь. Просматривая его страницу за страницей, вы обнаруживаете, что они покрыты странными символами, похоже, написанными кровью.|n|nКакое бы знание ни было скрыто на этих страницах, оно может оказаться важным. Отнесите фолиант капитану Гортку в Молот Агмара, к востоку от деревни Ледяной Пыли.', },
    {'Доставьте сшитый плотью фолиант капитану Горту в Молот Агмара.', },
  },
  [12058] = {
    'Рунические пророчества',
    {'В журнале Бранна есть расшифровка некоторых символов железных дворфов. Я нацарапала их на краеугольном камне, чтобы ты с его помощью $Gсмог:смогла; перевести надписи на рунических дисках.|n|nСудя по прочим записям, Бранн пытался узнать, откуда произошла его раса. Постарайся понять, что открылось ему на этих табличках. |n|nВозвращайся в Тор Модан, что к северо-востоку отсюда, подойди к каждой табличке и воспользуйся краеугольным камнем. Нельзя допустить, чтобы Альянс нашел его прежде нас!', },
    {'Ведунья Палуна из Лагеря Уанква просит вас перевести надписи на трех Рунических дисках.', },
  },
  [12059] = {
    'Странное приспособление',
    {'Взяв в руки это странное приспособление, вы сразу обретаете уверенность, что оно – магической природы. К сожалению, по его внешнему виду не определить, как и для чего это устройство используется.|n|nВозможно, верховный маг в Молоте Агмара на северо-востоке от Садов Лунного Покоя сможет сказать, для чего оно нужно?', },
    {'Отнесите странное устройство Горамоша проекции верховного мага Этаса Похитителю Солнца в Молот Агмара.', },
  },
  [12060] = {
    'Проекты и проекции',
    {'Это устройство телепортации. Если бы мне пришлось угадывать, я сказала бы, что оно ведет к платформе-волнолову, плавающей над Садами Лунного Покоя, к западу отсюда.|n|nМне нужно, чтобы ты $Gиспользовал:использовала; его для того, чтобы разведать, что там творится. Похоже, устройство работает в обоих направлениях, так что у тебя не предвидится проблем с возвращением.|n|nЯ думаю, что когда ты переместишься на вершину волнолова, там будет некий аппарат, который нужно будет изучить.|n|nТелепортироваться обратно ты сможешь из любой точки в пределах Садов.', },
    {'Подберитесь поближе и обследуйте конструкцию на вершине волнолова, плавающего в воздухе над Садами Лунного Покоя.|n|nПосле этого возвращайтесь с полученной информацией к проекции верховного мага Модеры в Покой Звезд.', },
  },
  [12061] = {
    'Проекты и проекции',
    {'Это устройство телепортации. Если бы мне пришлось угадывать, я сказал бы, что оно ведет к платформе-волнолову, плавающей над Садами Лунного Покоя, к юго-западу отсюда.|n|nМне нужно, чтобы ты $Gиспользовал:использовала; его для того, чтобы разведать, что там творится. Похоже, устройство работает в обоих направлениях, так что у тебя не предвидится проблем с возвращением.|n|nЯ думаю, что когда ты переместишься на вершину волнолова, там будет некий аппарат, который нужно будет изучить.|n|nТелепортироваться обратно ты сможешь из любой точки в пределах Садов.', },
    {'Подберитесь поближе и обследуйте конструкцию на вершине волнолова, плавающего в воздухе над Садами Лунного Покоя.|n|nПосле этого возвращайтесь с полученной информацией к проекции верховного мага Этаса Похитителя Солнца в Молот Агмара', },
  },
  [12062] = {
    'Оскорбить Корена Худовара',
    {'Корен Худовар сидит в соседней комнате, вынашивает очередные планы нападения дворфов Черного Железа на Хмельной фестиваль. Ты $Gдолжен:должна; его остановить!|n|nИди к Корену и разозли его хорошенько. Например, можешь сказать ему, что его пивом даже свинья побрезгует.|n|nА после этого приготовься к драке! Последний храбрец, осмелившийся раскритиковать его пиво... пошел на корм диким кабанам.', },
    {'Поговорите с Кореном Худоваром.', },
  },
  [12063] = {
    'Сила Ледяной Пыли',
    {'<Великая мать Ледяная Пыль кланяется.>|n|nДля меня честь познакомиться с тобой, $Gнаш герой:наша героиня;. Именно благодаря твоим действиям нас здесь сейчас так много – живых-здоровых и готовых к битве против сил Плети.|n|nТы так много $Gсделал:сделала; для нас, что мне стыдно еще раз просить тебя о содействии. Несмотря на мои мольбы, мой единственный сын, Банток, ушел на поиски своего отца, верховного вождя Ледяной Пыли. В последний раз его видели направляющимся на запад, к деревне Ледяной Пыли. Я не знаю, что со мной будет, если я потеряю сына...', },
    {'Найдите Бантока Ледяную Пыль в окрестностях деревни Ледяной Пыли.', },
  },
  [12064] = {
    'Ануб\'арские оковы',
    {'Принесите Бантоку Ледяной Пыли, ожидающему у деревни Ледяной Пыли на Драконьем Погосте, фрагмент ключа Анок\'ры, фрагмент ключа Тивакса и фрагмент ключа Синока.', },
    {'Принесите Бантоку Ледяной Пыли, ожидающему у деревни Ледяной Пыли на Драконьем Погосте, фрагмент ключа Анок\'ры, фрагмент ключа Тивакса и фрагмент ключа Синока.', },
  },
  [12065] = {
    'Фокусы на взморье',
    {'Силы охотников на магов проявляют активность на Сверкающем взморье, к югу от Садов Лунного Покоя. Я так полагаю, что ты обнаружишь на берегу хорошо охраняемый фокус и командира, отвечающего там за все.|n|nНесомненно, у него или у нее будет при себе некое контролирующее устройство. Раздобудь его и используй на средоточии.|n|nЕсли получится, мы сможем получить дополнительную информацию о том, что они там на самом деле замышляют.', },
    {'Добудьте кольцо управления средоточием силовых линий и воспользуйтесь им для получения информации о средоточии силовых линий на Сверкающем взморье.|n|nЗатем вернитесь к проекции верховного мага Модеры в Покое Звезд.', },
  },
  [12066] = {
    'Фокусы на взморье',
    {'Силы охотников на магов проявляют активность на Сверкающем взморье, к югу от Садов Лунного Покоя. Я так полагаю, что ты обнаружишь на берегу хорошо охраняемый фокус и командира, отвечающего там за все.|n|nНесомненно, у него или у нее будет при себе некое контролирующее устройство. Раздобудь его и используй на средоточии.|n|nЕсли получится, мы сможем получить дополнительную информацию о том, что они там на самом деле замышляют.', },
    {'Добудьте кольцо управления средоточием силовых линий и воспользуйтесь им для получения информации о средоточии силовых линий на Сверкающем взморье.|n|nЗатем вернитесь к проекции верховного мага Этаса Похитителя Солнца в Молот Агмара.', },
  },
  [12067] = {
    'Письмо домой',
    {'Вы находите письмо, упрятанное под подкладку еe одеяния. Оно гласит:|n|n"Отец,|n|nПрости меня за то, что я исчезла. Если ты читаешь это письмо – значит, я мертва.|n|nМеня заставили работать на армию Малигоса угрозами, что нашу семью убьют, если я этого не сделаю. Мне так стыдно!|n|nЕсли можешь сделать хоть что-нибудь, чтобы сражаться с ними, не думай обо мне. Я их одурачила и наношу им вред изнутри.|n|nЯ люблю тебя, папа!|n|nЭм"|n|nЭто письмо нужно непременно показать командиру Сайа Лазурная Сталь!', },
    {'Доставьте письмо капитана Малин командиру Сайе Лазурной Стали в Покой Звезд.', },
  },
  [12068] = {
    'Голоса прошлого',
    {'<Дракуру кладет Око пророка себе на лоб, а Сердце древних – на грудь.>|n|nМы уже почти достигли цели, дружок!|n|nОсталось только найти скрижали Драккари. Никто не знает, когда они были написаны, и что именно они гласят, но око и сердце Дракуру помогут расшифровать послание. А лежат они глубоко в склепе Дракил\'джин, что к востоку отсюда. |n|nКак только найдешь скрижали, забери священный настой у оракулов и заступников. С его помощью ты сможешь призвать меня к себе. Не переживай – они будут счастливы умереть во имя благого дела.', },
    {'Дракуру просит вас собрать скрижали Драккари в Руинах Дракил\'джин и отобрать 5 священных настоев у оракулов и заступников Драккари. Затем вам надо будет выпить эликсир Дракуру возле жаровни в руинах, чтобы призвать его дух.', },
  },
  [12069] = {
    'Возвращение верховного вождя',
    {'<Банток протягивает вам ключ от тюрьмы.>|n|nТоропись, $N! Возьми этот ключ и выпусти моего отца из ануб\'арской темницы! Когда он будет свободен, помоги ему уничтожить предводителя Ануб\'ара, короля подземелий Ануб\'ет\'кана. Когда король подземелий будет повержен, отруби кусок его хитинового панциря и отнеси его, как трофей, в Молот Агмара. Пусть Агмар узрит мощь верховного вождя!', },
    {'Освободите верховного вождя Ледяную Пыль с помощью ключа от ануб\'арской темницы и помогите ему одолеть короля подземелий Ануб\'ет\'кана.|n|nДобудьте кусок панциря Ануб\'ет\'кана и вернитесь с ним к командиру Агмару в Молоте Агмара в Драконьем Погосте.', },
  },
  [12070] = {
    'Второе дыхание',
    {'Дети железа подчиняют своими рунами моих братьев и посылают их на штурм Тор Модана. Как бы я хотел избежать братоубийства... но у нас нет другого выхода.|n|nМоим великанам не выстоять против них.|n|nЯ зарядил этот осколок земли великой силой, которая поможет нашим союзникам. Отнеси его на поле боя в Каменистые холмы и помоги моим братьям.|n|nУбивай любого железного дворфа, что осмелится встать у тебя на пути.', },
    {'Воспользуйтесь осколком земли, чтобы излечить великанов с Седых холмов, сражающихся в Каменистых холмах, убейте всех железных дворфов, что осмелятся встать у вас на пути, и вернитесь к Куруну на холм, возвышающийся над Тор Моданом.', },
  },
  [12071] = {
    'Ударим с воздуха!',
    {'Они уже видели, какова мощь Орды на земле, теперь пусть почувствуют, какова она в небе! Я хочу, чтобы ты немедленно $Gдоложился:доложилась; Вальноку Ветрояру. Он здесь, в Молоте Агмара.|n|nВальноку уже даны указания насчет твоей миссии, он ждет тебя.', },
    {'Поговорите с Вальноком Ветрояром в Молоте Агмара.', },
  },
  [12072] = {
    'Будь прокляты эти чумные звери!',
    {'Без сомнения, ты $Gвидел:видела; армию ануб\'арских гнилостных зверей, которых создают в деревне Ледяной Пыли. У ануб\'арцев есть планы послать этих монстров против наших солдат у Врат Гнева. Этого не должно произойти!|n|nОтправляйся на запад, в деревню Ледяной Пыли, с этим световым ружьем и воспользуйся им, чтобы вызвать одного из моих боевых наездников. Заберись к нему на спину и прикажи уничтожить гнилостных зверей, до которых нельзя дотянуться с земли.|n|nКогда достаточно проредишь их воздушные силы, возвращайся ко мне за наградой!', },
    {'С помощью сигнального ружья Вальнока вызовите в деревню Ледяной Пыли кор\'кронскую боевую виверну. Воспользовавшись ею, убейте 25 ануб\'арских гнилостных зверей!|n|nЕсли выполните задание, возвращайтесь к Вальноку Ветрояру в Молот Агмара.', },
  },
  [12073] = {
    'Куй железо, пока горячо',
    {'Солдаты Альянса – не единственные наши противники в Седых холмах. Все восточное побережье удерживают железные дворфы, а Тор Модан на северо-востоке захвачен каменными великанами.|n|nНо умелый воин никогда не упустит возможность воспользоваться слабостью врага. Железные дворфы ослаблены стычками в Тор Модане, и потому наиболее уязвимы. Не давай им пощады, $N. Убивай каждого дворфа, ставшего у тебя на пути. |n|nПусть сыны железа научатся бояться Орды.', },
    {'Убейте 10 любых железных дворфов, охраняющих Тор Модан, после чего доложите разведчику Вор\'такху из Лагеря Уанква об успешном выполнении его поручения.', },
  },
  [12074] = {
    'Удобный союзник',
    {'Древнюю столицу железных дворфов, Тор Модан, что далеко на северо-востоке отсюда, осадили войска таинственных каменных и земляных великанов.|n|nМеня мало интересуют разборки между детьми титанов, но Орде не стоит упускать шанс сокрушить железных дворфов силами других рас.|n|nОтправляйся в Тор Модан и поговори с этим \'Куруном\', возглавляющим армию великанов и служителей земли. Расскажи ему о наших интересах и предложи свою помощь в войне против железных дворфов.', },
    {'Поговорите с Куруном, который стоит на вершине холма рядом с Тор Моданом.', },
  },
  [12075] = {
    'Образец каменной плоти',
    {'Холодно тут, да, |3-6($R)?|n|nКо\'чар отказался со мной встречаться. Похоже, у него голова сейчас другим занята. Я про йормунгаров, кишащих в пещере внизу. Может быть, ты поможешь мне убедить Ко\'чара, что я хороший парень?|n|nЯ видел великана, которого черви жрали у входа в пещеру к северу отсюда... Ума не приложу, как червям удалось его так легко одолеть. Принеси мне образец ткани из раны этого великана.', },
    {'Возьмите образец каменной плоти с тела ледяного великана у входа в пещеру в ущелье Порочных Кристаллов, к северу от места, где стоит Зорт. Выполнив это задание, вернитесь к Зорту, ожидающему вас у центра каньона.', },
  },
  [12076] = {
    'Грязное дело',
    {'С первого взгляда могу сказать, что принесенный тобой образец носит следы воздействия чьей-то едкой слюны. Естественно будет предположить, что вещество, с помощью которого эти змеи прокладывают себе путь в земле, является в то же время превосходным оружием против ледяных великанов! Возьми этот скребок и вступи в схватку с несколькими змеями. Когда они плюнут в тебя, соскреби слюну с помощью скребка и принеси мне.|n|nМне нужна как минимум пара образцов – я собираюсь использовать эту слюну как основу для эликсира.', },
    {'Соберите два фиала едкой слюны йормунгаров с помощью скребка. Выполнив задачу, принесите сосуды Зорту в ущелье Порочных Кристаллов.', },
  },
  [12077] = {
    'Употреблять дважды в день',
    {'Этот эликсир должен защищать от их плевков. Предложи его Ко\'чару от моего имени, ладно? И скажи, что у меня этого добра еще много – если только он согласится оказать мне ответную услугу.', },
    {'Предложите приготовленный Зортом эликсир Ко\'чару Неуязвимому.', },
  },
  [12078] = {
    'Червячный наездник',
    {'Так и быть. Если великаны не придут к нам на помощь, мы можем использовать этих червей. Они наверняка есть в пещере, вместе с маткой. Возьми эту коробку, поймай 3 штуки и принеси мне.|n|nКогда дипломатия терпит неудачу, отличной альтернативой становится порабощение.', },
    {'Отправляйтесь в пещеры в ущелье Порочных кристаллов и заманите 3 порождения йормунгаров в крепкие ящики. Не забудьте собрать ящики, когда порождения йормунгаров окажутся в них!|n|nПринесите пойманные порождения йормунгаров Зорту в ущелье Порочных кристаллов.', },
  },
  [12079] = {
    'Излюбленное место червяков',
    {'Привет, $Gмалец:малявка;. Не знаю, что за безумие привело тебя в пещеру порочных кристаллов, но – добро пожаловать ко мне.|n|nЭти ледяные черви… эти йормунгары, они повадились есть моих собратьев. Сомневаюсь, что в это жестокое время ты найдешь мне подобных хоть сколько-нибудь дружелюбными, но если ты здесь для того, чтобы помочь мне с червями, я буду благосклонен к тебе.|n|nЕсли мы хотим отвоевать эту пещеру, для начала нужно очистить каньон от воспитателей йормунгаров. Присоединяйся, |3-6($R)!', },
    {'Отправляйтесь в пещеру у северной оконечности ущелья Порочных кристаллов и убейте по поручению Ко\'чара Неуязвимого 8 йормунгаров-трутней Ледяного Сердца.', },
  },
  [12080] = {
    'Вот это червяк!',
    {'Там, в пещерах, живет матка йормунгаров. Мы зовем ее Грохотуньей – это имя дал ей один искатель приключений из Чумных земель. Я видел ее только мельком, отражая их первоначальный натиск. Она так огромна, что даже у меня пробежал мороз по жилам. Эта пещера не будет нашей, пока тут обитает она!|n|nСобери друзей и покончи с ней.', },
    {'Войдите в пещеру Ледяного Сердца и убейте Грохотунью. Не забудьте использовать защитный эликсир Зорта, чтобы спастись от едких плевков йормунгаров – если, конечно, этот эликсир у вас еще есть.|n|nВыполнив задачу, вернитесь к Ко\'чару Неуязвимому в ущелье Порочных кристаллов.', },
  },
  [12081] = {
    'Гаврок',
    {'Если бы не ты, нам не удалось бы переломить ход сражения за Тор Модан в нашу пользу. Этот древний город давно уже стал полем битвы для сил земли и камня, и нам остается лишь надеяться, что на сей раз наша победа была окончательной.|n|nНо железные дворфы все еще пользуются своей силой, чтобы порабощать моих братьев. Гаврок пытается отыскать способ освободить рунических великанов. Ты найдешь его на маленьком скоплении островов посреди Побережья Восточного Ветра на юге. Это место зовется Руины Тетиса. Поспеши!', },
    {'Поговорите с Гавроком в Руинах Тетиса.', },
  },
  [12082] = {
    'Дун-да-Дун-та!',
    {'Слушай, $Gмалыш:малышка; тут тебе не площадка для игр.|n|nЯ собираюсь уносить отсюда ноги. Держись рядом со мной, и я выведу нас на волю.', },
    {'Сопроводите Харрисона по пути из руин Дракил\'джин, после чего поговорите с Харкором в лагере Харкора.', },
  },
  [12083] = {
    'В лесах',
    {'Я уверена, что существует еще несколько средоточий силовых линий, и каждое из них каким-то образом перенаправляет энергию. Но что они делают со всей этой энергией, до сих пор доподлинно не известно.|n|nЯ подозреваю, что еще одно средоточие можно найти в глубине Лоталорского редколесья на юго-востоке. Тебе снова понадобится отыскать главного и отобрать у него управляющее устройство – для каждого средоточия оно свое.|n|nБудь осторожнее, $N, эти леса очень опасны!', },
    {'Добудьте амулет управления средоточием силовых линий и используйте его для получения сведений о средоточии силовых линий в Лоталорском редколесье.|n|nПосле этого вернитесь к проекции верховного мага Модеры в Покое Звезд.', },
  },
  [12084] = {
    'В лесах',
    {'Я уверен, что существует еще несколько средоточий силовых линий, и каждое из них каким-то образом перенаправляет энергию. Но что они делают со всей этой энергией, до сих пор доподлинно не известно.|n|nЯ подозреваю, что еще одно средоточие можно найти в глубине Лоталорского редколесья на юге. Тебе снова понадобится отыскать главного и отобрать у него управляющее устройство – для каждого средоточия оно свое.|n|nПоторопись, |3-6($C)! У меня такое ощущение, что время на исходе!', },
    {'Добудьте амулет управления средоточием силовых линий и воспользуйтесь им для получения сведений от средоточия силовых линий в Лоталорском редколесье.|n|nЗатем вернитесь к проекции верховного мага Этаса Похитителя Солнца в Молот Агмара.', },
  },
  [12085] = {
    'Письмо домой',
    {'Вы находите письмо, упрятанное под подкладку его одеяния. Оно гласит:|n|n"Дейно,|n|nТа\'зинни просит прощения за исчезновение. Если ты это читаешь, то я мертв.|n|nМеня заставили работать на армию Малигоса угрозами, что иначе мою семью убьют. Та\'зинни не мог допустить такое!|n|nНе беспокойся за меня, главное – береги детишек. Я дурю врагов и наношу им вред изнутри.|n|nЯ люблю тебя, сестренка!|n|nТа\'зинни"|n|nЭто письмо нужно непременно показать командиру Агмару!', },
    {'Отнесите письмо лейтенанта Та\'зинни командиру Агмару в Молот Агмара.', },
  },
  [12086] = {
    'Сын Каркута',
    {'Человек, которого ты ищешь, ушел далеко на восток, к месту на побережье, называемому Стоянка Смерти, за Уну\'пе.|n|nСоблюдай осторожность, если собираешься идти искать его, $N. На нем – знак Каркута... того, кто наблюдает за мертвыми.', },
    {'Идите на восток к Стоянке Смерти, находящейся сразу за Уну\'пе.', },
  },
  [12087] = {
    'Немного помочь? DEPRECATED',
    {'Нас послали сюда, чтобы захватить Воющий зиккурат к северу отсюда. Мы уже не чаяли вернуться живыми… половину отряда потеряли!|n|nТам был Тассариан и другие… в общем, он им чем-то не понравился.|n|nОн ушел сегодня утром… возможно, отправился к зиккурату в одиночку. Но сейчас у нас есть более неотложные проблемы. Плеть все ближе к лагерю, и с ними надо разобраться – немедленно!', },
    {'Убейте 8 защитников зиккурата по просьбе капрала Венна со Стоянки Смерти.', },
  },
  [12088] = {
    'Тассариан, рыцарь Смерти',
    {'Ну что ж, $N, ты $Gпомог:помогла; нам, будет только справедливо, если мы поможем тебе.|n|nТы ищешь Тассариана? Он исчез сегодня утром. Мы думаем, он отправился на север, к Стонущему зиккурату. Если бы нам не доводилось сражаться плечом к плечу, мы бы даже подумали, что он предатель...|n|nВидишь ли, он – рыцарь Смерти. Я знаю, что они на нашей стороне, и все такое... но еще не так давно они были слугами Артаса.|n|nКто угодно, но только не Тассариан. Он славный малый. Ступай в Стонущий зиккурат, проверь, все ли с ним в порядке.', },
    {'Отыщите Тассариана внутри Стонущего зиккурата, к северу от Стоянки Смерти.', },
  },
  [12089] = {
    'Разыскивается: магистр Кельдонус!',
    {'По велению командира Агмара приказано выследить магистра Кельдонуса.|n|nОн обвиняется в предательстве. На данный момент он жив.|n|nМагистра Кельдонуса, бывшего мага-командира Молота Агмара, надлежит убить на месте во имя Орды.|n|nВ последний раз его видели, когда он направлялся на юго-запад, в сторону садов Лунного Покоя, чтобы присоединиться к синим драконам в их борьбе против магии.|n|nСледует соблюдать осторожность: Кельдонус весьма могущественный маг. В одиночку в бой не ввязываться!|n|nНаграду за его убийство можно получить у капитана Горта в Молоте Агмара.', },
    {'Убейте магистра Кельдонуса и вернитесь к капитану Горту в Молот Агмара в Драконьем Погосте.', },
  },
  [12090] = {
    'Разыскивается: Гигантавр',
    {'Убейте Гигантавра и приходите за вознаграждением к капитану Горту в Молоте Агмара на Драконьем Погосте.', },
    {'Убейте Гигантавра и приходите за вознаграждением к капитану Горту в Молоте Агмара на Драконьем Погосте.', },
  },
  [12091] = {
    'Разыскивается: Коготь Ужаса',
    {'Указ командира Агмара!|n|nПриговаривается: Коготь Ужаса|n|nПреступление: нападения на Орду.|n|nСтатус: жив|n|nКогтежут разыскивается за многократные нападения на караваны Орды, идущие в Ядозлобь и из Ядозлоби.|n|nОбиталище Когтя Ужаса – на утесе, возвышающемся над Рубиновым святилищем драконов, к востоку от Молота Агмара. Приближайтесь со всей возможной осторожностью! Не пытайтесь справиться с ним в одиночку!|n|nВознаграждения выплачиваются капитаном Гортом в Молоте Агмара.', },
    {'Убейте Когтя Ужаса и вернитесь за вознаграждением к капитану Горту в Молот Агмара на Драконьем Погосте.', },
  },
  [12092] = {
    'Усиление древняков',
    {'То, что натворили синие драконы, затрагивает не только твою расу. Затронуло оно и древняков Лоталорских лесов.|n|nНекоторые оказались подвергнуты порче – остерегайся их во что бы то ни стало! – но остальных, их большинство, еще можно спасти. Однако лесные древни, кажется, оказались невосприимчивы к магии, текущей по этим землям, и волшебным змеям, пришедшим вместе с ней.|n|nПопроси у древней их кору и скорми ее древнякам. Надеюсь, этого будет достаточно, чтобы их спасти.', },
    {'Воспользуйтесь корой древня для усиления 3 древ Лоталора, а затем вернитесь к Сарендриане в Покой Звезд.', },
  },
  [12093] = {
    'Руны порабощения',
    {'Несмотря на то, что Курун выступил против Тор Модана, железные дворфы продолжают порабощать наших братьев. Они призывают их из земли, сковывают рунами и принуждают их воевать против детей камня.|n|nПовсюду вдоль Побережья Восточного Ветра бродят подневольные великаны, принуждаемые отправиться на поля сражений. |n|nНайди четыре руны порабощения и заставь проклятых надзирателей ответить за преступления против моих братьев, убив четырех руноплетов, создавших эти руны. Без надзирателей эти руны потеряют силу.', },
    {'Гаврок с Руин Тетиса просит вас отключить четыре руны порабощения, убив надзирателя Дюрваля, надзирателя Коргана, надзирателя Лочли и надзирателя Брунона.', },
  },
  [12094] = {
    'Спящая сила',
    {'Пока руны подчинения бездействуют, у нас есть шанс освободить рунических великанов.|n|nЯ дам тебе кусок камня, который был частью меня с самого рождения. Если его правильно зарядить, ты сможешь освободить пленных великанов.|n|nМеста скопления силы отмечены тремя древними камнями. Два из них стоят между Путем Железа и лесной опушкой, отмечая пересечение силовых линий, как называет это место твой народ. А третий камень возвышается на южном краю острова, среди руин. Заряди мой камень у этих монолитов и возвращайся ко мне.', },
    {'Зарядите осколок Гаврока у первого, второго и третьего древних камней, после чего вернитесь к Гавроку в Руины Тетиса.', },
  },
  [12095] = {
    'В Драконью Погибель',
    {'К востоку отсюда, в самом сердце Драконьего Погоста, есть равнина, где нет ничего – только снег и кости драконов. Плеть устроила в центре тундры многочисленные лагеря, и теперь создает ледяных змеев, которых насылает на наши войска у Врат Гнева. С большинством из этих змеев без труда справляется Рокхан и его охотники на драконов, но вот один из них доставляет нам немало хлопот.|n|nСтупай на северо-восток и найди Рокхана в Драконьей Погибели. Помоги ему и его воинам убить Сарастру, и тебя щедро наградят!', },
    {'Поговорите с Рокханом в Драконьей Погибели в Драконьем Погосте.', },
  },
  [12096] = {
    'Усиление древняков',
    {'На древняков Лоталорских лесов к югу отсюда наводят порчу волшебные змеи... змеи, что восстали из земли!|n|nТе, кто уже подвергнуты порче, с теми мы ничего не можем поделать, но остальных – а их большинство – еще можно спасти. К счастью, лесные древни, кажется, оказались невосприимчивы к магии, текущей по этим землям, и волшебным змеям, пришедшим вместе с ней.|n|nПопроси у древней их кору и скорми ее древнякам. Это усилит их.|n|nА мне дай заняться своими делами. Мне нужно приглядывать за этими аптекарями!', },
    {'Воспользуйтесь корой древня для усиления 3 древ Лоталора, а затем вернитесь к хранителю земли Грифу в Молот Агмара.', },
  },
  [12097] = {
    'Сарастра, бич Севера',
    {'Мои охотники или померли, или от холода окочурились, $N. Только ты и твои друзья, кого с собой приведешь, больше рассчитывать не на кого. Все еще хочешь этим дельцем заняться? Скажи только слово – и я еще раз позову дракона, да.|n|nЕсли убьешь его, возьми его ледяное сердце, отнеси в Молот Агмара и преподнеси Горту. Он тебя, $Gдружок:сестренка;, хорошо наградит – это как пить дать.', },
    {'Поговорите с Рокханом, чтобы призвать ледяного змея Сарастру.|n|nУбейте змея и отнесите ледяное сердце Сарастры капитану Горту в Молот Агмара.', },
  },
  [12098] = {
    'Поиски в деревне Инду\'ле',
    {'Я уверена, что следующее средоточие силовой линии ты обнаружишь где-нибудь в развалинах деревни Инду\'ле к юго-востоку отсюда. Проблема в том, что у меня нет совершенно никаких сведений о том, что оно там.|n|nМне нужно, чтобы ты $Gотправился:отправилась; туда и $Gобследовал:обследовала; деревню и окрестности в поисках признаков средоточия или охотников на магов и их командира.|n|nИщи даже в озере, если придется!', },
    {'Поищите командующего силами охотников на магов в деревне Инду\'ле и озере Инду\'ле.', },
  },
  [12099] = {
    'Долгожданная свобода',
    {'Надеюсь, этот заряженный камень сможет рассеять магию рун, пленившую моих братьев.|n|nВозьми его с собой и отправляйся на поиски рунических великанов, что бродят на востоке вдоль Побережья Восточного Ветра. Освободи силу, заключенную в камне, и проследи за великанами. |n|nЕсли все пойдет, как задумано, они придут в себя и перестанут подчиняться железным дворфам. Но если камень не сработает, великаны набросятся на тебя. Даже ослабленные магией, они очень опасны. Но другого пути нет – не можем же мы обречь их на вечное рабство!', },
    {'Воспользуйтесь Руноломом Гаврока, чтобы освободить четырех рунических великанов, после чего вернитесь к Гавроку в Руины Тетиса.', },
  },
  [12100] = {
    'Сдерживание гнили',
    {'Рука об руку с Плетью идут смерть и болезнь. Мы часто упускаем из виду, что фауна зараженных Плетью районов в ужасном состоянии и сильно повреждена гнилью и заразой.|n|nДля многих местных животных уже слишком поздно. Терзающая зараза, которую распространяет Плеть, уже поразила их, и теперь эти звери гниют и больны бешенством.|n|nПридется тебе отправиться на запад, к Провалу Наржуна, и уничтожить пораженных животных. Поищи на их телах неповрежденный орган – он нужен нам для изготовления вакцины.', },
    {'По заданию Соара Ярости Ястреба из Молота Агмара на Драконьем Погосте убейте 15 зараженных тварей и добудьте орган сопротивления гниению.', },
  },
  [12101] = {
    'Добрый доктор...',
    {'Отнесите орган сопротивления гниению доктору Синтару Злобениусу в Молот Агмара.', },
    {'Отнесите орган сопротивления гниению доктору Синтару Злобениусу в Молот Агмара.', },
  },
  [12102] = {
    'В поисках рубиновой сирени',
    {'Как это неожиданно и хорошо, что Рубиновое святилище драконов находится совсем рядом, на восток отсюда. Там ты и найдешь цветок, который называют рубиновой сиренью. Это животворное растение – единственное, что мне нужно, чтобы изготовить вакцину для неоскверненных животных в этих землях.|n|nОтправляйся на восток и поищи в Рубиновом святилище драконов эту сирень.|n|nИмей в виду только одно: это святилище драконов, как и все остальные, занято силами Плети. Будь $Gосторожен:осторожна;. Мы не хотели бы, чтобы тебя сожрал тлеющий змей.|n|n<Синтар смеется.>', },
    {'Принесите 1 цветок рубиновой сирени доктору Синтару Злобениусу в Молот Агмара на Драконьем Погосте.', },
  },
  [12103] = {
    'ИСКЛЮЧЕНО',
    {'Все, хватит с меня, $N. Мы должны сделать так, чтобы зараза из Среброречья не распространилась по всему континенту.|n|nМне все равно, что стало причиной этой напасти – отравленная вода или древнее тролльское проклятие, от которого сошла с ума вся деревня. Эти жители опасны для окружающих! Возвращайся в Среброречье и покончи с ними.', },
    {'Капитан Деррик из Приюта Янтарной Сосны просит вас убить 8 селян Среброречья и 8 звероловов Среброречья.', },
  },
  [12104] = {
    'Вакцина для Соара',
    {'<Доктор Злобениус передает вам сосуд, наполненный мутной жидкостью.>|n|nНу, вот |3-6($R). Отнеси это бычаре и скажи, что все долги выплачены. Мы с ним официально в расчете.|n|nА теперь иди отсюда, пока я Дженнингса на тебя не напустил.', },
    {'Отнесите вакцину Синтара Соару Ярости Ястреба в Молот Агмара.', },
  },
  [12105] = {
    'Погружение во мрак',
    {'Этот дневник вел житель Среброречья по имени Михаил. В нем описывается появление некоей темной секты, называющей себя "Культ Волка".|n|nЖители деревни с подозрением отнеслись к новой секте, но потом симпатии обитателей деревни резко изменились.|n|nНастороженный столь внезапными переменами, Михаил отправил свою старшую дочь Сашу подальше от Среброречья. Сам же он остался в деревне, надеясь переубедить своих соплеменников.|n|nВ последней записи дневника говорится о городском собрании, на котором должны были обсуждаться странные явления на Руднике Полого Камня.', },
    {'Отнесите дневник Михаила лейтенанту Думонту в Приют Янтарной Сосны.', },
  },
  [12106] = {
    'Поиски в деревне Инду\'ле',
    {'Я уверен, что следующее средоточие силовой линии ты обнаружишь где-нибудь в развалинах деревни Инду\'ле к юго-востоку отсюда. Проблема в том, что у меня нет совершенно никаких сведений о том, что оно там.|n|nМне нужно, чтобы ты $Gотправился:отправилась; туда и $Gобследовал:обследовала; деревню и окрестности в поисках признаков средоточия или охотников на магов и их командира.|n|nИщи даже в озере, если придется!', },
    {'Поищите командующего силами охотников на магов в деревне Инду\'ле и озере Инду\'ле.', },
  },
  [12107] = {
    'Конец цепочки',
    {'В его одеяниях вы находите две интересных вещи.|n|nВо-первых, талисман, который явно представляет собой устройство для управления фокусом. А во-вторых, несколько приказов от некоего Сидрагоса, предназначенных предводителю в садах Лунного Покоя.|n|nВетхий промокший пергамент извещает Горамоша, что ему следует перевести всех охотников за магами на восток, к Лазуритовому святилищу драконов.|n|nБыть может, следует добыть из фокуса все сведения, какие можно, и отправиться на восток, чтобы понаблюдать за драконьим святилищем с западного уступа?', },
    {'Используйте талисман управления средоточием силовых линий, чтобы получить сведения о средоточии силовых линий под озером Инду\'ле. Затем отправляйтесь на восток, к Лазуритовому святилищу драконов, расположенному почти в центре южного Драконьего Погоста, и с западного уступа понаблюдайте за тем, что там происходит.|n|nПосле этого вернитесь к проекции верховного мага Модеры в Покое Звезд.', },
  },
  [12108] = {
    'ИСКЛЮЧЕНО',
    {'Эта куча земли очень похожа на спешно зарытую могилу. Лежащее под ней тело опознать невозможно, но вы обнаруживаете записку, которая адресована некоему Михаилу.|n|nВ записке также встречается очередное упоминание Рудника Полого Камня. Возможно, кто-то из Приюта Янтарной Сосны может пролить свет на это дело.', },
    {'Принесите дневник Михаила картограферу Тобиасу в Приют Янтарной Сосны.', },
  },
  [12109] = {
    'И снова к Гриану Камнегриву...',
    {'Дружинников Западного Края послали на восток в поисках прохода на северные территории. Их вторая задача – обеспечить безопасность стратегически важных точек, поэтому они вряд ли откажутся обследовать этот рудник.|n|nНайди Лагерь дружины Западного Края на северо-востоке и поговори с Грианом Камнегривом. Возможно, ты уже $Gвстречался:встречалась; с ним по дороге в Западный Край. Не забудь сказать ему, что это я тебя послал. |n|nОн будет счастлив отдать действующий рудник своему королю.', },
    {'Поговорите с капитаном Грианом Камнегривом в Лагере дружины Западного Края.', },
  },
  [12110] = {
    'Конец цепочки',
    {'В его одеяниях вы находите две интересных вещи.|n|nВо-первых, талисман, который явно представляет собой устройство для управления фокусом. А во-вторых, несколько приказов от некоего Сидрагоса, предназначенных предводителю в садах Лунного Покоя.|n|nВетхий промокший пергамент извещает Горамоша, что ему следует перевести всех охотников за магами на восток, к Лазуритовому святилищу драконов.|n|nБыть может, следует добыть из средоточия все сведения, какие можно, и отправиться на восток, чтобы понаблюдать за драконьим святилищем с западного уступа?', },
    {'Используйте талисман управления средоточием силовых линий, чтобы получить сведения о средоточии силовых линий на дне озера Инду\'ле. Затем отправляйтесь на восток, к Лазуритовому святилищу драконов, расположенному почти в центре южного Драконьего Погоста, и с западного уступа понаблюдайте за тем, что там происходит.|n|nПосле этого вернитесь к проекции верховного мага Этаса Похитителя Солнца в Молоте Агмара.', },
  },
  [12111] = {
    'Где бродят дикие звери',
    {'В этой упаковке – несколько сосудов с вакциной, изготовленной Синтаром. Я прошу тебя отыскать в находящихся поблизости лесах снегопадных оленей и полярных гризли. Когда найдешь этих животных, метни в них с безопасного расстояния один их сосудов. Из разбившегося сосуда распространится газ, который и вакцинирует животных. Им достаточно очутиться в облаке газа, и они окажутся привиты.|n|nНужно привить как можно больше животных. Как закончишь, возвращайся ко мне.', },
    {'Используйте суму с вакцинами, чтобы привить 5 снегопадных лосей и 5 полярных гризли по просьбе Соара Ярости Ястреба из Молота Агмара в Драконьем Погосте.', },
  },
  [12112] = {
    'Деловые отношения',
    {'Ну, похоже, наконец-то и ты $Gоказался полезным:оказалась полезной;. Нечасто мне $Gвстречался полезный:встречалась полезная:r; |3-6($R).|n|nЗдесь ты нам больше не понадобишься. Отправляйся-ка в Погань и узнай, не нужна ли помощь моему братцу Зорту. Он пошел посмотреть, не удастся ли ему убедить великанов пожертвовать своими жизнями, чтобы этого не пришлось делать нам. Определенно, если кого в семье и обделили мозгами, так это его.', },
    {'Найдите Зорта в центре ущелья порочных кристаллов, к северо-востоку от Лагеря Соплозабилось.', },
  },
  [12113] = {
    'Здравствуй, мяско!',
    {'Привет, |3-6($C)! Давай, присаживайся у огонька!|n|nЯ бы тебе предложил что-нибудь перекусить, но у меня ничего нет. Не знаю даже, что делать – то ли понадеяться на чью-нибудь помощь, то ли заняться охотой самому.|n|nСлушай, тебе же все равно нечем заняться? Может быть, принесешь мне немного мяса? Смотри, сколько его тут пасется!', },
    {'Харкор из Лагеря Харкора просит вас принести 10 кусков жилистого мяса ворга, которые можно добыть, поохотившись на хищников Ночного Воя, и 10 стейков из черпоклыка. Их можно вырезать из туш травоядных веслорогов.', },
  },
  [12114] = {
    'Анти-стрессовая терапия',
    {'Тролли... терпеть их не могу! <Харкор сплевывает на пол.>|n|nЭти мерзавцы однажды схватили меня... еще чуть-чуть – и стал бы я на голову короче!|n|nДрузья говорят, что я должен забыть обо всем и жить дальше, но я просто не могу простить троллям это оскорбление!|n|nЗнаешь, что бы сделало меня самым счастливым человеком, |3-6($R)? Куча трупов этих поганцев, гниющих на солнце! Ей-богу, я даже готов заплатить, если кто-то организует мне такое удовольствие.', },
    {'Харкор из Лагеря Харкора просит вас убить 10 заступников Драккари и 10 оракулов Драккари возле Руин Дракил\'джин.', },
  },
  [12115] = {
    'Кольтира и язык смерти',
    {'В наши ряды не так давно вступил некто, кто сумеет прочесть эту книгу. Освободившийся от уз рыцарь смерти по имени Кольтира Ткач Смерти временно поселился здесь, в Молоте Агмара. Поскольку он некогда был рыцарем смерти Артаса и воином Плети, он, возможно, умеет понимать язык мертвых.', },
    {'Отнесите сшитый плотью фолиант Кольтире Ткачу Смерти.', },
  },
  [12116] = {
    'Только смелым покоряются...',
    {'Приветствую тебя, |3-6($C). Спасибо, что $Gзашел:зашла; поболтать со стариной Кразом.|n|nВот уже много лет Краз слушает голоса духов и выполняет их просьбы.|n|nНедавно из глубины этих развалин к Кразу воззвали множество голосов несчастных душ, что не могут обрести покой.|n|nЕсли ты хочешь помочь душам наших предков, войди в склеп и собери то, что принадлежало когда-то несчастным призракам.', },
    {'Краз из Лагеря Харкора просит вас войти в Руины Дракил\'джина и собрать 5 каноп Драккари.', },
  },
  [12117] = {
    'Путешествие в гавань Моа\'ки',
    {'|3-6($R), с лодки из гавани Моа\'ки пришло сообщение. Сегодня утром там случилось нечто ужасное!|n|nТы здесь нам очень $Gпомог:помогла;. Может быть, ты $Gсогласился:согласилась; бы отправиться к великому Драконьему Погосту?|n|nСудя по тону сообщения, старейшине Ко\'нани очень пригодится твоя помощь...', },
    {'Отправляйтесь в гавань Моа\'ки на Драконий Погост и поговорите со старейшиной Ко\'нани.', },
  },
  [12118] = {
    'Путешествие в гавань Моа\'ки',
    {'|3-6($R), с лодки из гавани Моа\'ки пришло сообщение. Сегодня утром там случилось нечто ужасное!|n|nТы здесь нам очень $Gпомог:помогла;. Может быть, ты $Gсогласился:согласилась; бы воспользоваться лодкой и сплавать к великому Драконьему Погосту?|n|nСудя по тону сообщения, старейшине Ко\'нани очень пригодится твоя помощь...', },
    {'Отправляйтесь в гавань Моа\'ки на Драконий Погост и поговорите со старейшиной Ко\'нани.', },
  },
  [12119] = {
    'Добиться аудиенции',
    {'$N, отправляйся как можно быстрее в храм Драконьего Покоя и вручи это письмо распорядителю, Тариолстразу.|n|nХрам находится в центре Драконьего Погоста. Ступай по дороге, ведущей на восток, пока она не кончится, а потом иди напрямик через Драконьи пустоши, и придешь к храму.|n|nЯ уверена, что, когда распорядитель прочтет твое рекомендательное письмо, он позаботится о том, чтобы королева Алекстраза дала тебе аудиенцию. Остается только надеяться, что еще не поздно.|n|nСпасибо тебе за все, что ты $Gсделал:сделала; для нас. Желаю тебе благополучно добраться до цели!', },
    {'Вручите свое приглашение Тариолстразу в храме Драконьего Покоя.', },
  },
  [12120] = {
    'Молот Драк\'агуула',
    {'Скверна и разложение...|n|nКраз почувствовал их присутствие задолго до того, как ты $Gпринес:принесла; сюда эти кувшины. Скверна поразила древних духов Драккари и не дает им обрести покой.|n|nКразу незачем обманывать тебя, |3-6($C). Очистить это место будет нелегко, но об этом мы поговорим в другой раз.|n|nСначала мы должны добыть то, что поможет совершить акт очищения. Этот предмет находится в руках одного из смертных, Драк\'агуула. Принеси Кразу его молот!', },
    {'Краз из Лагеря Харкора просит вас убить Драк\'агуула возле Руин Дракил\'джин и принести ему Дракил\'джинский молот.', },
  },
  [12121] = {
    'Увидимся в другом мире',
    {'Эти драккари не проявили к тебе ничего, кроме жестокости. Не стоит чувствовать вину перед ними. Знай, что лишь немногие могли бы выполнить поручение, которое Краз хочет доверить тебе. |n|nЧтобы очистить это место и даровать духам долгожданный покой, тебе придется шагнуть в мир смерти.|n|nВнутри этого склепа тебя ждет тот, кто сможет нам помочь. Только он обладает знаниями, которые направят нас на истинный путь. |n|nУдарь молотом в гонги, и населяющие это место духи утащат тебя в потусторонний мир.|n|nКраз будет ждать твоего возвращения.', },
    {'Краз из Лагеря Харкора просит вас ударить Дракил\'джинским молотом в гонги, окружающие Руины Дракил\'джин. После этого вас, скорее всего, убьют, и тогда вы сможете войти в руины, чтобы поговорить с Ган\'джо из мира мертвых.', },
  },
  [12122] = {
    'Добиться аудиенции',
    {'$N, отправляйся как можно быстрее в храм Драконьего Покоя и вручи это письмо распорядителю, Тариолстразу.|n|nХрам находится в центре Драконьего Погоста. Ступай по дороге, ведущей на восток, пока она не кончится, а потом иди напрямик через Драконьи пустоши, и придешь к храму.|n|nЯ уверена, что, когда распорядитель прочтет твое рекомендательное письмо, он позаботится о том, чтобы королева Алекстраза дала тебе аудиенцию. Остается только надеяться, что еще не поздно.|n|nСпасибо тебе за все, что ты $Gсделал:сделала; для нас. Желаю тебе благополучно добраться до цели!', },
    {'Вручите свое приглашение Тариолстразу в храме Драконьего Покоя.', },
  },
  [12123] = {
    'Информация для королевы',
    {'<Дракон-распорядитель достает из рукава ваше рекомендательное письмо.>|n|nДа… да, думаю, ты уже $Gготов:готова; встретиться с королевой.|n|nКогда будешь $Gготов:готова;, обратись ко мне снова, и я прикажу одному из этих драконов доставить тебя на вершину храма. Тебе следует лично вручить письмо королеве Алекстразе.', },
    {'Вручите свое приглашение в храм Драконьего Покоя Алекстразе Хранительнице Жизни в храме Драконьего Покоя.', },
  },
  [12124] = {
    'Информация для королевы',
    {'<Дракон-распорядитель достает из рукава ваше рекомендательное письмо.>|n|nДа… да, думаю, ты уже $Gготов:готова; встретиться с королевой.|n|nКогда будешь $Gготов:готова;, обратись ко мне снова, и я прикажу одному из этих драконов доставить тебя на вершину храма. Тебе следует лично вручить письмо королеве Алекстразе.', },
    {'Вручите свое приглашение в храм Драконьего Покоя Алекстразе Хранительнице Жизни в храме Драконьего Покоя.', },
  },
  [12125] = {
    'Ради крови',
    {'Кровь невинных уже однажды использовалась для того, чтобы насытить жажду этого клинка. К сожалению, для меня это больше невозможно.|n|n<Кольтира замолкает, размышляя.>|n|nПридется импровизировать. К югу отсюда, на высоких утесах, расположена клыкаррская деревня Инду\'ле. Попавшие под мощное воздействие хаотической магии синих драконов, жители Инду\'ле сошли с ума.|n|nВозьми этот кровавый самоцвет и воздействуй им на сумасшедшего жителя деревни. Если я не могу брать кровь невинных, возьму кровь убогих!', },
    {'По просьбе Кольтиры Ткача Смерти воздействуйте кровавым самоцветом на спятившего селянина Инду\'ле, а затем возвращайтесь к Кольтире в Молот Агмара на Драконьем Погосте с наполненным кровавым самоцветом.', },
  },
  [12126] = {
    'На службе нечестивости',
    {'Такие, как я, жаждут силы нечестивости. Она составляет самую суть нашего существования, приносит смерть тем, кто осмеливается смеяться над ней! По счастью, у меня есть источник этой силы, из которого я могу черпать при необходимости.|n|nВот, возьми этот нечестивый самоцвет и ступай в Рубиновое святилище драконов, к востоку отсюда. Там ты найдешь герцога Валленхола, рыцаря смерти Артаса. Измотай его в поединке, а потом обрушь на него мощь самоцвета. Самоцвет убьет его и вберет его нечестивую силу!', },
    {'Используйте нечестивый самоцвет против герцога Валленхола и вернитесь с наполненным нечестивым самоцветом к Кольтире Ткачу Смерти в Молот Агмара на Драконий Погост.', },
  },
  [12127] = {
    'На службе у мороза',
    {'Трескучий мороз защищает рыцаря смерти и в то же время распугивает его врагов. Кто владеет холодом, способен сеять хаос и разрушение!|n|nВозьми этот ледяной самоцвет и отправляйся напрямик через тундру Драконьего Погоста, пока не выйдешь к Зеркалу Рассвета, к востоку от храма Драконьего Покоя. Там тебе придется сразиться с полчищами загробников льда, обитающих на поверхности озер, чтобы забрать у них суть холода. Когда они ослабеют, используй силу самоцвета, $N!', },
    {'Используйте ледяной самоцвет против загробников льда и вернитесь к Кольтире Ткачу Смерти в Молот Агмара на Драконий Погост с наполненным ледяным самоцветом.', },
  },
  [12128] = {
    'Как дела у Регара?',
    {'Из-за всего этого переполоха с армией, штурмующей Тор Модан, я чуть не забыл про отряд Регара в Лагере горняков.|n|nЯ отправил Регара и его помощников разбить лагерь возле Дун Аргола, на юге Побережья Восточного Ветра.|n|nОни должны были собрать сведения о железных дворфах, замеченных в южных холмах, но с тех пор я не получил от них ни единого отчета. Не $Gмог:могла; бы ты узнать, как у них дела?', },
    {'Поговорите с Регаром Бровебоем в Лагере горняков.', },
  },
  [12129] = {
    'Безукоризненный замысел',
    {'Железные дворфы не делают тайны из своих приготовлений к войне. Учитывая наличие в их армии големов, великанов и наэлектризованных элементалей, можно смело утверждать, что их преимущество над дружиной Западного Края огромно. Если нашим ребятам не удастся вовремя найти проход на север, железные дворфы застанут их врасплох. |n|nНам надо выиграть время для дружины Западного Края, и я знаю, что мы можем предпринять. В Дун Арголе полно кователей рун, собирающих боевых големов. Они часто носят с собой чертежи деталей, с помощью которых мы могли бы создать собственного голема. Собери все эти чертежи и принеси их мне!', },
    {'Принесите полный набор чертежей боевого голема Регару Бровебою в Лагерь горняков.', },
  },
  [12130] = {
    'Зачем ковать то, что можно отобрать?',
    {'Что толку от чертежей, если у нас нет ни инструментов, ни материалов, чтобы выточить детали? Впрочем, в Дун Арголе эти запчасти валяются повсюду...|n|nВот тебе новое задание!|n|nНайди-ка этим деталям новое применение.|n|nОни валяются повсюду вокруг мастерских железных кователей рун. Правда, я не стал бы рассчитывать на то, что железные дворфы будут тебе рады. Я бы тоже рассердился, если бы кто-то попытался стянуть результаты моего труда.', },
    {'Принесите 8 частей боевого голема Регару Бровебою в Лагерь горняков.', },
  },
  [12131] = {
    'Нам нужна энергия',
    {'Наш боевой голем почти готов! Остается только вложить в него энергобатареи. Судя по сведениям, которые мне удалось собрать в Дун Арголе, созданием зарядных ячеек занимаются два дворфа – рунический кузнец Дурар и рунический кузнец Каторн.|n|nЧтобы наш голем заработал, в него надо установить две энергобатареи.|n|nНайди этих рунических кузнецов. Их мастерские должны быть в самом центре Дун Аргола.', },
    {'Принесите энергобатареи Дурара и Каторна Регару Бровебою в Лагерь горняков.', },
  },
  [12132] = {
    'Сила разрушения',
    {'Ты уже многое $Gсделал:сделала; для меня, и осталось последнее задание.|n|nКроме мира, который все видят каждый день, существует и другой. Именно из того, другого мира, где царствует тень, нападают на меня мои мучители. Хоть я и бессилен против своих собственных демонов, но ты $Gмог:могла; бы положить конец их бесправному засилию. У тебя есть сила, я видел это своими собственными глазами.|n|nВойди в мир теней и сразись с демонами, мучающими меня!|n|nСделай это, и я переведу тебе фолиант, как и обещал.', },
    {'По просьбе Кольтиры Ткача Смерти из Молота Агмара, что на Драконьем Погосте, войдите в мир теней и сразите 6 мрачных мучителей.|n|nЕсли вам нужно будет еще раз войти в мир теней, обратитесь к Кольтире.', },
  },
  [12133] = {
    'Разбей тыкву!',
    {'Посреди деревни лежит большая тыква. Взгляд ее горит мрачной злобой.|n|nРазбив тыкву, вы видите старый, опаленный священный символ.', },
    {'Отдайте опаленный священный символ переодетой попечительнице сирот.', },
  },
  [12134] = {
    'Саша выходит на охоту',
    {'Это... проклятие... вот, что овладело Среброречьем и Деревней Солнцестояния... оно превратило наших жителей в диких зверей.|n|nОтец пытался их предупредить, но они слушали лишь голос волков...|n|nТеперь их уже не спасти. Можно лишь покончить с ними... ради их собственного блага.', },
    {'Саша просит вас убить 12 охотников солнцестояния в Деревне Солнцестояния.', },
  },
  [12135] = {
    '"И гори все огнем!"',
    {'Всадник без головы нападет на деревню в любой момент! Повсюду начнется пожар!|n|n$N, вы ведь поможете нам бороться с пожаром Всадника без головы? Когда он придет, присоединяйтесь к пожарной бригаде. Берите ведро и заливайте пожар или передавайте ведра по цепочке! Погасите пожар, и мы, может, еще спасемся!', },
    {'Переодетая попечительница сирот просит вас помочь потушить пожар в деревне, если ее подожжет Всадник без головы. Когда пожар будет потушен, снова поговорите с попечительницей сирот.', },
  },
  [12136] = {
    'Переведенная книга',
    {'Вот, $N. Я перевел все, запечатленное на страницах этого фолианта. В нем ты найдешь список имен последователей Культа Проклятых, разбросанных по всему континенту.|n|nИх сеть шпионов и агентов по меньшей мере впечатляет.|n|nПрощай, друг мой. Пусть эта книга хорошо послужит тебе и твоему народу.', },
    {'Доставьте переведенный сшитый плотью фолиант капитану Горту в Молот Агмара.', },
  },
  [12137] = {
    'Остынь, чудо!',
    {'Все как по пророчеству, $Gдружище:подруга;! $R- |3-6($C) придет, чтобы освободить души умерших... Долго же мы ждали твоего пришествия!|n|nДраккари стали диким народом, жестоким и беспощадным. |n|nНо наши души страдают безвинно, $Gдруг мой:подруга;. Это место надо очистить, и только смертному под силу совершить подобное.|n|nПоговори со мной, когда будешь $Gготов:готова; вернуться в свое тело. Возьми снег из ближайшего сундука и упокой моих братьев. Затем отнеси их останки своему хранителю душ. Он подскажет тебе, что делать дальше.', },
    {'Ган\'джо просит вас собрать снег вечного сна из его сундука в руинах Дракил\'джин.|n|nИм надо окропить древних духов Драккари и отнести крупицы духов Драккари Кразу в Лагерь Харкора.', },
  },
  [12138] = {
    '... а может быть, и нет',
    {'Думаешь, эти ребята, изготавливающие энергобатареи, догадались их зарядить? Нет, конечно! Это было бы слишком просто.|n|nНу ладно; не хотят по-хорошему – будем действовать по-плохому. Остаточного заряда хватит на то, чтобы обеспечить моторные системы голема, но в бою на него можешь не рассчитывать.|n|nВидишь грозовых караульных, которые патрулируют периметр Дун Аргола? Подведи голема поближе, и он сам впитает энергию после смерти часового.', },
    {'Подзарядите вашего Боевого голема от десяти грозовых караульных и вернитесь к Регару Бровебою в Лагерь горняков.', },
  },
  [12139] = {
    '"И гори все огнем!"',
    {'Всадник без головы нападет на деревню в любой момент! Повсюду начнется пожар!|n|n$N, вы ведь поможете нам бороться с пожаром Всадника без головы? Когда он придет, присоединяйтесь к пожарной бригаде. Берите ведро и заливайте пожар или передавайте ведра по цепочке! Погасите пожар, и мы, может, еще спасемся!', },
    {'Попечительница сирот в маске просит вас помочь потушить пожар в деревне. Когда пожар потухнет, снова поговорите с попечительницей сирот в маске в городе.', },
  },
  [12140] = {
    'Славься, Роанук!',
    {'Найдите Роанука Ледяную Пыль в Молоте Агмара, примите его в лоно Орды и посвятите его в вожди сил Орды.|n|nКогда ритуал будет завершен, вернитесь к командиру Агмару с клятвой крови Орды.', },
    {'Найдите Роанука Ледяную Пыль в Молоте Агмара, примите его в лоно Орды и посвятите его в вожди сил Орды.|n|nКогда ритуал будет завершен, вернитесь к командиру Агмару с клятвой крови Орды.', },
  },
  [12141] = {
    'Дипломатическое поручение',
    {'Я вижу, $N, вы очень хотите помочь. Разумеется, вы не для того добирались до Нордскола, чтобы торчать в городе! У меня как раз есть для вас задание… связанное с дальней поездкой.|n|nМы давно пытаемся добиться расположения клыкарров, коренных жителей Нордскола. Не так давно к нам явился молодой клыкарр. Он просил помощи, но мы тогда были не в состоянии ее оказать.|n|nНо теперь, когда вы здесь, быть может, вы согласитесь ему помочь? Отыщите Карука на берегу Терзающего Бича, к юго-западу отсюда, и узнайте, чем вы можете ему помочь.', },
    {'Поговорите с Каруком на берегу Терзающего Бича, к юго-западу от крепости Отваги.', },
  },
  [12142] = {
    'Заразу – под контроль!',
    {'Уф! Один из снобольдов устроил погром в нашем лагере, пока мы бились с драконом. Эти снобольды вредят нам, стоит только отвернуться. Сколько можно?!|n|nК югу отсюда ты найдешь снобольдов, живущих под опекой здешних магнатавров. Иди и прибей их.|n|nЕсли магнатавры вмешаются на стороне своих рабов, покончи и с ними.', },
    {'По заданию Дуана с передовой 7-го легиона убейте 10 снобольдов Снежных равнин и 3 магнатавров Драконьего Погоста в лагерях магнатавров, окружающих Драконий Покой.', },
  },
  [12143] = {
    'Преследование в каньоне',
    {'Не могу поверить! Еще одна шайка этих вредителей только что попыталась сбежать с очередной порцией наших припасов. Они несутся вон к тому северному каньону, гонись-ка за ними и разберись с тем, к кому они спешат!', },
    {'Дуан просит вас идти по следу снобольдов по каньону к северо-востоку от передовой 7-го легиона и разобраться с их вожаком.', },
  },
  [12144] = {
    'Заразу – под контроль!',
    {'Слышь, ты! Один из этих коротышек-снобольдов обчистил наш лагерь во время последнего налета драконов. Они набрасываются на нас каждый раз, стоит только повернуться спиной! Меня это достало.|n|nВон там, к востоку, ты найдешь снобольдов, которые прячутся под юбками у каких-то местных магнатавров. Перебей их. А если магнатавры вздумают заступиться за своих рабов, так и их перебей тоже.', },
    {'Убейте 10 снобольдов Снежных равнин и 3 магнатавров Драконьего Погоста в лагерях магнатавров, расположенных к юго-востоку от Драконьего Покоя. Выполнив задачу, вернитесь к Контоканису в Драконьей Погибели в северо-западных Драконьих пустошах.', },
  },
  [12145] = {
    'Преследование в каньоне',
    {'Не могу поверить! Еще одна шайка этих вредителей только что попыталась сбежать с очередной порцией наших припасов. Они несутся сейчас по каньону, гонись за ними и разберись с тем, к кому они спешат!', },
    {'По поручению Контоканиса преследуйте снобольдов по каньону к югу от Драконьего Зова и разберитесь с их вожаком.', },
  },
  [12146] = {
    'Зловещие выводы',
    {'Нижняя сторона рога украшена гравировкой с изображением молота и разряда молнии. Что-то с этим рогом не так, не подходит он магнатавру...|n|nВозьмите его, идите на юг по Пути Титанов к Драконьему Покою и найдите кого-нибудь, кому станет интересна эта диковина.', },
    {'Отнесите расписанный боевой рог к Драконьему Покою и найдите того, кто заинтересовался бы возможностью оценить потенциальную угрозу.', },
  },
  [12147] = {
    'Зловещие выводы',
    {'Нижняя сторона рога может похвастаться украшенной гравировкой печатью с изображением молота и разряда молнии. Что-то в этом роге кажется абсолютно несоответствующим магнатаврам.|n|nВозьмите этот рог, идите на восток через Драконьи пустоши к Драконьему Покою и найдите того, кого могли бы заинтересовать эти пугающие находки.', },
    {'Отнесите расписанный боевой рог к Драконьему Покою и найдите того, кто заинтересовался бы возможностью оценить потенциальную угрозу.', },
  },
  [12148] = {
    'Единственный в своем роде',
    {'Такая странная печать – и у магнатавров… это говорит о необычно высокой организации.|n|nМагнатаврам редко удается забыть о своей агрессивной натуре настолько, чтобы начать взаимодействовать друг с другом. Я подозреваю, что они задумали ограбить крупное поселение.|n|nЯ сильно сомневаюсь, что этот рог – единственный в своем роде. Мне нужны доказательства того, что я не права. В каньоне к северо-западу от Лазуритового святилища драконов ты найдешь Расщепителя костей. Иди сразись с ним и возвращайся с любыми свидетельствами, которые могут подтвердить мои опасения.', },
    {'Найдите и убейте Расщепителя Костей в каньоне (или рядом с ним), находящемся к северо-западу от Лазуритового святилища драконов. Принесите найденное вами свидетельство Аурастразе в храм Драконьего Покоя.', },
  },
  [12149] = {
    'Могучие магнатавры',
    {'Магнатавры – чрезвычайно агрессивные существа… и это основная причина, почему мы редко видим, чтобы они сосуществовали в сколь-нибудь значимых количествах, не начав убивать друг друга. Однако из их среды выделился могучий вожак, и мы должны выследить его и уничтожить, если хотим справиться с этой угрозой.|n|nЯ поспрашиваю тут в округе. А ты, тем временем, вреди им как только сможешь.|n|nК востоку отсюда установлены три факела. Рядом с ними – три крупных магнатавра. Убей их, чтобы выиграть немного времени для охоты на их вожака.', },
    {'Выследите и убейте Кровавого Пира, Ледоскала и Дракрова к востоку от Драконьего Покоя.|n|nКровавый Пир обитает в юго-восточном углу Драконьих Пустошей, прямо к северу от изумрудного святилища драконов. Ледоскал патрулирует северную оконечность Зеркала Рассвета. Дракров бродит у подножья утесов к западу от бронзового святилища драконов.|n|nКогда все три магнатавра будут убиты, возвращайтесь к Аурастразе в Драконий Покой.', },
  },
  [12150] = {
    'Мастер рун-затворник',
    {'Дрегмар Рунический Знак – магнатаврский мастер рун. Редкая пташка. Обычно он держится особняком, но прежде водился с более могущественными и влиятельными магнатаврами Драконьего Погоста. Так что он должен знать, кто у них новый вождь.|n|nМы вряд ли дождемся помощи в борьбе с Плетью и синими драконами, так что получить эти сведения от Дрегмара совершенно необходимо.|n|nМне говорили, его можно найти среди утесов, что нависают над Зеркалом Рассвета.', },
    {'Отыщите Дрегмара Рунического Знака неподалеку от его пещеры, на тропе, ведущей в утесы над Зеркалом Рассвета. Бросьте ему вызов и любой ценой узнайте имя повелителя магнатавров. Добыв нужные сведения, вернитесь к Аурастразе в Драконьем Покое.', },
  },
  [12151] = {
    'Распоясавшийся полководец',
    {'Нет никаких причин подозревать, что слова Дрегмара не соответствуют действительности. Сразит ли Гром\'тар тебя или будет сражен тобой – его это уже не касается.|n|nСледуй его указаниям… возьми рог, что ты $Gпринес:принесла; мне ранее, отправляйся к кругу факелов к югу от лазуритового святилища драконов и протруби в рог, чтобы объявить о своем вызове. Когда Гром\'тар Громовержец появится, убей его, а потом принеси мне его голову.', },
    {'Отправляйтесь к кругу факелов к югу от лазуритового святилища драконов и протрубите в расписанный боевой рог. Сразите Гром\'тара Громовержца и принесите его голову Аурастразе в Драконий Покой.', },
  },
  [12152] = {
    'Погибель Джин\'аррака',
    {'Я рад снова видеть тебя в мире живых. Многие из тех, что отправились по дороге смерти, так и не вернулись обратно. |n|nПока ты $Gотсутствовал:отсутсвовала;, Краза посетило видение, которое открыло ему, что надо делать дальше.|n|nСвященное подношение лежит где-то в склепе. Возьми эту пыль духов, сотворенную из собранных тобой останков, и рассей ее над подношением. |n|nЗаряженное подношение положит конец правлению падшего вождя и освободит многие замученные души.|n|nДа пребудет с тобой мудрость предков, $N.', },
    {'Краз из Лагеря Харкора просит вас найти cвященное подношение Драккари в руинах Дракил\'джина и осенить его пылью духов Драккари. После этого положите подношение к гонгам у руин Дракил\'джина.', },
  },
  [12153] = {
    'Тан и его Наковальня',
    {'Теперь, когда голем полностью заряжен, мы сможем направить его силу в нужное русло. Чтобы взять на себя управление, активируй его в периметре Дун Аргола. |n|nНаша информация о предводителе Дун Аргола, тане Гневном Топоре, свидетельствует о том, что его защищает личный телохранитель.|n|nЗовут это чудовище Наковальня, но оно не так неуязвимо, как кажется. Отключи этого голема – и тан останется беззащитным.|n|nТы найдешь нашего противника на вершине Дун Аргола, где он инспектирует производство.', },
    {'Воспользовавшись боевым големом, убейте тана Гневного Топора, после чего вернитесь к Регару Бровебою в Лагерь горняков.', },
  },
  [12154] = {
    'Затмение',
    {'В огромном помещении на вершине Дун Аргола находится источник энергии, питающий весь город. Если ты сможешь его уничтожить, то повергнешь в хаос весь Дун Аргол.|n|nБез энергии ни големы, ни часовые не будут функционировать; к тому же, отключится все освещение.|n|nНам выдали эту взрывчатку для раскопок, но тан Гневный Топор сорвал нашу работу. Впрочем, теперь она нам пригодится для других нужд – например, разрушить источник питания.', },
    {'Воспользуйтесь взрывчаткой Регара, чтобы уничтожить руническое силовое ядро в Дун Арголе. Доложите о своем успехе Регару Бровебою из Лагеря горняков.', },
  },
  [12155] = {
    'Разбей тыкву!',
    {'Посреди деревни лежит большая тыква. Взгляд ее горит мрачной злобой.|n|nРазбив тыкву, вы видите старый, опаленный священный символ.', },
    {'Отдайте опаленный священный символ попечительнице сирот в маске.', },
  },
  [12156] = {
    nil,
    {'Примерно час назад я должен был отправиться в Среброречье, к северо-западу отсюда, но мой эскорт еще не прибыл.|n|nБудь я проклят, если моя дипломатическая миссия сорвется из-за какого-то проспавшего рекрута!|n|nМы пытаемся наладить связь с местными обитателями, и сейчас каждая минут на счету. Послушай, может быть, ты согласишься сопроводить меня – за определенную плату?', },
    {'Сопроводите посланца Альянса в Среброречье. Выполнив это задание, вернитесь к лейтенанту Думонту в Приют Янтарной Сосны.', },
  },
  [12157] = {
    'Пропавший курьер',
    {'Нам еще повезло, что мы добрались сюда, $N. Едва приземлившись, мы угодили в засаду Плети.|n|nОдин из наших оказался шпионом Культа Проклятых. А у Тассариана, похоже, есть и другие доказательства того, что тут замешаны сектанты. Похоже, они сумели пробраться на самый верх...|n|nОдин из моих лучших курьеров отправился на заставу в западном Драконьем Погосте, но до сих пор не вернулся. Боюсь, его перехватили прислужники Плети. Не согласишься ли ты отправиться в Драконий Погост и поискать его? Его зовут курьер Лансон.', },
    {'Поговорите с курьером Лансоном в Покое Звезд, что в Драконьем Погосте.', },
  },
  [12158] = {
    'Рудник Полого Камня',
    {'Я и сам собирался послать кого-нибудь проверить, что происходит на Руднике Полого Камня, но все как-то не было времени этим заняться. $GСам:Сама; понимаешь, Орда на западе и железные дворфы на востоке не дают скучать. |n|nВпрочем, если тебя послал Дюмонт – мне остается только указать тебе направление.|n|nВход в рудник находится на северо-западе, недалеко отсюда. Надеюсь, его еще можно использовать. Нам бы не помешал дополнительный источник ресурсов, пока мы не вернемся к разработке рудника в Далечье.', },
    {'Обыщите Рудник Полого Камня к северо-западу от Лагеря дружины Западного Края.', },
  },
  [12159] = {
    'Неупокоенные души',
    {'<Петров тяжело дышит и настороженно осматривает рудник.>|n|nТоварищи мои... их души должны обрести покой! Я убиваю их одного за другим, но... они возвращаются снова и снова!|n|nКажется, я знаю, что надо делать, но у меня не хватит смелости.|n|nМожет быть, ты возьмешься за это нелегкое дело? Возьми эту лампу и подожги с ее помощью их трупы, чтобы они больше не смогли восстать из мертвых. |n|nПомоги моим друзьям – и я отвечу на все твои вопросы!', },
    {'Петров с Рудника Полого Камня просит вас поджечь с помощью шахтерского фонаря трупы 8 шахтеров с Рудника Полого Камня.', },
  },
  [12160] = {
    'Имя из прошлого',
    {'Получилось! Наконец-то мои товарищи смогут упокоиться...|n|nА я останусь здесь и закончу работу. Мы, шахтеры Полого Камня, всегда доводим любое дело до конца. И никогда не опускаем руки!|n|nВот почему Аругал ставит нас в пример. Мы не стали ему подчиняться, понимаешь? Мы отказались поклоняться культу Волка!', },
    {'Вернитесь к капитану Гриану Камнегриву в Лагерь дружины Западного Края.', },
  },
  [12161] = {
    'Рууна Слепая',
    {'Эй! Я случайно подслушал твой разговор с капитаном, и подумал, что тебе надо кое-что узнать. Видишь ли... здесь, в Нордсколе, не все так просто, как кажется.|n|nДаже мертвецов нельзя сбрасывать со счетов.|n|nК юго-западу отсюда, рядом с Перевалом Фордрассил, живет колдунья, которая называет себя Рууна Слепая. Говорят, она может разговаривать с духами умерших, видеть прошлое и будущее.|n|nЯ толком не знаю, на что она способна, но тебе не помешал бы такой союзник.', },
    {'Поговорите с Рууной Слепой, которая живет в Лагере Рууны рядом с Перевалом Фордрассил.', },
  },
  [12162] = {
    'Деревня Солнцестояния',
    nil,
    nil,
  },
  [12164] = {
    'Час ворга',
    {'Время пришло, $N. Аругал должен умереть.|n|nСобери несколько верных товарищей и отправляйся на Остров Кровавой Луны. Ты найдешь его на востоке, недалеко от побережья.|n|nМы нанесем стремительный удар. Возьми на себя лейтенантов Аругала, а я присоединюсь к тебе, когда дело дойдет до битвы с главарем.', },
    {'Саша из Торговой лавки Белой Сосны посылает вас на Остров Кровавой Луны убить Селаас, Варлама, Вспоробрюха и Тень Аругала.', },
  },
  [12165] = {
    'Коварный план',
    {'Геолог Рокар решил нам помочь и разработал план, как обернуть изобретения железных дворфов против их самих. |n|nНадо признать, от нашего нового лучшего друга все-таки есть какая-то польза. В одном он точно прав – нас слишком мало, чтобы действовать открыто. |n|nИди в Дун Аргол, в заснеженный край на юго-востоке, и захвати чертежи их боевых големов, которые носят с собой железные кователи рун. Доставь чертежи Рокару – пусть приступает к осуществлению своего плана.', },
    {'Принесите полный комплект чертежей боевого голема геологу Рокару в Лагерь Уанква.', },
  },
  [12166] = {
    'Жидкое пламя Элуны',
    {'$R, не поможешь мне?|n|nСилы плети вошли в деревню Ледяной Пыли к северу отсюда. Где бы они ни проходили, они повсюду сеют свою порчу, и невинные обитатели этой земли страдают.|n|nВозьми этот сосуд, наполненный жидким пламенем Элуны из Лунного колодца. Пожалуйста, воспользуйся этой жидкостью, чтобы очистить тела несчастных чумных животных, какие найдешь.', },
    {'По просьбе стража-смотрителя Джоди Песни Луны из Покоя Звезд воспользуйтесь жидким пламенем Элуны для очищения трупов 6 гнилостных маралов и 6 бешеных гризли.', },
  },
  [12167] = {
    'Убить сектантов',
    {'Ануб\'арские сектанты виновны, пусть и косвенно, в эпидемии среди животных. Мы обязаны положить этому конец!|n|nПары, исходящие от костюмов сектантов, впитываются во все, что только есть поблизости, загрязняя и отравляя землю и воду!|n|nСтупай на север, в деревню Ледяной Пыли, и перебей их. Принеси те их костюмы, что останутся целы после битвы – я позабочусь о том, чтобы ликвидировать их должным образом.', },
    {'Соберите 5 рабочих костюмов сектантов по просьбе стража-смотрителя Джоди Песни Луны из Покоя Звезд.', },
  },
  [12168] = {
    'Памятный дар Зангуса',
    {'Надпись на обратной стороне памятного дара гласит:|n|n"Моему любимому ученику. Если продолжишь делать успехи – я научу тебя невообразимым чудесам.|n|nА если нет – я тебя уничтожу!|n|nВсегда твой,|n|nВерховный сектант Зангус"|n|nНесомненно, стража-смотрителя из Покоя Звезд это заинтересует.', },
    {'Принесите памятный дар Зангуса стражу-смотрителю Джоди Песни Луны в Покой Звезд.', },
  },
  [12169] = {
    'Верховный сектант',
    {'Мне и раньше грезился Зангус, но без контекста, открытого тобой, я не знала, что все это значило. Ты $Gвнес:внесла; ясность в видение, которым богиня одарила меня, и теперь я знаю, что его можно найти в Провале Наржуна к северу отсюда.|n|nТы знаешь свою цель, $N. Если можно положить конец страданиям этой земли, верховный сектант должен умереть!', },
    {'По заданию Стража-смотрителя Джоди Песни Луны из Покоя Звезд убейте верховного сектанта Зангуса.', },
  },
  [12170] = {
    'Схватка в Черноречье',
    {'Вскоре после нашего появления Торговая Компания свернула свою деятельность и удрала отсюда. Не сомневаюсь, мерзкие гоблины испугались за свои жадные, трусливые задницы!|n|nНе могу сказать, что меня это огорчает – нашим машинам требуется топливо, а эти торгаши оставили без охраны множество лесопилок. Забрав оттуда припасы, мы могли бы без проблем добраться до Ледника Ледяной Короны.|n|nК несчастью, Альянсу пришла в голову та же идея. Мы должны их опередить! Отправляйся на лесопилку и помоги нам избавиться от присутствия воришек из Альянса.', },
    {'Капитан налетчиков Кронн просит вас убить 10 представителей или игроков Альянса на Лесопилке Черноречья.', },
  },
  [12171] = {
    'О предателях и предательстве',
    {'Думаю, этот список следует доставить главнокомандующему Халфорду Змеевержцу! Он командует 7-м легионом, стоящим в крепости Стражей Зимы на восточной границе Драконьего Погоста.|n|nЕсли кто-то из предателей, упомянутых в этом списке, находится в крепости Стражей Зимы... это может привести к катастрофе!|n|nСкорее, $N! Покажи этот документ Палене Серебряное Облако здесь, в Покое Звезд, и объясни, куда и зачем ты направляешься. Она даст тебе самого быстрого из своих гиппогрифов!', },
    {'Покажите депешу Альянса Палене Серебряное Облако в Покое Звезд.', },
  },
  [12172] = {
    'Настройка на Даларан',
    {'Добро пожаловать, маг.|n|nДо сих пор тебе, должно быть, интересно где же находится Даларан и как туда попасть. Я помогу тебе.|n|nНо прежде чем я научу тебя телепортироваться в наш великий город, тебе нужно настроиться на силовые линии Нордскола.|n|nВозьми этот кристалл настройки и используй его в провале под волноловом у Садов Лунного Покоя к западу отсюда. Тогда ты будешь $Gготов:готова; выучить нужное заклинание.', },
    {'По заданию проекции верховного мага Модеры в Покое Звезд настройтесь на силовые линии Нордскола.', },
  },
  [12173] = {
    'Настройка на Даларан',
    {'Приветствую тебя, маг.|n|nДолжно быть, тебе интересно, где же находится Даларан и как туда попасть. Я помогу тебе, если сумеешь пройти простенький тест.|n|nПрежде чем я научу тебя телепортироваться в наш великий город, тебе нужно настроиться на силовые линии Нордскола. Иначе ты просто умрешь в процессе перемещения!|n|nВозьми этот кристалл настройки и используй его в провале под волноловом у Садов Лунного Покоя к юго-западу отсюда. Тогда ты будешь $Gготов:готова; узнать то, чему я могу тебя научить.', },
    {'По заданию проекции верховного мага Этаса Похитителя Солнца в Молоте Агмара настройтесь на силовые линии Нордскола.', },
  },
  [12174] = {
    'Главнокомандующий Халфорд Змеевержец',
    {'Отвезите депешу Альянса главнокомандующему Халфорду Змеевержцу в Крепость Стражей Зимы, которая находится на востоке Драконьего Погоста.', },
    {'Отвезите депешу Альянса главнокомандующему Халфорду Змеевержцу в Крепость Стражей Зимы, которая находится на востоке Драконьего Погоста.', },
  },
  [12175] = {
    'Серые шкуры воргов',
    {'Я тебе вот что скажу, $Gдружище:подруга;: паршивая это работенка – заниматься обмундированием для солдат Орды!|n|nА тут еще эта волчица, Завоевательница Кренна, кнутом подгоняет. Вынь да положь ей полный комплект обмундирования к концу недели – иначе сбросит меня в яму к медведям.|n|nПомоги мне – а я уж в долгу не останусь. Мне нужны шкуры серо-дымчатых охотников.|n|nИх легко найти на севере, где они гоняются за оленями. Учти, я тебе хорошо заплачу!', },
    {'Торговец шкурами Джун\'ик из Крепости Завоевателей просит вас добыть 3 серые шкуры ворга с серо-дымчатых охотников, которые водятся в лесах на севере.', },
  },
  [12176] = {
    'Мелкая подмена',
    {'Кренна хочет сменить обмундирование нашего войска и пошить новое из шкур воргов – а наших запасов, естественно, не хватит, чтобы одеть всю армию. Хоть ты лопни, не наберется у нас столько шкур!|n|nТощие они, эти ворги, и меха с них – кот наплакал. Но у меня есть идея! Могу и с тобой поделиться – если обещаешь держать язык за зубами.|n|nК востоку от Волдруна живут медведи гризли, жирные как огры. Их огромные шкуры мы могли бы пустить в дело!|n|nДавай, $Gбратишка:сестренка;, принимайся за дело. Кренна ждать не любит.', },
    {'Торговец шкурами Джун\'ик просит вас принести ему 6 шкур медведей гризли.', },
  },
  [12177] = {
    'Уловка Джун\'ика',
    {'Ой... кажется, у нас возникла проблема. Эти шкуры... они коричневого цвета! |n|nДумай, думай, голова...|n|nВо, придумал! Серый цвет – это помесь белого и черного, верно? Тащи сюда уголь и муку! Я их перемешаю и посыплю шкуры этой пудрой. Никто и не заметит!|n|nТак... уголь продают кузнецы, а муку можно достать у поставщика.', },
    {'Принесите кусок угля и пять горстей простой муки торговцу шкурами Джун\'ику в Крепость Завоевателей в Седых холмах.', },
  },
  [12178] = {
    'Сверток для Кренны',
    {'Вот, $Gдружище:подруга;. Давай-ка отнесем эти шкуры Кренне и посмотрим, как она отреагирует.|n|nОчень надеюсь, что она ничего не заметит.', },
    {'Отнесите связку шкур Кренне в Крепость Завоевателей.', },
  },
  [12180] = {
    'Пленные геологи',
    {'Регар послал в Дун Аргол отряд старателей, поручив им поиски артефактов и информации о происхождении сего поселения. Правда, они не ожидали обнаружить, что Дун Аргол до сих пор обитаем.|n|nТеперь железные дворфы держат их пленниками, пешками в грядущей войне. У нас нет людей, которых мы могли бы послать им на помощь, а Регар витает в облаках, мечтая о победе над железными дворфами без посторонней помощи.|n|nВся надежда на тебя, $N. Ключи от клеток могут быть у любого железного дворфа или его прислужника.', },
    {'Освободите геолога Ганна, геолога Торгана и геолога Варана, после чего вернитесь к горному пехотинцу Килиану в Лагерь горняков.', },
  },
  [12181] = {
    'Имя для заразы',
    {'Покажите образец гнили Тобиасу Саркхоффу в Ядозлоби.', },
    {'Покажите образец гнили Тобиасу Саркхоффу в Ядозлоби.', },
  },
  [12182] = {
    'В Ядозлобь!',
    {'Вот, я оставил для тебя специального нетопыря. Он самый быстрый и ловкий из всех, что у меня есть! Доставит тебя прямо в Ядозлобь – глазом моргнуть не успеешь.|n|nА там просто передай этот флакон главному распространителю чумы Миддлтону.', },
    {'Передайте образец гнили Главному распространителю чумы Миддлтону, который живет в Ядозлоби на востоке Драконьего Погоста.', },
  },
  [12183] = {
    'Часть маскировки',
    {'Если геолог Варана права, и с Локеном общаются только некоторые высокопоставленные дворфы, то я могу поспорить, что в их число входят надзиратели.|n|nНам придется послать тебя на разведку под прикрытием, для чего надо раздобыть для тебя подходящую униформу. |n|nЗатем я постараюсь придумать, как загримировать тебя под одного из железных дворфов.|n|nВ общем, отправляйся в Дун Аргол, убей одного из надзирателей и принеси мне его униформу. Учти, зальешь ее кровью – будешь отстирывать $Gсам:сама;!', },
    {'Принесите униформу надзирателя горному пехотинцу Килиану в Лагерь горняков.', },
  },
  [12184] = {
    'Улыбайтесь, вас снимают!',
    {'Отлично! У нас есть униформа, и не хватает только немного дополнительной информации, чтобы сделать маскировку идеальной.|n|nЯ тут вспомнил, что Регар привез с собой фотокамеру – отснять результаты исследований, но мы найдем для нее другое применение. Возьми ее с собой в Дун Аргол и сделай несколько снимков железных дворфов.|n|nКонечно, твои модели вряд ли обрадуются такой популярности, так что тебе придется их немного... утихомирить. И не забудь вернуть мне камеру со снимками!', },
    {'С помощью камеры Килиана сделайте снимки 8 железных дворфов в Дун Арголе, после чего вернитесь к горному пехотинцу Килиану в Лагерь горняков.', },
  },
  [12185] = {
    'Лучшая маскировка для Локена',
    {'С помощью этих изображений я смог сделать отличный набор для маскировки. $GДружище:Подруга;, из тебя получится отличный железный дворф!|n|nВот, возьми этот сверток в Дун Аргол, замаскируйся и отправляйся к самому восточному зданию на центральном ярусе.|n|nТам ты увидишь пьедестал, с помощью которого главы кланов и надзиратели получают указания от Локена. Прикоснись к нему и запомни все, что услышишь.', },
    {'Замаскируйтесь под железного надзирателя рун, перехватите послание от Локена и передайте его горному пехотинцу Килиану в Лагерь горняков.', },
  },
  [12186] = {
    'УКАЗАТЕЛЬ: Победитель',
    nil,
    nil,
  },
  [12187] = {
    'УКАЗАТЕЛЬ: Участник',
    nil,
    nil,
  },
  [12188] = {
    'Гниль Отрекшихся и вы: как не заразиться самим',
    {'Знать во всех подробностях о том, как действует гниль, тебе, пожалуй, ни к чему. Главное, свое дело она делает. Мне удалось вывести инертный штамм гнили.|n|n<Миддлтон открывает пробирку и вдыхает ее содержимое.>|n|nКак видишь, мое тело практически не пострадало. Но если теперь смешать это с нужным реактивом, все мы обратимся в бесформенные лужи слизи.|n|nНа побережье к югу отсюда находятся жалкие призраки древних солдат Альянса. Перебей их и принеси мне эктоплазменный осадок.', },
    {'Принесите главному распространителю чумы Миддлтону из Ядозлоби в Драконьем Погосте 10 образцов эктоплазменного осадка.', },
  },
  [12189] = {
    'Меня окружают идиоты!',
    {'Груз из Нового Агамонда должен был прибыть в Ядозлобь на прошлой неделе, а потом его должны были передать мне после простейших полевых испытаний. Это последнее, чего недостает Орде для победы.|n|n<Синтар вздыхает.>|n|nКак же тяжко жить, когда кругом одни идиоты!|n|nОтправляйся в Ядозлобь, что близ восточных границ Драконьего Погоста. Отыщи этого шута Миддлтона и напомни ему, что я жду свой груз!', },
    {'Отправляйтесь в Ядозлобь в Драконьем Погосте и поговорите с главным распространителем чумы Миддлтоном.', },
  },
  [12190] = {
    'Поздоровайся с моим маленьким другом',
    {'У Харкора челюсть отвалится, когда он увидит такие отборные продукты! Осталось только решить вопрос с доставкой.|n|nОн разбил лагерь на восточном краю леса, рядом с проклятыми руинами Дракил\'джин, так что добраться до него проще простого. Ну что, отнесешь ему ингредиенты – или предпочитаешь помочь мне с бальзамировкой трупов?', },
    {'Пригмон просит вас отнести ингредиенты для Харкора в Лагерь Харкора.', },
  },
  [12191] = {
    'Пей до дна!',
    nil,
    {'Попадите кружкой с бесплатным пивом в С.С.М. 5 раз, затем поговорите с Биззлем Эхпрокачуном.', },
  },
  [12192] = {
    'Однажды, напившись в...',
    {'Нам удалось на время остановить клан Черного Железа, но они вернулись и жаждут мести! Они то и дело выныривают невесть откуда, выпивают наше пиво и убегают в "Угрюмого обжору". Первым делом нам надо защитить наш лагерь, если мы сохраним наш бочонок – это будет победа!', },
    {'Поговорите с Биззлем Эхпрокачуном в лагере Хмельного фестиваля.', },
  },
  [12193] = {
    'А не будет ли сувенирчика в нынешнем году?',
    {'Главное на Хмельном фестивале – не гонки на баранах, а выпивка! Улучи минутку и отдай свой купон Белби Быстросмен. Она стоит за поляной, на которой проходит Хмельной фестиваль. Если ты ее не увидишь, не беспокойся, она-то тебя всяко заметит.|n|nВ общем, отдай ей свой купон, и получишь бесплатную праздничную кружку. Кроме того, именно Белби занимается прочей праздничной торговлей.', },
    {'Отоварьте свой купон на праздничную кружку у Бликса Чиништукса в лагере Хмельного фестиваля.', },
  },
  [12194] = {
    'А не будет ли сувенирчика в нынешнем году?',
    {'Мы не только поим всех подряд, но и дарим пивные кружки! Красивые, памятные кружки, полученные совершенно законным образом! Вот тебе купон на такую кружку.|n|nПоговори с Бликсом рядом с лагерем Хмельного фестиваля. Он довольно странный тип, тем более, что очки эти никогда не снимает. Он и отоварит твой купон. Он же занимается прочей праздничной торговлей.', },
    {'Отоварьте свой купон на праздничную кружку у Бликса Чиништукса в лагере Хмельного фестиваля.', },
  },
  [12195] = {
    'Незваный гость',
    {'Недавно наши охотники вернулись с вылазки с необычной добычей.|n|nОни наткнулись на раненого дворфа, бежавшего из крепости железных дворфов Дун Аргол. Возможно, он мог бы предоставить нам ценную информацию о нашем старом противнике, но пока что он не в состоянии говорить из-за сильной лихорадки.|n|nЯ слышал, что для изготовления лекарств отлично подходят рога серебристых оленей, которые бродят по ближайшему лесу. Если ты принесешь мне достаточное количество рогов, я позабочусь о том, чтобы разговорить нашего дорогого гостя.', },
    {'Принесите 5 рогов взрослых оленей Тормаку Бывалому из Лагеря Уанква.', },
  },
  [12196] = {
    'С самого начала',
    {'У нас слишком мало времени, чтобы самим браться за ковку. Литейные мастерские в Дун Арголе работают день и ночь, и пока мы выкуем детали для одного конструкта, они соберут десять таких же големов из готовых запчастей. |n|nТы $Gдолжен:должна; вернуться обратно и раздобыть детали, упомянутые в этих чертежах.|n|nДолжно быть, они валяются повсюду вокруг зданий, где работают железные кователи рун. |n|nПоторопись, $N. Кажется, Тормак только и ищет предлога для того, чтобы выполнить свою угрозу!', },
    {'Принесите 8 частей боевого голема геологу Рокару в Лагерь Уанква.', },
  },
  [12197] = {
    'Нам нужна энергия',
    {'Итак, я полностью закончил сборку оболочки голема, но Тормаку этого мало. Он просто не понимает, что механизм не заработает сам по себе, по его велению! Чтобы включить его, нам понадобятся батареи.|n|nВ Дун Арголе созданием зарядных ячеек занимаются два дворфа – рунический кузнец Дурар и рунический кузнец Каторн.|n|nЧтобы наш голем заработал, в него надо установить две энергобатареи.|n|nНайди этих рунических кузнецов. Их мастерские должны быть в самом центре Дун Аргола.', },
    {'Принесите энергобатареи Дурара и Каторна Геологу Рокару в Лагерь Уанква.', },
  },
  [12198] = {
    '... а может быть, и нет',
    {'Энергобатарея голема практически разряжена. Ее заряда хватит для питания двигателя, но на оборонные системы можно не рассчитывать.|n|nК счастью, периметр Дун Аргола патрулируют грозовые караульные – от них мы сможем подзарядить батарею.|n|nПодведи голема поближе, и он впитает энергию после смерти часового.', },
    {'Подзарядите вашего Боевого голема от десяти грозовых караульных и вернитесь к геологу Рокару в Лагерь Уанква.', },
  },
  [12199] = {
    'Свержение железного тана',
    {'Теперь, когда голем полностью заряжен, мы сможем свергнуть предводителя Дун Аргола с его помощью.|n|nПока я шпионил за таном Гневным Топором, я заметил, что его повсюду сопровождает личный голем-телохранитель.|n|nЗовут это чудовище Наковальня, но он не так неуязвим, как кажется. Один электромагнитный импульс может разрушить его изнутри и отключить защитную функцию. Возьми нашего голема и активируй его в периметре Дун Аргола.|n|nТы найдешь тана на вершине главного завода, где он инспектирует производство.', },
    {'Воспользовавшись особой функцией вашего Боевого голема, убейте железного тана Гневного Топора, после чего вернитесь к Тормаку Бывалому в Лагерь Уанква.', },
  },
  [12200] = {
    'Слезы изумрудного дракона',
    {'Теперь, когда инертный образец чумного состава завершен и у нас имеется активирующее его вещество, остается лишь найти подходящее вместилище для этих компонентов.|n|nК юго-западу отсюда, на берегах в центре Драконьего Погоста, находится Изумрудное святилище драконов. Внутри святилища ты найдешь затвердевшие остатки слез зеленого дракона. Я не знаю всей истории, но, видимо, перед смертью они немало плачут. Иди $Gсам:сама; посмотри.|n|nОтправляйся в Изумрудное святилище драконов и принеси оттуда слезы.', },
    {'Принесите 8 слез изумрудного дракона главному распространителю чумы Миддлтону в Ядозлобь в Драконьем Погосте.', },
  },
  [12201] = {
    'Тень надзирателя',
    {'Похоже, этот Локен стоит за всеми приготовлениями к войне со стороны железных дворфов.|n|nБоюсь, что приказы от него получают только высокопоставленные дворфы, поэтому нам придется замаскировать тебя под надзирателя. Только так ты сможешь узнать, что они замышляют.|n|nЯ знаю, как это сделать, но мне понадобятся кое-какие материалы.|n|nДля начала тебе придется убить одного из железных надзирателей рун в Дун Арголе на юго-востоке и принести мне его униформу.', },
    {'Принесите униформу надзирателя Разведчику Вор\'такху в Лагерь Уанква.', },
  },
  [12202] = {
    'Улыбайтесь, вас снимают!',
    {'Теперь нам осталось только сделать тебя $Gпохожим:похожей; на железных дворфов.|n|nХорошо бы иметь перед собой образец, с которого мы будем копировать их мерзкие рожи.|n|nЯ тут вспомнил, что однажды охотничий отряд Тормака наткнулся на заблудившегося геолога и отобрал у него фотокамеру в качестве трофея. Пожалуй, теперь она нам пригодится.|n|nВозьми ее с собой в Дун Аргол, убей несколько железных дворфов и запечатлей их физиономии. Как сделаешь достаточное количество фотографий, возвращайся ко мне.', },
    {'С помощью камеры Рокара сделайте снимки 8 железных дворфов в Дун Арголе, после чего вернитесь к Разведчик Вор\'такху в Лагерь Уанква.', },
  },
  [12203] = {
    'Приказы Локена',
    {'Вот, я собрал все, что надо для того, чтобы замаскировать тебя под надзирателя. Знаю, выглядит мерзко, но ты уж постарайся сдержать свои эмоции, когда будешь напяливать эту гадость. Ну, ты понимаешь – надо, чтобы в тебе никто не усомнился.|n|nДержи маскировочный набор и отправляйся на юго-восток, к Дун Арголу. Там переоденься и иди к самому восточному зданию в центральной части города.|n|nТам ты увидишь пьедестал, где надзиратели получают указания от Локена. Прикоснись к пьедесталу и запомни все, что услышишь.', },
    {'Замаскируйтесь под железного надзирателя рун, перехватите послание от Локена и передайте его разведчику Вор\'такху в Лагерь Уанква.', },
  },
  [12204] = {
    'Во имя Локена',
    {'Железные дворфы были и остаются нашими самыми организованными и жестокими конкурентами за влаcть в Нордсколе. Куда бы мы не сунулись, они всюду преследуют нас с именем Локена на устах.|n|nМы должны узнать, кто такой этот Локен и чего он добивается.|n|nК северо-востоку отсюда есть Торговая лавка Красного леса, в которой торгует человек по имени Хью Гласс. А на востоке, среди Руины Тетиса, обитает каменный великан Гаврок. Эти двое могут рассказать тебе кое-что полезное о Локене.', },
    {'Поговорите с Хью Глассом и Гавроком о Локене, после чего передайте полученные сведения разведчику Вор\'такху из Лагеря Уанква.', },
  },
  [12205] = {
    'Разыскивается: Алый Натиск',
    {'Приказом верховного палача Роса все члены незаконной организации, известной как Алый Натиск, подлежат немедленной казни на месте!|n|nПощады не давать никому. Тем, кто участвует в этом деле, следует иметь в виду, что любой, попавший в плен к людям, будет убит, или того хуже.|n|nКак сказал верховный палач, "Пусть белый снег станет красным от их крови!"', },
    {'Убейте 20 членов Алого Натиска и доложите об этом верховному палачу Росу из Ядозлоби.', },
  },
  [12206] = {
    'Испорченные последние ритуалы',
    {'Ты $Gчитал:читала; доску объявлений? Что думает верховный палач?|n|n<Вики оглядывается и продолжает на пониженных тонах.>|n|nМы же не можем позволить, чтобы этих идиотов из Алого Натиска подняли их жрецы или, что еще хуже, чтобы они были подняты как воины Плети, правда?|n|nНет, я полностью с тобой согласна, мы просто должны что-то сделать с телами.|n|nИ у меня есть то, что нужно. Возьми этот настой порчи, что мы только что изготовили, и опробуй его на пленнике, сидящем в клетке – здесь, рядом.|n|nНикаких заморочек – никакого возвращения врагов.', },
    {'По просьбе аптекаря Вики Левин из Ядозлоби испробуйте настой порчи на узнике Алого Натиска.', },
  },
  [12207] = {
    'Падение Фордрассила',
    {'Давным-давно некие могущественные друиды посадили мировое древо на северо-востоке.|n|nИмя ему было Фордрассил. По неведомой причине те же самые друиды решили уничтожить его, когда оно выросло.|n|nИ вот, с тех пор, как мы прибыли сюда, я слышу плач земли. Она стонет, ибо ядовитая слизь разъедает ее в тех местах, где упали обломки великого древа. |n|nПрошу тебя, принеси мне образцы этой слизи, и я попытаюсь исцелить землю.', },
    {'Заклинательница ветра Серый Рог из Крепости Завоевателей просит вас отправиться к Ветвям Фордрассила, Сердцу Фордрассила или Слезам Фордрассила и принести ей 6 образцов слизи энтропических слизнюков.', },
  },
  [12208] = {
    'Удачи в охоте за троллями!',
    {'Никчемные твари!|n|nНеужели нельзя было договориться по-хорошему? Мы протянули им руку мира! Им оставалось только предоставить нам безопасный проход через Драк\'Тарон – и мы бы оставили их в покое. |n|nНо нет, эти заносчивые ледяные тролли решили, что они хотят войны. Теперь мы сотрем их с лица земли и захватим их драгоценную крепость!|n|nМы уже наняли банду головорезов, которые будут поставлять нам захваченных троллей для допроса. Поговори с Самиром, если ты тоже не хочешь оставаться в стороне. Его легко найти на северо-западе отсюда, к югу от Зеб\'Халека.', },
    {'Сержант Туркин отправил вас к Самиру в Гранитные ключи.', },
  },
  [12209] = {
    'Кража материальных ценностей',
    {'Ах, да, свежее мясо прибыло. Хочешь проявить себя, салага?|n|nВоины Алого Натиска – самого фанатичного и расистского крыла Алого ордена – у нас уже под самым носом, к югу. Если мы хотим с ними сразиться, нам понадобится больше доспехов и оружия, чем я сумею раздобыть за столь короткое время.|n|nПочему бы нам не позаимствовать их вооружение?|n|nЯ бы даже сказал, почему бы ТЕБЕ его не позаимствовать?', },
    {'По заданию интенданта Бартлетта из Ядозлоби похитьте 8 доспехов Алого Натиска и 8 единиц оружия Алого Натиска.', },
  },
  [12210] = {
    'Сезон охоты на троллей!',
    {'Эй, |3-6($R)! Хватит стоять столбом, у нас полно работы!|n|nМы нашли самый короткий путь в Зул\'Драк – через Крепость Драк\'Тарон. Мы должны захватить ее, чтобы обеспечить безопасный проход для войск Альянса. А пока мы собираем армию для осады крепости, самое время заняться истреблением ледяных троллей и сбором разведданных.|n|nДля этих целей мы собрали отряд головорезов, которые будут захватывать и доставлять к нам живых троллей для допроса. Отправляйся на северо-запад, к Гранитным ключам, и поговори с Самиром. Он скажет тебе, что делать дальше.', },
    {'Лейтенант Думонт из Приюта Янтарной Сосны послал вас поговорить с Самиром в Гранитных ключах.', },
  },
  [12211] = {
    'Не дадим им подняться!',
    {'Я просто не понимаю. Этот настой должен был сработать!|n|nНу, нечего теперь об этом беспокоиться.|n|n<По какой-то причине аптекарь вовсе не выглядит сильно расстроенной.>|n|nХотя он по каким-то причинам не подействовал на этих, из Натиска, мы все же должны сделать так, чтобы их жрецы не смогли поднять трупы.|n|nУ меня есть другая идея – идея, против которой у трупов нет никакой защиты.|n|n$N, возьми мою клетку с крысами и выпусти их на любые тела Алого Натиска, на какие наткнешься в Новом Дольном Очаге. Я морила голодом этих тварей, так что они должны оказаться весьма прожорливыми!', },
    {'По заданию аптекаря Вики Левин из Ядозлоби воспользуйтесь ее клеткой с крысами в Новом Дольном Очаге, чтобы ободрать дочиста 15 тел, принадлежащих Алому Натиску.', },
  },
  [12212] = {
    'Пополнение запасов',
    {'Доброго тебе дня, |3-6($C).|n|nВон тот славный лейтенант утверждает, что набег Орды на наши склады практически оставил нас без продовольствия.|n|nМы, конечно, заставим этих мерзавцев пожалеть о содеянном, но сначала нам надо восполнить наши запасы. Мои люди трудятся не покладая рук, без твоей помощи нам не обойтись.|n|nПолагаю, тебе не составит труда добыть немного оленины – в этих краях полно диких оленей. Удачной охоты!', },
    {'Старший лесник Андорхол из Приюта Янтарной Сосны просит вас убить несколько высокорогих оленей и принести ему 8 кусков сочной оленины.', },
  },
  [12213] = {
    'Подземная тьма',
    {'Что-то страшное случилось с этим деревом, Фордрассилом. После того как друиды уничтожили мировое древо, его обломки пустили корни глубоко в землю.|n|nЯ хочу, чтобы ты $Gразыскал:разыскала; три части великого ствола, упавших далеко на севере-востоке, и $Gуглубился:углубилась; как можно дальше под землю.|n|nКак только ты окажешься на месте, воспользуйся этим шаром, чтобы замерить выброс энергии. Возможно, наши исследования прольют свет на тайну уничтожения мирового древа.', },
    {'Заклинательница ветра Серый Рог из Крепости Завоевателей просит вас отыскать Сердце Фордрассила, Слезы Фордрассила и Ветви Фордрассила, углубиться под землю и воспользоваться Геомантской сферой для измерения уровня энергии.', },
  },
  [12214] = {
    'Новые кони',
    {'Здравствуйте, я Ханзел. Рад познакомиться, $Gгосподин:госпожа;.|n|nВерховный палач пришел ко мне и говорит: "Ханзел, раздобудь нам новых коней".|n|nА где я ему возьму этих коней? Из-под земли достану?|n|n<шепотом> На самом деле можно и из-под земли, главное, найти подходящий скотомогильник...|n|nНо скотомогильников у нас под рукой нет, так что придется вам отправиться на юг, в Новый Дольный Очаг, чтобы убивать там рыцарей и забирать их боевых скакунов.|n|nВернитесь на коне ко мне сюда и передайте мне поводья.', },
    {'Украдите 3 боевых коней Алого Натиска и доставьте их Ханзелу Бауэру в Ядозлобь. Передайте Ханзелу поводья из рук в руки.', },
  },
  [12215] = {
    'Мы или они!',
    {'Вот только этого нам еще не хватало...|n|nНынешний кризис продовольствия поставил нас в такое тяжелое положение, что мы вынуждены бороться за каждый кусок мяса с местными воргами. Ситуация ухудшается с каждым днем, и я боюсь, что скоро мы просто истребим всю дичь в округе. |n|nОтправляйся в лес, |3-6($R), и убей всех воргов, которые попадутся тебе на пути. Мои разведчики видели целую стаю на другом берегу реки к западу отсюда.', },
    {'Андерхол из Приюта Янтарной Сосны просит вас найти и убить 6 серо-дымчатых охотников в Седых холмах.', },
  },
  [12216] = {
    'Бери самое нежное!',
    {'Хотя мы еще не достигли поставленной цели, наш упорный труд уже начал приносить плоды. Увы, теперь стало очевидно, что местных оленей не хватит, чтобы обеспечить пропитанием всех жителей. |n|nБоюсь, нам придется обратить внимание на более опасную добычу – медведей гризли. В Седых холмах они водятся в изобилии, питаясь рыбой из многочисленных ручьев.|n|nУдачи тебе!', },
    {'Андерхол из Приюта Янтарной Сосны просит вас добыть 8 боков медведей гризли, которые водятся в Седых холмах.', },
  },
  [12217] = {
    'Орлиный взор',
    {'Итак, $N, теперь мы знаем, каким образом Орде удается выслеживать наши склады с продовольствием. |n|nОни магическим образом привязывают свой дух к зрению ничего не подозревающих орлов, которые кружат над верхушками деревьев. С их помощью они безнаказанно шпионят за каждым нашим шагом.|n|nПо приказу лейтенанта мы должны уничтожить этих величественных птиц, попавших под влияние наших врагов.', },
    {'Андерхол из Приюта Янтарной Сосны просит вас убить 5 императорских орлов и доложить ему о выполнении задания.', },
  },
  [12218] = {
    'Добрые вести не ждут на месте',
    {'Прежде чем я смогу отправить тебя к доктору Злобениусу с хорошими новостями, тебе придется еще провести обычное полевое испытание, но с некоторыми изменениями.|n|nИз останков старой крепости Стражей Зимы по-прежнему прут проголодавшиеся покойники. Выезжай на машине из восточных ворот и направляйся на северо-восток, через перевал Возмездия, пока не доберешься до двух башен на юго-восточной окраине крепости. Метни чумную бомбу в нежить, которая там кишит. И доложи мне о результатах!', },
    {'Используйте чумную бомбу распространителя гнили Отрекшихся, чтобы уничтожить 30 голодающих покойников на краю Полей Падальщиков по приказу главного распространителя чумы Миддлтона из Ядозлоби в Драконьем Погосте.', },
  },
  [12219] = {
    'Обломки мирового древа',
    {'Давным-давно мои предки посадили дерево в самом сердце Седых холмов.|n|nБудущее мировое древо было названо Фордрассил.|n|nОднако когда дерево выросло, по неведомым мне причинам его решили уничтожить. Гигантский ствол раскололся на три обломка, которые упали далеко на севере.|n|nНо в том месте, где они коснулись земли, из-под обломков начала распространяться омерзительная слизь, заражая все вокруг. Пожалуйста, принеси мне несколько образцов этой заразы, чтобы я смогла найти способ излечить землю.', },
    {'Иерофант Тайрин из Приюта Янтарной Сосны просит вас найти Ветви Фордрассила, Сердце Фордрассила или Слезы Фордрассила и принести ей 6 образцов слизи энтропических слизнюков.', },
  },
  [12220] = {
    'Темное влияние',
    {'Когда Фордрассил был уничтожен, его обломки пустили корни глубоко в землю.|n|nЯ хочу, чтобы ты $Gразыскал:разыскала; три части великого ствола, упавших далеко на севере, и $Gуглубился:углубилась; как можно дальше под землю.|n|nКак только ты окажешься на месте, воспользуйся этим шаром, чтобы определить выброс энергии в этом месте. Если мы хотим исцелить землю, нам прежде всего надо выяснить, что привело к гибели мирового древа.', },
    {'Иерофант Тайрин из Приюта Янтарной Сосны просит вас отыскать Сердце Фордрассила, Слезы Фордрассила и Ветви Фордрассила, углубиться под землю и воспользоваться Геомантской сферой для измерения уровня энергии.', },
  },
  [12221] = {
    'Гниль Отрекшихся',
    {'Я подготовил пакет, который нужно доставить доктору Синтару Злобениусу в Молот Агмара. Содержимое этого пакета составляет окончательный образец гнили вместе с инструкциями по изготовлению и образцами реагентов.|n|nМолот Агмара находится в западной части Драконьего Погоста. Как увидишь черные зубчатые металлические орочьи здания, – это и есть Молот Агмара.', },
    {'Доставьте образец гнили Отрекшихся доктору Синтару Злобениусу в Молот Агмара.', },
  },
  [12222] = {
    'Тайны прядильщиц пламени',
    {'Пока мы пытаемся дать отпор Орде, клан Укротителей драконов вербует новую армию в деревне Волдрун, которая находится у побережья на юге.|n|nСамые могущественные воины в этой деревне носят огнепрочные талисманы, которые дают им власть над могущественными протодраконами. Нам бы подчинить себе этих драконов – и можно было бы не опасаться угрозы, исходящей из Волдруна!|n|nА создают эти магические талисманы огневязы из клана Укротителей драконов. Убей их и принеси мне амулеты!', },
    {'Принесите 3 огнепрочных талисмана плотнику Дрейку в Приют Янтарной Сосны.', },
  },
  [12223] = {
    'Ослабление врага',
    {'Наши разведчики докладывают, что врайкулы опять проявляют бурную активность в южной деревне Волдрун. Тан Торвальд Эрикксон и его шавки готовятся к войне. А пока большинство наших людей разбираются с подлыми засадами ордынцев, Приют Янтарной Сосны не сможет оказать сопротивления захватчикам!|n|nОтправляйся на южное побережье, в Волдрун, и покажи этим Укротителям драконов, что нас лучше обходить стороной.|n|nУбей всех хускерлов, которые встретятся тебе на пути. Пусть они дважды подумают, стоит ли с нами связываться.', },
    {'Убейте 12 хускерлов из клана Укротителей драконов и вернитесь к плотнику Дрейку в Приют Янтарной Сосны.', },
  },
  [12224] = {
    'Авангард кор\'крона',
    {'Ты молодец, $Gбрат:сестра;. Во всех своих деяниях ты $Gпоказал:показала; себя $Gверным:верной; $Gзащитником:защитницей; Орды. Ты $Gпопирал:попирала; ногами воинов Ануб\'ара из Азжол-Неруба! Именно благодаря тебе у Орды теперь есть новые союзники, таунка, сильные и отважные! И наше супер-оружие в войне с Плетью также испытано и усовершенствовано тобой!|n|nПришел час твоей славы – тебя ждет наше элитное подразделение у Врат Гнева. Сын Саурфанга ждет твоего прихода в авангард кор\'крона! Твой путь лежит на северо-восток, к Вратам Гнева.', },
    {'Явитесь к Саурфангу Младшему в авангард кор\'крона.', },
  },
  [12225] = {
    'М-м-м... Янтарные желуди!',
    {'Вы чувствуете аппетитный запах сочных орехов, доносящийся из корзинки с семенами, и ваш желудок протестующе урчит.|n|nВидимо, какая-то добрая душа оставила здесь эти семена для подкрепления уставших путников. Вы с благодарностью съедаете оставшиеся орешки.|n|nВкус у этих семян еще лучше, чем запах! Теперь вы непременно хотите узнать, где можно достать еще больше этого лакомства.', },
    {'Поговорите с искусным резчиком по дереву Андерхолом в Приюте Янтарной Сосны.', },
  },
  [12226] = {
    'Ух, пронесло!',
    {'Надо действовать быстро, |3-6($R)! Нельзя допустить, чтобы эти драгоценные семена полностью разложились. Мы должны извлечь их, и немедленно!|n|nСкорее, принеси мне несколько стеблей чернокорня – он растет на берегу реки к западу отсюда – и я сделаю тебе эффективное слабительное.|n|nНу что ты стоишь столбом, беги! В конце концов, ты $Gсам виноват:сама виновата;...', },
    {'Андерхол из Приюта Янтарной Сосны просит вас принести ему 5 стеблей чернокорня.', },
  },
  [12227] = {
    'За дело!',
    {'Держи слабительное, |3-6($R).|n|nУчти – оно срабатывает мгновенно, так что сначала отыщи отхожее место и запрись там покрепче.|n|nВсе, иди за желудями!', },
    {'Андерхол из Приюта Янтарной Сосны просит вас взять слабительную настойку Андерхола и воспользоваться ближайшим туалетом, чтобы извлечь частично переваренные янтарные желуди.', },
  },
  [12228] = {
    'Возвращение магии [PH]',
    nil,
    nil,
  },
  [12229] = {
    'Возможная связь',
    {'Не так давно мы отправили на восток экспедицию, которую растерзали бешеные фурболги. Единственный выживший рассказал, что видел странную темную жидкость, вытекавшую из тела убитого нападавшего.|n|nМногие тысячи лет фурболги жили в мире друг с другом и с окружающими. Мне кажется, что их агрессивность как-то связана с этой темной жидкостью и со зловещей силой, которую мы обнаружили ранее.|n|nПожалуйста, принеси мне несколько образцов крови фурболгов. Ты найдешь их в Святилище Красного Клыка и Святилище Кровавого Сердца, которые находятся на востоке.', },
    {'Заклинательница ветра Серый Рог из Крепости Завоевателей просит вас принести 8 образцов крови безумных фурболгов, обитающих в Святилище Кровавого Сердца и Святилище Красного Клыка.', },
  },
  [12230] = {
    'Кража у осадных мастеров',
    {'Мне поручено уничтожить баллисты Алого Натиска. К сожалению, мы с аптекарями расходимся во мнениях касательно использования имеющихся ресурсов, так что мне просто нечем их уничтожить!|n|nК северо-востоку отсюда находятся Поля Падальщиков. Осадные мастера Плети со своей кузницей и полными повозками мяса большие мастера разрушения.|n|nК счастью для нас, они оставляют без присмотра свои бомбы.|n|nЯ хочу, чтобы ты $Gраздобыл:раздобыла; их для меня. И мне все равно, где ты их достанешь: поднимешь с земли или отберешь у осадных мастеров.', },
    {'По поручению Стража смерти Молдера из Ядозлоби раздобудьте 6 осадных бомб.', },
  },
  [12231] = {
    'Отпрыски медвежьего бога',
    {'Возможно, фурболгов Седых холмов затронула та же скверна, что заразила Фордрассил. Иначе я не могу объяснить, почему после стольких лет мира они оказались вовлечены в страшную, братоубийственную войну.|n|nНа востоке отсюда есть тщательно охраняемые святилища, которые стали домом отпрыскам Урсока.|n|nОстается лишь уповать на то, что порча не возымела действие на наследников бога, Кодиан и Орсонна.|n|nРазыщи их и выслушай, что они могут нам поведать.', },
    {'Заклинательница ветра Серый Рог из Крепости Завоевателей просит вас разыскать Орсонна в Святилище Красного Клыка и Кодиан в Святилище Кровавого Сердца.', },
  },
  [12232] = {
    'Бомбардировка баллист',
    {'Наконец-то у нас появился шанс ударить по их осадным машинам! Не облажайся!|n|nШучу.|n|nОтчасти.|n|n$C, ты $Gдолжен:должна; уничтожить баллисты Нового Дольного Очага с помощью этих бомб.|n|nМы покажем Королевскому фармацевтическому обществу, как это делалось в старые добрые времена! Никаких замысловатостей, никаких сложных рецептов!', },
    {'По заданию Стража смерти Молдера из Ядозлоби уничтожьте 5 баллист Нового Дольного Очага с помощью осадных бомб.', },
  },
  [12233] = {
    '[Depricated]Высадить семена',
    {'Нет, нет... Оставь их себе.|n|nТы же не думаешь, что я заберу из после всего, что ты с ними $Gсделал:сделала;?|n|nСлушай; вот что мы теперь должны предпринять...', },
    nil,
  },
  [12234] = {
    'Надо знать',
    {'Мне нужно знать, что замышляют в Новом Дольном Очаге.|n|nУкради их сегодняшние приказы, чтобы я могла это выяснить.|n|nСтупай на юг и осмотри аббатство, казармы и побережье – найди их текущие планы действий!|n|nЕсли вдруг заблудишься, казармы – это такое здоровенное здание рядом с кузницей.', },
    {'Украдите текущие приказы Алого Натиска в аббатстве, в казармах и на побережье по просьбе госпожи шпионов Репины из Ядозлоби.', },
  },
  [12235] = {
    'Наксрамас и падение крепости Стражей Зимы',
    {'Лорд Фордрагон возглавил сокрушительную атаку на Артаса у Врат Гнева. За это Артас направил против нас Наксрамас. В то время как Кел\'Тузад скрывается в парящей цитадели, его военачальник, Тельзан, осаждает крепость Стражей Зимы. Нижняя часть поселения уже потеряна, и надежда вызволить выживших тает с каждой минутой.|n|nДействовать нужно быстро! Срочно обратись к командиру грифонов Урику на грифоньей площадке! Он поможет тебе быстро добраться до места.|n|nСтупай!', },
    {'Поговорите с командиром грифонов Уриком на грифоньей площадке в крепости Стражей Зимы.', },
  },
  [12236] = {
    'Урсок, медвежий бог',
    {'Время пришло, $N. Возьми этот пепел и принеси его фурболгу, о котором упоминала Кодиан. Если он отправился на поиски Урсока, то его следы должны привести тебя к логову на севере Седой Пасти.|n|nУвы, ты не справишься без его помощи. $GОдному:Одной; тебе никогда не одолеть Урсока.|n|nКак только вы одержите победу над Урсоком, воспользуйся этим пеплом, чтобы очистить его дух. Даже если его физическое тело будет уничтожено, душа должна быть спасена.', },
    {'Заклинательница ветра Серый Рог из Крепости Завоевателей просит вас найти Тура Яролапа возле Логова Урcока и победить Урсока с его помощью. Когда Урсок падет, осыпьте его тело очищенным пеплом Фордрассила.', },
  },
  [12237] = {
    'Полет защитника Стражей Зимы',
    {'При помощи этого свистка ты можешь призвать грифона Стражей Зимы. Взбирайся на него и направляйся к руинам деревни Стражей Зимы, ныне известным как Поля Падальщиков, на юго-восток отсюда. Когда доберешься до полей, смотри в оба и ищи беспомощных селян Стражей Зимы. Когда заметишь кого-то из них, опускайся ниже и с помощью грифона подбери несчастного. Привези спасенного сюда, на грифонью площадку.|n|nТам повсюду кишат воины Плети, так что не зевай! Удачи!', },
    {'Спасите 10 беспомощных селян Стражей Зимы и возвращайтесь к командиру грифонов Урику в крепость Стражей Зимы.', },
  },
  [12238] = {
    'Очищение Драк\'Тарона',
    {'Друг мой, настало время действовать.|n|nСкоро Драк\'Тарон будет очищен от этой мерзкой нежити и засияет во всей своей былой славе. Моя душа обретет покой, а ты в награду за свои великие деяния обретешь великое сокровище!|n|nЭта крепость ведет к священному зиккурату. Встань на его вершине и призови меня в последний раз, чтобы я провел ритуал очищения. |n|nУвы, но тебе снова придется заплатить за вызов моего духа. Но в крепости еще остались выжившие, у кого ты сможешь забрать еще немного настоя.', },
    {'Дракуру просит вас выпить эликсир возле его жаровни в Драк\'Тароне. Для использования эликсира вам понадобится пять настоев терпения.', },
  },
  [12239] = {
    'Шпион в Новом Дольном Очаге',
    {'В рядах Алого Натиска у меня есть шпионка. Мне нужно, чтобы ты $Gпередал:передала; ей дневное задание, чтобы она могла спланировать следующую фазу нашей атаки.|n|nОна откликается на имя агента Скулли и находится там под личиной кладбищенского смотрителя Алого Натиска.|n|nВот это задание, отнеси ей и сделай то, о чем она попросит. Кладбище находится рядом с аббатством.', },
    {'Доставьте текущие приказы Алого Натиска агенту Скулли в Новый Дольный Очаг.', },
  },
  [12240] = {
    'Цель и средства',
    {'Моя сестра, живущая на родине, в Бастионе, прислала мне с последним кораблем несколько бочонков с термитами. Думаю, они пригодятся для того, что я от тебя хочу.|n|nНам очень мешает лесопилка в Новом Дольном Очаге, но до сих пор мы никак не могли пробраться внутрь, чтобы выманить их десятника.|n|nДумаю, что если натравить этих термитов на его драгоценные доски и бревна, он уж точно прибежит как миленький!|n|nНу что, |3-6($C), возьмешься его ликвидировать?', },
    {'Используйте термитов семейки Левин, чтобы выманить штейгера Калейки и убить его по просьбе аптекаря Вики Левин из Ядозлоби.', },
  },
  [12241] = {
    'Уничтожить саженец',
    {'Увы, $N, нам придется вмешаться в работу фурболгов. Я понимаю их благие намерения, но не могу допустить, чтобы заражение распространялось.|n|nЭтот саженец – источник зла, и потому он должен быть уничтожен. Возьми этот факел, подожги им зараженный саженец, и принеси мне пепел. |n|nОчищенный огнем, он поможет нам побороть скверну. С помощью этого пепла ты изгонишь злые силы из Урсока.', },
    {'Заклинательница ветра Серый Рог из Крепости Завоевателей просит вас взять лиственный факел и сжечь саженец Фордрассила. Принесите пепел Фордрассила Серому Рогу.', },
  },
  [12242] = {
    'Семена Фордрассила',
    {'Мы должны убедиться в том, что Фордрассил никогда не вырастет вновь. Я боюсь, что фурболги уже посадили его семя. |n|nОтправляйся в Седую Пасть, что в самом сердце Седых холмов, и собери все семена, которые сможешь найти. Я постараюсь их уничтожить.', },
    {'Заклинательница ветра Серый Рог из Крепости Завоевателей просит вас отправиться в Седую Пасть и принести ей 8 семян Фордрассила.', },
  },
  [12243] = {
    'Огонь над водами',
    {'У меня есть для тебя еще одно задание.|n|nМне удалось переработать кое-что из настоя порчи в мою знаменитую на весь мир огненную воду. Я хочу, чтобы ты $Gвзял:взяла; ее и $Gподжег:подожгла; паруса "Глупости грешника"!|n|nИспользуй воду прямо из дока. Когда паруса вспыхнут, матросы будут сильно заняты, разбираясь с ними, а ты пока проскользнешь в нижнее помещение и добудешь бумаги капитана.|n|nКорабль найдешь в Стоянке рыцарей, ниже и к югу от Нового Дольного Очага. Капитанская каюта расположена на первой нижней палубе, под лестницей.', },
    {'По заданию аптекаря Вики Левин из Ядозлоби воспользуйтесь Пылающей водой аптекаря, чтобы поджечь паруса "Глупости Грешника".|n|nПока матросы будут заняты тушением пожара, спуститесь вниз и раздобудьте у капитана лоцию капитана Шели.', },
  },
  [12244] = {
    'Починка крошшеров',
    {'Эй, $Gдружище:подруга;! Закатай рукава и берись за работу! У нас тут полно дел! Вон те крошшеры еще вчера надо было подлатать и отправить в Бухту торговцев!..|n|nЧто? У тебя нет инструментов? А зачем ты вообще сюда $Gпришел:пришла;? $GТопал:Топала; бы себе вместе с остальными дурнями сражаться с Ордой!|n|nМожет быть, твоих жалких мозгов хватит хотя бы на то, чтобы отвезти эти сломанные крошшеры на ремонт и не растрясти их по дороге?', },
    {'Синипус с Лесозаготовок Синего Неба просит вас привезти ему 3 сломанных крошшера.', },
  },
  [12245] = {
    'Никакой пощады пленникам',
    {'Много еще есть глупцов, которых тебе нужно будет убить.|n|nМои агенты сообщают, что кое-кто из наших добрых горожан вот-вот упадет прямо в объятия Алого Натиска.|n|nНет уж, этого не произойдет.|n|nОтправляйся в Новый Дольный Очаг и прикончи стража смерти Шнайдера, главного писаря Барригу, инженера Бурка и канцлера Амай.|n|nКак я слышала, они содержатся в разных местах. Уж конечно, сидят в клетках и дрожат в ожидании казни.|n|nПоговори с ними, а затем убей!', },
    {'По поручению госпожи шпионов Репины убейте Стража смерти Шнайдера, главного писаря Барригу, инженера Бурка и канцлера Амай.|n|nКогда выполните это задание, сообщите об этом верховному палачу Росу в Ядозлобь.', },
  },
  [12246] = {
    'Возможная связь',
    {'Живущие на востоке фурболги более дикие и агрессивные, чем те, с которыми тебе уже приходилось встречаться. Нашим отрядам случалось сталкиваться с этими тварями, и каждый раз немногочисленные выжившие рассказывали о темной вязкой жидкости, сочившейся из трупов поверженных фурболгов. |n|nВозможно, это как-то связано с порчей, обнаруженной нами на останках Фордрассила. |n|nПожалуйста, принеси мне несколько образцов крови фурболгов. Ты найдешь их в Святилище Красного Клыка и Святилище Кровавого Сердца, которые находятся на востоке.', },
    {'Иерофант Тайрин из Приюта Янтарной Сосны просит вас принести 8 образцов безумных фурболгов, обитающих в Святилище Кровавого Сердца и Святилище Красного Клыка.', },
  },
  [12247] = {
    'Дети Урсока',
    {'Теперь я уверена, что эту скверну распространяют фурболги Седых холмов. Долгие годы они жили в мире, но с недавних пор меж их племенами идет кровопролитная война.|n|nОсталось лишь узнать, затронула ли порча двух медведей, которых они почитают как богов.|n|nДвое отпрысков Урсока, Орсонн и Кодиан, обитают в Святилище Красного Клыка и Святилище Кровавого Сердца, что на юге и юго-востоке Седой пасти.|n|nОбратись к ним – может быть они могут поведать нам что-нибудь об этой беде.', },
    {'Иерофант Тайрин из Приюта Янтарной Сосны просит вас разыскать Орсонна в Святилище Красного Клыка и Кодиан в Святилище Кровавого Сердца.', },
  },
  [12248] = {
    'Саженец Фордрассила',
    {'У древних друидов были веские причины уничтожить Фордрассил. Мы не можем позволить фурболгам возродить его!|n|nПроблема в том, что спасение духа Урсока зависит от магии, содержащейся в саженце мирового древа.|n|nВозьми этот факел и сожги саженец, произрастающий в центре Седой Пасти, в старой кадке Фордрассила.|n|nПринеси мне пепел, оставшийся после сожжения дерева. Я надеюсь, что огонь очистит его от скверны, и мы сможем воспользоваться его магией для исцеления духа Урсока.', },
    {'Иерофант Тайрин из Приюта Янтарной Сосны просит вас взять зеленый факел и сжечь саженец Фордрассила. Принесите ей пепел Фордрассила.', },
  },
  [12249] = {
    'Урсок, медвежий бог',
    {'Время пришло, $N. Возьми этот пепел и принеси его фурболгу, о котором упоминала Кодиан. Если он отправился на поиски Урсока, то его следы должны привести тебя к логову на севере Седой Пасти.|n|nУвы, ты не справишься без его помощи. $GОдному:Одной; тебе никогда не одолеть Урсока.|n|nКак только вы одержите победу над Урсоком, воспользуйся этим пеплом, чтобы очистить его дух. Надеюсь, все наши труды были не напрасны...', },
    {'Иерофант Тайрин из Приюта Янтарной Сосны просит вас найти Тура Яролапа возле Логова Урcока и победить Урсока с его помощью. Когда Урсок падет, осыпьте его тело очищенным пеплом Фордрассила.', },
  },
  [12250] = {
    'Семена Фордрассила',
    {'Мы должны убедиться в том, что Фордрассил никогда не вырастет вновь. Я боюсь, что фурболги уже посадили его семя. |n|nОтправляйся в Седую Пасть, что в самом сердце Седых холмов, и собери все семена, которые сможешь найти. Я постараюсь их уничтожить.', },
    {'Иерофант Тайрин из Приюта Янтарной Сосны из Крепости Завоевателей просит вас отправиться в Седую Пасть и принести ей 8 семян Фордрассила.', },
  },
  [12251] = {
    'Возвращение к верховному главнокомандующему',
    {'Вернись скорее к верховному главнокомандующему Халфорду Змеевержцу, $N. Скажи ему, что твоя миссия выполнена и что немногие оставшиеся в живых жители деревни вернулись к работе.', },
    {'Поговорите с верховным главнокомандующим Халфордом Змеевержцем в крепости Стражей Зимы на Драконьем Погосте.', },
  },
  [12252] = {
    'Истязание истязателя',
    {'Достаточно! Я хочу, чтобы ты $Gположил:положила; конец мучениям моего народа!|n|nИстязатель Алого Натиска, Лекрафт, клещами вытягивает информацию из любого, кто попадется этим мерзавцам! Мне нужно знать, что им известно.|n|nМои источники сообщают, что он организовал свою "мастерскую" в подвале казарм, прямо рядом с кузницей.|n|nЯ тебе одолжу свое собственное клеймо, чтобы быть уверенным, что дело будет сделано как надо.|n|nНайди его – и добудь информацию.', },
    {'По поручению верховного палача Роса из Ядозлоби пять раз припечатайте клеймом истязателя Лекрафта, чтобы вытянуть из него нужную информацию. Получив ее, убейте Лекрафта.', },
  },
  [12253] = {
    'Спасение с городской площади',
    {'Эта дорога ведет на городскую площадь крепости Стражей Зимы. Некогда там кипела жизнь, теперь же это зона боевых действий, кишащая злобными упырями, жаждущими мести всему живому.|n|nА в зданиях, окружающих площадь, заперты деревенские жители. Их надо спасти! Понимаю, $N, я прошу очень многого, но ты – единственный солдат, без которого я могу обойтись. Освободи наших людей. Ступай на площадь, войди в эти дома. Убивай всех, кто попытается тебе помешать! Если выживешь, возвращайся ко мне.', },
    {'Спасите 6 пойманных жителей крепости Стражей Зимы по просьбе главнокомандующего Халфорда Змеевержца из крепости Стражей Зимы в Драконьем Погосте.', },
  },
  [12254] = {
    'Без молитвы – никак',
    {'Эти планы показывают, что грядет нечто неотвратимое.|n|nНо сначала нужно разобраться с той странной защитой, которая есть у сил Алого Натиска. Если Ядозлобь хочет разобраться с ним раз и навсегда, мы должны выяснить, кто стоит за всем этим, и уничтожить его.|n|nЯ заметила, что епископ в часовне на дальней стороне Нового Дольного Очага, что напротив мельницы, дал свое благословение войскам. Убей его и забери его молитвенник.|n|nМожет быть, это даст нам ключ к разгадке.', },
    {'По заданию агента Скулли из Нового Дольного Очага раздобудьте молитвенник епископа Стрита.', },
  },
  [12255] = {
    'Тан Волдруна',
    {'Теперь, когда мы захватили огнепрочные талисманы и ослабили оборону Волдруна, настало время бросить вызов самому предводителю врайкулов, тану Торвальду Эрикксону.|n|nЕго любимое верховое животное – дикий протодракон по кличке Огнедышащий. Его держат закованным в цепи на западе Волдруна, но тебе не составит труда подчинить его себе с помощью талисманов и обратить его против хозяина. |n|nПриручи Огнедышащего и обыщи верхушки всех башен Волдруна. Тан должен скрываться где-то там.', },
    {'Одержите победу над таном Торвальдом Эрикксоном с помощью Огнедышащего и доложите об успехе плотнику Дрейку из Приюта Янтарной Сосны.', },
  },
  [12256] = {
    'Тайны огневязов',
    {'Пока мы пытаемся дать отпор трусливым захватчикам из Альянса, клан Укротителей драконов вербует новую армию в деревне Волдрун, которая находится у побережья на юге. Врайкулы – серьезные противники, и мне хотелось бы уничтожить их прежде, чем они решат выступить против нас.|n|nСамые могущественные воины в этой деревне носят огнепрочные талисманы, которые дают им власть над могущественными протодраконами. Эти талисманы создают прядильщицы пламени из клана Укротителей драконов. Убей их и принеси мне амулеты!', },
    {'Принесите 3 огнепрочных талисмана сержанту Назгриму в Крепость Завоевателей.', },
  },
  [12257] = {
    'Демонстрация силы',
    {'Во врайкульской деревне Волдрун полным ходом идут приготовления к войне. Хотя местный тан не может выставить против нас большую армию, мы все равно не можем чувствовать себя в безопасности.|n|nНельзя дать им возможность напасть, когда мы к этому будем не готовы, поэтому я предлагаю самим сделать первый шаг. Если ты – истинный представитель Орды, ты с радостью ухватишься за возможность продемонстрировать свою силу.|n|nУбей всех хускерлов, которые встретятся тебе на пути. Пусть они дважды подумают, стоит ли связываться с Ордой!', },
    {'Убейте 12 хускерлов из клана Укротителей драконов и вернитесь к сержанту Назгриму в Крепость Завоевателей.', },
  },
  [12258] = {
    'Судьба погибших',
    {'Убейте 15 мстительных упырей по приказу командира Линоры Порыв Ветра в крепости Стражей Зимы в Драконьем Погосте.', },
    {'Убейте 15 мстительных упырей по приказу командира Линоры Порыв Ветра в крепости Стражей Зимы в Драконьем Погосте.', },
  },
  [12259] = {
    'Тан Волдруна',
    {'Теперь, когда мы захватили огнепрочные талисманы и ослабили оборону Волдруна, настало время бросить вызов самому предводителю врайкулов, тану Торвальду Эрикксону.|n|nЕго любимое верховое животное – дикий протодракон по кличке Огнедышащий. Его держат закованным в цепи на западе Волдруна, но тебе не составит труда подчинить его себе с помощью талисманов и обратить его против хозяина. |n|nПриручи Огнедышащего и обыщи верхушки всех башен Волдруна. Тан должен скрываться где-то там.', },
    {'Одержите победу над таном Торвальдом Эрикксоном с помощью Огнедышащего и доложите сержанту Назгриму из Крепости Завоевателей.', },
  },
  [12260] = {
    'Полное несходство',
    {'Ты, должно быть, удивляешься, как мне удается поддерживать эту личину? Я пользуюсь волшебным зеркальцем, которое мне одолжила госпожа шпионов.|n|nСилы в нем не так уж много, но я думаю, что на нас обоих хватит. Вот, возьми. Я хочу, чтобы ты $Gиспользовал:использовала; его, чтобы замаскироваться под одного из жрецов-воронов Алого Натиска.|n|nДавай быстрее... я понятия не имею, сколько продержится маскарад, пока зеркальце у тебя.|n|nПомни, что идеальная маскировка проявится не сразу, так что не особо рассчитывай не нее, пока у меня не появится возможность тебе помочь.', },
    {'По заданию агента Скулли из Нового Дольного Очага похитьте образ жреца-ворона Алого Натиска. После этого верните Волшебное зеркало банши агенту Скалли.', },
  },
  [12261] = {
    'Отрезать пути к отступлению',
    {'Они вытягивают силу из костей моих мертвых собратьев…|n|nУ меня нет никакой симпатии к Культу, но я удивлен их дерзостью. К ним не будет снисхождения… впрочем, я никогда и не был снисходительным.|n|nСделай так, чтобы им некуда было бежать, когда начнется бойня. Установи тотем уничтожения в конце тропы, ведущей из святилища... где дорогу начинает заносить снегом. Защищай его, пока он не зарядится полностью.', },
    {'Поместите тотем уничтожения в конце тропы, ведущей из Обсидианового святилища драконов, там, где дорогу начинает заносить снегом. Защищайте его до полной зарядки, затем вернитесь к Серинару.', },
  },
  [12262] = {
    'Без надежды на спасение',
    {'Мы никого не пощадим.|n|nТам, за нашими стенами, презренные некролиты и их скелеты-прислужники оскверняют мою землю своим присутствием на ней. Убей их всех до единого.', },
    {'Убейте 6 некролитов Пылающих Глубин и 10 тлеющих скелетов за пределами Обсидианового святилища драконов, после этого вернитесь к Серинару.', },
  },
  [12263] = {
    'С наилучшими намерениями',
    {'Культ Проклятых явился сюда не просто для того, чтобы вытягивать энергию из тел мертвых драконов. Думаю, я догадываюсь, что они замыслили, но мне нужно, чтобы ты $Gподтвердил:подтвердила; мою правоту.|n|nЯ придам тебе обличье вот этого мертвого некролита. Доберись до конца пещеры и выясни, зачем они здесь, в этом священном месте. А я буду смотреть твоими глазами.|n|nБудь осторожнее, $N: если тебе нанесут хоть какой-то урон, это разобьет хрупкую иллюзию.', },
    {'Дождитесь, пока Серинар замаскирует вас под некролита Пылающих Глубин, потом проникните в глубь Пасти Нелтариона, чтобы узнать, что там делает Культ Проклятых. Вернитесь к Серинару и расскажите о том, что они замышляют.', },
  },
  [12264] = {
    'Разборка с Проклятыми',
    {'Пещера наверху буквально кишит злодеями Культа. С такими созданиями можно разобраться только одним способом... и ты знаешь, каким.', },
    {'Убейте 3 некромантов Пылающих Глубин, 6 тлеющих созданий и 6 тлеющих упырей в Пасти Нелтариона, а затем возвращайтесь к Серинару.', },
  },
  [12265] = {
    'Осквернение осквернителей',
    {'Я чувствую крупное средоточие магии в рунах, обнаруженных при исследовании пещеры. У нас нет времени на сложные магические ритуалы... порою самое грубое решение является и самым эффективным.|n|nУничтожь руны. Разрушь их и сделай так, чтобы последователи Культа никогда не получили доступа к заключенной в них мощи.', },
    {'Найдите и уничтожьте 8 некромантских рун, выявленных на дне Пасти Нелтариона. Выполнив это, возвращайтесь к Серинару.', },
  },
  [12266] = {
    'Рассказ о разрушении',
    {'Можешь идти, |3-6($R).|n|nИди скажи Нелис, что она пропустила сочный махач.', },
    {'Отправляйтесь обратно в Драконий Покой и расскажите Нэлис, что задание Серинара выполнено.', },
  },
  [12267] = {
    'Пламя Нелтариона',
    {'Теперь, когда ряды сектантов поредели и сил у них поубавилось, самое время нанести удар по источнику заразы.|n|nРотин Гниющий в глубине пещеры воскрешает черных драконов в облике магмазмеев. Проберись в чертог Призыва и очисти оставшиеся кости – единственным способом, который не позволит их больше использовать: пламенем!|n|nКонечно, как только Ротин обнаружит, что кости горят, он тут же явится сам, так что тебе придется уничтожить и его тоже.|n|nЭтот магический сосуд поможет тебе выполнить задачу.', },
    {'Используйте пламя Нелтариона, чтобы очистить область призыва в глубине Пасти Нелтариона. После того как привлечете внимание Ротина Гниющего, убейте его, затем вернитесь к Серинару у входа в пещеру.', },
  },
  [12268] = {
    'Запчасти',
    {'Фу! Ну и мешанина!|n|nНет, гоблинам все-таки далеко до нас в области механики. Вот, ты только посмотри! Удивительно, что эта штуковина вообще работает.|n|nСлушай, может, ты мне слегка пособишь? Чтобы довести это устройство до ума, мне надо будет заменить несколько колесиков, шестеренок и пружин. Найти их не составит труда – они в изобилии валяются вокруг лесопилки.', },
    {'Трубкочист с Лесозаготовок Синего Неба просит вас собрать 4 рифленых шестеренки, 3 зубчатых колеса и 2 тугих пружины.', },
  },
  [12269] = {
    'Только не c нашего рудника!',
    {'Этот проклятый некрополь совершил нападение так неожиданно! Пока мы отражали атаку, мы потеряли рудник Стражей Зимы. Что еще хуже, приспешники Кел\'Тузада подняли убитых горняков как воинов Плети и теперь используют их для поставки их осадных дел мастерам материалов с нашего рудника!|n|nЭту линию поставок надо прервать, а наших павших братьев – упокоить как положено.|n|nОтправляйся на рудник Стражей Зимы, расположенный на Полях Падальщиков, к северо-востоку отсюда, и уничтожь поднятых Плетью горняков. Возвращайся ко мне с их шахтерскими удостоверениями, чтобы я мог зарегистрировать их как погибших.', },
    {'По поручению верховного лорде Леорика фон Цельдига из крепости Стражей Зимы на Драконьем Погосте добудьте 10 удостоверений шахтера Стражей Зимы.', },
  },
  [12270] = {
    'Искрошить Альянс',
    {'Читай по губам, |3-6($C): мне-нужны-крошшеры! Нельзя допустить, чтобы они попали в руки Альянса!|n|nДо сих пор они захватывали крошшеры, чинили их и обращали против наших братьев в Бухте торговцев. Но теперь мы сами воспользуемся их уловкой!|n|nУвидишь бесхозный крошшер – тащи его сюда! Увидишь крошшер в руках жалкого червя из Альянса – убей его и отними крошшер! А мы уже позаботимся о том, чтобы эти малютки работали как надо.|n|nВольно!', },
    {'Грекк с Лесозаготовок Синего Неба просит вас добыть для него 3 крошшера.', },
  },
  [12271] = {
    'Жезл принуждения',
    {'Жезл падает из рук мертвого Лекрафта. По всей длине жезла пульсируют магические руны.|n|nМогло ли быть, чтобы таким способом он выбивал признания?|n|nНужно, чтобы на это взглянул верховный палач.', },
    {'Отнесите жезл истязателя верховному палачу Росу в Ядозлобь.', },
  },
  [12272] = {
    'Кровоточащая руда',
    {'За считанные часы до вторжения сил Наксрамаса один из шахтеров наткнулся на кусок руды, покрытый клейкой жидкостью. В хаосе, возникшем во время эвакуации рудника, мы потеряли образцы, взятые с точки, где были чужаки. А теперь Плеть осматривает всю руду с целью использовать ее в своих машинах смерти.|n|nТебе нужно вернуться на рудник Стражей Зимы – он как раз на северо-востоке отсюда, на Полях Падальщиков – и раздобыть эту странную руду. Это непреложное условие нашего успеха!', },
    {'По поручению осадного инженера Полувспыха из крепости Стражей Зимы на Драконьем Погосте добудьте 10 образцов странной руды на руднике Стражей Зимы.', },
  },
  [12273] = {
    'Отречение',
    {'Пришло время окончательно деморализовать силы Алого Натиска!|n|nЯ хочу, чтобы ты $Gвзял:взяла; жезл и $Gвоздействовал:воздействовала; им на четырех его лидеров. Командир Джордан находится в казарамах наверху, главный канонир Зирхат – на юго-восточном склоне, ведет наблюдение за берегом, кузнец Гудман – в кузнице, а смотритель стойл Мерсер – в конюшнях.|n|nВоздействуй на них жезлом принуждения, сосредоточься на том, чтобы заставить их отречься от Алого Натиска, а затем убей!', },
    {'По заданию верховного палача Роса из Ядозлоби воздействуйте жезлом принуждения на командира Джордана, главного канонира Зирхата, кузнеца Гудмана и смотрителя стойл Мерсера.|n|nКогда они подпадут под влияние жезла, убейте каждого из них, вырвав у них перед смертью признание об отречении от Алого Натиска.', },
  },
  [12274] = {
    'Греховное падение',
    {'Нам нужны сведения, которые можно получить у верховного настоятеля. Теперь, когда у нас есть облик жреца-ворона, думаю, у тебя получится потолковать с ним.|n|nУвы, нужно будет еще как-то разлучить его с его телохранителями, иначе ты от него ничего не добьешься.|n|n<Агент некоторое время размышляет, опершись на лопату.>|n|nВо, придумала! Прими этот облик, поднимись на башню аббатства и позвони в колокол. Телохранители настоятеля бросятся наружу, а ты сможешь спуститься и поговорить с ним.', },
    {'Позвоните в колокол аббатства, затем поговорите с верховным настоятелем по просьбе агента Скулли из Нового Дольного Очага.', },
  },
  [12275] = {
    'Демогном',
    {'Полувспых недавно потребовал у моей группы специалиста, которого можно было бы отправить на разведку на рудник Стражей Зимы. Я отправил к нему Слинкина, своего подрывника. Я-то думал, что он сможет закрыть эту проклятую яму, после того как выполнит поручение Полувспыха, обеспечив нам таким образом еще одну победу над Плетью.|n|nНо вот прошел уже целый день, а Слинкина до сих пор нет! Мне нужен ответ! Поговори с осадным инженером Полувспыхом и отыщи моего пропавшего агента!', },
    {'Поговорите с осадным инженером Полувспыхом в крепости Стражей Зимы в Драконьем Погосте.', },
  },
  [12276] = {
    'В поисках Слинкина',
    {'Я не получал вестей от Слинкина и не знаю, какая судьба его постигла, однако же, возможно, могу помочь его отыскать.|n|n<Полувспых протягивает вам маленькую заводную игрушку.>|n|nЭто тебе не игрушка, наш новый друг. Это мое последнее изобретение! Эта машинка предназначена для того, чтобы отыскивать потерянное. Ситуация, конечно, неблагоприятная, однако эта машинка – твой единственный шанс найти Слинкина.|n|nКогда будешь $Gготов:готова; приступить к поискам, поставь робота на землю рядом со мной.', },
    {'Отыщите Слинкина Демогнома в руднике Стражей Зимы. Используйте самонаводящегося робота Полувспыха, если вам нужна будет помощь в поисках рудника.', },
  },
  [12277] = {
    'Ничего не оставлять на волю случая',
    {'Если в твоем сердце есть добро, и твоя совесть чиста, читай дальше.|n|nВ этом руднике, неподалеку от помоста штейгера, спрятан внушительный запас динамита. Ступай туда, возьми несколько пачек взрывчатки и проберись ко входу в рудник. Оказавшись там, установи взрывчатку и взорви вход. Не забудь проделать это и с верхним, и с нижним входами в рудник Стражей Зимы!|n|nНичего не оставляй на волю случая. Тут обитает зло, нельзя допустить, чтобы оно выбралось наружу! Да хранит тебя Свет.', },
    {'Добудьте бомбу Стражей Зимы и используйте ее, чтобы взорвать верхний и нижний стволы рудника Стражей Зимы. Выполнив задачу, вернитесь к осадному инженеру Полувспыху в крепость Стражей Зимы в Драконьем Погосте.', },
  },
  [12278] = {
    'Клуб "Пиво месяца"',
    {'Думаю, тебе понравится быть членом нашего клуба "Лучший пивовар месяца". Ведь это означает, что у тебя всегда будет самое лучшее и свежее пиво.|n|nЗаполни членскую карточку "Лучшего пивовара месяца" и отнеси ее Ларкину Громовару в таверну "Горючий камень" в Стальгорне.', },
    {'Отнесите членскую карточку "Лучшего пивовара месяца" Ларкину Громовару в таверну "Горючий камень" в Стальгорне.', },
  },
  [12279] = {
    'Медвежий аппетит',
    {'Наконец-то ты вернулся, Лимпи! Я уж боялся, что мы с Гризельдой останемся одни.|n|nЯ тут приготовил нам обед, но Гризельде вряд ли понравится моя стряпня.|n|nОна предпочитает рыбку, которая водится вдоль Побережья Восточного Ветра на востоке. Да я этих рыб сам на дух не переношу, но она у нас настоящий гурман. Поймай ей шесть больших рыбин – и она будет счастлива.|n|nНу давай, беги же! Не стоит заставлять нашу девочку ждать!', },
    {'Принесите 6 северных лососей Хью Глассу в Торговую лавку Красного леса.', },
  },
  [12280] = {
    'Текущий ремонт',
    {'Двадцать крошшеров к завтрашнему утру!|n|nЧто за светлая голова составляет эти графики? Могу поспорить, он даже близко не подходил к этим консервным банкам... |n|nМда... если я хочу уложиться в график, мне понадобится помощь. Если протянешь мне руку – отсыплю тебе кое-что из моей доли! $GСогласен:Согласна;?|n|nМне нужны колеса, шестеренки и пружины – они тут валяются повсюду.', },
    {'Лурц с Лесозаготовок Синего Неба просит вас собрать 4 рифленых шестеренки, 3 зубчатых колеса и две тугих пружины.', },
  },
  [12281] = {
    'Понимание военной машины Плети',
    {'Мы должны утешаться тем фактом, что смерть Слинкина, хотя и трагическая, послужила высшему благу. Его открытие, вкупе с твоими героическими деяниями в шахте и образцами, которые ты $Gвернул:вернула;, делает нас на шаг ближе к пониманию военной машины Плети.|n|nДоставь этот пакет главнокомандующему Халфорду Змеевержцу. В нем – образец этой странной руды и результаты моих исследований.', },
    {'Доставьте амуницию Полувспыха главнокомандующему Халфорду Змеевержцу в крепость Стражей Зимы.', },
  },
  [12282] = {
    'Отпечатки былого',
    {'Эта земля наполнена воспоминаниями о былом, $N. По всему Нордсколу отдаются немым эхом взывающие ко мне голоса.|n|nНа всем, чего коснулся Артас, он оставил жуткие отпечатки. Там, где он прошел, остаются лишь смерть и увядание. Вот почему так важно тщательно изучать историю, чтобы знать врага в лицо. Быть может, рано или поздно из глубины веков всплывут забытые истины, которые пригодятся нам в настоящем.|n|nДля начала, $N, добудь из ратуши мой гадальный шар. Выйдя из башни, ступай налево, и выйдешь на городскую площадь.', },
    {'Принесите Зелигу Иллюзорному из крепости Стражей Зимы в Драконьем Погосте его гадальный шар.', },
  },
  [12283] = {
    'Правду не скроешь',
    {'Нужно выяснить, что здесь происходит. Нам нужен дневник генерала!|n|nЯ почти уверена, что ты найдешь дневник на ее ночном столике на втором этаже ее дома. Этот дом находится рядом с церковью, напротив стойл и лесопилки.|n|nКак добудешь дневник, отнеси его в Ядозлобь, верховному палачу.|n|nДелать это придется по старинке: сила зеркала иссякла, мне самой едва хватит!|n|n<Агент ухмыляется.>', },
    {'Добудьте дневник верховного генерала Аббендис по просьбе агента Скулли и передайте этот дневник верховному палачу Росу в Ядозлоби.', },
  },
  [12284] = {
    'Преследуй по пятам',
    {'Мы понесли серьезные потери, |3-6($R).|n|nТолько одно утешает меня – наши враги пострадали не меньше. Я запросил подкрепление, но большая часть наших отрядов застряла в Бухте торговцев. Похоже, пока что нам придется рассчитывать только на себя.|n|nКак бы тяжело нам не приходилось, мы должны сражаться до конца! Эти земли богаты ресурсами, необходимыми Орде для операций в Нордсколе.|n|nМы должны сдерживать наступление Альянса, пока не прибудет помощь. Иди же и заставь их войска повернуть назад.', },
    {'Командир Баргок приказал вам убить 15 представителей или игроков Альянса на Лесозаготовках Синего Неба.', },
  },
  [12285] = {
    'Без головы не возвращайся!',
    {'Их нападение неизбежно, |3-6($C). Мне нужно, чтобы ты $Gпробрался:пробралась; туда и $Gлишил:лишила; Алый Натиск его главы. Я имею в виду в буквальном смысле!|n|nЭто будет нелегко... Аббендис, безусловно, будет окружена множеством своих людей. Предлагаю тебе взять с собой хотя бы пару друзей.|n|nПринеси мне ее голову, и я позабочусь о том, чтобы тебя достойно вознаградили за спасение Ядозлоби.|n|nПровалишь задание – не смей возвращаться!', },
    {'По заданию верховного палача Роса из Ядозлоби убейте верховного генерала Аббендис и принесите ему ее голову.', },
  },
  [12286] = {
    'Кулек конфет',
    nil,
    nil,
  },
  [12287] = {
    'Орик Чистосердечный и Забытое взморье',
    {'Я смотрел на сферу и видел путь, которым тебе должно пройти, $N.|n|nМного лет назад ужасное злодеяние было совершено на берегах Драконьего Погоста. Что тебе надлежит сделать – то покрыто тьмой, но я уверен, что твоя судьба – на юге, среди руин Забытого взморья.|n|nОтправляйся по дороге на юго-восток через разоренную городскую площадь. Следуй этим путем, пока не доберешься до Рассветного края. Там встретишь моего старого друга по имени Орик Чистосердечный. Он будет ждать тебя.', },
    {'Ищите помощи у Орика Чистосердечного в Рассветном краю на Драконьем Погосте.', },
  },
  [12288] = {
    'В военном лазарете',
    {'Эй, |3-6($C)! Пожалуйста, помоги нам!|n|nМы понесли тяжелые потери. Столько раненых... одной мне никогда не исцелить всех их. А если наши солдаты не встанут на ноги, нам придется сдавать позиции и уходить из Седых холмов!|n|nВот, возьми этот бинт и приступай к перевязке раненых на поле боя.|n|nПоторопись, $N, иначе они умрут!!!', },
    {'Аумана с Лесозаготовок Синего Неба просит вас перевязать медицинским жгутом 10 израненных рыскателей.', },
  },
  [12289] = {
    'Лежачего не бьют – лежачего пинают',
    {'Сегодня был черный день для Альянса. Много хороших парней полегли на поле битвы. Остается только утешать себя тем, что они храбро сражались и забрали с собой жизни многих врагов.|n|nТеперь, когда большую часть наших сил переправили в Бухту торговцев, мы остались одни перед лицом грядущей опасности. Мы должны защитить стратегически важные регионы, в которых добываются ресурсы, необходимые для победы над Ордой. Мы не можем подвести Альянс!|n|nИди же, $N. Не дай нашим врагам зализать раны и собраться с силами. Отомсти за павших братьев и подари нам надежду на победу!', },
    {'Сержант Хартсман поручил вам убить 15 игроков или представителей Орды на Лесозаготовках Синего Неба.', },
  },
  [12290] = {
    'Эликсир из темноплевела',
    {'На побережье бродят духи проклятых. В жизни то были отважные и благородные воины Альянса, но в смерти их настигло проклятие – они прикованы к этому миру до конца времен. Чтобы их освободить, нужно узнать, что их так терзает!|n|nК юго-востоку отсюда, на зловещей Возвышенности, растет редкая травка, именуемая темноплевелом. Из этого темноплевела я могу приготовить эликсир, который позволит тебе на время войти в мир забытых душ. Ступай, набери этой травы.', },
    {'Добудьте на Зловещей возвышенности 5 экземпляров темноплевела по просьбе Орика Чистосердечного из Рассветного края в Драконьем Погосте.', },
  },
  [12291] = {
    'Забытая повесть',
    {'Яды, содержащиеся в эликсире из темноплевела, заставят тебя потерять сознание. Темноплевел оказывает столь мощное воздействие, что даже твой дух будет обманут. Это позволит тебе на время вступить в мир мертвых.|n|nСделавшись духом, поговори с призрачными обитателями Забытого взморья. Узнай, отчего они так страдают, и возвращайся ко мне.|n|nПомни, $N: некогда эти духи были солдатами Альянса! Держись с ними почтительно, как то подобает их достоинству!|n|nНу, вот тебе эликсир, ступай на юг, на Забытое взморье.', },
    {'Выслушайте повесть о бедствиях забытого крестьянина, забытого ружейника, забытого рыцаря и забытого пехотинца по просьбе Орика Чистосердечного из Рассветного края в Драконьем Погосте.', },
  },
  [12292] = {
    'Помощь местных жителей',
    {'Наше противостояние с Ордой в Седых холмах зашло в тупик. До сегодняшнего дня силы были равны, и я не видел выхода из этой ситуации.|n|nНо сегодня к нам за помощью обратилась группа местных звероловов. Похоже, ордынцы ограбили их и отобрали что-то важное... какую-то реликвию. |n|nОни пообещали нам свою поддержку взамен за возвращение этой штуковины. Так что я поручаю тебе сходить в Торговую лавку Вечнозеленого леса, что к западу от Крепости Завоевателей, и забрать оттуда кедровый сундук.', },
    {'Лейтенант Думонт из Приюта Янтарной Сосны поручил вам добраться до Торговой лавки Вечнозеленого леса и забрать кедровый сундук.', },
  },
  [12293] = {
    'Дело сделано',
    {'Теперь у нас есть то, что нужно звероловам. Осталось только подписать с ними договор о сотрудничестве! |n|nОтнеси ящик зверолову по имени Иван на Заставу Тополиной рощи, что к северу отсюда.|n|nЕсли наши предположения верны, местные звероловы с радостью присоединятся к королевской армии.', },
    {'Отнесите кедровый сундук Ивану на Заставу Тополиной рощи.', },
  },
  [12294] = {
    'Заключение договора',
    {'Рад слышать, что твои люди выполнили свою часть сделки. |n|nСкажи Думонту, что мы тоже сдержим слово.', },
    {'Вернитесь к лейтенанту Думонту в Приют Янтарной Сосны.', },
  },
  [12295] = {
    'Урок дипломатии',
    {'Мы уже давно пытались договориться со звероловами, но они отказывались идти нам навстречу. Однако теперь, когда у нас есть их дурацкий ящик, дело должно сдвинуться с мертвой точки.|n|nХорошие новости для наших послов в Среброречье! Неделю назад мы отправили туда Дюкаля, и ему даже удалось добиться некоторого прогресса, судя по его последнему донесению.|n|nСтупай в Среброречье и помоги ему заключить договор. Город находится прямо по дороге на северо-запад.', },
    {'Поговорите с военным атташе Дюкалем в Среброречье.', },
  },
  [12296] = {
    'На грани жизни и смерти',
    {'Какая страшная битва...|n|nЯ побывала во многих сражениях, |3-6($C), но эта резня была самой жестокой из всех. Наши стычки с Ордой стали еще более ожесточенными. Идет война за право оставаться здесь, в Нордсколе – война не на жизнь, а на смерть.|n|nЕсли мы хотим продержаться здесь еще хотя бы день, нам надо перевязать раненых. Их здесь слишком много... мне не справиться одной.|n|nВот, я подготовила специальные бинты. Возьми их, если хочешь помочь мне исцелить наших бойцов.', },
    {'Реанна с Лесозаготовок Синего Неба просит вас перевязать медицинскими бинтами 10 израненных пехотинцев отряда Западного Края.', },
  },
  [12297] = {
    'О предателях и предательстве',
    {'Этот список необходимо доставить главнокомандующему Халфорду Змеевержцу. Он командует седьмым легионом, расположенным в Крепости Стражей Зимы на восточной границе Драконьего Погоста.|n|nЕсли кто-нибудь из предателей, упомянутых в этом списке, умудрился втереться к нему в доверие... последствия могут быть необратимыми.|n|nТоропись, $N. Покажи этот документ Гриру Рудомолоту в Крепости Западной Стражи и объясни всю важность твоего поручения. Тогда он посадит тебя на самого быстрого грифона, знающего путь в Крепость Стражей Зимы!', },
    {'Капитан Адамс попросил вас показать депешу Альянса Гриру Рудомолоту из Крепости Западной Стражи.', },
  },
  [12298] = {
    'Главнокомандующий Халфорд Змеевержец',
    {'Отвезите депешу Альянса главнокомандующему Халфорду Змеевержцу в Крепость Стражей Зимы, которая находится на востоке Драконьего Погоста.', },
    {'Отвезите депешу Альянса главнокомандующему Халфорду Змеевержцу в Крепость Стражей Зимы, которая находится на востоке Драконьего Погоста.', },
  },
  [12299] = {
    'Северное гостеприимство',
    {'Рад познакомиться с тобой, $N. Давай скрепим наш союз кровью ордынцев?|n|nПочему бы тебе не поохотиться на мародеров из Крепости Завоевателей, которые бродят вокруг нашего города, к западу отсюда? Эти мерзкие животные не заслуживают пощады.|n|nВ конце концов, было бы неплохо узнать, на что способны наши новые союзники.', },
    {'Сергей из Среброречья просит вас убить 8 мародеров из Крепости Завоевателей.', },
  },
  [12300] = {
    'Испытание смелости',
    {'Ладно, дружок. Пару раз ты нас действительно $Gвыручил:выручила;, но это еще не показатель смелости. |n|nВ наших краях нельзя стать настоящим охотником, не почувствовав себя в шкуре жертвы.|n|n<Сергей вытаскивает из ножен свой охотничий нож и протягивает его вам.>|n|nПредводителя проклятых орков, нападающих на наш город, зовут Костехват. Его легко найти в лагере на северо-западе.|n|nДа, ты меня правильно $Gпонял:поняла;: я поручаю тебе освежевать этого мерзавца.', },
    {'Найдите часового Костехвата к северо-западу от Среброречья и пройдите испытание смелости.', },
  },
  [12301] = {
    'Правда вернет нам свободу',
    {'Зелиг дал мне эту хрустальную сферу много лет назад, особо проинструктировав касательно ее использования. В течение пяти лет – чувствовал ли я гнев, беспокойство или печаль из-за событий, происходивших здесь – я должен был сосредотачивать свои мысли на этой сфере.|n|nТеперь я понимаю, почему Зелиг отдал этот кристалл мне.|n|nОтнеси мою хрустальную сферу на Забытое взморье. Найди развалины моей старой базы в верхней части побережья и помести сферу в центре поселения. Пусть обитающие там увидят мир через призму моего сердца и моей души.', },
    {'По просьбе Орика Чистосердечного из Рассветного края, что на Драконьем Погосте, задействуйте хрустальную сферу Орика в развалинах, расположенных на Забытом взморье, для освобождения обитающих там Забытых.', },
  },
  [12302] = {
    'Предупреждение',
    {'Спасибо за помощь, $N. Меня зовут Саша. Послушай, мне очень надо выбраться отсюда.|n|nЛюди, которые послали тебя сюда... мои товарищи... с ними что-то произошло. Они изменились... Они хотят... сделать тебя $Gодним:одной; из них.|n|nЭто испытание – всего лишь начало...|n|nДойди до северо-запада Среброречья, и ты увидишь все собственными глазами.|n|nУдачи... и помни – никому нельзя доверять!', },
    {'Дойдите до северо-западного края Среброречья.', },
  },
  [12303] = {
    'Финансовое обеспечение военных нужд',
    {'<Интендант понижает голос и шепчет.>|n|n$C, мне нужна твоя помощь; наша казна пуста! Отряд Кор\'крона у Врат Гнева забрал все деньги на тамошние сражения.|n|nОднако до меня дошли слухи, что в местах кораблекрушений на Забытом взморье к юго-востоку отсюда можно найти затонувшие сокровища.|n|nНам непременно нужно что-то срочно предпринять, или мы не сможем продолжать войну с Алым Натиском. Война, знаешь ли, обходится недешево!', },
    {'По заданию интенданта Бартлетта из Ядозлоби добудьте 6 сундучков с забытыми сокровищами.', },
  },
  [12304] = {
    'Недвижимость на взморье',
    {'Ядозлоби пора расширить свое влияние!|n|nВ свое время мы разберемся с Алым Натиском, ну, а пока я хочу, чтобы ты $Gотправился:отправилась; в место, называемое Забытым взморьем. У тех мест – огромный потенциал, а $Gвидел:видела; бы ты, какой там ландшафт!..|n|nК сожалению, там полным-полно людских призраков, членов экипажей затонувших кораблей и прочих, еще не осознавших, что они уже умерли.|n|nРасчисти берег и прибрежные воды – и, быть может, мы с тобой вскоре уже сможем говорить о постройке там новой, миленькой, уютной усыпальницы.', },
    {'По поручению наблюдателя Хансена, находящегося к северу от Забытого взморья убейте 20 призраков Забытого взморья.', },
  },
  [12305] = {
    'Прощальные мысли',
    {'Ты $Gоказал:оказала; честь и мне, и памяти сотен ветеранов Альянса, $N. Зелиг поступил мудро, прислав тебя сюда. Пожалуйста, вернись к нему и передай ему мою благодарность. Он будет рад услышать о том, что произошло на Забытом взморье.|n|nЯ, в отличие от Зелига, не наделен пророческим даром, но уверен, что тебя, друг, ждет великая судьба.|n|nПрощай!', },
    {'Вернитесь к Зелигу Иллюзорному в крепость Стражей Зимы в Драконьем Погосте.', },
  },
  [12306] = {
    'Клуб "Пиво месяца"',
    {'Чем нас больше – тем лучше, $N. Вступив в клуб "Лучший пивовар месяца", ты сможешь дегустировать самые выдающиеся сорта пива.|n|nЗаполни членскую карточку "Лучшего пивовара месяца" и отнеси ее Рай\'ме в Пристанище Темнотерна. Оно находится в Оргриммаре, в Аллее Духов.', },
    {'Отнесите заполненную членскую карточку "Лучшего пивовара месяца" Рай\'ме в Пристанище Темнотерна. Оно находится в Оргриммаре, в Аллее Духов.', },
  },
  [12307] = {
    'Аконитовый корень',
    {'$GСлышал:Слышала; когда-нибудь про волчий борец? Мерзкая трава... из-за нее гибнет половина наших посевов.|n|nМы пололи сорняки всю прошлую неделю, но оставшиеся корни опять дали всходы!|n|nДумаешь, это все чепуха? Учти: если волчий борец опять заколосится, произойдет... нечто ужасное! Так что если увидишь этот сорняк возле деревни – выдерни его немедленно, и ты окажешь нам очень большую услугу!', },
    {'Катя из Среброречья просит вас выдернуть восемь аконитовых кореньев.', },
  },
  [12308] = {
    'Побег из Среброречья',
    {'Ты… ты не $Gодин:одна; из них? Быстрее! Освободи меня!|n|nНам нужно немедленно отправляться в Приют Янтарной Сосны! Как только лейтенант Думонт узнает, кто эти люди на самом деле, он камня на камне не оставит от этого города!', },
    {'Откройте деревянную клетку и помогите освобожденному разведчику Альянса сбежать из Среброречья. Доложитесь лейтенанту Думонту по прибытии в Приют Янтарной Сосны.', },
  },
  [12309] = {
    'Найти Дюркона!',
    {'Отыщите кавалериста Дюркона в склепе Стражей Зимы в Драконьем Погосте.', },
    {'Отыщите кавалериста Дюркона в склепе Стражей Зимы в Драконьем Погосте.', },
  },
  [12310] = {
    'Мгновенный ответ',
    {'Наша реакция должна быть незамедлительной. Сокрушительной. Мы должны проучить этих мерзавцев раз и навсегда.|n|nНаши разведчики засекли местонахождение выживших звероловов Среброречья... тех, кому удалось спастись от пожара. Сейчас они прячутся вдоль юго-восточной дороги... видимо, пытаются заманить нас в ловушку.|n|nОтправляйся на Заставу на опушке и разберись с ними. Судя по донесениям, их предводителя зовут Владек... сделай так, чтобы я больше ничего о нем не слышал.', },
    {'Лейтенант Думонт отправил вас к Заставе на опушке убить Владека и 7 охотников Среброречья.', },
  },
  [12311] = {
    'Подземная обитель некролорда',
    {'Упрятанные за холодные каменные стены этого склепа покоятся останки благородных и знаменитых личностей, нашедших свою смерть в Нордсколе. В самой глубине усыпальницы обитает некролорд, поднимающий тела умерших в качестве слуг Плети.|n|nТебе нужно прорваться вглубь склепа Стражей Зимы и убить некролорда Амариона. Только так можно остановить зло, идущее изнутри!|n|nИ еще, $N: внимательно осмотри помещение, где найдешь Амариона – там может храниться важная информация.', },
    {'По заданию кавалериста Дюркона из крепости Стражей Зимы убейте некролорда Амариона.', },
  },
  [12312] = {
    'Тайны Плети',
    {'Вся эта обтянутая плотью книга испещрена коряво нацарапанными, будто вырезанными клинком, странными символами и изображениями. Вы и понятия не имеете, что здесь написано, но совершенно уверены, что это очень важно.|n|nОтнесите том кавалеристу Дюркону, стоящему на страже наверху склепа Стражей Зимы.', },
    {'Отнесите сшитый плотью фолиант кавалеристу Дюркону, находящемуся в крепости Стражей Зимы на Драконьем Погосте.', },
  },
  [12313] = {
    nil,
    {'Поговорите со шпионом Хмельного фестиваля в "Угрюмом обжоре" , что в Глубинах Черной горы.', },
    {'Поговорите со шпионом Хмельного фестиваля в "Угрюмом обжоре" , что в Глубинах Черной горы.', },
  },
  [12314] = {
    'Смерть капитану Зорне!',
    {'Если мы будем бездействовать, силы Орды прорвут нашу оборону и окончательно захватят Бухту торговцев. Командует ими капитан Зорна, которая неотлучно находится на своем корабле, пришвартованном в дальнем конце бухты.|n|nЕсли тебе удастся ее победить, обороноспособность Орды значительно понизится, и мы постараемся воспользоваться этим шансом, чтобы отвоевать порт. Только учти, $N: Зорна – превосходный боец. В одиночку тебе с ней не справиться. Захвати с собой подмогу – или воспользуйся работающим крошшером, если такой у тебя имеется.', },
    {'Убейте капитана Зорну и вернитесь к барону Фриману в Бухту торговцев.', },
  },
  [12315] = {
    'Смерть капитану Брайтвотеру!',
    {'Наши солдаты постоянно сталкиваются с отрядами подкрепления Альянса. Такое ощущение, будто их предводитель предугадывает каждый наш шаг!|n|nНастало время покончить с капитаном Брайтвотером. Он командует войсками с борта флагмана Альянса, пришвартованного на дальнем конце бухты.|n|nПобедить его будет нелегко, $N. Возьми с собой несколько проверенных друзей – или хотя бы воспользуйся ключом от одного из отремонтированных крошшеров. Мне все равно, каким образом умрет Брайтвотер – но я больше не хочу слышать его имя в списках живых!', },
    {'Убейте капитана Брайтвотера и доложите о своей победе генералу Хазгару из Бухты торговцев.', },
  },
  [12316] = {
    'Припрем их к стенке!',
    {'Нельзя допустить, чтобы Орда захватила Бухту торговцев! Этот порт чрезвычайно важен для наших операций в Седых холмах и за их пределами.|n|nКапитан Камнегрив забрал оставшихся дружинников из бригады Западного Края на поиски прохода в горах, так что на его помощь рассчитывать не приходится. |n|nОтправляйся на поле битвы, $N, и убей берсерков из Крепости Завоевателей. Орда послала их сражаться с нами, но мы не оставим им ни единого шанса вытеснить нас из Бухты!', },
    {'Убейте 10 представителей или игроков Орды в Бухте торговцев, после чего вернитесь к лейтенанту Стюарту.', },
  },
  [12317] = {
    'Припрем их к стенке',
    {'Проклятые солдаты из дружины Западного Края оказались более стойкими, чем мы предполагали. Они сражаются до последней капли крови, храбро и безрассудно, а у нас нет времени ждать, когда их силы иссякнут. |n|nЗавоевательница Кренна приказала как можно быстрее захватить этот порт, поэтому ты, $N, сделаешь все, чтобы переломить ситуацию в нашу пользу. Убивай наших врагов, сломи их моральный дух. Только тогда мы сможем водрузить наш флаг над Бухтой торговцев.|n|nИди же – Завоевательница Кренна не любит ждать.', },
    {'Убейте 10 представителей или игроков Альянса в Бухте торговцев, после чего вернитесь к центуриону Каггруму.', },
  },
  [12318] = {
    'Спасем Хмельной фестиваль!',
    {'Поговорите со шпионом Хмельного фестиваля в таверне "Угрюмый обжора" в Глубинах Черной горы.', },
    {'Поговорите со шпионом Хмельного фестиваля в таверне "Угрюмый обжора" в Глубинах Черной горы.', },
  },
  [12319] = {
    'Тайна книги',
    {'Что же это может быть, $N? Проклятый лич явно наложил на тебя не просто обычное проклятие!|n|n<Дюркон листает зловещие страницы.>|n|nЯ даже не знаю, правильно ли я держу эту книгу. Однако необходимо выяснить, какие важные сведения в ней содержатся!|n|n<Дюркон возвращает вам книгу.>|n|nГлавнокомандующий должен знать, что делать. Отнеси сшитый плотью фолиант к нему и расскажи ему о том, что произошло.', },
    {'Отнесите сшитый плотью фолиант главнокомандующему Халфорду Змеевержцу в крепость Стражей Зимы в Драконьем Погосте.', },
  },
  [12320] = {
    'Язык Смерти',
    {'Возьми эту книгу и иди по дороге, ведущей к казармам. Как войдешь в казармы, спустись по лестнице, ведущей в тюрьму. В тюрьме ты найдешь инквизитора Халларда и нашего мэра, Годфри. Полагаю, именно Годфри и окажется недостающей деталью головоломки, и именно Халлард – тот человек, который сумеет ее собрать.|n|nСтупай!', },
    {'Отнесите сшитый плотью фолиант инквизитору Халларду в тюрьме крепости Стражей Зимы.', },
  },
  [12321] = {
    'Праведная проповедь',
    {'Годфри Хорошер, некогда человек праведный и мэр Стражей Зимы, теперь принадлежит Плети. Его трансформация из человека в неумирающего вурдалака шла медленно и в течение длительного времени. Теперь он слышит зов Короля-лича и живет только для того, чтобы служить своему господину.|n|nНо, как и любой представитель Плети, Годфри знает язык смерти и, если его правильно мотивировать, расскажет об этом фолианте то, что нам нужно.|n|nКогда услышишь то, что надлежит услышать, возвращайся к главнокомандующему на линию фронта. А я здесь приберу, по необходимости.', },
    {'Дождитесь, пока инквизитор Халлард закончит свою праведную проповедь, и возвращайтесь к главнокомандующему Халфорду Змеевержцу в крепость Стражей Зимы на Драконьем Погосте с добытой информацией.', },
  },
  [12323] = {
    'Выкурим их!',
    {'В некоторых зданиях в центе Бухты торговцев все еще прячутся мелкие банды трусливых работников Торговой Компании. Я не могу позволить этим крысам прятаться в щелях, пока мои солдаты сражаются с Ордой. |n|nМожет быть, тебе удастся "убедить" их убраться отсюда подобру-поздорову? Вот, возьми дымовую шашку и выкури этих бродяг из бараков, лесопилки и конюшни. Только не связывайся с ними – они кусаются.', },
    {'С помощью дымовой шашки выкурите 20 отставших работников Торговой Компании из зданий. Доложите об успешном выполнении поручения сержанту Дауни.', },
  },
  [12324] = {
    'Выкурим их!',
    {'Мало того, что в нашем порту шныряют трусливые лазутчики Альянса – так еще и мерзкие работники Торговой Компании окопались в самом центре Бухты! Но я не собираюсь посылать за ними солдат – много чести для этих паршивцев. |n|nМожет быть, тебе удастся "убедить" их убраться отсюда подобру-поздорову? Вот, возьми дымовую шашку и выкури этих бродяг из бараков, лесопилки и конюшни. Только не связывайся с ними – вдруг они заразные?', },
    {'С помощью дымовой шашки выкурите 20 отставших работников Торговой Компании из зданий. Доложите об успешном выполнении поручения Каменному стражу Тотему Ярости.', },
  },
  [12325] = {
    'Заброс на вражескую территорию',
    {'Поговорите с командиром грифонов Уриком, чтобы организовать полет на заставу Торсона на Драконьем Погосте. Когда прибудете на заставу, доложитесь герцогу Августу Крушителю Врагов.', },
    {'Поговорите с командиром грифонов Уриком, чтобы организовать полет на заставу Торсона на Драконьем Погосте. Когда прибудете на заставу, доложитесь герцогу Августу Крушителю Врагов.', },
  },
  [12326] = {
    'Паровой сюрприз',
    {'Это задание типа "найти и уничтожить". Поведешь танк на Поля Падальщиков с целью разрушить чумные телеги Плети. Танку придан экипаж, состоящий из бойцов Седьмого легиона. Миссия будет признана выполненной, только если все они останутся в живых!|n|nТебе нужно будет приблизиться к чумной телеге и выпустить инженеров. Пусть они делают свое дело, а потом двигайтесь к следующей телеге. Когда поле будет очищено от чумных телег, направляйся к усыпальнице, расположенной перед разрушенной крепостью и высади там экипаж. Встретишься там внутри с Амбо Кэшем.', },
    {'Воспользовавшись паровым танком Альянса, уничтожьте 6 чумных телег и доставьте гвардейцев 7-го легиона к усыпальнице Стражей Зимы. Если успешно выполните задание, поговорите с Амбо Кэшем внутри усыпальницы Стражей Зимы на Драконьем Погосте.', },
  },
  [12327] = {
    'Опыт вне тела',
    {'А, ты ищешь знаний о прошлом. Это признак мудрости, |3-6($R).|n|nОбычно меня просят предсказать будущее, но дожившие до моих седин понимают, что мудрость прошлого гораздо более полезна, нежели туманные видения грядущего. |n|nВыпей это снадобье и загляни в мой хрустальный шар. Посмотрим, что откроется тебе в его глубинах.', },
    {'Выпейте зелье из легчайшей пыльцы возле хрустального шара Рууны и узрите видение из прошлого.', },
  },
  [12328] = {
    'Просьба Рууны',
    {'Я не возьму с тебя деньги за мои услуги, ибо чувствую, что ты действуешь во имя общего блага, и многое будет зависеть от того, что ты сегодня узнаешь.|n|nНо я попрошу тебя принести один важный компонент для зелья – легчайшую пыльцу папоротниковых мотыльков, которые водятся на северо-востоке отсюда. Принеси пыльцу, и я помогу тебе перенестись в то время и место, где произошли интересующие тебя события.', },
    {'Рууна Слепая просит вас принести ей четыре горсти легчайшей пыльцы.', },
  },
  [12329] = {
    'Судьба и совпадения',
    {'В этом мире есть два типа людей, $N: одни верят в совпадения, а другие – нет.|n|nПотеряв зрение, я обрела дар ясновидения. Полагаю, теперь ты можешь догадаться, к какому типу я принадлежу.|n|nСегодня утром у одной девушки по имени Саша было такое же видение, как у тебя. Думаю, ты захочешь с ней поговорить.|n|nТы найдешь ее на востоке, в Торговой лавке Белой Сосны, что по пути в Деревню Солнцестояния.', },
    {'Поговорите с Сашей в Торговой лавке Белой Сосны.', },
  },
  [12330] = {
    'Слабое место Анатолия',
    {'Моя сестра где-то неподалеку, а этот мерзавец не хочет признаваться, где они ее прячут.|n|nКажется, собственная судьба ему безразлична, но у меня есть кое-какие планы. Когда-то я была знакома с женой Анатолия, Татьяной – она работала на конюшне.|n|nВозьми этот дротик с транквилизатором, оглуши женщину и притащи сюда. Только не убивай ее – она нам понадобится, чтобы разговорить Анатолия.|n|nОбещаю, как только мы найдем мою сестру, я помогу тебе расправиться с человеком, который стоит за всем этим.', },
    {'Саша из Торговой лавки Белой Сосны просит вас выстрелить усыпляющим дротиком в Татьяну, жительницу Деревни Солнцестояния. Принесите ее в Торговую лавку Белой Сосны.', },
  },
