  [13034] = {
    'Наблюдатель и герой',
    {'Еще в самом начале своего путешествия в Нордскол я посетил Борейскую тундру и там впервые в жизни увидел таунка. Укротитель ветра Бара рассказал мне о Штормовом Копыте и его битве против Северного Ветра, древнего врага его народа.|n|nЯ отправился к Грозовой гряде, чтобы побольше узнать об этом герое, но вот что странно... в Тунка\'ло о нем даже не слышали.|n|nВозможно, какая-то информация есть в исторических документах в этом лагере? Разыщи и прочти свитки, что хранятся в лагере – а потом перескажи мне все, что удастся узнать.', },
    {'По просьбе Ксанатавра из лагеря Тунка\'ло прочитайте Первый, Второй и Третий свитки.', },
  },
  [13035] = {
    'Прислужники Локена',
    {'Мой брат отправил на штурм Террасы Творцов отборные войска: легион железных дворфов и своих лучших командиров.|n|nВоспользуйся рогом Вершин, чтобы призвать земельников себе на помощь и победить прислужников Локена.|n|nВеликана Айзенфауста ты найдешь на севере, в Зале Творца. Остальные засели в глубине Террасы Творцов, за лестницей, ведущей на северо-запад.', },
    {'Убейте Айзенфауста в Зале Творца, а также Халефнира Дитя Ветра и Даррона Рунокова на Террасе Творцов по просьбе Торима.', },
  },
  [13036] = {
    'Великая миссия',
    {'Наш путь к спасению был долог и труден, |3-6($C). Для того чтобы добраться сюда, нам пришлось много сражаться – на всех континентах, во всех мирах! И теперь нам предстоит выполнить самую главную миссию: победить Короля-лича и Плеть.|n|nНо, увы, мы одиноки в своей борьбе. Орда и Альянс нам не помогут – у них своя собственная война. Однако мы не должны падать духом! Мы будем сражаться до конца! А иначе зачем вообще сражаться?|n|nТы будешь нашим союзником? Твоя отвага и сила могут нам пригодиться, |3-6($C)! Мой командир, Энтари, ждет тебя у себя на заставе.', },
    {'Поговорите с командиром рыцарей Энтари в Оплоте Серебряного Авангарда в Ледяной Короне.', },
  },
  [13037] = {
    'Воспоминания о Штормовом Копыте',
    {'Когда бронзовые драконы подарили мне бессмертие и наставили на путь наблюдателя, Ноздорму вручил мне Молот Знаний.|n|nОтклик молота на твои находки означает, что время здесь искажено, и наш долг – восстановить подлинную линию времени.|n|nА для этого нам надо ее найти. Отправляйся на северо-запад, в Ледяные глубины, где находится древнее захоронение воинов Тунка\'ло. Разыщи дух вождя Быстрое Копье, брата Штормового Копыта. Попроси его вспомнить о битве его брата с Северным Ветром.', },
    {'Поговорите с вождем Быстрое Копье в Ледяных Глубинах и возвращайтесь к Ксанатавру в лагерь Тунка\'ло.', },
  },
  [13038] = {
    'Искажения времени',
    {'Эта гробница, захоронение воинов Тунка\'ло, всегда считалась священным местом, свободным от террора стихий.|n|nОднако некая странная сила проникла в Ледяные Глубины – сила, которая нарушает покой духов павших и как будто стирает мне память.|n|nКак будто кто-то пытается переиначить историю и убрать из нее наши деяния и воспоминания.|n|nПри жизни этот тотем служил символом моей власти. Сейчас это последнее связующее звено между мною и этим миром. Возьми его и сделай так, чтобы духи павших упокоились с миром, а потом верни его в лагерь Тунка\'ло.', },
    {'Закройте 4 расселины в Ледяных глубинах с помощью тотема вождя, а затем отправляйтесь в лагерь Тунка\'ло и отдайте тотем Ксанатавру.', },
  },
  [13039] = {
    'Оборона аванпоста',
    {'Мы уже не справляемся, $Gдруг:милая леди;. Когда они пробили брешь, шлюзы открылись. Плеть валит сюда бесконечным потоком.|n|nНам не хватает людей. И мы рады любому, кто способен сражаться и согласен помочь нам сдержать поток зла. Вставай в строй, $Gдружище:воительница;, и убивай этих чудовищ. Чем больше, тем лучше!', },
    {'Убейте 15 нерубов Забытых глубин по просьбе лорда Далфорса из Оплота Серебряного Авангарда в Ледяной Короне.', },
  },
  [13040] = {
    'Исцеление неисцелимого',
    {'У нас с каждым днем прибавляется раненых, у всех – сильное отравление. Причем с таким ядом мы раньше не сталкивались. Я не знаю, что там за пакость в ядовитых железах у нерубов; известно только, что их яд смертелен и не поддается никаким целительным снадобьям. Пока что нам удавалось только замедлить процесс общего отравления. Но нам нужно найти противоядие!|n|nИди на северо-запад, в долину рядом с аванпостом, и убей десятка полтора нерубов Забытых глубин. Вырежи их ядовитые железы и принеси мне.', },
    {'Принесите 10 ядовитых желез душителей Забытых глубин отцу Густаву в Оплот Серебряного Авангарда в Ледяной Короне.', },
  },
  [13041] = {
    'Недостающий камень',
    {'Как удачно, что ты $Gзашел:зашла;! Груз блестящих статуэток из бивня уже отправляется в Нижнюю Шахту, а мне, как назло, не хватает кальцедония – закончить глаз у последней статуэтки. Принеси мне кальцедоний, и я дам тебе еще один значок даларанского ювелира.', },
    {'Принесите кусок кальцедония Тимоти Джонсу в Даларан.', },
  },
  [13042] = {
    'В недрах Глубинных чертогов',
    {'В недрах Глубинных чертогов на северо-востоке сумасшедший ученый по имени доктор Ужас творит всякие бесчинства, вполне соответствующие его имени.|n|nКороль-лич дал ему разрешение ставить эксперименты над варгулами – врайкулами, которые погибли в сражении, но их сочли недостойными, воскресили и поставили под знамена Плети.|n|nМы должны его остановить, но гадание не раскрыло мне его точного местонахождения. Однако мы знаем, что у него есть ученик.|n|nВыбей нужную нам информацию из этого ученика, а потом как-нибудь тихо избавься от тела.', },
    {'По поручению костяной ведьмы из деревни Ньорндар выбейте информацию из ученика Остеркилгра: узнайте, где находится доктор Ужас.|n|nПотом убейте ученика.', },
  },
  [13043] = {
    'Когда сумма больше слагаемых',
    {'Вы открываете книгу и видите очень подробные и четкие иллюстрации, отражающие процесс создания того, что доктор называет "абсолютным оружием"!|n|nОчевидный прототип, Нергельд, внушительный мясистый великан, неподвижно стоит в дальнем конце Зала Ужасов.|n|nЕсли будет создана целая армия подобных "конструкций", это действительно будет конец. Существует единственный способ это предотвратить: убить доктора Ужаса!|n|nМожет быть, доктор выйдет к вам, если вы попытаетесь взять контроль над его творением?', },
    {'Заберитесь в Нергельда и возьмите над ним контроль. Защищайте его от обитателей Зала Ужасов, пока не покажется доктор Ужас.|n|nИспользуйте Нергельда, чтобы убить доктора, а потом возвращайтесь в деревню Ньорндар, в пещеру к костяной ведьме.', },
  },
  [13044] = {
    'Пропавшие без вести',
    {'На той стороне Долины Эха, что к западу отсюда, за Проломом, расположилась первая застава Плети в Ледяной Короне – Плетхольм. Мы организовали вылазку на заставу и перебили немало чудовищ Плети, но затем нас отбросили назад. Нескольких солдат недосчитались – они пропали без вести.|n|nЕсли наши товарищи еще живы, их необходимо спасти! Ступай по этой тропе на юго-восток и найди Пенумбриуса. Он – союзник бронзовых драконов и попечитель протодраконов. Он поможет тебе.', },
    {'Поговорите с Пенумбриусом в Оплоте Серебряного Авангарда в Ледяной Короне.', },
  },
  [13045] = {
    'В чащобу',
    {'Мы будем помогать тебе всеми силами, $N. Протодраконы полетят по Пролому в Плетхольм. Спаси всех рыцарей Серебряного Авангарда, которых встретишь. Доставь их в лазарет в самом центре Оплота Серебряного Авангарда.|n|nВозьми небесного когтя Серебряного Авангарда в палатке за моей спиной и ступай!|n|nПлетхольм расположен на северо-западе, по ту сторону Долины Эха, в большом Проломе.', },
    {'Вытащите из Плетхольма 3 плененных рыцарей Серебряного Авангарда и доставьте их в лазарет в центре Оплота Серебряного Авангарда. После этого поговорите с верховным лордом Тирионом Фордрингом.', },
  },
  [13046] = {
    'Муки Арнгрима',
    {'Голод Арнгрима вошел в легенды.|n|nДаже после смерти его лик искажен гримасой ненасытного голода. При одном только взгляде на это лицо у вас начинает бурчать в желудке.|n|nГоворят, что за всю свою жизнь он никогда не наедался досыта, а ведь он ел все подряд. Вы поневоле задумались: а есть ли способ накормить старого короля?|n|nКак только у вас возникает эта мысль, один из огромных замерзших зубов Арнгрима выпадает у него изо рта и, отскочив от его бороды, падает вам на ладонь.', },
    {'Вы должны накормить Арнгрима пятью бесплотными йормунгарами и вернуться к замерзшему изображению Арнгрима в Дун Ниффелем.|n|nИдите в долину Древних Зим и воспользуйтесь зубом Арнгрима, чтобы воздействовать на блуждающих йормунгаров. Когда они развоплотятся, сражайтесь с ними, пока они не ослабнут.', },
  },
  [13047] = {
    'Свидетель',
    {'Локен убил мою жену и настроил против меня моих учеников, а меня против них. Он отнял у меня самое дорогое, но сегодня... все изменится.|n|nСегодня мы вернем себе наши святые земли. Сегодня… Локен умрет.|n|nВстретимся у храма Мудрости, что к юго-западу от Ульдуара. Так или иначе, я положу этому конец.|n|nМне нужен только свидетель, тебе не нужно мне помогать – это дело личное.|n|nКогда все закончится, ты пойдешь к Йоккуму, королю снежных великанов, и расскажешь о том, что было. Он – добрый друг. Он поймет, что делать.', },
    {'Встретьтесь с Торимом у храма Мудрости. Потом отправляйтесь к Йоккуму в Дун Ниффелем и расскажите ему об исходе сражения.', },
  },
  [13048] = {
    'Откуда время пошло не туда',
    {'Молот Знаний может помочь нам исправить поврежденную линию времени, но для этого нам надо найти тот момент в прошлом, откуда время пошло не туда. В противном случае у нас ничего не получится.|n|nСудя по тому, что рассказал вождь Быстрое Копье, и по твоим находкам в Ледяных глубинах, можно с уверенностью предположить, что искажение произошло более-менее одновременно со смертью Штормового Копыта.|n|nОтправляйся на север, в Стенающую ложбину, и обойди древние захоронения, разоренные приспешниками Северного Ветра. Молот Знаний среагирует на подлинные предметы из эры Штормового Копыта и сам настроится на истинное время.', },
    {'Разыщите реликвии таунка и настройте Молот Знаний на истинное время Штормового Копыта. Когда он настроится на 6 реликвий из времени Штормового Копыта, возвращайтесь к Ксанатавру в лагерь Тунка\'ло.', },
  },
  [13049] = {
    'Доспехи героя',
    {'Похоже, не все исторические документы были испорчены вмешательством в ход времени. Мои помощники смогли разыскать записи, отражающие события подлинной линии времени.|n|nТам написано, что Штормовое Копыто был похоронен со всеми почестями среди деревенских старейшин, на нижнем ярусе Стенающей ложбины.|n|nБольшинство захоронений в тех местах уже разграблено войсками Северного Ветра. Им удалось захватить несколько поистине бесценных реликвий. Отправляйся на север, в Стенающую ложбину, и попытайся забрать у потомков бури копье и доспехи Штормового Копыта.', },
    {'Добудьте копье и кольчугу Штормового Копыта и верните их Ксанатавру в лагерь Тунка\'ло.', },
  },
  [13050] = {
    'Веранус',
    {'Если я собираюсь атаковать армию брата, мне нужно придумать, как к ней подобраться.|n|nКогда-то у меня была самка ездового дракона, но я отпустил ее на волю. Веранус была просто великолепна. Истинная предводительница своей стаи – в которую она и вернулась.|n|nНайти ее будет непросто... и все же, я думаю, есть один способ. Она остается в своем старом пустом гнезде – исключительно из гордости. Веранус – праматерь лишь номинально, поскольку давно миновала тот возраст, когда драконы способны к размножению.|n|nПринеси мне яйца из других гнезд, расположенных вблизи Бруннхильдарской деревни. У меня есть одна мысль...', },
    {'Раздобудьте 5 маленьких яиц протодракона в горах рядом с деревней Бруннхильдар и принесите их Ториму в Храм Штормов.', },
  },
  [13051] = {
    'Нарушение границ',
    {'У Веранус есть гордость. Я не знаю другого такого зверя, у которого было бы столько гордости. Она все еще удерживает свое старое гнездо и отгоняет от него молодых протодраконов.|n|nВозьми собранные тобой яйца и помести их в гнездо. Ты найдешь его на вершине невысокой скалы, прямо на юго-восток отсюда.|n|nЯ смогу взять ее под контроль, прежде чем она тебя растерзает. Ну, я надеюсь...', },
    {'Отнесите похищенные яйца протодракона в гнездо праматери и возвращайтесь к Ториму в Храм Штормов.', },
  },
  [13052] = {
    'Воздушная разведка',
    {'Ты хорошо $Gпомог:помогла; Уэсу с починкой и возвращением в строй этого ветролета.|n|nЕсли хочешь и дальше помогать нам, то знай: на нас с северо-запада надвигается необычный атмосферный фронт. У меня есть пилот, но, боюсь, по такой погоде ему нужен напарник.|n|nЕсли ты считаешь, что сможешь справиться, отправляйся в Лагерь у озера. Скажи Вику, что ты от меня.', },
    {'Отправляйтесь в Лагерь у озера по просьбе профессора Кальверт и поговорите там с пилотом Виком.', },
  },
  [13053] = {
    'В поисках уцелевших',
    {'Гретхен Искрошип хочет использовать мой ветролет, чтобы разыскать уцелевших людей из ее экспедиции. Она считает, что их держат в плену в деревне на севере.|n|nПроблема в том, что у меня нет второго пилота. Если ты согласишься лететь со мной, я обучу тебя паре приемов.|n|nЧто скажешь, $N? По рукам?', },
    {'Помогите Заку Шестеркруту совершить испытательный полет.', },
  },
  [13054] = {
    'Пропавший следопыт',
    {'Я не могу со спокойной совестью отправить тебя в пещеру воргов, не предупредив об опасности. Тот, кто пошел туда до тебя, не вернулся.|n|nМы уже приготовились к самому худшему, но оказалось, что он еще жив. Если ты поможешь ему вернуться, мы будем очень тебе благодарны. У нас осталось очень немного охотников, а следопыт Вал\'зиж – один из лучших.', },
    {'Разыщите следопыта Вал\'зижа в логове Гиморака, на юго-востоке от места крушения Гром\'арша.', },
  },
  [13055] = {
    'Лекарство из пещер',
    {'Как приятно увидеть доброжелательное лицо. Кто знает, может быть, это в последний раз.|n|nЯ уже почти выбрался, и тут меня укусил йормунгар. А они ядовиты. Все мое тело уже немеет, я чувствую.|n|nМне нужно противоядие, а для этого надо добыть ядовитую железу у кого-то из этих тварей. И еще мне понадобятся пещерные грибы, чтобы замедлить действие яда... грибы растут здесь...|n|nПожалуйста, поторопись. У меня мало времени.', },
    {'Добудьте 1 ядовитую железу йормунгара и 8 пещерных грибов и доставьте следопыту Вал\'зижу в Логово Гиморака.', },
  },
  [13056] = {
    'Всегда найдется время для мести',
    {'Теперь мне должно стать полегче. Думаю, как-нибудь справлюсь. И все же, $N, я попрошу тебя об одной услуге.|n|nНикто из этих червей не смог бы меня одолеть, если бы подлейший из воргов не убил моего крылатого змея, Хиишу.|n|nОбо мне можешь не беспокоиться. Мне станет легче, когда этот мерзавец ворг сдохнет. Ты найдешь его в глубине пещеры.', },
    {'Убейте Гиморака в пещере Ледяного Воя по просьбе следопыта Вал\'зижа.', },
  },
  [13057] = {
    'Терраса Творцов',
    {'Время пришло, $N. Я готов к встрече с Локеном. Мы отправимся на Террасу Творцов и дадим бой армиям моего брата. Этот дурак пожалеет, что связался со мной.', },
    {'Разыщите Торима на юго-восточном конце Террасы Творцов, к северо-западу от Дун Ниффелема.', },
  },
  [13058] = {
    'Чтобы ветер переменился',
    {'Теперь у нас есть все необходимое, чтобы исправить все то, что испортил Северный Ветер и его приспешники. Ты $Gнастроил:настроила; Молот Знаний на время и личность Штормового Копыта.|n|nСнова возьми молот и отправляйся к Храму Жизни, на равнины к северо-западу. Воспользуйся молотом, чтобы принять облик Штормового Копыта. Потом иди к Северному Ветру под личиной Штормового Копыта, но помни, что в той линии времени, которую нужно восстановить, Штормовое Копыто должен умереть, когда Северный Ветер ослабеет.|n|nТы используешь этот шанс и при помощи рога неистовства стихий уничтожишь Северного Ветра.', },
    {'Используйте Молот Знаний, чтобы вернуться в прошлое и сразиться с Северным Ветром под личиной Штормового Копыта. Когда Штормовое Копыто падет, возьмите рог неистовства стихий и прикончите Северного Ветра, а затем возвращайтесь к Ксанатавру в лагерь Тунка\'ло.', },
  },
  [13059] = {
    'Месть за варгулов',
    {'Я молился Леди Меча, чтобы она прислала кого-то, кто придет и уничтожит моего врага.|n|nТан Иллскар должен сполна заплатить за то, что он со мной сделал!|n|nВ былые времена я бы и сам отомстил этому подлецу, но теперь от меня осталась лишь жалкая оболочка. Я был лучшим воином тана Уфранга Могущественного. Во время боя за власть в Вальхаласе Иллскар применил бесчестный прием: скрытую магию. Я проиграл, и ты видишь, во что я превратился.|n|nТы найдешь тана и его защитников внизу, в Круге Страдания. Вызови его на поединок от моего имени. Убей его, и пусть он тоже познает страдания и муки, как знаю их я!', },
    {'Бросьте меч в Круге Страдания, вызовите на бой и убейте тана Иллскара по просьбе Бетода Фейгра из Глубинных чертогов.', },
  },
  [13060] = {
    'Когда остается единственный выход...',
    {'Что-то я сомневаюсь, что нам удастся закрепиться в этих горах.|n|nПоверь мне, я не из тех, кто легко сдается... но, когда ты зажат между замерзшими машинами, злобными врайкульскими бабами, какими-то непонятными существами, жаждущими стать драконами, и еще добрым десятком других воинственных тварей, это как-то не способствует оптимистическому настрою.|n|nНо ты все же не падай духом! Если мы не можем там закрепиться, это еще не значит, что мы не можем доставить тебя туда... поездка в один конец – это вовсе не сложно, когда привыкаешь.|n|n<Рикет указывает на ракеты неподалеку.>', },
    {'Воспользуйтесь принадлежащим Рикет пропеллерным доставочным аппаратом Д16, чтобы продвинуться вглубь Грозовой Гряды.', },
  },
  [13061] = {
    'Победа или смерть',
    {'Ну вот, время пришло. Я позабочусь о твоей медведице, сейчас она тебе не понадобится. Теперь тебе предстоит сразиться с великим Драконобойцей.|n|nПопрощайся с друзьями, приведи в порядок дела, ибо ты либо вернешься с победой... либо не вернешься вообще.', },
    {'Поговорите с Лок\'лирой Каргой в деревне Бруннхильдар.', },
  },
  [13062] = {
    'Прощальный подарок Лок\'лиры',
    {'Твоя помощь неоценима, $N. Теперь пришло время для настоящего испытания. Тебе понадобится все твое мастерство, мужество и немного везения.|n|n<Лок\'лира прикрепляет к вашим волосам тонкую прядь волос.>|n|nУ тебя все получится. Должно получиться. Поговори с Греттой Судьей. Она скажет тебе, что делать.', },
    {'Поговорите с Греттой Судьей в деревне Бруннхильдар.', },
  },
  [13063] = {
    'Посмотрим, чего ты стоишь',
    {'Сестра, ты добилась успеха там, где многих постигла неудача. Остается лишь выяснить, что тебе помогло: твоя сила и доблесть или простое везение.|n|nВозвращайся в деревню и разыщи там Астрид Бьорнриттар. Расскажи ей о своих достижениях. Только я тебя сразу предупреждаю: на нее нелегко произвести впечатление.', },
    {'По просьбе Бриджаны отправляйтесь в деревню Бруннхильдар и поговорите с Астрид Бьорнриттар.', },
  },
  [13064] = {
    'Соперничество братьев',
    {'Сиф? Это ты? Правда, ты?|n|nНет? $R? Но на мгновение мне показалось...|n|nВсе, хватит! Видения, в которых являлась мне моя Сиф, они терзали меня слишком долго! Пора отомстить за нее и почтить ее память, как должно.|n|nМой брат заплатит за все!', },
    {'Выслушайте историю Торима.', },
  },
  [13065] = {
    'Предок Оханзи',
    nil,
    nil,
  },
  [13066] = {
    'Предок Яруак',
    nil,
    nil,
  },
  [13067] = {
    'Предок Чоган\'гада',
    nil,
    nil,
  },
  [13068] = {
    'Отважный герой',
    {'Вероятно, ты $Gслышал:слышала; о доблестных подвигах нашего пропавшего героя?|n|nРыцарь Бриденбрад сражался с силами Плети на Прорванном фронте, и тут на союзников напало войско нежити. Многие солдаты союзных войск навечно остались на поле боя, но Бриденбрад уцелел и спас больше дюжины воинов – вытащил их из этой мясорубки, одного за другим.|n|nТак вот, |3-6($C), после этого он не вернулся. В последний раз его видели, когда он направлялся на северо-восток, в сторону Молчаливого Бдения. Найди его и приведи ко мне, и я воздам ему почести, подобающие доблестному герою.', },
    {'Отправляйтесь в северо-восточную часть Ледяной Короны, разыщите героя, рыцаря Бриденбрада, в Молчаливом Бдении и приведите его к верховному лорду Тириону Фордрингу на Вершину Рыцарей. Возле его стоянки обычно горит костер, заметный с воздуха.', },
  },
  [13069] = {
    'Пристрели их',
    {'Йотунхейм славится надежной воздушной обороной – это наездники на протодраконах и гарпунные пушки. Особенно много их возле наиболее уязвимых частей города: на севере и на западе.|n|nТак давай используем их оборону против них же!|n|n<Прыгун буравит вас своим единственным глазом и издает маниакальный смешок.>|n|nЗавладей гарпунной пушкой на любой из платформ, висящих над скалами на юго-западе, и уничтожь протодраконов и их наездников. Пристрели их!', },
    {'По заданию Прыгуна из Мрачного Свода сбейте с помощью йотунхеймского скорострельного гарпуна 15 йотунхеймских протодраконов и их наездников.', },
  },
  [13070] = {
    'Приближение холодного фронта',
    {'С запада веет холодом смерти, и холод этот грозится заморозить наши сердца и души и отдать их под власть темного властелина этих снежных пустошей. Но мы не сдаемся! Мы будем сражаться!|n|nПодготовка уже началась. Поговори с осадным мастером Феззиком у главных ворот, и он объяснит тебе твое задание.', },
    {'Поговорите с осадным мастером Феззиком в Оплоте Серебряного Авангарда в Ледяной Короне.', },
  },
  [13071] = {
    'Злоб любит огонь!',
    {'Злоб любит огонь! Злоб любит протодраконов!|n|n<Поганище радостно хлопает в ладоши.>|n|n$GМалыш:Малышка; $N, ступай в Йотунхейм и укради симпатичного протодракончика в деревне Ньорндар. Заставь протодракончика поджечь с десяток построек в Йотунхейме. Чтобы красиво горело красивым огнем!', },
    {'По просьбе Злоба из Мрачного Свода украдите ньорндарского протодракона и заставьте его поджечь 8 построек врайкулов в Йотунхейме.|n|nЦитадель Балагарда, в силу своей природы, гореть не может.', },
  },
  [13072] = {
    'Горькая участь героя',
    {'Я знаю, зачем ты $Gпришел:пришла;... Тебя прислали за мной... только вернуться я не смогу. Я заражен чумой нежити, |3-6($C), и не хочу, чтобы эта зараза коснулась кого-то еще. Нет, я никуда не пойду.|n|nСмерти я не боюсь. Но я знаю, во что превращусь после смерти, и мне ненавистна сама мысль о том, что мне волей-неволей придется служить этому подлому предателю Артасу.|n|nОставь меня... и позаботься о том, чтобы меня не искали. Ты сослужишь мне плохую службу, если, желая спасти меня, ты невольно разнесешь эту заразу.', },
    {'Расскажите о том, что случилось с рыцарем Бриденбрадом, верховному лорду Тириону Фордрингу на Вершине Рыцарей.', },
  },
  [13073] = {
    'Благосклонность хранителя',
    {'В мире есть те, кто обладает неограниченной силой: силой Жизни, силой Света, силой Воскрешения. Бриденбрад – не просто обычный человек... Его доблесть и отвага удивительны. Нам остается только надеяться, что кто-то сможет спасти героя от участи худшей, чем смерть.|n|nОтправляйся к верховному друиду Лилиандре в Оплот Серебряного Авангарда. Попроси ее провести тебя к Лунной поляне и обратись за помощью к хранителю Ремулу.', },
    {'По просьбе верховного лорда Тириона Фордринга с Вершины Рыцарей поговорите с верховным друидом Лилиандрой и доберитесь до хранителя Ремула на Лунной поляне.', },
  },
  [13074] = {
    'Изумрудный кошмар',
    {'Нам нужны желуди, обладающие мощной восстанавливающей магией, а они есть только в Изумрудном Сне. Многое на этой священной поляне тесно связано со Сном, в том числе и мое святилище.|n|nЯ отправлю тебя в Сон, и ты добудешь там такие желуди. Но будь $Gготов:готова; ко всему, |3-6($C): такой способ погружения в Сон очень опасен, и вполне возможно, ты окажешься в самом настоящем кошмаре.|n|nДобудь желуди как можно быстрее. Чтобы вернуться в реальный мир, тебе надо будет покинуть святилище – или же просто ущипнуть себя и проснуться.', },
    {'По заданию хранителя Ремула с Лунной поляны погрузитесь в Изумрудный Сон и добудьте 3 изумрудных желудя.|n|nЧтобы пробудиться, покиньте святилище Ремула или ущипните себя.', },
  },
  [13075] = {
    'Дар Ремула',
    {'Я открою портал. Он приведет тебя обратно к друиду, который отправил тебя сюда. Желаю удачи тебе и особенно – твоему рыцарю. Надеюсь, этот желудь очистит твоего рыцаря от скверны и спасет его от печальной судьбы зараженных.|n|nПрощай, |3-6($R).', },
    {'Отнесите изумрудный желудь рыцарю Бриденбраду в Молчаливое Бдение, что в Ледяной Короне.', },
  },
  [13076] = {
    'Время еще есть',
    {'Я чувствую себя как будто бы обновленным. Но чума не отступила до конца. Но невелика печаль! Я так благодарен тебе, ведь мы совсем незнакомы, а ты $Gпроделал:проделала; ради меня такой путь. Ты $Gподарил:подарила; мне несколько драгоценных часов жизни, когда я не буду заражать остальных, как это делает мерзкая нежить.|n|nСпасибо тебе, |3-6($C). И передай, пожалуйста, мою благодарность Тириону. Скажи ему, что помочь ему было для меня настоящей честью.', },
    {'Возвращайтесь к верховному лорду Тириону Фордрингу на Вершину Рыцарей и сообщите ему о том, каким действием обладают изумрудные желуди.', },
  },
  [13077] = {
    'Прикосновение Аспекта',
    {'Королева драконов Алекстраза всегда обладала способностями к магии. Своим огнем она умеет выжигать нежить и создавать новую жизнь. Кто знает, может, она и Бриденбраду поможет.|n|nАлекстраза живет в храме Драконьего Покоя, что в Драконьем Погосте. Отправляйся к ней и передай мою нижайшую просьбу о помощи.', },
    {'Попросите о помощи Алекстразу Хранительницу Жизни из храма Драконьего Покоя.', },
  },
  [13078] = {
    'Слезы Далии',
    {'В эти темные времена я не брошу поборника Света в беде.|n|nНам нужно что-то, наделенное святой силой: что-то, что даст нам надежду на спасение твоего Бриденбрада... Останки верного, преданного существа, павшего жертвой той же угрозы.|n|nОтправляйся к священной земле, окружающей Рубиновое святилище драконов. Когда Рубиновые хранители воспламенят землю под ногами нежити, ты увидишь, как зарождается и тянется к свету новая жизнь. Среди ростков будут и слезы Далии – принеси их мне.', },
    {'Сорвите слезы Далии с земли, очищенной пламенем Рубиновых хранителей, и принесите их Алекстразе Хранительнице Жизни в храм Драконьего Покоя.', },
  },
  [13079] = {
    'Дар Алекстразы',
    {'Ты $Gдолжен:должна; понимать, $Gюный:юная:r; |3-6($R), что моей власти достаточно, чтобы очистить тело во имя новой жизни... но изгнать из него чуму нежити так, чтобы не повредить само тело – это выше моих сил.|n|nЕсли все обстоит так, как ты говоришь, и этот Бриденбрад и вправду столь доблестный рыцарь и верный поборник Света, может быть, он и выдержит обряд очищения, но я не могу ничего обещать. Вот, возьми это, и прими мое благословение.', },
    {'Отнесите Дыхание Алекстразы рыцарю Бриденбраду в Молчаливое Бдение, что в в Ледяной Короне.', },
  },
  [13080] = {
    'Надежда жива',
    {'<Бриденбрад машет вам рукой, одновременно пытаясь отдышаться.>|n|nКак я и ожидал, было очень больно, но я буквально почувствовал, как порча уходит из моего тела. Но чуму так легко не изгонишь.|n|nСпасибо тебе за все, |3-6($C). Твоя самоотверженность заставила меня поверить, что в мире еще есть много хорошего и надежда жива. Я могу уйти, не боясь, что в мое отсутствие тьма возобладает над светом.|n|nА теперь иди. Иди и ни о чем не жалей.', },
    {'Вернитесь к верховному лорду Тириону Фордрингу на Вершину Рыцарей. Расскажите ему о действии Дыхания Алекстразы.', },
  },
  [13081] = {
    'Завещание наару',
    {'Мы очень благодарны за все, что ты для нас $Gсделал:сделала;, $N. У меня есть к тебе последняя просьба... Последняя надежда для паладина, достойного большего, чем мы можем дать.|n|nОтправляйся в Шаттрат и поговори с А\'далом из народа наару. Он всегда был поборником Света и преданным другом паладинов. Расскажи ему историю Бриденбрада и попроси о помощи.|n|nЯ даже передать не могу, насколько это важно. Боюсь, если ты не поторопишься, ничто уже не спасет нашего рыцаря.', },
    {'Попросите о помощи А\'дала из Шаттрата, который находится в лесу Тероккар.', },
  },
  [13082] = {
    'Дар А\'дала',
    {'Рад тебя видеть, $N. Я знаю, что случилось с рыцарем Бриденбрадом. И как ты $Gпытался:пыталась; его спасти, тоже знаю. Видно, отвага Бриденбрада передалась и тебе, а это уже само по себе чудо.|n|nСвет помогает тем, кто ему верен. Я благословлю Бриденбрада, и ему больше не будет угрожать участь нежити. Тебя же я перенесу обратно, в Даларан, чтобы ты $Gсмог:смогла; его найти. И помни: я всегда с тобой.', },
    {'Вернитесь к рыцарю Бриденбраду в Молчаливое Бдение, что в Ледяной Короне.', },
  },
  [13083] = {
    'Свет во тьме',
    {'<Накидка рыцаря Бриденбрада лежит на дне сундука и легонько колышется от ветра, проникшего внутрь.>|n|nТирион наверняка захочет получить эту последнюю реликвию, оставшуюся от великого рыцаря.', },
    {'Отнесите плащ рыцаря Бриденбрада верховному лорду Тириону Фордрингу на Вершину Рыцарей.', },
  },
  [13084] = {
    'Психологическая атака',
    {'Нам удалось подорвать боевой дух врайкулов, $N, и надо бы продолжать в том же духе.|n|nЯ хочу, чтобы ты каждый день $Gездил:ездила; в Йотунхейм и $Gпредавал:предавала; огню их знамена. Может быть, это и примитивный подход, но каждый день видеть пожары на своей территории – это деморализует похлеще, чем силовые методы воздействия.|n|nКак бы то ни было... хуже не будет!', },
    {'Сожгите 10 знамен врайкулов по поручению герцога Ланкрала из Мрачного Свода.', },
  },
  [13085] = {
    'Возвращение Вэлена',
    {'Я только видел, как этот глупец Вэлен Разоблаченный прокрался в склеп.|n|nТы уж позаботься, чтобы он осознал свои ошибки и вернул мне моих рыцарей смерти.', },
    {'Поговорите с Вэленом Разоблаченным в Мрачном Своде.', },
  },
  [13086] = {
    'Последний рубеж',
    {'Я знаю, как укрепить оборону Оплота, |3-6($C)! На верхушке каждой из четырех башен находится откатная пушка Серебряного Авангарда, освященная самим отцом Густавом. Ты полетишь на одну из этих башен и с помощью пушки будешь уничтожать штурмующие Оплот силы Плети.|n|nНо помни: на осаду башен наверняка пошлют ледяных змеев. Их надо сбить прямо в воздухе! Если змеи разрушат стены и башни, нам конец.', },
    {'Уничтожьте 100 солдат Плети с помощью пушки Серебряного Авангарда. Также уничтожьте 3 ледяных драконов-разрушителей.|n|nВ случае успеха вернитесь к осадному мастеру Феззику.', },
  },
  [13087] = {
    'Кулинария севера',
    {'Ну и что ты тут $Gзабыл:забыла;? Где мой обед? Я скоро с ГОЛОДУ сдохну! Принеси мне хотя бы охлажденного мяса, чтобы я сварил похлебку! Принесешь – дам тебе рецепт, будешь $Gсам:сама; себе еду варить. БЫСТРЕЕ, НЕСИ МНЕ МЯСО!', },
    {'Принесите четыре куска охлажденного мяса зверей Нордскола Брому Выпивастеру в Валгард.', },
  },
  [13088] = {
    'Кулинария севера',
    {'Как много новобранцев – и всех их надо хорошенько накормить! Если ты принесешь мне немного охлажденного мяса, я сделаю им мясную похлебку, а ты получишь рецепт.', },
    {'Принесите четыре куска охлажденного мяса зверей Нордскола Роллику Маккрилу в Крепость Отваги.', },
  },
  [13089] = {
    'Кулинария севера',
    {'Что может быть лучше согревающей мясной похлебки? Принеси мне немного охлажденного мяса проклятых тварей, что бродят по этому краю, и я научу тебя, как делать мою похлебку.', },
    {'Принесите четыре куска охлажденного мяса зверей Нордскола Томасу Количио в Лагерь Возмездия.', },
  },
  [13090] = {
    'Кулинария севера',
    {'Воинам армии Песни Войны нужна горячая пища. Если ты принесешь мне немного охлажденного мяса люторогов и прочих зверей, я сделаю им мясную похлебку, а ты получишь рецепт.', },
    {'Принесите четыре куска охлажденного мяса зверей Нордскола Орну Хрупкое Копыто в Крепость Песни Войны. Охлажденное мясо можно достать только убивая зверей, обитающих на континенте Нордскол.', },
  },
  [13091] = {
    'Нелегко быть водным ужасом',
    {'Ворота шлюза за стенами моей пещеры так и кишат элементалями, которых врайкульским магам еще только предстоит укротить. Я научу тебя одной хитрости, которая позволит тебе ненадолго подчинять себе этих существ, и ты сможешь всерьез ударить по Йотунхейму.|n|n<Одержимая банши ведьма чертит что-то в воздухе и прикладывает вам ко лбу большой палец.>|n|nИди и открой ворота шлюза! Водный ужас выскочит оттуда и ты, завладев им, сможешь уничтожить всех врагов!', },
    {'По заданию костяной ведьмы из деревни Ньорндар завладейте водяным ужасом и уничтожьте с его помощью 10 врайкулов в окрестностях Йотунхейма.|n|nВаша кара может коснуться йотунхеймских хранителей снов, йотунхеймских воинов, мьординских волхвов воды, ньорндарских копьеносиц и валхальских варгулов.', },
  },
  [13092] = {
    'Гадание по костям',
    {'Завладев этим созданием, я получила доступ ко всей ее силе и знаниям. Это действительно очень удачно. Будучи костяной ведьмой и прорицательницей по рунам, она владеет искусством бросать кости и тем самым определять чью-то судьбу.|n|n<Костяная ведьма усмехается.>|n|nНам с тобой повезло, что я могу повлиять на ее предсказания своей властью.|n|nПринеси мне кости врайкулов, которых ты $Gубил:убила; здесь в Йотунхейме, я их брошу и дам тебе шанс $Gсамому:самой; определить свою собственную судьбу.', },
    {'Принесите 15 костей врайкулов костяной ведьме в деревню Ньорндар.', },
  },
  [13093] = {
    'Гадание по костям',
    nil,
    nil,
  },
  [13094] = {
    'Ни стыда, ни совести',
    {'Верховный маг Беринард – это представитель Кирин-Тора при Малигосе. Он провел всю свою жизнь, изучая особенности его поведения.|n|nНедавно он передал мне свою работу, "Чарономикон", которая содержит в себе карту, которую пытается раздобыть Малигос. К несчастью, я совершила глупость и показала ее неким путешественникам из Орды, которые покупали у меня припасы, и после их ухода карта исчезла!|n|nДолжно быть, они ее украли. Прошу тебя,|3-6($C). Последуй за ними в Нексус и найди книгу прежде, чем Беринард захочет ее вернуть.', },
    {'Библиотекарь Серра просит вас зайти в Нексус и найти книгу с исследованиями Беринарда.', },
  },
  [13095] = {
    'Ни стыда, ни совести',
    {'Верховный маг Беринард – это представитель Кирин-Тора при Малигосе. Он провел всю свою жизнь, изучая особенности его поведения.|n|nНедавно он передал мне свою работу, "Чарономикон", которая содержит в себе карту, которую пытается раздобыть Малигос. К несчастью, я совершила глупость и показала ее неким путешественникам из Альянса, которые покупали у меня припасы, и после их ухода карта исчезла!|n|nДолжно быть, они ее украли. Прошу тебя, |3-6($C), последуй за ними в Нексус и найди книгу прежде, чем Беринард захочет ее вернуть.', },
    {'Библиотекарь Серра просит вас зайти в Нексус и найти книгу с исследованиями Беринарда.', },
  },
  [13096] = {
    'Гал\'дара заплатит за все',
    {'Ты $Gвидел:видела;?|n|nЯ в жизни не видел такого кошмара! Великий Акали убит у меня на глазах... Это было ужасно...|n|nЯ поклялся не лезть в это дело. Моя задача – наблюдать. Но всему есть предел! Гал\'дара не должен уйти безнаказанным! Он заплатит за все!|n|nИди в Гундрак и разыщи там Гал\'дара. Смерть Акали требует отмщения. И ты станешь орудием мести. Возвращайся ко мне, когда все будет сделано.', },
    {'Отправляйтесь в Гундрак и убейте Гал\'дара по поручению Тол\'мара из Дубра\'джина.', },
  },
  [13097] = {
    'Неоконченное дело',
    {'Да, это правда: пророк Акали больше не потревожит этот мир, – однако нам предстоит еще многое сделать.|n|nБольшую часть крови Акали принял другой, и именно он представляет угрозу.|n|nВот что, $N, отправляйся в Дубра\'джин, что на севере от Гундрака, и поговори с Тол\'маром. Он подскажет, что делать дальше.', },
    {'Поговорите с Тол\'маром в Дубра\'джине по просьбе Хар\'коа.', },
  },
  [13098] = {
    'Для наших потомков',
    {'Гундрак обречен.|n|nИстория повторяется у нас на глазах. Когда тролли выступают против своих же богов, конец известен. И он непременно настанет. Это лишь вопрос времени...|n|nНо если мы составим правдивую летопись всех событий, может быть, нам удастся предостеречь будущие поколения, чтобы они не пошли по тому же гибельному пути.|n|nЕсли тебе хватит смелости, отправляйся в Гундрак и разыщи исторические доказательства, которые дадут нам ответ на вопрос, что стало причиной падения империи Драккари.', },
    {'Отправляйтесь в Гундрак и заберите оттуда 6 табличек с летописью Драккари по поручению летописца Ба\'Кини из Дубра\'джина.', },
  },
  [13099] = {
    'Просто проверка',
    {'Понимаешь, какое дело... со стороны Гундрака постоянно доносится какой-то зловещий грохот. В последнее время – все громче и чаще.|n|nОдна моя давняя ученица ведет наблюдения на посту, расположенном к западу от Гундрака. Может быть, найдешь время, заглянешь к ней и проверишь, все ли у нее в порядке?', },
    {'Поговорите с Ба\'Кини в Дубра\'джине по просьбе То\'кини.', },
  },
  [13100] = {
    'Мясной рулет в странногрибном соусе',
    {'У нас снова заказ с доставкой! Мясной рулет с грибами для Ортона Беннета из "Диковин и редкостей".|n|nРаздобудь 4 странных гриба из Стоков Даларана и 2 куска охлажденного мяса, запеки их в форме для мясного рулета на любом открытом огне и отнеси Ортону.', },
    {'Сварите 4 странных гриба из Стоков Даларана и 2 куска охлажденного мяса, чтобы получить мясной рулет, и отнесите готовое блюдо Ортону Беннету в лавку "Диковины и редкости" на площадь Руноплета в Даларане.', },
  },
  [13101] = {
    'Сбор в Приюте фокусника',
    {'Арилль Лазурный Взгляд из "Приюта фокусника" ожидает наплыва гостей, ему предстоит приготовить море угощений, чтобы хватило на всех, и очень быстро! |n|nПринеси-ка мне северной похлебки и кувшин с вином из сырной лавки "Еще по сто", она находится прямо в центре Даларана. Хозяин лавки как раз задолжал мне винишко. Оно должно быть где-то там, у него в магазине.|n|nОтнеси вино и мясо Ариллю.', },
    {'Приготовьте 4 порции северной похлебки, возьмите кувшин с вином из сырной лавки в Даларане и отнесите все Ариллю Лазурному Взгляду в "Приют фокусника" на площади Руноплета.', },
  },
  [13102] = {
    'Рагу для завсегдатаев Стоков',
    {'Аджаю Грину, хозяину таверны из Стоков Даларана, срочно понадобилось овощное рагу. Припасы подходят к концу, и скоро ему будет нечем кормить клиентов.|n|nСобери 4 морковки из леса Хрустальной Песни и потуши их с 4 кусками охлажденного мяса.|n|nВ лес Хрустальной Песни можно попасть через портал в восточном углу площади Руноплета.|n|nКогда рагу будет готово, отнесите его Аджаю.', },
    {'Потушите 4 морковки из леса Хрустальной Песни с 4 кусками охлажденного мяса в кухонном горшке.|n|nКогда овощное рагу будет готово, отнесите его хозяину таверны Аджаю Грину в Стоки Даларана.', },
  },
  [13103] = {
    'Сыр для Златоплава',
    {'Ранид Златоплав из кожевенной лавки вдруг возжелал вина с сыром.|n|nВозьми сыра с полки в сырной лавке под названием "Еще по сто" в центре Даларана, а потом пройдись по кабакам и слей остатки вина из всех недопитых стаканов в одну бутылку. Отнеси вино с сыром Раниду.|n|nЕсть предположение, что он ничего и не заметит.', },
    {'Возьмите зрелый даларанский камамбер в сырной лавке "Еще по сто", потом пройдитесь по Даларану и слейте в бутылку остатки вина из 6 полупустых бокалов, стоящих на столах.|n|nОтнесите вино и сыр Раниду Златоплаву в кожевенную лавку в Торговой палате волшебников.', },
  },
  [13104] = {
    'И снова в Пролом',
    {'Аванпост укреплен, и ему ничто не угрожает. Мы отбили Долину Эха и уничтожили стены из паутины, закрывавшие вход в Пролом. Пришло время двинуться на Плетхольм и закрепиться в Ледяной Короне. Линия фронта сдвигается!|n|nЯ попросил черного хранителя помочь нам со штурмом Плетхольма. Он много знает о Плети, и эти знания нам пригодятся.|n|nИди к нему. Ты найдешь его в палатке у входа в Пролом, к северо-западу отсюда.', },
    {'Поговорите с черным хранителем в Долине Эха у входа в Пролом.', },
  },
  [13105] = {
    'И снова в Пролом',
    {'Аванпост укреплен, и ему ничто не угрожает. Мы отбили Долину Эха и уничтожили стены из паутины, закрывавшие вход в Пролом. Пришло время двинуться на Плетхольм и закрепиться в Ледяной Короне. Линия фронта сдвигается!|n|nЯ попросил черного хранителя помочь нам со штурмом Плетхольма. Он много знает о Плети, и эти знания нам пригодятся.|n|nИди к нему. Ты найдешь его в палатке у входа в Пролом, к северо-западу отсюда.', },
    {'Поговорите с черным хранителем в Долине Эха у входа в Пролом.', },
  },
  [13106] = {
    'Черный дозор',
    {'На Мясопилке Плети создаются поганища и мясистые великаны. Если нам удастся закрыть Мясопилку, то Король-лич останется без значительной части армии.|n|nЯ послал туда темную всадницу Арли. Ее штаб, Черный дозор, расположен на горном хребте, к западу от Корп\'ретара, прямо над Мясопилкой. Я слышал, что Серебряный Авангард собирается послать туда кого-то еще, но темная всадница точно знает, что делать. Найди Арли и помоги ей.', },
    {'Поговорите с темной всадницей Арли в Черном дозоре, что в Ледяной Короне.', },
  },
  [13107] = {
    'Сосиски с горчицей!',
    {'Верховный маг Пентарус любит смотреть битбол и сейчас собирается на матч, но ему нужно взять с собой что-нибудь перекусить.|n|nТебе нужно собрать ему корзинку для пикника. Положишь туда 4 сосиски из мяса люторога и 4 побега полевой горчицы, она растет прямо в городе, на зеленых участках.|n|nСобранную корзинку надо отдать верховному магу, чтобы у него было чем перекусить, пока он будет смотреть игру.', },
    {'Заполните пустую корзинку для пикника. Положите туда 4 сосиски из мяса люторога, которые вы приготовите сами, и 4 побега полевой горчицы, которая растет на зеленых участках в черте Даларана.|n|nОтнесите корзинку для пикника верховному магу Пентарусу на площадку Краса в Даларане.', },
  },
  [13108] = {
    'Любой ценой!',
    {'Так или иначе, Локен падет.|n|nДаже если мне лично придется поотрывать ему руки и ноги, он заплатит сполна за свои отвратительные деяния.|n|nЕсли встретишь его раньше меня, честь и слава победителя Локена достанутся тебе.|n|nПринеси мне его лживый язык – и заслужишь мою благодарность и благословение.', },
    {'Отправляйтесь в Чертоги Молний и убейте Локена. Потом возвращайтесь к королю Йоккуму в Дун Ниффелем и отдайте ему язык Локена.', },
  },
  [13109] = {
    'Диаметральные противоположности',
    {'Я скажу прямо, $Gмалыш:невеличка:r; |3-6($R). С тех пор, как у нас порвались узы дружбы с Торимом, что-то в нас изменилось... Мы уже не те, что прежде.|n|nКак вождь и правитель, я желаю лишь одного: чтобы мой народ не таил зла на Торима, чтобы их сердца исцелились, и наша дружба с Повелителем Бурь была восстановлена. Твоя победа над Фьорном стала первым шагом на этом пути. Теперь надо сделать следующий шаг...И ты вновь нам поможешь.|n|nВолхан из Чертогов Молний – это враг посильнее Фьорна. И он намного опаснее, потому что он не успокоится, пока не уничтожит нас – или пока не погибнет сам.', },
    {'Отправляйтесь в Чертоги Молний и убейте Волхана по поручению короля Йоккума из Дун Ниффелема.', },
  },
  [13110] = {
    'Неупокоенный',
    {'Далеко не все наши солдаты вернулись из Плетхольма. Многие были убиты и после смерти превращены в чудовищные подобия самих себя. Так поступает Плеть. Души этих бойцов не могут обрести покой. Мы должны помочь им.|n|nОтправляйся через Пролом в Плетхольм и уничтожь оживленных рыцарей. Окропи кости этой святой водой, и их души наконец обретут покой.', },
    {'По поручению отца Густава из Долины Эха в Ледяной Короне окропите кости 10 оживленных рыцарей святой водой, чтобы освободить наконец их неупокоенные души.', },
  },
  [13111] = {
    'Единственный в своем роде',
    {'Слушай сюда.|n|nНа первый взгляд, вроде обычная история: тролли выпустили в мир запретные силы, уничтожив своих же богов, которым должны поклоняться.|n|nТак-то оно так, но эти драккари – случай особый. Если все, что я слышала, правда, то в Гундраке сооружают какого-то особенного голема – говорят, что таких еще не было!|n|nТы же $Gискал:искала; приключений, да? Вот и давай отправляйся в Гундрак и принеси мне кусок этого самого голема – на предмет изучения.', },
    {'Отправляйтесь в Гундрак, добудьте обломок колосса Драккари и отнесите его летописцу Ба\'Кини в Дубра\'джин.', },
  },
  [13112] = {
    'Мясной рулет в странногрибном соусе',
    {'Ортон Беннет из "Диковин и редкостей" желает мяса с грибами.|n|nРаздобудь 4 странных гриба и 2 куска охлажденного мяса в Стоках Даларана, свари их в котелке на любом открытом огне и отнеси Ортону.|n|nЭх... если бы Совет разрешил мне готовить мои фирменные блюда из гномов, я бы им показал, что такое настоящее объедение!', },
    {'Сварите 4 странных гриба из Стоков Даларана и 2 куска охлажденного мяса, чтобы получить мясной рулет, и отнесите готовое блюдо Ортону Беннету в лавку "Диковины и редкости" на площадь Руноплета в Даларане.', },
  },
  [13113] = {
    'Сбор в Приюте фокусника',
    {'Прикинь: в Орде приняли закон, запрещающий каннибализм... это кто же такое придумал, хотелось бы знать! И как мне теперь выполнять все заказы?! Это ж я так разорюсь... Впрочем, давай сразу к делу.|n|nАрилль Лазурный Взгляд в "Приюте фокусника" скоро принимает у себя гостей. Им надо обеспечить кормежку. Короче, иди в сырную лавку в центре Даларана и возьми там кувшин с вином. И еще ему нужна северная похлебка.|n|nШевелись, Арилль ждет!', },
    {'Приготовьте 4 порции северной похлебки, возьмите кувшин с вином из сырной лавки в Даларане и отнесите все Ариллю Лазурному Взгляду в "Приют фокусника" на площади Руноплета.', },
  },
  [13114] = {
    'Рагу для завсегдатаев Стоков',
    {'У нас тут образовался еще один заказец. Хозяину таверны из Стоков Даларана срочно понадобилось овощное рагу, а то ему нечем кормить клиентов.|n|nОн просит именно овощное рагу, а то он, видишь ли, не оценил того сочного гнома, которого я добавил в рагу в прошлый раз. Собери 4 морковки в лесу Хрустальной Песни, потуши их с 4 кусками охлажденного мяса и отнеси Аджаю. В лес Хрустальной песни можно попасть через портал в восточном углу площади Руноплета.', },
    {'Потушите 4 морковки из леса Хрустальной Песни с 4 кусками охлажденного мяса в кухонном горшке.|n|nПотом отнесите овощное рагу хозяину таверны Аджаю Грину в Стоки Даларана.', },
  },
  [13115] = {
    'Сыр для Златоплава',
    {'Ранид Златоплав из кожевенной лавки требует вина и сыра. И чего бы ему не съесть сочного сытного гнома? Не понимаю!|n|nНабери сыра в сырной лавке в центре Даларана, а потом пройдись по кабакам и слей остатки вина из всех недопитых стаканов в одну бутылку. Отнеси вино с сыром Раниду.|n|nВино можешь назвать "Хмельной сюрприз", хе-хе.', },
    {'Возьмите зрелый даларанский камамбер в сырной лавке "Еще по сто", потом пройдитесь по Даларану и слейте в бутылку остатки вина из 6 полупустых бокалов, стоящих на столах.|n|nОтнесите вино и сыр Раниду Златоплаву в кожевенную лавку в Торговой палате волшебников.', },
  },
  [13116] = {
    'Сосиски с горчицей!',
    {'Верховный маг Пентарус обожает смотреть свой дурацкий битбол, закусывая в это время чем-нибудь вкусненьким.|n|nТебе нужно собрать ему корзинку для пикника. Положишь туда 4 сосиски из мяса люторога и 4 побега полевой горчицы, она растет прямо в городе, на зеленых участках.|n|nВ общем, обеспечь верховного мага сосисками с горчицей.', },
    {'Заполните пустую корзинку для пикника. Положите туда 4 сосиски из мяса люторога, которые вы приготовите сами, и 4 побега полевой горчицы, которая растет на зеленых участках в черте Даларана.|n|nОтнесите корзинку для пикника верховному магу Пентарусу на площадку Краса в Даларане.', },
  },
  [13117] = {
    'Откуда они берутся?',
    {'Слуги Короля-лича не знают усталости. Они трудятся день и ночь: собирают поганищ и мясных великанов в лабораториях в Мясопилке. Они создают их десятками! |n|nНо им этого мало. К ним туда постоянно прибывают скелетные создания, чтобы ускорить темп работ.|n|nЕсли мы не узнаем, откуда они появляются, и как они умудряются работать так быстро, они сотворят столько чудовищ, что те просто задавят нас числом. Отправляйся на юго-восток и попробуй узнать, откуда берутся эти скелеты.', },
    {'Проведите разведку у алтаря призыва в восточной части Мясопилки и возвращайтесь с докладом к темной всаднице Арли, которая ждет вас в Черном дозоре.', },
  },
  [13118] = {
    'Очищение Плетхольма',
    {'Силы Плети, отправленные на штурм Оплота Серебряного Авангарда, были отброшены. Теперь они, что называется, рвут и мечут. Все узники, находящиеся в Плетхольме, будут казнены и после смерти превращены в слуг Короля-лича.|n|nСеребряный Авангард наверняка обратится к тебе с просьбой достойно проводить этих бойцов. Я же не могу просить тебя об этом. Если мы хотим победить, то должны уничтожить Плеть на корню.|n|nОтправляйся через Пролом на северо-запад, в Плетхольм, уничтожая всех и вся на своем пути.', },
    {'По заданию черного хранителя из Долины Эха в Ледяной Короне уничтожьте 3 верховных жрецов Забытых глубин, 3 королей Забытых глубин и 8 оживленных рыцарей.', },
  },
  [13119] = {
    'Разрушение алтарей',
    {'Значит, у этих алтарей они вызывают своих рабочих и воинов?|n|nИми мы и займемся в первую очередь. У мастера призыва должен быть посох для активации портала. Если убить главного призывателя и забрать его посох, с его помощью можно устроить перегрузку портала Призыва и разрушить соответствующий алтарь.|n|nУничтожь все четыре алтаря, и когда все будет сделано, возвращайся ко мне.', },
    {'Убейте главного призывателя Зарода и используйте его посох призыва, чтобы уничтожить первый, второй, третий и четвертый алтари призыва. Когда все будет сделано, возвращайтесь к темной всаднице Арли в Черный дозор.', },
  },
  [13120] = {
    'Взгляд смерти',
    {'Мясопилка – это крупномасштабный проект, и нам будет трудно уследить за всем, что у них происходит. Но у меня есть план.|n|n<Из складок плаща Арли достает шар и показывает его вам.>|n|nЭто сфера взгляда смерти. С ее помощью мы можем следить за действиями Плети, чтобы знать, где лучше нанести удар.|n|nРазмести такие сферы у трех наиболее важных объектов: у лаборатории поганищ и лаборатории мясистых великанов на юго-западе, а также рядом с огромным зеленым котлом далеко на западе.', },
    {'Разместите сферу взгляда смерти на стойке у лаборатории поганищ, стойке у лаборатории мясистых великанов и стойке в окрестностях котла. Когда все будет готово, возвращайтесь к темной всаднице Арли в Черный дозор.', },
  },
  [13121] = {
    'Чужими глазами',
    {'Если мы хотим победить, то должны ударить по Королю-личу его же оружием.|n|nНа горе, находящейся к юго-западу отсюда, стоит крепость Кул\'галар. В ней живут йотунхеймские оракулы, которые подчиняются своему хозяину и следят за всеми с помощью Ока Короля-лича.|n|nВот это-то Око тебе и надо добыть. Увидеть, что происходит в цитадели Ледяной Короны, с его помощью не удастся, зато мы сможем узнать что-то важное о нашем противнике, чтобы затем принять верное решение.', },
    {'По просьбе костяной ведьмы из деревни Ньорндар добудьте информацию о противнике с помощью Ока Короля-лича.', },
  },
  [13122] = {
    'Камень Плети',
    {'Камень Плети дается каждому солдату Плети при рождении или после создания. Он дает им дополнительную силу, а их правителями – возможность наблюдать за тем, где находится и что делает каждый из солдат.|n|nЕсли у меня будет достаточное количество таких камней, то, возможно, я смогу отслеживать перемещение сил Плети внутри Ледяной Короны.|n|nУничтожая воинов Плети в Плетхольме, не забывай забирать у них камни. Когда их наберется достаточно, возвращайся ко мне.', },
    {'Принесите черному хранителю из Долины Эха в Ледяной Короне 15 камней Плети.', },
  },
  [13124] = {
    'И вновь продолжается бой',
    {'Битва продолжается, $N. Нам чудом удалось избежать обнаружения, и теперь мы по-прежнему пытаемся сорвать планы Малигоса. Но на этом хорошие новости заканчиваются... |n|nДаже самые лучшие наши попытки не привели практически ни к чему. Малигос и его прислужники продолжают набирать силу! К тому же, последний посланный нами диверсионный отряд был схвачен и помещен в окулус.|n|nМы должны попытаться их спасти! Белгаристраз и его товарищи крайне важны для выполнения нашей миссии. Мы можем на тебя рассчитывать, $N?', },
    {'Релораз просит вас войти в Окулус и спасти Белгаристраза с его командой.', },
  },
  [13125] = {
    'Чистое небо',
    {'Если мы хотим освободить эти земли от сил Плети, надо уничтожить хозяев Плетхольма.|n|nСалнаракс Резчик Плоти руководит храмом на первом ярусе Плетхольма. Неподалеку от него, в башне духов на втором ярусе, располагается верховный жрец Ят\'амон. А король подземелий Талонокс находится в Яме чудовищ, это на верхней дороге.|n|nВсе трое очень опасны. Будь $Gосторожен:осторожна; и, если понадобится помощь, труби в этот рог. Рыцари смерти Акеруса не оставят тебя в беде.', },
    {'По заданию черного хранителя из Долины Эха в Ледяной Короне убейте Салнаракса Резчика, короля подземелий Талонокса и верховного жреца Ят\'амона.', },
  },
  [13126] = {
    'Единым фронтом',
    {'Прими нашу благодарность, |3-6($R).|n|nТы и твои друзья помогли нам одолеть Дракоса, но теперь нам придется объединить усилия.|n|nПрямо над нами за непроницаемым барьером скрывается Варос. Чтобы добраться до него, тебе придется убить Центрифужные создания, которые питают его щит. После этого мы с друзьями присоединимся к тебе... |n|nКаждый из нас предоставит тебе дрейка, с помощью которых ты сможешь одолеть Вароса.', },
    {'Белгаристраз просит вас уничтожить 10 Центрифужных созданий, разрушить щит Вароса и одолеть самого Заоблачного Странника.', },
  },
  [13127] = {
    'Маг-лорд Уром',
    {'Теперь нам осталось преодолеть только одно препятствие, |3-6($C), и имя ему Уром.|n|nОн ждет нас наверху, на третьем кольце. Берегись, друг, ибо он могучий волшебник. Только тебе под силу бросить ему вызов.|n|nУбей его, и пусть он поплатится за то, что встал на сторону нашего врага!', },
    {'Белгаристраз просит вас победить Мага-лорда Урома в Окулусе.', },
  },
  [13128] = {
    'Высокие ставки',
    {'Настало время сразиться с Эрегосом, друг мой.|n|nОн сильный и хитрый противник. Как один из наиболее доверенных слуг Малигоса, он черпает силы из энергии, которой он заряжен.|n|nОдолеть его будет непросто...|n|nНо победа над магом-лордом дала возможность воспользоваться полной силой наших дрейков, и теперь их умения будут в твоем распоряжении. Воспользуйся ими с умом – и Эрегос вскоре падет. |n|nЕсли тебе будет сопутствовать удача, вернись к Релоразу и расскажи ему о нашей победе.', },
    {'Белгаристраз просит вас убить Эрегоса в Окулусе, после чего оповестить о его смерти Релораза из лагеря под Маскировочным щитом в Хладарре.', },
  },
  [13129] = {
    'Игры разума',
    {'Этих лентяев только могила исправит... Погоди! Я знаю, как их проучить.|n|n<Курцель отрывает длинную полоску от своей рубахи и протягивает ее вам.>|n|nДержи, |3-6($R). Приложи ее к останкам этого мерзкого лича и принеси ее Маку в лагерь.|n|nПусть они помучаются угрызениями совести.|n|nБольше они никогда не позволят девушке разгуливать тут в одиночестве!', },
    {'Курцель просит вас приложить клочок ее рубахи к трупу Новоса Призывателя, после чего отнести запятнанную лимфой ткань Маку.', },
  },
  [13130] = {
    'Первый камень',
    {'Сейчас Плетхольм – мерзкая яма, кишащая порождениями мрака. Но однажды он станет славной и гордой твердыней. Верховный лорд Фордринг сказал, что назовет ее "Крепость Справедливости".|n|nУвы, строительство даже такой великолепной крепости, как цитадель Ледяной Короны, пришлось начинать когда-то с одного-единственного камня. Вот и нам нужен такой камень.|n|nОтправляйся в лес Хрустальной Песни, который лежит к югу отсюда. На востоке этого леса найди Дикую чащу. В ней собери с земли хрустальную древесину, а в руинах Шандарала найди старую эльфийскую кладку.', },
    {'По заданию архитектора ордена Силаса из Долины Эха добудьте 10 бревен хрустальной древесины и 10 обломков древней эльфийской кладки.', },
  },
  [13131] = {
    'Пустой сундук',
    {'Нет, ты глянь! В моем сундуке шаром покати. Мне бы давно уже следовало наполнить десяток таких сундуков!|n|nМои товарищи прямо взвились при виде такой богатой добычи... и посмотри, что с ними стало теперь! Во что они превратились?! В ходячие скелеты, гремящие костями!|n|nМатушка мне всегда говорила: "Хуже ненайденного сокровища может быть только проклятое сокровище!"|n|nНо я так думаю, там дальше есть еще больше, и то золото уже не проклято, наверняка. Этим пьяницам оно ни к чему – для них это так, бесполезный мусор.|n|nДобудь для меня эти сокровища, а я уж тебя не обижу, отблагодарю, как положено.', },
    {'Принесите Бриггу на вершину Утгард 5 непотускневших серебряных слитков, 3 сверкающих кристалла, 2 золотых кубка и нефритовую статуэтку.', },
  },
  [13132] = {
    'Отмщение',
    {'Да! И я бы не стал их винить, $Gдруг:подруга;. Любой на их месте сделал бы так же.|n|nОни набросились на это золото... думали, что нашли настоящее сокровище... золотые горы, ага... А посмотри, что с ними стало теперь! Во что они превратились?! В безмозглых прислужников, не способных поднять ни единого дублона.|n|nМне, считай, повезло. Только чудом меня миновала такая же злая судьба. Когда все бежали, меня сбили с ног – ну, вообще-то, я сам свалился, если начистоту... был малости подвыпивши, да. А потом я увидел, как первый из них превратился в...|n|nБудь $Gдругом:добра;, найди, кто тут главный, и сделай так, чтобы он поплатился за то, что подсунул моим друзьям проклятое сокровище.', },
    {'Убейте короля Имирона по просьбе Бригга из вершины Утгард.', },
  },
  [13133] = {
    'Поиски древнего героя',
    {'$N, немедленно отправляйся на юго-запад, в Залы Предков!|n|nТам ты найдешь спящих мьординов. Разбуди их и разыщи Искальдера. Потом используй этот амулет и приведи Искальдера ко мне.|n|nСтупай прямо сейчас. Нельзя терять ни минуты!', },
    {'Приведите Искальдера к костяной ведьме в деревню Ньорндар.', },
  },
  [13134] = {
    'Пролитая кровь',
    {'Плеть не может создавать своих мясистых чудовищ без крови и бальзамирующей жидкости, которая консервирует части тел и дает им возможность функционировать. Если лишить их этого сырья, армия Плети скоро начнет разваливаться на части – в буквальном смысле слова, – и мы с легкостью уничтожим их поганые творения.|n|nВ лабораториях, где они создают своих мясистых великанов и поганищ, ты найдешь чаны с бальзамирующей жидкостью и громадные шары, заполненные кровью. Уничтожь их, а если кто-то попытается тебе помешать – убей его на месте!', },
    {'Уничтожьте 5 чанов с бальзамировочным составом и 5 кровавых сфер по просьбе темной всадницы Арли из Черного дозора.', },
  },
  [13135] = {
    'Кристаллы энергии',
    {'На юго-востоке отсюда, на восточных окраинах леса Хрустальной Песни, есть место, известное как Дикая чаща. В этой чаще живут самые разные существа, непохожие друг на друга. Но у них есть одно общее свойство: они все обладают магической энергией. В каждом из них заключен кристаллический источник чистой энергии. Ее там столько, что, если она по какой-то причине дестабилизируется, может произойти такой мощный выброс, что мы все погибнем!|n|nОтправляйся в Дикую чащу, убей нескольких тамошних обитателей и забери у них кристаллы энергии. Нам нужно топливо, а им нужно умереть. Это называется "взаимовыгодный обмен".', },
    {'Принесите 8 источников кристаллизованной энергии инженеру ордена Шпицпатрику в Долину Эха в Ледяной Короне.', },
  },
  [13136] = {
    'Зазубренные осколки',
    {'Вы вынимаете из тела вурдалака обломок какого-то темного ломкого металла. Обломок по краям зазубренный и неровный, что дает основания предположить, что либо его выковал неумелый мастеровой, либо это кусок, отломившийся от какого-то большого клинка.|n|nВы вспоминаете, что вы извлекали похожие куски из тел других вурдалаков в Мясопилке, – и задаетесь вопросом, зачем создатели этих тварей помещают в них куски металла. Может быть, рыцарь Олакин Сайнрит сумеет ответить на этот вопрос, если вы принесете ему еще несколько похожих железяк.', },
    {'Принесите 10 зазубренных осколков рыцарю Олакину Сайнриту в Черный дозор.', },
  },
  [13137] = {
    'Не совсем честный бой',
    {'Из всех вершин, нависающих над Йотунхеймом на юго-западе, ближе всех к облакам вершина Боевого Шрама. Это особое место для врайкулов, ристалище для поединков чести, второе по значимости после Валхаласа.|n|nНо мы отправимся туда не на поединок чести.|n|nСобери свою команду и лети на вершину. Когда будешь $Gготов:готова;, зажги сигнальный огонь, и я вселюсь в тело Искальдера.|n|nМы будем драться, ты победишь, и Вардмадра непременно придет поглядеть на сражение.', },
    {'Одержите победу над Искальдером на вершине Боевого шрама по поручению костяной ведьмы из деревни Ньорндар.', },
  },
  [13138] = {
    'Непонятный металл',
    {'<Олакин перекатывает на бронированной ладони один из осколков.>|n|nТакой может пробить любую броню. Надо выяснить, из чего они сделаны, и что Король-лич собирается с ними делать.|n|nМаликрисс можно найти на востоке, рядом с Цитаделью Ледяной Короны. Из немногих сообщений, дошедших до нас, мы знаем, что там установлено много плавильного и кузнечного оборудования. Отнеси туда эти осколки и расплавь их в одном из горнов на нижнем уровне Маликрисса. Когда металл переплавится и затвердеет, мы сумеем его опознать.', },
    {'Переплавьте мешок зазубренных осколков в одной из кузней Маликрисса. Потом возвращайтесь в Черный дозор и отдайте выплавленный слиток металла рыцарю Олакину Сайнриту.', },
  },
  [13139] = {
    'Ледяное сердце Нордскола',
    {'Доставьте донесение отца Густава верховному лорду Тириону Фордрингу в Оплот Серебряного Авангарда в Ледяной Короне.', },
    {'Доставьте донесение отца Густава верховному лорду Тириону Фордрингу в Оплот Серебряного Авангарда в Ледяной Короне.', },
  },
  [13140] = {
    'Руноковы Маликрисса',
    {'Найденные тобой осколки могут быть только из Маликрисса. Именно там обрабатывают металл для армии Короля-лича. Маликрисс находится на востоке от Корп\'ретара.|n|nУдивительно другое: этот металл не используется ни при создании поганищ и мясистых великанов, ни для призыва скелетов. На самом нижнем уровне Маликрисса ты найдешь скелетов-руноковов. Добудь пластины, над которыми они работают. Надо узнать, зачем этот металл поставляется на Мясопилку.', },
    {'Принесите рыцарю Олакину из Черного дозора 5 рунических саронитовых пластин.', },
  },
  [13141] = {
    'Битва за Вершину Рыцарей',
    {'<Верховный лорд Фордринг держит в руках знамя Серебряного Авангарда.>|n|nЭто не просто знамя, $N. Оно несет на себе благословение и потому способно очищать большие пространства зараженной порчей земли.|n|nОтнеси штандарт через Пролом на северо-запад, в место, которое эти мерзавцы из Плети в насмешку назвали Вершиной Рыцарей. Установи его там, где свалены в кучу черепа наших павших соратников и защити Вершину Рыцарей от нападения. Когда земля будет очищена, возвращайся к отцу Густаву.|n|nПоторопись, $N. И пусть твое сердце не знает страха!', },
    {'Отправляйтесь на Вершину Рыцарей и установите благословенное знамя Авангарда на груде рыцарских черепов. Защищайте знамя от солдат Плети, пока земля на Вершине Рыцарей не очистится от порчи. Затем возвращайтесь к отцу Густаву в Долину Эха в Ледяной Короне.', },
  },
  [13142] = {
    'Месть банши',
    {'Пришло время, $N, тебе и твоим друзьям встретиться лицом к лицу с хозяином цитадели Балагарда, владыкой Йотунхейма, верховным таном Балагардом.|n|nНа вершине крепости, расположенной в юго-западной части Йотунхейма, есть рог. Дунь в него, и твой вызов будет услышан.|n|nБалагарду не останется ничего другого, кроме как выйти с тобой на поединок. А я... прости, но вместо меня пойдет Вардмадра.|n|n<Одержимая банши ведьма издает душераздирающий смех.>', },
    {'Отомстите за костяную ведьму из деревни Ньорндар, бросив вызов верховному тану Балагарду и победив его.', },
  },
  [13143] = {
    'Новобранец',
    {'Начнем с самого главного. Я видел несколько гибких ловцов на крепостных стенах к востоку от нас. До того, как наши пути с Артасом разошлись, они служили мне и были отменными разведчиками… хотя для этого приходилось использовать глаз власти.|n|nСлетай туда, найди кого-нибудь из ловцов, задай ему трепку, а потом покажи эту печать Черного Клинка, и тогда он покорится тебе и будет слушаться беспрекословно. Ловец узнает печать, можешь не сомневаться. Отведи его на вершину скалы к северо-востоку отсюда, и он сам найдет дорогу ко мне.', },
    {'Приведите укрощенного гибкого ловца на вершину скалы к северо-востоку от Высоты Страдания по указанию Верета Хитрого с Высоты Страдания.', },
  },
  [13144] = {
    'Одним скелетом – двух воинов Плети!',
    {'В лаборатории поганищ в Мясопилке уже завершились работы сразу над несколькими созданиями. Пока что их держат прикованными к колоннам по периметру лаборатории, но если мы срочно не примем меры, эти создания выйдут на марш с армией Короля-лича.|n|nЦепкие руки, что тянутся из груд костей, разбросанных по всей Мясопилке – это руки скелетов, наделенных магической силой огня. Разыщи несколько этих скелетов, освободи их и приведи к завершенным поганищам. А потом отойди чуть в сторонку и наслаждайся спектаклем!', },
    {'Уничтожьте 3 прикованных поганищ с помощью пылающих скелетов по поручению темной всадницы Арли из Черного дозора.', },
  },
  [13145] = {
    'Зловещая крепость',
    {'Нам нужно понять, с чем нам придется столкнуться.|n|nРазведай местность, управляя гибким ловцом с помощью глаза власти. Есть несколько мест, которые мне показались особенно подозрительными, удели им особое внимание: дозорное укрепление на северо-востоке, цеха на юго-востоке, большая кузница ближе к центру и площадка для совершения обрядов на юго-западе.|n|nЛовец – отличный прыгун, и не боится глубоких провалов. Это тебе пригодится, чтобы преодолевать крепостные стены.', },
    {'Используйте гибкого ловца для разведки в Маликриссе по поручению Верета Хитрого с Высоты Страдания.', },
  },
  [13146] = {
    'Предсказуемые и тупые',
    {'Нужно посеять неразбериху… все, что угодно, лишь бы отрезать рыцарей смерти от их предводителей. Если мы разделаемся с их приспешниками, думаю, они станут более пристально следить за ходом операции.|n|nПоганища – легкая добыча, они медлительны, предсказуемы и, самое главное, тупы. Воспользуйся их доверием к ловцам, чтобы подтащить к ним побольше бомб Плети, которые разбросаны по всей стройке. Ты успеешь поджечь фитили значительно раньше, чем они сообразят, что происходит.', },
    {'Используйте железную цепь гибкого ловца, чтобы подтащить бомбы Плети к 4 неповоротливым страшилищам внутри Маликрисса.', },
  },
  [13147] = {
    'Сваха',
    {'Основное различие между варгулами и другой мелкой нежитью заключается в том, что у варгулов хватает сообразительности отлынивать от выполнения грязной работы. Ни один варгул не согласиться работать бок о бок со скелетами или вурдалаками.|n|nПредлагаю использовать этот факт и стравить между собой громил из тени и прочую нежить Малакрисса. Производство из-за этого неизбежно замедлится, и у рыцарей смерти начнутся проблемы.|n|nВсе просто: как только кто-то из громил оказывается рядом с другой нежитью, кидаешь в него камнем.', },
    {'По поручению Верета Хитрого с Высоты Страдания с помощью гибкого ловца бросайте камни в громил из тени, когда они оказываются рядом с другой нежитью Маликрисса. Возвращайтесь, когда вам удастся развязать 5 драк.', },
  },
  [13148] = {
    'Починка ожерелья',
    {'На этом сломанном ожерелье выгравирована надпись, которая гласит: "Собственность Тимоти Джонса – Ювелирные изделия, Картье и Ко. – Торговый район – Даларан".|n|nВозможно, вам следует починить его и вернуть владельцу.', },
    {'Почините ожерелье с помощью одного камешка кальцедония и верните его Тимоти Джонсу в его ювелирную мастерскую в Торговую палату волшебников Даларана.', },
  },
  [13149] = {
    'Развеянные иллюзии',
    {'Вечно они вмешиваются...|n|nПроклятые драконы Бесконечности снова хотят нарушить ход истории, пытаясь предотвратить предательство принца Артаса.|n|nЕсли они смогут убедить его, что зерно не заражено чумой, то он не примет рокового решения уничтожить Стратхольм.|n|nНельзя этого допустить!|n|nКак только увидишь ящик с зерном, воспользуйся Разбивателем Чар, чтобы открыть его истинную сущность. Когда закончишь, найди меня у входа в Стратхольм – это к северу отсюда.', },
    {'Хроми попросила вас снять маскировку с подозрительных ящиков с зерном с помощью Разбивателя Чар, после чего найти ее у входа в Стратхольм.', },
  },
  [13150] = {
    'zzOLDПотерянное устройство',
    {'К обратной стороне устройства прикреплена записка, из которой следует, что его владельцем является некий Тимоти Джонс, имеющий ювелирный магазин в некоем квартале Даларана. Пожалуй, он может вознаградить вас, если вы почините и вернете ему прибор.', },
    {'Почините прибор и верните его Тимоти Джонсу в ювелирный магазин Даларана.', },
  },
  [13151] = {
    'Королевский эскорт',
    {'Драконы Бесконечности так просто не сдадутся. К сожалению, я не знаю, что еще они задумали, но что-то подсказывает мне, что мы с ними еще встретимся.|n|nВсего через мгновение Артасу придется принять судьбоносное решение.|n|nНе расслабляйся, $N, ибо на карту поставлено многое. Я прошу тебя сопровождать принца во время очищения Стратхольма. |n|nАртас должен остаться в живых и победить Мал\'Ганиса!', },
    {'Хроми попросила вас сопровождать Артаса во время очищения Стратхольма. Вернитесь к ней, когда Мал\'Ганис будет убит.', },
  },
  [13152] = {
    'Визит к доктору',
    {'Стало быть, эти деятели в Святилище воскрешения решили оснащать вурдалаков осколками саронита? Надо им помешать, пока они не применили этих вурдалаков против наших войск.|n|nРазыщи вход в Святилище воскрешения – это где-то в Мясопилке, рядом с лабораторией мясистых великанов. "Отец-предводитель" вурдалаков, доктор Сабнок, держит там самое грозное и опасное из всех своих созданий, Заплатня. Освободи Заплатня от цепей и помоги ему отомстить доктору за все. Пусть творение само расправляется со своим творцом!', },
    {'По указанию темной всадницы Арли из Черного дозора отправляйтесь в Святилище воскрешения, разрушьте металлическую стойку, к которой прикован Заплатень, и помогите ему отомстить доктору Сабноку.', },
  },
  [13153] = {
    'Охрана для воинов',
    {'$N, рада тебя видеть. Пока в битве наступило затишье, мы должны торопиться и пополнить наши запасы. Проведенные мной исследования показывают, что доспехи солдат, недавно убитых у Ледопадов, накапливают невероятное количество энергии. Орда тоже собирает доспехи в этой области.|n|nОтправляйся к Ледопадам и уничтожь всех бойцов Орды, каких сможешь там обнаружить. Принеси мне их укрепленные доспехи.|n|nЕсли ты не встретишь там никого из Орды, может, наткнешься на доспехи какого-нибудь искателя приключений, сраженного элементалями.', },
    {'Принесите 10 комплектов прочных доспехов Орды из Ледопадов по приказу колдуньи Кайланы из крепости Ледяных Оков.', },
  },
  [13154] = {
    'Кости и стрелы',
    {'Эти драконы просто поразительны! Ну, по крайней мере, их кости! Я снабжал наших лучников наконечниками стрел из драконьей кости. К сожалению, после резни в Ангратаре собирать кости на Драконьем Погосте стало практически невозможно.|n|nНо в лесу Теней, что на западном краю Ледяных Оков, достаточно костей, чтобы пополнить наши запасы.|n|nНаправляйся в лес Теней и принеси любые осколки костей, какие только сможешь найти!|n|nОрда тоже собирает осколки в этом районе. Убей их всех!', },
    {'По просьбе лучника Рандольфа из крепости Ледяных Оков отыщите 10 колчанов со стрелами из драконьих костей в лесу Теней.', },
  },
  [13155] = {
    'Верет Хитрый',
    {'До меня уже доходили слухи про Маликрисс и про то, что Артас учредил новый орден рыцарей смерти, но я думал, что это так... баловство... чтобы заполнить пустое место. Но судя по этим цифрам, он нацелился на что-то большее.|n|nНе так давно мы отправили в Маликрисс нашего лучшего разведчика – Верета Хитрого. Ты найдешь его на Высоте Страдания, к западу от Маликрисса, во Дворе Костей.|n|nПостарайся проникнуть туда незаметно, не привлекая излишнего внимания.', },
    {'Разыщите Верета Хитрого на Высоте Страдания в Ледяной Короне.', },
  },
  [13156] = {
    'Редкое растение',
    {'Ух, ну и холодно же здесь! Напоминает мне штормовые вершины Каариноса на Аргусе. Меж тем, со всем этим снегом и льдом наши солдаты могут легко подхватить простуду.|n|nОтправляйся в степь Жизни, что в юго-западной части Ледяных Оков, и принеси мне 10 стелящихся красных растений. Я измельчу их и сделаю лекарство, которое поможет защититься от простуды.|n|nОрда тоже занимается сбором трав в этих краях. Не стесняйся, убивай их и забирай траву!', },
    {'Отберите по просьбе анахорета Тессы из крепости Ледяных Оков 10 сумок Орды с травами у ордынских игроков в степях Жизни.', },
  },
  [13157] = {
    'Вершина Рыцарей',
    {'Тебе есть чем гордиться. Ты $Gпомог:помогла; нам упрочить положение Серебряного Авангарда в стенах Ледяной Короны, $N. Но теперь Король-лич со своими погаными приспешниками угрожает Вершине Рыцарей напрямую.|n|nВерховный лорд Фордринг и уцелевшие рыцари ждут тебя на Вершине Рыцарей. Тебе нужно снова пройти через Пролом и разыскать верховного лорда Фордринга.', },
    {'Разыщите верховного лорда Тириона Фордринга на Вершине Рыцарей в Ледяной Короне.', },
  },
  [13158] = {
    'Главное – скрытность',
    {'Послушай меня, |3-6($R).|n|nЯ только что узнал, что в Аметистовой крепости произошел один инцидент. Оказывается, синие драконы планируют масштабную атаку на Даларан!|n|nМне нужно, чтобы ты немедленно $Gотправился:отправилась; в тюрьму и $Gпоговорил:поговорила; с тюремщиком Альтурасом. Он посвятит тебя в детали.|n|nЭто еще не все. Я хочу, чтобы ты $Gдействовал:действовала; очень осторожно. Незачем попусту тревожить жителей Даларана, особенно, если этой тревоги можно избежать. Я понятно выразился?|n|nОтлично. А теперь ступай!', },
    {'Отправляйтесь в Аметистовую крепость в Даларане и поговорите с тюремщиком Альтурасом по поручению Ронина.', },
  },
  [13159] = {
    'Сдерживание',
    {'Вот ключ от тюрьмы.|n|nМы станем здесь в качестве последней линии обороны в том случае, если вы не сможете сдержать силы нападающих.|n|nТоропись, |3-6($R). Времени мало. Те несколько воинов, что я оставил внутри, не продержатся долго.|n|nОбязательно поговори с лейтенантом Синклари. Она даст вам доступ к системе защиты тюрьмы.|n|nЯ буду ждать твоего доклада о том, что силы нападающих были успешно истреблены.', },
    {'Проникните по заданию тюремщика Альтураса в Аметистовую крепость и покончите с атакующими силами синих драконов. Вернитесь к нему с докладом, когда Синигоса будет повержена.', },
  },
  [13160] = {
    'Сногсшибательное зрелище',
    {'Из горгулий получаются замечательные разведчики, к тому же они могут наносить смертоносные удары с воздуха. Но у них есть очевидные слабые стороны. Большинству горгулий приходится подолгу отдыхать, накапливая энергию для дальнейших полетов. В такие периоды они остаются неподвижными, как камень.|n|nЧерез око, которым ты пользуешься, я увидел на восточной и южной стенах десятки караульных ледошкуров. Ловец поможет тебе добраться до них, а ты уничтожишь их во сне.', },
    {'По поручению Верета Хитрого с Высоты Страдания с помощью гибкого ловца поднимитесь к караульным ледошкурам и убейте 12 из них.', },
  },
  [13161] = {
    'Всадник Нечестивости',
    {'Пришло время рубить ему головы, этому зверю.|n|nЯ довольно долго служил вместе с Рокиром. Он овладел нечестивыми искусствами лучше, чем подавляющее большинство остальных рыцарей смерти, которых я знал. И, подобно всем рыцарям смерти, он не знает жалости. Не надейся, что он будет легким противником.|n|nКогда Рокир сражается на своей территории, его могущество возрастает. Увы, выбора у нас нет; однако постарайся остаться на ногах и не поддаться натиску нежити – тогда, быть может, тебе удастся победить. |n|nДействуй быстро и ловко, |3-6($C), и не забывай: Рокир хитер и жесток.', },
    {'Убейте Рокира, всадника Нечестивости, по поручению Верета Хитрого с Высоты Страдания.', },
  },
  [13162] = {
    'Всадник Льда',
    {'Сапф... Сапф, она хоть и женщина, но среди рыцарей смерти ей нет равных. Она очарует тебя медоточивыми речами, и ты поклянешься чем угодно, что в ее сердце нет зла, а потом она просто пронзит тебя чем-нибудь острым, по-прежнему улыбаясь своей лучезарной улыбкой. Не дай ей себя обмануть.|n|nНе сомневаюсь, у тебя хватит сил одолеть Сапф; но помни – излишняя самоуверенность может тебя погубить. Сила Сапф в том, что она обманывает своих будущих жертв, притворяясь слабой, а затем обрушивает на них всю мощь ледяных атак. |n|nНе расслабляйся. Повторяю: стоит недооценить ее силы, и ты погибнешь.', },
    {'Убейте Сапф, всадника Льда, по поручению Верета Хитрого с Высоты Страдания.', },
  },
  [13163] = {
    'Всадник Крови',
    {'Насколько мне известно, Бэлок – один из немногих врайкулов, которым удалось сделать карьеру. В основном, благодаря своей крайней жестокости, нежели сколько-нибудь выдающимся заслугам. Если он будет повержен, а еще лучше – мертв, то у тебя станет на одного противника меньше. А это, знаешь ли, не так плохо.|n|nКогда ты вступишь с ним в бой, старайся не приближаться к нему и держаться в стороне от своих спутников. Он воспользуется любой возможностью, чтобы лишить тебя жизненной силы: постарайся не допустить этого.|n|nЯ верю в тебя. Надеюсь, ты принесешь мне вести о его смерти.', },
    {'Убейте Бэлока, всадника Крови, по поручению Верета Хитрого с Высоты Страдания.', },
  },
  [13164] = {
    'Судьба Кровопорча',
    {'Теперь, когда всадники воинства Страдания мертвы, пришло время разделаться с их предводителем – Орбазом Кровопорчем.|n|nПока тебя не было, нас нагнал Могрейн. Он нашел место, где прячется Орбаз. Под цитаделью Ледяной Короны располагается глубокая шахта – там ты и найдешь Орбаза, прямо у входа.|n|nНесколько лучших воинов Черного Клинка уже отправились к шахте, так что возьми кого-нибудь себе в помощь и присоединяйся к нашим. Пусть Кровопорч умрет!', },
    {'Убейте Орбаза Кровопорча по поручению Верета с Высоты Страдания.', },
  },
  [13165] = {
    'Возвращение в Акерус',
    {'Туман развеялся. Теперь я четко вижу, что мы должны делать. Как и в тот день, когда я пронзил Испепелителем собственное сердце, чтобы освободить проклятую душу моего отца... тогда я тоже знал, на что иду.|n|nЕсли мы хотим, чтобы наш союз устоял перед грядущими переменами, мы должны отвоевать Акерус у Плети. Теперь ты знаешь, как открывать врата смерти – я сам учил тебя этому. Они перенесут тебя в Черный оплот, когда пожелаешь. Не медли, $N. Я буду ждать тебя в Акерусе. Грядет первая битва Рыцарей Черного Клинка, и Плеть будет уничтожена!', },
    {'Воспользуйтесь заклинанием Врат смерти, чтобы вернуться в Акерус: Черный оплот, и найдите там верховного лорда Дариона Могрейна.', },
  },
  [13166] = {
    'Битва за Черный оплот',
    {'Мы отвоевали Зал Властности, но Король-лич оставил нам маленький подарок в самом Сердце Акеруса. Там, по второму этажу бродят толпы поганищ, возглавляемых этим гнусным чучелом, Лоскутиком.|n|nВоспользуйся телепортом и уничтожь оставшиеся войска Плети на втором этаже. Только не пытайся сразиться с Лоскутиком в одиночку! Одолеть его можно только объединившись с прочими рыцарями смерти Акеруса. |n|nИди же, $N, и пусть моя вера придаст тебе сил.', },
    {'Убейте 10 солдат Плети и помогите одолеть Лоскутика, после чего вернитесь к верховному лорду Дариону Могрейну.', },
  },
  [13167] = {
    'Смерть королю-предателю!',
    {'Ануб\'арак, король-предатель, обитает в некогда славном подземном королевстве Азжол-Неруб.|n|nСовершив свое предательство, он превратил нашу родину в тот жалкий край, по которому мы сейчас ступаем. Он правит армией нерубов-нежити, которые, как и их лидер, поклялись в верности Королю-личу.|n|nПокончи с правлением короля-предателя, |3-6($C). Ты окажешь величайшую услугу обоим нашим народам.|n|nЕсли ты добьешься успеха там, где все прочие потерпели поражение, принеси мне панцирь Ануб\'арака.', },
    {'Одержите победу над Ануб\'араком из Азжол-Неруба и принесите Киликсу Разрушителю в Провал Наржуна разбитый панцирь Ануб\'арака.', },
  },
  [13168] = {
    'Простой урок',
    {'Смотри-ка... Это глаза власти. Служители Культа делают все, чтобы сохранить эти предметы. Но думаю, у них будет мало шансов, когда мы нападем на них прямо у них дома.|n|nГлаза власти позволяют управлять нежитью. Как ты понимаешь, было бы здорово получить контроль над всеми этими неуклюжими вурдалаками и скелетами.|n|nХочешь попробовать? Используй глаз власти, чтобы управлять пойманным духом.', },
    {'По заданию Керитоза Кровавого Клинка из Мрачного Свода возьмите под свой контроль пойманного эйдолонского наблюдателя, используя глаз власти.', },
  },
  [13169] = {
    'Лучший друг нежити',
    {'Нежить, заправляющая добычей саронита на юго-западе отсюда, морит голодом местных чумных псов, чтобы они были еще злее. Подкрадись к ним, используя маскировку, и покорми нескольких псов. Я уверен, что они либо тут же оставят тебя в покое, либо вовсе решат присоединиться к тому, кто дал им еду.|n|nТолько пока не накормишь их, близко не подходи: твоя маскировка не обманет их чутье.', },
    {'По просьбе Керитоза Кровавого Клинка из Мрачного Свода накормите с помощью эйдолонского наблюдателя 18 проголодавшихся чумных псов.', },
  },
  [13170] = {
    'Честь – удел слабых',
    {'Вурдалаки, вообще-то, достаточно хрупкие и нежные существа, и дозорные на юго-западных разработках саронита – не исключение. Использовав одну из теней, ты без труда сможешь пробраться туда и бесшумно убрать дозорных одного за другим.|n|nПрикончи как можно больше дозорных. Время у тебя будет, но не много... нужно, чтобы к нашей атаке их ряды поредели как следует.', },
    {'Убейте 20 неутомимых дозорных по поручению Керитоза Кровавого Клинка из Мрачного Свода.', },
  },
  [13171] = {
    'Откуда придет удар',
    {'Больше всего меня беспокоит саронитовый карьер на юго-западе отсюда. Там добывают такое невероятное количество руды, что я не представляю даже, что они собираются из нее делать. Но узнать это не так просто. Начнем с того, что ослабим их оборону.|n|nЯ заметил, что по всей базе разбросаны какие-то кристаллы. Думаю, они как раз служат для охраны. Ну, примерно, как зиккураты. Найди несколько таких кристаллов и уничтожь их с помощью эйдолонского наблюдателя.', },
    {'По заданию Керитоза Кровавого Клинка из Мрачного Свода уничтожьте 10 сдерживающих кристаллов Плети.', },
  },
  [13172] = {
    'Семена Хаоса',
    {'Полезная вещь, не правда ли? Тебе отлично удалось ослабить их оборону, |3-6($C). Теперь мы можем отправить в наступление основные силы.|n|nПлан прост: мы уничтожаем все, что движется, прорываемся вовнутрь и, пользуясь всеобщим замешательством, похищаем нужную информацию.|n|nСкажешь, когда будешь $Gготов:готова;. Я дам тебе грифона-скелета.', },
    {'По указанию Керитоза Кровавого Клинка из Мрачного Свода уничтожьте 80 солдат нежити в Саронитовом карьере. Попросите у него грифона-скелета.', },
  },
  [13173] = {
    'Под шумок',
    {'Нам удалось прибрать к рукам довольно много рабочих.Они отлично подойдут.|n|nЯ прошу тебя использовать глаз, чтобы привести одного из этих рабочих обратно в карьер. Сейчас, когда в лагере суматоха и неразбериха, они ни за что не отличат тебя от любого другого рабочего из тех, что разбежались во время нападения.|n|nНайди главного и приступай к работе. Если повезет, мы быстро выясним, куда они отправляют саронит. Я буду наблюдать за тобой через глаз.', },
    nil,
  },
  [13174] = {
    'Под шумок',
    {'Помешать осуществлению их проектов – это лишь часть нашего плана. Еще одна важная задача: выяснить, куда они отправляют столько саронита. Мы уже знаем несколько пунктов назначения, но его добывают в таких количествах, что вывод напрашивается сам собой: где-то ведутся работы над каким-то масштабным проектом.|n|nОтправляйся в карьер и попробуй добыть хоть какие-то сведения. Принеси мне все бумаги, какие найдешь. Если полетишь туда на грифоне, то можешь спешиться, как только покончишь с грязной работой.', },
    {'Принесите документ из Саронитового карьера, гроссбух Саронитового карьера, карту Саронитового карьера и расписание работ в Саронитовом карьере Керитозу Кровавому Клинку в Мрачный Свод.', },
  },
  [13175] = {
    'Восстановление контроля',
    nil,
    nil,
  },
  [13176] = {
    'Подготовка к доставке',
    nil,
    nil,
  },
  [13177] = {
    'Беспощадным пощады не будет',
    {'Добро пожаловать в крепость Ледяных Оков, $N. Твое задание будет очень простым. Одержи победу над десятью представителями Орды. А теперь ступай! Принеси победу Альянсу!', },
    {'Убейте 10 игроков Орды по приказу командира Заннета из крепости Ледяных Оков.', },
  },
  [13178] = {
    'Убить всех и каждого!',
    {'Добро пожаловать в крепость Ледяных Оков, $N. Вождь Гаррош требует лишь одного: убить их всех!|n|nВозвращайся ко мне, когда десять самых сильных воинов Альянса будут мертвы.', },
    {'Убейте 10 игроков Альянса по приказу командира Дардоша с Озера Ледяных Оков.', },
  },
  [13179] = {
    'Беспощадным пощады не будет',
    {'Добро пожаловать в крепость Ледяных Оков, $N. Твое задание будет очень простым. Одержи победу над десятью представителями Орды. А теперь ступай! Принеси победу Альянсу!', },
    {'Убейте 10 игроков Орды по приказу командира Заннета с Озера Ледяных Оков.', },
  },
  [13180] = {
    'Убить всех и каждого!',
    {'Добро пожаловать в крепость Ледяных Оков, $N. Вождь Гаррош требует лишь одного: убить их всех!|n|nВозвращайся ко мне, когда десять самых сильных воинов Альянса будут мертвы.', },
    {'Убейте 10 игроков Альянса по приказу командира Дардоша с Озера Ледяных Оков.', },
  },
  [13181] = {
    'Победа на Озере Ледяных Оков',
    {'Командир Заннет, должно быть, очень доволен видом груды ордынских тел у его ног, но контроль над Озером Ледяных Оков – приоритетная задача экспедиции Отважных. Сделай все возможное, чтобы эта территория оставалась нашей.|n|nНе думай, что союзники сделают за тебя всю грязную работу. Если к концу битвы не станешь рекрутом хотя бы второго уровня, можешь не возвращаться.', },
    {'Выиграйте битву на Озере Ледяных Оков и вернитесь к офицеру-стратегу Абрамису. Необходимо принять участие в битве, чтобы выиграть ее.', },
  },
  [13182] = {
    'И не забудь про яйца!',
    {'По всему Азжол-Нерубу порабощенные Плетью нерубы заботятся о яйцах, из которых вскоре должно появиться на свет их потомство, пополнив их и без того огромную армию.|n|nСкверно получится, если мы уничтожим наводнившую пещеры нежить, а эти скверные яйца останутся дозревать. Тогда новые орды займут место павших.|n|nЕсли ты направишься в ту область, что когда-то была известна как Азжол-Неруб, обязательно избавь наш древний дом ото всех яиц Плети, что встретятся тебе на пути.', },
    {'Проникните в Азжол-Неруб по просьбе Киликса Разрушителя из Провала Наржуна и уничтожьте 6 нерубских яиц Плети.', },
  },
  [13183] = {
    'Победа на Озере Ледяных Оков',
    {'Хотя Дардош весьма успешно справляется с уничтожением наших врагов, более важным для нас является контроль над крепостью Ледяных Оков. Сделай все, что потребуется, чтобы она принадлежала нам. Не думай, что союзники сделают за тебя всю грязную работу. Если к концу битвы не станешь рекрутом хотя бы второго уровня, можешь не возвращаться.', },
    {'Выиграйте битву на поле боя Озера Ледяных Оков и вернитесь к офицеру-стратегу Килрату в крепость Ледяных Оков. Необходимо принять участие в битве, чтобы выиграть ее.', },
  },
  [13184] = {
    'Больше нет нужды',
    nil,
    nil,
  },
  [13185] = {
    'Остановка осады',
    {'Я слышать их! Альянс скоро прийти. Уничтожь три осадных машины Альянса и возвращайся к Мурпу.', },
    {'Уничтожьте 3 осадных машины Альянса по приказу лейтенанта Мурпа из крепости Ледяных Оков.', },
  },
  [13186] = {
    'Остановка осады',
    {'Рано или поздно крепость будет осаждена силами Орды. Уничтожь три их осадных машины и возвращайся ко мне.', },
    {'Уничтожьте по приказу главного подрывника Легосо из крепости Ледяных Оков 3 осадных машины Орды.', },
  },
  [13187] = {
    'Безликие',
    {'Пытаясь избежать столкновения с силами нежити, мой народ копал все глубже и глубже, во всех смыслах теряя почву под ногами. В своем отчаянии они закопались слишком глубоко.|n|nМы случайно обнаружили щупальца воли Древнего Бога, воплощенной в созданиях, известных под названием безликих.|n|nВ конечном счете, мы не смогли драться на два фронта против столь могущественных врагов. Наша печальная судьба стоила нам проигранной войны против нежити и, в конце концов, нашего дома.|n|nВступи в Ан\'кахет, |3-6($C), и очисти наш бывший дом от этих ужасных безликих.', },
    {'Убейте глашатая Волажа из Ан\'кахета и трех позабытых, по просьбе Киликса Разрушителя из Провала Наржуна.', },
  },
  [13188] = {
    'Шаги короля',
    {'Ты, $N, отныне и навсегда нарекаешься рыцарем Черного Клинка. Но не забывай о том, что когда-то ты $Gсражался:сражалась; за Альянс.|n|nЕсли мы хотим победить, нам необходимо обрести союзников. Я назначаю тебя представителем рыцарей Черного Клинка в Альянсе. |n|nНа платформе к юго-востоку отсюда есть портал, который ведет напрямую в Штормград. Возьми с собой это письмо, написанное самим лордом Фордрингом, и отдай его самому королю Вариану Ринну. Иди же!', },
    {'Отнесите письмо в Штормград и отдайте королю Вариану Ринну.', },
  },
  [13189] = {
    'Благословение вождя',
    {'Ты, $N, отныне и навсегда нарекаешься рыцарем Черного Клинка. Но не забывай о том, что когда-то ты $Gсражался:сражалась; за Орду.|n|nЕсли мы хотим победить, нам необходимо обрести союзников. Я назначаю тебя представителем рыцарей Черного Клинка в Орде. |n|nНа платформе к юго-востоку отсюда есть портал, который ведет напрямую в Оргриммар. Возьми с собой это письмо, написанное самим лордом Фордрингом, и отдай его самому Траллу. Иди же!', },
    {'Отнесите письмо в Оргриммар и отдайте Траллу, вождю Орды.', },
  },
  [13190] = {
    'Все хорошо в свое время',
    {'Ан\'кахет, откуда мы пришли…|n|nОднажды, я верю, мы победим смерть и тьму, что окутали нашу древнюю родину. Чтобы это свершилось, у меня есть план, как ослабить защиту наших врагов.|n|nИх драгоценнейшие наблюдатели должны быть сожжены!|n|nСобери их трупы и сложи на жаровню в глубине этого города. Запах их горящих останков наполнит воздух, напоминая наших врагам об их слабости.|n|nНе забывай, |3-6($C)! У них тела нежити – они весьма недолговечны и разрушаются очень быстро.', },
    {'Заполучите труп наблюдателя Ан\'кахара по поручению Киликса Разрушителя из Провала Наржуна и поместите его на ан\'кахетскую жаровню в Ан\'кахете.|n|nЭто задание может быть выполнено только на героическом уровне сложности.', },
  },
  [13191] = {
    'Горючее для разрушителей',
    {'Лок\'тар, $N! Пусть, может быть, битва затихла, но мы должны быть готовы к следующей атаке Альянса! Отправляйся в Огненную котловину, что в юго-восточной части Ледяных Оков, и добудь десять неугасимых угольков.|n|nЭти угольки, смешанные с обычным углем, служат отличным топливом для разрушителей и осадных машин. |n|nСудя по донесениям, эти свиньи из Альянса собирают вечные угольки целые дни напролет. Убей их и забери у них все! Если они уже покинули это место, будь $Gготов:готова; драться с огненными элементалями, пока не соберешь сколько нужно!', },
    {'Соберите 10 неугасимых угольков с тел воинов Альянса в Огненной котловине по приказу осадного кузнеца Могучее Копыто из крепости Ледяных Оков.', },
  },
  [13192] = {
    'Охрана стен',
    {'Привет, $Gбратишка:сестренка;. Это место может любого ввергнуть в глубокую депрессию, меня так уж точно, а тебя?|n|nСлишком уж здесь обитает много духов. Я бы хотел поставить тут колдовских стражей худу, но мне нужно несколько душ, $Gбратишка:сестренка;. И не просто душ, а душ сильных воинов.|n|nУ Ледопадов в восточной части Озера Ледяных Оков есть все подходящие условия для извлечения душ. Убивай там представителей Альянса – может быть, у них окажется то, что нам нужно.|n|nПринеси мне куски доспехов убитых врагов. Если там не окажется Альянса, может быть, они найдутся у элементалей, $Gбратишка:сестренка;.', },
    {'Отправляйтесь к Ледопадам и заполучи 10 зачарованных доспехов Альянса по просьбе мастера худу Фу\'джина из крепости Ледяных Оков.', },
  },
  [13193] = {
    'Кости и стрелы',
    {'И почему они отправили меня снаряжать наших лучников? Я был поэтом, а не рейнджером! Ну, что толку жаловаться. $N, мне требуется кость дракона для изготовления наконечников для стрел.|n|nОтправляйся в лес Теней, что в западной части Озера Ледяных Оков. Со времени последней заварушки Альянс собирает там кости драконов. Убей их и отбери у них кости.|n|nЕсли не получится найти там Альянс, может быть, тебе повезет, и ты добудешь кости у обитающих там духов. Я слышал, они любят насаживать на такие кости своих еще живых жертв.', },
    {'Раздобудьте 10 колчанов со стрелами из драконьих костей у игроков Альянса в лесу Теней по просьбе лейтенанта Виерона Огненного Пера из крепости Ледяных Оков.', },
  },
  [13194] = {
    'Целительные розы',
    {'В затишье меж битвами могучий духом может поверить в том, что есть еще надежда на мир на этой земле. Увы, наша судьба не такова.|n|nОтправляйся в степь Жизни, в юго-западную часть Озера Ледяных Оков. Мне нужны растущие там розы для изготовления бальзама, исцеляющего раненых.|n|nК сожалению, роз стало маловато, потому что Альянс собирает их слишком быстро. Убей бойцов Альянса в степи Жизни и собери сумки с травами с их тел.|n|nЕсли же это тебе не удастся, может быть, сможешь найти несколько цветущих корнехлестов.', },
    {'Отнимите 10 сумок с травами у игроков Альянса в степи Жизни по просьбе идолопоклонника Мулфорта.', },
  },
  [13195] = {
    'Редкое растение',
    {'Ух, ну и холодно же здесь! Напоминает мне штормовые вершины Каариноса на Аргусе. Меж тем, со всем этим снегом и льдом наши солдаты могут легко подхватить простуду.|n|nОтправляйся в степь Жизни, что в юго-западной части Ледяных Оков, и принеси мне 10 сумок Орды с травами. Я измельчу их и сделаю лекарство, которое поможет защититься от простуды.|n|nОрда тоже занимается сбором трав в этих краях. Не робей, убивай врагов и забирай то, что они успели насобирать!|n|nТакже нужные травы можно найти у обитающих там плеточников.', },
    {'Принесите анахорету Тессе 10 сумок Орды с травами из степей Жизни.', },
  },
  [13196] = {
    'Кости и стрелы',
    {'Эти драконы просто поразительны! Ну, по крайней мере, их кости! Я снабжал наших лучников наконечниками стрел из драконьей кости. К сожалению, после резни в Ангратаре собирать кости на Драконьем Погосте стало практически невозможно.|n|nНо в лесу Теней, что на западном краю Ледяных Оков, достаточно костей, чтобы пополнить наши запасы.|n|nНаправляйся в лес Теней и принеси любые осколки костей, какие только сможешь найти!|n|nОрда тоже собирает осколки в этом районе. Убей их всех!', },
    {'По просьбе лучника Рандольфа из крепости Ледяных Оков отыщите 10 колчанов со стрелами из драконьих костей у игроков Орды в лесу Теней.', },
  },
  [13197] = {
    'Горючее для разрушителей',
    {'$N! Ты как раз вовремя! Может быть, мы и проиграли последнюю битву, но нам уже надо готовиться к следующей! Отправляйся к Огненной котловине в юго-восточной части Озера Ледяных Оков и добудь мне несколько неугасимых угольков.|n|nЭти угольки, смешанные с обычным углем, служат отличным топливом для разрушителей и осадных машин. |n|nО, и если ты вдруг увидишь Орду в Котле, не стесняйся, убивай и забирай у них угольки. Мы должны сделать все возможное, чтобы они не удержали крепость!', },
    {'Осадный кузнец Крепкохват из Крепости Ледяных Оков попросил вас собрать 10 неугасимых угольков с тел воинов Орды в Огненной котловине.', },
  },
  [13198] = {
    'Охрана для воинов',
    {'$N, рад тебя видеть. Мы должны подготовиться к следующей атаке на крепость. Проведенные мной исследования показывают, что доспехи солдат, недавно убитых у Ледопадов, накапливают невероятное количество энергии. Орда тоже собирает доспехи в этой области.|n|nОтправляйся к Ледопадам и уничтожь всех ордынцев, каких только обнаружишь. Принеси мне их укрепленные доспехи.|n|nЕсли ты не встретишь там никого из Орды, может, наткнешься на доспехи какого-нибудь искателя приключений, сраженного элементалями.', },
    {'Принесите 10 комплектов прочных доспехов из Ледопадов по приказу колдуньи Кайланы из крепости Ледяных Оков.', },
  },
  [13199] = {
    'Кости и стрелы',
    {'И почему они отправили меня снаряжать наших лучников? Я был поэтом, а не рейнджером! Ну, что толку жаловаться. $N, мне требуется кость дракона для изготовления наконечников для стрел.|n|nОтправляйся в лес Теней, что в западной части Озера Ледяных Оков. Со времени последней заварушки Альянс собирает там кости драконов. Убей их и отбери у них кости.|n|nЕсли не получится найти там Альянс, может быть, тебе повезет, и ты добудешь кости у обитающих там духов. Я слышал, они любят насаживать на такие кости своих еще живых жертв.', },
    {'Раздобудьте 10 колчанов со стрелами из драконьих костей у игроков Альянса в лесу Теней по просьбе лейтенанта Виерона Огненного Пера из крепости Ледяных Оков.', },
  },
  [13200] = {
    'Горючее для разрушителей',
    {'Лок\'тар, $N! Пусть битва на сей раз и закончена, но мы должны приготовиться к возврату крепости! Отправляйся к Огненной котловине, что в юго-восточной части Озера Ледяных Оков, и добудь десять неугасимых угольков.|n|nЭти угольки, смешанные с обычным углем, служат отличным топливом для разрушителей и осадных машин. |n|nСудя по донесениям, эти свиньи из Альянса собирают угольки целые дни напролет. Убей их и забери у них все! Если они уже покинули это место, будь $Gготов:готова; драться с огненными элементалями, пока не найдешь сколько нужно!', },
    {'Соберите 10 неугасимых угольков с тел воинов Альянса в Огненной котловине по приказу осадного кузнеца Могучее Копыто из крепости Ледяных Оков.', },
  },
  [13201] = {
    'Целительные розы',
    {'В затишье меж битвами могучий духом может поверить в том, что есть еще надежда на мир на этой земле. Увы, наша судьба не такова.|n|nОтправляйся в степь Жизни, в юго-западную часть Озера Ледяных Оков. Мне нужны растущие там розы для изготовления бальзама, исцеляющего раненых.|n|nК сожалению, роз стало маловато, потому что Альянс собирает их слишком быстро. Убей бойцов Альянса в степи Жизни и забери сумки с травами с их тел.|n|nЕсли же это тебе не удастся, может быть, сможешь найти несколько цветущих корнехлестов.', },
    {'Отыщите 10 сумок Альянса с травами в степи Жизни по просьбе идолопоклонника Мулфорта.', },
  },
  [13202] = {
    'Заколдованные стены',
    {'Привет, $Gбратишка:сестренка;. Смотри-ка, проклятый Альянс разместился в своей крепости с комфортом, а?|n|nМне кажется, уж слишком им там комфортно, как считаешь? Я хочу немного околдовать это место, но для этого мне нужны души, $Gбратишка:сестренка;. И не просто обычные души, а души храбрых воинов.|n|nУ Ледопадов в восточной части Озера Ледяных Оков есть все подходящие условия для извлечения душ. Убивай там бойцов Альянса – может быть, у них окажется то, что нам нужно.|n|nПринеси мне доспехи убитых врагов. Если там не окажется Альянса, может быть, доспехи найдутся у элементалей, $Gбратишка:сестренка;.', },
    {'Принесите 10 комплектов зачарованных доспехов Альянса из Ледопадов по просьбе мастера худу Фу\'джина из крепости Ледяных Оков', },
  },
  [13203] = {
    'Подарок Зимнего Покрова',
    nil,
    nil,
  },
  [13204] = {
    'Странные грибочки',
    {'Бесформенный кусок похожей на гриб плесени отваливается от особенно вонючего, покрытого слизью куска плоти пещерного зверя. Пока вы осматриваете отвалившийся кусок, вас просто передергивает от этого невыносимого смрада.|n|nВы удивляетесь про себя – неужели эту штуковину нерубы находят аппетитной? Положив липкую субстанцию к себе в сумку, вы собираетесь это выяснить...', },
    {'Соберите 6 кусков диковинной плесени с диких пещерных зверей в Ан\'кахете и принесите их Киликсу Разрушителю в Провал Наржуна.', },
  },
  [13205] = {
    'Разоружение',
    {'Поверь мне на слово, $Gдружище:подруга;: с врайкульскими топорами лучше близко не знакомиться!|n|nУ меня самого есть парочка шрамов от их клинков – отлично сбалансированных, чудовищно острых и совершенно смертоносных.|n|nДавай-ка, проникни в их крепость и стащи кое-что из врайкульского арсенала. Может быть, нам удастся разобраться, как они куют такое оружие. А может быть, и нет.|n|nВ любом случае – чем меньше у них топоров, тем лучше для нас.', },
    {'Защитник Мордун поручил вам проникнуть в Крепость Утгард и украсть 5 образцов врайкульского оружия.', },
  },
  [13206] = {
    'Разоружение',
    {'Мы должны разобраться, как этим дикарям удается ковать столь острое оружие!|n|nЕсли бы ты только $Gвидел:видела;, как легко они кромсают тела моих солдат своими топорами, ты бы тоже $Gпришел:пришла; в ужас. |n|nОбыщи их крепость и принеси Ансельму любые образцы клинков, которые только сможешь найти.|n|nСмотри, не подведи меня, |3-6($C). Чем больше оружия ты сможешь принести – тем меньше окажется в руках у врайкулов на поле боя.', },
    {'Темный следопыт Марра просит вас украсть в крепости Утгард 5 образцов врайкульского оружия и принести их верховному палачу Ансельму в Лагерь Возмездия.', },
  },
  [13207] = {
    'Чертоги Камня',
    {'Что ж, честно признаться, я удивлен, что в таком месте есть и другие искатели приключений! Так уж получается, что мне не помешала бы компания – в свете того, что ждет впереди.|n|nЕсли мои исследования этих чертогов верны, тут нас ожидают фундаментальные открытия!|n|nЕсли я, предположим, доверю тебе прикрывать себя, можешь присоединиться. Ну, что скажешь, |3-6($C)? Интересное предложение?', },
    {'Примите предложение Бранна Бронзоборода и сопровождайте его, пока он раскрывает тайны, хранящиеся в Чертогах Камня.', },
  },
  [13211] = {
    'Сила очищающего огня',
    {'Плеть использует против нас наших же павших солдат, превращая их в вурдалаков и скелетов или расчленяя их тела и собирая из разных частей поганищ. Мы должны положить этому конец!|n|nНаши солдаты пали, защищая тех, кто остался в живых, и наш долг – избавить их после смерти от столь ужасной участи. К тому же, нам не хотелось бы, чтобы они служили подкреплением вражеским войскам на поле боя. Возьми этот факел с собой, когда пойдешь на Мясопилку, и сожги все трупы, которые найдешь в Святилище воскрешения или в лаборатории поганищ.', },
    {'Рыцарь Олакин Сайнрит из Черного дозора просит сжечь 7 гноящихся трупов с помощью факела Олакина.', },
  },
  [13212] = {
    'Части тела',
    {'Враги захватили рыцаря Олакина, и Серебряный Авангард лишился командующего как раз перед самой атакой на Мясопилку. Для меня-то все рыцари одинаковы, но сами они так не думают.|n|nМне не хотелось бы тратить на это время, но выбора у меня нет. Нашего благородного рыцаря, наверное, уже давно разрубили на мелкие кусочки, чтобы соорудить из них поганищ. Отправляйся в Мясопилку, перебей этих чудовищ, которые сражаются с нашими войсками, и верни части тела Олакина.', },
    {'Принесите туловище Олакина, ноги Олакина, левую руку Олакина и правую руку Олакина темной всаднице Арли в Черный дозор.', },
  },
  [13213] = {
    'Битва при Валхаласе',
    {'Я многое знаю, $N. С тех пор, как ты $Gпобедил:победила; верховного тана Балагарда, произошло кое-что очень важное. Ты $Gнужен:нужна; нам в битве за Валхалас!|n|nПоле боя находится на севере отсюда. А теперь иди вместе со своими друзьями к валь\'кире Джейрвиф. Тебе понадобится помощь друзей в сражениях с противниками, которых предложит валь\'кира.|n|nУдачи.', },
    {'Поговорите с Джейрвиф из Валхаласа.', },
  },
  [13214] = {
    'Битва при Валхаласе: павшие герои',
    {'Есть у меня для тебя один противник, с которым ты точно не справишься.|n|nОчередной отряд самонадеянных чужеземцев попытался напасть на Валхалас. Спеси в них было много, но закончилось все, как обычно.|n|nЕсли ты считаешь себя $Gдостойным:достойной; сражаться плечом к плечу с опытными бойцами, тогда прими и этот вызов.', },
    {'Джейрвиф из Валхаласа передала вам вызов на битву, в которой вам предстоит за один раз одолеть всех шестерых павших героев: Элдрета, Генесса Полдуши, Джадраса, Масуда, Рита и Таллу.|n|nЕсли вам удастся победить, поговорите с Гьоннером Безжалостным, контролирующим южную часть Валхаласа.', },
  },
  [13215] = {
    'Битва при Валхаласе: Кит\'рикс Темный Повелитель',
    {'Многие хотят доказать, что они достойны сражаться за Валхалас. Некоторые так даже из-под земли вылезают.|n|nВот, например, Кит\'рикс Темный Повелитель.|n|nКит\'рикс пришел из глубин, где правит бал безумие. И вот, он захотел встретиться в бою с кем-нибудь... необычным. Думаю, ты как раз подойдешь.|n|nНу что, ты осмелишься встретиться с нерубским кошмаром, |3-6($R)?', },
    {'Джейрвиф из Валхаласа передала вам вызов от Кит\'рикса Темного Повелителя.|n|nЕсли вам удастся победить, поговорите с Гьоннером Безжалостным, контролирующим южную часть Валхаласа.', },
  },
  [13216] = {
    'Битва при Валхаласе: возвращение Сигрид Дитя Льда',
    {'Твоя давняя соперница, Сигрид Дитя Льда, вернулась. Может, помнишь, как она уступила тебе в дуэли на Диком уступе?|n|nНеважно. Главное, что она это помнит. Она жаждет реванша.|n|nЛично я считаю, что это хорошая возможность еще раз себя показать.|n|nВ общем, решать тебе, $N. Хочешь снова встретиться с Сигрид?', },
    {'Джейрвиф из Валхаласа передала вам вызов от Сигрид Дитя Льда.|n|nЕсли вам удастся победить, поговорите с Гьоннером Безжалостным, контролирующим южную часть Валхаласа.', },
  },
  [13217] = {
    'Битва при Валхаласе: Резчик-по-живому!',
    {'Пока что тебе везет, $N. Но следующее испытание ты едва ли выдержишь.|n|nПредупреждаю: лучше отступить сейчас. Резчик-по-живому – это настоящая гора гнилой плоти, порождение самых извращенных фантазий Короля-лича.|n|nНе представляю, как ты и твои друзья могут справиться с таким чудовищем. Но, как бы то ни было, решать тебе.', },
    {'Джейрвиф из Валхаласа передала вам вызов от Резчика-по-живому.|n|nЕсли вам удастся победить, поговорите с Гьоннером Безжалостным, контролирующим южную часть Валхаласа.', },
  },
  [13218] = {
    'Битва при Валхаласе: тан Смертельный Удар',
    {'Йотунхеймский врайкул заметил твои старания, $N. Сам тан Банахогг заинтересовался тобой и захотел стать твоим следующим противником.|n|nЕсли тебе показалось, что ты едва $Gодолел:одолела; Резчика-по-живому, можешь отправляться домой и забудь о битве с таном. Прозвище тана – Смертельный Удар, и я думаю, ты догадываешься, за что он его получил.|n|nТы принимаешь вызов тана?', },
    {'Джейрвиф из Валхаласа передала вам вызов от тана Банахогга Смертельного Удара.|n|nЕсли вам удастся победить, поговорите с Гьоннером Безжалостным, контролирующим южную часть Валхаласа.', },
  },
  [13219] = {
    'Битва при Валхаласе: последний бой',
    {'Боюсь, как бы твой успех не обернулся для тебя гибелью, $N.|n|n<Если бы валь\'кира не была белой, то она бы побледнела.>|n|nСлух о твоих успехах при Валхаласе дошел и до Цитадели Ледяной Короны, потревожив того, с кем тебе вряд ли захочется встречаться.|n|nСам принц Сандовал спешит сюда. Гьоннер считает, что тебе надо бежать. И я с ним согласна.|n|nТак что ты предпримешь? Он уже в пути. Ты $Gготов:готова; сойтись с кровавым принцем в последнем бою?', },
    {'Джейрвиф из Валхаласа передала вам вызов от принца Сандовала.|n|nЕсли вам удастся победить его, поговорите с Гьоннером Безжалостным, контролирующим южную часть Валхаласа.', },
  },
  [13220] = {
    'Воскрешение Олакина',
    {'У нас не слишком много времени на то, чтобы собрать Олакина. К счастью, Плеть приготовила отличное место, где ты сможешь провернуть эту операцию.|n|nРядом с Мясопилкой находится Святилище воскрешения. Поищи там катушку ниток и хирургический скальпель. Затем положи останки Олакина на большую плиту, находящуюся в центре святилища, и приступай к работе.', },
    {'Найдите катушку ниток и хирургический скальпель, отнесите их в Святилище воскрешения к останкам Олакина и попытайтесь воскресить рыцаря. Затем вернитесь к темной всаднице Арли в Черный дозор.', },
  },
  [13221] = {
    'Я еще жив!',
    {'Свет ко мне милостив. Я до сих пор не погиб в этом ожившем кошмаре, но если мне не удастся отсюда выбраться, приспешники Плети убьют меня, раздерут мое тело на части и используют их для своих "работ".|n|nЯ не могу уйти сам, но с твоей помощью, |3-6($C), мне, может быть, и удастся спастись, и я еще повоюю с силами Плети.|n|nПоможешь мне выбраться, пока мясники Плети меня не нашли?', },
    {'Проводите отца Камароса в безопасное место, а затем сообщите об этом Абсалану Благочестивому на борту "Усмирителя небес".', },
  },
  [13222] = {
    'Защита осадных машин',
    {'Внимание, $N! Мы начинаем атаку на крепость Ледяных Оков. Эти ордынские твари думают, что могут трусливо спрятаться за ее стенами? А вот я так не думаю! Мы покажем им силу гномской технологии и разберем эти стены по кусочкам!|n|nОднако даже самые могущественные осадные машины – ничто без тех, кто ведет их в бой. Защищай одну из осадных машин или управляй ею, пока она не уничтожит три ордынских строения.', },
    {'По приказу главного подрывника Легосо из крепости Ледяных Оков защитите осадную машину или управляйте ею, пока она не уничтожит три строения.|n|nОсадные машины могут изготавливать игроки в звании "рядовой" и выше в гоблинских мастерских.', },
  },
  [13223] = {
    'Защита осадных машин',
    {'Проклятый Альянс не сможет долго удерживать эту крепость. Мурп разломал бы все ее стены, но Мурпу приходится оставаться в лагере. Эх, если бы Мурп мог передавить весь Альянс, который хочет повредить ордынские разрушители.|n|nЭй, ты, $N! Ты пойдешь вместо Мурпа. Защити 3 осадных машины, пока они разрушают постройки Альянса. Альянс не ожидает, что ты будешь защищать разрушители. Покажи Альянсу, какой Мурп умный!', },
    {'Защитите осадную машину или управляйте ею, пока она не уничтожит три строения Альянса по приказу лейтенанта Мурпа из крепости Ледяных Оков.|n|nОсадные машины могут изготавливать лишь имеющие воинские звания игроки Орды в гоблинских мастерских.', },
  },
  [13224] = {
    'Молот Оргрима',
    {'Солдаты Серебряного Авангарда унесли мое истерзанное тело с поля боя на Прорванном фронте. Это была великая битва, |3-6($R). Мой топор пел, захлебываясь кровью подонков из рядов Альянса и Плети.|n|nДолго мне не протянуть, но это будет достойная смерть. Я попрошу тебя передать кое-что от меня.|n|nНаш летательный аппарат под названием "Молот Оргрима" может подняться так высоко, что силам Плети его не достать. Он где-то между Морд\'ретаром и Алдур\'таром.|n|n<Хорк тщетно пытается по-военному отдать честь.>|n|nЛети как можно выше и старайся избегать джаггернаута Альянса под названием "Усмиритель небес". Скажи Корму... скажи ему, что я умер... в бою... в бою за Орду.', },
    {'Найдите покорителя небес Корма Черного Шрама. Он находится на борту "Молота Оргрима", летающего над Ледяной Короной.', },
  },
  [13225] = {
    'Усмиритель небес',
    {'Мы завязли по уши, сражаясь с силами Плети и Орды. От воплей умирающих солдат звенело в ушах. Это была жестокая, беспощадная битва!|n|nВ какой-то момент тело отказалось меня слушаться. Я упал, и меня подобрали рыцари Серебряного Авангарда. Они вынесли меня с Прорванного фронта и доставили сюда. Едва ли я выживу. Ты исполнишь волю умирающего солдата, |3-6($R)? "Усмиритель небес" летает высоко над Ледяной Короной. Там ты и найдешь нашего командира старшего капитана Бартлетта. Скажи ему, что я умер, сражаясь за Альянс.', },
    {'Найдите старшего капитана Джастина Бартлетта. Он находится на борту "Усмирителя небес", патрулирующего Ледяную Корону.', },
  },
  [13226] = {
    'И пришел Судный День!',
    {'Мы не можем одолеть короля-лича порознь. Если мы не объединимся, то поражения не миновать!|n|nУслышь мой призыв, $Gбрат:сестра;! Серебряный Авангард примет любую помощь! Сам верховный лорд Тирион Фордринг ждет тебя на Серебряном аванпосте! Отправляйся в юго-восточную часть Ледяной Короны, там ты и найдешь лорда Фордринга и солдат Серебряного Авангарда.|n|nНе медли, |3-6($C), ибо Судный День настает!', },
    {'Отправляйтесь к верховному лорду Тириону Фордрингу в Оплот Серебряного Авангарда в Ледяной Короне.', },
  },
  [13227] = {
    'И пришел Судный День!',
    {'Мы не можем одолеть короля-лича порознь. Если мы не объединимся, то поражения не миновать!|n|nУслышь мой призыв, $Gбрат:сестра;! Серебряный Авангард примет любую помощь! Сам верховный лорд Тирион Фордринг ждет тебя на Серебряном аванпосте! Отправляйся в юго-восточную часть Ледяной Короны, там ты и найдешь лорда Фордринга и солдат Серебряного Авангарда.|n|nНе медли, |3-6($C), ибо Судный День настает!', },
    {'Отправляйтесь к верховному лорду Тириону Фордрингу в Оплот Серебряного Авангарда в Ледяной Короне.', },
  },
  [13228] = {
    'Прорванный фронт',
    {'Бой? Какой еще бой?! Эти полки производили разведку!|n|nА что там было про Альянс? Ты вообще $Gуверен:уверена;, что он что-то говорил об Альянсе?|n|nПослушай-ка, $N! Мне надо знать, что происходит, причем прямо СЕЙЧАС!|n|nИди и без ответов не возвращайся. Прочеши поля боя – найди выживших, найди следы, хоть что-то найди!', },
    {'По заданию Корма Черного Шрама с "Молота Оргрима" отправляйтесь к Прорванному фронту и, поговорив с умирающим берсерком, узнайте, что там произошло.', },
  },
  [13229] = {
    'Я еще жив!',
    {'Свет ко мне милостив. Я до сих пор не погиб в этом ожившем кошмаре, но если мне не удастся отсюда выбраться, приспешники Плети убьют меня, раздерут мое тело на части и используют их для своих "работ".|n|nЯ не могу уйти сам, но с твоей помощью, |3-6($C), мне, может быть, и удастся спастись, и я еще повоюю с силами Плети.|n|nПоможешь мне выбраться, пока мясники Плети меня не нашли?', },
    {'Проводите отца Камароса в безопасное место и доложите об этом брату Кельтану на борту "Молота Оргрима".', },
  },
  [13230] = {
    'Отомсти за меня!',
    {'Я слышу их, $Gбрат:сестра;...|n|nСтоны раненых воинов Альянса... как будто они насмехаются надо мной...|n|nЗакончи то, что мы начали, |3-6($C). Беспощадно, не зная жалости... никто не должен остаться в живых.|n|nРади... Орды...', },
    {'Добейте 5 умирающих солдат у Прорванного фронта по просьбе умирающего берсерка. Об исполнении доложите покорителю небес Корму Черному Шраму на борту "Молота Оргрима".', },
  },
  [13231] = {
    'Прорванный фронт',
    {'Что?! Нееет! Только не это!|n|nМы же как только ни изощрялись, чтобы сохранить операцию в тайне! Как в Орде про нее узнали?! Ресурсы… живая сила… все пропало? Немыслимо!|n|nВсе наши планы здесь, в Ледяной Короне, основывались на том, что мы захватим ворота раньше Орды. Нужно срочно перегруппироваться и готовить новый штурм.|n|nОтправляйся на поле боя и разыщи уцелевших. Расспроси их, как все было. Возможно, эта трагедия нас кое-чему научит.|n|nИ приготовься к войне на два фронта, $N...', },
    {'Отправляйтесь на Прорванный фронт и расспросите умирающего солдата, после чего возвращайтесь к старшему капитану Джастину Бартлетту на борт "Усмирителя небес".', },
  },
  [13232] = {
    'Прикончи меня!',
    {'Они смеются над нами... даже умирая, они смеются... |n|nПрошу тебя, $Gбрат:милая;... Не допусти, чтобы их издевательский смех стал последним, что я слышу в жизни... |n|nПрикончи меня... избавь от мучений... отправь меня... к Свету.|n|nРазыщи моих умирающих товарищей... добей и их тоже... из милосердия.|n|nЧтобы никто из нас не достался Плети!|n|nПрошу тебя...', },
    {'По просьбе умирающего солдата добейте 5 умирающих солдат у Прорванного фронта и доложите об исполнении старшему капитану Джастину Бартлетту на борту "Усмирителя небес".', },
  },
  [13233] = {
    'Пощады не будет!',
    {'Я говорил серьезно, это не было приступом гнева.|n|nСнова и снова Орда выказывает свое пренебрежение ко всему, что для нас дорого и свято. За преступления против Света они должны заплатить своей жизнью!|n|nВсе они.|n|nТолько представь, насколько светлее станет мир без этих мерзавцев, $N. Насколько легче будет жить нашим потомкам и как глубоко они будут чтить нашу память, зная, что именно нам они обязаны своим спокойствием и счастьем.|n|nА теперь иди, и пусть мечты станут реальностью!', },
    {'По заданию старшего капитана Джастина Бартлетта с борта "Усмирителя Небес" убейте 15 игроков, сражающихся на стороне Орды в Ледяной Короне.', },
  },
  [13234] = {
    'Они заплатят!',
    {'Время пришло!|n|nМы слишком долго терпели этих самодовольных болванов из Альянса! Слишком долго мы сдерживали свое желание очистить мир от отчаявшихся и слабых.|n|nИ теперь мы положим конец нашему унижению! Мы им покажем, что значит страх! Мы принесем честь и славу Орде!|n|nЗдесь, в Ледяной Короне, мы разобьем Альянс!|n|nСтупай, |3-6($C). Выслеживай их. Сломи. Отними у них волю к жизни!', },
    {'Убейте 15 игроков Альянса в Ледяной Короне по поручению покорителя небес Корма Черного Шрама.', },
  },
  [13235] = {
    'Победитель мясистого великана',
    {'Мясопилка разрушена, слуги Короля-лича убиты – ты хорошо $Gпотрудился:потрудилась;! Осталось только уничтожить главное достижение Мясопилки – мясистого великана по имени Тлетворец.|n|nБитва будет не из легких, но Мрачный Свод отправил туда подкрепление, Маргрейва Дакара с отрядом. Тебе надо встретиться с ним на высшей точке западной окраины Мясопилки. Когда будешь $Gготов:готова; начать наступление, дай ему знать, и он поведет свое войско в атаку.', },
    {'Поговорите с Маргрейвом Дакаром на западной оконечности Мясопилки, чтобы напасть на Тлетворца. Когда Тлетворец будет уничтожен, доложите об этом темной всаднице Арли из Черного дозора.', },
  },
  [13236] = {
    'Войско проклятых',
    {'Ты, наверное, гордишься своим могуществом: ну как же, ты громишь эту нежить, давишь кости мертвяков своей машиной…|n|nНо это все пустяки по сравнению с тем могуществом, которое потребовалось, чтобы их создать!|n|nЯ видел, как принц это делал. И могу показать, как это было... если хочешь, конечно.', },
    {'Оживите 100 вурдалаков-прислужников по просьбе Матиаса Нетлера в лагере сопротивления первого легиона.', },
  },
  [13237] = {
    'Тычки и тумаки',
    {'Пока ваш командир отвлекся на врагов из Альянса, мы можем сосредоточиться на основных противниках: Короле-личе и его прислужниках.|n|nЕсли мы еще надеемся взять цитадель, надо, чтобы твои люди контролировали каждые ворота.|n|nТак, будем действовать постепенно. Для начала вернись на поля боя и прорви оборону врага. Узнай, какие у них есть слабые стороны.|n|nЯ жду твоего доклада, |3-6($C).', },
    {'По поручению Кольтиры Ткача Смерти, находящегося на борту "Молота Оргрима", вы должны отправиться на Прорванный фронт и уничтожить 5 неповоротливых поганищ, 5 злокозненных некромантов и 5 адептов Тьмы.', },
  },
  [13238] = {
    'Какая-то полезная штука',
    {'Гоблины! Им вечно неймется! Они, что ли, рождаются с шилом в известном месте...|n|nСлушай, $N, Меднопал, наш местный инженер, очень хочет продемонстрировать мне какую-то штуку. Говорит, это очень полезная вещь.|n|nЯ сейчас не в том настроении, чтобы выслушивать его писклявые разглагольствования. В нашу последнюю встречу он верещал целый час, не умолкая! Я еле сдержался, чтобы не отправить его пинком в Каньон Гибели Сингдрагосы!|n|nСходи к нему вместо меня, хорошо? Пусть он покажет тебе эту "полезную штуку". Если это действительно что-то полезное, дай мне знать.', },
    {'Поговорите с главным инженером Меднопалом на борту "Молота Оргрима" по поручению покорителя небес Корма Черного Шрама.', },
  },
  [13239] = {
    'Непостоянство',
    {'Даже не знаю, с чего начать... ну, ты, наверное, знаешь, что будучи главным инженером этого корабля, я имею неограниченный доступ ко всем данным разведки – да, это правда, и меня очень заинтересовали эти ледяные змеи, которых ты $Gвидел:видела; на юге. Кажется, я придумал, как нам их изничтожить... но мне понадобится твоя помощь. Сооруди манекен из доспехов, обрызгай его этим раствором и сразу беги в укрытие!|n|n...Эй, ты еще здесь, |3-6($R)?', },
    {'Отправляйтесь к Прорванному фронту и воспользуйтесь летучим маслом Меднопала, чтобы привлечь 3 ледяных небесных когтей.|n|nДля того чтобы использовать масло, соберите на поле сражения груду костей, брошенный шлем и брошенную броню.', },
  },
  [13240] = {
    'Времиар превидит встречу с центрифужными созданиями!',
    {'Ты $Gдолжен:должна; отправиться в Окулус, дрейфующий над Хладаррой, $N.|n|nУ меня было видение, в котором ты уничтожаешь находящихся там центрифужных созданий. Уверяю тебя, если ты не нападешь $Gпервым:первой; на эти магические создания, они уничтожат тебя и твоих друзей.|n|nТаким мне явилось будущее – и ты $Gдолжен:должна; прислушаться к моему предчувствию.', },
    {'Исполните волю верховного мага Времиара, обитающего в Даларане, которого посетило видение, где вы уничтожаете 10 центрифужных созданий.', },
  },
  [13241] = {
    'Времиар превидит встречу имирьярскими берсерками!',
    {'Могучие воины короля Имирона в ближайшем будущем встанут на твоем пути к успеху! |n|nТебе следует отправиться в крепость, известную как Вершина Утгард, находящуюся в глубине лесов Ревущего фьорда. Трудно описать, насколько важная задача стоит перед тобой и твоими друзьями. Вы должны уничтожить имирьярских берсерков, вершащих там злые дела.|n|nЕсли вас постигнет неудача, смерть станет вашим наказанием, $N!', },
    {'Уничтожьте по заданию верховного мага Времиара, обитающего в Даларане, 7 имирьярских берсерков.', },
  },
  [13242] = {
    'Шевеление Тьмы',
    {'Тьма зашевелилась, $N. Произошло трагическое событие, которое никто, кроме Вневременного, не мог предвидеть. Скоро твой народ охватит злоба и ненависть. Приближается война.|n|nКрасные драконы сделали все, что было в их силах. Теперь все зависит от смертных рас Азерота.|n|nУвы, твое путешествие начинается со страданий. Сегодня отец потерял свое дитя. Тебе предстоит стать вестником, приносящим скорбные новости. Собери вооружение Саурфанга и отнеси его Саурфангу-старшему.', },
    {'Соберите на поле боя боевые доспехи Саурфанга и верните их верховному правителю Саурфангу в крепость Песни Войны, что в Борейской тундре.', },
  },
  [13243] = {
    'Времиар превидит встречу с посланницами из рода Бесконечности!',
    {'Драконы бесконечности угрожают существованию самого времени. Если ты не помешаешь им, ход времени будет искривлен!|n|nТы $Gдолжен:должна; отправиться в Пещеры Времени и переместиться в прошлое, в период, известный нам как Очищение Стратхольма.|n|nУ меня начинает раскалываться голова даже от попыток просмотреть все вариации прошлого, но я точно знаю, как жизненно важно тебе уничтожить посланниц из рода Бесконечности.|n|nЛишь когда они будут убиты, истинное прошлое будет сохранено, а настоящее и будущее никогда больше не подвергнутся угрозе изменения!', },
    {'Верховный маг Времиар из Даларана предчувствует, что вам необходимо убить 4 посланниц из рода Бесконечности.', },
  },
  [13244] = {
    'Времиар превидит встречу с титановыми воинами!',
    {'Опасность нависла над всем Азеротом. Безумный бог Локен действительно в силах уничтожить все живое!|n|nВ Земной сторожевой башне, что в Чертогах Молний, лучшие титановые воины пытаются исполнить смертоносную волю Локена, грозящую погубить неисчислимое количество жизней.|n|nЯ видел будущее, $N. Ты станешь $Gтем:той;, кто не допустит, чтобы это произошло!', },
    {'Убейте 7 титановых воинов, дабы предсказанное верховным магом Времиаром из Даларана сбылось.', },
  },
  [13245] = {
    'Доказательство смерти: Ингвар Расхититель',
    {'Я хочу, чтобы ты $Gсобрал:собрала; группу и $Gотправился:отправилась; в крепость Утгард. Там тебе предстоит найти и уничтожить Ингвара Расхитителя – прежде, чем он поведет свои войска врайкулов в атаку на ближайшие города Альянса и Орды.|n|nМне потребуется его секира в качестве доказательства того, что с ним покончено. Дело не в том, что я тебе не доверяю. Просто разумно было бы на моем месте убедиться в том, что дело сделано.', },
    {'Принесите секиру Расхитителя верховному магу Лан\'далоку, обитающему в Даларане.|n|nЭто задание выполняется в героическом режиме.', },
  },
  [13246] = {
    'Доказательство смерти: Керистраза',
    {'Известна ли тебе история Керистразы?|n|nКак она помогла убить Сарагосу, супругу Малигоса? Как затем он завладел Керистразой и заморозил ее в глыбе льда?|n|nМы узнали, что он использовал свою магию, чтобы сломить ее волю. Это свело ее с ума.|n|n$N, ты $Gдолжен:должна; отправиться в Нексус, что в Хладарре, и уничтожить ее, прежде, чем она окончательно обезумеет.|n|nЭто печалит меня, но я настаиваю, чтобы ты $Gпринес:принесла; мне ее сердце в качестве доказательства того, что ее больше нет.', },
    {'Принесите в Даларан по заданию кровавого верховного мага Лан\'далока разбитое сердце Керистразы.|n|nЭто задание выполняется в героическом режиме.', },
  },
  [13247] = {
    'Доказательство смерти: хранитель энергии Эрегос',
    {'Война Нексуса продолжает бушевать, $N, и нам нужно что-то предпринять, чтобы изменить ход событий! Хочешь ли ты отправиться в сердце битвы?|n|nХранитель энергии Эрегос охраняет канал, по которому Малигос выкачивает магию из силовых линий Азерота. Если мы сможем уничтожить его, это нанесет сильный удар по нашему врагу.|n|nПожалуйста, принеси мне одно из его устройств для настройки силовых линий, чтобы мы смогли изучить его.', },
    {'Принесите устройство для настройки силовых линий верховному магу Лан\'далоку в Даларан.|n|nЭто задание выполняется в героическом режиме.', },
  },
  [13248] = {
    'Доказательство смерти: король Имирон',
    {'Король Имирон с вершины Утгарда пребывает в милости у Короля-лича. Одной этой причины было бы достаточно для того, чтобы покончить с ним.|n|nНо если он протрубит в рог и созовет всех вождей племен, подобных имирьярам и мьординам, врайкулы станут силой куда более мощной, чем прочие армии Плети!|n|nТы, $N, $Gдолжен:должна; сделать так, чтобы этого никогда не произошло. Принеси мне медальон с его шеи, чтобы я знал, что Имирон больше не представляет для нас угрозы.', },
    {'Принесите медальон Усопшей королевы верховному магу Лан\'далоку в Даларан.|n|nЭто задание выполняется в героическом режиме.', },
  },
  [13249] = {
    'Доказательство смерти: пророк Тарон\'джа',
    {'Крепость Драк\'Тарон когда-то была гордым бастионом Драккари. Теперь это лишь перевалочный пункт для Короля-лича, пытающегося сокрушить Зул\'Драк и завладеть силой тролльих богов.|n|nНо если бы мы уничтожили здешнего предводителя, пророка Тарон\'джа, возможно, мы смогли бы остановить поступления все новых отрядов подкрепления для Плети из числа троллей. По крайней мере, это избавит Серебряный Авангард в Зул\'Драке хотя бы от одной из проблем.|n|nВозвращайся ко мне с его амулетом в качестве доказательства того, что пророк уничтожен.', },
    {'Принесите верховному магу Лан\'далоку в Даларан заколдованный амулет пророка.|n|nЭто задание выполняется в героическом режиме.', },
  },
  [13250] = {
    'Доказательство смерти: Гал\'дара',
    {'Драккарские пророки Зул\'Драка совершили немыслимое: они уничтожили большинство своих богов и завладели их силой! Самый могущественный и опасный среди них – это верховный пророк Акали, Гал\'дара.|n|nУединившийся в недрах Гундрака Гал\'дара впитал в себя практически всю колдовскую силу убитого Акали и теперь хочет извергнуться из города вместе со своими последователями в окружающий мир. Если мы не убьем его сейчас, нас захлестнет море безумной и невообразимой силы!|n|nБыстрее, $N, принеси мне то, что осталось от колдовской силы Акали.', },
    {'Принесите верховному магу Лан\'далоку в Даларан остатки колдунства Акали.|n|nЭто задание выполняется в героическом режиме.', },
  },
  [13251] = {
    'Доказательство смерти: Мал\'Ганис',
    {'$N, один друг из числа бронзовых драконов снабдил меня кое-какой информацией, и мы должны ею воспользоваться.|n|nЗагадочные создания Пылающего Легиона, называемые Повелителями ужаса, известны как раса Натрезим. Немногое мы знаем об их родном мире, и то – одни лишь слухи.|n|nНо известно, что Мал\'Ганис в своем прошлом совершил фатальную ошибку: он потерял артефакт из своего родного мира!|n|nЧерез Пещеры Времени ты $Gдолжен:должна; отправиться назад в прошлое, в период, известный нам как Очищение Стратхольма. Отыщи и принеси мне тот артефакт.', },
    {'Принесите артефакт из родного мира натрезимов верховному магу Лан\'далоку в Даларан.|n|nЭто задание выполняется в героическом режиме.', },
  },
  [13252] = {
    'Доказательство смерти: Сьоннир Литейщик',
    {'Немногое известно о том состоянии, что известно как Проклятие Плоти. Однако в Чертогах Камня хранится кое-какая информация.|n|nСьоннир Литейщик, похоже, знает многое об этом проклятии. Нам достоверно известно, что у него есть диск титанов, содержащий ответ на многие наши вопросы.|n|nПринеси мне этот диск, $N, чтобы мы смогли его изучить.', },
    {'Принесите верховному магу Лан\'далоку в Даларан диск о Проклятии Плоти.|n|nЭто задание выполняется в героическом режиме.', },
  },
  [13253] = {
    'Доказательство смерти: Локен',
    {'Локен, затаившийся в Чертогах Молний, жаждет положить конец всему нашем миру. Нужно ли мне еще что-то говорить, $N?|n|nОн восседает там, слушая безумные нашептывания Древнего Бога, запертого в глубинах под Нордсколом. Ты и твои друзья должны отправиться на Грозовую Гряду немедленно!|n|nБросьте вызов Локену в Земной сторожевой башне и остановите его, пока еще не слишком поздно! Принесите мне его рубиновое кольцо, и я пойму, что мы снова в безопасности.', },
    {'Принесите верховному магу Лан\'далоку в Даларан божественное рубиновое кольцо.|n|nЭто задание выполняется в героическом режиме.', },
  },
  [13254] = {
    'Доказательство смерти: Ануб\'арак',
    {'Порабощенные Плетью нерубы – просто чума для наших армий.|n|nСейчас, дрейфуя над миром, мы пребываем в относительной безопасности, но стоит нам спуститься на землю, как мы начинаем думать лишь о том, что нерубы могут выбраться из глубин Азжол-Неруба и напасть на нас.|n|nХорошо было бы посеять среди них панику. Убей их бывшего короля, ныне – мажордома Короля-лича, владыку склепа Ануб\'арака.|n|nПожалуйста, принеси мне его корону... все равно он ее больше не носит.', },
    {'Принесите бесполезную корону Ануб\'арака верховному магу Лан\'далоку из Даларана.|n|nЭто задание выполняется в героическом режиме.', },
  },
  [13255] = {
    'Доказательство смерти: глашатай Волаж',
    {'Нерубы Ан\'кахета копали слишком глубоко, пытаясь сбежать от наступающих армий Плети. Они подобрались слишком близко к Древнему Богу, влачащему свое существование в глубинах под Нордсколом.|n|nОбнаружив их присутствие, Древний Бог натравил на них своих безумных созданий, и нерубы попали между вошедшими в поговорку молотом и наковальней.|n|nЛидер сил Древнего Бога – глашатай Волаж – одно из кошмарных созданий, известных под именем Безликих. Покончи с ним и принеси мне его усохший мозг.|n|nНо, пожалуйста, постарайся $Gсам:сама; не сойти с ума.', },
    {'Принесите верховному магу Лан\'далоку в Даларан усохший мозг Безликого.|n|nЭто задание выполняется в героическом режиме.', },
  },
  [13256] = {
    'Доказательство смерти: Синигоса',
    {'На нас напали! Синие драконы телепортировались в Аметистовую крепость и теперь планируют вторгнуться оттуда в Даларан!|n|nДо нас уже доходили слухи о заключенных, которые были – якобы случайно – освобождены ими. Я не удивлюсь, если они специально выпускают некоторых из них на волю.|n|n$N, не $Gмог:могла; бы ты как можно быстрее сколотить команду и отправиться туда? Их силы ведет в бой Синигоса. Принеси мне ее голову!', },
    {'Принесите верховному магу Лан\'далоку в Даларан голову Синигосы.|n|nЭто задание выполняется в героическом режиме.', },
  },
  [13257] = {
    'Глашатай войны',
    {'Вождь нуждается в тебе, $Gвоин:воительница;. Оргриммар на военном положении. Торговля, оказание услуг – все теперь свернуто, когда вождь готовится к неизбежному конфликту.|n|nЯ не могу сказать тебе больше – во всяком случае, не сейчас. И не здесь.|n|nВождь приказывает всем самым сильным воинам направиться к нему на доклад в его тронную залу. Ступай, $N! Воспользуйся этим порталом, чтобы вернуться в Оргриммар и встретиться с Траллом.', },
    {'Доложите о своем прибытии Траллу, который находится в крепости Громмаш в Оргриммаре.', },
  },
  [13258] = {
    'Замечательная возможность',
    {'Нам удалось заполучить документы и планы, в которых указано слабое место Цитадели Ледяной Короны. Брешь в их обороне – и в прямом, и в переносном смысле.|n|nНа планах указан какой-то проход, уходящий под землю на несколько сотен футов. Мы не знаем его назначения, но наши разведчики доносят, что этот проход очень важен для Плети.|n|nПоговори с сержантом Креггой под стенами Цитадели Ледяной Короны. Она командует нашими силами, штурмующими цитадель.', },
    {'Поговорите с сержантом Креггой под стенами Цитадели Ледяной Короны.', },
  },
  [13259] = {
    'Закрепить преимущество',
    {'У нас почти все готово, чтобы причинить ощутимый ущерб этому тепленькому местечку, но надо все сделать с умом.|n|nНам удалось раздобыть очень мощные саронитовые бомбы, изготовленные мастерами Плети. Но прежде чем мы их взорвем, нужно зачистить территорию.|n|nВремени мало, нам надо успеть, пока Плеть не прислала сюда подкрепление.|n|nПомоги моим солдатам, а потом возвращайся сюда, и мы устроим фейерверк.', },
    {'Убейте 10 неповоротливых громад по поручению сержанта Крегги, находящегося у Цитадели Ледяной Короны.', },
  },
  [13260] = {
    'Уж кто бы говорил!',
    {'Сражаясь против Альянса, мы не должны забывать и о Плети.|n|nВ ближайшие недели мы еще не сможем начать наступление, но это не значит, что мы не должны изучить оборону противника.|n|nЯ попросил прикрепленного к нашему войску рыцаря смерти дать тебе пару советов. Ведь если подумать, то кто может знать этого врага лучше, чем рыцари смерти?|n|nПозволь представить тебе: Кольтира Ткач Смерти.', },
    {'По заданию покорителя небес Корма поговорите с Кольтирой Ткачом Смерти на борту "Молота Оргрима".', },
  },
  [13261] = {
    'Непостоянство',
    {'Ух ты! Получилось! То есть я ни капельки не сомневался в своей сверхъестественной гениальности и мастерстве, я просто не был уверен, какова будет мощность взрыва – в общем, я рад, что ты не $Gподпалил себе брови:подпалила себе реснички;. А теперь давай-ка покажем старине Корму, как ты подрываешь этих змеев. Он впечатлится и повысит меня до... э... кто там идет после главного инженера? В общем, бери еще пачку этой убойной штуковины и возвращайся на передовую, а я пойду приведу Корма...|n|nНу, чего ты стоишь? Вперед!', },
    {'Отправляйтесь к Прорванному фронту и воспользуйтесь летучим маслом Меднопала, чтобы привлечь 3 ледяных небесных когтей.|n|nДля того чтобы использовать масло, соберите на поле сражения груду костей, брошенный шлем и брошенную броню.', },
  },
  [13262] = {
    'Мощный взрыв',
    {'Кажется, ситуация вышла из-под контроля уже настолько, что дальше некуда. Вот что мы сделаем, $N.|n|nМне нужно, чтобы кто-то поджег фитиль от этих бомб. И, похоже, это будешь ты.', },
    {'Идите к ближайшему штабелю саронитовых бомб и подожгите фитиль.', },
  },
  [13263] = {
    'Фитиль короток!',
    {'Не успев поджечь фитиль, вы обнаруживаете, что он сгорает куда быстрее, чем вы рассчитывали!|n|nБомбы вот-вот рванут. Ваш единственный шанс на спасение – броситься в провал и надеяться, что там не слишком глубоко.', },
    {'Там, куда вы падаете, вас ждет кое-что интересное!', },
  },
  [13264] = {
    'Как все погано!',
    {'Поганища…|n|nОни могут быть очень опасными противниками. Мне не раз доводилось видеть, как именно их вмешательство меняло весь ход битвы. Однако немногие догадываются, что поганища могут быть очень ценными союзниками.|n|nМозгов у них, считай, нет вовсе. И если ты знаешь тайны их создания, то сможешь отдавать им распоряжения, которые они будут выполнять, не задумываясь.|n|nМне этот секрет известен – к твоему счастью.|n|nЭтот набор позволит заново оживлять убитых тобой поганищ. Возьми его и используй поганищ против сил Плети у Врат смерти.', },
    {'Используйте набор для оживления, чтобы воскресить поганище и убить с его помощью 15 ледяных вурдалаков, 15 агрессивных упырей и 15 восставших солдат Альянса по просьбе Кольтиры Ткача Смерти с "Молота Оргрима".', },
  },
  [13265] = {
    'Сбор ткани',
    nil,
    nil,
  },
  [13266] = {
    'Жизнь без сожалений',
    {'В день, когда за мной придет моя смерть, я хотел бы сказать, что жизнь прошла не зря. Те, кто станут оплакивать мою гибель, будут знать, что я был вождем, который принимал решения на благо своего народа.|n|nНо предательство Вариматаса и Гнилесса...Все, над чем мы работали, пошло прахом.|n|n<Тралл тяжело вздыхает.>|n|nПравосудие должно свершиться.|n|nПорталы, ведущие в Подгород, будут немедленно открыты. Вол\'джин будет ждать тебя. Вскоре я присоединюсь к тебе. Вместе мы сделаем то, что нужно сделать, $N.', },
    {'Воспользуйтесь порталом в Подгород, расположенном в крепости Громмаш, и доложите о своем прибытии Вол\'джину.', },
  },
  [13267] = {
    'Битва за Подгород',
    {'Весь Подгород под контролем Вариматаса. Наши солдаты находятся в боевой готовности, ожидая от вождя приказа идти в атаку.|n|nПомоги Орде отвоевать Подгород и встань в один ряд с нашими самыми великими воинами! Если останешься в живых, доложись Траллу.|n|nДай вождю знать, когда будешь $Gготов:готова; вступить в бой.', },
    {'Помогите Траллу и Сильване вернуть Орде контроль над Подгородом.|n|nВ случае успеха отрапортуйте об этом Траллу.', },
  },
  [13268] = {
    'Сбор ткани',
    nil,
    nil,
  },
  [13269] = {
    'Сбор ткани',
    nil,
    nil,
  },
  [13270] = {
    'Сбор ткани',
    nil,
    nil,
  },
  [13271] = {
    'Голос во тьме',
    {'Нет, это не кристалл, это какой-то замороженный орган…|n|nВы прикасаетесь к нему – и руку пронзает немыслимая боль. Такое ощущение, будто руку отрубили напрочь. Но никаких ран на ней не заметно…|n|nПытаясь собраться с мыслями, вы вдруг слышите где-то рядом мальчишеский голос.|n|n"Не стоило тебе этого делать, ой, не стоило!"', },
    {'Выясните, откуда доносится голос, который вы услышали в Наз\'анаке, Забытых глубинах.', },
  },
  [13272] = {
    'Сбор ткани',
    nil,
    nil,
  },
  [13273] = {
    'В поисках ядра',
    {'Теперь, когда оболочка Норганнона у нас в руках, осталось найти вторую половину ключа от архива. По счастью, Лига исследователей немало потрудилась, разыскивая следы ядра Норганнона.|n|nДалеко к юго-востоку от Библиотеки Изобретателя, на склонах к северу от Дун Ниффелема, находится лагерь, который носит мое имя. В этом лагере живут представители Лиги исследователей, которые занимаются поисками второй половины ключа. Принеси мне их карты и записи, и мы сумеем найти то, что ищем.', },
    {'Найдите записи геолога Хроны и записи геолога Сорена в главном лагере Бранна.', },
  },
  [13274] = {
    'Хранитель ядра',
    {'В записках геолога Сорена сказано, что ядро Норганнона хранится у одного из созданий Мимира, стража по имени Атан.|n|nСорен говорит, что подземелье, где обитает Атан, в наше время зовется "Сделка Локена".|n|nЛокен. Любопытно, не правда ли? О нем упоминали земельники.|n|nГоворят, это подземелье находится к юго-западу от разрушенного лагеря Лиги изобретателей, круглый вход в подземелье расположен на склоне горы со стороны долины Древних Зим.|n|nОтыщи этого Атана и отбери у него ядро. Но, думаю, без боя он его не отдаст...', },
    {'Добудьте ядро Норганнона.', },
  },
  [13275] = {
    'Пора прятаться!',
    {'Не стоило тебе трогать эту штуку! Теперь он непременно явится искать тебя.|n|nИ он тебя найдет. Если только ты не сумеешь от него спрятаться.|n|nХочешь выжить – принеси мне кровь безликих!', },
    {'Добудьте 3 образца крови безликих по совету Матиаса Нетлера.', },
  },
  [13276] = {
    'Как все погано!',
    {'Ты знаешь, что делать, |3-6($C).|n|nВозьми этот набор и используй внутренности поганищ, чтобы создать свое собственное, а потом прикажи ему атаковать вражеские силы у врат.|n|nТебе стоит отработать эту тактику к тому времени, как мы пойдем на штурм врат.', },
    {'Используйте набор для оживления, чтобы воскресить поганище и убить с его помощью 15 ледяных вурдалаков, 15 агрессивных упырей и 15 восставших солдат Альянса по просьбе Кольтиры Ткача Смерти с "Молота Оргрима".', },
  },
  [13277] = {
    'Борьба с великанами',
    {'Конечно, очень важно разгромить Плеть на поле битвы, но все-таки не следует пренебрегать и самими воротами.|n|nМясистые великаны, что обороняют укрепления, могут швырять массивные валуны и куски льда, нанося разрушительный урон вражеской пехоте.|n|nСоберись с силами и уничтожь этих великанов. Нам надо знать, насколько они сильны, чтобы предвидеть, с чем предстоит иметь дело.|n|nДа, и кстати, принеси мне их позвоночники. Если память мне не изменяет, с ними можно проделать одну любопытную штуку... Тебя я, конечно, тоже этому научу.', },
    {'Принесите Кольтире Ткачу Смерти на борт "Молота Оргрима" 5 гноящихся позвоночников пустулезных ужасов из Морд\'ретара.', },
  },
  [13278] = {
    'Корпой Оскверненный',
    {'$C, до меня дошли известия о том, что у Врат Смерти появился новый могучий зомби.|n|nМы не можем сидеть сложа руки, когда нам угрожает такой серьезный противник. Любые сведения о нем, какие тебе удастся раздобыть, – лучше, чем ничего.|n|nСтупай в западное караульное помещение у врат и найди это существо. Сразись с ним и отыщи брешь в его защите, которой мы могли бы воспользоваться.', },
    {'Убейте Корпоя Оскверненного из Морд\'ретара по просьбе Кольтиры Ткача Смерти с "Молота Оргрима".', },
  },
  [13279] = {
    'Основы химии',
    {'<Кольтира берет гноящиеся позвоночники и сливает из них жидкость во фляжку.>|n|nМалоизвестное свойство мясистых великанов...|n|nИх спинномозговая жидкость взаимодействует с чумой весьма любопытным образом: на выходе получается очень едкая кислота.|n|nЕсли разлить ее вниз с укреплений, войскам, что внизу, это не понравится, но зато жертвы уже не встанут и не пополнят собой ряды противника.|n|nВылей содержимое этой фляги в один из чумных котлов в западном караульном помещении Врат Смерти.', },
    {'Вылейте пустулезную спинномозговую жидкость в чумной котел в Морд\'ретаре по просьбе Кольтиры Ткача Смерти с борта "Молота Оргрима".', },
  },
  [13280] = {
    'Царь горы',
    {'Короче, $N, мне надо, чтобы ты $Gзагнал:загнала; мой прыгобот на са-амую макушку вон той горы на северо-западе, ясно?|n|nЭтот тупой и самодовольный Бубух Громбабах сейчас работает над своим собственным ботом, и, боюсь, он его почти доделал. Короче, мы договорились о соревновании, кто сумеет стать царем горы!|n|nКак доберешься наверх, воткни наш боевой штандарт в груду костей, чтобы все видели, что Альянс сильнее всех, а я – лучший изобретатель!', },
    {'Используйте прыгобот Зуботески, чтобы установить боевой штандарт Альянса в груде черепов на вершине горы, по просьбе Фраззл Зуботески.', },
  },
  [13281] = {
    'Избавление от чумы',
    {'Тебе больше не нужна моя помощь, чтобы обезвредить чумные котлы врагов, |3-6($R). |n|nУбей мясистых великанов у Врат смерти и используй их спинномозговую жидкость, чтобы нейтрализовать штаммы чумы. |n|nТы нанесешь сокрушительный удар по стратегии врага. Это крайне важное задание – жизненно важное для нашей победы, и его следует исполнить как можно скорее. |n|nПомни: и великанов, и чумные котлы можно найти в Морд\'ретаре.', },
    {'По приказу Кольтиры Ткача Смерти с "Молота Оргрима" отправляйтесь в Морд\'ретар и нейтрализуйте содержимое чумного котла с помощью пустулезной спинномозговой жидкости.|n|nПустулезная спинномозговая жидкость изготовляется из позвоночника великана. Его можно получить, убивая пустулезных ужасов.', },
  },
  [13282] = {
    'Возвращение на поверхность',
    {'Теперь уходи. У меня за спиной есть портал – выходи через него на поверхность.|n|nМы еще встретимся. Он ведь будет тебя искать.|n|nИ найдет, рано или поздно.', },
    {'Возвращайтесь к Кольтире Ткачу Смерти на борт "Молота Оргрима".', },
  },
  [13283] = {
    'Царь горы',
    {'Короче, $N, мне надо, чтобы ты $Gзагнал:загнала; мой прыгобот на вершину вон той горы на юго-востоке, ясно?|n|nЭта их девчонка, самодовольная Фраззл Зуботеска, уверена, будто ее бот круче моего. Ха! Короче, у нас тут соревнование, кто сумеет стать царем горы!|n|nКак доберешься наверх, воткни наш боевой штандарт в груду костей, чтобы все видели, что Орда сильнее всех, а я – лучший изобретатель!', },
    {'Используйте прыгобот Громбабаха, чтобы установить боевой штандарт Орды в груде черепов на вершине горы, по просьбе Бубуха Громбабаха.', },
  },
  [13284] = {
    'Атака пехоты',
    {'Приветствую тебя, |3-6($C).|n|nНаши войска несколько раз пытались взять Имирхейм штурмом, но врайкулы оказались куда более серьезным противником, чем все, кто прежде встречался нам. Не раз наши люди попадали в засады: мы потеряли многих и многих... |n|nЕсли ты $Gготов: готова; взяться за это дело и провести моих бойцов к вратам Имирхейма, мы щедро и с радостью вознаградим тебя за помощь. Мы намерены разбить лагерь у ворот и там дождаться подкрепления.', },
    {'Сопроводите войска "Усмирителя небес" к вратам Имирхейма. Выполнив задание, вернитесь на край ледника к востоку от Имирхейма к военачальнику Купу за наградой.', },
  },
  [13285] = {
    'Изготовление краеугольного камня',
    {'Ага! Значит, Храм Изобретений, трон самого Хранителя Мимира! Ну разумеется: где же еще следует соединять две части ключа, как не там?|n|nСогласно записям геолога, Храм Изобретений – одна из самых высоких точек с западной стороны Террасы Творцов. Короче, он должен быть примерно на восток от места крушения Гром\'арша.|n|nВстретимся с тобой у храма и соединим части ключа.', },
    {'Встретьтесь с Бранном Бронзобородом в Храме Изобретений и помогите Бранну сложить вместе оболочку Норганнона и ядро Норганнона. После этого вернитесь к Боктару Кровавому Безумию на место крушения Гром\'арша.', },
  },
  [13286] = {
    'Хоть какая-нибудь помощь!',
    {'Тяжкие времена настали, |3-6($C)…|n|nКак ни неприятно это признавать, я готов принять помощь от кого угодно, даже от нашего рыцаря смерти.|n|nСтупай к Тассариану и спроси, не согласится ли он помочь нам разработать тактику борьбы с Плетью, которая могла бы обеспечить победу.|n|nМы забрались слишком далеко... мы не можем потерпеть поражение!', },
    {'Поговорите с Тассарианом по просьбе старшего капитана Джастина Бартлетта на борту "Усмирителя небес".', },
  },
  [13287] = {
    'Тычки и тумаки',
    {'Тебе, при твоем богатом опыте, несомненно, известно, что лучший способ побольше разузнать о противнике – это сойтись с ним в бою.|n|nТы, несомненно, жаждешь обрести славу, взяв цитадель Ледяной Короны, но это невозможно сделать, пока не будут взяты все ворота Короля-лича. И для начала тебе следует сосредоточить свои усилия на первых из них...|n|nВозвращайся на Прорванный фронт. Вступи в бой с врагом. Отыщи в обороне противника брешь, которой мы могли бы воспользоваться, и возвращайся ко мне с подробным отчетом.', },
    {'Убейте 5 неповоротливых поганищ, 5 злокозненных некромантов и 5 адептов Тьмы по просьбе Тассариана, находящегося на борту "Усмирителя небес", корабля Альянса.', },
  },
  [13288] = {
    'Как все погано!',
    {'Поганища…|n|nОни могут быть очень опасными противниками. Мне не раз доводилось видеть, как именно их вмешательство меняло весь ход битвы. Однако немногие догадываются, что поганища могут быть очень ценными союзниками.|n|nМозгов у них, считай, нет вовсе. И если ты знаешь тайны их создания, то сможешь отдавать им распоряжения, которые они будут выполнять, не задумываясь.|n|nМне этот секрет известен – к твоему счастью.|n|nЭтот набор позволит заново оживлять убитых тобой поганищ. Возьми его и используй поганищ против сил Плети у Врат смерти.', },
    {'Используйте набор для оживления, чтобы воскресить поганище и убить с его помощью 15 ледяных вурдалаков, 15 агрессивных упырей и 15 восставших солдат Альянса по просьбе Тассариана с "Усмирителя небес".', },
  },
  [13289] = {
    'Как все погано!',
    {'Ты знаешь, что делать, |3-6($C).|n|nВозьми этот набор и используй внутренности поганищ, чтобы создать свое собственное, а потом прикажи ему атаковать вражеские силы у врат.|n|nТебе стоит отработать эту тактику к тому времени, как мы пойдем на штурм врат.', },
    {'Используйте набор для оживления, чтобы воскресить поганище и убить с его помощью 15 ледяных вурдалаков, 15 агрессивных упырей и 15 восставших солдат Альянса по просьбе Тассариана с "Усмирителя небес".', },
  },
  [13290] = {
    'Немного внимания',
    {'Главный инженер Болтоключ за время службы на "Рассекателе туч" проявил себя как совершенно незаменимый специалист. Если бы не его изобретательность, нас бы давно размазало тонким слоем по всему леднику.|n|nНо проблема в том, что он считает нужным делиться со мной любым своим открытием или изобретением, хотя я в этом практически ничего не понимаю.|n|nА сейчас мне и подавно не до того: все мои мысли заняты врагами. Я не могу допустить, чтобы меня отвлекали!|n|nПожалуйста, сходи к нему вместо меня, $N. И, если он попросит у тебя помощи, помоги ему, чем сумеешь. Он сейчас внизу, в трюме.', },
    {'Поговорите с главным инженером Болтоключом на борту "Усмирителя небес" по просьбе старшего капитана Джастина Бартлетта.', },
  },
  [13291] = {
    'Заимствованная технология',
    {'Понял, все понял! Шеф сейчас слишком занят, ему не до меня. Что ж, тем хуже для него!|n|nСлушай, мне тут удалось… э-э… позаимствовать у противника запас некоего раствора. Я, конечно, терпеть не могу возиться с примитивными гоблинскими технологиями, но в данном случае я готов сделать исключение.|n|nВозьми этот образец. Проведи для меня несколько испытаний – чисто чтобы убедиться, что это действительно полезная штука, – а я тем временем попытаюсь выяснить состав вещества, чтобы получить возможность его воспроизвести.|n|nСтупай на фронт и собери то, что может послужить приманкой, потом используй масло.', },
    {'Используйте краденый раствор на Прорванном фронте по просьбе главного инженера Болтоключа на борту "Усмирителя небес".|n|nДля этого вам понадобится брошенный шлем, брошенная броня и груда костей. Все это можно найти на Прорванном фронте.', },
  },
  [13292] = {
    'Решение проблемы',
    {'А, да-да. С возвращением. Лишняя практика никогда не повредит, ведь так?|n|nА вот и оно, решение проблемы этих мерзких ледяных змеев.|n|nПрореди их ряды, |3-6($R). Чем больше этих монстров погибнет сейчас, тем меньше останется, чтобы противостоять нам во время штурма цитадели.|n|nВот, возьми этот раствор и используй по назначению. А что не используешь, принеси обратно.', },
    {'Используйте краденый раствор на Прорванном фронте по просьбе главного инженера Болтоключа на борту "Усмирителя небес".|n|nДля этого вам понадобится брошенный шлем, брошенная броня и груда костей. Все это можно найти на Прорванном фронте.', },
  },
  [13293] = {
    'В Имирхейм!',
    {'Тебе нужно спуститься в Имирхейм, большой поселок ледяных врайкулов посреди Ледяной Короны.|n|nТам, на западной окраине поселка, находится наш парень, Бубух Громбабах. Он представляет армию Песни Войны в состязании с Альянсом. Проверяют, чей прыгобот лучше, наш или ихний.|n|nСмотри, $N, не подведи нас! На карту поставлена профессиональная честь гоблинских изобретателей! Кроме того, все наши ребята на тебя рассчитывают.|n|nИ, опять же, мы поставили деньги на то, что ты сумеешь отпинать этих трусов!', },
    {'Поговорите с Бубухом Громбабахом в Имирхейме.', },
  },
  [13294] = {
    'Борьба с великанами',
    {'Конечно, очень важно разгромить Плеть на поле битвы, но все-таки не следует пренебрегать и самими воротами.|n|nМясистые великаны, что обороняют укрепления, могут швырять массивные валуны и куски льда, нанося разрушительный урон вражеской пехоте.|n|nСоберись с силами и уничтожь этих великанов. Нам надо знать, насколько они сильны, чтобы предвидеть, с чем предстоит иметь дело.|n|nДа, и кстати, принеси мне их позвоночники. Если память мне не изменяет, с ними можно проделать одну любопытную штуку... Тебя я, конечно, тоже этому научу.', },
    {'Принесите Тассариану с "Усмирителя небес" 5 позвоночников пустулезных ужасов из Морд\'ретара.', },
  },
  [13295] = {
    'Основы химии',
    {'<Тассариан берет гноящиеся позвоночники и сливает из них жидкость во фляжку.>|n|nМалоизвестное свойство мясистых великанов...|n|nИх спинномозговая жидкость взаимодействует с чумой весьма любопытным образом: на выходе получается очень едкая кислота.|n|nЕсли разлить ее вниз с укреплений, войскам, что внизу, это не понравится, но зато жертвы уже не встанут и не пополнят собой ряды противника.|n|nВылей содержимое этой фляги в один из чумных котлов в западном караульном помещении Врат Смерти.', },
    {'Вылейте пустулезную спинномозговую жидкость в чумной котел в Морд\'ретаре по просьбе Тассариана на борту "Усмирителя небес".', },
  },
  [13296] = {
    'В Имирхейм!',
    {'Тебе нужно спуститься в Имирхейм, большой поселок ледяных врайкулов посреди Ледяной Короны.|n|nТам, на южной окраине поселка, находится Фраззл Зуботеска. Она представляет Экспедицию Отважных в состязании с этими ордынскими уродами. Проверяют, чей прыгобот лучше, наш или ихний.|n|nСмотри, $N, не подведи нас! На карту поставлена профессиональная честь гномских изобретателей! Кроме того, все наши ребята на тебя рассчитывают.|n|nИ, опять же, мы поставили деньги на то, что ты сумеешь отпинать этих трусов!', },
    {'Поговорите с Фраззл Зуботеской в Имирхейме.', },
  },
  [13297] = {
    'Избавление от чумы',
    {'Тебе больше не нужна моя помощь, чтобы обезвредить чумные котлы врагов, |3-6($R). |n|nУбей мясистых великанов у Врат смерти и используй их спинномозговую жидкость, чтобы нейтрализовать штаммы чумы. |n|nТы нанесешь сокрушительный удар по стратегии врага. Это крайне важное задание – жизненно важное для нашей победы, и его следует исполнить как можно скорее. |n|nПомни: и великанов, и чумные котлы можно найти в Морд\'ретаре.', },
    {'По приказу Тассариана с "Усмирителя небес" отправляйтесь в Морд\'ретар и нейтрализуйте содержимое чумного котла с помощью пустулезной спинномозговой жидкости.|n|nПустулезная спинномозговая жидкость изготовляется из позвоночника великана. Его можно получить, убивая пустулезных ужасов.', },
  },
  [13298] = {
    'Корпой Оскверненный',
    {'$C, до меня дошли известия о том, что у Врат Смерти появился новый могучий зомби.|n|nМы не можем сидеть сложа руки, когда нам угрожает такой серьезный противник. Любые сведения о нем, какие тебе удастся раздобыть, – лучше, чем ничего.|n|nСтупай в западное караульное помещение у врат и найди это существо. Сразись с ним и отыщи брешь в его защите, которой мы могли бы воспользоваться.', },
    {'Убейте Корпоя Оскверненного из Морд\'ретара по просьбе Тассариана с "Усмирителя небес".', },
  },
  [13299] = {
    'zzOLDПлащ огонька',
    nil,
    nil,
  },
  [13300] = {
    'Рабы саронитовых шахт',
    {'Наш народ был порабощен и отправлен на саронитовые шахты Имирхейма, оплота врайкулов в центре Ледяной Короны. Король-лич заставляет рабов день и ночь добывать эту проклятую руду. |n|nЯ обещал верховному лорду Фордрингу, что мы поможем этим беднягам выбраться из рудников; именно этим мы и займемся. |n|nУвы, мне было приказано оставаться на этом корабле – как посланнику к Экспедиции Отважных. Может быть, вместо меня рабов спасешь ты, $N?', },
    {'Абсалан Благочестивый, находящийся на борту "Усмирителя небес", просит вас освободить 10 рабов из саронитовых шахт.', },
  },
  [13301] = {
    'Атака пехоты',
    {'Приветствую тебя, |3-6($C).|n|nНаши войска несколько раз пытались взять Имирхейм штурмом, но врайкулы оказались куда более серьезным противником, чем все, кто прежде встречался нам. Не раз наши люди попадали в засады: мы потеряли многих и многих... |n|nЕсли ты $Gготов: готова; взяться за это дело и провести моих бойцов к вратам Имирхейма, мы щедро и с радостью вознаградим тебя за помощь. Мы намерены разбить лагерь у ворот и там дождаться подкрепления.', },
    {'Сопроводите кор\'кронские войска к вратам Имирхейма. Выполнив задание, вернитесь на край ледника к северу от Имирхейма к командиру наземных войск Ксутье за наградой.', },
  },
  [13302] = {
    'Рабы саронитовых шахт',
    {'Наш народ был порабощен и отправлен на саронитовые шахты Имирхейма, оплота врайкулов в центре Ледяной Короны. Король-лич заставляет рабов день и ночь добывать эту проклятую руду. |n|nЯ обещал верховному лорду Фордрингу, что мы поможем этим беднягам выбраться из рудников; именно этим мы и займемся. |n|nК сожалению, мне было приказано оставаться на этом корабле – как посланнику к армии Песни Войны . Может быть, вместо меня рабов спасешь ты, $N?', },
    {'Брат Келтан, находящийся на борту "Молота Оргрима", просит вас освободить 10 рабов из саронитовых шахт.', },
  },
  [13303] = {
    'Тестовое задание',
    nil,
    nil,
  },
  [13304] = {
    'Ремонт в полевых условиях',
    {'Мы атакуем, и Плеть отступает, $N. Надо воспользоваться моментом и закрепить наш успех.|n|nЭта долина под нами... кстати сказать, стратегически важный объект... открыта для всех. В юго-восточном конце долины Потерянной Надежды мы обнаружили разобранный разрушитель. Мы полагаем, что он в рабочем состоянии, но, безусловно, нуждается в ремонте.|n|nЕсли сумеешь забрать недостающие детали у этих падальщиков из Плети, у тебя должно получиться запустить разрушитель. Даже один разрушитель в рабочем состоянии может нанести ощутимый ущерб пехоте противника.', },
    {'Кольтира Ткач Смерти с "Молота Оргрима" хочет, чтобы вы отобрали 5 деталей разрушителя у мусорных упырей в долине Потерянной Надежды и отнесли их к сломанному разрушителю.', },
  },
  [13305] = {
    'Все к худшему',
    {'Зачем тебе эта машина? С Плетью воевать? Машинами Плеть не одолеешь.|n|nТы можешь уничтожить сотни… да что там, даже тысячи воинов Плети! Но саму Плеть тебе не победить.|n|nКогда наиграешься вдоволь, ступай на север. Я встречусь с тобой возле заброшенного военного лагеря. И там я покажу тебе кое-что, чтобы ты $Gпонял:поняла;, с чем имеешь дело.', },
    {'Используйте отремонтированный разрушитель, чтобы уничтожить 150 изгнивших вурдалаков, 20 ледотленных волхвов и 2 костяных великана в долине Потерянной Надежды. Выполнив эту задачу, поговорите с Матиасом Нетлером в лагере сопротивления первого легиона.', },
  },
  [13306] = {
    'Строим баррикады!',
    {'Когда наши войска продвинутся за Алдур\'тар, они окажутся уязвимы для атак с Железного вала и большого ледника под ним.|n|nДля строительства нормальных укреплений у нас нет ни времени, ни материалов, однако мы можем возвести хотя бы баррикады, чтобы защитить наших бойцов от обстрела и сдержать атаки Плети.|n|nОтправляйся с этим набором для строительства баррикад в долину Павших Героев, к западу от Алдур\'тара. Отыщи установленные мной метки и сооруди на их месте баррикады.', },
    {'Постройте 8 баррикад с помощью комплекта для возведения баррикад по просьбе Кольтиры Ткача Смерти, находящегося на борту "Молота Оргрима".', },
  },
  [13307] = {
    'Окровавленные знамена',
    {'В долине Павших Героев и на леднике Ледяной Короны, к западу от Алдур\'тара, Плеть пытается использовать против нас убитых. Слуги Плети пробудили мертвецов, спавших в долине, и наделили их невероятной силой и яростью. Источниками этой силы являются знамена, которые хранят у себя предводители Плети в районе ледника. Убей этих знаменосцев, и павшие герои, которых они возглавляют, лишатся своей сверхъестественной силы.|n|nИменно тебе выпало избавить нас от этого препятствия и расчистить путь нашим основным силам.', },
    {'Убейте 5 знаменосцев Плети, 5 обратителей Плети и 20 обращенных героев по просьбе Кольтиры Ткача Смерти, который находится на борту "Молота Оргрима".', },
  },
  [13308] = {
    'Игры разума',
    {'<Голос существа проникает вам прямо в мозг. Ощущения странные и болезненные.>|n|n$R, мне нужна твоя помощь. Как и твои порабощенные друзья, я – жертва алчности имирьяров Короля-лича. Поднявшись из глубин, чтобы выяснить, что за звуки доносятся из пещеры, я был захвачен в плен, и меня заковали в цепи.|n|nПоможешь мне? Ключ от моих кандалов – у бригадира шахтеров. Убей его!|n|n<Вы чувствуете давление в мозгу, словно существо пытается принудить вас выполнить его волю.>', },
    {'Добудьте ключ штейгера от оков темного проповедника Р\'кхема в Саронитовых шахтах.', },
  },
  [13309] = {
    'Воздушный десант',
    {'По приказу командира Купа, который расположился на склоне ледника к востоку от Имирхейма, воспользуйтесь подавительной пушкой "Усмирителя небес". Обеспечьте прикрытие для транспортного самолета, пока тот будет высаживать десант.', },
    {'По приказу командира Купа, который расположился на склоне ледника к востоку от Имирхейма, воспользуйтесь подавительной пушкой "Усмирителя небес". Обеспечьте прикрытие для транспортного самолета, пока тот будет высаживать десант.', },
  },
  [13310] = {
    'Воздушный десант',
    {'Ну, ладно, мелочь пузатая, есть у меня для тебя кое-какая работенка. Должна же быть от тебя какая-то польза, верно?|n|nДесант наших лучших разведчиков готов к заброске в Имирхейм. Тамошние врайкулы вооружены автоматическими копьеметами, которые разносят наш транспорт в клочья, но у нас очень толковые инженеры на "Молоте Оргрима", они создали блокиратор огня.|n|nТы будешь нашим канониром. Дашь несколько залпов по их копьеметам, чтобы создать им плохую видимость и заблокировать их механизмы. Твоя задача: сделать так, чтобы десант был сброшен благополучно, и чтобы наш транспортный аппарат вернулся на базу в целости и сохранности.', },
    {'Командир наземных войск Ксутья на краю ледника возле Имирхейма приказал вам использовать кор\'кронскую заградительную пушку, чтобы обеспечить прикрытие для кор\'кронского транспортника, так чтобы десант был сброшен, а транспортный самолет остался целым.', },
  },
  [13311] = {
    'Карты Новолуния: колода Демонов',
    {'Теперь, когда вы собрали все карты колоды Демонов, вы видите, как сверху появляется еще одна карта. На ней нарисован предсказатель, который глядит прямо на вас, независимо от того, под каким углом вы смотрите на изображение.|n|nВы чувствуете, что с помощью этой карты можно кого-то призвать.', },
    {'Призовите предсказателя судьбы с Ярмарки Новолуния и отдайте ему колоду Демонов.', },
  },
  [13312] = {
    'Железный вал',
    {'Железный вал возвышается над долиной Павших Героев, к западу от Алдур\'тара. Он окружает почти всю долину. Мы не сможем продвинуться дальше, пока не возьмем этот вал. Но там засел Гримкор Злобный и его приверженцы Культа Проклятых.|n|nЕсли ты одолеешь Гримкора, наши войска смогут взять эти стены. Возьми эту руну искажения. Ее мощь, высвобожденная в непосредственной близости от сферы Гримкора, в конце вала, обязательно привлечет внимание некроманта.', },
    {'Убейте Гримкора Злобного и возвращайтесь к Кольтире Ткачу Смерти на "Молот Оргрима".', },
  },
  [13313] = {
    'Ослепить соглядатаев!',
    {'Альянсу каким-то образом удалось запустить целую эскадрилью разведывательных машин, и теперь они кружат над долиной Павших Героев и ледником Ледяной Короны, к западу от Алдур\'тара.|n|nМы такого допустить не можем! Главный инженер Меднопал снабдил меня превосходным оружием как раз для такого случая: он называет эту штуку ЗГ-3. Он уверяет, что эта штука способна сбивать ветролеты Альянса с одного выстрела! Ступай и испытай ее в деле.', },
    {'С помощью ЗГ-3 уничтожьте 6 разведывательных истребителей "Усмирителя небес", потом вернитесь к покорителю небес Корму Черному Шраму на борт "Молота Оргрима".', },
  },
  [13314] = {
    'Перехватить донесения',
    {'Орда что-то затевает, и мне это не нравится! После того, что они вытворяли на Прорванном фронте, стало ясно, что они способны на все – и нам следует их остановить.|n|nНебо над ледником Ледяной Короны, к западу от Алдур\'тара и Железного вала, кишит их разведчиками. Всадники на дракондорах переносят депеши и донесения. Используй этот стреломет, когда понадобится убить разведчиков с "Молота Оргрима". Пожалуй, будет лучше, если ты тоже будешь летать...', },
    {'Заберите 6 донесений для "Молота Оргрима" у разведчиков с "Молота Оргрима", и отдайте их старшему капитану Джастину Бартлетту на борту "Усмирителя небес".', },
  },
  [13315] = {
    'Предварительная разведка',
    {'Дело движется. Мы разработали тактику, которая должна помочь нам взять Врата Смерти под контроль. Конечно, потери будут, и немалые, но в конце концов мы должны победить – особенно если Орда, с которой ты так жаждешь сразиться, нам не помешает.|n|nСледующей нашей целью станут Врата Горя. Слетай туда, ознакомься с местностью, посмотри, с чем предстоит иметь дело.|n|nА когда вернешься, я дам тебе новое поручение.', },
    {'Слетайте к Вратам Горя и ознакомьтесь с южной, центральной, северной и северо-западной частями Врат по просьбе Тассариана с "Усмирителя небес".', },
  },
  [13316] = {
    'Стражи Корп\'ретара',
    {'Корп\'ретар, именуемый также Вратами Ужаса, – это последнее препятствие между нами и цитаделью Ледяной Короны. Он расположен к югу от Железного вала, за ледником и Пожарищем. Переход будет долгим и трудным. Пока мы туда доберемся, наши солдаты выбьются из сил.|n|nНужно ослабить вражескую оборону, иначе мы все поляжем под этими стенами.|n|nУкрепления обороняют самые яростные и преданные солдаты Короля-лича. Сделай все возможное, чтобы их уничтожить – будем надеяться, этого будет достаточно.', },
    {'Убейте 5 провозвестников ужаса и 5 стражей Корп\'ретара по приказу Кольтиры Ткача Смерти с "Молота Оргрима".', },
  },
  [13318] = {
    'Перетащить и опустить',
    {'Так значит, Врата Горя обороняет Культ Проклятых? Неудивительно.|n|nЛадно, пора позабавиться. Ты говоришь, у южной части Врат тренируют новых сектантов? У каждого из них должен быть особый предмет, его выдают всем посвященным – сфера иллюзии.|n|nЭти артефакты используются для того, чтобы маскировать приверженцев секты и позволять им беспрепятственно проходить всюду, где надо, смешиваясь с толпой врагов.|n|nУбивай этих безумцев, пока не добудешь несколько таких сфер, а потом используй их против поработителей.', },
    {'Отберите сферы иллюзии у озлобленных посвященных в Алдур\'таре и используйте их против 3 темных поработителей по просьбе Тассариана, который находится на борту "Усмирителя небес".', },
  },
  [13319] = {
    'Вершина иерархии',
    {'Судя по твоему докладу и по тому, что мне известно о культе, в каждом их лагере имеется надзиратель, который всем и заправляет.|n|nРазумеется, уничтожение всех этих предводителей остановит сектантов лишь ненадолго, но все-таки на время выведет их из игры. На данный момент это вполне актуальная задача.|n|nОтыщи этих надзирателей и расправься с ними. Потом возвращайся ко мне.', },
    {'Отправляйтесь в Алдур\'тар и убейте надзирателя Фэдриса, надзирателя Саврина, надзирателя Веража и надзирателя Джакона про просьбе Тассариана с "Усмирителя небес".', },
  },
  [13320] = {
    'Невоспроизводимый компонент',
    {'Я даже отсюда ощущаю запах, исходящий от их котлов – но нет, это не чумное зелье... |n|nПриверженцев культа заставляют пить смесь, лишающую их воли и навеки обращающую в рабов Короля-лича. |n|nНекоторые говорят, что одним из ингредиентов этого зелья является душа подвергшегося пыткам и безжалостно убитого существа, однако мне никогда не удавалось заполучить подобный компонент... |n|nНаполни эту флягу образцами зелья из трех котлов, находящихся к северо-западу от ворот, и отнеси главному инженеру Болтоключу.', },
    {'Тассариан с корабля "Усмиритель небес" хочет, чтобы вы наполнили трехчастную флягу изо всех 3 котлов служителей культа в Алдур\'таре, а затем отнесли ее главному инженеру Болтоключу.', },
  },
  [13321] = {
    'Все переиграть',
    {'Это должно подействовать!|n|nЗначит, эти мерзавцы ищут чужие души, чтобы бросить их в свою безумную похлебку? Ничего, мы им подсобим!|n|nНа-ка, глотни малость! Не тревожься, оно очень сильно разбавлено… ну, по крайней мере, я почти уверен, что оно не окажет никакого эффекта, кроме того, что ты сможешь обнаруживать сущности поверженных сектантов.|n|nКогда соберешь их побольше, швырни корчащуюся массу искаженных душ в любой из их котлов.|n|nПоглядим, как им понравится собственное лекарство!', },
    {'Бросьте корчащуюся массу в котел в Алдур\'таре по просьбе главного инженера Болтоключа с "Усмирителя небес".', },
  },
  [13322] = {
    'Все переиграть',
    {'Значит, эти мерзавцы ищут чужие души, чтобы бросить их в свою безумную похлебку? Ничего, мы им подсобим!|n|nНа-ка, глотни малость! Не тревожься, оно очень сильно разбавлено… ну, по крайней мере, я почти уверен, что оно не окажет никакого эффекта, кроме того, что ты сможешь обнаруживать сущности поверженных сектантов.|n|nКогда соберешь их побольше, швырни корчащуюся массу искаженных душ в любой из их котлов.|n|nПоглядим, как им понравится собственное лекарство!', },
    {'Выпейте разбавленное снадобье сектантов по просьбе главного инженера Болтоключа с "Усмирителя небес", затем убивайте любых сектантов, каких встретите в Алдур\'таре, и забирайте их оскверненные сущности. После смешайте 10 сущностей, чтобы получить корчащуюся массу, и бросьте ее в любой из котлов сектантов.', },
  },
  [13323] = {
    'Перетащить и опустить',
    {'Что-то эти посвященные опять расплодились! Ты знаешь, что следует делать…|n|nУ южной части врат тренируют новых сектантов. У каждого из них должен быть особый предмет, его выдают всем посвященным – сфера иллюзии.|n|nЭти артефакты используются для того, чтобы маскировать приверженцев секты и позволять им беспрепятственно проходить всюду, где надо, смешиваясь с толпой врагов.|n|nУбивай этих безумцев, пока не добудешь несколько таких сфер, а потом используй сферы против поработителей.', },
    {'Отберите сферы иллюзии у озлобленных посвященных в Алдур\'таре и используйте их против 3 темных поработителей по просьбе Тассариана, который находится на борту "Усмирителя небес".', },
  },
  [13324] = {
    'Колода карт Новолуния: Призмы',
    {'Как только вы собираете вместе восемь карт из колоды Призм, девятая карта с такой же "рубашкой" появляется в колоде. На карте написано: "Принеси колоду на ярмарку Новолуния, и получишь награду". Ярмарка приезжает в Мулгор и Златоземье раз в несколько месяцев. Придется подождать до следующего раза...', },
    {'Принесите колоду Призм на ярмарку Новолуния.', },
  },
  [13325] = {
    'Колода карт Новолуния: Хаос',
    {'Как только вы собираете вместе восемь карт из колоды Хаоса, девятая карта с такой же "рубашкой" появляется в колоде. На карте написано: "Принеси колоду на ярмарку Новолуния, и получишь награду". Ярмарка приезжает в Мулгор и Златоземье раз в несколько месяцев. Придется подождать до следующего раза...', },
    {'Принесите колоду Хаоса на ярмарку Новолуния.', },
  },
  [13326] = {
    'Колода карт Новолуния: Аристократы',
    {'Как только вы собираете вместе восемь карт из колоды Аристократов, девятая карта с такой же "рубашкой" появляется в колоде. На карте написано: "Принеси колоду на ярмарку Новолуния, и получишь награду". Ярмарка приезжает в Мулгор и Златоземье раз в несколько месяцев. Придется подождать до следующего раза...', },
    {'Принесите колоду Аристократов на ярмарку Новолуния.', },
  },
  [13327] = {
    'Колода карт Новолуния: Нежить',
    {'Как только вы собираете вместе восемь карт из колоды Нежити, девятая карта с такой же "рубашкой" появляется в колоде. На карте написано: "Принеси колоду на ярмарку Новолуния, и получишь награду". Ярмарка приезжает в Мулгор и Златоземье раз в несколько месяцев. Придется подождать до следующего раза...', },
    {'Принесите колоду Нежити на ярмарку Новолуния.', },
  },
  [13328] = {
    'Вдребезги',
    {'Слуги Короля-лича установили три кристалла: Ужаса, Отчаяния и Страдания, – на крепостных стенах Корп\'ретара. Если наши войска подойдут к стенам Корп\'ретара, король обрушит на нас мощь этого грозного оружия.|n|nЗаработав на полную мощность, кристаллы наполнят сознание наших бойцов болью и страхом. И тогда Плеть играючи расправится с ними.|n|nНайди эти кристаллы, разбей их и принеси мне их осколки. Нельзя допустить, чтобы Король-лич применил против нас это оружие!', },
    {'Принесите Кольтире Ткачу Смерти на "Молот Оргрима" осколки кристалла Ужаса, кристалла Отчаяния и кристалла Страдания.', },
  },
  [13329] = {
    'Пред Вратами Ужаса',
    {'Войско Короля-лича выстроилось для защиты цитадели у Пожарища близ Корп\'ретара, южнее Железного вала.|n|nЛегион скелетов-разорителей под командованием рыцарей смерти перекрыл дорогу. Даже если мы уничтожим эту нежить, боюсь, Плеть просто их восстановит и снова нашлет на нас.|n|nУ меня есть план, как этому помешать, но я не знаю, сработает он или нет... Возьми этот раствор и попробуй полить им останки скелетов-разорителей, чтобы растворить их.', },
    {'Растворите останки 6 скелетов-разорителей летучей кислотой по заданию Кольтиры Ткача Смерти с "Молота Оргрима".', },
  },
  [13330] = {
    'Кровь избранных',
    {'Врайкулы, сумевшие добиться благоволения Короля-лича, называют себя имирьярами. Они живут в городе, расположенном в центре Ледяной Короны. Прежде чем атаковать цитадель Ледяной Короны, нам нужно как следует подготовиться. Прежде всего, необходимо извести так называемых "избранных" Короля-лича.|n|nСтупай в их город, Имирхейм, и истреби имирьяров в их собственном гнезде. Пусть все знают, чье войско сильнее!', },
    {'Убейте 20 врайкулов в Имирхейме по просьбе завоевателя Давоса Рихта с "Молота Оргрима".', },
  },
  [13331] = {
    'Ослепление Альянса',
    {'Альянсовцы, конечно, упрямы, этого у них не отнимешь, однако для того, чтобы нас остановить, потребуется нечто большее! Вот, возьми с собой ЗГ-3 и снова перестреляй бойцов-разведчиков с "Усмирителя небес"!|n|nВряд ли нам удастся вбить в их твердолобые башки побольше ума, но, по крайней мере, мы можем постараться: боеприпасов у нас хватит! Ты увидишь их бойцов, они кружат над долиной Павших героев, к западу от Алдур\'тара. Не возвращайся, пока не разгромишь их!', },
    {'С помощью ЗГ-3 уничтожьте 6 разведывательных истребителей "Усмирителя небес", потом вернитесь к покорителю небес Корму Черному Шраму на борт "Молота Оргрима".', },
  },
  [13332] = {
    'Строим баррикады!',
    {'Когда наши войска продвинутся за Алдур\'тар, они окажутся уязвимы для атак с Железного вала и большого ледника под ним.|n|nДля строительства нормальных укреплений у нас нет ни времени, ни материалов, однако мы можем возвести хотя бы баррикады, чтобы защитить наших бойцов от обстрела и сдержать атаки Плети.|n|nОтправляйся с этим набором для строительства баррикад в долину Павших Героев, к западу от Алдур\'тара. Отыщи установленные мной метки и сооруди на их месте баррикады.', },
    {'Постройте 8 баррикад с помощью комплекта для возведения баррикад по просьбе Тассариана с "Усмирителя небес".', },
  },
  [13333] = {
    'Перехват донесений',
    {'Несмотря на все наши усилия, Орда продолжает засылать разведчиков на территорию ледника Ледяной Короны, к западу от Железного вала и Алдур\'тара.|n|nНельзя допустить, чтобы ордынцы стали хозяином положения благодаря этой разведывательной операции. Так что бери ружье, стреляющее дротиками, и перебей всех разведичков с "Молота Оргрима", не щади никого! Все донесения, которые будут при них, неси мне.|n|nОрда хорошо потрудилась, а мы, так сказать, пожнем все плоды их трудов. Главное – вовремя подсуетиться.', },
    {'Заберите 6 донесений для "Молота Оргрима" у разведчиков с "Молота Оргрима", и отдайте их старшему капитану Джастину Бартлетту на борту "Усмирителя небес".', },
  },
  [13334] = {
    'Окровавленные знамена',
    {'В долине Павших Героев и на леднике Ледяной Короны, к западу от Алдур\'тара, Плеть пытается использовать против нас убитых. Слуги Плети пробудили мертвецов, спавших в долине, и наделили их невероятной силой и яростью. Источниками этой силы являются знамена, которые хранят у себя предводители Плети в районе ледника. Убей этих знаменосцев, и павшие герои, которых они возглавляют, лишатся своей сверхъестественной силы.|n|nИменно тебе выпало избавить нас от этого препятствия и расчистить путь нашим основным силам.', },
    {'Убейте 5 знаменосцев Плети, 5 обратителей Плети и 20 обращенных героев по просьбе Тассариана, который находится на борту "Усмирителя небес".', },
  },
  [13335] = {
    'Пред Вратами Ужаса',
    {'Войско Короля-лича выстроилось для защиты цитадели у Пожарища близ Корп\'ретара, южнее Железного вала.|n|nЛегион скелетов-разорителей под командованием рыцарей смерти перекрыл дорогу. Даже если мы уничтожим эту нежить, боюсь, Плеть просто их восстановит и снова нашлет на нас.|n|nУ меня есть план, как этому помешать, но я не знаю, сработает он или нет... Возьми этот раствор и попробуй полить им останки скелетов-разорителей, чтобы растворить их.', },
    {'Растворите трупы 6 скелетов-разорителей летучей кислотой по заданию Тассариана с "Усмирителя небес".', },
  },
  [13336] = {
    'Кровь избранных',
    {'Врайкулы, сумевшие добиться благоволения Короля-лича, называют себя имирьярами. Они живут в городе, расположенном в центре Ледяной Короны. Прежде чем атаковать цитадель Ледяной Короны, нам нужно как следует подготовиться. Прежде всего, необходимо извести так называемых "избранных" Короля-лича.|n|nСтупай в их город, Имирхейм, и истреби имирьяров в их собственном гнезде. Пусть все знают, чье войско сильнее!', },
    {'Убейте 20 врайкулов в Имирхейме по просьбе рыцаря-капитана Дроша с "Усмирителя небес".', },
  },
  [13337] = {
    'Железный вал',
    {'Железный вал возвышается над долиной Павших Героев, к западу от Алдур\'тара. Он окружает почти всю долину. Мы не сможем продвинуться дальше, пока не возьмем этот вал. Но там засел Гримкор Злобный и его приверженцы Культа Проклятых.|n|nЕсли ты одолеешь Гримкора, наши войска смогут взять эти стены. Возьми эту руну искажения. Ее мощь, высвобожденная в непосредственной близости от сферы Гримкора, в конце вала, обязательно привлечет внимание некроманта.', },
    {'Убейте Гримкора Злобного и возвращайтесь к Тассариану на "Усмиритель небес".', },
  },
  [13338] = {
    'Стражи Корп\'ретара',
    {'Корп\'ретар, именуемый также Вратами Ужаса, – это последнее препятствие между нами и цитаделью Ледяной Короны. Он расположен к югу от Железного вала, за ледником и Пожарищем. Переход будет долгим и трудным. Пока мы туда доберемся, наши солдаты выбьются из сил.|n|nНужно ослабить вражескую оборону, иначе мы все поляжем под этими стенами.|n|nУкрепления обороняют самые яростные и преданные солдаты Короля-лича. Сделай все возможное, чтобы их уничтожить – будем надеяться, этого будет достаточно.', },
    {'Убейте 5 провозвестников ужаса и 5 стражей Корп\'ретара по приказу Тассариана с "Усмирителя небес".', },
  },
  [13339] = {
    'Вдребезги',
    {'Слуги Короля-лича установили три кристалла: Ужаса, Отчаяния и Страдания, – на крепостных стенах Корп\'ретара. Если наши войска подойдут к стенам Корп\'ретара, король обрушит на нас мощь этого грозного оружия.|n|nЗаработав на полную мощность, кристаллы наполнят сознание наших бойцов болью и страхом. И тогда Плеть играючи расправится с ними.|n|nНайди эти кристаллы, разбей их и принеси мне их осколки. Нельзя допустить, чтобы Король-лич применил против нас это оружие!', },
    {'Принесите Тассариану на "Усмиритель небес" осколки кристалла Ужаса, кристалла Отчаяния и кристалла Страдания.', },
  },
  [13340] = {
    'Помощь в нападении',
    {'Нам нужны бойцы для нападения на Имирхейм!|n|nЛюбой воин, у которого есть хоть капля мозгов, скажет тебе, что врайкулы – отчаянные бойцы и голыми руками их не возьмешь. А уж имирьяры – тем более! Понятно, отчего Король-лич счел достойными именно их.|n|nРаспоряжение по осаде отдает командир наземных войск Ксутья. Сам город находится в центре Ледяной Короны. Войска Ксутьи стоят на краю ледника, к северу от города.', },
    {'Явитесь к командиру наземных войск Ксутье на краю ледника к северу от Имирхейма.', },
  },
  [13341] = {
    'Помощь в нападении',
    {'Нам нужны бойцы для нападения на Имирхейм!|n|nЛюбой воин, у которого есть хоть капля мозгов, скажет тебе, что врайкулы – отчаянные бойцы, и голыми руками их не возьмешь. А уж имирьяры – тем более! Понятно, отчего Король-лич счел достойными именно их.|n|nОсадой командует военачальник Куп. Сам город находится в центре Ледяной Короны. Войска Купа стоят на краю ледника, к северу от города.', },
    {'Явитесь к военачальнику Купу на краю ледника к северу от Имирхейма.', },
  },
  [13342] = {
    'Ненастоящий шпион',
    {'Что ж, $Gдружище:барышня;, настало время нам обзавестись шпионом.|n|nНет, не настоящим шпионом, но для наших целей он подойдет.|n|nВ северной части Алдур\'тара сектанты, призыватели Бездны, порабощают демонов. Используй этот жезл, чтобы вытянуть темную сущность из трупов порабощенных слуг, а затем используй их камень призыва, чтобы создать нашего маленького шпиона.|n|nПока этого посланца не обнаружат, он будет нашими глазами и ушами. Он проберется повсюду и будет неприметно наблюдать за врагом.', },
    {'Соберите 5 темных сущностей и вызовите темного посланника в Алдур\'таре по просьбе Тассариана, который находится на борту "Усмирителя небес".', },
  },
  [13343] = {
    'Тайна бесконечности, мания преследования',
    {'Ах, снова ты! Или мы только что беседовали?|n|n<Хроми размышляет над причудами времени.>|n|nКак бы то ни было, за тобой охотятся драконы Бесконечности! Точнее, не совсем за тобой, а за той прошлой версией тебя, что обороняла песочные часы Вечности. Помнишь, да?|n|nАга, значит, тогда это $Gбыл:была; все же ты, и теперь это снова ты. Постой, это все неважно! Важно то, что тебе следует вернуться в Бронзовое святилище драконов, чтобы защищать себя и песочные часы от атак драконов Бесконечности! Иначе ты исчезнешь из истории.', },
    {'Хроми на вершине храма Драконьего Покоя просит вас снова отправиться в Бронзовое святилище драконов.|n|nОказавшись в святилище, установите песочные часы Вечности и помогите Себе-в-Прошлом защитить их от атак драконов Бесконечности.', },
  },
  [13344] = {
    'Ненастоящий шпион',
    {'Сектанты отловили последнего отправленного тобой посланца, |3-6($R).|n|nКонечно, он успел доставить нам немало ценных сведений, и все же нам необходимо продолжать следить за каждым их шагом.|n|nИспользуй этот жезл, чтобы вытянуть темную сущность из трупов порабощенных слуг, а затем используй их камень призыва, чтобы создать еще одного шпиона.|n|nПока этого посланца не обнаружат, он будет нашими глазами и ушами. Он проберется повсюду и будет неприметно наблюдать за врагом.', },
    {'Соберите 5 темных сущностей и вызовите темного посланника в Алдур\'таре по просьбе Тассариана, который находится на борту "Усмирителя небес".', },
  },
  [13345] = {
    'Слишком мало сведений',
    {'Культ Проклятых известен тем, что вечно строит грандиозные планы, которые никогда не исполняются. Но на этот раз явно вышло иначе…|n|nБыть может, это близкое соседство с Королем-личом на них так повлияло. Как бы то ни было, они держатся увереннее, чем обычно. Необходимо выяснить, что питает их отвагу, а затем найти способ усмирить их!|n|nПодозреваю, что все дело в их ученых. Узнай, что они затевают, и доложи мне во всех подробностях.', },
    {'Отберите у ученых культа в Алдур\'таре 3 страницы Исследований Культа Проклятых и используйте их, чтобы составить доклад о Культе Проклятых по приказу Тассариана с "Усмирителя небес".', },
  },
  [13346] = {
    'Пусть злодеи не ведают покоя',
    {'Эти глупцы и впрямь обнаружили нечто, что может представлять серьезную угрозу для наших планов!|n|nПредводитель их секты, Алумет, совершил ритуальное самоубийство, и теперь его прихвостни передают его душе свою силу...|n|nЕсли оставить его в покое, их усилиями он скоро превратится в опасного противника!|n|nСобери его сердце, череп, скипетр и одеяние, а потом воздействуй на его останки кристаллом.|n|nТоропись, |3-6($R)! Уничтожь его, пока он не стал слишком силен!', },
    {'Повергните Алумета Восходящего в Алдур\'таре по просьбе Тассариана, который находится на борту "Усмирителя небес".', },
  },
  [13347] = {
    'Восставший из праха',
    {'Судьба от рождения начертана огненными письменами в наших душах. Падение Болвара – это трагедия, но оно было неизбежно. |n|nВсе, что ты можешь сделать ныне, $N – это почтить своего героя. Найди на поле боя щит Болвара и возврати его королю. Когда будешь отдавать шит Вариану, скажи ему так: "Не все потеряно. Из праха падшего восстанет сила, которая объединит народы и очистит этот мир от скверны."|n|nОн не должен терять веру. Теперь иди, $N. Твоему народу нужен герой. Им $Gнужен:нужна; ты.', },
    {'Найдите щит Фордрагона на поле боя при Ангратаре, Вратах Гнева. Отнесите щит в крепость Штормграда и вручите королю Вариану Ринну.', },
  },
  [13348] = {
    'Тщета',
    {'Теперь понимаешь? Посылая своих бойцов на войну с полчищами принца, вы только пополняете их ряды.|n|nВпрочем, я и не рассчитывал, что ты поймешь… думаю, с тобой будет то же, что и с другими. Возвращайся лучше к тому, кто тебя прислал. Думаю, о тебе тревожатся...', },
    {'Возвращайтесь к Кольтире Ткачу Смерти на борт "Молота Оргрима".', },
  },
  [13349] = {
    'Колыбель ледяных драконов',
    {'Мы должны продолжать наступление. Нельзя давать передышку армии Плети.|n|nНа востоке, сразу за долиной Потерянной Надежды, находится Каньон Гибели Синдрагосы. Там всем заправляет Культ Проклятых под жестким контролем нежити из врайкулов, прислужников Короля-лича.|n|nЭто место великой силы – возможно, древнее кладбище синих драконов. Там из праха синих драконов создают вселяющих ужас ледяных драконов.|n|nЕсли мы нанесем удар по Каньону Гибели Синдрагосы, у наших врагов сильно поубавится ледяных змеев. Так что, $N? Возьмешься за это дело?', },
    {'Отправляйтесь в Каньон Гибели Синдрагосы и убейте 5 воскресителей драконов, 8 сектантов-осквернителей и 3 врайкулов-некролордов по просьбе Кольтиры Ткача Смерти с "Молота Оргрима".', },
  },
  [13350] = {
    'Пусть злодеи не ведают покоя',
    {'А, это Алумет… Снова набирает силу. Я это чую. Снова его прихвостни передают магию его душе.|n|nЕсли оставить его в покое, их усилиями он скоро превратится в опасного противника!|n|nВозвращайся в его зал в северной части Алдур\'тара. Собери его сердце, череп, скипетр и одеяние, а потом воздействуй на его останки кристаллом.|n|nТоропись, |3-6($R)! Уничтожь его, пока он не стал слишком могуществен!', },
    {'Повергните Алумета Восходящего в Алдур\'таре по просьбе Тассариана, который находится на борту "Усмирителя небес".', },
  },
  [13351] = {
    'Предварительная разведка',
    {'Дело движется. Мы разработали тактику, которая должна помочь нам взять Врата Смерти под контроль. Конечно, потери будут, и немалые, но в конце концов мы должны победить – особенно если Альянс нам не помешает.|n|nСледующей нашей целью станет Алдур\'тар, Врата Горя. Слетай туда, ознакомься с местностью, посмотри, с чем предстоит иметь дело.|n|nА когда вернешься, я дам тебе новое поручение.', },
    {'Слетайте к Вратам Горя и ознакомьтесь с южной, центральной, северной и северо-западной частями Врат по просьбе Кольтиры с "Молота Оргрима".', },
  },
  [13352] = {
    'Перетащить и опустить',
    {'Так значит, Врата Горя обороняет Культ Проклятых? Неудивительно.|n|nЛадно, пора позабавиться. Ты говоришь, у южной части Врат тренируют новых сектантов? У каждого из них должен быть особый предмет, его выдают всем посвященным – сфера иллюзии.|n|nЭти артефакты используются для того, чтобы маскировать приверженцев секты и позволять им беспрепятственно проходить всюду, где надо, смешиваясь с толпой врагов.|n|nУбивай этих безумцев, пока не добудешь несколько таких сфер, а потом используй их против поработителей.', },
    {'Отберите сферы иллюзии у озлобленных посвященных в Алдур\'таре и используйте их против 3 темных поработителей по просьбе Кольтиры, который находится на борту "Молота Оргрима".', },
  },
  [13353] = {
    'Перетащить и опустить',
    {'Что-то эти посвященные опять расплодились! Ты знаешь, что следует делать…|n|nУ южной части врат тренируют новых сектантов. У каждого из них должен быть особый предмет, его выдают всем посвященным – сфера иллюзии.|n|nЭти артефакты используются для того, чтобы маскировать приверженцев секты и позволять им беспрепятственно проходить всюду, где надо, смешиваясь с толпой врагов.|n|nУбивай этих безумцев, пока не добудешь несколько таких сфер, а потом используй сферы против поработителей.', },
    {'Отберите сферы иллюзии у озлобленных посвященных в Алдур\'таре и используйте их против 3 темных поработителей по просьбе Кольтиры, который находится на борту "Молота Оргрима".', },
  },
  [13354] = {
    'Вершина иерархии',
    {'Судя по твоему докладу и по тому, что мне известно о культе, в каждом их лагере имеется надзиратель, который всем и заправляет.|n|nРазумеется, уничтожение всех этих предводителей остановит сектантов лишь ненадолго, но все-таки на время выведет их из игры. На данный момент это вполне актуальная задача.|n|nОтыщи этих надзирателей и расправься с ними. Потом возвращайся ко мне.', },
    {'Отправляйтесь в Алдур\'тар и убейте надзирателя Фэдриса, надзирателя Саврина, надзирателя Веража и надзирателя Джакона про просьбе Кольтиры с "Молота Оргрима".', },
  },
  [13355] = {
    'Невоспроизводимый компонент',
    {'Я даже отсюда ощущаю запах, исходящий от их котлов – но нет, это не чумное зелье... |n|nПриверженцев культа заставляют пить смесь, лишающую их воли и навеки обращающую в рабов Короля-лича. |n|nНекоторые говорят, что одним из ингредиентов этого зелья является душа подвергшегося пыткам и безжалостно убитого существа, однако мне никогда не удавалось заполучить подобный компонент...|n|nНаполни эту флягу образцами зелья из трех котлов, находящихся к северо-западу от ворот, и отнеси главному инженеру Меднопалу.', },
    {'Кольтира с корабля "Молот Оргрима" хочет, чтобы вы наполнили секционную флягу изо всех 3 котлов служителей культа в Алдур\'таре, а затем отнесли ее главному инженеру Меднопалу.', },
  },
  [13356] = {
    'Все переиграть',
    {'Это должно подействовать!|n|nЗначит, эти мерзавцы ищут чужие души, чтобы бросить их в свою безумную похлебку? Ничего, мы им подсобим!|n|nНа-ка, глотни малость! Не тревожься, оно очень сильно разбавлено… ну, по крайней мере, я почти уверен, что оно не окажет никакого эффекта, кроме того, что ты сможешь обнаруживать сущности оскверненного духа поверженных сектантов.|n|nКогда соберешь их побольше, швырни корчащуюся массу искаженных душ в любой из их котлов.|n|nПоглядим, как им понравится собственное лекарство!', },
    {'Бросьте корчащуюся массу в котел в Алдур\'таре по просьбе главного инженера Меднопала с "Молота Оргрима".', },
  },
  [13357] = {
    'Все переиграть',
    {'Значит, эти мерзавцы ищут чужие души, чтобы бросить их в свою безумную похлебку? Ничего, мы им подсобим!|n|nНа-ка, глотни малость! Не тревожься, оно очень сильно разбавлено… ну, по крайней мере, я почти уверен, что оно не окажет никакого эффекта, кроме того, что ты сможешь обнаруживать сущности поверженных сектантов.|n|nКогда соберешь их побольше, швырни корчащуюся массу искаженных душ в любой из их котлов.|n|nПоглядим, как им понравится собственное лекарство!', },
    {'Бросьте корчащуюся массу в котел в Алдур\'таре по просьбе главного инженера Меднопала с "Молота Оргрима".', },
  },
  [13358] = {
    'Ненастоящий шпион',
    {'Что ж, $Gдружище:барышня;, настало время нам обзавестись шпионом.|n|nНет, не настоящим шпионом, но для наших целей он подойдет.|n|nВ северной части Алдур\'тара сектанты, призыватели Бездны, порабощают демонов. Используй этот жезл, чтобы вытянуть темную сущность из трупов порабощенных слуг, а затем используй их камень призыва, чтобы создать нашего маленького шпиона.|n|nПока этого посланца не обнаружат, он будет нашими глазами и ушами. Он проберется повсюду и будет неприметно наблюдать за врагом.', },
    {'Соберите 5 темных сущностей и вызовите темного посланника в Алдур\'таре по просьбе Кольтиры, который находится на борту "Молота Оргрима".', },
  },
  [13359] = {
    'Место гибели драконов',
    {'Тут погиб целый выводок синих драконов. И вот теперь его слуги воскрешают их, одного за другим.|n|nСамого могучего воскресил он сам. Принеси мне пыли костей молодых драконов, и я покажу тебе, как он это сделал.', },
    {'Добудьте в Каньоне Гибели Синдрагосы 6 горстей пыли из костей дракончиков по приказу Матиаса Нетлера.', },
  },
  [13360] = {
    'Время ответов',
    {'Я вижу, у тебя много вопросов, $N. Ты – $Gединственный:единственная;, кто может видеть меня, ибо $Gкоснулся:коснулась; некоего предмета, принадлежавшего ему... Ты помнишь?|n|nТы не знаешь, что это? Нет-нет, я не могу просто так рассказать тебе... Он разгневается сверх всякой меры, а ведь ныне он не принц, но король!|n|nВстретимся во Дворе Костей, к северу от цитадели Ледяной Короны: там ты $Gсам:сама; все увидишь.', },
    {'Поговорите с Матиасом Нетлером во Дворе Костей.', },
  },
  [13361] = {
    'Охотник и принц',
    {'До того как стать королем, принц сражался во многих битвах... Но лишь в одной ему грозила смерть. |n|nБитва свершилась здесь, на этом месте. Позволь мне показать, что случилось, и ты все поймешь.|n|nНайди залитый кровью камень и осмотри его. Тогда тебе откроется прошлое.', },
    {'Матиас Нетлер со Двора Костей хочет, чтобы вы нашли Окровавленный камень и увидели, что случилось с принцем.', },
  },
  [13362] = {
    'Знание – тяжкая ноша',
    {'Теперь ты знаешь, что тебе предстоит, $N. Противник, которому неведомы ни боль, ни муки совести, ни человеческие чувства... Противник, который готов на все, чтобы добиться своего. |n|nЕдинственная слабость нынешнего короля в том, что его сердце все еще существует; и теперь король знает, что ты $Gнашел:нашла; его. |n|nЕсли хочешь вернуться и найти сердце, лучше возьми кого-нибудь в помощь – его хорошо охраняют...', },
    {'Вернитесь к Кольтире на борт "Молота Оргрима".', },
  },
  [13363] = {
    'Помощь Серебряного Авангарда',
    {'Среди рыцарей смерти ходят слухи о тех событиях, о которых ты говоришь. Я всегда думал, что в этой истории есть… более глубокий смысл.|n|nНадо предупредить остальных, но это нужно сделать тихо. Если Король-лич хоть что-нибудь заподозрит, он тут же переправит Сердце в другое место. А подобного случая более не представится.|n|nКульт Проклятых уже проникал и в Орду, и в Альянс. Черный Клинок действует по соседству с Плетью...|n|nНадо связаться с Тирионом Фордрингом и его Серебряным Авангардом.', },
    {'Поговорите с верховным лордом Тирионом Фордрингом на Вершине Рыцарей.', },
  },
  [13364] = {
    'Уловка Тириона',
    {'Этим утром разведчики сообщили мне, что из цитадели Ледяной Короны к Собору Тьмы движется процессия последователей Культа Проклятых, и что они несут некий артефакт. |n|nА теперь мне стало известно, что этим сокровищем может быть само сердце Артаса... Сердце, хранящее последние крупицы человечности, еще оставшиеся в нем! |n|nЭто знак свыше. Пока подобный предмет существует, остается надежда, что Артас Менетил вновь сможет стать человеком!|n|nВстретимся у входа в собор. И не забудь прихватить капюшон сектанта-послушника: никто не должен узнать нас.', },
    {'Тирион Фордринг с Вершины Рыцарей хочет, чтобы вы достали и надели капюшон сектанта-послушника, а затем встретились с ним у входа в Собор Тьмы, к северо-западу от цитадели Ледяной Короны.', },
  },
  [13365] = {
    'Ненастоящий шпион',
    {'Сектанты отловили последнего отправленного тобой посланника, |3-6($R).|n|nКонечно, он успел доставить нам немало ценных сведений, и все же нам необходимо продолжать следить за каждым их шагом.|n|nИспользуй этот жезл, чтобы вытянуть темную сущность из трупов порабощенных слуг, а затем используй их камень призыва, чтобы создать нового шпиона.|n|nПока этого посланника не обнаружат, он будет нашими глазами и ушами. Он проберется повсюду и будет неприметно наблюдать за врагом.', },
    {'Соберите 5 темных сущностей и вызовите темного посланника в Алдур\'таре по просьбе Кольтиры, который находится на борту "Молота Оргрима".', },
  },
  [13366] = {
    'Слишком мало сведений',
    {'Культ Проклятых известен тем, что вечно строит грандиозные планы, которые никогда не исполняются. Но на этот раз явно вышло иначе…|n|nБыть может, это близкое соседство с Королем-личом на них так повлияло. Как бы то ни было, они держатся увереннее, чем обычно. Необходимо выяснить, что питает их отвагу, а затем найти способ усмирить их!|n|nПодозреваю, что все дело в их ученых. Узнай, что они затевают, и доложи мне во всех подробностях.', },
    {'Отберите у ученых культа в Алдур\'таре 3 страницы Исследований Культа Проклятых и используйте их, чтобы составить доклад о Культе Проклятых по приказу Кольтиры с "Молота Оргрима".', },
  },
  [13367] = {
    'Пусть злодеи не ведают покоя',
    {'Эти глупцы и впрямь обнаружили нечто, что может представлять серьезную угрозу для наших планов!|n|nПредводитель их секты, Алумет, совершил ритуальное самоубийство, и теперь его прихвостни передают его душе свою силу...|n|nЕсли оставить его в покое, их усилиями он скоро превратится в опасного противника!|n|nСобери его сердце, череп, скипетр и одеяние, а потом воздействуй на его останки кристаллом.|n|nТоропись, |3-6($R)! Уничтожь его, пока он не стал слишком силен!', },
    {'Кольтира на борту "Молота Оргрима" хочет, чтобы вы убили Алумета Восходящего в Алдур\'таре.', },
  },
  [13368] = {
    'Пусть злодеи не ведают покоя',
    {'А, это Алумет… Снова набирает силу. Я это чую. Снова его прихвостни передают магию его душе.|n|nЕсли оставить его в покое, их усилиями он скоро превратится в опасного противника!|n|nВозвращайся в его зал в северной части Алдур\'тара. Собери его сердце, череп, скипетр и одеяние, а потом воздействуй на его останки кристаллом.|n|nТоропись, |3-6($R)! Уничтожь его, пока он не стал слишком могуществен!', },
    {'Кольтира на борту "Молота Оргрима" хочет, чтобы вы убили Алумета Восходящего в Алдур\'таре.', },
  },
  [13369] = {
    'Против воли рока',
    {'По просьбе леди Праудмур я позволю ей отправиться в Оргриммар с посольством, дабы говорить с военачальником Орды Траллом. Ты будешь сопровождать и оберегать ее в пути. По возвращении я хочу узнать вести из Оргриммара.|n|nКогда будешь $Gготов: готова;, поговори с Джайной.', },
    {'Сопроводите леди Джайну Праудмур в Калимдор в Оргриммар. Поговорите с военачальником Орды Траллом.', },
  },
  [13370] = {
    'Королевский ход',
    {'Ваш воитель, Болвар, погиб, защищая весь наш мир. Орда опечалена гибелью такого героя, однако Орда не в ответе за трусливое нападение Гнилесса у врат Гнева. Мы тоже потеряли немало героев из-за его предательства. |n|nПередай вашему королю, что мы сделаем все, что в наших силах, чтобы призвать к ответу виновников этого злобного деяния. Мы также сделаем все возможно, дабы избежать конфликта с Альянсом. Однако если на нас нападут, мы будет защищаться без колебаний.', },
    {'Воспользуйтесь порталом в крепости Громмаш, чтобы вернуться в крепость Штормграда и передать послание Тралла королю Вариану Ринну.', },
  },
  [13371] = {
    'В ожидании дальнейших распоряжений',
    {'Когда ты $Gушел:ушла; в Оргриммар, я послал в Подгород Бролла и Валиру. Сейчас они расположились рядом с канализационным коллектором у входа в развалины и ждут дальнейших указаний.|n|nЛеди Праудмур откроет портал для наших войск прямо на подступах к Подгороду. Иди туда и разыщи Бролла. Мы с Джайной подтянемся чуть позже, но уже очень скоро.', },
    {'Воспользуйтесь порталом в Крепости Штормграда и телепортируйтесь в Подгород. Когда прибудете на место, разыщите Бролла Медвежью Шкуру.', },
  },
  [13372] = {
    'Ключ к Радужному Средоточию',
    {'Выпавший из лап Сапфирона драгоценный камень в форме глаза издает мощный гул, явно магической природы, который не только слышен, но и ощущается всем телом. Для смертного слуха этот гул воспринимается как мучительная боль.|n|nТакой могущественный предмет можно отдать лишь королеве драконов, Алекстразе Хранительнице Жизни. Спросите ее совета на вершине храма Драконьего Покоя, что в Драконьем Погосте.', },
    {'Отнесите ключ от Радужного Средоточия Алекстразе Хранительнице Жизни на вершине храма Драконьего Покоя в Драконьем Погосте.', },
  },
  [13373] = {
    'Последнее слово техники',
    {'Я установила инфра-зеленые излучатели на захваченные бомбардировщики. Они действуют как щиты и защитят тебя в первом боевом вылете на вражескую территорию. Поговори с Риззи Храпокруткой, возьми бомбардировщик и лети в Зону бомбардировки!|n|nУ тебя будет полный боекомплект: бомбы, ракеты и щиты. Следи за тем, чтобы щиты не разряжались, и уничтожай наземные войска Плети, расположившиеся в Зоне бомбардировки. Потом возвращайся сюда. У тебя будет новое задание.', },
    {'Уничтожьте 40 пехотинцев из зоны бомбардировки, 8 капитанов из зоны бомбардировки и 15 горгулий-душительниц по заданию инженера-экспериментатора Теззлы.', },
  },
  [13374] = {
    'Боевое задание',
    {'Уничтожьте пехотинцев из зоны бомбардировки, боевые машины Плети, горгулий-душительниц и часовых ледяных драконов по заданию инженера-экспериментатора Теззлы.', },
    {'Уничтожьте пехотинцев из зоны бомбардировки, боевые машины Плети, горгулий-душительниц и часовых ледяных драконов по заданию инженера-экспериментатора Теззлы.', },
  },
  [13375] = {
    'Ключ к Радужному Средоточию (героический режим)',
    {'Выпавший из лап Сапфирона драгоценный камень в форме глаза издает мощный гул, явно магической природы, который не только слышен, но и ощущается всем телом. Для смертного слуха этот гул воспринимается как мучительная боль.|n|nТакой могущественный предмет можно отдать лишь королеве драконов, Алекстразе Хранительнице Жизни. Спросите ее совета на вершине храма Драконьего Покоя, что в Драконьем Погосте.', },
    {'Отнесите ключ от Радужного Средоточия (героический режим) Алекстразе Хранительнице Жизни на вершине храма Драконьего Покоя в Драконьем Погосте.', },
  },
  [13376] = {
    'Война продолжается',
    {'Война продолжается, $N. К счастью, у нас есть хороший запас бомб и ракет! Самое время испытать наш инфра-зеленый бомбардировщик и разорвать этих мерзавцев из Плети на мелкие плеточки!', },
    {'Уничтожьте 50 пехотинцев из зоны бомбардировки, 12 боевых машин Плети, 20 горгулий-душительниц и 12 часовых ледяных драконов по заданию инженера-экспериментатора Теззлы.', },
  },
  [13377] = {
    'Битва за Подгород',
    {'Глубоко в недрах Подгорода прячется убийца, ответственный за гибель Болвара и наших отважных солдат у Врат Гнева.|n|nВариан привел сюда с собой всю мощь Альянса, чтобы взять город. Присоединись к нему и к леди Праудмур в охоте на ассасина! Это позволит тебе стать $Gодним:одной; из первых героев Альянса!|n|nКогда будешь $Gготов:готова;, поговори с королем Варианом Ринном.', },
    {'Помогите королю Вариану Ринну и леди Джайне Праудмур покарать верховного аптекаря Гнилесса! Если вам это удастся, явитесь к королю Вариану Ринну.', },
  },
  [13378] = {
    'Главный инженер Меднопал',
    {'Поговорите с главным инженером Меднопалом', },
    {'Поговорите с главным инженером Меднопалом', },
  },
  [13379] = {
    'Зеленые технологии',
    {'Надо тебя познакомить с Теззлой. Да, точно! Она научилась использовать новое волновое излучение – инфразеленое – и с его помощью ей удалось подобраться поближе к армии Плети! Достаточно близко, чтобы сбрасывать на них бомбы!|n|nЯ наделю тебя способностью видеть в инфразеленом диапазоне, чтобы разыскать ее над Алдур\'таром, Вратами Горя. Отправляйся немедленно... насколько я знаю, у нее всегда найдется работа для отважных героев, которые не прочь повзрывать то да се! Особенно прислужников Плети!|n|nИ еще $N, Альянс украл нашу технологию, и у него есть собственный невидимый аэропорт неподалеку. Избегай строений со знаменами Альянса!', },
    {'Поговорите с инженером-экспериментатором Теззлой.', },
  },
  [13380] = {
    'Возглавить нападение',
    {'Технология инфра-зеленого излучения позволяет нам оставаться "невидимыми" прямо под носом у Плети! Больше того, мы установили инфра-зеленые излучатели на специально сконструированные бомбардировщики... но вовсе не для того, чтобы скрыть эти машины от глаз врага, нет! Мы используем излучение как щит!|n|nСтупай туда, где стоит Карен Нет, попроси бомбардировщик. Лети в Зону бомбардировки... используй щиты и пушку для защиты, а бомбометы – понятное дело, для бомбометания. В общем, потренируйся, а потом возвращайся ко мне. Я дам тебе новое задание, которое будет уже посерьезнее!', },
    {'Убейте 40 пехотинцев из зоны бомбардировки, 8 капитанов из зоны бомбардировки и 15 горгулий-душительниц по заданию Кибли Киллогерца.', },
  },
  [13381] = {
    'Боевой вылет',
    {'Надевай свои счастливые носки, $N, и читай все любимые молитвы. Твое следующее задание – это будет уже настоящее испытание находчивости, и смекалки, и силы духа. Прямо как нежданный визит обожаемой $Gтещи:свекрови;, хе-хе!|n|nПусть Карен Но даст тебе еще один бомбардировщик. Лети за Зону бомбардировки, к долине Потерянной Надежды. На этот раз целей будет гораздо больше: как на земле, так и в воздухе. В общем, чтоб тебе долететь и туда и обратно, и боеприпасы не кончились, и заряд у щитов не иссяк. Встретимся после боя, $N!', },
    {'Уничтожьте пехотинцев из зоны бомбардировки, боевые машины Плети, горгулий-душительниц и часовых ледяных драконов по заданию Кибли Киллогерца.', },
  },
  [13382] = {
    'Килотонны смерти',
    {'Бой продолжается! Для тебя есть задание дальнего действия. Цель – бомбардировка Долины Потерянной Надежды. Когда будешь $Gготов:готова;, пусть Карен даст тебе бомбардировщик. Сбрось все ракеты и бомбы на головы этих уродов Плети!', },
    {'Уничтожьте 50 пехотинцев из зоны бомбардировки, 12 боевых машин Плети, 20 горгулий-душительниц и 12 часовых ледяных драконов по заданию Кибли Киллогерца.', },
  },
  [13383] = {
    'Киллогерц',
    {'Гоблинам удалось открыть новую форму энергии. Они называют ее инфра-зеленым излучением, и это действительно зеленое золото с технологической точки зрения. Они, ясное дело, те еще психопаты, но мозги у них есть, и иногда они даже работают. Стыдно признаться, но мы выкрали их технологию. Однако я с гордостью заявляю, что мы ее усовершенствовали!|n|nРазыщи Кибли Киллогерца. Он у нас главный по разработкам инфра-зеленого излучения. Его база находится в маленьком секретном аэропорту Альянса над Алдур\'таром, Вратами Горя. Я дам тебе прибор инфра-зеленого видения, чтобы ты $Gсмог:смогла; найти аэропорт.', },
    {'Разыщите Кибли Киллогерца на базе в скрытом аэропорту Альянса над Алдур\'таром, Вратами Горя, по приказу главного инженера Болтоключа.', },
  },
  [13384] = {
    'Правосудие в Оке Вечности',
    {'Теперь, когда у тебя есть доступ к Радужному Средоточию, нужно использовать его в деле.|n|nКак бы мне ни хотелось, чтобы Малигос снова стал одним из нас, я понимаю, что это уже невозможно. Слишком многое поставлено на карту, и другие Драконьи аспекты решили, что Хранитель Магии должен умереть.|n|n<Крас произносит эти слова с дрожью в голосе.>|n|n$N, отправляйся к Оку Вечности, убей Малигоса и возвращайся сюда с Сердцем Магии.', },
    {'Принесите Сердце Магии Красу на вершине храма Драконьего Покоя в Драконьем Погосте.|n|nЭто задание предназначено для обычного уровня сложности и представляет собой версию Ока Вечности для 10 игроков.', },
  },
  [13385] = {
    'Героическое правосудие в Оке Вечности',
    {'Теперь, когда у тебя есть доступ к Радужному Средоточию, нужно использовать его в деле.|n|nКак бы мне ни хотелось, чтобы Малигос снова стал одним из нас, я понимаю, что это уже невозможно. Слишком многое поставлено на карту, и другие Драконьи аспекты решили, что Хранитель Магии должен умереть.|n|n<Крас произносит эти слова с дрожью в голосе.>|n|n$N, отправляйся к Оку Вечности, убей Малигоса и возвращайся сюда с Сердцем Магии.', },
    {'Принесите Сердце Магии Красу на вершине храма Драконьего Покоя в Драконьем Погосте.|n|nЭто задание предназначено для героического уровня сложности и представляет собой версию Ока Вечности для 25 игроков.', },
  },
  [13386] = {
    'Разведка провала',
    {'У меня есть для тебя интересное задание, $N. Если возьмешься, конечно.|n|nНам сообщили о каком-то провале под Цитаделью Ледяной Короны. Наши инженеры изучили схемы и определили все слабые места.|n|nМы отправили туда наших ребят с "позаимствованными" саронитовыми бомбами. Командует ими капитан Кендалл.|n|nЕсли ты им поможешь, мы сможем нанести неслабый удар силам Плети. Что скажешь, $N?', },
    {'Поговорите с капитаном Кендаллом под цитаделью Ледяной Короны.', },
  },
  [13387] = {
    'Круговая оборона',
    {'Саронитовые бомбы уже заложены, $N. Однако воспользоваться ими мы сможем только один раз. Надо использовать эту возможность максимально эффективно.|n|nЧтобы благополучно их взорвать, нужно хотя бы на время обеспечить себе контроль над этой территорией. Надо постараться уменьшить численность воинов Плети.', },
    {'Капитан Кендалл у цитадели Ледяной Короны просит вас убить 10 неповоротливых громад.', },
  },
  [13388] = {
    'Поджигай!',
    {'Все идет отлично. Можно браться за дело.|n|nБомбы заложены у самой ямы. Я начинаю эвакуировать наших.', },
    {'Капитан Кендалл под стенами цитадели Ледяной Короны просит вас отправиться к ближайшему штабелю саронитовых бомб и поджечь фитиль.', },
  },
  [13389] = {
    'Фитиль короток!',
    {'Не успев поджечь фитиль, вы обнаруживаете, что он сгорает куда быстрее, чем вы рассчитывали!|n|nБомбы вот-вот рванут. Ваш единственный шанс на спасение – броситься в провал и надеяться, что там не слишком глубоко.', },
    {'Там, куда вы падаете, вас ждет кое-что интересное!', },
  },
  [13390] = {
    'Голос во тьме',
    {'Нет, это не кристалл, это какой-то замороженный орган…|n|nВы прикасаетесь к нему – и руку пронзает немыслимая боль. Такое ощущение, будто руку отрубили напрочь. Но никаких ран на ней не заметно…|n|nПытаясь собраться с мыслями, вы вдруг слышите где-то рядом мальчишеский голос.|n|n"Не стоило тебе этого делать, ой, не стоило!"', },
    {'Выясните, откуда доносится голос, который вы услышали в Наз\'анаке, Забытых глубинах.', },
  },
  [13391] = {
    'Пора прятаться!',
    {'Не стоило тебе трогать эту штуку! Теперь он непременно явится искать тебя.|n|nИ он тебя найдет. Если только ты не сумеешь от него спрятаться.|n|nХочешь выжить – принеси мне кровь безликих!', },
    {'Добудьте 3 образца крови безликих по совету Матиаса Нетлера.', },
  },
  [13392] = {
    'Возвращение на поверхность',
    {'Теперь уходи. У меня за спиной есть портал – выходи через него на поверхность.|n|nМы еще встретимся. Он ведь будет тебя искать.|n|nИ найдет, рано или поздно.', },
    {'Вернитесь к Тассариану на борт "Усмирителя небес".', },
  },
  [13393] = {
    'Ремонт в полевых условиях',
    {'Хорошо. Но победу праздновать пока рановато. Нужно закрепить и развить успех, которого мы добились с помощью взрывов.|n|nМы заметили на поле боя вполне еще рабочую ордынскую катапульту класса "разрушитель". Но ее разбирают на части упыри.|n|nЕсли бы тебе удалось восстановить катапульту, мы могли бы нанести войскам Плети в долине куда более серьезный урон.|n|nДа, конечно, я понимаю, мертвяки превосходят нас по численности, но я в тебя верю!', },
    {'Отберите у упырей-мародеров 5 деталей разрушителя и отнесите их к сломанной катапульте в долине Потерянной Надежды по просьбе Тассариана на борту "Усмирителя небес".', },
  },
  [13394] = {
    'Все к худшему',
    {'Зачем тебе эта машина? С Плетью воевать? Машинами Плеть не одолеешь.|n|nТы можешь уничтожить сотни… да что там, даже тысячи воинов Плети! Но саму Плеть тебе не победить.|n|nКогда наиграешься вдоволь, ступай на север. Я встречусь с тобой возле заброшенного военного лагеря. И там я покажу тебе кое-что, чтобы ты $Gпонял:поняла;, с чем имеешь дело.', },
    {'Используйте отремонтированный разрушитель, чтобы уничтожить 150 изгнивших вурдалаков, 20 ледотленных волхвов и 2 костяных великана в долине Потерянной Надежды. Выполнив эту задачу, поговорите с Матиасом Нетлером в лагере сопротивления первого легиона.', },
  },
  [13395] = {
    'Войско проклятых',
    {'Ты, наверное, гордишься своим могуществом: ну как же, ты громишь эту нежить, давишь кости мертвяков своей машиной…|n|nНо это все пустяки по сравнению с тем могуществом, которое потребовалось, чтобы их создать!|n|nЯ видел, как принц это делал. И могу показать, как это было... если хочешь, конечно.', },
    {'Оживите 100 вурдалаков-прислужников по просьбе Матиаса Нетлера в лагере сопротивления первого легиона.', },
  },
  [13396] = {
    'Тщета',
    {'Теперь понимаешь? Посылая своих бойцов на войну с полчищами принца, вы только пополняете их ряды.|n|nВпрочем, я и не рассчитывал, что ты поймешь… думаю, с тобой будет то же, что и с другими. Возвращайся лучше к тому, кто тебя прислал. Думаю, о тебе тревожатся...', },
    {'Вернитесь к Тассариану на борт "Усмирителя небес".', },
  },
  [13397] = {
    'Каньон Гибели Синдрагосы',
    {'Ты настоящий герой, $N. Видишь ли, когда я даю одному из своих солдат поручение, шансы, что он действительно его выполнит, примерно пятьдесят на пятьдесят. А шансов на то, что он вернется живым, и того меньше.|n|nНо ты другое дело! На тебя всегда можно положиться. Ты работаешь, как гномские часы!|n|nЭто я к чему: вот тебе еще одно дело. Каньон Гибели Синдрагосы находится к востоку от долины. Сектанты развили там слишком бурную деятельность. Они создают ледяных змеев – и не только. Ступай и разберись с ними!|n|nНенавижу сектантов.', },
    {'Убейте 5 воскресителей драконов, 8 сектантов-осквернителей и 3 врайкулов-некролордов в Каньоне Гибели Синдрагосы по приказу Тассариана с "Усмирителя небес".', },
  },
  [13398] = {
    'Место гибели драконов',
    {'Тут погиб целый выводок синих драконов. И вот теперь его слуги воскрешают их, одного за другим.|n|nСамого могучего воскресил он сам. Принеси мне пыли костей молодых драконов, и я покажу тебе, как он это сделал.', },
    {'Добудьте в Каньоне Гибели Синдрагосы 6 горстей пыли из костей дракончиков по приказу Матиаса Нетлера.', },
  },
  [13399] = {
    'Время ответов',
    {'Я вижу, у тебя много вопросов, $N. Ты – $Gединственный:единственная;, кто может видеть меня, ибо $Gкоснулся:коснулась; некоего предмета, принадлежавшего ему... Ты помнишь?|n|nТы не знаешь, что это? Нет-нет, я не могу просто так рассказать тебе... Он разгневается сверх всякой меры, а ведь ныне он не принц, но король!|n|nВстретимся во Дворе Костей, к северу от цитадели Ледяной Короны: там ты $Gсам:сама; все увидишь.', },
    {'Поговорите с Матиасом Нетлером во Дворе Костей.', },
  },
  [13400] = {
    'Охотник и принц',
    {'До того как стать королем, принц сражался во многих битвах... Но лишь в одной ему грозила смерть. |n|nБитва свершилась здесь, на этом месте. Позволь мне показать, что случилось, и ты все поймешь.|n|nНайди залитый кровью камень и осмотри его. Тогда тебе откроется прошлое.', },
    {'Матиас Нетлер со Двора Костей хочет, чтобы вы нашли Окровавленный камень и увидели, что случилось с принцем.', },
  },
  [13401] = {
    'Знание – тяжкая ноша',
    {'Теперь ты знаешь, что тебе предстоит, $N. Противник, которому неведомы ни боль, ни муки совести, ни человеческие чувства... Противник, который готов на все, чтобы добиться своего. |n|nЕдинственная слабость нынешнего короля в том, что его сердце все еще существует; и теперь король знает, что ты $Gнашел:нашла; его. |n|nЕсли хочешь вернуться и найти сердце, лучше возьми кого-нибудь в помощь – его хорошо охраняют...', },
    {'Вернитесь к Тассариану на борт "Усмирителя небес".', },
  },
  [13402] = {
    'Помощь Тириона',
    {'Я не в первый раз слышу рассказ об Артасе и его сердце... Правда, мне всегда казалось, что это выдуманная история. |n|nЧто ж, нам следует действовать по обстоятельствам. К сожалению, делать это придется в тайне. |n|nШпионы Артаса повсюду, и если он узнает о наших планах, мы все погибнем. |n|nНужно сообщить обо всем Серебряному Авангарду. Сам Тирион лично отбирал паладинов для этого ордена. Если и остались еще те, кто свободен от губительного влияния служителей культа, то это они.', },
    {'Поговорите с верховным лордом Тирионом Фордрингом на Вершине Рыцарей.', },
  },
  [13403] = {
    'Уловка Тириона',
    {'Этим утром разведчики сообщили мне, что из цитадели Ледяной Короны к Собору Тьмы движется процессия последователей Культа Проклятых, и что они несут некий артефакт. |n|nА теперь мне стало известно, что этим сокровищем может быть само сердце Артаса... Сердце, хранящее последние крупицы человечности, еще оставшиеся в нем! |n|nЭто знак свыше. Пока подобный предмет существует, остается надежда, что Артас Менетил вновь сможет стать человеком!|n|nВстретимся у входа в собор. И не забудь прихватить капюшон сектанта-послушника: никто не должен узнать нас.', },
    {'Тирион Фордринг с Вершины Рыцарей хочет, чтобы вы достали и надели капюшон сектанта-послушника, а затем встретились с ним у входа в Собор Тьмы, к северо-западу от цитадели Ледяной Короны.', },
  },
  [13404] = {
    'Войска статического разряда: Зона бомбардировки',
    {'Это будет задание ближнего действия. Цель – Зона бомбардировки. Для разминки. $GГотов:Ты готова;?', },
    {'Убейте 50 пехотинцев из зоны бомбардировки, 10 капитанов из зоны бомбардировки и 20 горгулий-душительниц по заданию Кибли Киллогерца.', },
  },
  [13405] = {
    'К оружию! Берег Древних',
    {'Здесь, в Нордсколе, мы сражаемся не только с армиями Короля-лича, но и с силами Орды.|n|nНедавно на Береге Древних была найдена могущественная реликвия титанов. Мы, дворфы, уже многие годы оберегаем подобные артефакты, и потому считаем себя законными хранителями этой святыни.|n|nНо Орда разработала план по извлечению реликвии из руин титанов. Несомненно, они намереваются использовать ее в качестве оружия против нас, и потому наш долг – остановить их, пока еще не поздно.', },
    {'Выиграйте битву на поле боя Берега Древних и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.', },
  },
  [13406] = {
    'Новое излучение. Зона бомбардировки',
    {'Ну что, ты $Gготов:готова; размяться и слегка побомбить врагов? Ну, тогда хорошо. У тебя есть задание, а у нас – бомбы.', },
    {'Уничтожьте 50 пехотинцев из зоны бомбардировки, 10 капитанов из зоны бомбардировки и 20 горгулий-душительниц по заданию инженера-экспериментатора Теззлы.', },
  },
  [13407] = {
    'К оружию! Берег Древних',
    {'Война с Плетью в Нордсколе – это еще не повод давать послабление Альянсу!|n|nЭти проклятые дворфы из Лиги Исследователей откопали какую-то могущественную реликвию титанов. Мы не можем допустить, чтобы она попала в руки Альянса!|n|nИди, $N, и уничтожь наших врагов. Пусть они поймут, что им нигде от нас не скрыться.', },
    {'Выиграйте битву на поле боя Берега Древних и вернитесь к ордынскому вестнику войны в любую из столиц Орды, на Озеро Ледяных Оков, в Даларан или в Шаттрат.', },
  },
  [13408] = {
    'Штурмовые укрепления',
    {'Цитадель Адского Пламени уже долгое время отбивает все наши атаки. Мы сохраняем позиции, но не можем перейти в решительное наступление. Нам необходимо укрепить передовые.|n|nРазведчики обнаружили рядом с Цитаделью Адского Пламени три форта. Мы должны их захватить. Помоги нашим войскам и доложи мне, когда все три перейдут к нам.|n|nПусть удача сопутствует тебе в битве, $N. Скорее всего, Орда тоже положила глаз на эти укрепления, так что тебе придется иметь дело с ее войсками.', },
    {'Захватите Дозорное укрепление, Ристалище и Изрезанный холм, и возвращайтесь к прапорщику Трейси Праудвелл в Оплот Чести на Полуострове Адского Пламени.', },
  },
  [13409] = {
    'Штурмовые укрепления',
    {'Мы должны стереть проклятых орков Скверны с лица нашей земли! Но перед тем, как напасть на Цитадель Адского Пламени, необходимо укрепить позиции.|n|nГонцы обнаружили три форта, которые хорошо подходят для наших целей. К сожалению, Альянсу пришла в голову та же идея, и он уже выдвинул войска, чтобы захватить эти укрепления.|n|nТы $Gдолжен:должна; отбросить силы Альянса и помочь нашему войску захватить все три форта. Когда выполнишь это задание, возвращайся ко мне.|n|nВо славу Орды!', },
    {'Захватите Дозорное укрепление, Ристалище и Изрезанный холм, и возвращайтесь в Траллмар к Черноглазке Зову Войны.', },
  },
  [13410] = {
    'Штурмовые укрепления',
    {'Цитадель Адского Пламени уже долгое время отбивает все наши атаки. Мы сохраняем позиции, но не можем перейти в решительное наступление. Нам необходимо укрепить передовые.|n|nРазведчики обнаружили рядом с Цитаделью Адского Пламени три форта. Мы должны их захватить. Помоги нашим войскам и доложи мне, когда все три перейдут к нам.|n|nПусть удача сопутствует тебе в битве, $N. Скорее всего, Орда тоже положила глаз на эти укрепления, так что тебе придется иметь дело с ее войсками.', },
    {'Захватите Дозорное укрепление, Ристалище и Изрезанный холм, и возвращайтесь к прапорщику Трейси Праудвелл в Оплот Чести на Полуострове Адского Пламени.', },
  },
  [13411] = {
    'Штурмовые укрепления',
    {'Мы должны стереть проклятых орков Скверны с лица нашей земли! Но перед тем, как напасть на Цитадель Адского Пламени, необходимо укрепить позиции.|n|nГонцы обнаружили три форта, которые хорошо подходят для наших целей. К сожалению, Альянсу пришла в голову та же идея, и он уже выдвинул войска, чтобы захватить эти укрепления.|n|nТы $Gдолжен:должна; отбросить силы Альянса и помочь нашему войску захватить все три форта. Когда выполнишь это задание, возвращайся ко мне.|n|nВо славу Орды!', },
    {'Захватите Дозорное укрепление, Ристалище и Изрезанный холм, и возвращайтесь в Траллмар к Черноглазке Зову Войны.', },
  },
  [13412] = {
    'Корастраза',
    {'Привет тебе, |3-6($C). Я могу попросить тебя об услуге?|n|nУ красного дракона Релораза, командующего нашим аванпостом, есть сестра, Корастраза. Против его воли она поднялась в одно из верхних колец Нексуса, чтобы увидеть фантастически могущественных синих драконов.|n|nОн, конечно, не подает виду, но его беспокоит судьба сестры , и ему будет приятно узнать, что с ней ничего не случилось.|n|nПожалуйста, разыщи ее. И попроси ее на время забыть о гордости и послать весточку брату.', },
    {'Поговорите с Корастразой в Хладарре по просьбе библиотекаря Серры.', },
  },
  [13413] = {
    'Асы, ввысь!',
    {'Ты настолько $Gотважен и дерзок, смертный:дерзка и отважна, смертная;, что не боишься приблизиться к логову Малигоса? Или ты просто не знаешь, чем это грозит? Ладно, скоро мы это узнаем...|n|nЯ давно тренирую красных драконов. Моя задача: изучить врага и обучить моих питомцев такой тактике боя, которая будет наиболее эффективной, когда придет время сразиться с повелителем синих драконов.|n|nЯ хочу посмотреть тебя в деле – понять, на что ты $Gспособен:способна;. И поэтому я разрешаю тебе взять одного из моих питомцев и вылететь на боевое задание.|n|nТебе стоит лишь попросить – и мои драконы в твоем распоряжении.', },
    {'Возьмите дракона Корастразы из верхнего кольца Нексуса в Хладарре и убейте 5 чешуеклятов-гвардейцев.', },
  },
  [13414] = {
    'Асы, ввысь!',
    {'Мы снова встретились, |3-6($R). Надо признаться, я уже начинаю к тебе привыкать.|n|nВерно ли я понимаю, что ты $Gпришел:пришла; тренироваться, чтобы отточить свои навыки воздушного боя?|n|nМои питомцы всегда готовы сеять панику и разрушения в стане врага.|n|nТебе стоит лишь попросить – и они в твоем распоряжении.', },
    {'Возьмите дракона Корастразы из верхнего кольца Нексуса в Хладарре и убейте 5 чешуеклятов-гвардейцев.', },
  },
  [13415] = {
    'Пульт в библиотеке',
    {'Мы знаем, где оболочка Норганнона, $N. Возьми диск изобретателя и иди в библиотеку. Там должен быть пульт, который нужно активировать с помощью этого диска. Я так думаю, Мимир спрятал там не только оболочку. Вполне вероятно, что там есть запас схем, которого инженерам Стальгорна хватит на несколько лет бесперебойной работы!|n|nВ любом случае, воспользуйся диском, чтобы добраться до оболочки. Будем надеяться, что фантазия Мимира на этом иссякла, и новые препятствия не предвидятся.', },
    {'Активируйте пульт в Библиотеке Изобретателя с помощью диска изобретателя.', },
  },
  [13416] = {
    'Пульт в библиотеке',
    {'Мы знаем, где оболочка Норганнона, $N. Возьми диск изобретателя и иди в библиотеку. Там должен быть пульт, который нужно активировать с помощью этого диска. Я так думаю, Мимир спрятал там не только оболочку. Вполне вероятно, что там есть запас схем, которого инженерам Стальгорна хватит на несколько лет бесперебойной работы!|n|nВ любом случае, воспользуйся диском, чтобы активировать пульт. Будем надеяться, что фантазия Мимира на этом иссякла, и новые препятствия не предвидятся.', },
    {'Активируйте пульт в Библиотеке Изобретателя с помощью диска изобретателя.', },
  },
  [13417] = {
    'Братья Бронзобороды',
    {'Вот оно! Наконец-то у нас есть краеугольный камень... Какая красота! Я немало попутешествовал по миру, но эта вещь снова приводит меня в восторг. Хотя сейчас явно не время застывать в эстетическом ступоре, восхищаться и ахать я буду потом, а сейчас надо скорее выбираться отсюда!|n|nЗабирайся в мой ветролет и прикрывай нас от железных дворфов!', },
    {'Прикрывайте Бранна Бронзоборода и его ветролет, пока не доберетесь до Ледяной крепости.', },
  },
  [13418] = {
    'Подготовка к войне',
    {'Эй, ты!|n|nДа, я к тебе обращаюсь. С виду ты, вроде, $Gнеглупый парень:неглупая барышня;. А нам тут, в Ледяной Короне, нужны адекватные кадры. И чем больше, тем лучше!|n|nТы, наверное, $Gслышал:слышала;, что нам не удалось захватить ледник с земли, но пусть тебя это не слишком тревожит. Сейчас мы готовим новую атаку. Мы ударим по ним с нашего нового боевого корабля, который построен с помощью самых продвинутых технологий во всем Азероте. Против нашего "Усмирителя небес" не выстоять никому: ни Орде, ни Артасу.|n|nДай мне знать, когда будешь $Gготов:готова; отправиться в путь.', },
    {'Поговорите с офицером ван Россемом, который переправит вас на борт "Усмирителя небес" в Ледяной Короне, а потом побеседуйте со старшим капитаном Джастином Бартлеттом.', },
  },
  [13419] = {
    'Подготовка к войне',
    {'Эй, ты!|n|nДа, я к тебе обращаюсь. С виду ты, вроде, $Gнеглупый парень:неглупая барышня;. А нам тут, в Ледяной Короне, нужны адекватные кадры. И чем больше, тем лучше!|n|nЭти мерзавцы из Альянса вошли в Ледяную Корону раньше нас, рванули без подготовки и получили именно то, что вполне заслужили из-за своего нетерпения. А мы не спешили. Мы подготовились как следует и уже очень скоро пойдем в атаку. Мы ударим по ним с нашего нового боевого корабля, который построен с помощью самых продвинутых технологий во всем Азероте. Против нашего "Молота Оргрима" не выстоять никому: ни Альянсу, ни Артасу.|n|nДай мне знать, когда будешь $Gготов:готова; отправиться в путь и оказать нам посильную помощь.', },
    {'Поговорите с покорителем небес Клумом, который переправит вас на борт "Молота Оргрима" в Ледяной Короне, а потом побеседуйте с покорителем небес Кормом Черным Шрамом.', },
  },
  [13420] = {
    'Вечный лед',
    {'Этот кусок льда подвергся очень сильному давлению и воздействию природной магии – где-то на большой глубине. В результате получился лед, который никогда не тает.|n|nМало что понимая в таких вещах, вы решаете отнести образец этого странного льда в Дун Ниффелем. Наверняка там есть кто-то, кто знает, что это такое.', },
    {'Возвращайтесь в Дун Ниффелем и расспросите Кальдера насчет осколка Вечного льда.', },
  },
  [13421] = {
    'Больше Вечного льда!',
    nil,
    nil,
  },
  [13422] = {
    'Поучить уму-разуму',
    {'Ты преуспела там, где другие потерпели поражение. Но почивать на лаврах еще рано.|n|nПокажи остальным, что такое настоящие сила и преданность!|n|nНепокорные врайкулы из Заброшенного рудника снова нуждаются во вразумлении. Покажи им, сестра, каково это – не повиноваться нам!', },
    {'Накажите 6 обессиленных врайкулов из Заброшенного рудника с помощью вразумляющего жезла по заданию Гретты Судьи из деревни Бруннхильдар.', },
  },
  [13423] = {
    'Подтверждение победы',
    {'Все восхищены тобой, сестра. Но не теряй бдительности: любая из сестер, жаждущая славы, может попытаться отобрать у тебя титул королевы хильд!|n|nПокажи этим бездарностям, на что ты способна!', },
    {'Одержите победу над 6 дуэлянтами-победителями по заданию Гретты Судьи из деревни Бруннхильдар.', },
  },
  [13424] = {
    'Обратно в Яму Клыка',
    {'Чтобы оставаться в форме, нужно ежедневно соревноваться с другими хильдами!|n|nОтправляйся обратно в Яму Клыка и покажи всем, на что ты способна. Для них будет честью проиграть в поединке с тобой.', },
    {'Отправляйтесь в Яму Клыка, воспользуйтесь поводьями матриарха ледочревов и победите 6 боевых медведей Круга хильд по заданию Гретты Судьи из деревни Бруннхильдар.', },
  },
  [13425] = {
    'Смерть гнусным тварям!',
    {'Доказать свою доблесть среди равных недостаточно, дорогая сестра. Нам ведь нужно еще и сражаться с врагами!|n|nПредательницы из Валькириона по-прежнему издеваются над нашими благородными традициями, выращивая зараженных протодраконов.|n|nВозьми масло льда, которое они используют, и заморозь эти гнусные яйца.', },
    {'По заданию Гретты Судьи из деревни Бруннхильдар отправляйтесь в Валькирион и добудьте у валькирионских претенденток флаконы масла льда. Используйте флаконы масла льда, чтобы уничтожить 30 зачумленных яиц протодраконов.', },
  },
  [13426] = {
    'Ксанатавр, Свидетель',
    {'Похоже, мы тут не единственные гости. Гонец принес записку от таурена по имени Ксанатавр, который сообщает, что находится в деревне таун\'ка под названием лагерь Тунка\'ло. Записка была написана немного непонятно, но, кажется, этот самый Ксанатавр прибыл на Грозовую Гряду для изучения истории и легенд народа таунка.|n|nВстреться с ним, $N. Узнай – вдруг то, что он знает, может каким-то образом помочь нам. Из описания следует, что лагерь Тунка\'ло находится далеко на восток отсюда, над Террасой Творцов, к северу от Дун Ниффелема.', },
    {'Поговорите с Ксанатавром в лагере Тунка\'ло.', },
  },
  [13427] = {
    'К оружию! Альтеракская долина',
    {'Победите на поле боя Альтеракской долины и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.', },
    {'Победите на поле боя Альтеракской долины и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.', },
  },
  [13428] = {
    'К оружию! Альтеракская долина',
    {'Мы почти изгнали врагов, что вторглись в Альтеракскую долину из Грозовой Вершины. Теперь надо перебросить наши силы на помощь клану Северного Волка.|n|nРешительная победа позволит нам высвободить ресурсы, необходимые для сокрушения этих подонков из Альянса на всех остальных фронтах.|n|nСтупай, $N. Заслужи великую честь, откликнувшись на зов отважных воинов клана Северного Волка.', },
    {'Победите на поле боя Альтеракской долины и вернитесь к ордынскому вестнику войны в любую из столиц Орды, на Озеро Ледяных Оков, в Даларан или в Шаттрат.', },
  },
  [13429] = {
    'Отвлекающий маневр',
    {'<Кси\'ри излучает пульсирующее сияние, отдавая приказания войскам Алдоров и Провидцев. Армия Кси\'ри готова отбросить силы Иллидана и тем самым отвлечь их, чтобы Акама мог проникнуть в храм. Наару ждет вашего сигнала, чтобы начать атаку.>', },
    {'Убедитесь, что Акама и Майев вошли в Черный храм в долине Призрачной Луны после того, как войска Кси\'ри совершат отвлекающий маневр.', },
  },
  [13430] = {
    'Испытание наару: Магтеридон',
    {'Прежде чем наару признают тебя достойным, тебе предстоит пройти четыре испытания.|n|nОсталось лишь одно препятствие, $Gсмертный:смертная;. Собери армию побольше и отправляйся в логово Магтеридона в глубины Цитадели Адского Пламени. Пробейся в центральный чертог и убей гнусного сеятеля скверны!', },
    {'По заданию А\'дала из Шаттрата убейте Магтеридона.', },
  },
  [13431] = {
    'Дубина Кардеша',
    {'Для создания оружия мне необходимы эталоны стихий. Принеси мне их!|n|nЭталон земли ты найдешь в логове Груула Драконобоя в Острогорье.|n|nЭталон огня – это сердце существа, именуемого Ночной Погибелью. Это легендарное чудовище по слухам обитает в священных залах пророка Медива.|n|nПоторопись!', },
    {'Принесите эталоны земли и огня Скартису Еретику в Узилище (героический уровень сложности) в Резервуар Кривого Клыка.', },
  },
  [13432] = {
    'Сосуды Вечности',
    {'Иллидан наполнил семь сосудов из Источника Вечности. Три из них он вылил в озеро на горе Хиджал и создал второй Источник. Долгое время считалось, что остальные четыре сосуда были утрачены.|n|nНо после того как открылся Темный портал, мы узнали, что Иллидан отдал по одному сосуду своим лейтенантам Кел\'тасу и Вайш. Найди эти сосуды и принеси нам. Без них мы не можем открыть временные проходы к событиям, так или иначе связанным с горой Хиджал, – ни к недавним, ни к древним. Мы должны позаботиться о том, чтобы ничто не смогло изменить исход битвы за Хиджал.', },
    {'Соридорми из Пещер Времени желает, чтобы вы принесли ей неполный фиал Леди Вайш из Резервуара Кривого Клыка и неполный фиал Кель\'таса из Крепости Бурь.', },
  },
