  [13772] = {
    'Великая битва',
    {'Великая битва – одно из самых важных соревнований турнира. Победа достанется нелегко, но я в тебе не сомневаюсь. Продолжай тренировки верхом до тех пор, пока не сможешь действовать как одно целое со своим верховым животным. |n|nЯ помогу тебе подготовиться к битве. Иди в стойла за павильоном, оседлай ящера Черного Копья и брось вызов искателям славы. Ты найдешь их прямо за этой палаткой на Арене искателей славы Орды.', },
    {'Принесите три знака искателя славы Гаджу в шатер Орды на Ристалище Серебряного турнира.|n|nЕсли вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в Павильоне Похитителей Солнца.', },
  },
  [13773] = {
    'Клинок, достойный чемпиона',
    {'Ходят слухи, что чемпионы Альянса отправились на поиски древних клинков для своих бойцов. Нельзя допустить, чтобы они получили столь значительное преимущество!|n|nЕсть одна древняя легенда о деве из Седых холмов, которая охраняет могущественный клинок. Говорят, будто страшное проклятие превратило ее в лягушку, чтобы никто больше не смог коснуться этого меча. Теперь она живет среди прудовых лягушек на берегу Ясеневого озера, что к востоку от Ясеневой заставы... И только поцелуй любви, дарованный от чистого сердца, может разрушить злые чары. Только не забудь воспользоваться этим бальзамом для губ – иначе покроешься бородавками.', },
    {'Раздобудьте меч Ясеневого озера и принесите его Руноку Буйногривому в Павильон Похитителей Солнца на Ристалище Серебряного турнира.', },
  },
  [13774] = {
    'Достойное оружие',
    {'Что за невезение!|n|nМой турнирный клинок куда-то делся, а сражение должно состояться сегодня днем!|n|nОдин бард рассказал мне, что некая дева дарит путникам ценные вещицы в обмен на букетик зимних гиацинтов. Эти цветы растут только на льду, идущем вниз по реке от Железной плотины, на северо-западе от границы между Ледяной Короной и лесом Хрустальной Песни. Собери цветы и отнеси их к озеру Драк\'Мар, оно расположено в северо-восточной части Драконьего Погоста, почти на границе с Зул\'Драком и Седыми холмами.', },
    {'Принесите меч Драк\'Мара Руноку Буйногривому в Павильон Похитителей Солнца на Ристалище Серебряного турнира.', },
  },
  [13775] = {
    'Клинок Зимы',
    {'Проклятый рыцарь смерти сломал мой клинок.|n|nВ центре озера Дыхания Зимы в ледяном плену томится прекрасная дева. Она – хранительница древнего меча, и отдаст его тому, кто ее освободит.|n|nНа юге Леса Хрустальной Песни, над выходом из ущелья Порочных Кристаллов, ты найдешь лорда Вечнопылающего. Убей его, забери жгучий уголь и с его помощью освободи деву. Докажи, что ты $Gдостоин:достойна; этого меча.', },
    {'Рунок Буйногривый из Павильона Похитителей Солнца на Ристалище Серебряного турнира просит вас принести Клинок Зимы.', },
  },
  [13776] = {
    'Теория и практика',
    {'Турнир – это возможность помериться силой с другими героями, но стоит помнить и о том, что главный враг – Плеть – не дремлет. Ты оттачиваешь мастерство в поединках с товарищами, но тебе столь же необходимо совершенствоваться в битвах с неприятелем.|n|nОтправляйся на юго-запад Долины павших героев, что к северу от Корп\'ретара – там приспешники Плети поднимают из небытия павших героев и обращают их против нас. Окажи честь нашим союзникам и упокой этих слуг Плети, тем самым подготовившись к настоящей битве.', },
    {'Убейте 10 обращенных героев по заданию Дерна Тотема Ярости из Павильона Похитителей Солнца на Ристалище Серебряного турнира.', },
  },
  [13777] = {
    'Великая битва',
    {'Великая битва – одно из самых важных соревнований турнира. Победа достанется нелегко, но я в тебе уверена. Продолжай тренировки верхом, до тех пор, пока не сможешь действовать как одно целое со своим верховым животным.|n|nЯ помогу тебе подготовиться к битве. Иди в стойла за павильоном, оседлай мулгорского кодо и брось вызов искателям славы. Ты найдешь их прямо за этой палаткой на Арене искателей славы Орды.', },
    {'Принесите три знака искателя славы Анке Точеное Копыто в шатер Орды на Ристалище Серебряного турнира.|n|nЕсли вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в Павильоне Похитителей Солнца.', },
  },
  [13778] = {
    'Клинок, достойный чемпиона',
    {'Ходят слухи, что чемпионы Альянса отправились на поиски древних клинков для своих бойцов. Нельзя допустить, чтобы они получили столь значительное преимущество!|n|nЕсть одна древняя легенда о деве из Седых холмов, которая охраняет могущественный клинок. Говорят, будто страшное проклятие превратило ее в лягушку, чтобы никто больше не смог коснуться этого меча. Теперь она живет среди прудовых лягушек на берегу Ясеневого озера, что к востоку от Ясеневой заставы... И только поцелуй любви, дарованный от чистого сердца, может разрушить злые чары. Только не забудь воспользоваться этим бальзамом для губ – иначе покроешься бородавками.', },
    {'Раздобудьте меч Ясеневого озера и принесите его стражу смерти Визери в Павильон Похитителей Солнца на Ристалище Серебряного турнира.', },
  },
  [13779] = {
    'Достойное оружие',
    {'Что за невезение!|n|nМой турнирный клинок куда-то делся, а сражение должно состояться сегодня днем!|n|nОдин бард рассказал мне, что некая дева дарит путникам ценные вещицы в обмен на букетик зимних гиацинтов. Эти цветы растут только на льду, идущем вниз по реке от Железной плотины, на северо-западе от границы между Ледяной Короной и лесом Хрустальной Песни. Собери цветы и отнеси их к озеру Драк\'Мар, оно расположено в северо-восточной части Драконьего Погоста, почти на границе с Зул\'Драком и Седыми холмами.', },
    {'Принесите меч Драк\'Мара Стражу смерти Визери на Ристалище Серебряного турнира.', },
  },
  [13780] = {
    'Клинок Зимы',
    {'Проклятый рыцарь смерти сломал мой клинок.|n|nВ центре озера Дыхания Зимы в ледяном плену томится прекрасная дева. Она – хранительница древнего меча, и отдаст его тому, кто ее освободит.|n|nНа юге Леса Хрустальной Песни, над выходом из ущелья Порочных Кристаллов, ты найдешь лорда Вечнопылающего. Убей его, забери жгучий уголь и с его помощью освободи деву. Докажи, что ты $Gдостоин:достойна; этого меча.', },
    {'Страж смерти Визери из Павильона Похитителей Солнца на Ристалище Серебряного турнира просит вас принести Клинок Зимы.', },
  },
  [13781] = {
    'Теория и практика',
    {'Турнир – это возможность помериться силой с другими героями, но стоит помнить и о том, что главный враг – Плеть – не дремлет. Ты оттачиваешь мастерство в поединках с товарищами, но тебе столь же необходимо совершенствоваться в битвах с неприятелем.|n|nОтправляйся на юго-запад Долины павших героев, что к северу от Корп\'ретара – там приспешники Плети поднимают из небытия павших героев и обращают их против нас. Окажи честь нашим союзникам и упокой этих слуг Плети, тем самым подготовившись к настоящей битве.', },
    {'Убейте 10 обращенных героев по заданию Сары Чолк из Павильона Похитителей Солнца на Ристалище Серебряного турнира.', },
  },
  [13782] = {
    'Великая битва',
    {'Великая битва – одно из самых важных соревнований турнира. Победа достанется нелегко, но я в тебе уверен. Продолжай тренировки верхом, до тех пор, пока не сможешь действовать как одно целое со своим верховым животным.|n|nЯ помогу тебе подготовиться к битве. Иди в стойла и оседлай боевого коня Отрекшихся и брось вызов искателям славы. Ты найдешь их прямо за этой палаткой на Арене искателей славы Орды.', },
    {'Принесите три знака искателя славы дрессировщику Дречу в шатер Орды на Ристалище Серебряного турнира.|n|nЕсли вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в Павильоне Похитителей Солнца.', },
  },
  [13783] = {
    'Клинок, достойный чемпиона',
    {'Ходят слухи, что чемпионы Альянса отправились на поиски древних клинков для своих бойцов. Нельзя допустить, чтобы они получили столь значительное преимущество!|n|nЕсть одна древняя легенда о деве из Седых холмов, которая охраняет могущественный клинок. Говорят, будто страшное проклятие превратило ее в лягушку, чтобы никто больше не смог коснуться этого меча. Теперь она живет среди прудовых лягушек на берегу Ясеневого озера, что к востоку от Ясеневой заставы... И только поцелуй любви, дарованный от чистого сердца, может разрушить злые чары. Только не забудь воспользоваться этим бальзамом для губ – иначе покроешься бородавками.', },
    {'Раздобудьте меч Ясеневого озера и принесите его Эрессее Певице Рассвета в Павильон Похитителей Солнца на Ристалище Серебряного турнира.', },
  },
  [13784] = {
    'Достойное оружие',
    {'Что за невезение!|n|nМой турнирный клинок куда-то делся, а сражение должно состояться сегодня днем!|n|nОдин бард рассказал мне, что некая дева дарит путникам ценные вещицы в обмен на букетик зимних гиацинтов. Эти цветы растут только на льду, идущем вниз по реке от Железной плотины, на северо-западе от границы между Ледяной Короной и лесом Хрустальной Песни. Собери цветы и отнеси их к озеру Драк\'Мар, оно расположено в северо-восточной части Драконьего Погоста, почти на границе с Зул\'Драком и Седыми холмами.', },
    {'Принесите меч Драк\'Мара Эрессее Певице Рассвета в Павильон Похитителей Солнца на Ристалище Серебряного турнира.', },
  },
  [13785] = {
    'Клинок Зимы',
    {'Проклятый рыцарь смерти сломал мой клинок.|n|nВ центре озера Дыхания Зимы в ледяном плену томится прекрасная дева. Она – хранительница древнего меча, и отдаст его тому, кто ее освободит.|n|nНа юге Леса Хрустальной Песни, над выходом из ущелья Порочных Кристаллов, ты найдешь лорда Вечнопылающего. Убей его, забери жгучий уголь и с его помощью освободи деву. Докажи, что ты $Gдостоин:достойна; этого меча.', },
    {'Эрессея Певица Рассвета из Павильона Похитителей Солнца на Ристалище Серебряного турнира просит вас принести Клинок Зимы.', },
  },
  [13786] = {
    'Теория и практика',
    {'Турнир – это возможность помериться силой с другими героями, но стоит помнить и о том, что главный враг – Плеть – не дремлет. Ты оттачиваешь мастерство в поединках с товарищами, но тебе столь же необходимо совершенствоваться в битвах с неприятелем.|n|nОтправляйся на юго-запад Долины павших героев, что к северу от Корп\'ретара – там приспешники Плети поднимают из небытия павших героев и обращают их против нас. Окажи честь нашим союзникам и упокой этих слуг Плети, тем самым подготовившись к настоящей битве.', },
    {'Убейте 10 обращенных героев по заданию Кетиэля Солнечного Копья из Павильона Похитителей Солнца на Ристалище Серебряного турнира.', },
  },
  [13787] = {
    'Великая битва',
    {'Великая битва – одно из самых важных соревнований турнира. Победа достанется нелегко, но я в тебе уверена. Продолжай тренироваться вместе со своим верховым животным, пока вы не будете действовать как одно целое.|n|nЯ помогу тебе подготовиться к битве и покажу, на что способны другие искатели славы. Иди в стойла за павильоном, оседлай крылобега Луносвета и брось вызов искателям славы. Они ждут тебя на Арене искателей славы Орды, прямо за этой палаткой.', },
    {'Принесите три знака искателя славы Анире Турон в Павильон Похитителей Солнца на Ристалище Серебряного турнира.|n|nЕсли вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в Павильоне Серебряного союза.', },
  },
  [13788] = {
    'Атака с воздуха',
    {'После того, как тебе удалось обнаружить лазутчика Культа Проклятых, Серебряный Авангард приказал удвоить охрану. Они не верят, что Культ остановит поражение Черного рыцаря.|n|nВскоре после этого наши воздушные разведчики видели Ледяную Пасть – змея, который возглавляет отряд наемников Культа.|n|nТы должен перехватить их до того, как они нападут на нас. Ледяную Пасть видели на юго-западе, между Железным валом и Алдур\'таром.', },
    {'Крок Гроза Плети с Ристалища Серебряного турнира просит вас уничтожить Ледяную Пасть и 3 бомбистов – сектантов.', },
  },
  [13789] = {
    'Битва на вражеской территории',
    {'Для постройки Колизея было выбрано очень опасное место, $N. За эти земли, отбитые у Плети, мы заплатили кровью и болью, но враг и сейчас не прекращает атаковать нас бесчисленным войском.Хуже того, эту ненавистную нежить поддерживают приверженцы среди Культа Проклятых.|n|nОтправляйся в Ледяную Корону, и убивай всех служителей культа Проклятых, которые тебе встретятся.', },
    {'Убейте 15 членов Культа Проклятых в Ледяной Короне по заданию Селлиана Первого Луча из Серебряного павильона на Ристалище Серебряного турнира. Вы можете найти их в любой области Ледяной Короны.', },
  },
  [13790] = {
    'На равных с чемпионами',
    {'Принесите 4 знака чемпиона Луури в павильон Серебряного союза на Ристалище Серебряного турнира.|n|nЕсли вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в павильоне.', },
    {'Принесите 4 знака чемпиона Луури в павильон Серебряного союза на Ристалище Серебряного турнира.|n|nЕсли вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в павильоне.', },
  },
  [13791] = {
    'Битва на вражеской территории',
    {'Пока мы тут играем в войну, неплохо было бы вспомнить о том, что нас окружают реальные противники. Серебряный Авангард хочет найти лучших воинов с помощью турнира, но мы можем отыскать их и среди тех, кто вернулся из настоящей битвы. Давай покажем этим паладинам, что мы можем сражаться с Плетью даже во время подготовки к состязаниям.|n|nОтправляйся в Ледяную Корону, и убивай всех служителей культа Проклятых, которые тебе встретятся. Чаще всего они бродят вокруг Алдур\'тара и Заставы Вестника Смерти.', },
    {'Убейте 15 членов Культа Проклятых в Ледяной Короне по заданию Зор\'бе Кровопускателя с Ристалища Серебряного турнира. Вы можете действовать в любой области Ледяной Короны.', },
  },
  [13792] = {
    'Бредущий Тенью',
    {'Теперь, когда демонические врата разрушены, мы должны восполнить жизненную силу природы. Сердце леса необходимо вернуть!|n|nВ этом нам поможет Гайван Бредущий Тенью, великий друид-медведь. Он отправился на юго-запад, мимо Холма Демонического Огня к Обители Дор\'Данил – именно там, глубоко под землей, хранится Сердце леса. Его оберегают друиды Ясеневого леса.|n|nРазыщи Гайвана и поведай ему о том, что случилось.', },
    {'Поговорите с Гайваном Бредущим Тенью. Его можно найти где-то рядом со входом в Обитель Дор\'Данил, что в Ясеневом лесу.', },
  },
  [13793] = {
    'На равных с чемпионами',
    {'Итак, чемпион, ты $Gосвоил:освоила; искусство верхового поединка и $Gпрошел:прошла; испытания всех уровней. Теперь настала пора убедиться, что ты можешь одолеть любого противника на турнире.|n|nПродолжай оттачивать приемы боя, узнавай больше о слабых местах своих оппонентов. Чемпионы всех городов тренируются на Арене чемпионов. Отправляйся в стойла, выбери себе ездовое животное и сразись с ними.', },
    {'Принесите 4 знака чемпиона Иллирии Приходу Тьмы на Ристалище Серебряного турнира.|n|nЕсли вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в павильоне Серебряного союза.', },
  },
  [13794] = {
    'Эдрик Чистый',
    {'Я обратилась к моим братьям из Серебряного Авангарда с просьбой обратить особое внимание на тех, кто сумел получить звание чемпиона. Эдрик Чистый, абсолютный чемпион нашего братства, лично следит за тренировками воинов из всех городов Азерота и помогает им подготовиться к главному состязанию.|n|nПожалуйста, подойди к нему и представься. Он будет рад встретиться с тобой и подготовить тебя к поединкам с величайшими воинами Азерота.', },
    {'Поговорите с Эдриком Чистым из Серебряного павильона на Ристалище Серебряного турнира.', },
  },
  [13795] = {
    'Гроза Плети',
    {'Меня просил поговорить с тобой глава делегации Рыцарей Черного Клинка. Крок Гроза Плети – могучий воин, и я не сомневаюсь, что он многого потребует от тебя, |3-6($C).|n|nРыцари Черного Клинка разбили лагерь на северной стороне Ристалища, к западу от палаток Альянса.', },
    {'Поговорите с Кроком Грозой Плети в северной стороне Ристалище Серебряного турнира.', },
  },
  [13796] = {
    'Сердце леса',
    {'Ты $Gдолжен:должна; любой ценой доставить Сердце леса Кривокрону!|n|nОскверненное Ордой, оно хранится в глубине Обители Дор\'Данил. Только Кривокрон способен очистить его от зла.|n|nНо чтобы прикоснуться к нему, тебе понадобится Сила природы. Собери несколько непорочных душ покалеченных друидов и хранителей, чтобы они смогли объединиться в Силу природы.|n|nУдачи, $N!', },
    {'Добудьте Сердце Леса.', },
  },
  [13797] = {
    'Грязные делишки',
    {'Что нужно Драаке – так это некий магнит, к которому бы притягивались демонические снаряды.|n|n<Дуран смущенно ухмыляется.>|n|nКажется, я знаю, что нам поможет.|n|nОтыщи в шахтах куски руды величиной с кулак, а я пока приготовлю особые... чары.', },
    {'Осмотрите кучки свежих обломков и найдите 10 кусков руды.', },
  },
  [13798] = {
    'Огненный ливень',
    {'Как раз вовремя, |3-6($C). Эльфы снова пошли в наступление!|n|nВозьми эту проклятую руду и пометь с ее помощью цели для Драаки.|n|nЕе снаряды попадут по мишеням, которые ты укажешь, и поразят всех находящихся рядом врагов демоническим огнем.|n|nДа-да, я знаю, что остальные с предубеждением относятся к демонической магии. Ей-богу, это все полная чепуха, но я на всякий случай превращу тебя в беса, чтобы никто тебя не узнал.', },
    {'Бросайте проклятую руду с башен Заставы Расщепленного Дерева, чтобы обозначить цели Драаке. Убейте таким образом 30 бойцов ночных эльфов и 5 гневных древней.|n|nЕсли вам надо заново принять облик беса, обратитесь к Дурану.', },
  },
  [13801] = {
    'Голоса мертвых эльфов',
    {'Т...ты это слышишь? Призраки! Ненавижу призраков!|n|nИх завывания доносятся прямо из курганов на востоке. О-о, заставь их замолчать!!!|n|nПожалуйста, $Gмилостливый господин:милостливая госпожа;, я заплачу – только пусть эти звуки более меня не мучают!', },
    {'Уничтожьте 15 любых призраков ночных эльфов в Обители Дор\'Данил.', },
  },
  [13803] = {
    'Кровь слабых',
    {'Мы знали, что эльфы не сдадутся без борьбы, но никто не ожидал, что у них хватит сил осадить Заставу Расщепленного Дерева...|n|nНу теперь-то они заплатят за свои злодеяния!|n|nСовсем рядом, в Обители Дор\'Данил хранится нечто очень ценное для эльфов: Сердце леса.|n|nМне нужен кто-то, кто сможет пробраться к реликвии и осквернить ее. И этим кем-то будешь ты, $N.|n|nНо для начала отнеси мой топор Дурану в шахты. Вскоре он прольет кровь наших врагов.', },
    {'Кадрак просит вас принести окровавленный топор Дурану на Заставу Расщепленного Дерева.', },
  },
  [13805] = {
    'Пронзи их сердце!',
    {'Вот так...|n|nКровь павших калдорай осквернена. Теперь осталось только доставить ее в Сердце леса в Обители Дор\'Данил.|n|nСвященная реликвия, над которой трясутся надменные эльфы, обернется против них. Разве не прекрасно?|n|n<Дуран зловеще смеется.>|n|nОбитель находится прямо напротив холмов на юго-востоке. Один из моих бесов уже обозначил кровью путь от входа к месту, где хранится сердце.|n|nТоропись! Кадрак ждать не будет.|n|nВперед, |3-6($C).', },
    {'Дуран хочет, чтобы вы окропили Сердце Леса оскверненной калдорайской кровью.', },
  },
  [13806] = {
    'Демоническое задание',
    {'Послушай, |3-6($C), я знаю, что все внимание сейчас обращено на Заставу Расщепленного Дерева, но если мы из-за этого забудем про порталы сатиров, то окажемся лицом к лицу с еще большей проблемой, чем осада аванпоста.|n|n<Локе с изумлением наблюдает полное отсутствие реакции на вашем лице.>|n|nТы... ты ничего не знаешь про порталы?|n|nНа северо-востоке, в районе Сатирнаара и Ксавиана сатиры пытаются призвать на помощь армаду демонов.|n|nМы должны закрыть эти порталы любой ценой. Это важнее чем все, что сейчас здесь происходит!', },
    {'Локе Окарр с Заставы Расщепленного Дерева просит вас закрыть 12 порталов сатиров в Сатирнааре и Ксавиане.', },
  },
  [13807] = {
    'FLAG: Приглашение на турнир',
    nil,
    nil,
  },
  [13808] = {
    'Миссия немыслима',
    {'У меня есть особое поручение, с которым может справиться только хорошо экипированный, отважный |3-6($C). Но, поскольку я не могу рисковать своими людьми, придется доверить это тебе...|n|nВраги напали на лесозаготовки Песни Войны и отрезали этот стратегически важный пункт от наших основных сил. В эту ловушку попал очень важный дипломат, эльфийка крови, направлявшаяся в Оргриммар.|n|nЕе необходимо освободить.|n|nСледуй по дороге на северо-восток и насыпь этот порошок в тлеющую жаровню, чтобы подать знак нашему шпиону. Выполняй все его указания.|n|n$GСвободен:Свободна;!', },
    {'Кадрак просит вас распылить секретный порошок вызова над тлеющей жаровне в Сатирнааре.', },
  },
  [13809] = {
    'Атака с воздуха',
    {'После того, как тебе удалось обнаружить лазутчика Культа Проклятых, верховный лорд Тирион Фордринг приказал удвоить охрану. Он не верит, что их остановит поражение Черного рыцаря.|n|nВскоре после этого наши воздушные разведчики видели Ледяную Пасть – змея, который возглавляет отряд наемников Культа. Его видели на юго-западе, между Железным валом и Алдур\'таром.', },
    {'Эдрик Чистый из Серебряного павильона на Ристалище Серебряного турнира просит вас уничтожить Ледяную Пасть и 3 бомбистов – сектантов.', },
  },
  [13810] = {
    'Битва на вражеской территории',
    {'Для постройки Колизея было выбрано очень опасное место, $N. За эти земли, отбитые у Плети, мы заплатили кровью и болью, но враг и сейчас не прекращает атаковать нас бесчисленным войском.Хуже того, эту ненавистную нежить поддерживают приверженцы среди Культа Проклятых.|n|nОтправляйся в Ледяную Корону, и убивай всех служителей культа Проклятых, которые тебе встретятся.', },
    {'Убейте 15 членов Культа Проклятых в Ледяной Короне по заданию Селлиана Первого Луча из Серебряного павильона на Ристалище Серебряного турнира. Вы можете найти их в любой области Ледяной Короны.', },
  },
  [13811] = {
    'На равных с чемпионами',
    {'Итак, чемпион, ты $Gосвоил:освоила; искусство верхового поединка и $Gпрошел:прошла; испытания всех уровней. Теперь настала пора убедиться, что ты можешь одолеть любого противника на турнире.|n|nПродолжай оттачивать приемы боя, узнавай больше о слабых местах своих оппонентов. Чемпионы всех городов тренируются на Арене чемпионов. Отправляйся в стойла, выбери себе ездовое животное и сразись с ними.', },
    {'Принесите 4 знака чемпиона Луури в павильон Серебряного союза на Ристалище Серебряного турнира.|n|nЕсли вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в павильоне Похитителей Солнца.', },
  },
  [13812] = {
    'Атака с воздуха',
    {'После того, как тебе удалось обнаружить лазутчика Культа Проклятых, Серебряный Авангард приказал удвоить охрану. Они не верят, что Культ остановит поражение Черного рыцаря.|n|nВскоре после этого наши воздушные разведчики видели Ледяную Пасть – змея, который возглавляет отряд наемников Культа.|n|nТы должен перехватить их до того, как они нападут на нас. Ледяную Пасть видели на юго-западе, между Железным валом и Алдур\'таром.', },
    {'Крок Гроза Плети с Ристалища Серебряного турнира просит вас уничтожить Ледяную Пасть и 3 бомбистов – сектантов.', },
  },
  [13813] = {
    'Битва на вражеской территории',
    {'Пока мы тут играем в войну, неплохо было бы вспомнить о том, что нас окружают реальные противники. Серебряный Авангард хочет найти лучших воинов с помощью турнира, но мы можем отыскать их и среди тех, кто вернулся из настоящей битвы. Давай покажем этим паладинам, что мы можем сражаться с Плетью даже во время подготовки к состязаниям.|n|nОтправляйся в Ледяную Корону, и убивай всех служителей культа Проклятых, которые тебе встретятся. Чаще всего они бродят вокруг Алдур\'тара и Заставы Вестника Смерти.', },
    {'Убейте 15 членов Культа Проклятых в Ледяной Короне по заданию Зор\'бе Кровопускателя с Ристалища Серебряного турнира. Вы можете действовать в любой области Ледяной Короны.', },
  },
  [13814] = {
    'На равных с чемпионами',
    {'Итак, чемпион, ты $Gосвоил:освоила; искусство верхового поединка и $Gпрошел:прошла; испытания всех уровней. Теперь настала пора убедиться, что ты можешь одолеть любого противника на турнире.|n|nПродолжай оттачивать приемы боя, узнавай больше о слабых местах своих оппонентов. Чемпионы всех городов тренируются на Арене чемпионов. Отправляйся в стойла, выбери себе ездовое животное и сразись с ними.', },
    {'Принесите 4 знака чемпиона Иллирии Приходу Тьмы на Ристалище Серебряного турнира.|n|nЕсли вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в павильоне Похитителей Солнца.', },
  },
  [13815] = {
    'Лесоруб',
    {'Как тебе уже сообщили, нам предстоит сопроводить дипломата из осажденного лагеря в безопасное место.|n|nТы все правильно понимаешь – миссия невыполнима. Все входы и выходы из лагеря тщательно охраняются эльфами.|n|nПоэтому сначала нам предстоит устроить диверсию и отвлечь их внимание на что-то другое.|n|nИдея проста: возьми топор и сруби несколько деревьев, над которыми они так трясутся. |n|nКак закончишь с этим делом, брось еще немного порошка в жаровню, и мы продолжим разговор.', },
    {'Крокк хочет, чтобы вы отправились на лесозаготовки Песни Войны и срубили там несколько дубов Ясеневого леса топором Расщепленного Дерева.|n|nЕсли вы вдруг потеряете секретный порошок вызова, поговорите с Кадраком на Заставе Расщепленного Дерева.', },
  },
  [13816] = {
    'Священный планетарий (героич.)',
    {'Слушай внимательно! На кону – судьба всего Азерота.|n|nТолько одно спасет нас – нужно найти Священный планетарий и помешать этому Алгалону отправить сообщение его повелителям-титанам.|n|nОтыщи Священный планетарий и возвращайся со всеми данными, которые сможешь там собрать. Может быть, мы успеем подготовиться к прибытию Алгалона.', },
    {'Найдите Священный планетарий по заданию геолога Лорен из Архива в Ульдуаре.', },
  },
  [13817] = {
    'Диск доступа к Архиву (героич.)',
    {'Платиновый диск правильной формы выглядит совершенно новым – на нем нет ни единой царапины. По краю его выгравирована руническая надпись: "АРХИВ".|n|nДолжно быть, в глубинах Ульдуара есть устройство, с помощью которого можно прочитать этот диск.', },
    {'Отнесите диск доступа к Архиву к панели управления Архивом в Ульдуаре.', },
  },
  [13818] = {
    'Алгалон (героич.)',
    {'Ты $Gсправился:справилась;, $N. Теперь возьми печати, отнеси их к панели управления Архивом и попытайся получить доступ к Священному планетарию.|n|nПоторопись, $Gдруг:подруга; – дорога каждая секунда.', },
    {'Принесите печати хранителей к панели управления Архивом в Ульдуаре.', },
  },
  [13819] = {
    'Все хорошо, что хорошо кончается (героич.)',
    {'Мы должны поторопиться, $N – надо передать код отклика из Даларана как можно скорее.|n|nОтнеси его Ронину, я встречу тебя там.', },
    {'Доставьте код отклика "Альфа" Ронину в Даларан.', },
  },
  [13820] = {
    'Семья Рвизасовов',
    {'Верховный лорд поручил мне завершить строительство Колизея как можно быстрее. Мы бросили все наши силы на эту работу, но очень скоро обнаружили, что нам потребуется помощь в доставке материалов. Для этого я наняла парочку гоблинов – Беззла Рвизасова и его брата Боззла.|n|nОни руководят строительством юго-восточной части Ристалища. Поговори с Беззлом и узнай, не нужна ли им помощь в доставке материалов.', },
    {'Поговорите с Беззлом Рвизасовом на Ристалище Серебряного турнира.', },
  },
  [13821] = {
    'Печать Фрейи (героич.)',
    {'Печать Фрейи достать будет сложнее всего.|n|nСогласно данным из Архива, сущность печати связана с тремя старшими слугами Фрейи – Ярким Листом, Железной Ветвью и Каменной Корой. Если хоть один из них пострадает, сущность печати будет повреждена.|n|nНо если ты пощадишь слуг, силы Фрейи приумножатся.|n|nЧто еще сказать, $N... оказались мы между молотом и наковальней.', },
    {'Добудьте печать Фрейи по заданию геолога Лорен.|n|nЗа дополнительными сведениями обратитесь к панели управления Архивом.', },
  },
  [13822] = {
    'Печать Ходира (героич.)',
    {'Печать Ходира будет нелегко раздобыть. Во-первых, тебе придется одолеть самого Ходира. А во-вторых, одолеть его нужно до того, как он уничтожит сундук с печатью!|n|nВоспользуйся панелью управления Архивом, чтобы получить дополнительные сведения. Эта премудрая штуковина стоит всех библиотек мира!', },
    {'Добудьте печать Ходира по заданию геолога Лорен.|n|nЗа дополнительными сведениями обратитесь к панели управления Архивом.', },
  },
  [13823] = {
    'Печать Торима (героич.)',
    {'Торим не в себе, $N. Он во власти темных сил.|n|nТемная сущность приняла обличье его погибшей жены, Сиф.|n|nНельзя позволить иллюзии свести его с ума. Если это случится, то мы никогда не сможем найти печать Торима!|n|nВразуми его, и побыстрее.|n|nКак обычно, за подробностями этой жуткой истории можешь обратиться к панели управления Архивом... но они вряд ли тебе понравятся.', },
    {'Добудьте печать Торима по заданию геолога Лорен.|n|nЗа дополнительными сведениями обратитесь к панели управления Архивом.', },
  },
  [13824] = {
    'Печать Мимирона (героич.)',
    {'Мимирон хитер – в его комнате установлен какой-то механизм самоуничтожения.|n|nЕсли хочешь получить его печать, тебе придется победить его до того, как механизм завершит свой цикл. Если тебе нужно больше информации – воспользуйся панелью управления Архивом.', },
    {'Добудьте печать Мимирона по заданию геолога Лорен.|n|nЗа дополнительными сведениями обратитесь к панели управления Архивом.', },
  },
  [13825] = {
    'Мидии с сюрпризом',
    nil,
    nil,
  },
  [13826] = {
    'Нат Пэгл, великий рыболов',
    nil,
    nil,
  },
  [13827] = {
    'Сокровище!',
    nil,
    nil,
  },
  [13828] = {
    'Мастер ближнего боя',
    {'Суть турнира – это верховой поединок. Возьми копье и оседлай кель\'дорайского скакуна – он ждет тебя снаружи.|n|nВерхом на нем отправляйся к Джерану Локвуду, его можно найти с северной стороны Ристалища, на тренировочной площадке к востоку от Арены претендентов. Джеран обучит тебя тонкостям ведения ближнего боя, чтобы поединок не закончился для тебя с первым ударом.', },
    {'Вооружитесь копьем и оседлайте кель\'дорайского скакуна – он ждет вас снаружи павильона. Поговорите с Джераном Локвудом и отработайте прием "Выпад" 5 раз на манекене для ближнего боя. После этого вернитесь к чародею Таэлису в Павильон Серебряного союза на Ристалище Серебряного турнира.', },
  },
  [13829] = {
    'Мастер ближнего боя',
    {'Суть турнира – это верховой поединок. Возьми копье и оседлай крылобега Похитителей Солнца – он ждет тебя снаружи.|n|nВерхом на нем отправляйся к Джерану Локвуду, его можно найти с северной стороны Ристалища, на тренировочной площадке к востоку от Арены претендентов. Джеран обучит тебя тонкостям ведения ближнего боя, чтобы поединок не закончился для тебя с первым ударом.', },
    {'Вооружитесь копьем и оседлайте крылобега Похитителей Солнца – он ждет вас снаружи павильона. Поговорите с Джераном Локвудом и отработайте прием "Выпад" 5 раз на манекене для ближнего боя. После этого вернитесь к магистру Эдиену Солнечной Низине в шатер Орды на Ристалище Серебряного турнира.', },
  },
  [13830] = {
    'Рыба-призрак',
    {'$GВсякий стоящий рыболов:Всякая стоящая рыбачка; в Нордсколе знает о карликовой рыбе-прилипале, называемой среди знатоков "сосокунем". Она несъедобна, но алхимики часто используют ее для приготовления зелий.|n|nНо речь не об этом. Если ты внимательно присмотришься к косяку прилипал в водах Слияния рек в низине Шолазар, то заметишь затесавшуюся среди них рыбу-призрака. На воздухе она становится прозрачной и в конце концов попросту исчезает. Многие считают, что она возвращается в Шолазар, но есть и те, кто сочиняет о ней всякие небылицы.|n|nВылови эту рыбу и раскрой ее секрет!', },
    {'Раскройте тайну рыбы-призрака по просьбе Марсии Чейз из Даларана.', },
  },
  [13831] = {
    'Странное предписание',
    {'Неподалеку стоит грубо вытесанная аптекарская скамья, вся заваленная исписанными пергаментами и причудливыми склянками. Похоже, Отрекшиеся также изучали работы Грязного Копыта. Вы хватаете несколько свитков, которые кажутся наиболее важными, и готовитесь разгромить лабораторию. Несомненно, Целителя Деревьев заинтересует ваша находка.', },
    {'Доставьте записи аптекаря Тарнариуну Исцелителю Деревьев в Лор\'данел.', },
  },
  [13832] = {
    'Звезда сточных вод',
    {'Представляешь, некоторые граждане ловят в Стоках Даларана гигантских крыс и рыб-мутантов. А ведь в здешних водах можно найти столько ценного! Обманутые любовники, пойманные с поличным воры, неосторожные пьяницы – каждый сбрасывает или роняет сюда какую-нибудь приятную мелочь.|n|nДостаточно просто достать крючком до дна и не дергать леску слишком резко, когда что-нибудь попадется. Попробуй, $N. Что поймаешь – тащи ко мне. Будем торговаться!', },
    {'Принесите Марсии Чейз в Даларан ржавое украшение.', },
  },
  [13833] = {
    'Густая кровь',
    {'Как можно понять из названия, ужорь – это весьма прожорливая рыбешка. Лекари используют ее для варки исцеляющих составов, поэтому если хочешь заработать – иди за ужрем-кровопийцей.|n|nОни падки на кровь, поэтому проще всего убить какую-нибудь зверушку в Борейской тундре, намазаться ее кровью, затем искупаться в озерной воде и начать рыбачить.', },
    {'Принесите Марсии Чейз в Даларан 5 ужрей-кровопийц.', },
  },
  [13834] = {
    'Опасный деликатес',
    {'Чем ценнее улов, тем опаснее рыбалка. В озере Ледяных Оков водится редкая рыба, но ловить ее примется лишь безрассудный.|n|nЯ толкую о террорели. Она страшно ядовита и ужасно вкусна. Вот принесешь мне ее – тогда пойдет другой разговор.', },
    {'Принесите Марсии Чейз в Даларан 10 террорелей.', },
  },
  [13835] = {
    'Мастер дальнего боя',
    {'Чтобы преуспеть в верховом поединке, нужно лишить противника защиты. Возьми вот это копье и оседлай кель\'дорайского скакуна – он ждет тебя снаружи.|n|nПотом езжай к Валису Ловцу Ветра, его можно найти с северной стороны Ристалища, на тренировочной площадке к востоку от Арены претендентов. Валис научит тебя приему "Удар по щиту" – это поможет тебе ослабить противника.', },
    {'Вооружитесь копьем и оседлайте кель\'дорайского скакуна – он ждет вас снаружи павильона. Поговорите с Валисом Ловцом Ветра и отработайте "Удар по щиту" 2 раза на мишени для дальнего боя. После этого вернитесь к разведчице Шалиндрии на Ристалище Серебряного турнира.', },
  },
  [13836] = {
    'Обезручен!',
    {'До меня дошли слухи о трагедии в даларанской тюрьме – особо опасный заключенный отгрыз руку одному из охранников и выбросил ее в воду.|n|nДоктора из больницы скорой помощи говорят, что ее еще можно пришить.|n|nДостаточно порыбачить хорошенько возле тюрьмы и, ставлю свой любимый гарпун, рука непременно всплывет на поверхность. Найди руку и принеси ее Олисарре Доброй в Даларан. Остальное она сделает сама.', },
    {'Принесите откушенную руку Олисарре Доброй в Даларан.', },
  },
  [13837] = {
    'Мастер стремительной атаки',
    {'Самым эффективным приемом в верховом поединке является "Рывок". Возьми копье и оседлай кель\'дорайского скакуна – он ждет тебя снаружи.|n|nВерхом на нем отправляйся к Рагану Сталебрюху, его можно найти с северной стороны Ристалища, на тренировочной площадке к востоку от Арены претендентов. Он научит тебя этому удару и покажет основные стратегические приемы.', },
    {'Вооружитесь копьем и оседлайте кель\'дорайского скакуна – он ждет вас снаружи павильона. Поговорите с Раганом Сталебрюхом и отработайте "Рывок" 2 раза на манекене для стремительной атаки. После этого вернитесь к Аварету Молниеносному Удару в шатер Альянса на Ристалище Серебряного турнира.', },
  },
  [13838] = {
    'Мастер дальнего боя',
    {'Чтобы преуспеть в верховом поединке, нужно лишить противника защиты. Возьми вот это копье и оседлай крылобега Похитителей Солнца – он ждет тебя снаружи.|n|nПотом езжай к Валису Ловцу Ветра, его можно найти с северной стороны Ристалища, на тренировочной площадке к востоку от Арены претендентов. Валис научит тебя приему "Удар по щиту" – это поможет тебе ослабить противника.', },
    {'Вооружитесь копьем и оседлайте крылобега Похитителей Солнца – он ждет вас снаружи павильона. Поговорите с Валисом Ловцом Ветра и 2 раза отработайте "Удар по щиту" на мишени для дальнего боя. После этого вернитесь к Галатии Сияющий Рассвет в шатер Орды на Ристалище Серебряного турнира.', },
  },
  [13839] = {
    'Мастер стремительной атаки',
    {'Самым эффективным приемом в верховом поединке является "Рывок". Возьми копье и оседлай крылобега Похитителей Солнца – он ждет тебя снаружи.|n|nВерхом на нем отправляйся к Рагану Сталебрюху, его можно найти с северной стороны Ристалища, на тренировочной площадке к востоку от Арены претендентов. Он научит тебя этому удару и покажет основные стратегические приемы.', },
    {'Вооружитесь копьем и оседлайте крылобега Похитителей Солнца – он ждет вас снаружи павильона. Поговорите с Раганом Сталебрюхом и отработайте прием "Рывок" 2 раза на манекене для стремительной атаки. После этого вернитесь к Амариэлю Верному Солнцу в шатер Орды на Ристалище Серебряного турнира.', },
  },
  [13840] = {
    nil,
    {'"Куд... куд... куд... КУДАХ!|n|nКуд... куд... куд."|n|nКурица смотрит на вас одним глазом, затем начинает скрести когтями землю. Кажется, она пытается что-то написать, но вы не можете разобрать буквы. Может быть... С-А-Л-Ь-Д-Е-Н? Не дожидаясь расспросов, курица разворачивается и отправляется по своим куриным делам.', },
    {'Найдите немного цыплячьего корма и вернитесь к вашей курочке-подружке. Когда найдете курицу, покажите, как вы рады ее видеть (эмоция "/рад"), а потом накормите специальным цыплячьим кормом.', },
  },
  [13841] = {
    'Искренние извинения',
    {'Похоже, мне конец... Возможно, мои действия были не настолько продуманными, как мне казалось. |n|nНо, во всяком случае, нам удалось отразить атаку, которая могла бы стереть с лица земли Заставу Расщепленного Дерева. Будем надеяться, что главнокомандующий Адский Крик расценит это именно так.|n|nНе сомневаюсь, скоро меня вызовут в Оргриммар и потребуют отчета в моих действиях.|n|nПрошу тебя, $N, постарайся прибыть туда раньше меня и передать это письмо Гаррошу.|n|nНадеюсь, тебе удастся смягчить его гнев.', },
    {'Драака просит вас передать Гаррошу Адскому Крику объяснительную записку.', },
  },
  [13842] = {
    'Искупление',
    {'Демоны желают только одного: вновь поставить нас в зависимость от своей проклятой магии. Эта кабала может привести к порабощению всей расы орков.|n|nХочешь, чтобы Драака избежала наказания? Найди демона, который манипулировал ей, и уничтожь эту тварь.|n|nЕсли же ты не принесешь мне голову демона, вам с Драакой не поздоровится!', },
    {'Поговорите с Дураном в шахте Расщепленного Дерева.', },
  },
  [13843] = {
    'Комплект для сборки Хламобота',
    {'Копаясь в базе данных панели управления прототипом, вы находите чертежи комплекта для сборки Хламобота. Имея достаточно навыков в инженерном деле, вы можете изучить их и самостоятельно производить комплекты для сборки.', },
    {'Изучите данные панели управления прототипом в библиотеке Изобретателя.', },
  },
  [13844] = {
    'Сокровища Алталакса',
    {'Прежде, чем ты снова ринешься в бой, |3-6($C), выслушай то, что я хочу тебе сказать, ибо это важно. Мои разведчики докладывают, что Отрекшиеся исследуют разрушенную башню Алталакса на юге.|n|nПеред нападением в этом промозглом месте был расквартирован дивизион Совета Теней под командованием павшего высокорожденного Атрикуса Нарассина. Нарассин давно покоится в земле, но если какие-то его бумаги уцелели, мы не должны допустить, чтобы они попали в руки врага. Добудь записи о его исследованиях и убей командира Отрекшихся, который привел нежить к этим руинам.', },
    {'Найдите фолиант Нарассина среди руин Алталакса и убейте предводителя Отрекшихся Тигана Холловея.', },
  },
  [13845] = {
    'Запечатанный фиал с ядом',
    {'Этот яд, похоже, смертельно опасен. Может быть, кто-нибудь в Даларане заинтересуется им.', },
    {'Принесите запечатанный фиал с ядом алхимику Синесре в Стоки Даларана.', },
  },
  [13846] = {
    'Вклад в общее дело',
    {'Лучшие из лучших чемпионов ежедневно приходят к часовне, чтобы послушать речи исповедницы.|n|n$GВидел:Видела; бы ты, как это их вдохновляет! Они находят в себе силы продолжать сражение за дело Серебряного Авангарда и вносят посильный вклад в наше общее дело.|n|nМожет быть, и ты, $N, внесешь свою лепту? Пожертвуй немного золота на нужды Авангарда!', },
    {'Поговорите с оруженосцем Арти и пожертвуйте 10 золотых на нужды Серебряного Авангарда.', },
  },
  [13847] = {
    'У вражеских врат',
    {'Несмотря на проводимый турнир, Серебряный Авангард продолжает подготовку к штурму цитадели Ледяной Короны.|n|nНа юго-западе Ледяной Короны, во Дворе Костей, отряд отважных рыцарей разбил лагерь прямо к югу от Корп\'ретара. Бери копье, седлай боевого скакуна Серебряного Рассвета и отправляйся на истребление подданных Короля-лича.|n|nПусть тебя не смущают костяные пехотинцы, $N – копыта твоего скакуна легко переломают их истлевшие кости.', },
    {'Убейте 15 костяных пехотинцев, 10 костяных разведчиков и 3 костяных лейтенантов по заданию капитана Джозефа Холли из Павильона Серебряного союза на Ристалище Серебряного турнира.', },
  },
  [13848] = {
    'Плохие новости',
    {'C самого начала осады Заставы Расщепленного Дерева от нас не поступало никаких известий. Командир Мрачный Клык, наверное, сходит с ума от беспокойства.|n|nЯ хочу отправить тебя на Зорамское взморье с докладом. Увы, это будут печальные вести, но, во всяком случае, он будет знать, что происходит.|n|nПоговори с Вульгрой, когда будешь $Gготов:готова; отправиться в путь.', },
    {'Кадрак просит вас поговорить с командиром Мрачный Клык на Зорамском взморье.', },
  },
  [13849] = {
    'Астранаар в огне!',
    {'$C, в Астранааре пожар!|n|nБыстрее, хватай ведро с водой и туши огонь, пока еще можно что-то спасти!', },
    {'Потушите 15 пожаров.', },
  },
  [13850] = {
    'Иммунитет к яду',
    {'Хочешь купить ядошкурого равазавра? Тогда я должен тебя предупредить.|n|nЭти зверюшки ядовиты от кончика носа до кончика хвоста: ядовитая кровь, ядовитая слюна, ядовитая шкура. Заберись на него, и через несколько часов ты труп.|n|nЧтобы этого не произошло, нужно выработать иммунитет к их яду, а это – долгий, очень долгий процесс... нужно, чтобы кровь равазавра попала на твою кожу бесчисленное количество раз. Если хочешь попробовать, то отправляйся на северо-запад отсюда – равазавры во множестве обитают на севере Топей.', },
    {'Мор\'век из Кратера Ун\'Горо утверждает, что вам необходимо 20 раз отравиться кровью ядошкурого равазавра, чтобы выработать иммунитет к яду. Чтобы кровь равазавра попала на вашу кожу, нападите на него.', },
  },
  [13851] = {
    'У вражеских врат',
    {'Несмотря на проводимый турнир, Серебряный Авангард продолжает подготовку к штурму цитадели Ледяной Короны.|n|nНа юго-западе Ледяной Короны, во Дворе Костей, отряд отважных рыцарей разбил лагерь прямо к югу от Корп\'ретара. Бери копье, седлай боевого скакуна Серебряного Рассвета и отправляйся на истребление подданных Короля-лича.|n|nПусть тебя не смущают костяные пехотинцы, $N – копыта твоего скакуна легко переломают их истлевшие кости.', },
    {'Убейте 15 костяных пехотинцев, 10 костяных разведчиков и 3 костяных лейтенантов по заданию Клары Взубногой из Павильона Серебряного союза на Ристалище Серебряного турнира.', },
  },
  [13852] = {
    'У вражеских врат',
    {'Несмотря на проводимый турнир, Серебряный Авангард продолжает подготовку к штурму цитадели Ледяной Короны.|n|nНа юго-западе Ледяной Короны, во Дворе Костей, отряд отважных рыцарей разбил лагерь прямо к югу от Корп\'ретара. Бери копье, седлай боевого скакуна Серебряного Рассвета и отправляйся на истребление подданных Короля-лича.|n|nПусть тебя не смущают костяные пехотинцы, $N – копыта твоего скакуна легко переломают их истлевшие кости.', },
    {'Убейте 15 костяных пехотинцев, 10 костяных разведчиков и 3 костяных лейтенантов по заданию Фликля Гайковерта из Павильона Серебряного союза на Ристалище Серебряного турнира.', },
  },
  [13853] = {
    'Возвращение огня',
    {'Пожар практически потушен, но мы должны что-то сделать с этими ветрокрылами!|n|nБыстрее, $N, прыгай в метатель глеф и обстреляй их!', },
    {'Подстрелите 15 геллионов Адского Крика и их ветрокрылов-наблюдателей с помощью метателя из Астранаара.', },
  },
  [13854] = {
    'У вражеских врат',
    {'Несмотря на проводимый турнир, Серебряный Авангард продолжает подготовку к штурму цитадели Ледяной Короны.|n|nНа юго-западе Ледяной Короны, во Дворе Костей, отряд отважных рыцарей разбил лагерь прямо к югу от Корп\'ретара. Бери копье, седлай боевого скакуна Серебряного Рассвета и отправляйся на истребление подданных Короля-лича.|n|nПусть тебя не смущают костяные пехотинцы, $N – копыта твоего скакуна легко переломают их истлевшие кости.', },
    {'Убейте 15 костяных пехотинцев, 10 костяных разведчиков и 3 костяных лейтенантов по заданию Рании из Павильона Серебряного союза на Ристалище Серебряного турнира.', },
  },
  [13855] = {
    'У вражеских врат',
    {'Несмотря на проводимый турнир, Серебряный Авангард продолжает подготовку к штурму цитадели Ледяной Короны.|n|nНа юго-западе Ледяной Короны, во Дворе Костей, отряд отважных рыцарей разбил лагерь прямо к югу от Корп\'ретара. Бери копье, седлай боевого скакуна Серебряного Рассвета и отправляйся на истребление подданных Короля-лича.|n|nПусть тебя не смущают костяные пехотинцы, $N – копыта твоего скакуна легко переломают их истлевшие кости.', },
    {'Убейте 15 костяных пехотинцев, 10 костяных разведчиков и 3 костяных лейтенантов по заданию Айре Устремленной к Звездам из Павильона Серебряного союза на Ристалище Серебряного турнира .', },
  },
  [13856] = {
    'У вражеских врат',
    {'Несмотря на проводимый турнир, Серебряный Авангард продолжает подготовку к штурму цитадели Ледяной Короны.|n|nНа юго-западе Ледяной Короны, во Дворе Костей, отряд отважных рыцарей разбил лагерь прямо к югу от Корп\'ретара. Бери копье, седлай боевого скакуна Серебряного Рассвета и отправляйся на истребление подданных Короля-лича.|n|nПусть тебя не смущают костяные пехотинцы, $N – копыта твоего скакуна легко переломают их истлевшие кости.', },
    {'Убейте 15 костяных пехотинцев, 10 костяных разведчиков и 3 костяных лейтенантов по заданию Моры Сестры Воргов из Павильона Похитителей Солнца на Ристалище Серебряного турнира.', },
  },
  [13857] = {
    'У вражеских врат',
    {'Несмотря на проводимый турнир, Серебряный Авангард продолжает подготовку к штурму цитадели Ледяной Короны.|n|nНа юго-западе Ледяной Короны, во Дворе Костей, отряд отважных рыцарей разбил лагерь прямо к югу от Корп\'ретара. Бери копье, седлай боевого скакуна Серебряного Рассвета и отправляйся на истребление подданных Короля-лича.|n|nПусть тебя не смущают костяные пехотинцы, $N – копыта твоего скакуна легко переломают их истлевшие кости.', },
    {'Убейте 15 костяных пехотинцев, 10 костяных разведчиков и 3 костяных лейтенантов по заданию Гаджу из Павильона Похитителей Солнца на Ристалище Серебряного турнира.', },
  },
  [13858] = {
    'У вражеских врат',
    {'Несмотря на проводимый турнир, Серебряный Авангард продолжает подготовку к штурму цитадели Ледяной Короны.|n|nНа юго-западе Ледяной Короны, во Дворе Костей, отряд отважных рыцарей разбил лагерь прямо к югу от Корп\'ретара. Бери копье, седлай боевого скакуна Серебряного Рассвета и отправляйся на истребление подданных Короля-лича.|n|nПусть тебя не смущают костяные пехотинцы, $N – копыта твоего скакуна легко переломают их истлевшие кости.', },
    {'Убейте 15 костяных пехотинцев, 10 костяных разведчиков и 3 костяных лейтенантов по заданию Анки Точеное Копыто из Павильона Похитителей Солнца на Ристалище Серебряного турнира.', },
  },
  [13859] = {
    'У вражеских врат',
    {'Несмотря на проводимый турнир, Серебряный Авангард продолжает подготовку к штурму цитадели Ледяной Короны.|n|nНа юго-западе Ледяной Короны, во Дворе Костей, отряд отважных рыцарей разбил лагерь прямо к югу от Корп\'ретара. Бери копье, седлай боевого скакуна Серебряного Рассвета и отправляйся на истребление подданных Короля-лича.|n|nПусть тебя не смущают костяные пехотинцы, $N – копыта твоего скакуна легко переломают их истлевшие кости.', },
    {'Убейте 15 костяных пехотинцев, 10 костяных разведчиков и 3 костяных лейтенантов по заданию Аниры Турон из Павильона Похитителей Солнца на Ристалище Серебряного турнира.', },
  },
  [13860] = {
    'У вражеских врат',
    {'Несмотря на проводимый турнир, Серебряный Авангард продолжает подготовку к штурму цитадели Ледяной Короны.|n|nНа юго-западе Ледяной Короны, во Дворе Костей, отряд отважных рыцарей разбил лагерь прямо к югу от Корп\'ретара. Бери копье, седлай боевого скакуна Серебряного Рассвета и отправляйся на истребление подданных Короля-лича.|n|nПусть тебя не смущают костяные пехотинцы, $N – копыта твоего скакуна легко переломают их истлевшие кости.', },
    {'Убейте 15 костяных пехотинцев, 10 костяных разведчиков и 3 костяных лейтенантов по заданию дрессировщика Дреча из Павильона Похитителей Солнца на Ристалище Серебряного турнира.', },
  },
  [13861] = {
    'Битва у Цитадели',
    {'Пока часть рыцарей тренируется перед турниром, остальные готовятся к атаке на крепость врага – цитадель Ледяной Короны.|n|nНа юго-западе Ледяной Короны, во Дворе Костей, отряд отважных рыцарей разбил лагерь прямо к югу от Корп\'ретар. Бери копье, седлай турнирного скакуна и отправляйся на истребление подданных Короля-лича.|n|nПусть тебя не смущают костяные пехотинцы, $N – копыта твоего скакуна легко переломают их истлевшие кости.', },
    {'По заданию Эдрика Чистого из Серебряного павильона на Ристалище Серебряного турнира убейте 3 костяных командиров.', },
  },
  [13862] = {
    'Битва у Цитадели',
    {'Пока часть рыцарей тренируется перед турниром, остальные готовятся к атаке на крепость врага – цитадель Ледяной Короны.|n|nНа юго-западе Ледяной Короны, во Дворе Костей, отряд отважных рыцарей разбил лагерь прямо к югу от Корп\'ретар. Бери копье, седлай боевого скакуна Серебряного Рассвета и отправляйся на истребление подданных Короля-лича.|n|nПусть тебя не смущают костяные пехотинцы, $N – копыта твоего скакуна легко переломают их истлевшие кости.', },
    {'По заданию Эдрика Чистого из Серебряного павильона на Ристалище Серебряного турнира убейте 3 костяных командиров.', },
  },
  [13863] = {
    'Битва у Цитадели',
    {'Пока часть рыцарей тренируется перед турниром, остальные готовятся к атаке на крепость врага – цитадель Ледяной Короны.|n|nНа юго-западе Ледяной Короны, во Дворе Костей, отряд отважных рыцарей разбил лагерь прямо к югу от Корп\'ретар. Бери копье, седлай турнирного скакуна и отправляйся на истребление подданных Короля-лича.|n|nПусть тебя не смущают костяные пехотинцы, $N – копыта твоего скакуна легко переломают их истлевшие кости.', },
    {'По заданию Крока Грозы Плети с Ристалища Серебряного турнира убейте 3 костяных командиров.', },
  },
  [13864] = {
    'Битва у Цитадели',
    {'Пока часть рыцарей тренируется перед турниром, остальные готовятся к атаке на крепость врага – цитадель Ледяной Короны.|n|nНа юго-западе Ледяной Короны, во Дворе Костей, отряд отважных рыцарей разбил лагерь прямо к югу от Корп\'ретар. Бери копье, седлай турнирного скакуна и отправляйся на истребление подданных Короля-лича.|n|nПусть тебя не смущают костяные пехотинцы, $N – копыта твоего скакуна легко переломают их истлевшие кости.', },
    {'По заданию Крока Грозы Плети с Ристалища Серебряного турнира убейте 3 костяных командиров.', },
  },
  [13865] = {
    'Мокрая работенка',
    {'Слушай внимательно, |3-6($C).|n|nВ этих краях эльфами командуют трое, и внимание их сосредоточено на лесопилке. Убить их – значит посеять панику и беспорядок в рядах эльфов, и, возможно, тогда мы сможем выполнить свою задачу здесь.|n|nБудешь на месте, учти, что чем больше разведчиков ты сможешь уничтожить, тем ближе окажется наша цель.', },
    {'Крокк просит вас убить Доринара, Арминона, Эндолара и 12 разведчиков Ясеневого леса.|n|nЕсли вы вдруг потеряете секретный порошок вызова, поговорите с Кадраком на Заставе Расщепленного Дерева.', },
  },
  [13866] = {
    'К заставе!',
    {'Леса позади тебя только кажутся спокойными – на самом деле наши враги притаились за каждым деревом. Я видел много тел орков, подстреленных в спину – они даже не успели обнажить оружие.|n|nТам, за границей, пролегают опасные земли, но смекалка и острые клинки помогут нам выжить на заставе Мор\'шан. Именно оттуда Кадрак планирует начать нападение – он всегда предпочитал действие разговорам. С этого момента вы с ним будете действовать заодно.|n|nОкликни меня, когда будешь $Gготов:готова; лететь, и я тебе помогу.', },
    {'Поговорите с Кулгом Кровобрызгом на границе Ясеневого леса и Азшары, и он оправит вас на заставу Мор\'шан. По прибытии немедленно разыщите Кадрака.', },
  },
  [13867] = {
    'Устранение угрозы фурболгов',
    {'Если идти прямо на север Астранаара, можно встретить фурболгов из племени Колючий Мех. Мои разведчики докладывают, что за прошедшие несколько месяцев их численность значительно выросла. Если их окажется слишком много, они могут попытаться собрать армию и атаковать сам Астранаар!|n|nОтправляйся в деревню Колючего Меха и убей как можно больше этих существ.|n|nЯ же останусь в Астранааре и буду ждать от тебя известий. Да пребудет с тобой Элуна, |3-6($C).', },
    {'Убейте 15 фурболгов в деревне Колючего Меха.', },
  },
  [13868] = {
    'Искажающее влияние?',
    {'Обыскивая сумки мертвого фурболга, вы находите маленький оберег, явно изготовленный руками троллей.|n|nПодняв его с земли, вы внезапно ощущаете что-то странное в этом куске дерева – как будто его окружает некая темная аура проклятья|n|nОсторожно завернув его в обрывок какой-то ткани, вы кладете оберег в сумку и напоминаете себе непременно показать его Раэне Волкопас при следующем визите в Астранаар.', },
    {'Отнесите оберег троллей Раэне Волкопас в Астранаар, что в Ясеневом лесу.', },
  },
  [13869] = {
    'Вернуть останки',
    {'То, что сатиры сделали с этим деревьями, ужасно, но это не идет ни в какое сравнение с массовыми убийствами, которые учинили орки!|n|n<Великий Древний весь сотрясается от ярости, осыпая вас листьями.>|n|n$R, я прошу тебя отправиться по дороге, ведущей на лесопилку, и спасти хотя бы остатки этих деревьев, древней и энтов, погибших от руки высокомерной Орды.', },
    {'Раздобудьте 10 штабелей древесины клана Песни Войны.', },
  },
  [13870] = {
    'Как нельзя лучше',
    {'Ну что, |3-6($C), все складывается как нельзя лучше.|n|nПока эльфы еще не оправились от твоей последней вылазки – самое время совершить набег на лесопилку!|n|nНайди способ проникнуть туда и поговори с надзирателем Гортаком. Он расскажет тебе, как лучше всего сопроводить дипломата в безопасное место.|n|nУдачи!', },
    {'Крокк просит вас проникнуть на лесопилку Песни Войны и поговорить с надзирателем Гортаком.', },
  },
  [13871] = {
    'Безопасность превыше всего!',
    {'Можно подумать, мне тут нечем заняться!|n|nНе так уж легко сохранять порядок в этом месте, когда со всех сторон атакуют эльфы и дренеи. А тут еще какой-то убийца шныряет вокруг лагеря, и уже перерезал горло чрезвычайно важному послу... причем во время моего дежурства!|n|nЭто зашло слишком далеко, |3-6($C). Ищи по всему лагерю, пока не найдешь наемника, и отомсти за погибшего дипломата.|n|nКогда я предстану перед Адским Криком, я хочу хотя бы предъявить ему голову убийцы в качестве оправдания.', },
    {'Надзиратель Гортак просит вас принести ему голову калдорайской убийцы.', },
  },
  [13872] = {
    'Мудрость воргена',
    {'Этот парень напротив меня известен как пилигрим Гефест. Он ворген.|n|nНе так давно он вместе с сестрой прибыл в Астранаар в поисках убежища. Насколько мне удалось понять, он хочет помочь Служителям Земли справиться с последствиями Катаклизма. Его сестра обладает еще более могущественными способностями. Ее отправили на восток усмирять вулкан.|n|nВозможно, этот ворген сможет нам помочь. Отнеси ему оберег и спроси, что он о нем думает.', },
    {'Отнесите оберег троллей пилигриму Гефесту в Астранаар, что в Ясеневом лесу.', },
  },
  [13873] = {
    'Последняя просьба Шилы',
    {'Я... не могу поверить, что она погибла. Все случилось так быстро...|n|nПолагаю, я должен поблагодарить тебя за то, что ты $Gотомстил:отомстила; за смерть госпожи. Весь Луносвет в долгу перед тобой.|n|nВ безграничной мудрости своей повелительница предвидела свою смерть. Она оставила это послание и попросила доставить его по назначению, если с ней что-то случится.|n|nМы должны были присоединиться к оргриммарскому эскорту на перекрестке, что к северу от этого места. Прошу тебя, |3-6($R), встреть их вместо нас и убедись, что письмо попало в нужные руки.', },
    {'Страж Менерин просит вас отнести запечатанное послание Шилы стражу Гуртару.', },
  },
  [13874] = {
    'Жизнь без оберега',
    {'Фурболги опять решили наложить лапы на то, что им не принадлежит.|n|n<Гефест задумчиво крутит оберег в руках, после чего откладывает в сторону.>|n|nНа этой деревяшке есть символ, который накладывает порчу на всех, кто не принадлежит расе троллей. Как я понимаю, фурболги и раньше этим занимались. Некоторые из них ничему не учатся.|n|nНе сомневаюсь, они хранят обереги в Берлоге Колючего Меха. Она находится прямо над их деревней на севере.', },
    {'Найдите 8 оберегов троллей.', },
  },
  [13875] = {
    'Просьба Гуртара',
    {'$C, у меня есть к тебе просьба исключительно личного характера. |n|nМного лун сменилось с тех пор, как я в последний раз видел мою возлюбленную, Драаку. Боюсь, что чувства ее угаснут со временем.|n|nЭтот венок очень дорог нам обоим, как и кровавые чашечки – цветы, что растут только в этих местах.|n|nПожалуйста, собери их, вплети в венок и передай его Драаке. Пусть он напомнит ей о моей любви.', },
    {'Страж Гуртар просит вас отдать венок из кровавых чашечек Драаке с Заставы Расщепленного Дерева.', },
  },
  [13876] = {
    'Он зашел слишком далеко',
    {'Да, |3-6($R), я говорю на твоем языке.|n|nМы, фурболги, уже сталкивались с такого вида порчей. Не так давно наш вождь хитростью завладел идолом Ремула. Эта оскверненная демонами святыня околдовала все племя, и если бы не друид по имени Бролл Медвежья Шкура, нам бы не видать спасения.|n|nНо на этот раз мы ничего не крали. Тролли Зорам\'гара сами подарили нам эти обереги в знак дружбы. Видимо, дружба эта оказалась смертельной.|n|nНаш вождь, Дал Жилотяг, зашел слишком далеко. Войди в берлогу и забери его обереги.', },
    {'Найдите коллекцию Жилотяга.', },
  },
  [13877] = {
    'По течению',
    {'<Ворген окидывает вас оценивающим взглядом, и только после этого переходит к своей просьбе.>|n|nЕсли мы не будем действовать быстро, вулкан поглотит весь Ясеневый лес. Поверь мне на слово, его извержение не было вызвано естественными причинами.|n|nМоя сестра Сабина, могущественный шаман Служителей Земли, отправилась на восток, к Громовой вершине, где течет поток лавы. Она пытается объединить силы прочих стихий, чтобы противостоять повелителю пламени, который стоит за этими чудовищными разрушениями. |n|n$N, я прошу тебя – найди ее и предложи свою помощь.', },
    {'Поговорите с Сабиной на южной границе лавового потока Громовой вершины, что в Ясеневом лесу.', },
  },
  [13878] = {
    'Сквозь огонь и воду',
    {'Помоги мне, |3-6($C)! Проклятые свинобразы подожгли стойла! Пожар! Пожар!|n|n<Дорак продолжает бессвязно выкрикивать что-то до тех пор, пока вам не удается успокоить его.>|n|nТам до сих пор остались волки. Кто-то должен спасти волчат!', },
    {'Снимите цепи с волков в горящих стойлах.', },
  },
  [13879] = {
    'Громовая вершина',
    {'Приветствую тебя, |3-6($C).|n|nПрими мои поздравления с успешным нападением на Астранаар. Это унижение эльфы никогда не забудут.|n|nЖаль, что не только они препятствуют Орде захватить Ясеневый лес...|n|nЕще одна беда наступает с востока, и шаман Служителей Земли уже отправился туда, чтобы попытаться найти выход из кризиса. Разыщи его рядом с подножием вулкана Громовая вершина и окажи всю возможную помощь.', },
    {'Бройк поручил вам найти Стиквада у Громовой вершины.', },
  },
  [13880] = {
    'Горячая лава',
    {'<Огромный элементаль земли смотрит на вас сверху вниз.>|n|nЕсли мы хотим победить, необходимо остановить поток лавы. Я передам тебе частичку своей силы – воспользуйся ей, чтобы заполнить лавовые разломы!', },
    {'С помощью дара земли заполните 8 лавовых разломов.', },
  },
  [13881] = {
    'Одержимые',
    {'Больше всего меня беспокоит судьба колючешерстных медведей, что обитают в этих оскверненных лесах. Недавно тяжелая болезнь поразила целое поселение к югу отсюда, и даже медвежье святилище не уберегло их от этой беды.|n|n$N, я не знаю, в чем причина этой болезни, но она пожирает их изнутри. Как бы ни было мучительно думать о том, что мы потеряем целое поколение медведей... надо положить конец их страданиям, чтобы земля вновь приняла их в свои объятья.|n|nНо что еще более важно – мы должны найти источник заразы! Возможно, это озеро, из которого все они пили...', },
    {'Убейте 6 одержимых колючешерстных медведей и обследуйте озеро, из которого они пили.', },
  },
  [13882] = {
    'Семена жизни',
    {'Что-то подтачивает силы всех живых существ Темных Берегов! Я попытаюсь узнать что-нибудь об этой... штуке, которую ты $Gнашел:нашла;, но до тех пор надо защитить природу от дальнейшего уничтожения.|n|nМожешь собрать для меня кое-какие материалы? Мне потребуется жизнь во всех ее проявлениях. Поговори с Ону в роще, пусть он отдаст тебе Семя Земли. Затем поймай огонька Темных берегов – и у нас будет Семя воздуха. Наконец, Семя воды можно найти среди ракушек на западном побережье.', },
    {'Соберите Семя Земли, Семя Моря и Семя Неба.', },
  },
  [13883] = {
    'Обломки кораблей',
    {'Эти корабли строили спустя рукава – другого объяснения я не нахожу!|n|nНаверное, строители слишком торопились. Ты только посмотри – бронированная обшивка отваливается даже при непрямом попадании!|n|nДавай я тебе покажу, как это поправить – но сначала надо подобрать куски обшивки со дна моря.|n|nТы принеси обшивку, а я сделаю все остальное.', },
    {'Соберите 10 кусков затонувшего металлолома.', },
  },
  [13884] = {
    'Потушить огонь',
    {'Если мы хотим отвоевать территорию и положить конец уничтожению леса, сначала надо разобраться со слугами лорда Магматара.|n|nЯ имею в виду лавовых яростней, что купаются в магме на севере отсюда. Они питаются силой своей стихии, поэтому в одиночку тебе их не одолеть.|n|nОкликни меня, когда будешь $Gготов:готова; – и я вызову тебе на помощь своего элементаля.', },
    {'Убейте 10 лавовых яростеней. Обратитесь к Арктану, если вам потребуется еще один морозный волноход.', },
  },
  [13885] = {
    'В защиту Темных берегов',
    {'Теперь, когда мы знаем, что наши превентивные меры сработали, нам надо охватить как можно большее пространство.|n|nЯ уже распорядилась подготовить одного из наших гиппогрифов, но мне все равно не справиться в одиночку. Поговори с моим другом Орсеем – он ждет тебя возле распорядителя полетов за чащей. Дай ему знать, когда будешь $Gготов:готова; отправиться в путь, и я немедля присоединюсь к тебе. Вместе мы защитим Темные Берега с воздуха и спасем несчастных животных!', },
    {'Поговорите с Орсеем возле Рощи Древних и оседлайте гиппогрифа. Пролетая над рощей, защитите 8 серых колючешерстных медведей, 8 белохвостых оленей и лунопардов-матриархов и патриархов.', },
  },
  [13886] = {
    'Вихрь',
    {'Время пришло, $N. Вооружайся и приходи ко мне. Я вызову кружащийся вихрь, который в мгновение ока перенесет тебя по небу в Громовую вершину.|n|nНаправь силу Служителей Земли через элементаля, чтобы уничтожить лорда Магматара, и равновесие вновь будет восстановлено.', },
    {'Убейте лорда Магматара с помощью Кружащегося вихря.', },
  },
  [13887] = {
    'Яйца ядошкурого равазавра',
    {'Теперь, когда у тебя выработался иммунитет к яду равазавра, ты сможешь прикасаться как к самим животным, так и к ядовитым яйцам. Эти ящеры – хищные зверюги, и их надо приручать с самого рождения.|n|nТак что, если ты хочешь оседлать равазавра, найди невылупившееся яйцо – их полно в гнездах по всей Топи. Ищи яйца со светлой скорлупой – именно из таких рождаются ядошкурые равазавры.|n|nЕсли принесешь мне несколько яиц, я разрешу тебе взять одно из них и научу, как приручить твоего зверька.', },
    {'Принесите Мор\'веку 4 яйца ядошкурого равазавра. Он будет ждать вас на юго-востоке Топей.', },
  },
  [13888] = {
    'Вихрь',
    {'Время пришло, $N. Вооружайся и приходи ко мне. Я вызову кружащийся вихрь, который в мгновение ока перенесет тебя по небу в Громовую вершину.|n|nНаправь силу Служителей Земли через элементаля, чтобы уничтожить лорда Магматара, и равновесие вновь будет восстановлено.', },
    {'Убейте лорда Магматара с помощью Кружащегося вихря.', },
  },
  [13889] = {
    'Бедный, голодный равазаврик',
    {'Равазаврик выжидательно смотрит на вас, после чего начинает опять что-то рисовать в грязи.|n|nКонечно, рисунки очень грубые, но вам все же удается разобрать очертания деметродонов, стегодонов и терродактилей. Когда ящер заканчивает рисунок, он ощеривает зубы и выразительно щелкает челюстью.|n|nНаверное, ваш равазаврик хочет свежего мяса. Убейте несколько любых деметродонов, стегодонов и терродактилей в кратере Ун\'Горо и накормите голодного малыша.', },
    {'Ваш равазаврик хочет съесть 15 кусков свежего мяса динозавра.', },
  },
  [13890] = {
    'Да будет вечное пламя',
    {'Это не просто какое-то мелкое поручение, |3-6($R)!|n|nКорабли продолжают прибывать, и если огонь на маяке так и не загорится, они потеряются в море – а то и совсем пропадут! Только тебе я могу доверить хранить путеводный свет.|n|nДля начала собери сальники гидр, обитающих в этих водах, затем принеси их в кузню и перетопи в масло.|n|nЕсли потом ты подольешь это масло в светильник маяка, у нас появится чуть больше времени, чтобы продержаться.', },
    {'Командир Мрачный Клык из Зорам\'гара поручил вам залить жир гидры-тайнохлыста в огонь на маяке.', },
  },
  [13891] = {
    'Поглотитель Темных берегов',
    {'Теперь, когда обитатели Темных берегов в безопасности, давай обратим внимание на артефакт, который ты $Gнашел:нашла; в озере. Я практически уверена, что он был создан руками прислужников древних богов. С этими демонами можно сражаться только силой, дающей жизнь! Вот, отнеси Саженец жизненоса на берег обмелевшего озера, что на юге отсюда. Омой его в водах озера: это должно отключить древний артефакт.|n|nНо будь $Gосторожен:осторожна;! Кто знает, кто охраняет этот источник зла...', },
    {'Воспользуйтесь саженцем жизненоса на берегу обмелевшего озера к югу от Рощи Древних, чтобы уничтожить Всепожирающий артефакт и его хранителя.', },
  },
  [13892] = {
    'Не оставляй следов',
    {'На юго-западе отсюда лежит тело существа, которое имеет какое-то отношение к почитаемым культом Сумеречного Молота древним богам.|n|nОн пал в битве в стародавние времена – чуть ли не от руки самих Титанов или одного из их созданий.|n|nНо сейчас к его телу проявляют особый интерес сектанты Сумеречного Молота, и я боюсь, что они затевают что-то недоброе.|n|nНадо выяснить, что они там делают и с какими целями. Вот, возьми эту статуэтку – ее магия укроет тебя от посторонних глаз, пока ты будешь собирать сведения.', },
    {'Проникните к Мечу Властителя, воспользовавшись магией статуэтки пантеры, и проследите за служителями культа Сумеречного Молота.', },
  },
  [13893] = {
    'Соггот и Кронн',
    {'Меч Властителя – это поле древней битвы, $N. Титаны отправили двадцать каменных великанов, чтобы одолеть Соггота, но уцелел из них только один.|n|nСкрижали гласят, что Кронн, самый большой из каменных великанов, позволил Согготу захватить его своими щупальцами... но лишь для того, чтобы добраться до головы чудовища, которую он расколол своим могучим мечом.|n|nХорошо, что Соггот погиб. У нас больше нет двадцати каменных великанов, чтобы остановить его.', },
    {'Вернитесь к Лариену в Рощу Древних и передайте ему полученную вами информацию.', },
  },
  [13894] = {
    'Знак убийства',
    nil,
    nil,
  },
  [13895] = {
    'Дремлющие древни',
    {'Хотя на нашей стороне нет двадцати каменных великанов, чтобы сокрушить врагов, наша древняя деревянная кожа прочнее любого гранита.|n|nПосмотри по сторонам, |3-6($R): здесь дремлют мои братья и сестры, но рог хранителя пробудит их в час битвы.|n|nНайди хранителя чащи Ароса возле моста, что на северо-востоке.|n|nОбъясни ему всю серьезность ситуации.', },
    {'Найдите Ароса на северо-востоке от Рощи Древних на Темных берегах.', },
  },
  [13896] = {
    'Раскопанное знание',
    {'Послушай, $N, мы должны понять, с чем нам придется иметь дело.|n|nЯ знаю, кто может помочь разобраться в этом деле. На юго-западе отсюда, прямо под Мечом Властителя, я видела группу дворфов-археологов, которые раскапывали близлежащие руины.|n|nЧто-то мне подсказывает, что они могли наткнуться на некие знания, которые могут оказаться полезными.', },
    {'Поговорите с археологом Гроффом на Раскопках Сомнамбулера.', },
  },
  [13897] = {
    'Битва за Темные берега',
    {'Древние обитатели рощи откликнулись на наш зов, $N. Даже сейчас я вижу мир их глазами.|n|nСлужителям культа Сумеречного Молота пришлось ускорить свои ритуалы, и потому им удалось оживить лишь бледное подобие некогда ужасного Соггота.|n|nМы должны уничтожить его, пока еще не поздно. Мое присутствие требуется в другом месте, так что возвращайся к друидам Рощи Древних, когда Соггот будет уничтожен. Они скажут тебе, что делать дальше.', },
    {'Убейте аватара Соггота у Меча Властителя.', },
  },
  [13898] = {
    'Волны против нас',
    {'Убийство хранителя чащи приравнивается к объявлению войны, $N, и наги еще поплатятся за это.|n|nНайди их логово внутри пещеры на острове Най\'вел, что на юго-западе отсюда.|n|nОни должны понять, что это им не сойдет с рук.', },
    {'Убейте 8 мирмидонов клана Темной Чешуи.', },
  },
  [13899] = {
    'Владыка Черной Чешуи',
    {'Если наги действительно решили связать свою судьбу с Сумеречным Молотом... да смилуется Элуна над их душами.|n|nОтправляйся в их логово на острове Назж\'вел и найди их предводителя, полководца Гневного Гребня.|n|nВозможно, рог древних все еще можно спасти.', },
    {'Убейте Полководца Гневного Гребня в Назж\'вел.', },
  },
  [13900] = {
    'Дар Азшаре',
    {'Полководец сказал, что рог древних будет принесен в дар Азшаре над Назж\'вел.|n|nВозможно, мы успеем спасти еще одну реликвию от уничтожения.', },
    {'Не дайте жрицам клана Темной Чешуи передать Рог Древних Азшаре над Назж\'вел.', },
  },
  [13901] = {
    'Глубокое отчаяние',
    {'Проблема с нагами гораздо серьезнее, чем казалось на первый взгляд, |3-6($C), и ее не решить простым сокращением их популяции. Чтобы угомонить их, нам придется прибегнуть к более серьезным действиям.|n|nОтправляйся на северный край Зорамского взморья, где находится Непроглядная Пучина. Когда окажешься внутри, покажи нагам, кто здесь главный. Они должны понять, что мы больше не потерпим их присутствия на нашей территории!', },
    {'Убейте 6 жриц прилива из Непроглядной Пучины.', },
  },
  [13902] = {
    'В наступление!',
    {'Нам еще многое нужно сделать на Темных Берегах прежде, чем наша миссия будет считаться законченной. Хотя мы смогли остановить разрушение земли, наши враги все еще могут в любой момент свести на ноль все усилия.|n|nЯ попрошу тебя отыскать группу друидов в Роще Древних, что на юге отсюда. Их возглавляет мой старый друг, Балрен-медведь.|n|nСкажи ему, что настал час повергнуть наших врагов. Я присоединюсь к нему, как только мы сможем стабилизировать эту местность.', },
    {'Поговорите с Балреном-медведем в Роще Древних на Темных берегах.', },
  },
  [13903] = {
    'Личинка из улья Гориши',
    {'Равазаврик испытующе смотрит на вас, после чего начинает что-то рисовать в грязи.|n|nСреди нарисованных знаков вы разбираете изображения различных больших насекомых – в основном, горишских силитидов. Малыш заканчивает рисунок, после чего указывает на него короткой лапой, чавкает и облизывается.|n|nОчевидно, он хочет, чтобы вы отправились в Скользкий овраг, что на юге кратера Ун\'Горо, и принесли ему мясо силитидов. Когда соберете мясо, угостите им своего равазаврика.', },
    {'Ваш равазаврик проголодался. Принесите ему 10 кусков мяса силитида.', },
  },
  [13904] = {
    'Всмятку, в мешочек или сырые?',
    {'Равазаврик пытается привлечь ваше внимание, и вы слышите, как бурчит у него в животе. Он рисует в грязи несколько силитидов и добавляет внизу какие-то овалы, настойчиво указывая на них когтем.|n|nСомнений нет – ему нужны яйца силитидов! К счастью, вы знаете, где раздобыть лакомство для малыша – в Ядовитом улье, который находится в западном Танарисе, рядом с кратером Ун\'Горо.', },
    {'Ваш равазаврик хочет, чтобы вы принесли ему 12 яиц силитида.', },
  },
  [13905] = {
    'Перья опаляющего руха',
    {'Равазаврик внимательно смотрит на вас, словно сомневается, поймете ли вы его. Затем он рисует в грязи два пера и показывает когтем сначала на рисунок, а потом на свои локти и колени.|n|nОн, вроде бы, не голоден, что бы значили эти перья?|n|nНаверное, он хочет использовать их в качестве украшения, как другие ящеры. Самыми большими перьями могут похвастаться опаляющие рухи, которых легко найти вокруг останков огромных животных в западном Танарисе, к северо-востоку от Долины Кактусов.', },
    {'Ваш равазаврик хочет, чтобы вы принесли ему 5 перьев опаляющего руха.', },
  },
  [13906] = {
    'Они так быстро растут',
    {'При хорошем уходе равазавры быстро растут. По мере взросления молочные зубы заменятся коренными. Если ты будешь собирать все выпавшие зубы, то сможешь легко определить, когда он достаточно окрепнет для того, чтобы его можно было тренировать как верховое животное.|n|nОн сам даст тебе знать о том, что ему нужно, так что внимательно следи за ним и тщательно ухаживай за своим малышом. А когда все его молочные зубы выпадут, возвращайся ко мне со своим равазавром и всем, что нужно для его седла.', },
    {'Вернитесь к Мор\'веку на юго-восток Топей в Кратер Ун\'Горо со своим равазавриком, а также принесите 20 молочных зубов равазавра, 20 отрезов рунической ткани, 20 кусков грубой кожи и 80 золотых монет.', },
  },
  [13907] = {
    'Зачистка руин',
    {'Великие бородачи из Стальгорна послали меня на раскопки Сомнамбулера, как только до них дошли слухи о случившемся несчастье. Да ты $Gсам:сама; посмотри! Драгоценные артефакты в одночасье смыло в море, месяцы кропотливой работы воргену под хвост! |n|nМало того, волны разрушили поселения мурлоков, которые располагались вдоль берега. Скажешь, туда им и дорога? Ага, как же! Выжившие мурлоки пытаются пробраться под защиту руин и, если честно, наносят куда больше ущерба, чем стихии. Ну чего ты ждешь – сделай что-нибудь!', },
    {'Убейте 10 оракулов племени Серой Мглы или беженцев из племени Серой Мглы возле Раскопок Сомнамбулера.', },
  },
  [13908] = {
    'Приготовьтесь к поездке',
    {'Твой равазавр окреп, возмужал и сильно к тебе привязался. Пожалуй, вскоре ты сможешь ездить на нем – как только я доделаю седло и уздечку. Правда, их тоже придется укрепить, чтобы они выдержали воздействие яда равазавра.|n|nПринеси мне немного грубой кожи, рунической ткани и денег на остальные ингредиенты – и я тут же примусь за работу.', },
    {'Принесите 20 кусков грубой кожи, 20 отрезов рунической ткани и 80 золотых монет Мор\'веку. Он ждет вас на юго-востоке Топей в Кратере Ун\'Горо', },
  },
  [13909] = {
    'Обломки для бездомных',
    {'Мы сможем найти выход из ситуации. Надо только немного подумать... Мы, дворфы, издавна славились своей мудростью!|n|nЗначит, так: этим мурлокам нужен новый дом, верно? Мысли созидательно, $N! В буквальном смысле...|n|nВо время катаклизма на берег вынесло целую кучу всякого мусора, да и некоторые хижины все еще можно восстановить. Ну-ка, пробегись по побережью и собери все подходящие материалы для строительства. Поверь, для них особо стараться не придется!', },
    {'Соберите 5 подлежащих восстановлению частей строений Серой Мглы на берегу и в воде возле Раскопок Сомнамбулера.', },
  },
  [13910] = {
    'Новый дом',
    {'Что нам стоит дом построить? Нарисовал – и будем жить! К западу от раскопок я установил на побережье наш флаг. Песок там достаточно плотный, и вполне подходит для постройки. Возьми мои инструменты и собранные материалы, и возведи этим несчастным тварям новые хижины.', },
    {'Постройте лачугу для мурлоков в специальном месте на западе от раскопок рассеянного геолога.', },
  },
  [13911] = {
    'Рассеянный геолог',
    {'Как, ты говоришь, тебя зовут? $N? Мы знакомы? Если тебя прислали из Лиги, можешь передать им, что я никуда отсюда не уйду без моей находки! Она была уже у меня в руках... как вдруг раздались крики, и меня захлестнуло волной...|n|nСлушай, как там тебя зовут, я все записал в моем путевом журнале, и я знаю, где он сейчас лежит! Отыщем журнал – отыщем и мою находку! Или наоборот?... Иди за мной!', },
    {'Покажите геологу Сомнамбулеру, где лежит его журнал, после чего поговорите с археологом Фердом на раскопках.', },
  },
  [13912] = {
    'Тайны болота',
    {'Кто бы мог подумать, что вечно рассеянный Сомнамбулер – на самом деле непризнанный гений! Вот уж воистину тайна, скрытая под пылью веков. Но я не собираюсь преуменьшать заслуги старика. Смотри, что мне удалось обнаружить в его записях... нет, не то... это список покупок... нашел! Вот, смотри: на этой странице он пытается определить, который сейчас год с помощью Диска!|n|nПохоже, этот артефакт Титанов представляет собой некий диск с зашифрованными надписями. Незадолго до катастрофы мы со всеми предосторожностями выкопали его из-под земли, но не успели поднять на поверхность. Если он все еще лежит там, среди руин, пожалуйста, принеси его мне!', },
    {'Найдите покрытый грязью древний диск среди ближайших руин.', },
  },
  [13913] = {
    'Они забрали наших гномов!',
    {'Спасите Буга "Моднявого" и Минкс из фургона Бесконечной Агонии, принадлежащего мастеру пыток Тундраку.', },
    {'Спасите Буга "Моднявого" и Минкс из фургона Бесконечной Агонии, принадлежащего мастеру пыток Тундраку.', },
  },
  [13914] = {
    'Перья опаляющего руха',
    {'Равазаврик внимательно смотрит на вас, словно сомневается, поймете ли вы его. Затем он рисует в грязи два пера и показывает когтем сначала на рисунок, а потом на свои локти и колени.|n|nОн, вроде бы, не голоден, что бы значили эти перья?|n|nНаверное, он хочет использовать их в качестве украшения, как другие ящеры. Самыми большими перьями могут похвастаться опаляющие рухи, которых легко найти вокруг останков огромных животных в западном Танарисе, к северо-востоку от Долины Кактусов.', },
    {'Ваш равазаврик хочет, чтобы вы принесли ему 5 перьев опаляющего руха.', },
  },
  [13915] = {
    'Бедный, голодный равазаврик',
    {'Равазаврик выжидательно смотрит на вас, после чего начинает опять что-то рисовать в грязи.|n|nКонечно, рисунки очень грубые, но вам все же удается разобрать очертания деметродонов, стегодонов и терродактилей. Когда ящер заканчивает рисунок, он ощеривает зубы и выразительно щелкает челюстью.|n|nНаверное, ваш равазаврик хочет свежего мяса. Убейте несколько любых деметродонов, стегодонов и терродактилей в кратере Ун\'Горо и накормите голодного малыша.', },
    {'Ваш равазаврик хочет съесть 15 кусков свежего мяса динозавра.', },
  },
  [13916] = {
    'Всмятку, в мешочек или сырые?',
    {'Равазаврик пытается привлечь ваше внимание, и вы слышите, как бурчит у него в животе. Он рисует в грязи несколько силитидов и добавляет внизу какие-то овалы, настойчиво указывая на них когтем.|n|nСомнений нет – ему нужны яйца силитидов! К счастью, вы знаете, где раздобыть лакомство для малыша – в Ядовитом улье, который находится в западном Танарисе, рядом с кратером Ун\'Горо.', },
    {'Ваш равазаврик хочет, чтобы вы принесли ему 12 яиц силитида.', },
  },
  [13917] = {
    'Личинка из улья Гориши',
    {'Равазаврик испытующе смотрит на вас, после чего начинает что-то рисовать в грязи.|n|nСреди нарисованных знаков вы разбираете изображения различных больших насекомых – в основном, горишских силитидов. Малыш заканчивает рисунок, после чего указывает на него короткой лапой, чавкает и облизывается.|n|nОчевидно, он хочет, чтобы вы отправились в Скользкий овраг, что на юге кратера Ун\'Горо, и принесли ему мясо силитидов. Когда соберете мясо, угостите им своего равазаврика.', },
    {'Ваш равазаврик проголодался. Принесите ему 10 кусков мяса силитида.', },
  },
  [13918] = {
    'Терминал титанов',
    {'Теперь, когда диск у нас в руках, многие предыдущие находки обретают новое значение. Например, вскоре после моего прибытия, геолог Сомнамбулер откопал нечто, напоминающее доисторический тостер.|n|nЯ же всегда был убежден, что это устройство предназначено для чтения данных. К несчастью, его разбило и унесло волной вместе со всем нашим лагерем во время цунами!|n|nНо он не мог уплыть далеко – наверняка обломки все еще валяются на линии прибоя. Вот, возьми мой проверенный детектор артефактов и прочеши им весь пляж.', },
    {'Используйте обнаружитель затерянных артефактов на пляже возле Раскопок Сомнамбулера, чтобы найти 5 деталей артефакта. Соберите их вместе, чтобы получить древнее устройство с прорезью.', },
  },
  [13919] = {
    'Путешествие к Лунному колодцу',
    {'Ничего не вышло...|n|n<С глубокой скорбью на лице Пельтур достает Слезу из чаши и бережно омывает ее.>|n|nДолжно быть, на святыню как-то повлияло извержение Громовой вершины. Пожалуйста, отнеси Слезу к Лунному колодцу чистоты. Это единственное место, еще не затронутое скверной – его охраняет сама сила богини. Он находится на юго-востоке от подножия вулкана.|n|nОмой святыню в водах, благословленных Элуной. Я не могу знать, что будет дальше. Я боюсь за судьбу моей дочери. Теперь она в твоих руках, $N.', },
    {'Очистите Слезу Элуны в Лунном колодце чистоты, что в Ясеневом лесу.', },
  },
  [13920] = {
    'Прежде, чем уйти...',
    {'Здесь, в Дозоре Адского Крика, не хватает таких |3-8($C), как ты. Поэтому прежде, чем ты отправишься в путь, я хочу попросить тебя об одной услуге.|n|nИз-за непрекращающихся атак Альянса мы потеряли в море множество ценных товаров, в том числе провизию, необходимую для поддержания сил наших солдат, участвующих в битве за Ясеневый лес.|n|nОднако к востоку отсюда находятся богатые охотничьи угодья. Добудь для наших отрядов самое лучшее мясо, которое только сможешь найти!', },
    {'Принесите 5 стейков из оленины командиру Мрачному Клыку в форт Зорам\'гар.', },
  },
  [13921] = {
    'Тот, кто будет прощен',
    {'<Вы чувствуете, как в вашей голове раздается бесконечно умиротворяющий голос, исходящий откуда-то из колодца.>|n|nТы желаешь исцелить дитя, но каждое деяние, даже самое благое, должно быть оплачено. На востоке отсюда высится Башня в Ночных лесах, а рядом с ней возле моего лунного колодца бродит существо, поддавшееся скверне.|n|nАврий Дурной Толк жаждет прощения и освобождения. Даруешь ли ты ему то, о чем он просит, если это приблизит тебя к цели?', },
    {'Поговорите с Аврием Дурным Толком у башни в Ночных лесах, что в Ясеневом лесу.', },
  },
  [13922] = {
    'В оскверненных руках',
    {'Мой бывший клан Кабарог Скверны из Ночной поляны довольно часто охотился у Зеркала Небес и собирал лунные камни, которые встречаются только в тех местах.|n|nЭти лунные камни известны своими целебными свойствами. Не сомневаюсь, они могут помочь исцелить эту бедную девочку из Астранаара.|n|nНочная поляна находится возле дороги, ведущей на север. От нее отходит множество тропинок, огибающих холмы с восточной стороны – именно там ты найдешь моих нераскаявшихся братьев. У них есть то, что тебе нужно.', },
    {'Добудьте 5 лунных камней Упавшего Неба.', },
  },
  [13923] = {
    'На заставу Адского Крика',
    {'Вперед, в самое пекло, |3-6($R)!|n|nЗастава Адского Крика – самый ненадежный фронт во всем Ясеневом лесу, но ты многое узнаешь, побывав там лично... если, конечно, выживешь.|n|nКак закончишь последние приготовления, поговори с Андруком. Я поручил ему отправить тебя прямо на заставу.|n|nПрибудешь на место и немедленно разыщешь капитана Гоггата. Он выдаст тебе дальнейшие инструкции.|n|nСмерть и боль нашим врагам! За Орду!', },
    {'Поговорите с капитаном Гоггатом в дозоре Адского Крика.', },
  },
  [13924] = {
    'Все хорошо, что хорошо кончается',
    {'Спасибо за то, что ты $Gспас:спасла; меня от участи хуже, чем смерть! За то, что ты $Gуберег:уберегла; от погибели меня и этого несчастного ребенка.|n|nТеперь дитя почти в безопасности. Осталось только отнести лунные камни назад, на запад от Астранаара. Передай их Пельтуру – он знает, что делать дальше.|n|nСтупай с миром, и да хранит тебя Элуна!', },
    {'Отнесите освященные лунные камни Пельтуру Белой Луне в Астранаар, что в Ясеневом лесу.', },
  },
  [13925] = {
    'Подстелить соломку',
    {'А ты никак $Gслышал:слышала; про Древних богов, $N? Мы с Ону единогласны во мнении, что найденный тобой артефакт мог быть изготовлен только ими, и теперь он поглощает Темные Берега. Что-то пробудило кошмары, которые мы считали давно позабытыми. Это неподвластно тебе и мне... но я хочу хотя бы сохранить природу от воздействия зла.|n|nВ этом побеге заключена энергия жизни, которую ты мне $Gпринес:принесла;. Хочется верить, что она защитит местных обитателей. Испытай ее на любом медведе, олене или лунопарде, не затронутом порчей, и дай мне знать, что случится!', },
    {'Испытайте саженец жизненоса на любом здоровом седом колючешерстном медведе, белохвостом олене, лунопарде-матриархе или патриархе.', },
  },
  [13926] = {
    'Ру, оракул-сиротка',
    {'Дети будут очень рады такому другу, как вы, $N. Как замечательно, что вы станете опекать одного из них!|n|nВозьмите эту свистульку, с ее помощью вы сможете позвать своего воспитанника. Свистулька не прослужит долго, но на Детскую неделю должно хватить.|n|nПозовите сиротку, $N! Он будет очень рад познакомиться с вами и попутешествовать по Нордсколу.', },
    {'Поговорите с попечительницей сирот Арией; после этого воспользуйтесь детской свистулькой оракула, чтобы позвать сиротку, о котором вы будете заботиться во время Детской недели.', },
  },
  [13927] = {
    'Кекек, волчер-сиротка',
    {'Дети будут очень рады такому другу, как вы, $N. Как замечательно, что вы станете опекать одного из них!|n|nВозьмите эту свистульку, с ее помощью вы сможете позвать своего воспитанника. Свистулька не прослужит долго, но на Детскую неделю должно хватить.|n|nПозовите сиротку, $N! Он будет очень рад познакомиться с вами и попутешествовать по Нордсколу.', },
    {'Поговорите с попечительницей сирот Арией, после этого воспользуйтесь детской свистулькой волчера, чтобы позвать сиротку, о котором вы будете заботиться во время Детской недели.', },
  },
  [13928] = {
    'Тела павших',
    {'Хранитель Ордан поручил мне и моим часовым охранять башню. Пока нам удавалось сдерживать атаки Орды, но теперь их войска заходят с севера, чтобы напрямую напасть на крепость.|n|nХранитель отправил дриад на защиту дерева, но что они могут сделать против авангарда орков Песни Войны?|n|nПрошу тебя, отправляйся туда и принеси как можно больше тел павших сестер. Их надо отнести Халаннии в Приют. Она сможет им помочь.', },
    {'Соберите 10 трупов смеющихся сестер Халаннии.', },
  },
  [13929] = {
    'Самое большое дерево!',
    {'Мы помним, что еще перед большой войной Су-сэй рассказывал нам о большом-пребольшом дереве!|n|nСу-сэй, кажется, называл его Седой Пастью, и оно в центре Серых холмов. Нет, неправильно, он говорил иначе! Мы вспомнили! Большое дерево растет прямо посреди Седых холмов! Такое не пропустишь!|n|nТы отведешь нас туда, да? И мы заберемся прямо внутрь? Су-сэй говорил, там живут большие люди-медведи. Может нам удастся их увидеть.', },
    {'Отведите вашего подопечного Ру к Седой Пасти. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.', },
  },
  [13930] = {
    'Дом людей-медведей',
    {'Верховный шаман Ракжак всегда рассказывал истории о великих воинах прошлого. Как-то он поведал об огромных людях-медведях, которые сражались за великий город-дерево.|n|nКекек хочет посмотреть на то дерево и место битвы! Верховный шаман Ракжак сказал Кекеку, что город-дерево называется Седая Пасть и находится в самом центре Седых холмов.|n|nКекек никогда раньше не видел городов до того, как встретился с попечительницей сирот, но в этом городе нет воинов – только мужчины в фиолетовых одеждах. Кекек хочет увидеть настоящих героев, которые сражаются за свой город!', },
    {'Отведите вашего подопечного Кекека к Седой Пасти. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.', },
  },
  [13931] = {
    'Новый подарок к новому году',
    {'Мы не только поим всех подряд, но и дарим пивные кружки! Красивые, памятные кружки, полученные совершенно законным образом! Вот тебе купон на такую кружку.|n|nПоговори с Бликсом рядом с лагерем Хмельного фестиваля. Он довольно странный тип, тем более, что очки эти никогда не снимает. Он и отоварит твой купон. Он же занимается прочей праздничной торговлей.', },
    {'Отоварьте свой купон на праздничную кружку у Бликса Чиништукса в лагере Хмельного фестиваля.', },
  },
  [13932] = {
    'Новый подарок к новому году',
    {'Главное на Хмельном фестивале – не гонки на баранах, а выпивка! Улучи минутку и отдай свой купон Белби Быстросмен. Она стоит за поляной, на которой проходит Хмельной фестиваль. Если ты ее не увидишь, не беспокойся, она-то тебя всяко заметит.|n|nВ общем, отдай ей свой купон, и получишь бесплатную праздничную кружку. Кроме того, именно Белби занимается прочей праздничной торговлей.', },
    {'Отоварьте свой купон на праздничную кружку у Бликса Чиништукса в лагере Хмельного фестиваля.', },
  },
  [13933] = {
    'Святилище бронзовых драконов',
    {'Иногда верховный оракул Су-сэй рассказывает истории о великой святыне драконов – не такой, конечно, как Великий камень дождя, а совсем другой. Су-сэй говорит, что мы можем увидеть в ней себя – точнее, какими мы будем через много лет.|n|nОтведешь нас туда? Мы помним, что это святилище бронзовых драконов, которое находится в Драконьем Погосте. Су-сэй говорит, что Великий камень дождя показал ему святилище на северо-востоке от Храма Драконьего Покоя или на северо-западе от места, которое сухокожие зовут Крепостью Стражей Зимы. Идем?', },
    {'Отведите вашего подопечного Ру к Бронзовому святилищу драконов. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.', },
  },
  [13934] = {
    'Святилище бронзовых драконов',
    {'Когда Кекек был щенком, он слышал, как старейшины рассказывали об одном далеком святилище. Они говорили, что род бронзовых драконов, который его оберегает, может видеть будущее.|n|nКекек станет великим воином! Пойдем, посмотрим каким вырастет Кекек. Святилище бронзовых драконов находится где-то на Драконьем Погосте, на северо-восток от храма Драконьего Покоя и на северо-запад от Крепости Стражей Зимы.|n|nПойдем, увидим будущее. Плохо, что попечительница ругает Кекека. Кекек воин, а не забияка.', },
    {'Отведите вашего подопечного Кекека к Бронзовому святилищу драконов. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.', },
  },
  [13935] = {
    'Защитить древо!',
    {'Мы использовали силу сердца леса для защиты древа от Орды, но его возможности не безграничны. Теперь мы воспользуемся святыней, чтобы дать врагам отпор!|n|nЗдесь неподалеку охотится Тенумбра, великая хищница леса. В ее силе и ловкости мы должны черпать вдохновение. Ты станешь $Gедин:едина; с ее тенью, впитаешь в себя дух пантеры и уничтожишь тех, кто посягает на величие Ясеневого леса!', },
    {'Поговорите с Халаннией, чтобы призвать тень Тенумбры, и воспользуйтесь ее силой, чтобы уничтожить 50 врагов из клана Песни Войны в приюте в Ночных Лесах.', },
  },
  [13936] = {
    'Болван Шкрып',
    {'Задержки, опять задержки! Сил моих не хватает!|n|nМне сказали, что этот гоблин просто гений – мол, он изобретет такое устройство, которое с превратит в пыль наших врагов, но пока что он нас только завтраками кормит! Если он еще раз явится с пустыми руками, клянусь, сброшу его обрыва! |n|nИди поговори с ним, |3-6($C). Скажи ему, что мое терпение на исходе.', },
    {'Капитан Гоггат просит вас поговорить с Шкрыпом в Дозоре Адского Крика.', },
  },
  [13937] = {
    'Поездка в "Чудо чудное".',
    {'А у нас есть еще минутка? Мы слышали, что в Даларане есть магазин игрушек, но никогда там не были. Госпожа попечительница говорит, что сирот слишком много, и мы будем мешать покупателям. Может быть, мы могли бы заглянуть туда вдвоем?|n|nА еще мы всегда хотели бумажный дирижаблик. Как ты думаешь, они продаются в "Чуде чудном"? Это наша мечта... Может быть, ты подаришь нам его?', },
    {'Купите бумажный дирижаблик в магазине "Чудо чудное" и бросьте его вашему подопечному Ру.', },
  },
  [13938] = {
    'Заглянем в "Чудо чудное".',
    {'Может Кекек тебя еще кое о чем попросить? Попечительница рассказывала, что в Даларане есть магазин игрушек "Чудо чудное", но Кекека туда не пускают. Говорят, если Кекек туда пойдет, придется отвести и всех остальных сирот. Но Кекек очень хочет попасть в магазин!|n|nКекек видел, как другие дети играют с бумажными дирижабликами. Говорят, их продают в "Чуде чудном". Ты запустишь такой дирижаблик, чтобы он летал вокруг Кекека?', },
    {'Купите бумажный дирижаблик в магазине "Чудо чудное" и отдайте его вашему подопечному Кекеку.', },
  },
  [13939] = {
    'Мох скверны',
    {'[Deprecated] I\'d hoped to never return to Teldrassil for such grim business. I\'d hoped that its corruption had been wiped away completely. Something fowl lingers.|n|nThe corruption of the wicked fel moss still threatens to turn peaceful creatures against us. The grells and gellkin still infest the area and threaten Shadowglen\'s residents.|n|nEngage these grells and grellkin, $N, and see if they are indeed caught under the enchantment of the wicked fel moss. Once we know for certain, we will know how to proceed.', },
    {'Соберите 6 образцов мха скверны.', },
  },
  [13940] = {
    'Пробуждение ото Сна',
    {'Держись крепче, $N. Дорога в мир бодрствующих может оказаться тяжелой для твоего неподготовленного разума и тела.', },
    {'Поговорите с Малфурионом Яростю Бури в Оке Урагана.', },
  },
  [13941] = {
    'Зловещее прикосновение',
    {'Гитьис Зловещая прославилась своим ядом – более сильным, чем у любого другого чащобного тенетника. Дирания Серебряное Сияние, живущая у основания Альдрассила, наверняка весьма заинтересована в яде из переполненных ядовитых желез Гитьис, чтобы создать не менее мощную противоядную сыворотку. Возможно, она так в этом заинтересована, что даже предложит награду...', },
    {'Принесите переполненную ядовитую железу Дирании Серебряное Сияние в Альдрассил.', },
  },
  [13942] = {
    'Бомба на взводе',
    {'Да я уже почти воплотил в жизнь мое великое изобретение!|n|nВот, видишь эти взрывчатые вещества? Их вполне достаточно для изготовления мега-бомбы, о которой мечтает Гоггат – осталось только собрать все части воедино.|n|nМне не хватает лишь глины, да не простой, а омытой лунным светом.|n|nТолько она сможет раскрыть весь потенциал моего изобретения. А собрать ее можно на северных берегах Астранаарского озера.', },
    {'Шкрып просит вас собрать 10 образцов омытой лунным светом глины.', },
  },
  [13943] = {
    'Превентивный удар',
    {'Наши войска еще не готовы осадить Астранаар, |3-6($C). Однако наши враги знают о скором нападении и не сидят на месте. Они разбили лагерь у подножия скалы и намереваются напасть на нас при свете луны.|n|nЯ хочу, чтобы ты $Gвышиб:вышибла; эти мысли у них из головы – можно вместе с мозгами. Возвращайся, когда утихомиришь этих остроухих.', },
    {'Капитан Гоггат хочет, чтобы вы убили 10 застрельщиков Астранаара и 3 офицеров Астранаара.', },
  },
  [13944] = {
    'Маленькие руки, короткий запал',
    {'<Глядя на оживленно жестикулирующего Шкрыпа, вы внезапно обращаете внимание, что его перчатки подозрительно болтаются на руках.>|n|nВсе готово! Теперь даже Гоггат не сможет ни к чему придраться!|n|nНадо только устроить ему достойную демонстрацию нашего изобретения... знаю!|n|nМы подорвем старую телегу – все равно босс хотел избавиться от этой груды ржавчины. Вот, бери мою взрывчатку. Посмотрим, как теперь запоет капитан!', },
    {'Взорвите сломанный фургон в Дозоре Адского Крика с помощью импровизированной взрывчатки.', },
  },
  [13945] = {
    'Опасность обители',
    {'Агрессия племени Кривой Сосны связывает нам руки. Никто из наших не горит желанием взять на себя ответственность и выступить против существ, которые некогда были нашими друзьями, но я все больше опасаюсь того, что они планируют вскоре захватить Доланаар.|n|nБольше всего меня беспокоят фурболги в лощине Бен\'этиль и обители Бен\'этиль. Я хочу, чтобы ты $Gотправился:отправилась; на запад, $Gдобрался:добралась; до обители и $Gубил:убила; так много фурболгов Кривой Сосны, как только сможешь. Может быть, у нас больше не будет возможностей уменьшить их силы, поэтому действуй без промедлений.', },
    {'Убейте 20 фурболгов Кривой Сосны внутри и вокруг обители Бен\'этиль.', },
  },
  [13946] = {
    'Возмездие природы',
    {'Я рада, что ты $Gрешил:решила; исправить свою ошибку – это говорит много хорошего о твоем характере.|n|nУ меня есть для тебя еще одно задание. Я собрала несколько семян гневоплода. Они похожи на шишки Скверны, но гораздо более мощные. Природа часто очень негативно реагирует на демонов, и эти семена гневоплода являют собой яркий пример такой реакции.|n|nК северу отсюда, в Пещере Бесов находятся грелли в огромном количестве. Используй эти семена гневоплода, чтобы избавиться от них, пока они не стали совсем серьезной угрозой.', },
    {'Используйте семена гневоплода, чтобы убить 12 греллей в Пещере Бесов.', },
  },
  [13947] = {
    'Адстранаар!',
    {'Так значит Шкрып все-таки изобрел хорошую взрывчатку?|n|nКак нельзя вовремя. Пока мы тут прохлаждаемся, эльфы Астранаара готовят атаку на наш лагерь.|n|nНо мы сбросим на них наши бомбы с воздуха! Гибель Астранаара станет величайшей трагедией для всех ночных эльфов.|n|nКак только завершишь последние приготовления, поговори с Тракой. И пусть рука твоя будет твердой, |3-6($C).', },
    {'Капитан Гоггат просит вас убить 20 часовых Астранаара и 10 метателей из Астранаара с помощью импровизированной взрывчатки Шкрыпа.', },
  },
  [13948] = {
    'В дозор',
    {'Похоже, служители культа откапывают останки существа, известного как Соггот Скользящий.|n|nНаверное, их надзиратели, что стоят на вершине платформ, знают больше о том, зачем это делается.', },
    {'Проникните к Мечу Властителя, воспользовавшись магией статуэтки пантеры, и проследите за предводителями культа Сумеречного Молота.', },
  },
  [13949] = {
    'Эскорт караванов до Перекрестка',
    {'<Халга обезоруживающе улыбается, держа в руках огромное ружье.>|n|nТы когда-нибудь раньше $Gпользовался:пользовалась; такими, $N? Это зверь! Переносной ад! На своих двоих его, конечно, далеко не утащишь, но нет оружия лучше для сопровождения караванов. Я называю его автоматическим дробовиком. |n|nНужно доставить добытые тобой припасы в Перекресток, и без проблем по дороге нам не обойтись. Я хочу, чтобы ты $Gобеспечил:обеспечила; нам охрану. Без шуток. Скажи, когда будешь $Gготов:готова; – я отправлю тебя с ближайшим караваном.', },
    {'Поговорите с Халгой Кровавый Глаз на Дальней Заставе о сопровождении каравана Перекрестка до фермы Гроль\'дома.', },
  },
  [13950] = {
    'Друзья детства!',
    {'Знаешь, в сиротском приюте так одиноко... Иногда нам хочется увидеть другие края, встретить новых друзей.|n|nМожет быть, ты отведешь нас туда, где живут другие детеныши? Мы слышали про такое место – Приют Зимних Плавников, которое находится в огромной Борейской тундре. Мы думаем, оно может находиться на границе с островом Хладарра.|n|nГоспожа попечительница говорит, что кто-то смелый спас выводок детенышей в этом месте. Наверное, им теперь тоже одиноко, и им нужны друзья. Ты отведешь нас туда?', },
    {'Отведите вашего подопечного Ру к Приюту Зимних Плавников. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.', },
  },
  [13951] = {
    'Друзья детства!',
    {'Кекеку грустно – в приюте слишком мало других щенят. Может быть, ты сводишь Кекека в гости?|n|nКекек знает племя, которое живет на Поляне Снегопада в Драконьем Погосте. Ты знаешь, где это? На севере от города людей-моржей в Гавани Моа\'ки и южнее Рубинового святилища драконов.|n|n<Кекек презрительно морщится при упоминании клыкарров.>|n|nОтведи туда Кекека. Может быть, Кекек встретит других волчеров и покажет им силу Бешеного Сердца!', },
    {'Отведите вашего подопечного Кекека на Поляну Снегопада. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.', },
  },
  [13952] = {
    'Благодарный покойник',
    {'Как приятно было навестить друзей и родных! Только, кажется, я немного перестарался... и съел все, что они приготовили для меня! Даже крошки подмел!|n|nМогу ли я попросить тебя принести мне еще вкусного поминального хлеба? Я бы был очень благодарен!|n|nКажется, рецепт можно купить у Чепмана.', },
    {'Принесите поминальный хлеб веселому духу человека на кладбище Штормграда.|n|nЧтобы увидеть дух, используйте оранжевые бархатцы.', },
  },
  [13953] = {
    'Наги среди нас',
    {'Похоже, череп этого существа был расколот в битве с Аросом, и внешне оно точно подходит под описание наги. |n|nГоворят, что несмотря на свой чудовищный облик, наги некогда были ночными эльфами, попавшими под власть тайной магии королевы Азшары.|n|nКажется, именно они пытаются помешать вам заполучить рог древних.', },
    {'Вернитесь к Балрену-медведю в Рощу Древних в Темные берега.', },
  },
  [13954] = {
    'Королева драконов',
    {'Верховный оракул Су-сэй говорил, что Великие создали всех драконов, и даже их королеву. Мы хотим ее увидеть! Ты отведешь нас на вершину Храма Драконьего Покоя? Мы помним, что Су-сэй рассказывал про храм – он в самом центре Драконьего Погоста.|n|nМы очень-очень хотим увидеть королеву драконов! Наверное, она очень большая и красивая. Может быть, она поможет нам найти новых родителей.|n|nПойдем?', },
    {'Отведите вашего подопечного Ру познакомиться с Алекстразой Связующей Жизнь, которая обитает на вершине храма Драконьего Покоя. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.', },
  },
  [13955] = {
    'Королева драконов',
    {'Кекеку всегда нравились драконы. Кекек даже хотел превратиться в дракона, но госпожа попечительница не разрешила. Но она сказала, что ты можешь отвести Кекека познакомиться с королевой драконов.|n|nКекек думает, что госпожа попечительница наконец-то предложила что-то хорошее. Ты отведешь Кекека в Храм Драконьего Покоя, в центре Драконьего Погоста? Давай встретимся с королевой драконов! Наверное, она очень большая, раз живет на самой вершине! Кекеку не терпится познакомиться с ней!', },
    {'Отведите вашего подопечного Кекека познакомиться с Алекстразой Хранительницей Жизни, на вершину храма Драконьего Покоя. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.', },
  },
  [13956] = {
    'Встреча с Великим',
    {'Верховный оракул Су-сэй всегда рассказывал нам про то, какие святилища строили Великие, и как мы дарили им блестяшки, но он сам никогда не видел Великих. Никто их не видел – но, может, ты знаешь, где их искать?|n|nСу-сэй говорит, что Великие построили врата и поставили их в центре южной части Шолазара. Су-сэй не знает, куда они ведут, но может быть, там мы найдем Великих! Отведи нас к вратам, $N, мы должны это выяснить!', },
    {'Отведите вашего подопечного Ру к Этимидиану на Террасу Создателя. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.', },
  },
  [13957] = {
    'Великий Хеминг Эрнестуэй',
    {'Знаешь, с кем Кекек всегда мечтал познакомиться? С Хемингом Эрнестуэем, про которого рассказывал Старейшина Харкек. Говорят, он странствует по Шолазару и охотится на огромных зверей! Даже старейшины племени Бешеного Сердца почитают Хеминга Эрнестуэя как великого охотника.|n|nСтарейшина Харкек сказал Кекеку, что Лагерь Эрнестуэя находится в центре западной части Шолазара, на берегу реки, которая называется Разлом Морского Потока. Своди Кекека туда, чтобы он спросил у Хеминга, как стать таким великим охотником!', },
    {'Отведите вашего подопечного Кекека познакомиться с Хемингом Эрнестуэем в Лагерь Эрнестуэя. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.', },
  },
  [13958] = {
    'Состояние критическое!',
    {'Враги отступают, и победа уже близка!|n|nОднако не стоит праздновать заранее, |3-6($C). Еще многое предстоит сделать до того, как Орда окончательно заявит свои права на Ясеневый лес.|n|nЯ слышал, что возле Приюта в Ночных Лесах снова идут бои, и ордынцы несут тяжелые потери. Судя по донесениям, среди них много раненых.|n|nОтнеси туда эти лекарственные препараты и передай Таггу. Расскажи ему о нашем нападении на Астранаар. Возможно, эта новость поднимет боевой дух наших воинов.', },
    {'Гоггат поручил вам отнести боевой перевязочный набор Таггу в приют в Ночных Лесах.', },
  },
  [13959] = {
    'Назад в приют',
    {'Нам было весело с тобой, $N. Жаль, что ты не можешь стать $Gнашим папочкой:нашей мамочкой;, и нам пора возвращаться к попечительнице сирот Арии в Даларан.|n|nМожет быть, ты еще навестишь нас как-нибудь? Нам очень понравилось общаться с малышами Зимних Плавников и с королевой драконов. И никто нам не поверит, что мы видели одного из Великих!|n|nМы будем скучать по тебе, $N. Обещаем, мы будем тебе писать!', },
    {'Отведите вашего подопечного обратно в приют Даларана, отдав детскую свистульку оракула попечительнице сирот Арии.', },
  },
  [13960] = {
    'Назад в приют',
    {'Знаешь, а мы не так уж и плохо провели время вместе, $N. Ты $Gпоказал:показала; Кекеку много всяких интересных мест. Кекек нашел новых друзей и сделал много всего такого, что не снилось другим щенкам.|n|nТеперь мы друзья – Кекек, ты, Хеминг Эрнестуэй и щенки Поляны Снегопада. Может быть, ты когда-нибудь принесешь Кекеку книгу про зеленые холмы? А Кекек обещает написать тебе как-нибудь и рассказать, как идут дела. Может быть, Кекек даже не будет больше дразнить длинноязыких детей.|n|nА теперь Кекеку пора возвращаться к попечительнице Арии, в фиолетовый город людей.', },
    {'Отведите вашего подопечного обратно в приют Даларана, отдав детскую свистульку волчера попечительнице сирот Арии.', },
  },
  [13961] = {
    'Допросить их',
    {'Следуя инстинкту, мы должны были бы разорвать нападающих на куски, но мудрость подсказывает иное. Нам необходимо допросить одного из этих погромщиков свинобразов и узнать все, что можно. Возьми эту сеть, $N, и поймай ею одного из них. Они атакуют нашу ферму с запада. Оглуши его и принеси сюда.', },
    {'Используйте сеть Гроль\'дома для поимки погромщика из племени Иглогривых и притащите его Тогрику на ферму Гроль\'дома.', },
  },
  [13962] = {
    'Безвыходное положение',
    {'Хотя боевые перевязочные наборы помогут нам продолжать сражаться, мы все еще находимся в безвыходном положении.|n|nДриад легко победить, но их предводитель воскрешает павших воинов, едва их тела коснутся земли. Нам приходится сражаться с бесконечным потоком этих вредителей!|n|nСам Хранитель Одан прячется вот в том мутировавшем древе. Сколько мы ни пытались пробиться к нему, все впустую. Может быть, тебе удастся добраться до этого шамана, пока мы будем расчищать тебе путь от дриад?|n|nДля покорителя Астранаара это должно быть легкой прогулкой.', },
    {'Тагг из приюта в Ночных Лесах просит вас убить хранителя Ордануса.', },
  },
  [13963] = {
    'Всеми правдами и неправдами',
    {'Думаю, если плеснуть ему в лицо ледяной водой, он придет в себя. Как ты думаешь, что он может рассказать нам?|n|nЯ запру его в загоне для животных, что находится сзади. Не думаю, что он будет долго оставаться в сознании. Узнай все, что сможешь о том, почему свинобразы нападают на наши фермы! Методы проведения допроса можешь выбирать самостоятельно.', },
    {'Допросите пленника из племени Иглогривых. Если он без сознания, Тогрик может привести его в чувство.', },
  },
  [13964] = {
    'К башне Звездной Пыли',
    {'Приют Серебряного Ветра пал! Увы, я не знаю, как это произошло – говорят, что ордынцы напали внезапно, и каким-то образом обратили на свою сторону элементалей-охранников озера Мистраль.|n|nВыжившие отступили в Башню Звездной Пыли, и им срочно нужна твоя помощь!|n|nТвой путь лежит на юго-юго-восток, к башне, которая возвышается у начала тропы Когтя, ведущей в Когтистые горы. Не сомневаюсь, часовой Велена Звездный Всполох уже готовит ответную атаку.', },
    {'Поговорите с часовой Веленой Звездный Всполох в Башне Звездной Пыли.', },
  },
  [13965] = {
    'Весточка от Эдьюнов',
    {'$N, если у тебя есть свободная минутка, я бы хотел попросить тебя о небольшой услуге.|n|nДавненько я не получал весточки от своих друзей, семьи Эдьюнов. Может быть, ты сбегаешь к ним и узнаешь, как они поживают?|n|nВечная благодарность тебе обеспечена. Их дом находится на маленьком островке земли к западу от святилища Эссины.', },
    {'Поговорите с Бенджари Эдьюном в доме Эдьюнов, что в Ясеневом лесу.', },
  },
  [13966] = {
    'Подарок Зимнего Покрова',
    nil,
    nil,
  },
  [13967] = {
    'Проредить... стадо?',
    {'В южных районах численность фурболгов превышает все наши расчеты. К тому же, они гораздо более агрессивны, чем ожидалось.|n|nУчитывая, что мы разрываемся между охотой на эльфов и добычей бесценной древесины, только ты можешь помочь нам сократить популяцию фурболгов.|n|nПока что я занимаюсь теоретическими расчетами, но вскоре ты понадобишься мне для проведения экспериментов. А пока что займись нашей мохнатой проблемой и принеси Таркану уши фурболгов в доказательство ее решения.', },
    {'Сенани Громовое Сердце в приюте Серебряного Ветра просит вас принести Таркану 15 ушей фурболгов – тотемистов из племени Гиблой Чащи и ведмедей из племени Гиблой Чащи.', },
  },
  [13968] = {
    'Уничтожение Мучеклыка',
    {'Кажется, в результате волнений на юге этот "Мучеклык" собрал под своими знаменами всех беженцев племени Иглогривых. Под его руководством они стали несколько опаснее обычных разбойников. С такими типами не дискутируют, его надо уничтожить и точка.|n|nЕсли наш пленник не врет, ты найдешь Мучеклыка к юго-востоку отсюда в месте, которое называется Тернистым холмом. Исследуй те утесы, откуда ему лучше всего видна дорога. Убей его, $N, и угроза минует.', },
    {'Уничтожьте Мучеклыка, предводителя Иглогривых.', },
  },
  [13969] = {
    'Пропавший кодо Гроль\'дома',
    {'$GДруг:Подруга;, если ты путешествуешь на юг, к Тернистому Холму, то, может быть, сможешь и поискать одного из наших пропавших кодо? Не каждый караван доходит до Дальней заставы. Эти головорезы Иглогривые угнали нагруженного кодо прошлым утром. Возможно, они уже убили его, но я надеюсь, что нет – наши стойла и без того опустели.', },
    {'Найдите пропавшего кодо Гроль\'дома где-то на Тернистом холме.', },
  },
  [13970] = {
    'Животноводство',
    {'Кодо – выносливые создания. Немного еды, и этот великан придет в себя.|n|nИглогривые ограбили немало караванов, и, должно быть, награбили огромное количество зерна. Мешки с украденным зерном можно найти в их лагерях.', },
    {'Соберите 5 мешков украденного зерна в лагерях Иглогривых на Тернистом холме.', },
  },
  [13971] = {
    'Возвращение кодо',
    {'Огромное животное медленно поднимается, стряхивает грязь и пыль степей со своих вновь мощных лап и, повинуясь инстинкту, медленно направляется в сторону фермы Гроль\'дома.|n|nТебе стоит поговорить с Краналом Фиссом и убедиться, что кодо успешно добрался до фермы.', },
    {'Поговорите с Краналом Фиссом с фермы Гроль\'дома, чтобы быть $Gуверенным:уверенной;, что пропавший кодо благополучно прибыл.', },
  },
  [13972] = {
    'Снова среди людей',
    {'Наконец-то! Похоже, снадобье Греннана подействовало на одного из диких!|n|nТеперь ты сможешь контролировать себя большую часть времени – только не давай гневу вырваться наружу.|n|nА сейчас с тобой хочет поговорить мэр Армстед. Гилнеас под осадой, и нам нужен каждый боец, способный держать оружие.', },
    nil,
  },
  [13973] = {
    'Ополчение Гроль\'дома',
    {'Они появились из ниоткуда, |3-6($C)! Орда Иглогривых, до самого горизонта – одни спины, рыла и клыки. Мы были вынуждены вернуться на ферму, но они продолжали наступать.|n|nЛучшие из наших защитников пали на поле боя, и мы не можем найти фермера Ралтона. Мне нужно, чтобы ты $Gзанял:заняла; наступательную позицию. Удерживай этих свинорылых на расстоянии, а я позабочусь о раненых до тех пор, пока не прибудет помощь.', },
    {'Убейте 6 погромщиков из племени Иглогривых.', },
  },
  [13974] = {
    'Маленькая посылка Шкрыпа',
    {'Вах!!!|n|nТы смотри, как горит! Это же потрясающе! Настоящий прорыв во взрывотехнике – чего, собственно, я и добивался...|n|nЯ буду самым знаменитым гоблином во всем Нордсколе!|n|nВеришь, нет, но я внес корректировки в формулу, чтобы результат вышел еще более взрывоопасным!|n|nВот, держи образец вещества. Его надо доставить к юго-востоку от Приюта Серебряного Ветра моему кузену Флузу. Полагаю, он найдет способ применить его на благо Орде.', },
    {'Шкрып попросил вас отнести маленькую посылку Флузу в приют Серебряного Ветра.', },
  },
  [13975] = {
    'Доставка каравана в Перекресток',
    {'*Рокко вручает тебе кажущийся знакомым дробовик.*|n|nВот, я почистил для тебя Халгину артиллерию. Думаю, об отдаче тебя предупреждать не нужно. Когда будешь $Gготов:готова; двинуться к Перекрестку, говори! Тхорк ждет тебя там. Смотри, не груби ему.|n|nНе останавливайся, $N, а если кто-то приблизится, двинь ему прикладом. Мы хотим гордиться тобой!', },
    {'Поговорите с Рокко Хлыстоногом с фермы Гроль\'дома и проводите его караван до Перекрестка.', },
  },
  [13976] = {
    'Три друга леса',
    {'Не хочешь совершить небольшое путешествие на юг? У меня там живут друзья, от которых давно уже не поступало вестей. Увы, я не могу покинуть свою семью и отправиться навестить их – $Gсам:сама; видишь, что тут творится. То какие-то щупальца лезут из-под земли, то демоны бродят по округе.|n|nОдного из моих товарищей зовут Больюн, и он разбил свой лагерь к северо-западу от этого проклятого святилища Огненной Расщелины. Аленндаар и Харлон намеревались присоединиться к нему, так что все вместе они должны быть в безопасности. Но кто сейчас может за это поручиться?|n|nЗаранее спасибо, $N.', },
    {'Поговорите с Больюном в его лагере, что в Ясеневом лесу.', },
  },
  [13977] = {
    'Массовое производство',
    {'Ха-ха! Ты это $Gвидел:видела;?!|n|nНадо немедленно запустить это в производство!|n|nВот, отнеси эти остатки Джинксу. Он строит новый склад к западу отсюда.', },
    {'Флуз просит вас отнести порошок "Пиф-паф!" Шкрыпа Джинксу в Производственный цех.', },
  },
  [13978] = {
    'Скрывающиеся во мгле',
    {'Мы построили стены и укрепления, чтобы защититься от врагов... но они все равно уже стоят на пороге.|n|nЧтобы сдержать первую волну нападавших, нашим ополченцам пришлось оставить город без защиты.|n|nУвы, мои худшие опасения подтвердились, и Гриммбург оказался под осадой орков.|n|nОни то ли ждут приказа наступать, то ли просто докладывают о наших передвижениях основным войскам. В любом случае – мы должны от них избавиться!|n|nЗнаю, ты $Gодин:одна; из диких, но ты не $Gчужой:чужая; в нашем городе. Дай врагу отпор, докажи, что в тебе осталось еще что-то человеческое.', },
    {'Гвен Армстед из Гриммбурга просит вас убить 8 орков-разведчиков.', },
  },
  [13979] = {
    'Гоблинские эксперты',
    {'Прекратить бы хоть ненадолго эти проклятые гоблинские бомбардировки! Мы смогли бы нанести ответный удар и отвоевать приют Серебряного Ветра.|n|nЯ всегда думала, что гоблины либо слишком ленивы, чтобы создать что-то стоящее, либо столь энергичны, что подрываются на собственных изобретениях. К несчастью, этими вредителями руководит сам главный бумженер Бдыжень.|n|nПослушай, отправляйся-ка ты к Производственному цеху на западной стороне приюта и не возвращайся без головы главного бумженера!', },
    {'Добудьте голову Бдыжня.', },
  },
  [13980] = {
    'Они где-то рядом!',
    {'Они где-то рядом, |3-6($C), и они охотятся на нас.|n|nМоих людей находят мертвыми, и у меня нет ни тени сомнения в том, что тут замешаны длинноухие!|n|nПохоже, твои действия в Астранааре заставили их изрядно поволноваться, и они изо всех сил пытаются отсрочить свое окончательное поражение.|n|nВот, возьми эти очки – в них ты увидишь даже самых пронырливых эльфов. Не дай им подобраться со спины, пока мы не закончим со взрывчаткой.', },
    {'Джинкс из Производственного цеха просит вас уничтожить 12 убийц из Ясеневого леса.', },
  },
  [13981] = {
    'Они готовят бомбу!',
    {'Это определенно самая огромная бомба из всех бомб, которые тебе когда-либо доводилось видеть. Да что там эти гоблины думали, когда создавали такое чудовище?|n|nУстройство выглядит вполне готовым. Гоблины постарались от души – похоже, этой шутке ничего не повредит, хотя вытащить ее отсюда будет проблематично.|n|nНужно как можно скорее сообщить о создании Большой Бомбы охотнице Джалин в Башню Звездной Пыли. Это к юго-западу отсюда.', },
    {'Доложите о существовании бомбы охотнице Джалин в Башне Звездной Пыли, что в Ясеневом лесу.', },
  },
  [13982] = {
    'В цепях',
    {'Берегись, $N. Когда мы попали в плен к Каливе, то слышали, как она упоминала твое имя.|n|nТолько ее сердце может освободить нас из этих оков, но я боюсь, что она подстроила тебе ловушку.', },
    {'Добудьте сердце Каливы.', },
  },
  [13983] = {
    'Гвозди для собственного гроба',
    {'Как только все будет готово, мы должны будем отправить эту бомбу прямиком в Саурбоз.|n|nКонечно, говоря "мы", я имею в виду тебя.|n|nПравда, учитывая численный перевес противников, шансы на успех невелики. Надо придумать что-нибудь серьезное, чтобы обеспечить твою безопасность.|n|nПожалуй, я мог бы переделать один из этих крошшеров, но мне потребуются запчасти. К счастью, их легко найти среди деревьев в западном лесу.|n|nЗаймись сбором, а я пока закончу работу над бомбой.', },
    {'Джинкс просит вас собрать 3 бронзовых шестеренки, 3 куска медной обшивки и 5 зажимных болта.', },
  },
  [13984] = {
    nil,
    {'Разведчики орков используют для слежки специально натасканных волков, и я не удивлюсь, если в их шайке есть и сам укротитель.|n|nТы принеси мне ошейники, которые носят эти волки, а мы пустим по их следу одну из наших гончих.', },
    nil,
  },
  [13985] = {
    'Очищение святилища',
    {'Злодеяниям Пылающего Легиона пора положить конец!|n|n$N, ты $Gпобедил:победила; одного из их самых могущественных прислужников, но в восточных лесах, в Святилище Огненной Расщелины, бродит еще множество омерзительных демонов.|n|nПрошу тебя, друг леса, убей этих мерзких созданий и предупреди об опасности Высокого Баобоба, древо войны из Святилища Эссины, что на северо-востоке.', },
    {'Убейте 12 демонов в святилище Огненной Расщелины.', },
  },
  [13986] = {
    'Раненый товарищ',
    {'Думаю, ты знаешь, какие жаркие бои ведутся в этих краях, |3-6($C). Нам пока удается удержать позиции, но не всегда удается избежать потерь.|n|nОдин из наших воинов, Апони Светлая Грива, была ранена в руку в одном из сражений. Ее тут же отправили назад в Громовой Утес для лечения, и она была так расстроена этим решением, что забыла здесь свой щит. Не затруднит ли тебя передать его ей вместе с нашими наилучшими пожеланиями? Мы все соскучились по ее улыбке.|n|nТы найдешь ее на Вершине Старейшин.', },
    {'Отнесите побитый фамильный щит Апони Светлой Гриве на Вершину Старейшин Громового Утеса.', },
  },
  [13987] = {
    'Последний рубеж',
    {'$N, мне крайне нужна твоя помощь! Я не могу вечно сдерживать наступление демонов. А если я потерплю поражение, Астранаар падет вместе со мной!|n|nУмоляю, помоги мне!', },
    {'Убейте 30 вторгшихся демонов.', },
  },
  [13988] = {
    'Растущая проблема',
    {'Внезапно появившаяся буйная растительность на прежде бесплодной земле... Мой приятель Джеррек уже видел такое где-то в Степях. Мне бы стоило взглянуть на это, но я не могу оставить свой пост.|n|nПоэтому, $N, я одолжу тебе свои "глаза". Этот орел мне служит с тех самых пор, как мне дали имя. Пожалуйста, возьми его с собой на Громовую Вершину, где ждет Джеррек, и мы во всем разберемся.|n|nЧтобы добраться туда, иди по дороге, ведущей от Перекрестка на восток. Поверни на юг у большого покрытого рисунками камня.', },
    {'Возьмите орла Глаза Тонги на Громовую Вершину на юго-западе от Кабестана.', },
  },
  [13989] = {
    'Король Гиблой Чащи',
    {'Мне нет дела до того, кто ты $Gтакой:такая;, |3-6($R). Меня заботит только судьба фурболгов.|n|nОтнеси это знамя Кровавого Клыка кратчайшим путем в деревню Зеленой Лапы и воткни древко в тотемный холм. Обитатели расценят это как знак агрессии и постараются уничтожить знамя, но ты оберегай его, пока на защиту чести племени не выйдет сам вождь Мургут. И тогда ты убьешь предателя!|n|nЗапомни, друг, тебе надо беречь силы и готовиться к долгому сражению.', },
    {'Поместите знамя Кровавого Клыка на тотемном кургане Гиблой Чащи и не позвольте фурболгам уничтожить его, пока не появится вождь. Одолейте вождя Мургута.', },
  },
  [13990] = {
    'Рекламный код Upper Deck – верховой цыпленок',
    nil,
    nil,
  },
  [13991] = {
    'Похищенное серебро',
    {'Ну что же, $N. Я признаю, что для тебя найдется место в великой Орде. Ты $Gпродемонстрировал:продемонстрировала; силу, хитрость, инициативу... И даже Тхорк недавно упоминал твое имя, а нас не так-то легко впечатлить. Хорошо.|n|nТеперь можно приступить к настоящей работе. Недавно был похищен груз серебра, предназначавшегося в уплату стражникам Перекрестка. Расследованием руководит Газрог из Кабестана. Поговори с ним!|n|nПросто следуй дорогой, ведущей отсюда на восток и попадешь на побережье.', },
    {'Поговорите с Газрогом у входа в Кабестан.', },
  },
  [13992] = {
    'Небольшая диверсия',
    {'Меня отправили сюда наблюдать за действиями кентавров. Я следил за каждым их перемещением в течение многих дней! Пришло время покинуть это место, но они окружили этот оазис.|n|nТы выглядишь довольно угрожающе. Можешь прикрыть меня? Устрой среди них переполох! Убивай всех без разбору. Пока они будут охотиться за тобой, я смогу выскользнуть отсюда незамеченным и доставлю собранную информацию Ретгару Вратам Cмерти.', },
    {'Убейте 8 кентавров из племени Колкар.', },
  },
  [13993] = {
    'Ты – бомба!',
    {'Ну что ж, $N, у нас все готово.|n|nЯ запрограммировал дорогу в Когтистые горы, так что тебе останется только побеспокоиться о самой бомбе.|n|nЕсли какой-нибудь недоброжелатель попробует сунуться к тебе, используй циркулярные пилы, а если врагам удастся подобраться слишком близко, оглуши их коротким замыканием.|n|nЗапомни, у тебя есть только один шанс починить бомбу, если она окажется серьезно повреждена.|n|nНу, собирайся с духом и возвращайся ко мне.|n|nУдачи!', },
    {'Джинкс просит вас направить модифицированный крошшер к Когтистым горам и поговорить с Саурбозом.', },
  },
  [13994] = {
    nil,
    {'Послушай, $N, ты $Gдолжен:должна; в точности выполнить указания инквизитора.|n|nОн утверждает, что Орда напала на Гилнеас. Если это правда – то мы должны как можно скорее предупредить клан Волчьего Сердца, пока еще не поздно.|n|nКроме того, Балвус Волчье Сердце с меня шкуру живьем снимет, если узнает, что я оставил тебя умирать на складах Седогрива.|n|nБеги, $N. Спасай свою шкуру... и предупреди наших братьев из Черной дубравы, когда придет время.', },
    nil,
  },
  [13995] = {
    'Гора короля кентавров',
    {'Нас прислали сюда, чтобы мы отследили перемещения кентавров из племени Колкар, но после недели наблюдений за тем, как эти грязные твари носятся по оазису, у меня руки чешутся познакомить мой топор с их шеями. Что скажешь, |3-6($C)? Поможешь мне?|n|nМожет, это заставит показаться Курака – самого сильного из них.', },
    {'Защитите Горгала Злошрама, когда он нападет на кентавров. Помогите ему убить Курака.', },
  },
  [13996] = {
    nil,
    {'Your mission, if you are able to read this while I\'m in combat, is to kill 5 of these insufferable little kobolds that are constantly keeping me in combat.|n|nJust the fact that you are reading this is a huge WIN! Isn\'t Dan awesome?!!', },
    nil,
  },
  [13997] = {
    nil,
    {'Dan is the most awesome programmer in the world... the World of Warcraft!|n|nIsn\'t it weird that you used to not be able to talk with me at all while I was fighting? No longer, my friend, now that Dan has made significant improvements to one of my creature flags!|n|nCelebrate with me by snuffing out the lives of these awful creatures that perpetually have me in combat.', },
    nil,
  },
  [13998] = {
    'Веруем в грибы',
    {'Я вырастил эти необычные споры, которые ты $Gвыкопал:выкопала; для меня, в самой питательной среде...реагентов... которой я действительно горжусь. Теперь я сгораю от нетерпения узнать, как выращенные споры поведут себя в воде оазисов Перекрестка.|n|nЗастывший Оазис на юго-востоке, пожалуй, наименее загрязнен, а значит, лучше всего подходит для нашего эксперимента. Просто посади эти споры во влажную почву рядом с оазисом и пронаблюдай за результатом.|n|nДержи рот на замке, |3-6($C).|n|n<Хелбрим обезоруживающе улыбается.>', },
    {'Посадите грибные культуры возле Застывшего оазиса и понаблюдайте за результатом.', },
  },
  [13999] = {
    'Кто кого дурит?',
    {'Подумай, $N, какие возможности! Постоянно развивающаяся служба доставки любых ядовитых грибов. Мои компаньоны в Подгороде непременно захотят узнать об этом.|n|nВот мои заметки и дополнительные образцы. Если поторопимся, успеем к следующему кораблю в Восточные королевства. Отправляйся по дороге, которая проходит к востоку отсюда, она приведет тебя в Кабестан. Найди таверну "Сломанный Киль" в южной части города, а в ней мою приятельницу Сашию и доставь ей это.', },
    {'Доставьте изыскания Хелбрима Сашие в Кабестан в Северных Степях.', },
  },
  [14000] = {
    nil,
    {'Думаю, этого хватит, чтобы выследить укротителя волков.|n|nОтнеси ошейники ловчему Расселу. Я уже попросил его выделить для этой цели одну из лучших гончих.', },
    nil,
  },
  [14001] = {
    'Гоблинские спасательные шлюпки',
    {'Ой, прости, $N, я думал, ты того!|n|nТут черти что творится, Орда погрызлась с Альянсом! Уж не знаю, кто это начал, но мы умудрились заплыть в самое пекло.|n|nНашим братьям и сестрам нужна помощь.|n|n<Гоблин тычет пальцем в сторону спасательных капсул, плавающих вокруг.>|n|nЯ немного посижу и соберусь с силами, а ты пока помоги потерпевшим! Возьми мои термогидратные ласты, с ними ты сможешь плавать быстрее.|n|nИ передай Хамми, что я скоро приплыву, чтоб она не волновалась.', },
    {'Спасите 6 уцелевших гоблинов.', },
  },
  [14002] = {
    nil,
    {'Отнеси ошейники в дальние клетки и дай их обнюхать любой гончей – они знают, что надо делать.|n|nКак только найдешь то, что ищешь, приготовься к жестокой схватке. И не забудь доложить мэру, что дело сделано.', },
    nil,
  },
  [14003] = {
    'Починка самофланжа',
    {'Так-так, он работает не так, как надо. Кажется, я его сломал.|n|nВпрочем, нет оснований для беспокойства. Окажи мне услугу, сбегай к Браку тут в лагере. Он быстро разберется с этой штуковиной!', },
    {'Отнесите сломанный самофланж к Браку Трубореву в лагере.', },
  },
  [14004] = {
    'Вернуться к создателю самофланжа',
    {'Увы, у меня ничего не вышло. Структурная целостность самофланжа крайне низка. Я могу добавить пару циферблатов и рычаг-другой, чтобы попытаться исправить это, но... от этого может стать только хуже.|n|nСмотри, что я нашла, когда заблокировала стравливающий клапан и сняла крышку с корпуса дифференциала: личное клеймо "Начальник Медноклин". Отнеси это обратно Пароклапану и скажи, что этот Медноклин – настоящий гений. Когда закончишь здесь, просто скажи мне, и я отправлю тебя обратно при помощи телепорта Брака.', },
    {'Отнесите переконструированные обломки самофланжа обратно Пароклапану в Лагерь Котельника. Чтобы попасть к нему, поговорите с Венаки.', },
  },
  [14005] = {
    'Месть Элуны',
    {'В то время как Тельдрассил очищает себя от порчи, которая затронула все, что выросло за эти годы, какое-то злокачественное образование появилось на краю, к югу отсюда. У нас есть возможность действовать быстро и удалить источник мха Скверны, который заразил Кривую Сосну, древесников и всех остальных.|n|nВода из лунных колодцев, которую ты $Gпринес:принесла;, и обновленная сила самого Тельдрассила помогут мне на некоторое время наделить тебя огромной мощью. Положи конец этой порче, $N.', },
    {'Используйте данные Тариндреллой силы, чтобы пробраться к источнику порчи и уничтожить его.', },
  },
  [14006] = {
    'Руководство по эксплуатации',
    {'Когда я был в Союзе механиков, начальник Медноклин был нашим лучшим инженером. Он переметнулся в Торговую Компанию незадолго до моего ухода, и все секреты его мастерства ушли вместе с ним. Он владел ценными знаниями, которыми понемногу делился с кругом приближенных.|n|nЕсли он сконструировал самофланж, то, наверное, у него есть и руководство по эксплуатации. Последнее, что я о нем слышал – что он работает в Каменном карьере, на северо-востоке. Возьми у него руководство и собери разрозненные страницы у его последователей.', },
    {'Соберите руководство по эксплуатации самофланжа.', },
  },
  [14007] = {
    'Верный выстрел',
    {'Я Бамм Взрыбомм, твой наставник.|n|nКак я понимаю, ты собираешься стать $Gвеликим:великой:c; |3-4($C)? Ну что же, будем учиться.|n|nНачнем с "Верного выстрела". Это полезное умение. И неплохой шанс заслужить уважение собратьев по цеху.|n|nИзучи данное умение и потренируйся на манекене.', },
    {'Поговорите с Баммом Взрыбоммом, обучитесь приему "Верный выстрел" и поразите тренировочный манекен 3 раза.', },
  },
  [14008] = {
    'Чародейские стрелы',
    {'Я Физз Лихтер, твой наставник.|n|nКак я понимаю, ты собираешься стать $Gвеликим:великой:c; |3-4($C)? Ну что же, будем учиться.|n|nНачнем с "Чародейских стрел". Это полезное умение. И неплохой шанс заслужить уважение собратьев по цеху. Изучи данное заклинание и потренируйся на манекене, что стоит в юго-восточной части двора.', },
    {'Поговорите с Физзом Лихтером и обучитесь заклинанию "Чародейские стрелы", после чего дважды опробуйте его на тренировочном манекене.|n|nПомните, что "Чародейские стрелы" можно использовать только с некоторой вероятностью после применения других атакующих заклинаний. Для того чтобы активировать "Чародейские стрелы", вначале используйте на тренировочном манекене заклинание "Огненный шар".', },
  },
  [14009] = {
    'Быстрое исцеление',
    {'Я сестра Горазлата, твой наставник.|n|nКак я понимаю, ты собираешься стать $Gвеликим:великой:c; |3-4($C)? Ну что же, будем учиться.|n|nНачнем с "Быстрого исцеления". Это полезное умение. И неплохой шанс заслужить уважение собратьев по цеху. Изучи данное заклинание и потренируйся в исцелении раненых сотрудников во дворе.', },
    {'Поговорите с сестрой Горазлатой и обучитесь заклинанию "Быстрое исцеление", после чего трижды используйте его на раненом сотруднике.', },
  },
  [14010] = {
    'Потрошение',
    {'Я Крадли Дротик, твоя наставница.|n|nКак я понимаю, ты собираешься стать $Gвеликим:великой:c; |3-4($C)? Ну что же, будем учиться.|n|nНачнем с "Потрошения". Это полезное умение. И неплохой шанс заслужить уважение собратьев по цеху. Изучи данное умение и потренируйся на манекене, что стоит в юго-восточном углу двора.', },
    {'Поговорите с Крадли Дротик и обучитесь приему "Потрошение", после чего трижды опробуйте его на тренировочном манекене.|n|nПомните, что данный прием является продолжением серии, поэтому для начала потребуется применить против манекена умение "Коварный удар".', },
  },
  [14011] = {
    '"Стихийный удар"',
    {'Я Максс Оползень, твой наставник.|n|nКак я понимаю, ты собираешься стать $Gвеликим:великой:c; |3-4($C)? Ну что же, будем учиться.|n|nНачнем со "Стихийного удара". Это полезное умение. И неплохой шанс заслужить уважение собратьев по цеху. Изучи данное умение и потренируйся на манекене, что стоит в юго-восточном углу двора.', },
    {'Поговорите с Макссом Оползнем и обучитесь приему "Стихийный удар", после чего дважды опробуйте его на тренировочном манекене.', },
  },
  [14012] = {
    'Жертвенный огонь',
    {'Я Ехид Опальчик, твой наставник.|n|nКак я понимаю, ты собираешься стать $Gвеликим:великой:c; |3-4($C)? Ну что же, будем учиться.|n|nНачнем с "Жертвенного огня". Это полезное умение. И неплохой шанс заслужить уважение собратьев по цеху. Изучи данное заклинание и потренируйся на манекене, что стоит в юго-восточной части двора.', },
    {'Поговорите с Ехидом Опальчиком и обучитесь заклинанию "Жертвенный огонь", после чего трижды опробуйте его на тренировочном манекене.', },
  },
  [14013] = {
    'Рывок',
    {'<Воин-матик NX-01 включается в оперативный режим.>|n|nОбнаружен босс $N. Я Воин-матик NX-01.|n|nОпустите монету, чтобы получить сеанс массажа или обучиться приему "Рывок". После изучения приема потренируйтесь на манекене, что стоит поблизости.', },
    {'Поговорите с Воином-матиком NX-01 и обучитесь приему "Рывок", после чего опробуйте его на тренировочном манекене.', },
  },
  [14014] = {
    'Верните наши вещи!',
    {'Наши бомбы и инструменты! Подлые макаки выкрали их под покровом ночи и унесли на восток!|n|nПожалуйста, доберись до обезьяних владений и конфискуй то, что принадлежит нам по праву. Я верю, ты справишься, $N. Без инструментов мы застрянем на этом острове навеки!', },
    {'Добудьте 8 ящиков инструментов.', },
  },
  [14015] = {
    nil,
    {'Вы разворачиваете свиток и обнаруживаете довольно подробную карту Гилнеаса, всего с одной ошибкой – все пространство между побережьем и гриммбургскими скалами не прорисовано.|n|nТакже на карте изображены стрелки, вероятн обозначающие планы Орды по продвижению вглубь Гилнеаса. Несомненно, мэру Армстед пригодится этот документ.', },
    nil,
  },
  [14016] = {
    'Проклятие Черного рыцаря',
    {'После твоей победы я было распорядилась убрать останки Черного рыцаря с Ристалища, но исповедница Пейлтресс настояла на том, чтобы похоронить его по всем правилам. И с тех пор на нашем кладбище происходят странные вещи, которые отпугивают жителей, желающих воздать почести павшим героям.|n|nТы не $Gмог:могла; бы лично посетить кладбище и выяснить, что там творится? Оно находится на восточном краю Ристалища.', },
    {'Рыцарь Райдалла из Серебряного павильона на Ристалище Серебряного Турнира просит вас осмотреть могилу Черного рыцаря.', },
  },
  [14017] = {
    'Судьба Черного рыцаря',
    {'Говоришь, его тело забрали служители культа Проклятых? Я знаю только одно место, куда они могли бы его отнести: это Застава Вестника Смерти, что на западе от Ристалища.|n|nМы должны остановить их во что бы то ни стало. Это только подтверждает правдивость мрачных слухов... Среди них совершает свои темные обряды бесславный доктор Колер. Найди алтарь, возвышающийся над лагерем служителей культа, убей доктора и принеси мне доказательства его грязных деяний. Любой ценой замедли их работу!', },
    {'Перехватите приказы доктора Колера на Заставе Вестника Смерти, а затем вернитесь к рыцарю Райдалле в Серебряный павильон на Ристалище Серебряного Турнира.', },
  },
  [14018] = {
    'Тот, кто будет прощен',
    {'Это голос самой богини воззвал к тебе из колодца, $N! Лекарство для Релары находится к востоку от Башни в Ночных лесах. Там ты найдешь того, кто поддался скверне.|n|nАврий Дурной Толк – именно тот, кто жаждет прощения и очищения. Если ты поможешь ему, то спасешь и мою дочь.', },
    {'Поговорите с Аврием Дурным Толком у башни в Ночных лесах, что в Ясеневом лесу.', },
  },
  [14019] = {
    'Связка спелых бананчиков',
    {'У нас тут вот какое дело. В джунглях на востоке водится множество обезьян. Так эти макаки стащили всю нашу взрывчатку и теперь швыряются ею куда ни попадя.|n|nИногда – прямо в нас!|n|nПо моей просьбе Физз Лихтер начинил эти бананы селитрой. Ни одна обезьяна не устоит перед связкой спелых бананчиков!|n|nТебе всего-то и нужно, что пойти в джунгли и покормить обезьянок.', },
    {'Накормите 10 обезьян с гранатой, бросив им бананы с селитрой.', },
  },
  [14020] = {
    'Проклятие',
    {'Проклятие застало всех нас врасплох. Все было в порядке, пока однажды целые деревни не начали превращаться в стаи воющих воргенов. По приказу лорда Седогрива мы не покладая рук пытались найти лекарство от этой напасти, но удача от нас отвернулась.|n|nОднако нам все же удалось обнаружить нечто обнадеживающее. Оказалось, что очищенная вытяжка из черной мандрагоры способна облегчить большинство симптомов Проклятия.|n|nНо беда не ходит в одиночку. После нападения орков связь с нашим городом прервалась, и мне неоткуда больше достать сырье для снадобья. Пожалуйста, если тебе встретится по пути черная мандрагора, собери ее и принеси мне, чтобы я смог приготовить еще немного вытяжки.', },
    {'Креннан Аранас из Гриммбурга просит вас раздобыть 8 черных мандрагор.', },
  },
  [14021] = {
    'Глубинная суть проблемы',
    {'Хитроумные обезьяны-рудокопы!|n|nВ этой пещере их полно, и они добывают руду... кирками! Это совсем не похоже на них, и я уверен, что все дело в каджа\'мите!|n|nНикто из моих горняков не вернулся... У меня почти не осталось работников! $N, ты же видишь, ситуация безвыходная.|n|n<Штейгер понижает голос.>|n|nЭти парни и в подметки не годятся моей старой команде. Какие были тролли! Какие тролли! Сейчас таких уже не делают!|n|nНо, может, ты проводишь моего последнего шахтера в пещеру и защитишь его от обезьян? Пойми, нам очень нужен каджа\'мит!', },
    {'Проведите испуганного шахтера по Каджа\'митовой пещере.', },
  },
  [14022] = {
    'Пиршество странников',
    {'А ты не хочешь присоединиться к Пиршеству странников, $N? Когда-то в этот день мы вспоминали о былых путешествиях, рассказывали друзьям о том, как нам улыбнулась удача, и приглашали их разделить с нами пищу. Многие до сих пор соблюдают эту традицию.|n|nТы тоже можешь отметить Пиршество странников – в честь этого праздника в каждой столице накрыты пиршественные столы, ломящиеся от изобилия яств. |n|nА если ты хочешь узнать, как готовятся эти изысканные кушанья, найди Грегори Табора – он стоит рядом с вратами Штормграда.', },
    {'Поговорите с Грегори Табором – он стоит рядом с вратами Штормграда.', },
  },
  [14023] = {
    'Пряная хлебная запеканка',
    {'Наша пряная хлебная запеканка – главное блюдо праздничного стола Пиршества странников. Этот рецепт недаром включен в пиршественную поваренную книгу как самое популярное блюдо Штормграда.|n|nЕсли ты умеешь готовить, навести торговцев Пиршества странников и купи пиршественную поваренную книгу, а также все необходимые ингредиенты для приготовления праздничного угощения. А если ты не знаешь, как обращаться с кастрюлями и сковородками – самое время научиться!|n|nКак только приготовишь хлебную запеканку, принеси ее Джасперу Муру, он стоит возле праздничных столов.', },
    {'Приготовьте 5 порций пряной хлебной запеканки и отнесите ее Джасперу Муру, который стоит возле праздничных столов у ворот Штормграда.', },
  },
  [14024] = {
    'Тыквенный пирог',
    {'Ах, как ароматно пахнет приготовленная тобой пряная хлебная запеканка! Но праздничный стол Пиршества странников невозможно представить без огромного тыквенного пирога. Этот десерт очень популярен в Штормграде, поскольку готовится из спелых элвиннских тыкв, которые растут только в этих краях.|n|nЕсли ты еще не знаешь, как готовить тыквенный пирог, загляни в свою пиршественную поваренную книгу.|n|nКстати, тебя не затруднит испечь несколько кусочков и отнести их Эдварду Уинслоу? Он накрывает столы рядом со Стальгорном, и тыквенный пирог наверняка у него уже кончился.', },
    {'Испеките 5 кусков тыквенного пирога и принесите их Эдварду Уинслоу, который стоит возле праздничных столов Стальгорна.', },
  },
  [14025] = {
    'На линии фронта',
    nil,
    nil,
  },
  [14026] = {
    'Шумные прощания',
    nil,
    nil,
  },
  [14027] = {
    'Лицом к лицу',
    {'Моим людям очень нужна помощь, $N. Мы из всех сил стараемся дать оркам отпор, но нас слишком мало.|n|nНо если ты уничтожишь несколько нападавших, это склонит чашу весов в нашу пользу. Посмотрим, способны ли члены твоего клана убивать врагов, или ярости вашей хватает только на охоту за нашими овцами.', },
    {'Лейтенант Райт поручил вам убить 10 орков-захватчиков.', },
  },
  [14028] = {
    'Клюквенный соус',
    {'Если ты еще не $Gпробовал:пробовала; клюквенный соус – ты не знаешь вкус жизни. Он делается из свежайшей клюквы, которая растет в Болотине. Если хочешь попробовать его приготовить – купи все, что тебе надо, у продавца Пиршества странников.|n|nА рецепт должен быть в твоей пиршественной повареной книге.|n|nЕсли у тебя есть свободная минутка – может быть, ты поможешь Джасперу Муру приготовить очередную порцию соуса для штормградского стола? Я как раз собирался обменять пару порций на испеченный тобой пирог.', },
    {'Приготовьте 5 порций клюквенного соуса и отнесите ее Джасперу Муру, который стоит возле праздничных столов у ворот Штормграда.', },
  },
  [14029] = {
    'Прорвать осаду',
    nil,
    nil,
  },
  [14030] = {
    'Голодающие Дарнаса',
    {'Спасибо за клюквенный соус! Нам еще так много надо приготовить – я просто не успеваю за всем следить. Но самое главное – я должен заботиться о том, чтобы Исаак Аллертон из Дарнаса не испытывал недостатка в провизии, а у него как раз кончились все угощения. Я могу рассчитывать на твою помощь? Было бы неплохо, если бы ты $Gприготовил:приготовила; несколько порций хлебной запеканки и тыквенного пирога. Все нужные ингредиенты есть у продавца.|n|nОтнеси готовую еду к праздничным столам, которые накрыты рядом со входом в Дарнас, прямо под Террасой Воинов.', },
    {'Приготовьте 5 порций хлебной запеканки и отнесите ее Исааку Аллертону, который стоит у входа в Дарнас.', },
  },
  [14031] = {
    'Фотоохота',
    {'Эй, $N, тут по всей пещере какие-то странные рисунки и другие артефакты.|n|nМожет, ты воспользуешься своей фотокамерой ТКК с ультравспышкой и сделаешь снимки в означенных местах? Кроме того, сфотографируй алтарь, который находится в глубине пещеры.|n|nУверен, Хамми это будет интересно.', },
    {'Фотокамерой ТКК с ультравспышкой сделайте снимки алтаря пигмеев и наскальных рисунков в трех пещерах.', },
  },
  [14032] = {
    nil,
    {'Первое твое задание, $N, – это зачистка. Северные леса наводнили кобольды. Ступай туда и уничтожь столько кобольдов-вредителей, сколько сможешь. Сократи их число, чтобы в один прекрасный день мы смогли вытеснить их из Североземья.', },
    {'Уничтожьте 8 кобольдов-вредителей. Вернитесь к маршалу Макбрайду.', },
  },
  [14033] = {
    'Засахаренный батат',
    {'Раз уж ты здесь, помоги нам пополнить запасы тельдрассильской сладкой картошки – она идет на изготовление самого вкусного засахаренного батата, который ты когда-либо $Gпробовал:пробовала;.|n|nЕсли не веришь – приготовь $Gсам:сама;, этот рецепт есть в твоей пиршественной поваренной книге. А если после этого у тебя останется немного угощения – можешь поделиться с Грегори Табором, который накрывает столы возле Штормграда. Он их просто обожает, хотя его послушать – так можно подумать, у него каждое блюдо самое любимое.', },
    {'Приготовьте 5 порций засахаренного батата и отнесите их Грегори Табору, который стоит у ворот Штормграда.', },
  },
  [14034] = {
    'Припугнуть Фута',
    {'Благодаря последнему конфликту между Альянсом и Ордой я получал прибыль, пока контр-адмирал Хартли не навестил МОЙ порт и не засунул нос своего корабля в мои дела. Он разыскивал корабли Орды и лишал их возможности посещать нейтральный порт.|n|nЯ не собираюсь позволять ему загребать мои деньги своими пухлыми ручонками! Раздобудьте мне план его флагманского судна. Главный инженер Хартли пьянствует в таверне "Сломанный киль" вон там на холме...', },
    {'Добудьте чертеж корабля у главного инженера Фута в таверне "Сломанный киль", что в Кабестане.', },
  },
  [14035] = {
    'Запеченная индейка',
    {'Какой же праздник Пиршества странников без главного украшения – и я вовсе не имею в виду бутафорский рог изобилия. Я говорю про огромную жареную индейку, царицу праздничного стола!|n|nПо-моему, в твоей пиршественной поваренной книге есть подходящий рецепт. Почему бы тебе не убить несколько диких индеек и не приготовить их к празднику? Индейки водятся повсюду в Элвиннском лесу, так что тебе не составит труда отыскать добычу.|n|nКак только закончишь готовить, принеси жареных индеек Исааку Аллертону к вратам Дарнаса, хорошо?', },
    {'Приготовьте 5 запеченных индеек и отнесите их Исааку Аллертону к вратам Дарнаса.', },
  },
  [14036] = {
    'Пиршество странников',
    {'Ты $Gпришел:пришла; сюда, чтобы отпраздновать с нами Пиршество странников? Когда-то в этот день мы вспоминали о былых путешествиях, рассказывали друзьям о том, как нам улыбнулась удача, и приглашали их разделить с нами пищу. Многие до сих пор соблюдают эту традицию.|n|nТы тоже можешь отметить Пиршество странников – в честь этого праздника в каждой столице накрыты пиршественные столы, ломящиеся от изобилия яств. |n|nА если ты хочешь узнать, как готовятся эти изысканные кушанья, найди Майлса Стендиша во внутреннем дворе Подгорода.', },
    {'Поговорите с Майлсом Стендишом во внутреннем дворе Подгорода.', },
  },
  [14037] = {
    'Пряная хлебная запеканка',
    {'Наша пряная хлебная запеканка – главное блюдо праздничного стола Пиршества странников. Этот рецепт был придуман еще во времена расцвета Лордерона, и дошел до наших дней без изменений.|n|nЕсли ты умеешь готовить, навести торговцев Пиршества странников и приобрети пиршественную поваренную книгу, а также все необходимые ингредиенты для приготовления праздничного угощения. А если ты не знаешь, как обращаться с кастрюлями и сковородками – самое время научиться!|n|nКак только приготовишь хлебную запеканку, принеси ее Вилльяму Маллинсу, который стоит возле праздничных столов.', },
    {'Приготовьте 5 порций пряной хлебной запеканки и отнесите ее Вилльяму Маллинсу, который стоит возле праздничных столов во внутреннем дворе Подгорода.', },
  },
  [14038] = {
    'Кто не с нами, тот против нас',
    {'<Газлоу расстилает план на столе и после некоторого размышления тыкает пальцем в место в кормовой части судна, ниже ватерлинии>.|n|nЗдесь! Здесь, где коленвал подходит к винтовому механизму, обшивка тоньше всего. И это прямо рядом с крюйт-камерой!|n|n$N, я, конечно же, не буду иметь никакого отношения к тому, что $Gкакой-то предприимчивый:какая-то предприимчивая:c; |3-6($C) из Орды прикрепит мину к этой части судна. Даже если я сам и дал $Gему:ей; эту мину. И заплатил $Gему:ей;. Корабль стоит на якоре к юго-востоку отсюда... иди туда!|n|nПотом свяжись со мной по радио при помощи этого краденого ГНМ-передатчика.', },
    {'Прикрепите магнитную мину в самой тонкой части корпуса "Непобедимого".', },
  },
  [14039] = {
    'Дом Калдорай',
    {'Встретить тебя – бесспорная честь для меня. Ты доказательство благородства нашей расы.|n|nТеперь иди и закончи последнее задание. Отнеси воды Тиранде Шелест Ветра в Дарнас.', },
    {'Отнесите наполненный сосуд Тиранде Шелест Ветра в Дарнас.', },
  },
  [14040] = {
    'Тыквенный пирог',
    {'Ты $Gприготовил:приготовила; отличную хлебную запеканку! Но праздничный стол Пиршества странников невозможно представить без огромного тыквенного пирога. Этот десерт очень популярен в наших краях, поскольку готовится из спелых тирисфальских тыкв, которые растут только в этих краях.|n|nЕсли ты еще не знаешь, как готовить тыквенный пирог, загляни в свою пиршественную поваренную книгу.|n|nКстати, тебя не затруднит испечь несколько кусочков и отнести их Фрэнсису Итону? Он накрывает столы рядом со Оргриммаром, и наверняка у него уже кончился тыквенный пирог.', },
    {'Испеките 5 кусков тыквенного пирога и принесите их Фрэнсису Итону, который стоит у праздничных столов возле Оргриммара.', },
  },
  [14041] = {
    'Клюквенный соус',
    {'Ты уже $Gпробовал:пробовала; клюквенный соус? Он делается из свежайшей клюквы с берегов реки Строптивой. Если хочешь его приготовить – купи все необходимое у торговца Пиршества странников.|n|nА рецепт записан в твоей пиршественной повареной книге.|n|nЕсли у тебя есть свободная минутка – может быть, ты поможешь Докину Дальнему Лугу приготовить немного соуса? Он стоит у подъемника на западе Громового Утеса.', },
    {'Приготовьте пять порций клюквенного соуса и принесите их Докину Дальнему Лугу, который ждет у подъемника на западе Громового Утеса.', },
  },
  [14042] = {
    'Оружие и контрабанда',
    {'Должно быть, Хартли выгрузил всю свою артиллерию на берегу. Давай-ка заставим его показать зубы, $N!|n|nПробегись по берегу и найди его боеприпасы. Подожги их. Он останется безоружным и застрянет на берегу, пока чинят "Непобедимый". А я буду ждать тебя в Кабестане.', },
    {'Уничтожьте 5 Тераморских схронов боеприпасов на берегу.', },
  },
  [14043] = {
    'Засахаренный батат',
    {'Раз уж ты здесь, помоги нам пополнить запасы мулгорской сладкой картошки – она идет на изготовление самого вкусного засахаренного батата, который ты когда-либо $Gпробовал:пробовала;.|n|nЕсли не веришь – приготовь $Gсам:сама;, этот рецепт есть в твоей пиршественной поваренной книге. А если после этого у тебя останется немного угощения – можешь поделиться с Фрэнсисом Итоном, который накрывает столы возле Оргриммара. Боюсь, у него опять кончились все запасы угощений, несмотря на все мои усилия.', },
    {'Приготовьте 5 порций засахаренного батата и принесите их Фрэнсису Итону, который стоит у праздничных столов возле Оргриммара.', },
  },
  [14044] = {
    'Нехватка продовольствия в Подгороде',
    {'Спасибо за то, что $Gпринес:принесла; нам засахаренный батат! Нам еще так много надо приготовить – я просто не успеваю за всем следить. А тут еще Майлс жалуется на то, что у него практически кончился клюквенный соус и запеканка. Я могу рассчитывать на твою помощь? Было бы неплохо, если бы ты $Gприготовил:приготовила; несколько порций угощения. Все нужные ингредиенты есть у продавца.|n|nОтнеси готовую еду Майлсу к праздничным столам, которые накрыты в руинах над Подгородом.', },
    {'Приготовьте 5 порций пряной хлебной запеканки и 5 порций клюквенного соуса, и отнесите их Майлсу Стендишу к входу в Подгород.', },
  },
  [14045] = {
    'Найти барона Дольноберега',
    {'Этот грязный пират барон Дольноберег держал в страхе местные воды до тех пор, пока Альянс не потопил его флот и не повязал выживших. Думаешь, я доволен? По мне видно, что я свечусь от радости, $N?|n|nДо того, как его поймали, Дольноберег захватил один из моих самых ценных грузов. Я хочу получить обратно свои товары! Найди Дольноберега в лагере Альянса к югу отсюда и попробуй заставить его рассказать, где он держит мои сокровища.', },
    {'Найдите упомянутого пирата барона Дольноберега и поговорите с ним.', },
  },
  [14046] = {
    'Потребности истинного барона',
    {'Да, $Gприятель:подруга;, я без сомнений отправлюсь на виселицу. На кой мне теперь эти сокровища…|n|nРазве что купить на них свою жизнь. Я заключу с тобой сделку, |3-6($R). Разбей эти наручники и я скажу тебе, где закопаны сокровища.|n|nО, моему слову можно верить, $Gприятель:подруга;. Я же был настоящим бароном.', },
    {'Если вы доверяете барону Дольноберегу, поговорите с ним и освободите его от наручников.', },
  },
  [14047] = {
    'Запеченная индейка',
    {'Какой же праздник Пиршества странников без главного украшения – огромной жареной индейки, царицы праздничного стола!|n|nПо-моему, в твоей пиршественной повареной книге есть подходящий рецепт. Почему бы тебе не убить несколько диких индеек и не приготовить их к празднику? Индейки водятся повсюду в Тирисфальских лесах, так что тебе не составит труда отыскать добычу.|n|nКак только закончишь готовить, принеси жареных индеек Фрэнсису Итону к вратам Оргриммара, хорошо?', },
    {'Приготовьте 5 запеченных индеек и принесите их Фрэнсису Итону к вратам Оргриммара.', },
  },
  [14048] = {
    'Слишком мало индеек',
    {'С самого начала праздника я не отхожу от плиты, но угощений надо гораздо больше, чем я могу приготовить одна. Может быть, мне удастся уговорить тебя помочь?|n|nХорошую дикую индейку тут найти очень сложно, может ты сумеешь принести мне несколько порций? Ты можешь купить несколько порций уже готового блюда или приготовить $Gсам:сама;. Если ты решишь их готовить, то могу посоветовать охотиться на птиц в Элвиннском лесу. Все остальные ингредиенты можно купить у любого торговца Пиршества странников.', },
    {'Принесите 20 запеченных индеек Кэтрин Железный Чан к вратам Стальгорна.', },
  },
  [14049] = {
    'Самая необычная карта',
    {'Такое дельце, $Gприятель:подруга;. Чтобы защитить карту сокровищ, я вытатуировал ее на голове моего первого помощника.|n|nРазумеется, сейчас он мертв, как и все остальные члены команды. Альянс понятия не имеет, что у них в руках, и его отрубленная голова украшает сейчас дерево у входа в их лагерь.|n|nСними эту голову и принеси ее Газлоу в Кабестан.', },
    {'Возьмите татуированную голову у входа в лагерь Альянса.', },
  },
  [14050] = {
    'Богатство Газлоу',
    {'Разрази меня гром! Ты $Gбыл:была; $Gправ:права;!|n|nЧертов Барон, а? Зарыл сокровище прямо у меня под носом. Или, вернее, прямо над головой. На карте отмечено место в скалах над Кабестаном, на юге.|n|nВыйди из города по дороге на запад, заберись на холм, поверни на юг и иди обратно к берегу, там найди огромное дерево на берегу залива. Принеси мне мое сокровище и получишь свою долю!', },
    {'Газлоу из Кабестана хочет, чтобы вы отправились в скалы над городом и выкопали его сокровище.', },
  },
  [14051] = {
    'Не забыть про запеканку!',
    {'Ох, как нелегко следить за тем, чтобы праздничные столы не пустовали! Одной рукой помешиваю клюквенный соус, другой готовлю засахаренный батат, а еще надо следить за тем, чтобы пироги не подгорели!|n|nИ почему у меня такое чувство, что я что-то упустила из виду? Точно, я забыла про запеканку! Ай, беда... что же делать? Я уже не успею приготовить все, что собиралась! Послушай, может быть, ты мне поможешь? Это несложно – просто купи несколько тарелок готовой запеканки или приготовь ее $Gсам:сама; – все ингредиенты можно купить прямо здесь.', },
    {'Принесите 20 порций пряной хлебной запеканки Кэтрин Железный Чан к праздничным столам у ворот Стальгорна.', },
  },
  [14052] = {
    'Встреча с Тони',
    {'Эта ситуация с пиратами мне все портит. Капитан Шпрота нападает на все корабли, какие увидит. Даже на те, чьи владельцы заплатили мне за "покровительство". Мы должны стрясти деньги с этих пиратов и побыстрее!|n|nЯ знаю одного парня, он лейтенант у Шпроты, такой же корыстный делец, как и Головокружилкинс. Я предложил ему устроить маленький "мятеж" и переманить кое-кого из пиратов на нашу сторону. Если эти ребята будут работать на нас, мы станем получать бешеные деньги, понимаешь?|n|nПоговори с Тони Два Клыка на Острове Битв к югу отсюда.', },
    {'Поговорите с Тони Два Клыка на Острове Битв, что в Северных Степях.', },
  },
  [14053] = {
    'У нас опять кончился соус?',
    {'Мой супруг, Джаспер, собирался приготовить клюквенный соус, но потом оказалось, что на столах слишком мало засахаренного батата. Похоже, ему не справиться без посторонней помощи. Если ты умеешь готовить, можешь купить клюкву у продавца Пиршества странников – он стоит рядом с вратами в Стальгорн.|n|nА если тебе не хочется браться за половник – ты всегда можешь попросить кого-нибудь приготовить соус для тебя.', },
    {'Принесите 20 порций клюквенного соуса Эллен Мур к праздничным столам возле Штормграда.', },
  },
  [14054] = {
    'Проще пареной тыквы',
    {'Исаак трудится не покладая рук, чтобы все смогли отведать разнообразные угощенья в честь Пиршества странников, и научились готовить традиционные блюда из тех продуктов, что принес нам последний урожай. Я же стараюсь, чтобы гости ни в чем не испытывали недостатка, но одно из любимых блюд Исаака – тыквенный пирог – уже практически закончилось.|n|nТы сможешь принести еще? Если возьмешься лично его приготовить, купи несколько спелых элвиннских тыкв у праздничного торговца возле Штормграда.', },
    {'Принесите 20 кусков тыквенного пирога Мэри Аллертон к праздничным столам возле Дарнаса.', },
  },
  [14055] = {
    'Батат – значит, батат!',
    {'Моя жена Эллен попросила меня проследить за тем, чтобы столы не пустовали, а сама никак не может определиться, что же ей приготовить. Сначала она поручила мне испечь тыквенный пирог, а потом передумала и решила делать засахаренный батат.|n|nА у меня уже тесто для пирога поднялось! Послушай, может быть, ты займешься этой сладкой картошкой? Представлешь, как она обрадуется, если мы приготовим все, что ей хотелось?|n|nКстати, все необходимые ингредиенты можно приобрести у праздничного торговца в Дарнасе. Удачи, $N.', },
    {'Принесите 20 порций засахаренного батата Джасперу Муру к праздничным столам возле Штормграда.', },
  },
  [14056] = {
    'Там мрачный Гломп над златом чахнет',
    {'Что? Мятеж по дешевке – это к Головокружилкинсу.|n|nДа, $Gприятель:подруга;, мы можем сделать эту работу. Но деньги вперед. Капитан Шпрота складирует все денежки, которые мы получаем. Из них я смогу заплатить мятежникам.|n|nСокровища лежат сразу за казармами. Займись сначала "казначеем" капитана. С Гломпом справиться нелегко. Поверь мне на слово, уж я пробовал.', },
    {'Убейте Гломпа и добудьте сокровища Гломпа.', },
  },
  [14057] = {
    'Оружие. Нам нужно оружие',
    {'Для настоящего хорошего мятежа нужно оружие. Все лучшее капитан Шпрота взял себе: целую партию больших тяжелых дворфийских кремневых винтовок. Он хранит их где-то в другом здании на острове. Принеси мне шесть таких винтовок и я раздам их моим будущим офицерам...', },
    {'Соберите 6 тяжелых дворфийских винтовок.', },
  },
  [14058] = {
    'Батат – значит, батат!',
    {'Роберта Картер попросила меня помочь ей и приготовить одно из ее любимых блюд – засахаренный батат. Я бы рад помочь, но уже пообещал хозяйке накрыть на стол.|n|nМоя благодарность не будет иметь границ, если ты поможешь мне с этим. Роберта никогда не простит мне, если я ее подведу.|n|nКстати, если ты собираешься самостоятельно приготовить это блюдо, могу порекомендовать купить все необходимое у праздничного торговца в Громовом Утесе. Заранее спасибо, $N.', },
    {'Принесите 20 порций засахаренного батата Вилльяму Маллинсу к праздничным столам над Подгородом.', },
  },
  [14059] = {
    'У нас опять кончился соус?',
    {'Не понимаю, куда девается весь клюквенный соус – можно подумать, его поганищам скармливают, стоит мне только отвернуться. Поможешь мне приготовить еще? Если ты умеешь готовить, можешь купить сочную мулгорскую клюкву у праздничного торговца, который стоит возле Оргриммара.|n|nА если тебе лень возиться с ягодами – просто попроси кого-нибудь приготовить соус.', },
    {'Принесите 20 порций клюквенного соуса Роберте Картер, которая стоит возле праздничных столов во внутреннем дворе Подгорода.', },
  },
  [14060] = {
    'Проще пареной тыквы',
    {'Докин и Лаха трудятся не покладая рук, чтобы все смогли отведать разнообразные угощенья в честь Пиршества странников, и научились готовить традиционные блюда из тех продуктов, что принес нам последний урожай. Я же стараюсь, чтобы гости ни в чем не испытывали недостатка, но одно из наших любимых блюд – тыквенный пирог – уже практически закончилось.|n|nТы сможешь принести еще? Если возьмешься лично его приготовить, купи несколько спелых тирисфальских тыкв у торговца Пиршества странников возле Подгорода.', },
    {'Принесите 20 кусков тыквенного пирога Мархаре Голдвит к праздничным столам возле Громового Утеса.', },
  },
  [14061] = {
    'Слишком мало индеек',
    {'С самого начала праздника я не отхожу от плиты, но угощений надо гораздо больше, чем я могу приготовить одна. Может быть, мне удастся уговорить тебя помочь?|n|nХорошую дикую индейку достать тут очень сложно – разве что ты сумеешь принесешь мне несколько порций. Если решишь лично их приготовить, то могу посоветовать охотиться на птиц в Тирисфальских лесах. Все остальные ингредиенты можно купить у любого торговца Пиршества странников.', },
    {'Принесите 20 запеченных индеек Ондани Большой Мельнице к вратам Оргриммара.', },
  },
  [14062] = {
    'Не забыть про запеканку!',
    {'Ох, как нелегко следить за тем, чтобы праздничные столы не пустовали! Одной рукой помешиваю клюквенный соус, другой готовлю засахаренный батат, а еще надо следить за тем, чтобы пироги не подгорели!|n|nИ почему у меня такое чувство, что я что-то упустила из виду? Точно, я забыла про запеканку! Ай, беда... что же делать? Я уже не успею приготовить все, что собиралась! Послушай, может быть, ты мне поможешь? Это несложно – просто купи несколько тарелок готовой запеканки или приготовь ее $Gсам:сама; – все ингредиенты можно купить прямо здесь.', },
    {'Принесите 20 порций пряной хлебной запеканки Ондани Большой Мельнице к вратам Оргриммара.', },
  },
  [14063] = {
    'Мятеж!',
    {'А теперь переходим к моей любимой части мятежа: убийства! Пиратам неважно, кто пойдет в расход, важно, кто контролирует корабли. У восточной части этого острова стоит на якоре корабль "Кинжал девы", бывший флагманский корабль капитана Шпроты. Он оставил там Алисию Катберт, это одна из его самых надежных офицеров. Устраним ее – и корабль наш, а вместе с ним и море.|n|nМои люди будут в лодках. Заберись на "Кинжал девы" и протруби там в этот рог – это будет сигнал для нас, что можно начинать. Давай!', },
    {'Используйте пиратский сигнальный рог, чтобы призвать Тони Два Клыка и его команду на "Кинжал Девы". Помогите ему справиться с Алисией Катберт.', },
  },
  [14064] = {
    'Богатый пир',
    {'Если ты еще не $Gпробовал:пробовала; блюд с пиршественного стола – считай, Пиршество странников прошло мимо тебя!|n|nПожалуйста, присаживайся, отведай наших угощений. Не стесняйся пересаживаться поближе – или просто попроси соседей передать тебе любое блюдо.|n|nКогда насытишься вдоволь, почувствуешь, как на тебя снизойдет дух пиршества.', },
    {'Съешьте по 5 порций каждого из праздничных блюд с пиршественного стола, пока не ощутите дух пиршества.', },
  },
  [14065] = {
    'Богатый пир',
    {'Если ты еще не $Gпробовал:пробовала; блюд с пиршественного стола – считай, Пиршество странников прошло мимо тебя!|n|nПожалуйста, присаживайся, отведай наших угощений. Не стесняйся пересаживаться поближе – или просто попроси соседей передать тебе любое блюдо.|n|nКогда насытишься вдоволь, почувствуешь, как на тебя снизойдет дух пиршества.', },
    {'Съешьте по 5 порций каждого из праздничных блюд с пиршественного стола, пока не ощутите дух пиршества.', },
  },
  [14066] = {
    'Осмотр места преступления',
    {'Недавно был похищен груз серебра. Он предназначался в уплату стражам Перекрестка, и его необходимо вернуть.|n|nЯ собираю информацию среди населения здесь, а для тебя у меня есть другое задание – обыщи место преступления. Отправляйся на запад, там ты найдешь разбитую повозку из каравана. Она находится к северу от дороги, что ведет отсюда в Перекресток. Выясни, кто взял наши деньги и верни их!', },
    {'Найдите разбитую повозку каравана возле дороги между Кабестаном и Перекрестком и поищите вокруг улики.', },
  },
  [14067] = {
    'Похищенное серебро',
    {'Совершенно ясно, что похитившие серебро Орды ящеры действовали без сообщников!|n|nПора хорошенько проучить их.', },
    {'Убейте 8 яркочешуйчатых опустошителей, 4 яркочешуйчатых смертехвата и найдите украденное серебро.', },
  },
  [14068] = {
    'Охота на яфферов',
    {'Уфтановка ловуффек для яфферов, может быть, и опафное дело, но я разработал соверфенно новую ловуффку, которая знафительно сниффает рифк.|n|nПолофы ловуффку на землю, и она нафнет издавать виффафие звуки, тофь-в-тофь как яфферы. Таким образом мы заманим яффера в ловуффку, а как только он фтупит туда, ловуффка зафлопнется. Фсе, яффер уфе не так опафен! Фсе офень просто. Я бы и фам фделал это, но недавно перебефал дорогу королю Деруффий Коготь.', },
    {'Используйте "Ловуфку для яфферов" Кала\'мы для поимки 5 маленьких яфферов.', },
  },
  [14069] = {
    'Хороших работников трудно найти',
    {'У меня ничего не вышло! Я делал все что мог, чтобы выполнить план по производству "Каджа-Колы", но ты же знаешь... с этими троллями – просто беда. Сложно найти толковых помощников!|n|nДумаю, понадобится твое личное участие. Полагаю, пары ударов током от батареи твоего гоблинского все-в-одном-чудо-пояса будет достаточно. Главное, приструнить основных зачинщиков мятежа, и тогда остальные тролли быстренько придут в чувство.|n|nПроизводство "Каджа-Колы" должно идти без перебоев, иначе торговый принц с нас шкуру спустит!', },
    {'Усмирите 8 взбунтовавшихся троллей.', },
  },
  [14070] = {
    'Как вразумить должников',
    {'Все-таки надо бы разобраться с нашими должниками. Никчемные лодыри прячутся в Рабочем квартале. Я знаю, как ты не любишь шастать по трущобам, но, как говорится, кому сейчас легко?|n|n<Хамми листает какие-то бумаги.>|n|nЗдесь у меня все записано. Все имена.|n|nДумаю, стоит начать, скажем так, с "личной беседы". Пара-тройка стратегических избиений – даже без тяжких физических повреждений – и все остальные сразу поймут намек. И должники, и конкуренты.|n|n$N – не из тех гоблинов, с кем можно шутки шутить!', },
    {'Избейте Бруно Негорючего, Френки Скрипетельку, Джека Молотка и Судзи Магика.', },
  },
  [14071] = {
    'Кружим по кварталу',
    {'Я слышала, $N, ты собираешься устроить корпоративный банкет. Всем банкетам банкет! И это правильно. Чем веселее твоя вечеринка, тем вернее твое продвижение по службе. Проверено опытом!|n|nТак что садись в свой хотрод да отправляйся собирать друзей по всему городу.|n|nНу, а когда станешь $Gторговым принцем:торговой принцессой;, обо мне не забудь, лады?', },
    {'Прокатитесь на хотроде и соберите своих друзей: Туза, Гоббера и Иззи.', },
  },
  [14072] = {
    'Против Верога',
    {'Регтар Врата Смерти отправил меня сюда с заданием наблюдать за деятельностью кентавров, но я никак не могу обнаружить их главаря. Я узнала, что его зовут Верог Дервиш, но вот где он скрывается, я никак не могу выяснить.|n|nПоможешь мне кое-что разыскать? Я понимаю, что говорить об "оперативной информации кентавров" бессмысленно, но все же в их лагерях часто бывают разбросаны разнообразные важные сообщения. Обыщи все палатки кентавров в районе Застывшего Оазиса и принеси все, что сможешь там найти.', },
    {'Найдите 4 документа оперативной информации кентавров в Застывшем Оазисе.', },
  },
  [14073] = {
    'Врата Смерти получает подкрепление',
    {'$N! Тебя все больше и больше уважают в Орде. Я видел твое имя в докладах, что поступили из Застывшего Оазиса и Забытых Прудов, и везде говорится, что ты – настоящий бич кентавров. Впечатляет.|n|nРетгар Врата Смерти отвечает за наши операции, связанные с кентаврами – здесь и по всем Северным Степям. $GТакому:Такой; $Gотважному:отважной:c; |3-2($C), как ты, найдется место в рядах его армии. Отправляйся к нему с докладом. Следуй по дороге на запад и найдешь его заставу. Выполняй все его приказы.', },
    {'Отправляйтесь с докладом к Регтару Вратам Смерти на его заставу к западу от Перекрестка, что в Северных Степях.', },
  },
  [14074] = {
    'Лапами кверху',
    {'Серебряный Авангард отправил сюда корабль, перевозивший мясо долгоногов и прочие припасы для Ристалища, но он так и не добрался до пункта назначения. Наши разведчики доложили, что на него напали квалдиры, безжалостные пираты, которые бороздят эти моря.|n|nОни убили всю команду и перетащили груз на остров, который теперь называется Лагерь Хротгара. Посмотри на север – и увидишь его среди туманов. Может быть, ты поможешь нам вернуть украденные припасы? Если мясо долгоногов не прибудет вовремя, у нас может закончиться провизия.', },
    {'Верните 10 украденных окорочков долгонога Нараси Снежной Заре из Павильона Серебряного союза на Ристалище Серебряного турнира.', },
  },
  [14075] = {
    'Беспорядки в шахтах',
    {'В Каджа\'митовой шахте опять беспорядки. Вернулись роющие черви, и они – в прямом смысле слова – пожирают всю прибыль Торгового дома Каджаро!|n|nДобыча каджа\'мита практически остановлена, а это, как ты понимаешь, отрицательно сказывается на производстве "Каджа-Колы"!|n|nМы пригласили истребителя червей, но он, шельмец, взял деньги вперед и сбежал.|n|nМожет быть, ты $Gсам:сама; очистишь три шахты? Я бы пошел вместе с тобой, да вот пока не прошел обучение на семинаре по боевому искусству.', },
    {'Убейте 6 роющих червей.', },
  },
  [14076] = {
    'Завтрак Чемпионов',
    {'Теперь, когда постройка Колизея закончена, Серебряный Авангард дал нам новое поручение – позаботиться о животных, с которыми предстоит сражаться чемпионам.|n|nУ этих гигантских йормунгаров странные вкусовые предпочтения – похоже, они питаются яйцами себе подобных. Самыми питательными считаются яйца глубинных йормунгаров.|n|nВот, отнеси этот барабан к Подножию в Грозовой Гряде и ударь в него рядом со снежными курганами. Звук пробудит глубинных йормунгаров, и ты сможешь одолеть их, чтобы завладеть яйцами.', },
    {'Найдите 4 яйца йормунгаров и принесите их Савинии Певице Преданий на ристалище Серебряного турнира.', },
  },
  [14077] = {
    'Милосердие Света',
    {'Последняя проповедь Исповедницы Пейлтресс заставила меня задуматься о том, что нам недостаточно просто сражаться плечом к плечу с рыцарями Авангарда – мы должны помогать им исполнить свой долг.|n|nУ северного побережья находится Лагерь Хротгара – остров, который захватили морские пираты – квалдиры, убив всех обитавших на нем клыкарров. Возьми эту книгу и прочти отходную молитву рядом с телами павших жителей. Пусть их несчастные души обретут покой вдали от зловещих туманов острова.', },
    {'Воспользуйтесь Молитвенником исповедницы для проведения последнего обряда над телами 8 убитых туаликов, после чего вернитесь к Нараси Снежной Заре в шатер Альянса на Ристалище Серебряного турнира.', },
  },
  [14078] = {
    'Тотальная эвакуация',
    {'А ты что здесь делаешь? Разве ты не $Gслышал:слышала; про эвакуацию?|n|nНемедленно разыщи лейтенанта Вальдена, и он выдаст тебе дальнейшие инструкции.', },
    {'Найдите лейтенанта Вальдена в северо-западном углу Торговой площади.', },
  },
  [14079] = {
    'Уроки верховой езды в Элвиннском лесу',
    {'Это рекламное сообщение об уроках верховой езды и продаже скакунов пришло от Рандала Охотника.|n|nЕго можно найти на лесопилке Восточной долины, в Элвиннском лесу, вдоль дороги, ведущей из Штормграда.', },
    {'Верните это рекламное сообщение Рандалу Охотнику на лесопилку Восточной долины в Элвиннском лесу.', },
  },
  [14080] = {
    'Остановить нападение',
    {'Квалдиры, морские врайкулы, что захватили наши грузы, завладели островом клыкарров, который находится на севере пролива, убили его обитателей и переименовали его в Лагерь Хротгара. Если позволить им закрепиться на этой позиции, они изберут нас следующей целью.|n|nАвангард бросил все силы на борьбу с Плетью, поэтому защитить Ристалище можем только мы. Лети на север от турнирной площадки, пока не увидишь этот остров, и убей квалдиров прежде, чем они возьмутся за нас.', },
    {'Нараси Снежная Заря из Павильона Серебряного союза на Ристалище Серебряного турнира просит вас убить 10 квалдиров.', },
  },
  [14081] = {
    'Уроки верховой езды в Лесах Вечной Песни',
    {'Это рекламное сообщение об уроках верховой езды и продаже скакунов пришло от Пераскамина.|n|nЕго можно найти в Стойлах Турона, к юго-востоку от Врат Пастыря, ведущих из Луносвета.', },
    {'Верните это рекламное сообщение Пераскамину в стойла Турона в Луносвете.', },
  },
  [14082] = {
    'Уроки верховой езды в Экзодаре',
    {'Это рекламное сообщение об уроках верховой езды и продаже скакунов пришло от Аалун.|n|nЕе можно найти в Экзодаре на Острове Лазурной Дымки', },
    {'Верните это рекламное сообщение Аалун, которая находится неподалеку от Экзодара на острове Лазурной Дымки.', },
  },
  [14083] = {
    'Уроки верховой езды в Дун Мороге',
    {'Это рекламное сообщение об уроках верховой езды и продаже скакунов пришло от Ультама Громовой Рог.|n|nЕго можно найти на Ферме Янтарленов, которая расположена вдоль дороги, ведущей на восток от Стальгорна.', },
    {'Верните это рекламное сообщение Ультаму Громовому Рогу на ферму Янтарленов в Дун Мороге.', },
  },
  [14084] = {
    'Уроки верховой езды в Дун Мороге',
    {'Это рекламное сообщение об уроках верховой езды и продаже скакунов пришло от Бинджи Перосвиста.|n|nЕго можно найти в Поселке Сталежара к северо-востоку от Караноса в Дун Мороге.', },
    {'Верните это рекламное сообщение Бинджи Перосвисту в поселок Сталежара в Дун Мороге.', },
  },
  [14085] = {
    'Уроки верховой езды в Дарнасе',
    {'Это рекламное сообщение об уроках верховой езды и продаже скакунов пришло от Джартсама.|n|nЕго можно найти в Анклаве Кенария, в Дарнасе.', },
    {'Верните это рекламное сообщение Джартсаму в анклав Кенария в Дарнасе.', },
  },
  [14086] = {
    'Уроки верховой езды в Оргриммаре',
    {'Это рекламное сообщение об уроках верховой езды и продаже скакунов пришло от Кильдара.|n|nЕго можно найти в Аллее Чести Оргриммара.', },
    {'Верните это рекламное сообщение Кильдару в Аллею Чести в Оргриммаре.', },
  },
  [14087] = {
    'Уроки верховой езды в Мулгоре',
    {'Это рекламное сообщение об уроках верховой езды и продаже скакунов пришло от Кара Певца Бури.|n|nЕго можно найти в Мулгоре, в Деревне Кровавого Копыта.', },
    {'Верните это рекламное сообщение Кару Певцу Бури в деревню Кровавого Копыта в Мулгоре.', },
  },
  [14088] = {
    'Уроки верховой езды в Дуротаре',
    {'Это рекламное сообщение об уроках верховой езды и продаже скакунов пришло от Ксар\'Ти.|n|nЕго можно найти в Деревне Сен\'джин, что в южном Дуротаре.', },
    {'Верните это рекламное сообщение Ксар\'Ти в деревню Сен\'Джин в Дуротаре.', },
  },
  [14089] = {
    'Уроки верховой езды в Тирисфальскх лесах',
    {'Это рекламное сообщение об уроках верховой езды и продаже скакунов пришло от Вельмы Варнам.|n|nЕе можно найти в Брилле, в Тирисфальских лесах.', },
    {'Верните это рекламное сообщение Вельме Варнам в Брилл в Тирисфальских лесах.', },
  },
  [14090] = {
    'Гормоку нужны снобольды',
    {'Уже двое моих людей погибли, пытаясь угомонить магнатавра по кличке Гормок, а это животное все еще буйствует – воет без остановки и требует своего любимого снобольда.|n|nЯ бы его собственными руками придушил, но Серебряный Авангард собирается выпустить его на бой в Колизее. Похоже, придется попытаться разыскать его любимую игрушку. Возьми эту сеть и отправляйся к Побоищу Гарма, что на юго-востоке Грозовой Гряды и к северо-востоку от К-3. Поймай там несколько снобольдов – и молись Свету, чтобы среди них оказался тот самый зверек.', },
    {'Воспользуйтесь утяжеленной сетью, чтобы поймать 8 последователей с Холмов Снежной Слепоты, и приведите их Савинии Певице Преданий в Павильон Серебряного союза на Ристалище Серебряного турнира.', },
  },
  [14091] = {
    'Дурной знак',
    {'Похоже, лейтенант скончался от нанесенных ран, и эту новость надо немедленно сообщить принцу.|n|nВы слышите шум драки, доносящийся со стороны рынка.', },
    {'Вернитесь к принцу Лиаму Седогриву на Торговую площадь.', },
  },
  [14092] = {
    'Завтрак Чемпионов',
    {'Теперь, когда строительство Колизея завершено, Серебряный Авангард поручил нам заботу о зверях, с которыми придется сразиться чемпионам.|n|nЭтим гигантским йормунгарам полагается странная диета – они питаются яйцами себе подобных. Самые сытные откладывают глубинные йормунгары.|n|nВот, отнеси этот барабан к Подножию, что в центре Грозовой Гряды, и ударь в них возле снежных курганов. Звук пробудит глубинных йормунгаров, и ты сможешь убить их, собрать яйца и принести на Ристалище.', },
    {'Принесите 4 яйца йормунгаров Тайлосу Вестнику Зари в шатер Орды на Ристалище Серебряного турнира.', },
  },
  [14093] = {
    'И разверзся ад',
    {'Воргены! Отец предупреждал меня, что создания верховного мага Аругала обезумели.|n|nНо откуда они взялись?|n|nВпрочем, наверное, это не имеет значения. Лучше помоги нам справиться с ними. Покажем им, из какого теста сделаны настоящие гилнеаcцы!', },
    {'Принц Лиам Седогрив приказал вам убить 6 озлобленных воргенов.', },
  },
  [14094] = {
    'Спасение припасов',
    {'Послушай, $N, мы не можем допустить, чтобы все припасы были уничтожены.|n|nСейчас, когда Гилнеас отрезан от остального мира, мы не продержимся и зиму, если потеряем еще больше продовольствия.|n|nПожалуйста, помоги мне спасти хоть что-то!', },
    {'Спасите 4 ящика с припасами.', },
  },
  [14095] = {
    'Опознание останков',
    {'Неповрежденный зуб кракена – это действительно редкая находка. Наверняка она заинтересует Крестоносца Серебристый Рассвет из Серебряного павильона.', },
    {'Отнесите зуб кракена Крестоносцу Серебристый Рассвет в Серебряный павильон.', },
  },
  [14096] = {
    'На этот раз ты нарвался, Кул',
    {'Рыцарь Кул опять угодил в беду, но на этот раз увлек за собой других. Как только он увидел, что приспешники культа Проклятых разбили лагерь на Заставе Вестника Смерти, что на западе от Ристалища, то собрал группу претендентов и повел их на бой с захватчиками.|n|nРазумеется, не имея должного подкрепления, они были разбиты и захвачены в плен. Я не сомневаюсь, что злодеи принесут их в жертву, дабы подпитать этой силой свою зловещую магию. Ключи от черных клеток, в которых держат пленников, могут храниться у любого из служителей культа. Прошу тебя, найди ключи, спаси Кула и несчастных претендентов от ужасной участи!', },
    {'Спасите Кула Безрассудного и 4 пленных претендентов с Заставы Вестника Смерти и вернитесь к Нараси Снежной Заре в шатер Альянса на Ристалище Серебряного турнира.', },
  },
  [14097] = {
    'Уберите этого торговца!',
    nil,
    nil,
  },
  [14098] = {
    'Эвакуация Торговой площади',
    {'Теперь здесь стало небезопасно – даже родные стены не могут защитить от беды.|n|nМы пытаемся не пустить воргенов в дома, но их слишком много, и за всеми невозможно уследить.|n|nПомоги нам эвакуировать жителей в тюремный квартал – армия моего отца сможет лучше их защитить.', },
    {'Помогите эвакуировать людей из 3 домов.', },
  },
  [14099] = {
    'Королевский приказ',
    {'Теперь тебе тоже пора уходить, $N. Ступай в Военный квартал вместе с остальными жителями.|n|nКак только пересечешь мост, разыщи Гвен Армстед и узнай, все ли прошло благополучно.|n|nА я останусь здесь и буду прикрывать отход вместе со стражниками.|n|nИди же! Это приказ.', },
    {'Поговорите с Гвен Армстед в северо-восточной части Военного квартала.', },
  },
  [14100] = {
    'Реликвия Служителей Земли',
    {'Ты уже многому $Gнаучился:научилась;, $N. Теперь, когда тебе подвластны все четыре основных элемента, пора узнать, как сохрянять между ними равновесие. Тебе пригодится это знание – потренировавшись, ты сможешь носить с собой только одну реликвию вместо четырех тотемов.|n|nПоговори с Готуром Четыре Ветра на Аллее Мудрости в Оргриммаре и обрети власть над четырьмя стихиями.', },
    {'Принесите четыре тотема Готуру Четыре Ветра в Оргриммар.', },
  },
  [14101] = {
    'Дроттинн Хротгар',
    {'Квалдиры, морские врайкулы, которые грабят корабли и прибрежные поселения, захватили остров клыкарров, что находится на севере пролива. Их предводитель – бывалый пират Дроттинн Хротгар, который давно уже стремится установить контроль над этими морями.|n|nПока он правит шайкой бандитов, наши корабли и транспортные суда находятся в постоянной опасности. А если мы окажемся отрезанными от остального мира, нам останется только сдаться на милость Королю-личу.|n|nВозьми этот боевой рог, который мы отняли у пленного квалдира, и отнеси его к кругу клыкаррских статуй на северо-востоке Лагеря Хротгара. С его помощью ты сможешь бросить вызов предводителю врайкулов.', },
    {'Верховный крестоносец Аделард из Серебряного павильона на Ристалище Серебряного турнира просит вас одолеть Дроттинна Хротгара.', },
  },
  [14102] = {
    'Призыватель туманов Йингвар',
    {'Квалдиры вернулись на берега Нордскола – и это может стать для нас проблемой, если мы не обеспечим безопасность наших грузов и подкреплений. Один из их предводителей, Призыватель туманов Йингвар, поселился в пещере на западной стороне Лагеря Хротгара. Оттуда он управляет туманами, чтобы скрыть базы пиратов и подвластных квалдирам морских чудовищ.|n|nВозьми этот амулет и отправляйся на север от Ристалища, к Лагерю Хротгара. Найди пещеру призывателя туманов и воспользуйся амулетом, чтобы увидеть его.', },
    {'Верховный крестоносец Аделард из Серебряного павильона на Ристалище Серебряного турнира просит вас одолеть Призывателя туманов Йингвара.', },
  },
  [14103] = {
    'Титаниевый порошок',
    nil,
    nil,
  },
  [14104] = {
    'Орнолф Меченый',
    {'Орнолф Меченый – безжалостный пират, о котором со страхом отзываются даже его собратья-квалдиры. Он и его команда "Ярости Бора" грабят суда и убивают наших людей.|n|nОрнолф и его бандиты были среди тех, кто принял участие в расправе над обитателями острова клыкарров, который теперь носит название Лагерь Хротгара. Корабль этого пирата стоит на якоре в гавани на востоке этого острова. Возьми этот захваченный флаг и установи его на корабле. Не сомневаюсь, это приведет Орнолфа в ярость, и он попытается лично расправиться с тобой. Удачи!', },
    {'Верховный крестоносец Аделард из Серебряного павильона на Ристалище Серебряного турнира просит вас одолеть Орнолфа Меченого.', },
  },
  [14105] = {
    'Вестник смерти Карос',
    {'Культ Проклятых удвоил свои усилия, стремясь к нашему уничтожению. Они обнаглели настолько, что собрали свои силы на западе от Ристалища, на Заставе Вестника Смерти.|n|nВозглавляет их безжалостный Вестник Смерти Карос, и скоро его люди нападут на нас из-за возведенных укрытий.|n|nНаши солдаты и искатели славы готовятся отразить атаку, но только чемпионы могут обезглавить войско противника. Найди Вестника Смерти, $N, и убей его.', },
    {'Верховный крестоносец Аделард из Серебряного павильона на Ристалище Серебряного турнира просит вас одолеть Вестника Смерти Кароса.', },
  },
  [14107] = {
    'Судьба Павших',
    {'Серебряный Авангард – не единственная сила, противостоящая Королю-личу в Ледяной Короне. Но наш враг хочет обратить против нас души павших союзников...|n|nИх духи блуждают по Долине павших героев, на юго-западе от ристалища и к западу от Алдуртара. Земля там буквально усыпана кристаллами душ, которые Плеть использует для подчинения призраков. Собери эти кристаллы и освяти с помощью Благословенной светом реликвии, чтобы даровать покой неприкаянным духам. Они это заслужили.', },
    {'Крестоносец Серебристый Рассвет из Серебряного павильона просит вас даровать покой 6 духам павших героев.', },
  },
  [14108] = {
    'Изгнать Кракена!',
    {'Похитители Солнца и Серебряный союз отправили корабли на север, чтобы вступить в схватку с врайкулами, захватившими Лагерь Хротгара, но по пути были перехвачены пиратским флагманом. Хуже того, проклятые квалдиры нашли способ вызвать из глубин Северного моря свирепое чудовище – кракена. Если мы хотим спасти хоть кого-то из команды кораблей, мы должны изгнать кракена и прервать ритуал квалдиров.|n|nКрестоносец, возьми эти копья и пусть серебряный гиппогриф отнесет тебя в самую гущу битвы.', },
    {'Крестоносец Серебристый Рассвет из Серебряного павильона просит вас оседлать серебряного гиппогрифа, бросить 6 пылающих копий в кракена Северного моря и поразить 3 врайкулов-пробудителей глубин.|n|nСеребряного гиппогрифа можно найти возле палатки Серебряного Авангарда на Ристалище Серебряного Турнира.', },
  },
  [14109] = {
    'Новый наряд',
    {'Новый наряд? Да ты что?! Твой банкет – настоящее событие! Все сливки общества этого острова соберутся! Прямо-таки взбитые сливки!|n|nНу, что же… удачных покупок! Кстати, лучшие в городе магазины – в Переулке Дельцов.', },
    {'Купите блестящие украшения у Гэппи Серебряного Зуба, новый стильный костюмчик у Забо и модные темные очки у Миссы Фарцовщицы в переулке Дельцов.', },
  },
  [14110] = {
    'Новый наряд',
    {'Новый наряд? Да ты что?! Твой банкет – настоящее событие! Все сливки общества этого острова соберутся! Прямо-таки взбитые сливки!|n|nНу, что же… удачных покупок! Кстати, лучшие в городе магазины – в Переулке Дельцов.', },
    {'Купите блестящие украшения у Гэппи Серебряного Зуба, новый стильный костюмчик у Забо и модные темные очки у Миссы Фарцовщицы в переулке Дельцов.', },
  },
  [14111] = {
    'Реликвия Служителей Земли',
    {'Ты уже многому $Gнаучился:научилась;, $N. Теперь, когда тебе подвластны все четыре основных элемента, пора узнать, как сохрянять между ними равновесие. Тебе пригодится это знание – потренировавшись, ты сможешь носить с собой только одну реликвию вместо четырех тотемов.|n|nПоговори с Предсказателем Эанну в Стальгорне возле Великой Кузни – он поможет тебе отточить мастерство в повелевании стихиями.', },
    {'Принесите четыре тотема Предсказателю Эанну в Стальгорн.', },
  },
  [14112] = {
    'Кстати, чем питаются йети?',
    {'Рыцари поймали огромного йети по кличке Ледяной Рев, который будет участвовать в гладиаторских боях, и поручили нам тренировать и кормить его.|n|nЖаль, им не понравилась моя идея отдать ему на растерзание парочку Похитителей Солнца. Эта тварь предпочитает мясо акул, так что тебе придется отправиться за ним на "Серебряный Клинок", который стоит на якоре к северу пролива. Возьми свежую наживку из бочек на борту и брось ее в воду – она привлечет внимание акул.', },
    {'Савиния Певица Преданий из Павильона Серебряного союза на Ристалище Серебряного турнира просит вас принести ей 3 куска мяса акулы Северного моря.', },
  },
  [14113] = {
    'Банкет',
    {'Ничего себе! Да тут собрался весь цвет кезанского общества! Кому какое дело до дракона?|n|nМы решили устроить банкет у бассейна. Гости, похоже, довольны. И все ждут тебя!|n|nТак что давай наряжайся, иди к бассейну и общайся с гостями. Я тоже скоро приду... но сначала мне надо кое-что сделать.', },
    {'Наденьте свой потрясный прикид для вечеринки (темные очки, новый стильный костюмчик и блестящие украшения) и отправляйтесь развлекать 10 кутил из Кезана, собравшихся у бассейна в штаб-квартире ТКК.', },
  },
  [14115] = {
    'Пираты-наемники',
    {'Ой, мама! Пираты!|n|n$N, к тебе на банкет заявились пираты Южных морей!|n|nНадо немедленно что-то предпринять! Иначе все твои планы стать $Gследующим торговым принцем:следующей торговой принцессой; накроются медным тазом!', },
    {'Убейте 12 пиратов-наемников, чтобы спасти свою карьеру.', },
  },
  [14116] = {
    'Незваный гость',
    {'Пока ты там $Gразбирался:разбиралась; с пиратами, я видела торгового принца. Он потихоньку поднялся по лестнице. Думал, наверное, его никто не заметит. Он сейчас на балконе на верхней площадке.|n|n$N, я думаю, это он подослал пиратов.|n|n<Хамми морщится.>|n|nТебе надо подняться наверх. И как можно скорее! Нельзя заставлять его ждать.', },
    {'Поговорите с торговым принцем Галливиксом на верхнем этаже штаб-квартиры ТКК на Кезане.', },
  },
  [14117] = {
    'Глаза Ясеневого леса',
    {'Кругом враги, |3-6($C), даже тут, у самых наших дверей. Ночные эльфы прислали подкрепление на заставу Талрендис, пытаясь оcтановить наше вторжение в Ясеневый лес. В то время, как мы разговариваем, их разведчики прочесывают близлежащие холмы, докладывая о каждом движении у врат.|n|nНадо избавиться от этих глаз Ясеневого леса.|n|nИди. Они бродят возле врат, больше всего их в восточной части. Убей разведчиков, которые следят за нами!', },
    {'Убейте 8 разведчиков с заставы Талрендис.', },
  },
  [14118] = {
    'Оленина для солдат',
    {'Из-за того, что мы истратили все ресурсы этих земель на наши боевые машины, местным животным негде жить. Они в любом случае умрут, поэтому пусть хотя бы их мясо не пропадет даром. Желудки воинов Оргриммара совершенно пусты.|n|nПоохоться на ослабших мохоногих маралов в округе и запасись их мясом для нашей пехоты.', },
    {'Соберите 15 больших кусков оленины, убив ослабших мохоногих маралов.', },
  },
  [14120] = {
    'Миллиард деревянных?!',
    {'Ты весьма $Gчестолюбивый юнец:честолюбивая девушка;, $N. Может быть, даже чересчур, а это, знаешь ли, не всегда хорошо. Хотя в твоем возрасте я был точно таким же, так что ты – это я, только моложе.|n|nУ меня к тебе предложение. Ты, должно быть, $Gзаметил:заметила;, что из-за твоего дракона началось извержение Каджаро. Все, кто останется на Кезане, умрут! Но если ты принесешь мне миллиард деревянных до того, как моя яхта отчалит от острова, я позабочусь о том, чтобы ты $Gоказался:оказалась; в числе немногих спасшихся счастливцев.|n|nВ общем так – хочешь жить, думай, где достать бабки!', },
    {'Поговорите с Хамми Кофельнагель в штаб-квартире ТКК на Кезане.', },
  },
  [14121] = {
    'Грабь награбленное',
    {'Мы все умрем!!!|n|n<Вы даете Мегз пощечину, чтобы прекратить истерику.>|n|nПрошу прощения, $Gгосподин:госпожа; $N. Этого больше не повторится. Так... надо срочно придумать, где взять столько денег.|n|nГоворят, торговый принц нанял грабителей, и те уже бесчинствуют на улицах.|n|nСадись в свой хотрод и поезжай в город. Дави их без жалости, этих грабителей. А заодно собирай все добро, что они успели награбить. По-моему, это будет лишь справедливо.', },
    {'Садитесь в хотрод, задавите 12 наемных грабителей и заберите у каждого украденные им вещи.', },
  },
  [14122] = {
    'Ограбление банка',
    {'Все твои счета заморожены, а Первый банк Кезана закрылся!|n|nТебе нужна куча денег. А где их взять? Думаю, надо просто забрать свои деньги из банка! В твоем гоблинском все-в-одном-чудо-поясе столько всяких полезных приспособлений. Наверняка там найдется какой-нибудь инструмент, чтобы вскрыть дверь в хранилище.|n|nНадеюсь, ты $Gслушал:слушала; мои советы и $Gотложил:отложила; энную сумму на черный день. Потому что сегодня – самый что ни на есть черный день. Хотя и подсвеченный раскаленной магмой!!!', },
    {'Взломайте хранилище Первого банка Кезана и заберите свои личные сбережения.', },
  },
  [14123] = {
    'Антикварные ценности',
    {'Есть всего один способ достать миллиард деревянных: украсть у богатых!|n|nЭтот мерзавец торговый принц награбил целые горы всевозможного антиквариата и дорогущих предметов искусства. Давно пора отобрать у него эти ценности и отдать их бедным... например, нам!|n|nСейчас мы тебя замаскируем под одного из прихлебателей Галливикса. А потом ты спокойненько зайдешь на виллу торгового принца и "приберешь" антикварные ценности.|n|nТолько старайся не приближаться к его свиньям. Они чуют чужих. Их не обманешь никакой маскировкой!', },
    {'Раздобудьте "Ястреба Малди", "Гоблину Лизу" и "Платиновую бомбу".', },
  },
  [14124] = {
    'Каджа\'митовые месторождения',
    {'Нам нужна куча денег, чтобы расплатиться с торговым принцем и убраться с Кезана подобру-поздорову! И эти деньги – буквально у нас под ногами, в Каджа\'митовой шахте. Подходи и бери!|n|nПоследние из известных нам каджа\'митовых месторождений остались как раз на Кезане. Они здесь повсюду, куда ни плюнь. Собственно, благодаря им мы и стали гениальнейшими механиками и алхимиками. Если эти месторождения не стоят миллиарда деревянных, тогда я даже не знаю, что может стоить...|n|nВозьми у меня разрывные бомбы, подорви ближайшее месторождение и собери разлетевшиеся куски.|n|nТолько будь $Gосторожен:осторожна;. Берегись бунтующих троллей!', },
    {'Соберите 12 кусков каджа\'мита.', },
  },
  [14125] = {
    'Страховочный план',
    {'У нас уже целая куча деревянных, но этого все равно мало. Но на этот случай у меня есть план! Здание штаба застраховано, и если вдруг что случится, мы получим страховку.|n|nПосле банкета остались фейерверки, и я разложила их по всему зданию. Тебе только и нужно, что зайти в штаб и устроить маленькую диверсию.|n|nПредлагаю следующую огнеопасную комбинацию: неисправный генератор, прохудившаяся печка и легковоспламеняющаяся кровать. А потом просто выходишь наружу и посылаешь в здание газобота.|n|nПлан идеальный, а главное – надежный!', },
    {'Устройте перегрузку барахлящего генератора, включите прохудившуюся печку, уроните сигару на легковоспламеняющуюся кровать и запустите газобота, чтобы поджечь штаб-квартиру ТКК!', },
  },
  [14126] = {
    'Сбережения',
    {'Ну вот, мы набрали нужную сумму. Осталось только добраться до яхты торгового принца. Она уже готовится выйти из порта!|n|nНам надо поторопиться. Давай, забирайся в машину. Я – за рулем!', },
    {'Отдайте ваши сбережения торговому принцу Галливиксу на борту его яхты на Кезане.', },
  },
  [14127] = {
    'Возвращение высокорожденных?',
    {'Восковая печать на этих приказах недавно была сломана. Аккуратные записи карандашом, которые делали ночные эльфы, прочесть невозможно, но на небольшой от руки нарисованной карте изображены близлежащие руины. Ниже карты видны руны, написанные металлическими мерцающими чернилами.|n|nНет никаких сомнений, что Аг\'тору будет интересно на это взглянуть.', },
    {'Доставьте приказы разведчика Аг\'тору Кровопалу к задним вратам Оргриммара.', },
  },
  [14128] = {
    'Возвращение высокорожденных?',
    {'Наши союзники эльфы крови осматривали изображенные на этой карте руины, и, вероятно, смогут понять эти таинственные записи. Найди среди них ту, кого зовут Малинея Опустошительница Небес. Она проводит исследования на оргриммарской пересадочной станции ракетной дороги к северу отсюда – это часть новой транспортной системы гоблинов, которая, извиваясь, проходит через эти земли. Давай, поторапливайся!', },
    {'Доставьте приказы разведчика Малинее Опустошительнице Небес на оргриммарскую пересадочную станцию ракетной дороги.', },
  },
  [14129] = {
    'Сбежавшие крошшеры!',
    {'Я хотел продемонстрировать нашим новым союзникам из Орды легендарную эффективность гоблинской техники, но сейчас, оглядываясь назад, мне кажется, что автоматизация крошшеров была не самой лучшей из моих идей. Сейчас эти крошшеры – можно сказать, настоящие машины-убийцы – сеют в округе смерть. Не пойми меня превратно – такие штуковины вполне могут пригодиться где-то еще, но сейчас мне прямо-таки $Gнеобходим храбрый:необходима храбрая:c; |3-6($C), $Gкоторый:которая:c; поможет мне совладать с этими махинами.|n|nЭто не так уж и сложно. В первую очередь тебе понадобится подчинить себе один из этих крошшеров. Возьмешь управление на себя, и я передам тебе по радио новые инструкции.', },
    {'Атакуйте один из сбежавших крошшеров возле задних врат Оргриммара и заберитесь внутрь, когда он будет значительно поврежден.', },
  },
  [14130] = {
    'Друзья бывают разных цветов',
    {'Меня и моих братьев преследуют.|n|nНедавно убили нашего вожака, а сейчас черные драконы ищут тех из нас, кто остался в живых. Я здесь, чтобы найти Азурегоса и переправить его в безопасное место, если только он даст возможность это сделать.|n|nУ Азурегоса мало друзей и выбирает он их немного... странным образом. Единственный, кого я здесь знаю, это мурлок по имени Эргл. Ты сможешь найти его на берегу к северо-востоку отсюда.|n|nСделай все возможное, чтобы найти Азурегоса и прислать его ко мне.|n|nПожалуйста, торопись.', },
    {'Найдите Эргла в руинах храма Арккоран.', },
  },
  [14131] = {
    'Собери мне чуть-чуть',
    {'Азурегос… Азурегос. Азу? Дракон? Да, мы с ним друзья! Он научил меня говорить. Говорил, что ему нравится мой цвет… можно подумать, он художник, да?|n|nНе помню, куда он пошел. Ммм… у меня что-то с памятью.|n|nЯ засадил весь пляж растениями кауфи. Они любят песок. Это странно.|n|nМожешь собрать их?', },
    {'Соберите 10 бобов кауфи с растений в руинах храма Арккоран.', },
  },
  [14132] = {
    'Это просто невежливо!',
    {'Если бы они попросили, я бы поделился. А они просто стали рвать и крошить мои растения кауфи. Это невежливо! Тебе надо научить их, как себя вести.|n|nПусть макринни замолчат.', },
    {'Убейте 10 макринни в руинах храма Арккоран.', },
  },
  [14133] = {
    'Путь к сердцу мага',
    {'Теперь, когда ты $Gвыполнил:выполнила; поручения Эргла, он расскажет тебе об Азурегосе. Поговори с ним, может быть, узнаешь что-нибудь полезное о возможном местонахождении Азурегоса.', },
    {'Спросите Эргла об Азурегосе.', },
  },
  [14134] = {
    'Древесина для подрядчика',
    {'Теперь, когда ты $Gнаучился:научилась; управлять этой штукой, давай сделаем то, что должен был делать я, – заготовим древесину. Иначе эти орки построят катапульту из МЕНЯ!|n|nВ этой области много спиленных деревьев. Воспользуйся крошшером и собери столько, сколько сможешь.', },
    {'Воспользуйтесь перепрограммированным крошшером, чтобы собрать 6 штабелей азшарской древесины. Если вы потеряете свой крошшер, можно поймать и перепрограммировать другой.', },
  },
  [14135] = {
    'На деревья',
    {'Замри на секундочку, я подключу циркулярную пилу.|n|nСнайперы ночных эльфов с заставы Талрендис прячутся в деревьях и стреляют в моих рабочих. Я хочу, чтобы ты $Gзанялся:занялась; этими снайперами… предварительно занявшись деревьями. Поищи азшарские молодые деревца восточнее главных ворот. Твой крошшер сам поймет, что ему делать. Поруби их!', },
    {'Воспользуйтесь циркулярной пилой крошшера, чтобы спилить азшарские молодые деревца и убейте 9 снайперов с заставы Талрендис, когда они появятся.', },
  },
  [14136] = {
    'Спасательная операция на море',
    {'Квалдиры захватили маленький остров на севере и переименовали его в Лагерь Хротгара. Чтобы разведать ситуацию, мы отправили туда капитана Аэртаса Огненного Ястреба, но его корабль попал в засаду к пиратам неподалеку от Ристалища! К несчастью, квалдиры значительно превосходят по численности его команду. Прошу тебя, отправляйся туда и покажи этим бандитам, что они не на тех напали. |n|n"Огненный Ястреб" находится к северу от Ристалища, на западной части пролива.', },
    {'Гирана Окровавленная из Павильона Похитителей Солнца на Ристалище Серебряного турнира просит вас убить 8 квалдиров-берсерков и 3 квалдиров-гарпунеров, напавших на "Огненный Ястреб".', },
  },
  [14137] = {
    'Изучение классовых навыков',
    nil,
    nil,
  },
  [14138] = {
    'Бизнес – прежде всего',
    {'Что касается беспорядков в Каджа\'митовой шахте... штейгер Промоках уже сбился с ног. Ищет тебя. Он что-то говорил о "взбунтовавшихся вконец обнаглевших троллях".|n|nКаджа\'мит, добываемый нашими троллями, – основной компонент "Каджа-Колы". На этой шипучке мы делаем огромные деньги, и, кстати, благодаря ей ты $Gсам:сама; можешь стать $Gторговым принцем:торговой принцессой;!|n|nНо сначала нам нужно восстановить производство. Иди на восток, найди штейгера. Вручи ему вот это, чтобы у него был стимул к действию.', },
    {'Передайте поощрение Хамми штейгеру Промокаху в штаб-квартире ТКК на Кезане.', },
  },
  [14140] = {
    'Остановить нападение',
    {'Квалдиры, морские врайкулы, что захватили наши грузы, завладели островом клыкарров, который находится на севере пролива, убили его обитателей и переименовали его в Лагерь Хротгара. Если позволить им закрепиться на этой позиции, они изберут нас следующей целью.|n|nАвангард бросил все силы на борьбу с Плетью, поэтому защитить Ристалище можем только мы. Лети на север от турнирной площадки, пока не увидишь этот остров, и убей квалдиров прежде, чем они возьмутся за нас.', },
    {'Гирана Окровавленная с Ристалища Серебряного турнира просит вас убить 10 квалдиров.', },
  },
  [14141] = {
    'Гормоку нужны снобольды',
    {'Уже двое моих людей погибли, пытаясь угомонить магнатавра по кличке Гормок, а это животное все еще буйствует – воет без остановки и требует своего любимого снобольда.|n|nЯ бы его собственными руками придушил, но Серебряный Авангард собирается выпустить его на бой в Колизее. Похоже, придется попытаться разыскать его любимую игрушку. Возьми эту сеть и отправляйся к Побоищу Гарма, что на юго-востоке Грозовой Гряды и к северо-востоку от К-3. Поймай там несколько снобольдов – и молись Свету, чтобы среди них оказался тот самый зверек.', },
    {'Воспользуйтесь утяжеленной сетью, чтобы поймать 8 последователей с Холмов Снежной Слепоты, и приведите их Тайлосу Вестнику Зари в шатер Орды на Ристалище Серебряного турнира.', },
  },
  [14142] = {
    'На этот раз ты нарвался, Кул',
    {'Рыцарь Кул опять угодил в беду, но на этот раз увлек за собой других. Как только он увидел, что члены культа Проклятых разбили лагерь на Заставе Вестника Смерти, к западу от Ристалища, то собрал группу претендентов и повел их на бой с захватчиками.|n|nРазумеется, не имея должного подкрепления, они были разбиты и захвачены в плен. Я не сомневаюсь, что мерзавцы принесут их в жертву, дабы подпитать этой силой свою зловещую магию. Ключи от черных клеток, в которых держат пленников, могут храниться у любого из служителей культа. Прошу тебя – найди ключи, спаси Кула и несчастных претендентов от ужасной участи!', },
    {'Спасите Кула Безрассудного и 4 пленных претендентов с Заставы Вестника Смерти и вернитесь к Гиране Окровавленной на Ристалище Серебряного турнира.', },
  },
  [14143] = {
    'Лапами кверху',
    {'Серебряный Авангард отправил сюда корабль, перевозивший мясо долгоногов и прочие припасы для Ристалища, но он так и не добрался до пункта назначения. Наши разведчики доложили, что на него напали квалдиры, безжалостные пираты, которые бороздят эти моря.|n|nОни убили всю команду и перетащили груз на остров, который теперь называется Лагерь Хротгара. Посмотри на север – и увидишь его среди туманов. Может быть, ты поможешь нам вернуть украденные припасы? Если мясо долгоногов не прибудет вовремя, у нас может закончиться провизия.', },
    {'Верните 10 украденных окорочков долгонога Гиране Окровавленной из Павильона Похитителей Солнца на Ристалище Серебряного турнира.', },
  },
  [14144] = {
    'Милосердие Света',
    {'Последняя проповедь Исповедницы Пейлтресс заставила меня задуматься о том, что нам недостаточно просто сражаться плечом к плечу с рыцарями Авангарда – мы должны помогать им исполнить свой долг.|n|nУ северного побережья находится Лагерь Хротгара – остров, который захватили морские пираты – квалдиры, убив всех обитавших на нем клыкарров. Возьми эту книгу и прочти отходную молитву рядом с телами павших жителей. Пусть их несчастные души обретут покой вдали от зловещих туманов острова.', },
    {'Воспользуйтесь Молитвенником исповедницы для проведения последнего обряда над телами 8 убитых туаликов, после чего вернитесь к Гиране Окровавленной в шатер Орды на Ристалище Серебряного турнира.', },
  },
  [14145] = {
    'Кстати, чем питаются йети?',
    {'Рыцари поймали огромного йети по кличке Ледяной Рев, который будет участвовать в гладиаторских боях, и поручили нам тренировать и кормить его.|n|nЖаль, им не понравилась моя идея отдать ему на растерзание парочку представителей Серебряного союза. Эта тварь предпочитает мясо акул, так что тебе придется отправиться за ним на "Багровый Рассвет", который стоит на якоре к северу пролива. Возьми свежую наживку из бочек на борту и брось ее в воду – она привлечет внимание акул.', },
    {'Тайлос Вестник Зари из Павильона Похитителей Солнца на Ристалище Серебряного турнира просит вас принести ему 3 куска мяса акулы Северного моря.', },
  },
  [14146] = {
    'Защитить врата!',
    {'Боже, что происходит?|n|n<Вопли, крики и шум битвы наполняют радиоэфир.>|n|n$N! Сейчас же возвращайся сюда. Спеши к вратам – на нас напали!|n|nПомоги нам дать отпор захватчикам. Я сейчас заряжу твой гранатомет!', },
    {'Подрядчик Жаднюк просит вас поспешить к задним вратам Оргриммара и убить 20 ночных эльфов-налетчиков.', },
  },
  [14151] = {
    'Багровый рубин',
    {'Багровый рубин обработать непросто – это самый изысканный камень во всем Нордсколе. На солнце он сияет подобно багровой хрустальной розе.|n|nНо прежде, чем я передам тебе рецепт, тебе придется сделать пять эпических трансмутаций драгоценных камней. Можешь создавать любые камни, даже одинаковые.|n|nВозвращайся, когда будешь $Gготов:готова;.', },
    {'Линзи Черноболт просит вас успешно трансмутировать пять эпических драгоценных камней с помощью алхимии. Можно трансмутировать аметрин, око Зула, страхолит, царский янтарь и величественный циркон.', },
  },
  [14152] = {
    'Спасательная операция на море',
    {'Послушай, чемпион: капитан Эллеан Гребень Волны повела свой корабль на север, чтобы изгнать квалдиров из Лагеря Хротгара, но по пути наткнулась на банду пиратов, направлявшихся к Ристалищу. К несчастью, квалдиры значительно превосходят по численности команду Эллеан, и нашим морякам все труднее сопротивляться натиску бандитов.|n|nОтправляйся на север, к кораблю в Проливе Хротгара, который находится между Ристалищем и Лагерем Хротгара, и помоги капитану отразить атаку пиратов. Схватка происходит на востоке пролива.', },
    {'Отправляйтесь в Северное море и убейте 8 врайкулов-берсерков и 3 врайкулов-гарпунеров, напавших на "Гребень Волны".', },
  },
  [14153] = {
    'Банкет',
    {'Ого! Ничего себе! Да тут собрался весь цвет кезанского общества! Кому какое дело до несчастного дракона?|n|nМы решили устроить банкет у бассейна. Гости, похоже, довольны. И все ждут тебя!|n|nТак что давай наряжайся, иди к бассейну и общайся с гостями. Я тоже скоро приду... Только схожу возьму вещи.', },
    {'Наденьте свой потрясный прикид для вечеринки (темные очки, новый стильный костюмчик и блестящие украшения) и отправляйтесь развлекать 10 кутил из Кезана, собравшихся у бассейна в штаб-квартире ТКК.', },
  },
  [14154] = {
    'На расстоянии укуса',
    {'Один из этих вшивых щенков хорошенько зацепил Демпси, и его все еще нельзя переносить, пока кровотечение не остановится.|n|nНам надо удержать позицию всего на несколько минут. Помоги нам дать отпор этим чудовищам, $Gбрат:сестра;!', },
    {'В течение 2 минут сдерживайте натиск воргенов на крыше тюрьмы Гилнеаса.', },
  },
  [14155] = {
    'Арборицид',
    {'Ну, как тебе этот крошшер? Думаю, я могу подключить аварийные источники питания – в случае чего можно будет перейти на них.|n|nСлушай, эти ночные эльфы черпают силу у древа войны, которое растет к западу от ворот. Это большое, гигантское дерево. Ты знаешь, что делать! Уничтожь его!|n|nЭто твоя миссия!', },
    {'Воспользуйтесь крошшером, чтобы уничтожить древня с заставы Талрендис. Если потеряете крошшер, можете воспользоваться запасным, его можно взять у задних врат Оргриммара.', },
  },
  [14156] = {
    'Засланный шпион',
    {'Если король хочет спасти лорда Краули и его шайку предателей, то мы, конечно, подчинимся.|n|nВ любом случае... одному из моих людей было приказано внедриться в банду Краули, и я был бы счастлив узнать, что он уцелел.|n|nСвяжись с Шоном Демпси, только тайно... люди Краули не должны узнать, на кого он работает на самом деле. Эти парни могут быть опаснее воргенов.', },
    {'Найдите Шона Демпси на крыше тюрьмы Гилнеаса.', },
  },
  [14157] = {
    'Старые распри',
    {'Как только ни называли лорда Дария Краули – мятежником, предателем, террористом...|n|nДо начала гражданской войны я считал его своим другом.|n|nЯ не виню его за то, что он возглавил восстание против меня. Мы выстроили тридцатиметровую стену между его землями и Гилнеасом... но у нас не было иного пути.|n|nКак бы то ни было, сейчас нам нужен такой человек, как Краули.|n|nПроникни в Каменную тюрьму и узнай у капитана Бродерика, где содержится Краули. Я бы послал одного из своих людей, но, боюсь, наши старые распри могут помешать переговорам.', },
    {'Поговорите с капитаном Бродериком в Каменной тюрьме, что в Гилнеасе.', },
  },
  [14159] = {
    'Арсенал мятежного лорда',
    {'Арсенал, о котором упомянул Краули – это подвал в здании, которое находится на западе от этого места.|n|nДа, меня тоже беспокоит, что находящееся там оружие было пронесено в город врагами, но сегодня оно может спасти жителей Гилнеаса.|n|nРазыщи Джосайю Авери и конфискуй арсенал мятежников. Пусть это оружие послужит благому делу.', },
    {'Поговорите с Джосайей Авери в Военном квартале Гилнеаса.', },
  },
  [14160] = {
    'Список заслуг',
    {'В этом свитке перечислены многие великие достижения, полученные |3-4($N) в области ювелирного искусства.|n|nОтнесите его Тимоти Джонсу и получите причитающуюся награду.', },
    {'Доставьте Список заслуг Тимоти Джонсу в Даларан.', },
  },
  [14161] = {
    'Удар по василискам',
    {'Мы передвинули целую гору из-за карьера по добыче минералов внизу. Но мы не подумали о подземных василисках, которые теперь стали, гм, наземными. Ты выглядишь $Gинициативным:инициативной; – отправляйся туда и устрани эту помеху, а я тебя чем-нибудь отблагодарю.', },
    {'Убейте 10 серокаменных василисков в карьере у подножья горы.', },
  },
  [14162] = {
    'Отчитаться Хорзаку',
    {'Ты первоклассно $Gвыполнил:выполнила; работу по лесозаготовкам. Но теперь говорят, что не хватает камней. Ты $Gдумал:думала;, что если мы можем двигать горы, то собрать кучу камней – для нас раз плюнуть?..|n|nНу, это не моя проблема. Может быть, ты этим займешься? Поговори с Хорзаком Кругоглодом перед оргриммарской пересадочной станцией ракетной дороги. Может, ты сможешь ему помочь. Иди по дороге на северо-восток и найдешь его на ракетной башне.', },
    {'Найдите Хорзака Кругоглода на оргриммарской пересадочной станции ракетной дороги в Азшаре.', },
  },
  [14163] = {
    'К оружию! Остров Завоеваний',
    {'Чем ближе мы к схватке с Королем-личом, тем очевиднее тот факт, что Орда стоит на пути к нашей победе в Ледяной Короне.|n|nЧтобы отрезать нам путь к Острову Завоеваний, они выслали элитную армию стражей, известную как Кор\'крон. Стоит ли говорить о том, насколько стратегически важен этот клочок земли? Я поручаю тебе, $N, одержать победу в сражении за остров!', },
    {'Победите на поле боя Острова Завоеваний и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.', },
  },
  [14164] = {
    'К оружию! Остров Завоеваний',
    {'Вскоре мы добьемся победы в Нордсколе... но для начала нам надо закрепиться в Ледяной Короне, наладить поставки продовольствия и подкреплений.|n|nОстров Завоеваний представляется мне идеальным плацдармом – это богатое ресурсами место легко защитить от нападений. Однако похоже, что Альянс пришел к такому же выводу и послал Седьмой Легион навстречу нашим войскам.|n|n$N, отправляйся туда и сделай все для нашей победы!', },
    {'Принесите почетные знаки каждого поля боя ордынскому вестнику войны в любую столицу Орды, на Озеро Ледяных Оков, в Даларан или Шаттрат.', },
  },
  [14165] = {
    'Хладный камень',
    {'Рабочих хлебом не корми – дай пожаловаться. То изнурительная многочасовая работа, то низкая зарплата, то василиски превращают их в камень. Вечно им что-нибудь не так!|n|nНо я тут подумал, что, может быть эти превращения – выгодное дело. А вдруг они превращаются в камень высокого качества? И тогда мои нытики принесут мне гораздо больше дохода в качестве роскошных строительных материалов, нежели в качестве рабочей силы! Найди какого-нибудь окаменевшего горняка и принеси его сюда.', },
    {'Найдите в карьере у подножья горы окаменевшего горняка и принесите его Хорзаку Кругоглоду на оргриммарскую пересадочную станцию ракетной дороги.', },
  },
  [14166] = {
    'Благодарный покойник',
    {'Как приятно было навестить друзей и родных! Только, кажется, я немного перестарался... и съел все, что они приготовили для меня! Даже крошки подмел!|n|nМогу ли я попросить тебя принести мне еще вкусного поминального хлеба? Я бы был очень благодарен!|n|nКажется, рецепт можно купить у Чепмана.', },
    {'Принесите поминальный хлеб веселому даларанскому духу на кладбище Даларана.|n|nЧтобы увидеть дух, используйте оранжевые бархатцы.', },
  },
  [14167] = {
    'Благодарный покойник',
    {'Как приятно было навестить друзей и родных! Только, кажется, я немного перестарался... и съел все, что они приготовили для меня! Даже крошки подмел!|n|nМогу ли я попросить тебя принести мне еще вкусного поминального хлеба? Я бы был очень благодарен!|n|nКажется, рецепт можно купить у Чепмана.', },
    {'Принесите поминальный хлеб веселому духу дворфа на кладбище Стальгорна.|n|nЧтобы увидеть дух, используйте оранжевые бархатцы.', },
