  [28768] = {
    'Зимние Ключи!',
    {'Донова Снегонора – женщина-дворф – друг Древобрюхам.|n|nМы торгуем огненной водой.|n|nТы найдешь ее у источников Ледяного огня – это надо идти на восток через наши пещеры.|n|nОна хочет одолеть фурболгов из племени Зимней Спячки и нуждается в помощи. Может быть, ты сумеешь ей помочь.', },
    {'Явитесь к Донове Снегоноре у Источников Ледяного огня в Зимних Ключах.', },
  },
  [28769] = {
    'Волки и овцы',
    {'Орки-захватчики – не дураки. Они следят за наши действиями, чтобы улучить удобный момент для нападения.|n|nВ лесу на северо-западе расположились шпионы из клана Черной горы. Они смотрят на нас через подзорные трубы, выжидая урочный час. Я хочу, чтобы ты $Gнапал:напала; на них!|n|nРасправься со шпионами клана Черной горы! Нужно продемонстрировать им, что мы знаем о том, что они следят за нами, а также показать нашу боеготовность!', },
    {'Расправьтесь с 8 шпионами клана Черной горы.', },
