  [28775] = {
    'Разбитая статуэтка змеи',
    {'Прошлый владелец просто выбросил эту разбитую статуэтку. Однако умелый ювелир мог бы ее полностью восстановить при помощи определенных материалов.', },
    {'Почините разбитую статуэтку, применив необходимые умения и материалы.', },
  },
  [28776] = {
    'Разбитая статуэтка земельника',
    {'Прошлый владелец просто выбросил эту разбитую статуэтку. Однако умелый ювелир мог бы ее полностью восстановить при помощи определенных материалов.', },
    {'Почините разбитую статуэтку, применив необходимые умения и материалы.', },
  },
  [28777] = {
    'Разбитая статуэтка совы',
    {'Прошлый владелец просто выбросил эту разбитую статуэтку. Однако умелый ювелир мог бы ее полностью восстановить при помощи определенных материалов.', },
    {'Почините разбитую статуэтку, применив необходимые умения и материалы.', },
  },
  [28778] = {
    'Разбитая статуэтка медведя',
    {'Прошлый владелец просто выбросил эту разбитую статуэтку. Однако умелый ювелир мог бы ее полностью восстановить при помощи определенных материалов.', },
    {'Почините разбитую статуэтку, применив необходимые умения и материалы.', },
  },
  [28779] = {
    'До дома далече',
    {'Думаю, мне удалось сбежать потому, что отсюда, по сути, больше некуда деваться...|n|nЯ застрял на этих платформах, и рано или поздно они меня все равно найдут. Если только...|n|nСлыхал я, что сердце высокородного элементаля дарует его обладателю свойства соответствующей стихии. Стало быть, сердце воздушного элементаля пришлось бы очень кстати, надумай я спуститься на землю.|n|nПринеси мне сердце великого визиря Эртан – с помощью его магии я смогу благополучно приземлиться на побережье Ульдума.', },
    {'Раздобудьте сердце великого визиря Эртан.', },
  },
  [28780] = {
    'В бой!',
    {'Пока ты $Gтренировался:тренировалась;, мне пришло срочное донесение от сержанта Виллема. Оказывается, орки Черной горы привлекли гоблинов, промышляющих наемными убийствами. Виллем попросил меня прислать ему на подмогу $Gнастоящего героя:настоящую героиню;. Ты $Gдолжен:должна; придти им на помощь, $N!|n|nОбратись к сержанту Виллему, который находится к северу от аббатства в командирском шатре. За дело!', },
    {'Явитесь к сержанту Виллему, находящемуся за Аббатством Североземья.', },
  },
  [28781] = {
    'Неплановые цели',
    {'Мы были участниками секретной операции, организованной принцем Надуном из Рамкахена. Однако большую часть нашего отряда перебили в результате засады, вследствие чего мы не можем выполнить задание.|n|nЕсли ты согласишься помочь нам, я бы смог выторговать для тебя солидное вознаграждение.|n|nНам было поручено уничтожить любые неплановые цели, потеря которых нанесла бы ощутимый урон военной инфраструктуре противника.|n|nВпереди мы обнаружили генерала Хусама в сопровождении двух капитанов. Ликвидация этих целей станет неоспоримым благом для Рамкахена.', },
    {'Ликвидируйте генерала Хусама и 2 присягнувших капитанов.', },
  },
  [28782] = {
    'Легендарная птица',
    {'У местных есть легенда о могучей сове, которая кружит над вершинами гор, словно сама крылатая смерть. Местные назвали ее "Смертокрыл".|n|nНо скоро им сообщили, что это имя уже занято, и поэтому они выбрали другое прозвище, которое также наполняет душу страхом и ужасом.|n|nСмертоух!|n|nСмертоух живет на вершине горы, к юго-западу от нашей коптильни. Заставь это инфернальное уханье умолкнуть... чтобы мы могли съесть эту сову!', },
    {'Убейте Смертоуха.', },
  },
  [28783] = {
    'Источник их силы',
    {'Перед тем, как наш отряд попал в засаду, нам удалось провести полномасштабную разведку в стане врага.|n|nМы установили, что посланник Смертокрыла Сиамат является источником новоприобретенной силы Неферсета.|n|nВраги заявляют, что они всего лишь восстановили величие прошлых дней, но произошло нечто другое: в их души закралась тьма.|n|nБудучи повелителем одного из четырех ветров, Сиамат обладает гигантской силой. Однако он растерял часть своего могущества вследствие передачи своей мощи Неферсету.|n|nНужно сразить его сейчас, пока Сиамат ослаблен, и положить конец этому безумию.', },
    {'Сразите Сиамата.', },
  },
  [28784] = {
    'В бой!',
    {'Пока ты $Gтренировался:тренировалась;, мне пришло срочное донесение от сержанта Виллема. Оказывается, орки Черной горы привлекли гоблинов, промышляющих наемными убийствами. Виллем попросил меня прислать ему на подмогу $Gнастоящего героя:настоящую героиню;. Ты $Gдолжен:должна; придти им на помощь, $N!|n|nОбратись к сержанту Виллему, который находится к северу от аббатства в командирском шатре. За дело!', },
    {'Явитесь к сержанту Виллему, находящемуся за Аббатством Североземья.', },
