  [28934] = {
    'Конец Королевской компании',
    {'В этом гроссбухе указано множество мест, и ты, $Gпарень, должен:подруга, должна; проверить для меня кое-что. Нельзя допустить, чтобы это продолжалось и дальше.|n|nВот запись, которая меня особенно волнует: в ней говорится о месте в Ульдуме, которое находится к востоку от гробницы Хартута, рядом со входом со стороны Танариса. Не нравится мне это. Иди туда и разберись.|n|nДа, если увидишь что-то большое и опасное – брось в него эту бомбу.', },
    {'Убейте 5 техников химической компании и воспользуйтесь кориевой бомбой Гвоздезуба, чтобы уничтожить повозку с химикатами на заброшенной ферме к востоку от гробницы Хартута, рядом со входом со стороны Танариса. После этого вернитесь к инспектору Кромсу Гвоздезубу в Штормград.', },
  },
  [28935] = {
    'Конец Королевской компании',
    {'В этом гроссбухе указано множество мест, и ты, $Gпарень, должен:подруга, должна; проверить для меня кое-что. Нельзя допустить, чтобы это продолжалось и дальше.|n|nВот запись, которая меня особенно волнует: в ней говорится о месте в Ульдуме, которое находится к востоку от гробницы Хартута, рядом со входом со стороны Танариса. Не нравится мне это. Иди туда и разберись.|n|nДа, если увидишь что-то большое и опасное – брось в него эту бомбу.', },
    {'Убейте 5 техников химической компании и воспользуйтесь кориевой бомбой Гвоздезуба, чтобы уничтожить повозку с химикатами на заброшенной ферме к востоку от гробницы Хартута, рядом со входом со стороны Танариса. После этого вернитесь к детективу Крямсу Гвоздезубу в Оргриммар.', },
  },
  [28936] = {
    'Дилемма дивы',
    nil,
    {'Убейте 6 наг.', },
  },
  [28937] = {
    'Хлебные крошки Альянса',
    {'Чудовища! Просто чудовища!|n|nНаш корабль зашел в порт к югу от Cтромгарда, но на берегу нас ждала стая странных созданий.|n|nПеред тем как смыться оттуда, я успел обратить внимание на их противные морды и странные булькающие звуки, которые они издавали. Лучше поспеши на помощь моим товарищам, $N!', },
    {'Поговорите с Леди Гаргой в бухте Фальдира.', },
  },
  [28938] = {
    'Спасение маленьких мурлоков',
    nil,
    {'Спасите 6 маленьких мурлоков.', },
  },
  [28939] = {
    'Остерегайтесь чужаков',
    nil,
    {'Убейте Темночешуя.', },
  },
  [28940] = {
    'Достать противоядие',
    nil,
    {'Соберите 6 растений.', },
  },
  [28941] = {
